-- 경기도의회 행정사무감사 회의록(경기연구원 관련) 이관 데이터 (자동 생성: tools/import_audit.py)
-- 게시판 코드 audit. 여러 번 실행해도 중복되지 않습니다.
insert into public.boards (code,name,members_only,admin_only_write) values ('audit','행정사무감사',false,true) on conflict (code) do nothing;
create unique index if not exists posts_legacy_idx on public.posts ((attachments->>'legacy_id')) where attachments ? 'legacy_id';
insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'audit','[2017.11.20. 월요일] 경기연구원 — 기획재정위원회 2017년도 행정사무감사','<div class="box" style="margin-bottom:16px"><b>제9대 경기도의회 기획재정위원회</b> · 2017년도 행정사무감사(2017. 11. 13. ~ 2017. 11. 24.)<br>원문: <a href="https://kms.ggc.go.kr/cms/mntsViewer.do?mntsId=10423" target="_blank" rel="noopener" style="color:var(--primary);text-decoration:underline">경기도의회 회의록 뷰어에서 보기</a></div><p>2017년도 행정사무감사
</p>
<h4>기획재정위원회 회의록
</h4>
<p class=''ar''>경기도의회사무처
</p>
<p><hr /></p>
<p>피감사기관 : 경기연구원
</p>
<p><hr /></p>
<p>일  시 : 2017년 11월 20일(월)
</p>
<p>장  소 : 기획재정위원회 회의실
</p>
<p><hr /></p>
<p class=''ar''>(10시33분 감사개시)
</p>
<p><b>○ 위원장 이재준 </b> 좌석을 정돈해 주시기 바랍니다. 성원이 되었으므로 지금부터 지방자치법 제41조, 동법 시행령 제39조 및 경기도의회 행정사무감사 및 조사에 관한 조례 제2조의 규정에 의하여 경기연구원에 대한 2017년도 행정사무감사를 시작하겠습니다.
</p>
<p style="padding-left:1.2em">  위원 여러분 그리고 경기연구원 원장 직무대행을 비롯한 임직원 여러분! 안녕하십니까? 경기도의회 기획재정위원회 감사위원장 이재준 위원입니다. 오늘은 우리 위원회 감사일정에 따라 경기연구원에 대한 행정사무감사를 실시하게 되었습니다.
</p>
<p style="padding-left:1.2em">  여러분께서도 잘 아시는 바와 같이 우리 의회의 행정사무감사는 경기도의 행정사무 전반에 관한 실태를 정확히 파악하여 의정활동에 반영하고 도민의 삶의 질 향상에 기여하고자 함이 그 목적이므로 매우 중요한 의미가 있다고 하겠습니다. 오늘은 경기도의 싱크탱크인 경기연구원의 운영실태를 감사하는 것인 만큼 연구원에 대한 심도 있는 감사활동으로 경기도 발전을 위한 정책대안이 제시될 수 있도록 위원 여러분들의 적극적인 감사활동을 부탁드립니다. 아울러 감사에 임하는 임직원 여러분께서도 이와 같은 목적이 달성될 수 있도록 적극 협조해 주시기 바랍니다.
</p>
<p style="padding-left:1.2em">  그러면 감사를 시작하기 전에 증인선서를 받도록 하겠습니다. 감사를 받는 임직원은 증인의 자격으로 소관 업무를 보고하고 질의에 답변하기에 앞서 먼저 선서를 하셔야 합니다.
</p>
<p style="padding-left:1.2em">  증인선서의 취지와 관계 규정을 말씀드리면 선서를 하는 이유는 이번에 경기도의회가 2017년도 행정사무감사를 실시함에 있어서 증인으로부터 양심에 따라 숨김없이 사실대로 증언하겠다는 서약을 받기 위한 것입니다. 만약 증인이 허위증언을 한 때에는 지방자치법 제41조제5항 및 경기도의회 행정사무감사 및 조사에 관한 조례 제30조의 규정에 의하여 고발될 수 있습니다. 또한 증언 또는 진술을 거부한 때에는 동법 규정에 의하여 500만 원 이하의 과태료가 부과될 수 있음을 알려드립니다.
</p>
<p style="padding-left:1.2em">  그러면 먼저 증인 출석여부를 확인하겠습니다. 증인들께서는 모두 자리에서 일어서 주시기 바랍니다.
</p>
<p style="padding-left:2.4em">    (일동기립)
</p>
<p style="padding-left:1.2em">  경기연구원 원장 직무대행 나왔습니까?
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네.
</p>
<p><b>○ 위원장 이재준 </b> 연구기획본부장 나왔습니까?
</p>
<p><b>○ 연구기획본부장 이정훈 </b> 네.
</p>
<p><b>○ 위원장 이재준 </b> 경영본부장 나왔습니까?
</p>
<p><b>○ 경영본부장 이용환 </b> 네.
</p>
<p><b>○ 위원장 이재준 </b> 북부연구센터장 나왔습니까?
</p>
<p><b>○ 북부연구센터장 이외희 </b> 네.
</p>
<p><b>○ 위원장 이재준 </b> 대외협력처장 나왔습니까?
</p>
<p><b>○ 대외협력처장 박정란 </b> 네.
</p>
<p><b>○ 위원장 이재준 </b> 공존사회연구실장 나왔습니까?
</p>
<p><b>○ 공존사회연구실장 박충훈 </b> 네.
</p>
<p><b>○ 위원장 이재준 </b> 공감도시연구실장 나왔습니까?
</p>
<p><b>○ 공감도시연구실장 봉인식 </b> 네.
</p>
<p><b>○ 위원장 이재준 </b> 상생경제연구실장 나왔습니까? 
</p>
<p><b>○ 상생경제연구실장 이수행 </b> 네.
</p>
<p><b>○ 위원장 이재준 </b> 휴먼교통연구실장 나왔습니까? 
</p>
<p><b>○ 휴먼교통연구실장 송제룡 </b> 네.
</p>
<p><b>○ 위원장 이재준 </b> 생태환경연구실장 나왔습니까? 
</p>
<p><b>○ 생태환경연구실장 이기영 </b> 네.
</p>
<p><b>○ 위원장 이재준 </b> 연구기획부장 나왔습니까?
</p>
<p><b>○ 연구기획부장 최용환 </b> 네.
</p>
<p><b>○ 위원장 이재준 </b> 정책분석부장 나왔습니까?
</p>
<p><b>○ 정책분석부장 김을식 </b> 네.
</p>
<p><b>○ 위원장 이재준 </b> 홍보ㆍ정보부장 나왔습니까? 
</p>
<p><b>○ 홍보ㆍ정보부장 이인애 </b> 네.
</p>
<p><b>○ 위원장 이재준 </b> 행정지원부장 나왔습니까?
</p>
<p><b>○ 행정지원부장 이용원 </b> 네.
</p>
<p><b>○ 위원장 이재준 </b> 재정지원부장 나왔습니까?
</p>
<p><b>○ 재정지원부장 박인숙 </b> 네.
</p>
<p><b>○ 위원장 이재준 </b> 연구지원부장 나왔습니까?
</p>
<p><b>○ 연구지원부장 배미성 </b> 네.
</p>
<p><b>○ 위원장 이재준 </b> 대외ㆍ의정부장 나왔습니까?
</p>
<p><b>○ 대외ㆍ의정부장 이덕환 </b> 네.
</p>
<p><b>○ 위원장 이재준 </b> 다음은 선서의 요령을 설명드리겠습니다. 선서는 전체 증인을 대표하여 원장 직무대행이 발언대에 나오셔서 오른손을 들고 선서문을 낭독하시고 다른 증인들께서는 자리에 서서 오른손만 들어주시면 됩니다.
</p>
<p style="padding-left:1.2em">  그러면 선서를 해 주시기 바랍니다.
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 선서! 본인은 경기도의회가 지방자치법 제41조, 같은 법 시행령 제39조제1항, 경기도의회 행정사무감사 및 조사에 관한 조례 제2조에 따라 소관 업무에 대한 2017년도 행정사무감사를 실시함에 있어 기관장으로서 성실하게 감사를 받을 것이며 또한 증인으로서 증언을 함에 있어서는 지방자치법 시행령 제43조제5항과 경기도의회 행정사무감사 및 조사에 관한 조례 제19조에 의거하여 양심에 따라 숨김과 보탬이 없이 사실 그대로 말하고 만일 거짓이 있으면 위증의 벌을 받기로 서약하고 이에 선서합니다. 2017년 11월 20일 경기연구원 원장 직무대행 김군수.
</p>
<p><b>○ 위원장 이재준 </b> 모두 자리에 앉아 주시기 바랍니다.
</p>
<p style="padding-left:2.4em">    (일동착석)
</p>
<p style="padding-left:1.2em">  그러면 간부소개와 업무보고를 간략히 해 주시기 바랍니다. 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 안녕하십니까? 경기연구원 부원장 김군수입니다. 우선 원장이 공석인 관계로 정관상 직무대행자인 부원장으로서 오늘 경기도의회 기획재정위원회 연구원의 주요업무보고를 드리는 것에 양해의 말씀을 드립니다. 또한 연구원의 발전을 위하여 노력하시는 존경하는 기획재정위원회 위원님들의 많은 관심에 감사드리며 앞으로도 많은 성원을 부탁드리겠습니다. 
</p>
<p style="padding-left:1.2em">  그러면 보고에 앞서 연구원의 주요간부를 소개해 드리겠습니다. 
</p>
<p style="padding-left:1.2em">  먼저 이정훈 연구기획본부장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  이용환 경영본부장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  박정란 대외협력처장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  이외희 북부연구센터장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  박충훈 공존사회연구실장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  봉인식 공감도시연구실장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  이수행 상생경제연구실장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  송제룡 휴먼교통연구실장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  이기영 생태환경연구실장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  최용환 연구기획부장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  김을식 정책분석부장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  이인애 홍보ㆍ정보부장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  이용원 행정지원부장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  박인숙 재정지원부장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  배미성 연구지원부장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  이덕환 대외ㆍ의정부장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  이상으로 간부소개를 마치고 지금부터 연구원의 주요업무를 보고드리겠습니다. 배부해 드린 보고자료의 목차를 봐 주시기 바랍니다. 보고순서는 기본현황, 2017년 주요성과, 2018년 주요업무계획 순으로 보고드리겠습니다. 
</p>
<p style="padding-left:1.2em">  먼저 1쪽 기본현황이 되겠습니다. 저희 연구원은 1995년도에 개원하여 경기도의 중장기 비전 제시와 정책개발 기능을 수행하고 있습니다. 연구원 조직은 2본부 1처 1센터 5실 7부로 구성되어 있습니다. 우리 연구원의 인력은 부원장 1명, 연구직 55명, 관리ㆍ정보ㆍ기능직 21명으로 77명의 정규직원과 계약직원 111명 등 총 188명이 근무하고 있습니다. 
</p>
<p style="padding-left:1.2em">  다음은 2쪽이 되겠습니다. 연구기획본부, 연구실, 경영본부, 대외협력처, 북부연구센터와 그 하부조직의 주요업무입니다. 구체적인 업무내용은 자료를 참조하여 주시기 바랍니다. 
</p>
<p style="padding-left:1.2em">  다음은 3쪽 예산현황에 대해서 보고드리겠습니다. 올해의 총예산 규모는 225억 원으로 일반회계 195억 원, 수탁용역사업특별회계 30억 원입니다. 일반회계의 수입ㆍ지출 내역을 말씀드리겠습니다. 수입 항목은 경기도 출연금이 전체의 72.5%인 141억 원으로 가장 많습니다. 지출 항목으로는 인건비가 45.6%인 89억 원으로 가장 많으며 다음이 연구사업비가 82억 원으로 전체 41.9% 정도를 차지하고 있습니다. 
</p>
<p style="padding-left:1.2em">  다음은 2017년 주요성과에 대해서 보고드리겠습니다. 보고자료 4쪽부터 7쪽이 되겠습니다. 먼저 4쪽의 연구분야 성과입니다. 9월 30일 기준으로 총 245건의 연구과제와 정책현안분석을 수행하였으며 이는 2017년 당초계획 대비 75.9%에 해당됩니다. 특히 정책현안분석을 통해 지방분권, 4차 산업혁명, 도시재생 등 도정 주요이슈에 역점을 두고 대응하고 있습니다. 
</p>
<p style="padding-left:1.2em">  다음은 5쪽입니다. 2017년에 완료했거나 수행 중인 주요전략 연구과제입니다. 구체적인 내용은 자료로 참조하여 주시기 바랍니다. 
</p>
<p style="padding-left:1.2em">  다음은 6쪽 경기도 의뢰 단기정책과제 현황입니다. 경기도와 경기도의회에서 의뢰한 단기정책과제 총 83건 중 66건이 채택되었습니다. 그중 경기도의회에서 의뢰한 건수는 13건이며 전 건 채택되어 완료되었거나 수행 중에 있으며, 특히 경기도의회에서 의뢰한 시군 전략 연구는 현재 7건을 수행 중이며 추가로 하남, 평택 2개 시의 전략 연구가 계획되어 있습니다. 총 9건의 시군 전략 과제가 추진될 예정에 있습니다. 
</p>
<p style="padding-left:1.2em">  다음은 7쪽 2017년 경영분야 주요성과에 대해서 보고드리겠습니다. 2017년 주요성과는 크게 GRI 역할 재정립, 연구역량 강화, 연구 교류 및 성과공유 확대, 대외소통 강화 이렇게 네 가지로 구분하여 보고드리겠습니다. 
</p>
<p style="padding-left:1.2em">  먼저 GRI 역할 재정립 분야입니다. 환경변화에 대응해서 사업목표와 전략을 변경하였으며 지역균형발전을 위해 2015년에 북부지역, 2016년에 동부지역에 이어 2017년에는 중부내륙지역 발전종합계획 수립연구를 수행하고 있습니다. 
</p>
<p style="padding-left:1.2em">  다음은 연구역량 강화 분야입니다. 정책연구과제의 영문ㆍ중문 초록을 작성하고 연구 성과의 전문학술지에 게재를 의무화하였습니다. 또한 연구의 국제화를 위한 우수보고서 번역 등 학술연구를 독려하였습니다. 연구 교류 및 성과공유 확대 차원에서는 경기도 7개 공공연구기관이 MOU를 체결하여 협력연구를 진행하고 있습니다. 
</p>
<p style="padding-left:1.2em">  마지막으로 대외소통 강화 분야입니다. 경기도 내 중ㆍ고등학생들을 대상으로 G.G Talk Talk이라는 교육재능기부 프로그램을 운영하고 있습니다. 2017년에는 20개 시군 45개 학교를 대상으로 79건의 교육을 실시하였습니다. 또한 정책연구원에 대한 이해를 돕고 학생들에게 진로 및 직업탐색의 기회도 제공하고 있습니다. 아울러 정책세미나ㆍ포럼, 의정연구교류, 국제컨퍼런스 개최 등 연구원 행사 참여를 확대하였습니다. 
</p>
<p style="padding-left:1.2em">  다음은 8쪽의 2018년 주요업무계획입니다. 먼저 우리 연구원은 경기도민과 함께 미래를 여는 종합연구기관 GRI라는 목표아래 네 가지 추진해야 할 전략으로 첫째 가치를 추구하는 연구 지향, 둘째 더불어 탐구하는 네트워크 형성, 셋째 현장과 소통하는 통로 다변화, 넷째 서로 화합하는 조직문화 조성을 설정하였으며 이러한 전략을 실천하기 위해서 GRI 중기연구 어젠다 발굴 등 전략별 핵심사업을 선정하여 추진할 계획입니다.
</p>
<p style="padding-left:1.2em">  다음은 9쪽 2018년도 주요업무계획 중에서 연구분야 부문입니다. 연구과제사업, 연구유관사업 순으로 보고드리겠습니다. 먼저 연구과제사업입니다. 2018년에는 14개 GRI 중기연구 어젠다를 중심으로 자체적으로 계획한 정책 및 전략과제에 집중할 예정입니다. 또한 2018년 주요업무계획상 기본과제, 정책과제, 정책현안분석 등 총 287건의 연구과제를 추진할 예정입니다. 특히 중점적으로 추진할 전략과제 10건은 10쪽의 표를 참조해 주시기 바랍니다.
</p>
<p style="padding-left:1.2em">  다음은 각 부서별 주요업무과제 수행에 대해서 보고드리겠습니다. 보고자료 11쪽부터 16쪽이 되겠습니다. 먼저 공존사회연구실입니다. 주요 역점 연구분야는 지방 행ㆍ재정 기능 강화 및 재정립, 지방분권, 한반도 및 동북아 정세 분석 등이고 구체적인 연구과제 목록은 자료를 참조하여 주시기 바랍니다. 
</p>
<p style="padding-left:1.2em">  다음은 12쪽 공감도시연구실입니다. 주요 역점 연구분야는 국토 및 지역개발정책 제도, 삶의 질 연구, 수도권 정책과 GB정책, 주택정책, 도시ㆍ농촌 설계 등입니다. 구체적인 연구과제목록은 자료를 참조하여 주시기 바랍니다.
</p>
<p style="padding-left:1.2em">  다음은 13쪽 상생경제연구실입니다. 주요 역점 연구분야는 지역경제 및 산업정책, 국내외ㆍ지역산업 경제동향 분석, 4차산업 등 신성장산업 육성, 문화ㆍ관광산업 연구 등입니다. 
</p>
<p style="padding-left:1.2em">  다음은 14쪽 휴먼교통연구실입니다. 주요 역점 연구분야는 삶의 질이 보장되는 교통환경 조성, 안전하고 편리한 대중교통 서비스체계 제공, 편리하고 효율적인 광역교통체계 구축, 4차 산업혁명과 연계된 지능형 교통체계 구현 등입니다. 구체적인 연구과제 목록은 자료를 참조하여 주시기 바랍니다. 
</p>
<p style="padding-left:1.2em">  다음은 15쪽 생태환경연구실입니다. 주요 역점 연구분야는 지속가능발전과 녹색경제, 상하수도 정책, 환경안전 및 보건, 폐기물 및 자원순환, 대기 및 유해물질, 기후변화 및 에너지 정책 등입니다. 구체적인 연구과제 목록은 자료를 참조하여 주시기 바랍니다. 
</p>
<p style="padding-left:1.2em">  다음은 16쪽 북부연구센터입니다. 주요 역점 연구분야는 경기북부지역 삶의 질 향상에 관련된 정책개발, 남북교류협력 및 통일 정책, DMZ 및 접경지역 연구 등입니다. 구체적인 연구과제 목록은 자료를 참조하여 주시기 바랍니다. 
</p>
<p style="padding-left:1.2em">  다음 17쪽부터는 연구유관사업입니다. 연구부대사업, 연구지원사업, 연구기반사업 순으로 보고드리겠습니다. 
</p>
<p style="padding-left:1.2em">  우선 연구부대사업입니다. 정책세미나ㆍ포럼, 동향분석과 전망, GRI학술지의 발간, 콘텐츠 홍보, 의정연구교류, 대외협력교류, 국제화사업 등을 계획하고 있습니다. 
</p>
<p style="padding-left:1.2em">  다음은 18쪽 연구지원사업 부문으로 정보자료 지원, 전산사업, GIS사업을 추진할 계획입니다.
</p>
<p style="padding-left:1.2em">  다음은 19쪽 연구기반사업 부문으로 연구사업 인력 운영, 인적자원 개발, 연구기획 및 평가사업을 추진할 계획입니다.
</p>
<p style="padding-left:1.2em">  다음은 20쪽 경영분야에 대하여 네 가지 경영전략에 대한 추진과제를 중심으로 보고드리겠습니다. 먼저 가치를 추구하는 연구를 실현하기 위해 지역균형발전을 위한 미래연구를 기획ㆍ추진하고 또한 기본과제 연구성과를 전 학술지에 게재하는 등 연구역량을 강화하며 연구실 간 통섭연구를 통한 융복합연구의 지원을 강화하도록 하겠습니다. 두 번째, 더불어 탐구하는 네트워크 형성을 위해 국제 산ㆍ학ㆍ연ㆍ관 공동연구 추진체계를 구축하고 연구성과 공유와 경기도 공공기관 협력연구를 더욱더 추진하며 지자체 연구기관과 교류를 활성화하고 경기도 자체수행 정책과제 자문을 통해 대외소통을 강화하도록 하겠습니다. 세 번째는 현장과 소통하는 통로 다변화를 위해 지역으로 연구를 좀 더 확대하고 의정교류를 활성화하겠습니다. 교육재능기부 프로그램을 지속적으로 추진하고 연구결과물의 공개 확대 등 사회공헌과 지식전파에 주력하겠습니다. 또한 중기 핵심연구 어젠다를 발굴하여 전략연구를 추진하도록 하겠습니다. 마지막으로 서로 화합하는 조직문화를 조성하기 위해 연구와 근로환경을 개선하고 직원들의 자기개발과 연구참여를 확대하도록 노력하겠습니다. 
</p>
<p style="padding-left:1.2em">  다음은 22쪽의 2017년도 신규착수 연구목록과 28쪽의 3년간 도의회 요청과제 현황 또한 29쪽의 2016년 행정사무감사 처리요구사항 조치결과는 허락해 주신다면 자료로 대신하겠습니다. 
</p>
<p style="padding-left:1.2em">  이상으로 연구원의 주요업무보고를 모두 마치겠습니다. 감사합니다.
</p>
<p><hr /></p>
<p>업무보고서(경기연구원)
</p>
<p><hr /></p>
<p><b>○ 위원장 이재준 </b> 수고하셨습니다. 
</p>
<p style="padding-left:1.2em">  다음은 감사를 위한 질의 답변 순서가 되겠습니다. 감사의 효율적인 진행을 위해 질의는 일문일답으로 하되 질의시간을 제한하도록 하겠습니다. 우선 위원님 한 분당 10분씩 시간을 드리고 추가질의는 일단 5분을 드리도록 하겠습니다. 원활한 감사 진행을 위해 부득이 시간제한을 두게 된 점 널리 양해해 주시면 고맙겠습니다. 만약 시간적 제약으로 인해 준비하신 질의를 미처 다 하지 못하신 위원님들께서는 추후 서면으로 질의가 가능하오니 이를 활용해 주시기 바랍니다. 또 위원님들의 질의에 대해서 답변이 어려울 경우 업무담당 실장 및 부장 등 실무자와 답변해도 좋습니다. 다만 사전에 위원장에게 동의를 얻은 후 발언대로 나와서 소속과 직ㆍ성명을 분명히 밝히고 답변해 주시기 바랍니다. 
</p>
<p style="padding-left:1.2em">  그럼 질의에 들어가기에 앞서 자료요구하실 위원님 계시면 자료요청을 해 주시기 바랍니다. 양근서 위원님.
</p>
<p><b>○ 양근서 위원 </b> 자료요구 2건 먼저 하겠습니다. 지난 행정사무감사에서 경기연구원의 수탁용역사업 수입에 대해서 수탁연구용역사업에 참여했던 비정규직, 특히 석사 출신에 대해서 수익금을 배분하지 않고 정규직들이 다 독식하고 있다는 지적을 했었고 거기에 대해서 아마 조치가 이루어졌을 텐데요. 어떤 방식으로 개선이 됐는지 보고를 자료로 해 주시고요.
</p>
<p style="padding-left:1.2em">  두 번째로 경기연구원에 정규직 전환 로드맵이 아마 나와 있겠지요? 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네, 있습니다.
</p>
<p><b>○ 양근서 위원 </b> 정부의 지침도 떨어졌고. 세부적인 계획을 오전 중에 취합해서 제출해 주시기 바랍니다.
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네, 알겠습니다. 
</p>
<p><b>○ 위원장 이재준 </b> 추가로 요청하실 위원님 안 계십니까? 
</p>
<p style="padding-left:2.4em">    (「네.」하는 위원 있음) 
</p>
<p style="padding-left:1.2em">  그럼 질의하실 위원님께서는 거수로 신청하여 주시기 바랍니다. 양근서 위원님 질의해 주시기 바랍니다.
</p>
<p><b>○ 양근서 위원 </b> 지금 현재 경기연구원 원장이 공석인 상태에서 부원장님께서 직무대행체제로 임하고 있는데요. 가능하면 직무대행체제보다는 온전한 신임 원장을 빨리 선임해서 경기연구원이 맡고 있는 일들에 대해서 좀 더 공적 책임감을 높이면서 밀도 있게 사업들이 추진될 수 있는 체제로 빨리 전환됐으면 하는 바람을 갖고 있습니다. 여기에 대해서는 아마 우리 부원장님도 동의하시죠? 서운하지는 않으시죠? 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 아닙니다. 저는 전적으로 동의합니다. 
</p>
<p><b>○ 양근서 위원 </b> 혹시 부원장님을 비롯해서 내부적으로 자체승진을 통해서 지금 공석인 원장을 해야 되겠다, 이런 여론이 혹시 내부적으로 있습니까? 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 그런 거는 없습니다. 
</p>
<p><b>○ 양근서 위원 </b> 없습니까? 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네.
</p>
<p><b>○ 양근서 위원 </b> 그런 욕심 없습니까, 부원장님? 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네, 그런 거 없습니다. 
</p>
<p><b>○ 양근서 위원 </b> 아니, 원장 되기 싫으세요? 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 저는 원래부터 원장이 되고 싶은 생각이 없습니다. 
</p>
<p style="padding-left:2.4em">    (웃  음)
</p>
<p><b>○ 양근서 위원 </b> 어쨌든 경영보다는 연구에 충실하시겠다는 의미는 알겠는데…….
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네, 연구에 충실…….
</p>
<p><b>○ 양근서 위원 </b> 사실은 좀 미묘한 시점이 있습니다. 내년까지 지금 인사 추천권자인 남경필 도지사의 임기가 6월까지로 한정돼 있고 이후에 계속 연임에 성공할지 못 할지 불확실한 상태인데 아시는 것처럼 원장 공모절차를 진행했다가 1순위로 내정됐던 분이 개인사정으로 인해서 고사하는 바람에 현재 지금 재공모도 하지 못하고 후임 원장 채용과 관련해서는 명확한 입장을 정하지 못하고 차일피일 공석인 상태가 지속되고 있어서 의회 차원에서는 상당히 좀 안타깝다는 생각을 합니다. 가능하면 아까 말씀드렸듯이 막중한 임무, 경기도의 싱크탱크로서의 기능을 생각했을 때 내부승진이 됐건 외부공모가 됐건 후임 원장이 빨리 선임이 돼서 책임경영체제를 했으면 하는 바람을 다시 한 번 말씀드립니다. 
</p>
<p style="padding-left:1.2em">  몇 가지 좀 확인하고 넘어가겠습니다. 우선 수탁용역과 위탁용역이 어떻게 다르죠? 같은 개념입니까, 아니면 더 엄밀히 구분되는 기준이 있나요? 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 수탁용역은 저희가 경기도나 시군이나 외부로부터 입찰이나 수의계약에 의해서 받는 계약을 통해서 수행하는 과제이고요. 그다음에 위탁과제는 보통 과제 분류상 저희 예산으로 외부의 전문기관에 저희의 부족한 연구역량을 강화시키기 위해서 의뢰하는 경우를 위탁과제라고 부릅니다. 
</p>
<p><b>○ 양근서 위원 </b> 아, 주체의 문제군요. 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네.
</p>
<p><b>○ 양근서 위원 </b> 그러니까 위탁은 외부기관에 경기연구원에서 위탁을 하는 개념이고 외부로부터 위탁한 과제를 우리가 수임을 하면 수탁과제라고 이렇게 구분하는 거군요?
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네, 그렇습니다. 
</p>
<p><b>○ 양근서 위원 </b> 지금 보여주신 여기 자료상에는 이게 잘 구분이 안 되고 혼용이 되고 있는 것 같아서 드리는 말씀이고요. 
</p>
<p style="padding-left:1.2em">  그러면 수탁용역사업은 해마다 조금씩 다르겠지만 대체로 연간 어느 정도 규모입니까, 사업비 기준으로 했을 때?
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 계약금액 기준으로 했을 때 2015년, 16년도에는  한 50억 정도 됐었습니다. 그런데…….
</p>
<p><b>○ 양근서 위원 </b> 보니까 자료에 보면 2016년도에는 30억 규모에서 올해는 50억 규모로 거의 한 2배 정도 이렇게 늘려 잡았네요? 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 아닙니다. 2017년도에는 목표를 30억으로 잡았는데요. 2015년도에는 계약 기준으로 53억인가 그 정도로 계약을 한 걸로 알고 있습니다.
</p>
<p><b>○ 양근서 위원 </b> 아닙니다. 업무보고 자료를 보면 지난해에는 수탁연구용역 사업계획을 대략 사업비 규모 30억 원으로 잡았고 올해는 50억 원으로 잡았잖아요. 지금 연구원에서 제출한 자료에 근거해서 말씀을 드리는 거예요. 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네, 3쪽에 2016년도 수탁용역사업이 50억으로 목표를 잡았고 2017년도에는 30억으로 잡았습니다. 
</p>
<p><b>○ 양근서 위원 </b> 지금 뒤집힌 건가요, 그러면? 반대인 건가요? 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 아닙니다. 업무보고자료 3페이지가 맞는 거죠.
</p>
<p><b>○ 양근서 위원 </b> 3페이지. 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 3페이지에 맨 윗단의 표에 의하면 2016년도에는 50억으로 잡혀있고 2017년도에는 30억으로 잡혀 있습니다. 
</p>
<p><b>○ 양근서 위원 </b> 아, 그러니까 오히려 감소했군요? 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네.
</p>
<p><b>○ 양근서 위원 </b> 이 이유는 뭔가요? 이렇게 굉장히 큰 폭으로 감소하게 잡았는데. 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 저희가 2016년도에는 계약금액 기준으로 50억을 잡았는데요. 실제로 집행한 금액이 한 60%인 30억 정도 됐었습니다. 그래서 올해 목표액을 계약금액으로 하지 말고 집행금액으로 하자는 얘기들이 많아서 목표액을 집행금액으로 했습니다. 
</p>
<p><b>○ 양근서 위원 </b> 현실적인 기준에 맞게끔 조정하는 것이고 특별한 사유는 없는 거네요? 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네, 그렇습니다. 
</p>
<p><b>○ 양근서 위원 </b> 그렇다면 수탁용역도 전체 연구인력의 규모나 또는 전체 경기연구원이 갖고 있는 예산, 사업비에 비해서 적정 규모가 있을 거라고 판단되는데 대략적으로 어느 정도 수준, 그러니까 우리 경기도로부터 지원받는 전체 출연금을 가지고 운영하고 있기 때문에 그 규모에 비해서 어느 정도 수탁사업비를 사업계획으로 삼는 것이 적정한 수준이라고 보고 있습니까? 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 저희들의 지난 몇 년간 경험으로 봤을 때 계약금액으로는 한 50억 정도 그다음에 집행금액으로는 한 30억 정도, 그 정도가 돼야지만 저희의 수입금이 한 15억 정도가 잡힐 거라고 생각됩니다.
</p>
<p><b>○ 양근서 위원 </b> 15%요? 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 15억 정도 수입액이요. 보통 전출금을 저희가 35%를 떼고 있기 때문에 매년 한 15억 정도 수입으로 잡고 있습니다. 
</p>
<p><b>○ 양근서 위원 </b> 그런데 실제 그 예산하고 집행비가 이렇게 크게 차이가 나는 이유는 뭐가 있습니까? 50억에서 30억으로 주는 거는.
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 두 가지가 있다고 생각하는데요. 수탁과제 기간이 보통 1년을 넘게 됩니다. 그러기 때문에 계약을 올해 1월 달에 하더라도 내년도에 끝나는 이월된 과제들이 있습니다.
</p>
<p><b>○ 양근서 위원 </b> 계속 이월되는 문제 때문에 그런 결과가 나온다는 얘기인가요?
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 또한 하반기에 계약한 과제들은 이월된 부분이 많기 때문에 그렇습니다. 
</p>
<p><b>○ 양근서 위원 </b> 알겠습니다. 아까도 잠깐 자료제출 요구를 하면서 질문을 했지만 수탁연구용역에 참여했던 비정규직, 계약직 직원들에 대해서 수익금을 배분하지 않고 정규직들이 다 독식하고 있다라고 지적을 했는데 그것은 어떻게 개선이 됐습니까? 일단 구두로 한번 답변해 주시기 바랍니다. 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 저희가 수탁과제를 수행하게 되면 정규직 인건비에 해당되는 부분을 전출금으로 계산해서 일반회계로 돌리고 있습니다. 그런데 비정규직 부분은 우리 내부자원이 아닌 다른 자원을 별도로 채용해서 인건비로 쓰고 있는데요. 그 부분은 저희가 수익금으로…….
</p>
<p style="padding-left:2.4em">    (관계직원, 경기연구원장 직무대행에게 개별설명)
</p>
<p style="padding-left:1.2em">  그래서 원래 수익금 중의 일부를 비정규직한테 특별연구장려금 형태로 지급하고 있습니다. 
</p>
<p><b>○ 양근서 위원 </b> 그러니까 올해부터 그렇게 하는 것으로 개선했다는 얘기입니까? 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네, 그렇습니다. 
</p>
<p><b>○ 양근서 위원 </b> 알겠습니다. 구체적인 세부내역은 자료로 제출해 주시고요. 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네, 알겠습니다. 
</p>
<p><b>○ 양근서 위원 </b> 그런데 이 내용들이 왜 지난해 행정사무감사 주요 지적사항 및 개선사항에서 누락돼 있죠? 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 저희가 특별연구장려금은 작년 행감……. 
</p>
<p style="padding-left:2.4em">    (관계직원, 경기연구원장 직무대행에게 개별설명)
</p>
<p><b>○ 양근서 위원 </b> 지금 행감 자료에는 이 부분이 누락돼 있어요. 왜 그렇죠? 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 아, 그렇습니까? 다시 한 번 확인을…….
</p>
<p><b>○ 양근서 위원 </b> 지난해 행정사무감사에서 주요하게 쟁점이 됐던 이슈고 가장 큰 지적사항 중의 하나였는데. 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 지난해에 지적된 사항에 대해서 저희들이 회의를 거쳐서 제도개선사항으로 해서 31페이지에 포함시켰습니다. 제도개선사항으로 해서 주요업무 보고자료 31쪽에…….
</p>
<p><b>○ 양근서 위원 </b> 31쪽에 어디 있습니까? 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 맨 윗단에 석사급 비정규직…….
</p>
<p><b>○ 양근서 위원 </b> 제도개선사항 그 부분에 들어가 있군요? 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네, 맨 위쪽에 있습니다. 
</p>
<p><b>○ 양근서 위원 </b> 알겠습니다. 그리고 정규직 전환 로드맵 관련해서는 기본방침이, 지금 정부에서 제안하고 있는 가장 큰 핵심적인 지침 중의 하나가 근무연수와 관계없이 지금 현재 하고 있는 일 기준으로 상시업무라고 판단했을 때는 적극적으로 모두 다 정규직 전환에 포함될 수 있도록 하라라고 하는 것이 큰 틀에서 가장 핵심적인 지침내용이지 않습니까? 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네, 그렇습니다.
</p>
<p><b>○ 양근서 위원 </b> 그러면 거기에 대해서 경기연구원에서는 그 기준을 준용해서, 전폭적으로 다 수용해서 정규직 전환 로드맵을 작성하고 있습니까? 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네, 정부의 방침에 따라서 저희도 기본계획을 수립했습니다. 또한 정규직전환심의위원회를 내년도 3월 정도에 구성해서 지금 위원님이 말씀하신 그런 내용을 담도록 노력을 하고…….
</p>
<p><b>○ 양근서 위원 </b> 그 기준으로 하면 현재 거의 한 80~90명에 달하는 비정규직, 계약직 연구원들이 상당수 있지 않습니까? 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네, 그렇습니다. 
</p>
<p><b>○ 양근서 위원 </b> 행정직까지 포함해서. 이분들이 다 어쨌든 정규직 전환 대상에 포함되는 걸로 일단 기준을 잡으려고 하는 것 아닙니까? 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 저희가 지금 비정규직에 111명입니다만 박사급을 뺀 나머지가 한 90명 정도 되고 있습니다. 그중에서 9개월 이상 연속적인 근무를 하고 있고 2년 이상 근무한 사람들이 한 60명 정도 되고 있습니다. 그래서 60명에 대해서는 저희들이 전환심의위원회에서 지금 말씀하신 바와 같이 정규직 전환을 적극적으로 검토하고 있습니다. 
</p>
<p><b>○ 양근서 위원 </b> 그러면 일단은 근무시한을 나름대로 기준을 잡아놓은 상태네요, 6개월이라고? 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네, 그렇습니다.
</p>
<p><b>○ 양근서 위원 </b> 알겠습니다. 일단은 그 세부적인 자료를 제출하면 그거 가지고 후속질문 하겠습니다. 이상입니다.
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네.
</p>
<p><b>○ 위원장 이재준 </b> 양근서 위원님 수고하셨습니다. 다음 이현호 위원님 질의해 주시기 바랍니다. 
</p>
<p><b>○ 이현호 위원 </b> 이현호 위원입니다. 지금 위원석하고 우리 연구원 간부석엔 다 물이 있는데 왜 우리 여기 기자분들은 물 주시면 안 되는 건가요? 물도 안 되는 거예요? 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 아, 죄송합니다. 
</p>
<p style="padding-left:2.4em">    (웃   음)
</p>
<p><b>○ 이현호 위원 </b> 아니, 좀 차별하는 것 같아 가지고 그러네요. 그렇잖아, 다 물 있는데. 
</p>
<p style="padding-left:1.2em">  우리 연구원에서 이번에도 또 이렇게 감사 준비하시느라고 수고 많이 하셨습니다. 앞서서 우리 존경하는 양근서 위원님께서 서두에 말씀하신 내용에 대해서 말씀을 드리겠습니다. 9월 15일 이후에 원장 공석 상태가 지금 계속되고 있어서 애로사항이나 또 향후 추진, 그런 계획에 대해서 어저께 청취하고 또 공공기관의 통일적인 임원 임명제도를 마련해서 임원 선임의 공정성과 전문성을 제고하기 위한 지난 7월 출자ㆍ출연 조례를 우리 존경하는 임채호 위원님께서 발의해서 개정했습니다. 또 시행합니다. 또한 원장 선임절차와 관련해서 임원추천위원회 도입에 대해서 권고하고자 제가 질의를 하겠습니다. 
</p>
<p style="padding-left:1.2em">  지난 9월 15일 우리 임해규 원장이 퇴임 후 현재까지 원장이 공석이지 않습니까?
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네.
</p>
<p><b>○ 양근서 위원 </b> 그렇죠? 현재 부원장 대행체제로 운영하고 있는 것으로 알고 있는데 원장 공석 시 어떤 법적 근거로 직무대행자가 지정이 되었는지 설명해 주시기 바라고요. 또 원장 공석으로 인한 어려움은 무엇인지, 향후 원장 선임 계획은 어떻게 가지고 있는지 먼저 제가 질의하겠습니다. 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 위원님이 말씀하신 그 세 가지 사항에 대해서 말씀드리도록 하겠습니다. 먼저 원장 공석 시 직무대행은 저희 정관 제16조에 나와 있습니다. 직무…….
</p>
<p><b>○ 이현호 위원 </b> 기간 없습니까, 대행직무 기간 없어요? 그러면…….
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 대행직무 기간은 구체적으로 나와 있지 않습니다. 
</p>
<p><b>○ 이현호 위원 </b> 1년이고 2년, 예를 들어서 1년이 넘더라도 원장을 새로 선임하기까지는 계속 직무대행을 합니까? 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네. 지금 정관에는 그런 기간이 명시가 안 돼 있기 때문에 원장이 공석 시에는…….
</p>
<p><b>○ 이현호 위원 </b> 명시를 해 놔야겠네, 그것도. 그렇지 않습니까? 만약에 짧은 기간이라면 모르겠지만 지금 말씀하신 대로 정관에 어떤 직무대행하게 돼 있지만, 그것이 하염없이 말이죠. 시간이 끌려가더라도 직무를 대행한다면 어떻게 보면 원장이 중간에 그만두게 되면 그만둔 기간보다도 대행체제가 더 길 수 있지 않습니까? 그렇죠? 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네, 그런 가능성도…….
</p>
<p><b>○ 이현호 위원 </b> 그러니까 제가 볼 때는 정관을 다시 손을 봐서, 그렇지 않습니까? 어떤 일정한 기간이 있어야 되지 않겠어요? 그렇죠? 그래야만이 빠른 시일 내에 새로운 원장을 선임해야 되지 않나 이렇게 말씀을 드리거든요.
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네.
</p>
<p><b>○ 이현호 위원 </b> 정관을 한번 수정해야 될 것 같지 않겠어요? 그렇죠? 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네, 그 문제는 저희 이사회 이사장과 상의하도록 하겠습니다. 
</p>
<p><b>○ 이현호 위원 </b> 한번 챙겨 보시기 바랍니다. 그거 말씀하시고요.
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 그다음에 향후 원장 선임에 대해서, 공개절차에 관련돼서 저희가 이사장과 협의를 한 바 있습니다. 그래서 이사장이 이사회에서 보고안건으로 선임절차나 앞으로 향후 일정에 대해서 좀 보고했으면 좋겠다는 그런 희망사항이 있어서 24일 날 보고를 하도록 예정이 되어 있습니다. 
</p>
<p><b>○ 이현호 위원 </b> 알았습니다. 그리고 8월 31일 날 원장 공개모집 공고를 냈고 아까 우리 존경하는 양근서 위원님도 질의하셨지만 그 후보자가 돌연 사퇴했어요, 그렇죠? 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네, 그렇습니다. 
</p>
<p><b>○ 이현호 위원 </b> 그런데 그 사퇴한 배경을 여기서 우리 도의원들에게 공개할 수 있습니까? 왜 사퇴하셨는지.
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 제가 얘기 듣기로는 서울대 국제대학원에서 휴직하는데 휴직 정원이 남지 않아서 학교에서 휴직 처리를 해 주지 못한다라는 그런 얘기를 들었습니다. 
</p>
<p><b>○ 이현호 위원 </b> 그러니까 그러한 문제점이 있는데 사전에 그런 것까지 파악도 못 하고 여기서, 본인도 마찬가지지만 여기서도 마찬가지고. 그러한 분을 적정한 인물이라고 해서 선정했다가 돌연 사퇴하는 바람에 지금 공백 기간이 생겼지 않았습니까, 그렇죠?
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네.
</p>
<p><b>○ 이현호 위원 </b> 거기에 대해서는 책임감을 통감해야 되지 않겠습니까, 연구원에서? 그렇지 않나요? 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네, 그렇습니다. 
</p>
<p><b>○ 이현호 위원 </b> 그거 인정하시죠? 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네. 
</p>
<p><b>○ 이현호 위원 </b> 차후엔 그런 일이 없길 바라고요. 또한 제가 볼 때 왜 원장 후보를 1명만 선정합니까? 2명을 해 놨으면 혹시 1명이 중간에 문제점이 있어서 그만두더라도 그다음 사람을 선정해서 인사청문회 열어서 원장으로 이렇게 임명할 수가 있는데 왜 1명을 해 놨냐 이거죠. 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 그 문제에 대해서 저희 내부에서도 얘기가 있었는데요. 저희 연구원의 설립에 관련돼서 지방자치단체출연 연구원의 설립에 관한 법률에 의거해서 저희가 이사회의 의결을 통해서 원장 선정을 이사장이 임명하도록 그렇게 조항에 돼 있기 때문에…….
</p>
<p><b>○ 이현호 위원 </b> 아니, 법령에 꼭 한 사람만 선정하게 돼 있어요? 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 지금까지 그렇게 해 왔기 때문에…….
</p>
<p><b>○ 이현호 위원 </b> 지금까지 그랬어도 그거를 고칠 수 있는 거 아니에요, 방법을. 꼭 그거를 고집할 필요는 없지 않냐 이거죠. 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 그것도 저희 이사회에 보고안건으로 한번 얘기해 보도록……. 
</p>
<p><b>○ 이현호 위원 </b> 아까 우리 존경하는 임채호 위원님께서 지난번에 발의하신 내용이, 또 임원추천위원회를 구성하게 돼 있잖아요, 그렇죠? 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네.
</p>
<p><b>○ 이현호 위원 </b> 구성했습니까? 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 저희가 그것도 나름대로 분석을 했는데요. 지금 조례에서 임원추천위원회를 구성하도록 되어 있고 복수추천해서 도지사가 임명하도록 되어 있습니다만 그 예외조항에 출자ㆍ출연에 관련된 법률을 적용받는 저희 연구기관은 제외하도록 한다는 규정이 있기 때문에 출자ㆍ출연 기관에 관련된 법률에 적용해서 저희가 임원추천위원회를 구성하지 않고 지금까지 해 왔던 심사위원회를 구성해서 했습니다.
</p>
<p><b>○ 이현호 위원 </b> 글쎄, 지금까지는 임원추천위원회를 구성 않고 이사회를 거쳐서 했지만 지난번에 조례가 개정됐으니까……. 다른 기관에도 보면 서울 같은 경우에도, 서울연구원에 보니까 임원추천위원회를 만들어서 원장을 선임하더라고요, 그렇죠? 알고 계세요? 서울의 경우, 서울. 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 서울이요?  
</p>
<p><b>○ 이현호 위원 </b> 그거 알고 계신 거예요? 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 그건 제가 정확히는 잘 모르겠습니다. 
</p>
<p><b>○ 이현호 위원 </b> 서울의 경우는 거기도 임원위원회를 추천해서 원장을 선정하게 돼 있더라고요, 선임하게끔. 우리 경기도도 조기에 그런 방법으로 해야 되지 않나 이렇게 말씀드리는 건데 거기에 동의하십니까? 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 그 문제에 대해선 저희가 이사장하고도 협의를 했습니다. 전임 원장과도 협의를 해서 그 조례에 나와 있는 출자ㆍ출연 기관의 설립에 근거되는 법령에서는 그 규정에 따른다, 이렇게 돼 있어서 저희가 그때는 그렇게 단수추천으로 했습니다만 앞으로 이 문제에 대해서는 저희가 이사장하고 이사회에서 다시 얘기를 해야 될 것으로 생각이 됩니다. 
</p>
<p><b>○ 이현호 위원 </b> 제가 볼 때는 꼭 의도적으로, 고의적으로 경기연구원 원장 선임을 아예 하지 않는 건가 이런 오해도 불러일으킬 수가 있어요. 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 그건 절대 아닙니다. 
</p>
<p><b>○ 이현호 위원 </b> 그야 물론 당연히 절대 아니라고 하겠지만 그런 오해를 불러일으켰기 때문에 그런 걸 앞으로 불식시키기 위해서는 아까 말씀하신 대로 후보자를 복수선정해서 하는 것이 낫지 않겠나 이런 말씀을 드리는 건데 아까 말씀하실 때에 한번 고려해 보신다고 했으니까 그렇게 해 주시기 바라고요.
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네.
</p>
<p><b>○ 이현호 위원 </b> 정말 우리 연구원에서 가장 중요한 핵심 역할을 하는 원장이 상당히 오랫동안 이렇게 공석으로 있는데 공석으로 있어도 어떤 문제가 없나 보지요? 문제없어요? 우리 연구원 운영하는 데 아무 하자 없습니까? 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 아닙니다. 저희가 시스템으로 이루어졌기 때문에 웬만한 일은 잘 처리가 되는데요. 그런데 연구사업 계획이나 예산과 인사 이런 부분에서는 원장의 가치나 철학에 근거해서 반영이 돼야 되는데 그런 부분이 반영되지 않고 그다음에 인사, 새로운 정규직 박사를 뽑는 데 있어서도 여러 가지 어려운 점이 많습니다. 
</p>
<p><b>○ 이현호 위원 </b> 제가 볼 때는 우리 경기연구원도, 우리 도 산하기관에 보면 거의 다 임원추천위원회를 구성해서 하거든요. 그런데 유독 경기연구원만 그렇게 안 하고 있단 말이에요. 그렇지요? 제가 볼 때는 경기연구원도 임원추천위원회 제도를 도입해 가지고 해도 아무런 문제가 없습니다. 앞으로 임원추천위원회를 만들어서 우리 연구원도 임원을 선정해 주시기를 바라고요. 또한 다른 시도의 사례도 한번 참고하셔서 제가 말씀드린 것을 도입해 주시기를 부탁드리겠습니다. 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네, 추후에 검토를 하도록 하겠습니다. 
</p>
<p><b>○ 이현호 위원 </b> 이상 마치겠습니다. 
</p>
<p><b>○ 위원장 이재준 </b> 이현호 위원님 수고하셨습니다. 다음 오완석 위원님 질의해 주시기 바랍니다.
</p>
<p><b>○ 오완석 위원 </b> 수원 출신 오완석 위원입니다. 감사 준비하느라고 고생 많으셨고요. 저는 기본현황 몇 가지 확인하고 하겠습니다. 보니까 전기이월금이 매년 한 27억 이상이 됩니다. 그러니까 퍼센트로 따지면 한 13%가 되는데 여기가 출연금 받아서, 기금 또 수탁사업 받아서 하는데 전기이월금이 이렇게 많이 생기는 이유가 어떤 것들 때문인가요? 이게 관례적으로 생긴 건가요, 아니면 이번에만 그런 건가요?
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 그 전년도에도 한 28억 정도 생겼습니다. 
</p>
<p><b>○ 오완석 위원 </b> 네. 그러니까 그게 구조적으로 그렇게 될 수밖에 없는 건지 아니면, 왜 그렇게 남는 거지요? 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 저희가 약간 구조적인 면도 있습니다. 
</p>
<p><b>○ 오완석 위원 </b> 어떤 부분 때문에요?
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 첫 번째는 연구과제를 수행할 때 남는 돈들이 이월되거나 아니면…….
</p>
<p><b>○ 오완석 위원 </b> 과제가 끝나야 집행을 해서 그런 건가요?
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네, 과제가 끝나고 집행되는 것도 있고…….
</p>
<p><b>○ 오완석 위원 </b> 잔금, 계약금 치르고 이런 식으로 과제 끝나야만 해야 되기 때문에 매년…….
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네, 그렇습니다.
</p>
<p><b>○ 오완석 위원 </b> 단기간, 1년 내에 끝나지 않는 과제가 연결되기 때문에 그래서 어쩔 수 없이 그럴 수밖에 없다는 거예요?
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네, 그런 것도 7억 정도가 그렇게 되고 있습니다. 
</p>
<p><b>○ 오완석 위원 </b> 매년 그럴 수밖에 없는 거예요?
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네, 매년 그렇게 될 수밖에 없는 상황이고요.
</p>
<p><b>○ 오완석 위원 </b> 알겠습니다. 그다음에 사업수익을 보면 15억 5,800만 원으로 한 8% 정도 되는데요. 이게 우리 수탁사업하고 관련돼 있는 건가요?
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네, 전부 다 수탁사업에서 나오는 금액입니다.
</p>
<p><b>○ 오완석 위원 </b> 수탁사업 외에 다른 거는 없는가요?
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네, 다른 거는 없습니다. 
</p>
<p><b>○ 오완석 위원 </b> 그런데 아까 말씀하실 때 수탁사업이 2017년도에 존경하는 양근서 위원님이 질문하셨을 때 50억에서 30억으로 줄었습니다. 그걸 현실화시키기 위해서 그랬다고 했는데 수탁사업 사업수익이 올해 것만, 제가 자료를 못 받아서 그런데 올해 건 이런데 작년도는 어느 정도 됐었어요, 규모가?
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 작년도에도 한 15억 5,000만 원…….
</p>
<p><b>○ 오완석 위원 </b> 그럼 현실적으로 줄이려면 20억 정도 다운시켜야지 30억으로 예상을 해 놓으면 어떻게 합니까?
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 그거는 왜냐하면 계약금액이 50억이었기 때문에 실제로 집행금액은 30억이었습니다. 작년도에 30억이었고 거기에서 35% 정도의……. 
</p>
<p><b>○ 오완석 위원 </b> 그러면 이렇게 질문할게요. 그러면 수탁사업이 건수가 좀 어떻습니까? 수탁사업 의뢰건수가 좀 늘어나는 편입니까, 아니면 줄어드는 편입니까? 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 의뢰건수는 한 50건, 45건 정도 작년에, 재작년도에 그렇게 됐었는데요. 올해는 줄어들었습니다. 올해는 26건으로…….
</p>
<p><b>○ 오완석 위원 </b> 지난 3년 내지 5년 보면 줄어들고 있는 편이에요, 늘어나…….
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네, 최근에 들어서 줄어들었습니다. 
</p>
<p><b>○ 오완석 위원 </b> 계속 줄어드는 편이에요? 그 이유가 뭐라고 생각하시는지 혹시…….
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 저희가 생각하기에는 입찰을 저희가 해야 되는데, 입찰에는 두 가지 종류가 있는데요. 적격심사에 의한 입찰이 있고 그다음에 협상에 의한 입찰이 있는데 경기도하고 시군에서 입찰하는 게 낮은 가격으로 우선순위가 되는 적격심사에 의해서…….
</p>
<p><b>○ 오완석 위원 </b> 입찰경쟁에서 우리가 좀 밀린다는 건가요?
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네.
</p>
<p><b>○ 오완석 위원 </b> 그럼 앞으로도 계속 그럴 수밖에 없는 건가요? 저도 경기연구원에 대해서 주변에 들어보면 연구진이 워낙 훌륭하시고 그다음에 연구결과가 괜찮아서 시군에서도 많이 활용을 했고 그다음에 다른 곳에서도 많이 했다고 하는데 지금은 각 지자체별로 연구하는데, 수원시 같은 경우도 시정연구원이 생기고 해서 갈수록 더 줄어들 수밖에 없는 구조가 아닌가 싶기도 한데, 그러면 여기에 대한 무슨 대비책이나 아니면 그냥 내버려둬도 되는 건지, 원장님 입장은 어떻습니까?
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 그래서 저희가 개선방안으로서 중앙정부에서 추진하고 있는 여러 가지 사업들이 있습니다. 특히나 ODA 사업 같은 것도 저희가 적극적으로 나설…….
</p>
<p><b>○ 오완석 위원 </b> 시군 사업은 이미 자체적으로 시군에서 소화를 하고 있기 때문에 중앙정부에서 진행되고 있는 사업을 경기연구원에서 수탁을 받아서 할 수 있는 방법 쪽으로 연구를 노력하시겠다 이런 거지요? 그 성과는 좀 나오고 있나요?
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 지금 2017년도에 ODA 사업 중에 캄보디아 교통학술용역을 저희가…….
</p>
<p><b>○ 오완석 위원 </b> 수주를 했어요? 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네, 수주를 했습니다. 관체 공동으로 수주했습니다.
</p>
<p><b>○ 오완석 위원 </b> 관심을 가지시고, 사실 연구원분들이 수탁과제를 많이 받아서 자기 분야에 대해서 연구도 하시고 그런 업무성과를 계속 내셔야 만이 연구원으로서의 역할이 있지 않습니까? 일이 없어서 일을 못 하면 문제가 되는 거니까 그런 부분도 적극적으로 했으면 좋겠고, 실질적으로 정원을 보면 연구원분들이 한 9명의 정원이 결원돼 있는데 그중 6명이 연구직이에요. 이거는 제가 지난번에도 그런 것 같은데 이게 무슨 이유가 있나요? 채워지지 않는……. 어떻게 질문해야 되나? 6명 정도는 문제가 없나요? 연구원 6명이면 상당히 많은 것 아닙니까? 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 그래서 저희가 원장님이 오시면 정규직 직원을 새로 채용한다는 계획을 가지고 있었습니다. 그런데 올해도 3명을 채용한다는 계획을 가지고 있었습니다만 원장님이 안 계시는 바람에 채용을 할 수 없는 그런 상태이고요.
</p>
<p><b>○ 오완석 위원 </b> 네, 알겠습니다. 그리고 존경하는 이재준 위원장님이 요구하신 자료를 보면 예산 집행실적 및 위탁사업 수입현황인데 여기에 보면 집행잔액이 저조한 부분이 몇 개 있어요. 여기 보면 의정연구교류 같은 경우는 2015년, 2016년, 2017년도 모두 다 집행률이 낮고요. 그다음에 정책세미나와 포럼운영 같은 경우도 그렇고 인적자원개발비 같은 것도 그렇고. 물론 연구사업비 중에 연구과제사업이라든가 기본과제, 정책과제, 정책현안분석 같은 경우는 대부분 집행잔액이 많지 않은데 그 외에 의정연구교류라든가 그 외에 어찌 보면 다른 기관, 의회나 이런 쪽에 함께할 수 있는 이런 부분들인데 그런 부분들이 계속 집행률이 떨어지고 있어요. 그것도 반도 안 됩니다. 그 이유가 뭡니까? 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 의회하고 저희가 교류한 부분이 한 서너 가지 사업이 있었는데요. 근본적으로 의정연구포럼은 횟수로는 한 횟수가 줄어들었습니다. 그거는…….
</p>
<p><b>○ 오완석 위원 </b> 의정연구교류 이게 구체적으로 어떤 사업이지요?
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 의정연구교류가 첫 번째는 의정연구포럼이 있고요. 두 번째는 민생의제 토론회라고 돼 있고 시군 토론회가 있고 의정콜로키움 네 가지로 구성돼 있습니다. 
</p>
<p><b>○ 오완석 위원 </b> 저도 세 가지를 다 활용을 같이 해 봤고 또 최근에는 광교신도시의 교통문제 때문에 한번 했는데 정말 의원 입장에서는 되게 중요하고 되게 괜찮은 것 같아요. 그런데 이게 홍보가 돼서 그렇지 않은가. 물론 저도 매달 하고 싶어요. 지금 현안문제가 하도 많아 가지고 매달 하고 싶은데 기획재정위원이라고 특권을 가지고 매달 하는 것 같아서 제가 의뢰를 못 하는데 이게 매년 집행률이 저조하다는 얘기는 활용을 안 하고 있다는 것이지 않습니까? 그래서 물론 과거에는 경기연구원이 집행부에서 요구하는 연구를 주로 많이 했으면 지금은 경기도의회에서 적극적으로 의뢰도 많이 하고 또 그 건수가 계속 늘어나고 있는 것 같은데 실질적으로 의정연구교류 같은 경우는 상임위나 이런 데보다도 의원 개개인이 필요에 의해서 하는 연구가 많지 않습니까, 토론회나 포럼이나 이런 부분들이. 저는 이걸 적극적으로 좀 더 활용을 해야 되지 않느냐.
</p>
<p style="padding-left:1.2em">  왜 그러냐 하면 국회의원 같지 않고 우리 도의원님들은 정책개발하는 데 정말 힘듭니다. 토론회 하나 준비하는 데 정말 힘들어요, 혼자 다 할 수가 없으니까. 그런데 이번에 해 보니까 너무 좋아요. 다 준비해 주시고 와서 전문가분들까지 다 섭외해 주시고 또 저희는 가서 인사말 하고 지역주민들과 함께하면서 그 부분에 대해서 아주 양질의 정보를 얻을 수 있고 주민들도 되게 좋아하시고. 그래서 괜찮은 것 같다.
</p>
<p style="padding-left:1.2em">  그리고 이것은 당연히 예산을 늘려서라도 좀 더 적극적으로 홍보를 해서, 물론 인원이 어떨지 모르겠습니다. 경기연구원에서 그만한 연구진분들이 도와줄 수 있는지는 모르겠지만 아무튼 조정을 해서라도 이 부분을 적극적으로 활용할 수 있고 또 많은 위원님들이 할 수 있게끔 좀 해야 되지 않겠느냐. 이 부분은 물론 경기연구원에서만의 노력 가지고만 되는 게 아니겠지요. 경기도의회에서도 노력을 해야 될 것 같은데 저도 경기도의회의 의총 때라든가 아니면 다른 걸 통해서라도 홍보를 하고 또 활용할 수 있는 방안을 찾도록 해 보겠습니다. 이 부분은 중요한 것 같고 우리 개개인 의원님들한테도 소중한 프로그램인 것 같아요. 그래서 이걸 연구개발해서 많이 활용할 수 있게끔 그렇게 부탁을 드리겠습니다. 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네.
</p>
<p><b>○ 오완석 위원 </b> 정책세미나도 같은 건가요?
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 정책세미나는 주로 도나 의회에서 요청한 경우에 저희들이 준비하는 건데요. 올해는 도나 의회에서 요청한 경우가 작년도에 비해서 약간 줄어들었습니다. 그 이유를 한번 봤더니 시군 전략과제를 지금 하고 있기 때문에 시군 전략과제에서 자체적으로 토론회나 포럼을 하고 있기 때문이 아닌가 이렇게 생각됩니다. 
</p>
<p><b>○ 오완석 위원 </b> 그러니까 이제는 시군에서도 규모가, 경기도 같은 경우는 특히 100만 이상이 되고 있는 수원시 같은 경우는 특례시 해 달라고 하고 있고, 그러면서 자체적으로 개발 내지는 정책들이 있기 때문에 자체적 연구원을 만들어서 예산도 많이 지원해 주고 투자를 적극적으로 하고 있습니다. 과거하고 좀 다르지요. 우리 경기연구원도 물론 지금까지 잘해 오셨고 또 정책개발에 대해서는 어느 연구원 못지않게 우리나라에서 손꼽을 정도로 잘하고 있다고 저는 알고 있는데 하여튼 그런 부분들에 좀 더 박차를 가해야 되지 않나 싶습니다. 
</p>
<p style="padding-left:1.2em">  그리고 한 가지 더 보면 이 자료에 의하면 책임연구원별로 연구과제를 수행하시는데 연구원에 따라서 연구과제가 좀 차이가 있습니다. 많은 분들은 많고, 심지어는 13건이라면 6건, 4건, 5건 이하로 하는데 그게 특별한 이유가 있나요? 아니면 연구의 정책 내용 때문에 그런가요, 무엇 때문에 그런 거지요? 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 우선 책임연구과제 수가 적은 것은 연구년으로 갔다든지 아니면 파견을 갔다든지 이런 경우의 하나고요. 보통 기본적…….
</p>
<p><b>○ 오완석 위원 </b> 보통 기본적으로는 연구원분들의 연구가 거의 비슷하게 하는 거고…….
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 한 3건에서 6건 사이…….
</p>
<p><b>○ 오완석 위원 </b> 줄어든 것은 조기퇴직했다든가 아니면 다른 데 해서 다른 업무를 보신다든가 그런다는 거지요?
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네, 그렇습니다.
</p>
<p><b>○ 오완석 위원 </b> 네, 알겠습니다. 수고하셨습니다. 이상입니다.
</p>
<p><b>○ 위원장 이재준 </b> 오완석 위원님 수고하셨습니다. 다음 임채호 위원님 질의해 주시기 바랍니다.
</p>
<p><b>○ 임채호 위원 </b> 임채호 위원입니다. 감사 준비하시느라고 우리 직원분들 수고 많으셨습니다. 
</p>
<p style="padding-left:1.2em">  먼저 8쪽을 보면 2018년도 주요업무계획이 있습니다. 우리가 향후 2017년이면 2017년도에 대한 평가를 받고 2018년도에 대한 사업계획을 짜잖아요?
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네.
</p>
<p><b>○ 임채호 위원 </b> 이렇게 2018년도 차기년도에 대한 사업계획을 짤 때는 어떤 방법으로 짜나요? 기획을 어떻게 하나요? 사업명, 어젠다나 이런 걸 정할 때 그걸 어떻게 짜나요?
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 저희가 연구기획본부에서 기안을 해서 연구계획 발표회가 있습니다. 저희 10월 달에 했었는데 거기에서 발표를 해 가지고 많은 사람들의 의견을 듣고 그걸 가지고 다시 계획을 짜도록 이렇게 되어 있습니다. 
</p>
<p><b>○ 임채호 위원 </b> 그렇게 되다 보면 기본용역과제는 어느 정도 이렇게 하겠다라는 목표가 있겠지요?
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네.
</p>
<p><b>○ 임채호 위원 </b> 그런데 2017년도는 목표가 몇 개였었나요?
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 2017년도에 정책과제는 99개, 수탁과제는 금액으로 한 30억…….
</p>
<p><b>○ 임채호 위원 </b> 글쎄, 그거는 알고 기본연구과제를 지금 1건밖에 안 했잖아요.
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 아, 그거는 9월 말에 끝난 거를 기준으로 했기 때문에 14개 과제가 지금 진행 중에 있습니다. 
</p>
<p><b>○ 임채호 위원 </b> 아, 진행 중에 있다?
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네, 그렇습니다.
</p>
<p><b>○ 임채호 위원 </b> 계속적이기 때문에.
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네. 
</p>
<p><b>○ 임채호 위원 </b> 그리고 연구분야의 새로운 연구과제 어젠다를 정할 때 주로 제가 생각하기에는 가장 시급한 게 올 같은 경우 내년 사업은 새로운 정부가 들어섰단 말이에요. 그리고 지방선거가 있어 가지고 새롭게 또 시작돼야 되는 그런 지자체도 되잖아요. 그랬을 때 그걸 반영해서 어젠다를 정해야 되지 않나 이렇게 생각이 돼서, 지금 보면 중기연구 어젠다 안을 보면 지금 문재인 정부에서 강력하게 추진하고 있는 게 도시재생사업입니다. 그렇지요? 재개발사업의 문제점이 너무 많기 때문에 도시재생사업을 임기 내 1년에 10조씩 50조를 준비해서 도시재생사업을 하겠다. 이러한 게 나왔을 때 우리 경기도에서 어떻게 거기에 대해서 대응을 해서 우리 경기도의 도시재생사업의 마중물이 돼야 되느냐 또 어떤 지역이 거기에 해당이 돼야 되느냐라는 게 그 어젠다에 들어가 줘야 되지 않나 이렇게 생각이 돼서 드리는 거고요.
</p>
<p style="padding-left:1.2em">  두 번째는 문재인 정부에서 자치분권을 사실 연방제 수준으로 하겠다는 겁니다. 지방자치단체가 아니고 지방정부 수준으로 만든다는 얘기지요. 그렇지요?
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네.
</p>
<p><b>○ 임채호 위원 </b> 지방정부 수준으로 만든다는 건데 지금 연구과제 어젠다에는 전혀 그런 게 없어요. 자치분권과 관련돼서 경기도는 어떻게 해야 되느냐? 
</p>
<p style="padding-left:1.2em">  그다음에 개헌 관련돼서도 제가 한 말씀 드릴게요. 내년 지방선거 6ㆍ13과 대비해서 개헌을 하겠다. ‘개헌을 하면 그 개헌에 우리 경기도는 지방정부로서의 어떤 어떤 내용이 담아져야 되지 않나?’ 그런 것도 같이 의회하고 협의도 해 보고 또 나름대로 연구 어젠다로 정해서 연구할 필요성이 있다는 것을 말씀드리고 싶습니다. 그렇지요?
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네.
</p>
<p><b>○ 임채호 위원 </b> 다음에 우리 경기도의회에, 아까 오완석 존경하는 위원님께서 말씀하셨지만 그래도 경기연구원하고 의회가 좀 더 연구과제뿐만이 아니고 소통이 잘 되는 것 같아요, 그나마. 그래서 경기도의회와 의회 의원들, 개개인까지는 어렵더라도 상임위원회 관련된 현황 어젠다를 우리 경기연구원에서 비전 제시랄까, 앞으로 이런 상임위원회에서는 이렇게 이렇게 하는 것도 괜찮다라는 어젠다를 한번 정해서 이렇게 해 나간다면 이게 다 경기도를 위한 경기연구원의 설립존재가 아닌가 이렇게 생각이 드는 거지요.
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네. 
</p>
<p><b>○ 임채호 위원 </b> 수탁ㆍ위탁받아 가지고 대학 다니면서 의회에서 아르바이트를 하는 건지 아르바이트하기 위해서 대학을 다니는 건지는 모르겠지만 이 수탁ㆍ위탁 난, 크게 여기 나름대로의 자구책 차원에서는 좋지요. 어떤 수입이 들어와서 연구원들의 재정적 부담도 해소해 주고 이런 건 참 좋은데 이러한 우리 경기연구원의 설립목적과 취지에 맞게끔 우리 경기도 도민과 경기도를 위해서 어떤 어젠다 정책을, 지금도 괜찮은 정책들은 많이 있습니다. 이렇게 보면 핵 위기에 대응한 공론화, 일자리, 저출산 이런 여러 가지가 있는데, 4차산업과 관련된 이런 게 있는데 이번 18년도에는 새로운 정부 또 그다음에 정책에 대해서도 우리가 대응해야 할 부분 또 지방자치단체에서 우리가 어떻게, 새로운 지방자치가 탄생이 되면 어떻게 나가야 되는가 방향이나 이런 걸 어젠다로 집어넣었으면 하는 그런 아쉬움이 있어서요. 그 부분에 대해서 한번 말씀 좀 해 보세요. 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 우선 위원님이 말씀하신 어젠다는 저희들이 경기도 공무원들이랑 도민들 의견을 받아서 이 어젠다를 받았습니다. 그래서 어젠다 14개를 세팅했는데요. 위원님들의 의견을 받지 못한 것에 대해서는 저희가 잘못했다고 생각이 됩니다.
</p>
<p style="padding-left:1.2em">  그리고 재생과 관련해서는 저희가 이 문제에 대해서는 상당히 중요하다고 생각하고 있기 때문에 12쪽에서도 주요연구과제에 이상대 박사의 지역단위 재생전략연구랑 장윤배 박사의 도시재생 뉴딜사업에 대응한 지자체의 역할 이 두 가지를 과제로 설정을 하고 있습니다.
</p>
<p style="padding-left:1.2em">  그다음에 연방제 수준의 지방정부 개헌과 관련해서도 다음 11쪽에 박충훈 박사와 조성호 박사가 재정분권 그다음에 신정부의 지방분권 추진방향과 대응전략 이런 2개 과제를 과제로 설정해서 연구를 하고 있고 또한 개헌 포럼도 여기서 운영해서 개헌에 관련된 대응을 하려고 저희들이 적극적으로 생각하고 있습니다. 
</p>
<p><b>○ 임채호 위원 </b> 하여간 우리 경기연구원이 그런 데 신속하게 대처하고 그 지역, 그때그때 그 시기나 거기에 어떤 문제점이 도출했을 때 팩트체크를 하면서 정책분석을 해서 위원들한테 지금 보내주고 있죠? 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네, 그렇습니다. 
</p>
<p><b>○ 임채호 위원 </b> 그건 너무 잘하고 계신 것 같고 그렇게 좀 더 2018년도에는 나름대로 우리 정책을 갖다가 개발을 하고 의회 의원들 또 도 공무원과의 소통 그런 거를 잘하고 계시지만 더 분발해 주실 것을 부탁드립니다. 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네, 더 열심히 하도록 하겠습니다. 
</p>
<p><b>○ 임채호 위원 </b> 이상입니다. 
</p>
<p><b>○ 위원장 이재준 </b> 임채호 위원님 수고하셨습니다. 다음 장동일 위원님 질의해 주시기 바랍니다. 
</p>
<p><b>○ 장동일 위원 </b> 부원장님 이하 직원 여러분들, 준비하시느라고 수고 많으신데요. 경기연구원의 정책반영 연구 건수가 자료를 보니까 해마다 조금씩 줄고 있는데, 수치상으로는. 2017년 거는 반영이 내년에 된다 하더라도 해마다 조금씩 줄고 있는 걸 볼 수가 있고, 특히 중요한 도정 현안이나 선도적 수범사례 이런 부분들이 수치상으로 조금씩 줄고 있는데 그거에 대한 설명을 좀 해 주시겠습니까? 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 저희 연구과제가 10월 달 이후 3개월 동안 거의 반 이상이 끝납니다. 그래서 그 과제가 끝나면 한 6개월 내지 1년 정도 정책에 반영된 거를 알 수 있는데요. 작년에도 그랬고 재작년에도 그랬고 한 6개월, 1년 정도 지난 다음에 이 정책과제가 반영되니까 그 통계 수치는 한 내년도 전반기가 되면 저희도 지금 한 62건에서 150건 이상으로 될 거라고 예상이 됩니다. 지금 이거는 9월 30일 현재…….
</p>
<p><b>○ 장동일 위원 </b> 그러니까 밑에 설명이 나와 있듯이 내년 이후로 반영이 된다 하더라도 어쨌든 3년간 계속 이렇게 하향곡선을 그리고 있어요, 수치상으로는. 그 부분에 대해서 조금 궁금해져서요. 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 이거는 2015년에 비해서 2016년에도 좀 줄어들었고 2017년에도 이 상태면 줄어들 걸로 예상이 됩니다만 그 법령 제ㆍ개정, 제도개선 이 부분에서 약간 줄어든다고 생각이 되는데요. 이 문제에 대해서는 저희가 구체적으로 한번 검토를 해 봐야 될 것 같습니다. 
</p>
<p><b>○ 장동일 위원 </b> 네, 한번 좀 봐 주십시오, 이 부분은. 그래서 별도로 제가 한번 나중에 또 알아보도록 하겠습니다. 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네, 알겠습니다. 
</p>
<p><b>○ 장동일 위원 </b> 그다음에 14개 핵심 어젠다에 아까 우리 질문에 나왔습니다마는 저출산 문제에 대해서 경기도가 2020년까지 현재 출산율보다 획기적으로 비율을 높여서 1.5명 정도로 늘리겠다는 계획을 제가 언론에서 본 적이 있는데 이거 알고 계십니까? 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네, 대략적으로 알고 있습니다.  
</p>
<p><b>○ 장동일 위원 </b> 그 연구를 경기연구원에서 한 게 아니고 다른 외부기관에서 연구를 했던데 참여를 하셨나요, 그때? 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 저희 연구원에서요? 
</p>
<p><b>○ 장동일 위원 </b> 네. 좋습니다, 아무튼. 그래서 우리가 이 부분은 일자리 문제와 같이 맞물려서 제일 중요한 부분인데 이 부분에 대해서는 어떤 계획을 가지고 있습니까? 여기 보니까 저출산 및 일ㆍ가정 양립 해서 어젠다에 포함돼 있긴 한데 뒷부분에 구체적인 내용이 안 나와 있는 것 같은데. 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 저희가 저출산 인구에 관련돼서는 지금 경기도하고 같이 협의해서 인구영향평가를 하고 있고 그다음에 인구정책 지표 산정 이런 비슷한 연구를 하고 있습니다. 그래서 저출산ㆍ고령화에 대응한 인구정책을 하기 위해서 내년도에도 이런 문제에 초점을 맞춰서 계획을 잡고 있습니다. 
</p>
<p><b>○ 장동일 위원 </b> 그리고 도시재생 관련해서 앞서도 질의가 나왔습니다마는 도시재생은 3년, 4년 이렇게 걸려서 이게 성과가 나오는 게 아니잖아요? 보통 한 10년 가까이는 이렇게 성과를 보고 여러 가지 워낙 범위가 폭넓고 이해관계도 복잡하기 때문에 상당히 어렵고 힘든 과정인데 경기연구원에서는 어떤 방향으로 방향을 잡고 있어요? 이게 굉장히 중요한 문제인데. 제가 잠깐 한두 가지 사례를 보면, 제가 실제 가본 곳인데요. 전라남도 순천 같은 경우는, 서울은 더 잘하고 있지만. 실제로 도시재생에 성공한 사례가 전국적으로, 이 얘기가 나온 지는 오래됐어도 그렇게 많지가 않아요. 특히 전라남도 순천 같은 경우는 구도심이 굉장히 공동화돼 가지고 시하고 시민사회단체가 협업 비슷하게 조금씩 챌린지 숍이라고 해서 이렇게 뭘 도전하는 형식으로 창업센터를 만들어서 구도심이 다시 활성화되는 그런 걸 제가 직접 가서 봤는데 그 과정도 굉장히 어렵다고 하더라고요, 지자체에서 지원도 해 주고 하는데. 그래서 이런 부분들을 종합적으로 봐서 이 부분에 접근해야 될 것 같은데, 거기에 대한 앞으로의 계획 한번 미리 설명해 주시죠. 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 그거 관련해서 저희 계획은 재생사업에 대한 기본적인 방향을 설정하고 그다음에 전통시장, 구 상권 이런 분야에서 또 다른 분이 하고 있기 때문에 그것과 같이 맞물려서 융합적인 연구를…….
</p>
<p><b>○ 장동일 위원 </b> 이게 복잡하더라고요. 분권하고 도시재생은 지금 굉장히 정부에서도 추진하려고 하는 의지가 강하고 또 실제 저희들의 굉장히 중요한 부분이기 때문에 경기연구원에서도 이 부분에 대해서 경기도 차원에서 심도 있게 접근을 해야 될 것 같은데 이게 간단한 문제가 아니고 굉장히 복잡해요, 접근방식이. 시간도 오래 걸리고. 그래서 단순하게 그냥 어젠다에 넣어서 형식적으로 추진하겠다 그렇게 접근하면 안 될 것 같고 시작부터 좀 치밀하면서도 심도 있게 계획해야 되겠다는 생각에서 질의를 드리는 건데 부원장님, 거기에 대해서 설명 좀 해 주세요. 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 저희가 이 문제에 대해서는 지금 위원님 말씀하신 바와 같이 내년도에 조금 더 세밀하게 과제를 추진하도록 하고 관련된 분들의 의견을 모아서 여러 가지 어려운 점을 극복할 수 있는 그런 상태로 추진하도록 하겠습니다. 
</p>
<p><b>○ 장동일 위원 </b> 알겠습니다. 이상입니다. 
</p>
<p style="padding-left:2.4em">    (이재준 위원장, 나득수 간사와 사회교대)
</p>
<p><b>○ 위원장대리 나득수 </b> 장동일 위원님 수고하셨습니다. 다음 질의하실 위원님 계십니까? 최춘식 위원님 질의해 주십시오. 
</p>
<p><b>○ 최춘식 위원 </b> 최춘식 위원입니다. 감사 준비하시느라고 직원 여러분들 고생 많이 하셨습니다. 용어에 대해서 잠깐 질문을 드려보고 다음 단계로 넘어가도록 하겠습니다. 
</p>
<p style="padding-left:1.2em">  여기 연구과제에 보면 연구유형이 나와 있잖아요? 기본, 전략, 정책, 위탁, 수탁 나와 있는데 이걸 어떻게 구분해서 붙여주는 이름입니까? 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 기본연구과제는 저희 자체적으로 학술지에 게재할 목적으로 만드는 과제의 형태입니다. 그리고 정책연구과제는 도나 도의회에서 정책적으로 필요한 사항을 연구하기 위해서 만들어진 과제가 정책연구과제이고요. 위탁연구는…….
</p>
<p><b>○ 최춘식 위원 </b> 됐습니다, 그거는. 그런데 전략과 정책을 혼용으로 쓰고 있는 부분도 여기 연구보고서에 보니까 있네요. 그러면 대략적으로 전략보다는 정책이 좀 더 큰 개념으로 쓰고 있는 용어죠? 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 정책이 더 큰 용어입니다. 정책 중에서…….
</p>
<p><b>○ 최춘식 위원 </b> 그러니까 전략보다 정책이 더 큰 용어잖아요? 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네, 그렇습니다.
</p>
<p><b>○ 최춘식 위원 </b> 그런데 이거는 어떻게 구분하기 곤란해서 이렇게 해 놨습니까? 괄호 치고 “정책(전략)” 같이 쓰고 있는 부분은? 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네. 정책과제 중에서 상당히 융합적인 연구가 필요한 중요한 사업 같은 경우에는 전략연구라고 그렇게 명하고요. 나머지 부분들은 일반정책과제 이렇게 구분하고 있습니다.
</p>
<p><b>○ 최춘식 위원 </b> 그러니까 전략이 좀 더 작은 개념 아니에요? 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 전략이 좀 더 큰 개념입니다. 
</p>
<p><b>○ 최춘식 위원 </b> 전략이 큰 겁니까, 정책보다? 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 전략이 크고 정책이 좀 더 작은 단위입니다. 
</p>
<p><b>○ 최춘식 위원 </b> 그렇게 되나요?
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 정책과제라는 게 정책과제 중에서 전략정책과제, 일반정책과제 2개로 나뉩니다. 그러니까 정책과제의 유형은 두 가지입니다. 전략정책과제, 일반정책과제. 그런데 전략정책과제는 좀 융합적 연구가 필요한 규모가 큰…….
</p>
<p><b>○ 최춘식 위원 </b> 전략, 정책을 같이 쓴다 그런 말씀이죠, 그때는? 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네, 그렇습니다.
</p>
<p><b>○ 최춘식 위원 </b> 전략정책과제, 유형. 알았습니다. 그건 한번 좀 보고요. 
</p>
<p style="padding-left:1.2em">  여기 지금 연구과제가 진행돼서 이미 결과물이 나온 것도 있고 또는 이 업무보고서 내용을 보게 되면 진행 중인 것도 있는데 4차 산업혁명에 국한해서 한번 질의를 드려보겠습니다. 
</p>
<p style="padding-left:1.2em">  지역에서 지난번에 저희가 4차 산업혁명에 대해서 토론회를 한 번 개최한 적이 있었어요. 그런데 개념이 참 잘 안 잡히는 게 이거더라고요, 보니까. 우리가 산업혁명을 1ㆍ2ㆍ3ㆍ4차까지 놓고 보게 되면 1차산업 같은 경우는 기계의 발명부터 기술의 혁신까지를 얘기할 테고 2차는 중화학공업으로의 전환, 3차산업은 컴퓨터부터 인터넷까지를 얘기하고, 4차산업이 이제 문제인데요. 여기 보면 인공지능, 사물인터넷까지 또 빅데이터, 모바일 쭉 해서 총체적인 부분들을 용어로 다 쓰고 있습니다. 그런데 궁금한 것은 모든 분야에서, 여기에 업무보고 내용 보게 되면, 한번 제가 제목을 열거해 보겠습니다. “4차 산업혁명 시대의 스마트시티 전략” 또 “제4차 산업혁명과 지역정책: 지역혁신 생태계를 중심으로” 해서 생태계까지도 여기에 들어가 있고 또 그다음에 “판교제로시티 플랫폼 분석”에 대한 부분 또 “4차 산업혁명과 에너지ㆍ보건 관리”까지 이렇게 쭉 아주 다양한 분야에 이 4차 산업혁명이라는 것을 접목시켜놨어요. 그렇죠? 지금 보면. 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네, 그렇습니다. 
</p>
<p><b>○ 최춘식 위원 </b> 그런데 그렇다면 이 4차 산업혁명에 대해서 어떤 결과물이 아직은 완벽하게 나와 있는 게 없는 것 같은데 맞습니까? 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 결과물이, 저희가 금년도에 한 13과제를 했는데요. 결과물이 일부분 나와 있긴 나와 있습니다. 
</p>
<p><b>○ 최춘식 위원 </b> 네, 그러면 일반적으로 연구용역에 대한 경기연구원의 연구 결과물을 보면 많은 거를 지금 우리가 받아보고 있잖아요, 저희한테 많이 보내주시잖아요.
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네.
</p>
<p><b>○ 최춘식 위원 </b> 그것을 보고 그 책자에 의해서 우리가 습득할 수 있는 지식수준 또는 그것을 우리가 보고서 이해할 수 있고 또 그걸 가지고 내가 생각할 수 있는 그런 부분에 간다는 말씀이죠? 그런데 이 4차산업 같은 경우는 그 결과물을 가지고 지금 제가 열거해 드린 이런 분야에 접목을 시켜줘야 만이 효과가 발생하는 거 아니겠습니까? 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네, 그렇습니다.
</p>
<p><b>○ 최춘식 위원 </b> 그럼 거기에 대해서 어떻게 하고 계십니까? 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 그래서 저희 내부에서도 4차 산업혁명에 관련된 개념이나 유형 자체를 명확히 실체를 파악하기 어렵기 때문에 나름대로 회의를 많이 하고 있습니다만 저희는 전략과제연구로서 4차 산업혁명에 대비한 공공기관, 유관기관들하고 같이 협력해서 과제를 추진하고 있습니다. 그래서 거기서 명확하게 전략이나 과제들을 금년 말까지 도출해서 그거 가지고 내년도에도 세부 추진전략을 짜려고 계획하고 있습니다만 지금 저희 혼자만의 생각으로 명확한 실체나 과제를 설정하는 것은 어렵기 때문에 유관기관들하고 같이 협력해서 하고 있는 실정입니다. 
</p>
<p><b>○ 최춘식 위원 </b> 그렇다면 여기에 지금 명시된 대로 환경 분야에 대한 연구가 4차 산업혁명과 같이 부합시켜서 연구가 됐습니다.
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네.
</p>
<p><b>○ 최춘식 위원 </b> 그러면 그것을 우리 도내에 있는 유관기관에도 이걸 다 보내줘서 같이 거기에 대한 일정부분 어떤 교감을 이룹니까? 그냥 책자 발간으로 끝납니까? 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 4차 산업혁명과 관련해서 담당하는 본부장이 대신 답변해도 되겠습니까? 
</p>
<p><b>○ 최춘식 위원 </b> 네, 좋습니다. 답변해 주세요. 
</p>
<p><b>○ 연구기획본부장 이정훈 </b> 연구기획본부장 이정훈입니다. 위원님 말씀이 굉장히, 지금 한국의 4차 산업혁명 개념이 실행계획의 혼란으로 아직 정립이 안 돼 있습니다. 그래서 저희 연구원이 주관해서 경기도의 경제과학진흥원과 차세대융합기술원, 일자리재단 등 10여 개 연구기관이 공동으로 계속 토론하면서 국내외 사례를 모으고 경기도에서 앞으로 어떻게 4차 산업혁명을 진행할지에 관한 경기도 나름대로의 모델을 지금 구축하고 있고요. 12월이면 보고서가 1차적으로 완성이 돼서 내년 초에 출간이 될 계획인데요. 그 개요를 잠깐 말씀드리면 기본적으로는 손에 좀 잡히기 어려운데, 크게는 빅데이터를 활용한 공장의 자율적 의사결정 그다음에 도시와 시민 삶의 어떤 인공지능이나 빅데이터 기술과의 결합. 그게 자율자동차나 에너지, 환경, 공공 헬스케어 이런 부분들이 있고요. 말씀하신 대로 지금 환경 분야는 저희 연구원하고 또 빅데이터센터하고 공동으로 미세먼지를 어떻게 실시간으로 측정해서 그걸 관리해 나갈 것인가 또 물 수질이나 가뭄을 어떻게 빅데이터를 활용해서 사전에 예측하고 관리할 것인가, 이런 분야에 대해서 관련 기관들이 모여서 연구를 하고 있고 내년 초에는 기초적인 모델이 나올 것으로 예상되고 있어서요. 저희가 그게 나오면 위원님들 모시고 보고회를 한번 갖도록 하겠습니다. 
</p>
<p><b>○ 최춘식 위원 </b> 네. 어차피 말씀 나왔으니까 한 가지만 제가 질의를 드릴게요. 지금 자율주행자동차에 대한 말씀을 해 주셨잖아요?
</p>
<p><b>○ 연구기획본부장 이정훈 </b> 네.
</p>
<p><b>○ 최춘식 위원 </b> 그럼 이것을 우리가 연구해서 그것이 될 수 있는 부분, 우리가 가능성을 충분히 가지고 있는데 여기에는 법적인 문제도 따르지 않습니까? 
</p>
<p><b>○ 연구기획본부장 이정훈 </b> 그렇습니다.
</p>
<p><b>○ 최춘식 위원 </b> 예를 들어서 자율주행자동차가 가다가 사고를 냈을 때 그땐 누구한테 이 책임을 묻습니까? 이런 것도 연구가 돼야 되지 않겠어요? 
</p>
<p><b>○ 연구기획본부장 이정훈 </b> 네, 맞습니다. 
</p>
<p><b>○ 최춘식 위원 </b> 이런 게 앞으로 우리 과제라는 거죠. 그래서 이것을 놓고 현장에 어떻게 접목할 것인가에 대해서, 지금 연구의 결과물로 끝날 것이 아니라 이거는 토의와 토론이 충분히 이루어져야 된다, 좀 더 심도 있게. 이런 것을 좀 말씀드리는데 생각이 어떠십니까? 
</p>
<p><b>○ 연구기획본부장 이정훈 </b> 네, 아주 정말 옳으신 말씀이고요. 4차 산업혁명 연구는 그냥 탁상의 페이퍼로 끝나서는 절대 그게 실행될 수 없고요. 그래서 저희가 내년도 경기도청의 연구예산 6억을 지금 현재 도의회에 제출해 놓은 상태입니다. 그래서 2억 정도는 저희 연구원이 경기도 시군에서, 지금 다 각각 고민하고 있는 4차 산업혁명과 스마트시티에 관련된 시도들이 있습니다. 그것들을 다 모아서 워킹그룹을 만들어서 경제과학진흥원하고 같이 운영을 하고요. 내년 하반기에는 워싱턴에서 글로벌 시티 팀 챌린지라는 4차 산업혁명 관련된 세계의 모든 도시와 기업과 전문가들이 모이는 엑스포가 있습니다. 거기에 경기도의 각 시군과 기관들이 공동으로 출품하는 그런 계획을 지금 진행하고 있습니다. 말씀하신 대로 현장의 연구를 추진하는 것이 저희들의 목표입니다. 
</p>
<p><b>○ 최춘식 위원 </b> 네, 알겠습니다. 앞으로 연구가 이루어지는 모든 사항들이 현장과 공유할 수 있는 부분을 우리 연구원에서 찾아 주셔야 될 것 같습니다. 
</p>
<p><b>○ 연구기획본부장 이정훈 </b> 네, 그렇게 하겠습니다. 
</p>
<p><b>○ 최춘식 위원 </b> 그렇게 생각하십니까? 
</p>
<p><b>○ 연구기획본부장 이정훈 </b> 네. 
</p>
<p><b>○ 최춘식 위원 </b> 이상입니다. 
</p>
<p><b>○ 위원장대리 나득수 </b> 최춘식 위원님 수고하셨습니다. 다음 김영환 위원님 질의해 주십시오. 
</p>
<p><b>○ 김영환 위원 </b> 고양시 출신 김영환입니다. 먼저 부원장님 이하 우리 직원 여러분, 감사 준비하시느라고 너무나 고생하셨고요. 국정과제에 관련해서 제가 질문을 좀 드리겠습니다. 부원장님, 혹시 국정과제백서 받아 보셨어요? 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네, 받았습니다. 
</p>
<p><b>○ 김영환 위원 </b> 몇 개의 국정과제가 있죠? 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 100대 국정과제가 있습니다.
</p>
<p><b>○ 김영환 위원 </b> 세부실천과제가 몇 개 있죠? 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 400…….
</p>
<p><b>○ 김영환 위원 </b> 487. 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네, 487.
</p>
<p><b>○ 김영환 위원 </b> 487개 세부과제 있습니다. 존경하는 임채호 위원님께서 도시재생과 그다음에 우리 최춘식 위원님께서 4차 산업혁명 잠깐 언급하셨는데 새 정부의 국정철학과 신념이 사실은 대한민국의 전체적인 정책의 틀을 바꾸었어요. 그러니까 그 이전의 정책과 그 이후의 정책은 완전히 다릅니다. 그런데 100대 국정과제와 487개 세부 실천과제가 연도별, 연차별 재정계획을 다 포함하고 있고요. 구체적으로 487개의 실천과제는 또 세부적인 과제들로 관리되고 있어요. 그런데 제가 경기연구원 이렇게 보면 과연 이 전체적인 큰 변화에 경기도가 무엇을 대응해야 되는지, 어떻게 새 정부의 큰 흐름에 우리 지방정부가 할 수 있는 것들은 어떤 것들이 있는지. 제가 각 실별로 연구들 쭉 봤는데 전체적인 기획은 하나도 없어요, 이런 부분에 대해서. 파편적으로 도시재생과, 그러니까 민감한 사안들, 도지사가 관심 있는 사안만 딱 들어와 있고 문재인 정부의 큰 변화를 이루는 내용들이 경기연구원에 전혀 준비가 안 돼 있는 것 같아요. 어떻게 준비하고 계세요? 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 저희가 국정과제에 관련돼서는 지금 위원님 말씀하신 대로 개별적으로 접근하고 있는 건 맞습니다. 
</p>
<p><b>○ 김영환 위원 </b> 그러니까 예를 들면, 제가 경제2분과 전문위원으로 있었지만 그쪽에서도 국토부의 국정과제가 거의 30개에 이르러요. 세부실천과제가 거의 150개에 이릅니다. 중기부 승격한 거, 그 속에도 국정과제가 무수히 포함돼 있고 우리 경기도 중소기업들이, 소상공인들이 어떻게 생존하고 어떻게 창업ㆍ벤처 국가로 갈 것인지에 대한 큰 그림들이 다 들어 있어요. 지방정부가 어떻게 준비해야 될지. 이를테면 단적인 예로 하나 실천과제 예를 들어볼게요. 지금 가계부채하고 그다음에 중소기업들의 부채, 이 심각한 부채를 해소시켜 주기 위해서 국민행복기금에서 지금 채권소각 했지요? 국민들에 대해서 1,000만 원 이하. 그렇지요?
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네.
</p>
<p><b>○ 김영환 위원 </b> 우리 경기도에 금융기관 있지요?
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네.
</p>
<p><b>○ 김영환 위원 </b> 경기신용보증재단이 있습니다. 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네.
</p>
<p><b>○ 김영환 위원 </b> 지금 중진공은 5년 소멸시효 넘어가는 것들을 20년, 30년 계속 소멸시효 자동연장시키고 있는데 그걸 10년으로 줄이기로 했습니다. 그러니까 중소기업들이 실패를 했을 때 다시 시장진출을 위한 기회를 만들어 주기 위해서 10년 이상 된 장기연체 채권들에 대해서 연장시키지 않고 기회를 주고 원금과 이자에 대한 감면조치를 하는 것으로 세부실천과제로 계획돼 있어요. 그런데 경기신용보증재단은 과연 어떻게 해야 될까?
</p>
<p style="padding-left:1.2em">  그러니까 우리 각 기관들, 자잘하게 우리 경기도 지방정부가 해야 될 과제들이 무수히 산더미처럼 지금 쌓여 있는 겁니다. 제가 단적인 하나의 실천과제만 지금 말씀드린 거예요. 그런데 이것들이 기획이 돼야 될 것 같아요. 경기도에서 뭘 준비하지? 이를테면 도시재생도 지금 중앙정부 일반재정에서 2조, 그렇지요? 기금에서 5조 그다음에 다른 기관에서 3조 이렇게 됩니다. 국토부. 그러면 일반재정에서 1,500억 도시재생사업이 8,000억까지 늘어나고요. 그다음에 지방정부가 준비해야 될 게 또 있어요, 한 5,000억 정도. 그렇게 계획이 돼 있어요. 그러면 5,000억 정도의 지방정부가 경기도, 서울, 인천 다 있을 텐데 재정은 어떻게 준비하지? 당장 당면과제 아니겠어요, 재정분석이? 그렇지 않겠습니까? 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네.
</p>
<p><b>○ 김영환 위원 </b> 경기도에서 지금 세 군데인가 두 군데인가 이렇게 정리된 걸로 알고 있는데 이걸로는 안 되지요, 그것만으로는. 주먹구구식으로 지금 움직이고 있거든요, 파편적으로. 그래서 종합적으로 경기도가 움직여야 될 과제들을 세팅하고 경기도도 세부 실천과제로서 어떻게 준비를 해야 되고 각 기관별, 각 주무부서 다 준비를 해야 돼요. 그래야 이게 호흡이 맞아서 새 정부가 이 공약들을 실천하고 여하튼 국민의 동의를 받아서 정당성을 가지고 출범한 정부이기 때문에 그거에 대한 경기연구원의 총체적인 기획, 준비 이런 것들이 필요하다 이런 말씀을 드리고 싶은데 어떠세요? 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 그 문제에 대해서도 저희가 지난주에도 기조실하고 회의를 했습니다만 똑같은 얘기를 저희한테 의뢰를 했었습니다. 그래서 내년도에는 종합적인 국정과제를 포함해서 여러 가지 문제들을 서로 기획하고 우리가 대응할 수 있는 방안을 어떻게 할 것인가에 대해서…….
</p>
<p><b>○ 김영환 위원 </b> 내년도요? 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 내년도 초까지는 그런 걸 어느 정도 기획을 해야 되지 않을까 생각하고 있습니다. 
</p>
<p><b>○ 김영환 위원 </b> 제가 보기에는 각 박사님들이 지금 국정백서 있잖아요, 국정과제백서 딱 끼고 있어야 돼요. 자기 분야에서 해당되는 것들 딱 끼고 있어야 됩니다. 그래서 경기도가 준비해야 될 것들 딱 준비를 하고 있어야 돼요. 기획하고 어떤 정책과제들이 있는지부터 어떤 기획으로 이것들을 보조를 맞출지 이 준비를 하고 있어야 된다니까요.
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네, 그렇게 하도록 하겠습니다. 
</p>
<p><b>○ 김영환 위원 </b> 국정과제백서들이 다 있는지 모르겠어요. 잠깐만 제가 조금 시간이 3분밖에 안 남아서 전체적으로 질의하고 그다음에 이정훈 본부장님이 말씀하시든 부원장님이 말씀하시든 말씀해 주세요.
</p>
<p style="padding-left:1.2em">  그리고 남 지사께서 청년정책, 청년 시리즈 뭐 3년간 연구를 했다고 자꾸 주장을 하세요. 그래서 제가 경기연구원 실적을 보니까 4건밖에 없어요, 청년관련 대상 연구실적이. 그것도 청년 시리즈 관련된 게 아니고요, 청년고용 부진. 딱 연결되면 이거 하나. 그다음에 공유지 활용 청년층 임대주택, 경기도 청년층 공공임대주택 보증금 지원방안 연구, 경기도 청년구직지원금 도입을 위한 기초연금. 청년구직지원금은 연정사업이기 때문에 했을 거고요. 연금, 통장, 복지포인트 이거 관련해서는 전혀 연구원이 없어요. 도지사께서 거짓말하신 것 같아, 방송에 나와서. 연구원 이거 한 거 없지요?
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 저희 과제로서는 한 게 없습니다. 
</p>
<p><b>○ 김영환 위원 </b> 네, 제가 확인을 했고요. 그다음에 공공투자관리센터 제가 질의를 마지막으로 드릴게요. 일단 저의 고민 하나가 여기에 있어요. 뭐냐 하면 우리 경기연구원의 모법이 뭐지요?
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 지방자치단체 출연연구원의 설립에 관한 법률입니다.
</p>
<p><b>○ 김영환 위원 </b> 거기 12조 어떻게 돼 있지요? 12조. 제가 규정집이 없어져 가지고, 12조.
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 자율적…….
</p>
<p><b>○ 김영환 위원 </b> 자율적 아니에요. 자율성은 있는데 또 하나 더 있습니다. 원장님, 모법 12조는 굉장히 중요한 거예요.
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> “지방연구원은 연구 및 경영에서 독립성과 자율성이 보장된다.” 이렇게 돼 있습니다. 
</p>
<p><b>○ 김영환 위원 </b> 그렇지요. 독립성과 자율성입니다. 독립성. 제가 공공투자관리센터 이거 준비를 하면서, 존경하는 양근서 위원님께서도 많은 관심이 있는 거고요. 우리 재정을 쓰면서 정말 객관적이고 효율적으로 써야 된다는 차원에서 제정안이 나온 건데 아무래도 할 수 있는 터가 경기연구원밖에 없어요, 이걸 수행할 수 있는 터가. 도지사가 다른 전문기관에 위탁할 수도 있지만 공공기관을 상정했을 때 우리 경기연구원밖에 없다. 그런데 경기연구원은 어떻게 준비를 하세요?
</p>
<p style="padding-left:1.2em">  일단 첫 번째, 독립성이라는 측면에서 이게 정치적으로 흔들릴 가능성도 있고 그간의 사태를 보더라도 경기연구원은 충분히 그럴 소지도 있다. 그런데 독립성을 어떻게 보장하면서 이 재정분석의 객관성을 이룰까? 이게 첫 번째 질문.
</p>
<p style="padding-left:1.2em">  두 번째, 조직적으로 지금 어떻게 대응을 하고 있는지. 관련 분야, 수많은 분야들이 필요한데 첫 번째, 재정분석할 수 있는 경험 있는 유능한 분이 필요하고요. 두 번째, 경제 쪽을 전공한 이런 박사님들도 필요하고 또 재정투자 관련해서는 여러 다양한 사회수요들이 올라올 수도 있거든요. 이런 부분들의 조직적인 준비들을 또 어떻게 할 거냐? 경기연구원은 그러면 이거를 할 용의는 있으세요? 첫 번째 질문부터 해서 두 번째, 세 번째 답변을 부탁드립니다. 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네, 저희들이 할 용의는 충분히 있습니다. 그런데 아직 공식적으로 저희한테 공문이 안 왔기 때문에 구체적으로 공식적인 말씀은 드릴 수가 없겠습니다만 내부적으로는 저희가 독립성 문제에 대해서 위원님이 말씀하신 대로 상당히 중요하다고 생각해서 우선 운영위원회를 둬서 거기서 객관적으로 검증할 수 있는, 독립적으로 객관적으로 검증할 수 있는 그런 상태를 만들어야 된다 이런 얘기가 많이 나오고 있습니다. 그걸 검토하고요. 그다음에 예산도 분리해서 가능하면 특별회계나 분리회계를 해 가지고 예산을 분리하는 그런 방향으로 생각하고 있습니다.
</p>
<p style="padding-left:1.2em">  또 한 가지는 조직적으로는 외부의 전문가들, 지금 말씀하신 재정분야, 경제분야, 사회수요 여러 가지 분야들의 분들을 한 반 이상은 충원을 해야 될 필요가 있다고 생각합니다. 그래서 독립적으로 운영할 수 있도록 원장 직속으로 조직을 생각하고 있습니다, 내부적으로는.
</p>
<p><b>○ 김영환 위원 </b> 이제 답변 끝나고 이정훈 박사님 마지막, 국정과제 관련해서 답변하십시오. 
</p>
<p><b>○ 연구기획본부장 이정훈 </b> 김영환 위원님 말씀, 굉장히 전적으로 저희들이 잘 새겨서 해야 되는데 좀 미흡한 점이 있는 것 같은데요. 5월에 국정과제 발표된 이후에 저희가 연구원 박사별로 487개 세부과제 중에서 경기도에 관련된 것들을 다 매칭을 했습니다. 그래서 한 100여 개 정도의 세부과제를 뽑아서 한 박사님당 대체로 한 3개~5개 정도의 기초검토를 했고요. 아직 저희가 깊이 못 들어간 것은 계획이 구체적으로 안 나온 것도 있고 지금 일자리 로드맵 같은 건 이제 나왔고요. 그래서 계획이 나온 것들을 추가적으로 검토를 하고 그다음에 나머지에 대해서 대기를 하면서 이 부분들에 대해서는, 지금 현재 저희가 업무보고에 나온 거는 내년도 연구량의 한 20% 정도만 산정을 해 놨고요. 나머지 80%는 이런 국정과제를 중심으로 해서 또 민선7기에 새롭게 할 과제들을 발굴해서 추가적으로 도와 의회하고 협의해서 진행할 것으로 그렇게 계획을 하고 있습니다. 
</p>
<p><b>○ 김영환 위원 </b> 한마디만 더 할게요. 제가 자료를 드릴 수도 없고, 대외비로 돼 있어서. 여하튼 487개 세부과제가 구체적인 로드맵으로 또 실천과제가 깊숙이 짜여져 있어요. 그래서 저는 우리 박사님들이 해당 부처 공무원들하고도 정말 밀착되게, 이 의미가 뭔지, 어떻게 추진하려고 하는지, 그렇게 해서 좀 정보들을 계속 빼 가지고 와야 된다고 봅니다. 자료는 있습니다. 
</p>
<p><b>○ 연구기획본부장 이정훈 </b> 네.
</p>
<p><b>○ 김영환 위원 </b> 수만 페이지에 걸쳐 어떻게 처리를 할지에 대한 세부자료들이 있거든요. 그거를 파악하시는 게 저는 중요하다고 봐요. 그렇게 주문 좀 더 드리겠습니다.
</p>
<p><b>○ 연구기획본부장 이정훈 </b> 네, 그 부분에 대해서는 노력을 하겠고 위원님께 많이 협조를 부탁드리겠습니다. 
</p>
<p><b>○ 김영환 위원 </b> 네, 이상입니다. 
</p>
<p style="padding-left:2.4em">    (나득수 위원장대리, 이재준 위원장과 사회교대)
</p>
<p><b>○ 위원장 이재준 </b> 김영환 위원 수고하셨습니다. 다음 나득수 위원님 질의해 주시기 바랍니다.
</p>
<p><b>○ 나득수 위원 </b> 부천 출신 나득수입니다. 행정사무감사 준비하시느라고 노고가 많으십니다. 먼저 자료요청부터 드리겠습니다. 우리 경기연구원에 최근 5년 동안 경기도 지방재정 개선에 관한 어떤 연구목록이 있으면 목록을 주시기 바랍니다. 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네, 알겠습니다. 
</p>
<p><b>○ 나득수 위원 </b> 일단 목록부터 주십시오. 초과근무수당 부당지급에 대해서 여쭤보겠습니다. 공공기관은 초과근무수당을 근로기준법에 따라서 지급해야 한다는 것은 일반적인 상식이지요? 일반법이죠?
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네, 그렇습니다. 
</p>
<p><b>○ 나득수 위원 </b> 그런데 우리 경기연구원에서는 공무원수당 지급방식을 택했지요. 그렇지요?
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네, 그렇습니다. 
</p>
<p><b>○ 나득수 위원 </b> 그래서 그게 한 2008년부터 하는 걸로 저는 알고 있습니다. 맞습니까? 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네, 그렇습니다. 
</p>
<p><b>○ 나득수 위원 </b> 그래서 경기도에서 그걸 체킹을 하고, 임금채권의 소멸시효가 3년이지요?
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네, 그렇습니다.
</p>
<p><b>○ 나득수 위원 </b> 그래서 3년분 미지급분에 대해서 소급 지급하라고 그랬어요.
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네, 그렇습니다. 
</p>
<p><b>○ 나득수 위원 </b> 그러면 지금 3년분 미지급 임금채권이라면 기준일이 언제 정도가 될까요? 2013년, 14년? 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 2013년 12월 23일부터입니다.
</p>
<p><b>○ 나득수 위원 </b> 13년 12월…….
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 12월 23일부터인가 24일부터입니다.
</p>
<p><b>○ 나득수 위원 </b> 2013년 12월 23일부터요. 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 24일부터입니다.
</p>
<p><b>○ 나득수 위원 </b> 24일부터. 그 초과근무수당에 대해서 이렇게 우리 경기연구원이 경기도 싱크탱크인데 법을 모르고 지급했다는 게 저는 이해가 안 갑니다. 그렇지요?
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네.
</p>
<p><b>○ 나득수 위원 </b> 원장님께서는 어떻게 생각하세요?
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 그 문제에 대해서도 저희들이 인식을 못 했다는 점 충분히 잘못했다고 생각이 되고, 다른 공공기관한테 물어보니까 다른 공공기관도 저희와 비슷한 그런 식으로 통상임금을…….
</p>
<p><b>○ 나득수 위원 </b> 보고에 보면, 연구원에서 제출한 자료에 보면 5억이라고 돼 있어요. 그렇지요?
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네, 맞습니다. 
</p>
<p><b>○ 나득수 위원 </b> 그런데 우리 경기도에서는 5억 4,000 정도로 보고를 받았는데 이 금액 차이가 어떤 건가요? 왜 다르지요?
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 저희가 실제로 지급하는 액수는 5억 200으로 지금 계산을 했습니다. 
</p>
<p><b>○ 나득수 위원 </b> 퇴직자들 분에 대해서도 다 지급하신 거예요?
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 퇴직자는 아직, 내년도 1월 달에, 나머지 한 70명 정도는 1월 달에 1억 2,800만 원 정도를 지급할 예정에 있습니다.
</p>
<p><b>○ 나득수 위원 </b> 그렇다면 수당지급방법을 통상임금기준으로 한다면 초과근무수당이 대폭 오를 건데 어떻게 대처하실 겁니까? 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 저희가 5억 200 중에서 3억 8,800을 11월 달에 지불했습니다. 현재 재직자랑 일부 퇴직자를 중심으로 한 100명 정도 3억 8,800을 지급했고요. 나머지 70명에 대한 퇴직자들 1억 2,000만 원 정도는 내년 1월 달에 지급할 예정에 있습니다. 
</p>
<p><b>○ 나득수 위원 </b> 아니, 그러니까 제가 듣고 싶은 말씀은, 초과근무시간을 제한한다든가 그런 조치는 취하지 않으셨나요? 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 아, 네. 초과근무시간을 원래 석사연구원은 45시간인데 35시간으로 제한을 하였고 또한 결재시스템을 변경하였습니다. 
</p>
<p><b>○ 나득수 위원 </b> 그러니까 초과근무시간 제한은 법적인 법규 위반은 아니지요? 그렇지요?
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네, 법규 위반 아닙니다. 
</p>
<p><b>○ 나득수 위원 </b> ‘진즉 그렇게 초과근무시간을 제한했더라면 이런 현상이 발생하지 않았을 건데.’ 하는 그런 생각을 해 봅니다. 아무쪼록 행정업무를 추진하면서 그냥 전에 해 왔던 관행, 그걸 관습적으로 따라왔던 것 같아요.
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네, 그렇습니다. 
</p>
<p><b>○ 나득수 위원 </b> 우리 경기도 싱크탱크인 경기연구원에서 그렇게 했다는 게 참 참담하고요. 앞으로는 정말 법 규정을 잘 검토해 주시기 바랍니다.
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네, 알겠습니다. 
</p>
<p><b>○ 나득수 위원 </b> 다음은 우리 행정사무감사 요구자료에 315쪽을 보시면 위원회 횟수가 있어요. 위원회가 보니까 4개 위원회가 있지요, 4개 위원회가. 그렇지요?
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네.
</p>
<p><b>○ 나득수 위원 </b> 그런데 3개 위원회는 개최실적이 없어요, 개최실적이. 그렇지요?
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네.
</p>
<p><b>○ 나득수 위원 </b> 그러니까 공유시장경제위원회만 개최했어요. 그게 특별한 이유가 있어요?
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 저희가 경제일자리위원회랑 글로벌위원회, 사회정책위원회가 2015년도, 16년도에는 정책개발하는 데 외부 전문가들이나 이런 사람들의 도움을 많이 받았습니다. 그런데 2017년도 돼서는 이 3개 위원회에서 위원장뿐만 아니라 필요성에 대해서 그렇게 생각이 안 된 것 같습니다. 2015년, 16년도에.
</p>
<p><b>○ 나득수 위원 </b> 그래요. 그런데 올해 공유시장경제위원회를 새로 구성했어요. 그렇지요?
