<p><b>○ 경기연구원장직무대행 김군수 </b> 네.
</p>
<p><b>○ 나득수 위원 </b> 공유시장경제위원회의 운영목적을 보니까 “발전국가 이후에 성장, 고용, 복지, 인구, 지방 문제를 극복하기 위한 한국사회의 새로운 국가발전모델 형성 및 지방발전 전략 수립”이라는 목적으로 설립이 됐어요.
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네.
</p>
<p><b>○ 나득수 위원 </b> 그렇다면 이 위원회가 모든 분야를 다 총괄해서 다루려고 하는 것이 아닌가 그렇게 생각되는데 그렇지는 않습니까? 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네, 그렇지는 않습니다. 공유시장경제에 대한 이해나 개념이나 이런 게 아직 명확히 안 됐기 때문에 그것부터 정확한 명…….
</p>
<p><b>○ 나득수 위원 </b> 그런데 기존의 위원회하고 많은 내용이 겹치지는 않나요?
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네, 겹치지는 않습니다. 연구주제 말씀하시는 거면 그건 겹치지 않고 주제에 대해서는 공유시장경제에 대해서 초점을 맞추고 했다고 저는 알고 있습니다. 
</p>
<p><b>○ 나득수 위원 </b> 네. 그렇다면 우리 4개 위원회를 운영하면서 연구과제를 선정했다든가 아니면 도정에 반영했다든가 하는 사례는 있나요?
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 그거는 확인해 봐야 알겠습니다. 지금 제가 정확히 답변을…….
</p>
<p><b>○ 나득수 위원 </b> 파악 못 하고 계셨어요?
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네.
</p>
<p><b>○ 나득수 위원 </b> 보통 운영위원회가 식당 등에서 개최됐다고 그래요, 주제발표를 듣고. 그 주제에 대해서 위원들의 의견을 듣는 방식으로 진행됐다는데 그 토론 내용을 가지고 어떤 생산적인 결과물을 내놓지 못한다면 그 위원회가 단순히 그 위원들의, 교수님이나 전문가들의 사교모임 정도 되지 않을까 싶은데 어떻게 생각하세요?
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 위원회에 저도 회의를 한두 번 가봤고 주위에서 얘기를 듣기로는 상당히 생산적으로 운영이 됐다는 얘기를 많이 했습니다. 그래서 정책에 관련된 내용을 좀 더 검증하고 앞으로 어떤 일을 할 것인가에 대해서 서로 의견을 교환하는 그런, 기존의 양식하고는 좀 다르게 하려고 노력을 했다고 얘기는 들었습니다. 
</p>
<p><b>○ 나득수 위원 </b> 그러면 원장님도 가보셨어요? 참석을 하시는 건가요, 매 위원회에? 그렇지는 않지요?
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 아니요, 참석은 안 하고 한 번 정도 참석한 적 있습니다. 
</p>
<p><b>○ 나득수 위원 </b> 그런데 소문이 그렇게 들려요.
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 2015년도, 16년도에…….
</p>
<p><b>○ 나득수 위원 </b> 위원회가 작년에만 3개 위원회에서 한 1,600만 원 썼어요, 예산을. 그렇지요?
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네.
</p>
<p><b>○ 나득수 위원 </b> 아무쪼록 운영위원회가 존재의 의미를 발견할 수 있도록 생산적인 어떤 논의를 해 주시면 고맙겠습니다. 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네, 알겠습니다. 
</p>
<p><b>○ 나득수 위원 </b> 다음으로 짤막하게 또 질문드리겠습니다. 보면 경기도 자체감사에서 초빙연구원이죠, 초빙연구원. 채용 부적정 지적을 받으셨어요. 해마다, 감사 받을 때마다 받으시는 것 같아요, 그렇죠? 근본적인 이유는 뭐예요? 규정을 위반하는 근본적인 이유. 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 초빙연구원을 뽑을 때 이번에 감사 지적받은 게 여러 가지 있습니다만 그 첫 번째가 정확히 직급을 표시하지 않은 점 그다음에 역할을 정확히, 그러니까 모집분야를 정확히 표시하지 않은 점 이런 거에 대해서는 저희 내부적으로 좀 융통성 있게 운영하고 싶었습니다. 그래서 지원한 사람에 따라서 경력이 많으면 연구위원…….
</p>
<p><b>○ 나득수 위원 </b> 그런데 해마다, 그러니까 받을 때마다, 2년마다 받죠? 2년마다 감사를 받잖아요, 경기도 감사를. 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네.
</p>
<p><b>○ 나득수 위원 </b> 그런데 받을 때마다 지금 지적사항으로 나오고 있어요. 
</p>
<p style="padding-left:1.2em">  네, 알겠습니다. 우리 초빙연구원, 비상임연구원 등 운영규칙을 보면, 그렇죠? 운영규칙 별표1을 보면 선임연구위원 가급ㆍ나급, 연구위원 가급ㆍ나급 이런 기준이 있어요, 위촉 자격기준이 있어요. 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네, 그렇습니다. 
</p>
<p><b>○ 나득수 위원 </b> 거기에 보면 전ㆍ현직 국회의원 그다음에 전ㆍ현직 광역의회의원 그다음에 장성으로 3년 이상 근무한 자 이런 분들 그다음에 대령급 군인 30년 이상 근무자 그다음에 뭐 여러 가지 있어요. 전ㆍ현직 기초의회의원인 자 이렇게 돼 있어요. 그런데 연구원이라고 하면 리서치 능력이라든가 연구 능력이 있어야 되는데 그런 능력이 없으신 분들을 채용한다는 것은 어떤 목적에서 채용하는 거예요? 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 저희가 기본적으로는 박사 소지자 또는 석사 후 경력 있는 사람을 기본으로 하는데 그 외에 또 여러 가지 실무경험이 많은 분들을 포함시켰으면 좋겠다는 생각에 아마 그걸 집어넣은 것 같습니다. 
</p>
<p><b>○ 나득수 위원 </b> 이 규정이 적정하다고 보십니까, 원장님께서는? 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 저 개인적으로는 적정하지 않다고 생각합니다. 
</p>
<p><b>○ 나득수 위원 </b> 그렇죠? 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네.
</p>
<p><b>○ 나득수 위원 </b> 저 또한 마찬가지입니다. 그리고 지금 현직 의원을 또 채용할 수 있다고 그래요. 현직 의원은 자격이 있나요? 그 비상임연구원으로 채용한다는 거죠? 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네, 비상임연구원은 모든 문호를 개방하기 때문에 괜찮습니다.
</p>
<p><b>○ 나득수 위원 </b> 네, 비상임위원은 가능하죠. 이 규정을 잘 검토하셔서 개선방안을 내 주십시오. 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네, 알겠습니다. 
</p>
<p><b>○ 나득수 위원 </b> 이상입니다. 
</p>
<p><b>○ 위원장 이재준 </b> 나득수 위원님 수고하셨습니다. 
</p>
<p style="padding-left:1.2em">  본질의가 이제 거의 끝나가는데 제가 마지막인 것 같습니다. 저도 한 10분 질의를 드리겠습니다. 광역버스에 대해서 질문할 건데 직무대행께서 답변하기가 곤란하시면 담당…….
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 담당자한테 요청하겠습니다. 
</p>
<p><b>○ 위원장 이재준 </b> 담당자께서 나와서 답변 부탁드리겠습니다. 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네, 감사합니다. 
</p>
<p><b>○ 휴먼교통연구실장 송제룡 </b> 저는 휴먼교통연구실의 실장을 맡고 있는 송제룡입니다. 
</p>
<p><b>○ 위원장 이재준 </b> 요새 버스 때문에 설왕설래하고 말들이 많아요. 첫 번째가 버스 거리비례제를 했고 그다음에 2층버스 도입을 했고 그다음에 입석금지조치를 취하면서 광역버스 확대정책을 취했고 버스 준공영제, 그러면서 또 CNG버스 도입, 그러고 전기차 도입까지 이렇게 갔습니다, 4년 동안. 그런데 이 모든 초점들이 전부 광역버스에 해당되는 이유는 뭔가요? 
</p>
<p><b>○ 휴먼교통연구실장 송제룡 </b> 광역버스에 해당된 이유에 대해서 말씀드리겠습니다. 일단 시내버스라고 하면 인ㆍ면허권이 시장ㆍ군수에게 있습니다. 그리고 시장ㆍ군수가 인ㆍ면허와 관련된 시내버스에 대해서 전체적으로 관여를 하고 있는데 2014년도에 좌석제를 시행하면서 차내 혼잡도 문제라든지 여러 가지 광역버스에 대한 문제가 언론에 집중이 되었다고 보고 있고요. 경기도에서는 시내버스 중에서도 광역버스에 대해서는 시군과 경기도가 협의해서 관여하다 보니까 광역버스 중심으로 개선방안이라든지 운전자 처우개선이라든지 서비스문제라든지 이런 것들이 경기도 차원에서 필요하다라고 판단했습니다. 
</p>
<p><b>○ 위원장 이재준 </b> 그렇진 않죠. 지금 광역버스도 인허가권이 기초단체에 있습니다, 우리 도가 있는 게 아니고요. 
</p>
<p><b>○ 휴먼교통연구실장 송제룡 </b> 네, 맞습니다. 
</p>
<p><b>○ 위원장 이재준 </b> 그러니까 우리가 영향력을 미칠 수가 없고 사실 우리는 협의부서지 우리가 인허가권을 내줄 수가 없고, 또 뭐가 있냐면 중간에 다른 시군을 경유하는데 그거에 대해서 경유하는 그 지역은 발언권이 없고 인ㆍ면허권을 가진 데만 인허가를 해 줄 수 있게끔 되어 있어요. 그래서 불합리한 제도임에도 불구하고 계속적으로 광역버스를 거론하는데 그 본질은 처음부터 끝까지가 다 광역버스에 얼마를 지원해 줄 것만 고민을 하고 있다라는 거예요. 일례를 들면 거리비례제도 마찬가지였었고 입석금지 때, 입석금지 때 아시죠? 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네.
</p>
<p><b>○ 위원장 이재준 </b> 그래서 20%를, 그래서 400원을 인상해 주죠. 그런데 입석금지가 지금 안 되어 있고 그때 당시 증차하기로 했던 166대의 증차가 하나도 안 됐어요. 증차했다라고 얘기하는 것들이 다 어디서 왔냐면 판교TB, 하남 그다음에 김포한강신도시 이 세 군데에 80대 이상이 증차가 된다고요. 그러면 신규택지기 때문에 증차가 된 것이지 입석금지를 하기 위해서 166대가 증차 안 됐고 그렇다면 그 166대를 증차한다고 해서 360억이라는 요금을 인상한 거에 대해서는 지금 당장 내놔야 되는 거예요. 그런 보고서들이 경기연구원에서 나간다라는 겁니다. 거기에 대해서 답변 좀 해 줘 보시죠. 
</p>
<p><b>○ 휴먼교통연구실장 송제룡 </b> 지금 위원장님께서 좋은 질문을 해 주셨다고 생각이 들고요. 2014년도에 좌석제를 시행하면서 입석에 대한 금지가 이루어졌고요. 그에 따라서 증차를 하면서 버스요금을 2015년도에 인상을 할 때 증차요인이 있었다고 저는 보고 있고요. 증차와 관련된 연구는 사실 우리 연구원에서 수행은 하지 않았고요. 제가 알기로는 한국종합경제연구원에서 2014년도에 연구를 수행한 걸 가지고 2015년도 요금조정에 활용된 것으로 알고 있고요. 166대에 대해서 증차가 이루어지지 않았다고 말씀하셨는데…….
</p>
<p><b>○ 위원장 이재준 </b> 자, 잠깐만요. 그래서 그런 과정을 거쳐서 거기에도 결국은 경기연구원이 연구한 서비스 평가에 대한 연구 문건이 다 영향을 미칩니다. 그래서 결국은 뭐가 있냐면 준공영제로 가는데, 준공영제 두 번째 단락에 보면 “장기적인 마스터플랜과 철저한 준비 없이 성급히 준공영제를 시행할 경우 효과 대비 막대한 재정부담과 노사정 간 갈등만 초래할 것이다.”라고 되어 있는데, 이게 서론에 쓰여 있는 거예요. 이거에 대한 대비책이 하나도 없이 준공영제를 지금 시행하려고 동의안이 올라온 거예요. 그럼 이거에 대한 보완대책, 문제점을 이렇게 지적했으면 보완대책은 세웠을 거 아닙니까? 보완대책은 뭐죠? 경기연구원에서 제시한 보완대책. 
</p>
<p><b>○ 휴먼교통연구실장 송제룡 </b> 위원장님 말씀하신 내용을 보면 저희가 2015년도하고 16년도에 경기도 버스체계개편 추진방안 연구용역을 수행했습니다. 이때 그 수행한 내용을 보면 2014년도에 경영ㆍ서비스 평가 재원 분석한 것을 토대로 해서 2015년도에 준공영제를 시행했을 때 경기도가 소요되는 예산에 대해서 저희가 분석했고요. 그때 원가에 대한 투명성이라든지 앞으로 준공영제를 도입했을 때 소요되는 재원에 대해서 2015년도 기준으로 해서 분석한 것으로 저희는 알고 있습니다. 
</p>
<p><b>○ 위원장 이재준 </b> 아니, 그 문제가 아니라 이 문제점을 지적했잖아요. 쭉 여러 가지 문제점이 있어요. 운전자 처우개선 등 노선 면허권 사유화, 원가 표준의 객관성ㆍ투명성 확보 미비, 여러 가지 문제점이 있는데 그중에 제일 큰 문제점이 뭐냐면 철저한 준비 없이 성급히 시행할 경우에 막대한 재정적 손실과 그다음에 노사정 간의 갈등을 유발할 것이다라고 했으면 그거에 대한 대비책이 여기에 들어 있어야 되는 거 아니냐는 거예요. 그 대비책이 뭐냐는 거죠, 대비책이. 
</p>
<p><b>○ 휴먼교통연구실장 송제룡 </b> 저희가 2015년도에 연구를 수행하고 그 이후에 대비책에 대한 연구는 하지 않았지만…….
</p>
<p><b>○ 위원장 이재준 </b> 잠깐만요, 그러면 됐고요. 그래서 예산이 얼마 들어가냐면 처음에 서울시하고 인천시를 비교했어요. 그래서 서울시는 도입 전에 816억 했던 것이 도입하고 나서 2,538억입니다. 그래서 딱 3배가 올라요. 인천시 같은 경우는 227억에서 718억 해서 3.2배가 늡니다. 이렇게 재정적으로 막대한 예산들이 들어가는데 이거에 대한 어떤 대비책도 없이, 경기도에는 어떻게 보고를 했는지 몰라도 십몇 %밖에 증가를 안 한다고 얘기합니다. 경기도에서 보도자료 내신 거 보셨죠? 
</p>
<p><b>○ 휴먼교통연구실장 송제룡 </b> 네.
</p>
<p><b>○ 위원장 이재준 </b> 20%가 안 되게끔 증가하기 때문에 재정적으로 문제없다 이렇게 얘기합니다. 똑같은 연구논문을, 경기연구원에서 써준 논문을 보는데 어떻게 거기서는 이십몇 %밖에 안 됐다고 그래요? 이게 300%가 넘는 소요경비가 증액했는데. 그러면 연구원에서, 잠깐만요. 직무대행님, 잠깐 발언대로 나와 보십시오. 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네.
</p>
<p><b>○ 위원장 이재준 </b> 그렇다면 반박자료를 내야 될 거 아닙니까? 그건 팩트가 아니다라고 얘기해야 되는 거 아니에요? 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네, 위원장님 말씀 맞습니다. 
</p>
<p><b>○ 위원장 이재준 </b> 두 분 잠깐만 계세요. 그리고 또 하나가 뭐가 있냐면 운송수지율. 그것이 우리, 운송수지율이 저기로 나와요. 95%가 2014년 연구논문에서 2015년 요금인상을 하면서 운송수지율이 95%가 나오는데 계속 80%라고 주장한 근거는 뭔가요? 80%가 아니라 최근……. 경기연구원의 연구 하나가 얼마만큼 정책에 큰 혼란을 가져오냐면 2011년 직행좌석버스 운송수지율이 90.6%, 2012년 99.1%, 2013년 95.7%, 2014년 91%, 2015년 요금인상 후에 94.9% 이렇게 나옵니다. 어디가 80%예요? 여기 이런 백데이터가 다 있는데 왜 80%라고 써서 보고를 하는 것이죠? 
</p>
<p><b>○ 휴먼교통연구실장 송제룡 </b> 그 내용에 대해서는 제가 좀 잘 모르는 부분인 것 같고요. 저희가…….
</p>
<p><b>○ 위원장 이재준 </b> 잠깐만요, 그러면 직무대행님 말씀 좀 해 보세요. 경기도에서 이렇게 보도자료를 냈어요. 그렇다고 그러면 우리 연구원 논문하고 다르잖아요. 그러면 반박으로 이 연구논문하고 실체가 다르다라고 얘기해야 되는 거 아닙니까? 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네, 맞습니다. 저희가 그건 확인을 못 했습니다. 
</p>
<p><b>○ 위원장 이재준 </b> 지금 보면요. 입석금지한다 그래서 8,000명을 태우기 위해서 166대를 증차해서 다니고 있어요. 그런데 입석금지도 안 할 뿐만 아니라 또다시 지금 8,000명이 부족해서 버스 준공영제를 하면 8,000명이 앉아서 다닐 수 있다라고 보고를 하는 겁니다, 지금. 뭐죠? 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 저희가 지금은 답변하기가 좀 곤란합니다만 확인한 후에……. 
</p>
<p><b>○ 위원장 이재준 </b> 아니, 제가 자료를 세 가지밖에 요청을 안 했어요. 경기연구원에서 버스요금 관련 연구한 것만 제가 자료요청을 해서 지금 질문을 드리는 건데 이거에 대해서 얘기를 안 하시면 말이 안 되죠. 
</p>
<p><b>○ 휴먼교통연구실장 송제룡 </b> 위원장님이 말씀하신 80, 제가 알기로는 2015년도 기준으로 해서 지금 수익금이 운송원가에 충당할 수 있는 퍼센티지를 가지고 말씀하시는 것 같은데요. 저희가 2015년도에 광역버스 같은 경우에는 85% 정도를 수익금으로 충당하고 있고요. 2016년도에 만약에 준공영제를 하게 된다면 수지율을 90%까지 올리겠다라고 해서 재정지원 금액이 824억이라는 금액이 나왔습니다. 
</p>
<p><b>○ 위원장 이재준 </b> 지금 보면 운송원가 3개를 계산해 놓은 게 연구논문에 있어요. 첫 번째가 2014년 운송원가, 2015년 준공영제 전의 운송원가 그다음에 2015년 준공영제 후의 원가가 나와 있어요. 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네.
</p>
<p><b>○ 위원장 이재준 </b> 그러면 2014년은 25만 5,000원이야, 운전직 인건비가. 그다음에 준공영제 전에는 26만 6,000원이고. 그리고 준공영제를 하게 되면 34만 2,000원이에요. 그래서 28%의 인건비가 증가해요. 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네.
</p>
<p><b>○ 위원장 이재준 </b> 그래서 28%를 늘려 주는 것까지 동의하는데 2014년도, 2015년도에는 저기가 없습니다, 이윤이 하나도 없어요. 이윤이 어차피 들어 있으니까, 내부창출 원가계산방법을 쓰니까. 그런데 2015년도 준공영제 후의 내부창출 원가계산은 이윤으로 해서 1만 7,000원이 왜 별도로 들어가는 거죠? 대당. 
</p>
<p><b>○ 휴먼교통연구실장 송제룡 </b> 원가산정에 대해서는 제가 산정을 하지 않아서 잘, 오후에 시간이 되신다면…….
</p>
<p><b>○ 위원장 이재준 </b> 그러니까 이윤이 없는 것을, 이윤이 2014년, 15년도 다 없어요. 이윤이 원래 들어 있어요. 내부창출 원가방식 할 때 전체 토털 금액의 6%에서 7%를 해 준단 말이에요. 그런데 여기에 또다시 없는 이윤 1만 7,000원이 들어가 있고, 또 하나는 뭐냐면 28%의 인건비가 증액하는데 왜 업체들은 인건비 부담에 대해서 한 푼도 부담을 안 하고 우리 경기도가 재정으로 전부 100%를 지원해 줘야 되느냐는 문제예요. 그거를 왜 여기서 결정을 하죠? 그것은 합리적인 토론 방법이나 그 버스업체들, 우리 경기도, 경기연구원 이렇게 콘센서스(consensus)를 이루어서 몇 % 할 건지를 해야 되잖아요. 서울은 16%예요, 인천 19.5%고. 그런데 우리 경기도는 30%를 해 주기로 한단 말이에요. 
</p>
<p><b>○ 휴먼교통연구실장 송제룡 </b> 제가 개인적인 생각을 말씀드리자면 이윤이라든지 인건비에 대한 금액은 지금 정확하게 낼 수는 없을 것 같고요. 앞으로 협상을 통해서 이루어져야 할 것 같다는 생각을 갖고 있습니다. 
</p>
<p><b>○ 위원장 이재준 </b> 그런데 이게 어떻게 작용을 했냐면 “버스 1대당 9만 원씩을 지원해 준다.” 이러니까 버스업체들이 동의한 겁니다. 이것이 만약에 5만 원이다, 4만 원이다 이러면 동의가 안 되고 서로 간에 토론들이 됐을 거예요. 그런데 그런 과정을 다 빼고 “무조건 준공영제 해야 된다. 그러니까 우리가 9만 원씩 주겠다. 그러니까 동의해라.” 이렇게 된 거거든요. 그것이 아니라 준공영제를 할 건지 완전공영제를 할 건지, 이거 예산은 얼마 들어가고 이건 얼마 들어가고. 그다음에 그렇게 됐을 때 분담되는, 증액이 되는 원가 인상요인은 누가 얼마씩 부담할 건지 이런 얘기들을 해야 되는데 이런 것이 아니라 결국 거기가 손해난다고 한 대당 9만 원은 다 그냥 인정해 준 거예요. 그러다 보니까 인건비 30%만 올린 것이 아니라 이윤으로 1만 7,000원씩을 또 넣은 거예요. 그래서 이것을 9만 원으로 맞춰 놓거든요. 어떻게 경기연구원의 연구용역 자료가 저희가 보면 상식적이지 않은 이런 자료들이 계속 생산이 되고 있냐는 거죠. 
</p>
<p><b>○ 휴먼교통연구실장 송제룡 </b> 그 9만 원이라는 원가의 차이는 시내버스 중에서도 광역버스 운전기사들의, 근로자들의 처우개선하고도 관련돼 있고요. 지금은 격일제로 운전자가 근무하고 있는데 1일 2교대제로 근무환경이 바뀌었을 때 운전자들의 근무하는 시간은 줄어들면서 시급도 올라가고 하면서 인건비가 증가한 걸로 나와 있는데요.
</p>
<p><b>○ 위원장 이재준 </b> 그 부분에 대해서는 뭐가 있냐면 우리가 그래서 요금인상을 해 줬잖아요, 광역버스 20%를. 20%를 해 줬을 때 그러면 수익금이 대당, 그런 거예요. 2015년 우리가 요금인상 용역한 거에 따르면 1대당 57만 9,000원이에요. 거기다가 보조금 6만 2,000원을 받으면 64만 원씩이 수익금이 생깁니다, 대당. 
</p>
<p><b>○ 휴먼교통연구실장 송제룡 </b> 네, 맞습니다. 
</p>
<p><b>○ 위원장 이재준 </b> 그러면 운송원가가 64만 원이면 똔똔은 되잖아요. 그렇다면 똔똔 말고 수익금이 얼마 더 돼야 할까 해서 그럼 2~3만 원만 지원해 주면 되는 것이지 왜 9만 원을 지원해 주냐는 거고 그다음에 또 하나는 왜 이걸 갖다가 노선별로 해서 80%가 적자노선이라고 하고, 업체별로 하면 그렇지가 않은데. 그래갖고 결국은 전부 적자 난……. 업체라는 것은요, 흑자노선 하나만 갖고 적자노선 10개도 운영할 수 있는 거예요. 그런데 그걸 갖다가 노선별로 해서, 지금 경기대원 같은 경우는 어떤 식으로 하냐면 흑자노선은 흑자노선으로 몰고 적자노선은 적자노선으로 몰아요. 대부분 버스업체들이 그래. 그래야 재정지원을 더 받으니까. 그렇게 노선별로 따지면 너무나 잘못된 거죠, 관점이. 한 말씀해 보시죠. 
</p>
<p><b>○ 휴먼교통연구실장 송제룡 </b> 저희가 2016년도에 버스체계개편 연구용역을 수행하면서 원가부분에 대해서 저희가 그 당시로는 분석했고요. 그 당시에 준공영제를 도입하게 되면 소요되는 예산이 824억이라는 수치를 내놓았고 그 824억 원 중에는 사실상 원가 중심으로만 금액이 나왔지 수익금 부분은 요금인상 부분도 있고 하기 때문에 여러 가지 변동요인이 있어서 반영을 못 했고요.  
</p>
<p><b>○ 위원장 이재준 </b> 그렇죠. 그러니까 원가가 64만 원이면 그중에 사실 수익금에서 많이 남는단 말이에요. 그럼 남으면 거기서 자기네가 얼마 부담하고 우리도, 공공도 얼마 부담하고 이런 식의 얘기가 돼야 되는데 그것이 아니라 일단 그냥 차이 나는 9만 원을 다 우리가 지원해 주겠다 이렇게 되니까 이런 것들이 일어난 것이고……. 
</p>
<p style="padding-left:1.2em">  네, 들어가시고요. 저기 직무대행께서는……. 그런 거예요 이게. 경기연구원이 낸 자료가 저쪽에서 인용이 될 때 잘못 인용이 된다든지 내지는 그것을 잘못 해석한다라면 우리가 적극적으로 해 주지 않으면, 이게 또 지사님 말씀하신 게, 언론 브리핑한 게 또 일반버스까지 다 한다고 그러잖아요. 5,000억짜리예요, 5,000억짜리. 왜 5,000억씩 매년 우리 경기도가 지원해 줘야 되느냐는 거지요. 그것에 대한 설명이 부족한 거잖아요. 그러니까 1,000억을 지원해 주든 얼마든 업체들이 과다하게 벌어가거나 내지는 감당할 수 있는 원가는 거기서 감당을 해 줘야 되는 것이지 그걸 갖다가 우리가 다, 남는데. 서울 같은 경우 시내버스 임원급들이 3억 7,000을 받아가요, 우리 경기도 1억 7,000 받아갑니다. 그게 다 원가에 들어 있는 거예요. 그리고 여기 원가는 더, 경기도는 더 모순된 게 시내버스, 고속버스, 시외버스, 마을버스까지를 다 버스업체가 해요. 그러면 임원이나 정비직은 어느 소속이냐는 거예요. 원가시스템에 안 되어 있어. 그래서 그걸 하기 위해서 BIS시스템을 만들기로 했는데 그게 연말에 나오는 거잖아요, 그래서 내년에 시험하고. 그러면 이런 과정들을 거쳐서 하는 것이 맞다고 얘기해야 되는데 집행부에서 하니까 그냥 아무 말도 안 한다면 경기연구원이 왜 있어야 되느냐는 거지요.
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 그 문제에 대해서는 저희 내부에서도 토론이 많이 이루어졌는데요. 도에다가도 그런 내용들을 어느 정도 일부는 전달을 한 걸로 알고 있습니다. 
</p>
<p><b>○ 위원장 이재준 </b> 전달한 게 있으면 그 전달한 서류를 저한테 주시고요. 하여간 경기연구원이 양심적으로 연구한 것들이 내지는 연구한 것이 우리가 이런 목적으로 연구를 했는데 이것이 잘못 왜곡이 된다고 그랬을 때는 어떤 채널을 통해서든 그걸 보정을 해야지 잘못되는 방향으로 가고 너무나 막대한 예산들이 들어가는 거잖아요. 이거 5,000억이지요, 그다음에 전기차 만들어서 공급한다고 또 1조 원이지요. 1조 5,000억을 어떻게 할 거냐는 거예요. 그런 것들을 그냥 공약으로 발표하게끔 이렇게 그냥 놔두시면 안 되는 거지요.
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네, 저희 역할을 좀 더 생각을 해 보겠습니다. 
</p>
<p><b>○ 위원장 이재준 </b> 오전 본질의는 전부 끝났으니까 중식을 위해서 2시까지 감사를 중지하고자 하는데 이의 없으십니까? 
</p>
<p style="padding-left:2.4em">    (「네.」하는 위원 있음) 
</p>
<p style="padding-left:1.2em">  2시까지 감사를 중지합니다. 
</p>
<p class=''ar''>(12시35분 감사중지)
</p>
<p class=''ar''>(14시05분 감사계속)
</p>
<p><b>○ 위원장 이재준 </b> 좌석을 정돈해 주시기 바랍니다. 감사를 속개하겠습니다. 
</p>
<p style="padding-left:1.2em">  그러면 계속해서 추가질의 답변을 시작하도록 하겠습니다. 추가질의 답변 시간은 5분이 되겠습니다. 질의하실 위원님께서는 거수로 신청해 주시기 바랍니다. 이현호 위원님 질의해 주시기 바랍니다.
</p>
<p><b>○ 이현호 위원 </b> 이현호 위원입니다. 이사장의 임기는 몇 년이에요? 이사장.
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 3년입니다.
</p>
<p><b>○ 이현호 위원 </b> 이사장이요?
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네, 3년입니다.
</p>
<p><b>○ 이현호 위원 </b> 상근입니까, 비상근입니까? 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 비상근입니다.
</p>
<p><b>○ 이현호 위원 </b> 비상근이에요?
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네.
</p>
<p><b>○ 이현호 위원 </b> 네, 알았습니다. 2016년도 결산보고서에 세출결산을 보니까 집행률이 76%에 불과했습니다. 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네. 
</p>
<p><b>○ 이현호 위원 </b> 아시겠지요?
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네.
</p>
<p><b>○ 이현호 위원 </b> 특히 연구원 사업비의 경우 71.1%밖에 되지 않는데 특별한 이유가 있는지 모르겠습니다만 몇 가지 말씀을 드리겠습니다. 지금 방금 말씀드린 대로 2015년도 결산보고서를 살펴봐도 집행률은 80%밖에 되지 않았습니다. 전반적으로 예산을 연구원에서 과다하게 세우고 불용시키는 비율이 높은 것 같은데 우리 부원장님께서는 이 점에 대해서 어떻게 생각하고 계십니까? 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 저희가 재작년도부터 정규직 인원을 보충하려고 2명, 3명씩 인건비에다 포함을 시켰는데요. 올해도 마찬가지이고 작년도에도 그 인원을 보충 못 했습니다. 그 인건비가 지출되지 않은 게 우선 집행률이 낮은 원인입니다. 그다음에 또 한 가지는 과제사업비 같은 경우에도 이월되는 부분이 한 7억에서 9억 정도가 되기 때문에 그 부분을 집행하지 못한 것도 있고요. 
</p>
<p><b>○ 이현호 위원 </b> 그러니까 그 인력을 채용할 계획을 다 세웠던 것 아니에요. 그렇지요?
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네, 그렇습니다. 
</p>
<p><b>○ 이현호 위원 </b> 그 인력을 채우지 못했기 때문에…….
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네, 그런 부분도 있습니다. 
</p>
<p><b>○ 이현호 위원 </b> 그러니까 어떤 게 잘못인가. 채우지 못할 것을 세운 것이 잘못한 건가, 세우고 충원을 못 시킨 것이 잘못된 것인가. 그렇지요? 어떤 게 잘못된 것인가 이거지요. 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 그러니까 채용계획을 세워서 예산에 반영을…….
</p>
<p><b>○ 이현호 위원 </b> 세웠으면 해야 할 것 아니에요. 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 해야 되는데, 올해에도 채용을 하려고 그랬는데 9월 15일 날 원장님이 나가시는 바람에 새로운 원장님이 오신 다음에 채용을 했으면 좋겠다는 얘기가 있어서, 채용을 하려고 생각했습니다만 중도포기를 하시는…….
</p>
<p><b>○ 이현호 위원 </b> 어차피 새로운 원장은 세우기가 쉽지 않는 것 아니에요, 이제. 그렇지요?
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네, 내년도에는…….
</p>
<p><b>○ 이현호 위원 </b> 아니, 원장. 새로운 원장을 선임하기가 쉽지 않단 말이에요, 임용하기가. 그렇지요?
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네, 그런 걸로 알고 있습니다. 
</p>
<p><b>○ 이현호 위원 </b> 그럼 쉽게 말해서 일단은 금년도는 넘어가고 지금 어떻게 보면 지사하고 같이 간다고 볼 때에 지금 얼마 안 남았는데 새롭게 누가 연구원 원장 한다고 응모는 안 할 거란 말이에요. 그렇지요?
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네, 그런 줄 알고 있습니다.
