<p><b>○ 양근서 위원 </b> 그래서 저는 이것을 더 적극적이고 상향 조정해서 정규직 대상 기준을 확대해야 할 필요가 있다고 보는데요. 예를 들면 이런 겁니다. 지금 의회에 계약직으로 파견돼서 일하고 있는 박사급 연구위원들이 계세요. 총 네 분이지요.
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네, 4명입니다. 
</p>
<p><b>○ 양근서 위원 </b> 이분들은 지금 근무기간이 1년 됐어요.
