<p><b>○ 경기연구원장직무대행 김군수 </b> 네, 그렇습니다. 
</p>
<p><b>○ 양근서 위원 </b> 그러면 아까 말씀하신 기준으로라면 여기에 포함됩니까, 안 됩니까? 현재 60명 대상에.
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 포함이 안 됩니다. 
</p>
<p><b>○ 양근서 위원 </b> 안 되지요? 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 초빙연구원은 포함이 안 됩니다.
</p>
<p><b>○ 양근서 위원 </b> 그러니까 이게 말이 안 되잖아요. 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 그런데 여기에는 고도의 전문직무를 갖는 사람은 제외하도록 돼 있기 때문에 박사급은 제외하는 걸로 저희가 알고 있습니다. 
</p>
<p><b>○ 양근서 위원 </b> 그러면 일단 아까 그 60명 대상 기준에서 박사급은 다 제외한다는 얘기입니까? 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네, 초빙연구원이 주로 박사급인데요. 박사급이 지금 저희가 16명이 있습니다. 그런데 박사급은 제외…….
</p>
<p><b>○ 양근서 위원 </b> 아니, 석사ㆍ박사라고 하는 것은 말 그대로 학위에 관련된 것이지 그것이 고도의 전문성을 요하는지 안 하는지에 대해서는 말 그대로 정성적으로 심사위원회에서 기준을 정하기 나름으로 판단하면 되는 것이지 박사라고 해서 고도의 전문직을 요하는 것이고 석사는 아니라고 판단할 수 있는 근거가 어디 있습니까? 그렇잖아요?
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 그래서 저는 심의위원회에서 그걸 판단할 사항이라고 생각하고 저희는 우선 내부적으로는 그렇게 생각하고 있는데요. 
</p>
<p><b>○ 양근서 위원 </b> 그러니까 그 기준대로라면 지금 전체 111명의 비정규직 중에서 16명이 지금 초빙연구원, 박사급이에요. 나머지는 다 석사, 연구위원급이고.
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네.
</p>
<p><b>○ 양근서 위원 </b> 그러면 16명은 지금 보니까 근무기간이 7년 되신 분도 계시고, 최장. 적게는 지금 1년 되신 분들이 계시는데 2년들이 주로 많고. 이분들은 어쨌든 정규직 대상에서 다 제외시켜야 된다는 것이잖아요, 기계적으로. 이건 말이 안 되는 것 같아요. 그렇잖아요? 그 기준이라고 하는 것도 방금 부원장님이 말씀하셨듯이 고도의 전문직무라고 하는 것 자체도 이게 상식적인 기준은 아닌 것 같아요. 그렇지요? 예를 들면 이런 게 있어요. 일시ㆍ간헐적 업무나 휴직대체 등 보충적 근로인 경우에는 정규직 대상에서 제외시켜도 된다라고 하는 기준에 따르면 그런 분야에 해당되는 경우가 있습니다. 111명 중에 예를 들면 휴직대체인력이라고 명시돼서 뽑은 분들이랄지 또는 단기정책과제를 수행하는 데 있어서 수탁과제 연구위원으로 참여한 분들이랄지 이런 분들은 정규직 대상에서 심사숙고를 해야 될 대상이겠지만 아니, 7년 근무하고 2년 이상 근무하신 분들인데 당연히 포함시켜야 된다고 보는 거고요. 어떻게 생각하십니까? 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 그분들이 저희 일반회계에서 채용된 사람들이 아니라 수탁과제에서 계속적으로 채용해서 연장을 하는 분들이었고 또 하나 고도의 전문직무인지 아닌지는 확인을 해 봐야 되겠습니다만 주로 수탁과제에 의해서 체결되었기 때문에, 그래서 이거를 상시ㆍ지속적인 여부 판단은 추후에 다시 한 번 검토를 해 봐야 될 것으로 생각합니다. 아직까지는 저희 내부적…….
</p>
<p><b>○ 양근서 위원 </b> 왜냐하면 수탁과제라고 하는 것이 아까도 저희가 거론했지만 연간 35억 원에서 50억 원 정도의 사업계획을 세울 정도로 매년 항상 상시적으로 일어나는 일이잖아요. 그리고 그 업무라고 하는 것이 구체적인 주제 자체는 조금씩 달라질 수 있지만 포괄적으로 거의 모든 분야에 걸쳐서 수탁이 이루어지고 연구가 이루어지지 않습니까? 그러면 일종의 상시업무지요, 상시업무. 그렇잖아요? 1년, 2년 하고 그만둘 것도 아니고 수탁업무 자체가 상시업무이기 때문에 그 기준으로 봐야 된다는 얘기이고 아까 말씀드렸던 경기도의회 파견 4명의 연구위원, 초빙연구원 박사급도 마찬가지입니다. 경기도의회에서 지금 현재 의정활동 지원활동을 하고 있는데 이게 일시적인 업무입니까, 간헐적인 업무입니까, 아니면 상시업무입니까? 얼른 대답을 해 보세요. 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 그건 판단하기가 어려운데요.
</p>
<p><b>○ 양근서 위원 </b> 뭐가 판단이 어려워요. 이건 당연히 상시적인 업무지요. 의회에서 보좌인력이 부족해 가지고 요청을 했고 그 기준에 따라서 지금 이 시스템이 만들어진 건데 이것도 상시업무이기 때문에 적극적으로 해석을 하세요, 적극적으로. 그리고 이에 따른 예산 추가비용이 있을 것 아닙니까? 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네.
</p>
<p><b>○ 양근서 위원 </b> 이건 어느 정도 됐는지, 그러니까 60명 기준으로 했을 때 제가 방금 말씀드린 그런 기준을 가지고 상향화시키고 적극적으로 기준을 적용했을 때 그럼 당연히 비정규직 정규직 대상군이 늘어날 텐데 그랬을 때는 예산이 어느 정도 추가되는지 이것들을 조사해서 비용분석을 해 가지고 제출해 주시기 바랍니다.
