<p><b>○ 경기연구원장직무대행 김군수 </b> 네, 알겠습니다. 
</p>
<p><b>○ 양근서 위원 </b> 그러니까 적극적으로, 공격적으로 정규직 전환계획을 마련해 달라는 주문이에요. 그렇지 해 주시겠죠?
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네. 저희들도 그 부분에 대해서는 적극적으로 생각하고 있습니다. 
</p>
<p><b>○ 양근서 위원 </b> 이상입니다.
</p>
<p><b>○ 위원장 이재준 </b> 양근서 위원님 수고하셨습니다. 다음 질의하실 위원님, 최춘식 위원님.
</p>
<p><b>○ 최춘식 위원 </b> 최춘식 위원입니다. 여기 GRI 연구결과 정책반영 사례집 있잖아요? 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네.
</p>
<p><b>○ 최춘식 위원 </b> 여기 지금 저희 주신 거 말씀드리는 거예요, 정책반영 사례집. 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 아, 책자로 돼 있는 거 말씀하시는 거…….
</p>
<p><b>○ 최춘식 위원 </b> 네, 이거 있죠? 그리고 지금 업무보고하신 거, 업무보고. 이 2개를 좀 비교해 봤거든요. 그런데 여기 34페이지 18번에 나와 있는 거, 도 4차산업 대응전략 수립자료 활용으로 과제명은 제4차 산업혁명 시대 일자리 전략 이거요.
