<p><b>○ 경기연구원장직무대행 김군수 </b> 네.
</p>
<p><b>○ 최춘식 위원 </b> 이것이 여기 업무보고에 있는 2017년도 신규착수 연구목록에 들어가 있어야 되는 게 맞는 건가요, 아니면 없어도 되는 건가요? 17년도에 수행한 과업인데. 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네, 17년도에……. 이거는 저희가 매주마다 발간하는 이슈&진단에서 연구를 했기 때문에 과제 수행에는 포함하지 않은 것 같습니다. 
</p>
<p><b>○ 최춘식 위원 </b> 목록에 안 들어가 있어도 되는 겁니까, 이게? 왜냐하면 업무보고 자료에 의하면 17년도 신규착수 연구목록을 따로 뽑아 주셨잖아요, 그렇죠? 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네.
</p>
<p><b>○ 최춘식 위원 </b> 그럼 거기에 들어가 있어야 됩니까, 안 들어가 있어야 됩니까? 제가 잘 못 찾았나요? 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 여기 신규착수 목록에는 과제만 들어가 있습니다. 이거는 과제가 아닌 정책 진단…….
</p>
<p><b>○ 최춘식 위원 </b> 아, 진단으로 했기 때문에 안 들어간 거예요? 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네, 들어가지 않았습니다. 
</p>
<p><b>○ 최춘식 위원 </b> 과제만 들어가 있는 거예요? 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네, 과제만 들어갔습니다. 저희가 280개를 다 집어넣기엔 양이 너무 많아서요.
</p>
<p><b>○ 최춘식 위원 </b> 아, 그래서 이게 안 들어 있다. 좋습니다, 그거는. 그런데 이게 지금 연구과제가 연구된 기간을 보면 한 2주 정도밖에 안 되거든요?
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네.
</p>
<p><b>○ 최춘식 위원 </b> 과제가 상당히 다방면으로 다양한 것 같은데 굉장히 빨리 끝났어요. 이런 경우는 어떤 경우에서 이렇게 빨리 끝납니까? 다른 거 보니까 지금도 진행 중인 게 태반인데. 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 저희 과제는 보통 한 4개월에서 10개월 정도 소요되고요. 이슈&진단 같은 경우에는 매주마다 발간해야 되기 때문에 한 2주 정도 연구해서 현안이나 그런 걸 중심으로 해서 대안을 만들어서 연구합니다. 
</p>
<p><b>○ 최춘식 위원 </b> 그게 시급성은 있다고 하지만 만약에 그렇게 했을 때 내용이 좀 부실하거나 이런 것은 우려되는 게 없었어요? 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 그래서 저희가 이슈&진단 같은 경우에는 구체적인 정책적 대안을 마련하지 못합니다. 그래서 주로 이슈와 큰 방향만 제시하고……. 
</p>
<p><b>○ 최춘식 위원 </b> 안만 제시해 주고? 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네, 그런 상태고. 필요성을 느끼면 과제로 전환해서 세부적인 전략을 짜게 됩니다. 
</p>
<p><b>○ 최춘식 위원 </b> 그래서 이렇게 빨리 끝내야 된다 그런 뜻이죠? 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네, 이슈&진단은 2주 정도 연구하게 됩니다. 
</p>
<p><b>○ 최춘식 위원 </b> 잘 알겠습니다. 이상입니다. 
</p>
<p style="padding-left:2.4em">    (이재준 위원장, 나득수 간사와 사회교대)
</p>
<p><b>○ 위원장대리 나득수 </b> 최춘식 위원님 수고하셨습니다. 다음 질의하실 위원님 계십니까? 박형덕 위원님 질의해 주시기 바랍니다. 
</p>
<p><b>○ 박형덕 위원 </b> 박형덕 위원입니다. 오전에 이어 오후에 또 이렇게 위원님들에 대한 질의와 답변을 하시느라고 고생이 많으십니다. 저는 몇 가지만 그냥 간단히 질의하겠습니다. 
</p>
<p style="padding-left:1.2em">  우리 경기도 및 도의회 의뢰과제 수행에 관련해서 질의하겠습니다. 그게 보니까 단기정책 의회 의뢰과제 해서 GRI에서 지금 하고 있는데 단기정책과제에 대해서 설명 좀 해 주세요. 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 단기정책과제는 크게 두 가지로 구분됩니다. 도나 도의회에서 의뢰한 과제를 보통 한 4개월에서 6개월 내에 연구하는 과제이고 그다음에 저희가 필요해서 자체적으로 발굴하는 과제가 한 10% 정도 됩니다. 그 두 가지 유형의 과제를 단기정책과제라고 그러고 그 반대되는 유형이 전략과제라고 그건 시간이 소요되면서 연구자들이 많이 포함되는, 융합적인 연구를 하는 그런 과제하고 대별되는 과제라고 할 수 있습니다. 
</p>
<p><b>○ 박형덕 위원 </b> 그러면 과제 의뢰업체 선정 완료까지는 절차가 어떻게 진행이 돼요? 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 도 의뢰나 도의회 과제 같은 경우에는 도에서 공문 형태로 저희한테 의뢰가 오면 저희가 내부적으로 검토를 해서 회신을 주게 됩니다. 그래서 도에서 해당 실국이면 실국에 다시 조율을 해서 최종적으로 저희한테 공문 형태로 주면 저희 내부적으로 연구위원회라는 위원회에서 예산과 연구내용을 확정하게 됩니다. 
</p>
<p><b>○ 박형덕 위원 </b> 그런데 주신 자료에 보니까 경기도는 우리 GRI에다 70건을 의뢰해서 76% 정도인 53건만 채택이 된 반면에 도의회는 13건을 했는데 13건 전체가 다 채택이 됐어요? 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네.
</p>
<p><b>○ 박형덕 위원 </b> 그러면 도의회에서 요구한 과제는 그만큼 집행부에서 준 과제보다 더 내용이 완벽해서 의회 건을 이렇게 잘 해 주신 거에 대해서 감사하지만 집행부에서 낸 과제보다 100% 과제를 이렇게 수행한 부분에 대해서는 의회에서 낸 과제가 집행부에서 낸 과제보다 더 월등하다고 생각돼서 이렇게 채택이 된 건가요? 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 물론 그런 면도 있겠습니다만 우선 도 집행부에서 의뢰한 과제 중에서 저희가 수행하고 있는 과제와 중복되는 부분이 있는 주제 같은 경우에는 우선 수행하기 어렵다고 공문을 회신하였고 또한 한 달 이내의 고도의 분석을 필요로 하지 않는 간단한 분석을 통해서 하는 과제들은 과제로 하지 않고 그냥 현안분석이나 간단한 대응 정도로 했음 좋겠다는 판단하에서 그래서 의뢰불가로 해서 보낸 경우도 있습니다. 
</p>
<p><b>○ 박형덕 위원 </b> 어쨌든 경기도와 도의회 정책과제 현안문제를 해결하기 위해서 과제의뢰에 성실히 우리 GRI에서 해 준 부분에 대해서 전 개인적으로 감사드립니다. 그리고 특히 도의회에 더 많은 관심과 사랑을 갖고 있었기 때문에 그런 부분에서 GRI에서 도의원님들의 얘기를 존중하고 또 그 과제에 대해서 이렇게 채택해 주셔서 잘 해 주신 부분에 대해서 저 개인적으로 감사드리는 측면이 있습니다. 
</p>
<p style="padding-left:1.2em">  이제 연말이고 아직 진행 중인 과제도 마무리 안 된 것 같은데 의회 의뢰과제 목록 중에서 지방분권형 헌법 개정 검토안이 있는데 이 부분은 다 마무리가 됐나요? 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 이거는 과제가 마무리된 걸로 알고 있습니다. 이거는 과제형태로 하는 것보다도 현안분석이라고 해서 아마 간단하게 현안분석을 한 걸로 알고 있습니다. 
</p>
<p><b>○ 박형덕 위원 </b> 그러면 사실 지방분권이 문재인 정부 들어서고 나서 지금 상당히 지방정부뿐만 아니라 중앙정부에서도 발 빠르게 관심과 또 그 부분에 지금 많은 연구, 노력들을 하고 있는데 특히 우리 경기도의회에서 이런 지방분권형 과제를 내놓고 GRI가 함께했다는 데는 전 상당히 의미가 있다고 생각해요. 그래서 혹시 그 부분에 대해서 분권에 대한 우리 경기도만의 구체적인 제시라든가 제안이라든가 기타 이런 부분, 다 됐다 그러면 나온 게 있습니까, 지금? 그런 부분에 대해서 설명 좀 해 주세요. 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 저희 연구원에서 지방분권에 관련된 경기도 대응전략까지 포함해서 여러 과제를 완료했다고 생각을 하는데요. 구체적인 거는 제가 잘 기억을 못 하기 때문에 담당자를 불러서 대신 답변하도록 해도 되겠습니까? 
</p>
<p><b>○ 박형덕 위원 </b> 네, 그러세요.
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 그러면 박충훈 박사님. 
</p>
<p><b>○ 공존사회연구실장 박충훈 </b> 공존사회연구실장 박충훈입니다. 질의하신 내용에 대한 답변드리도록 하겠습니다. 저희가 지방자치 및 지방분권에 관한 연구는 수년 전부터 관심을 가지고 쭉 지속을 해 왔고요. 특히 올 들어 새 정부 출범하면서 대통령께서 지방분권의 의지를 밝히시는 과정에서 크게 로드맵이라든가 이런 것들이 나왔습니다만 아직 세부적인 사항이 발표가 안 되고 있는 상황이기 때문에 예의주시를 하면서 그러한 지방분권 방안들을 경기도에 맞게 최적화시키기 위한 노력을 계속하고 있습니다. 현재에도 경기도 관련 부서들과 정보를 교환하고 있으며 일부 내용들에 대해서는 저희가 연구되는 대로 도에 전달해서 경기도 입장에서 중앙정부에 건의할 수 있도록 하는 그런 노력을 하고 있습니다. 
</p>
<p><b>○ 박형덕 위원 </b> 그래서 지방자치가 도래된 지 20년이 지났고 또 이제는 지방자치단체가 성숙도에 올랐다고 이렇게 봅니다. 그런데 이게 너무 중앙적인 집권하에 지방자치가 이루어지다 보니까 사실 많은 지방자치단체에 어려움도 있고 또 이제는 도민들뿐만 아니라 지방자치단체의 역할이 분명히 있어야 된다. 그런데 물론 현 지방정부 들어서 아직 정확한 로드맵이 결정되지 않은 상태에서 우리 경기도가 결정할 수 있는 큰 역할은 사실 없지만 그래도 미리 준비를 잘 해서 정부에서 그런 로드맵이 결정됐을 때 발 빠르게 다른 광역시보다 한 단계 빨리 나갈 수 있는 그런 준비는 돼야 되겠다, 저는 그런 생각이 듭니다. 
</p>
<p style="padding-left:1.2em">  어쨌든 지방분권은 전 반드시 이루어진다고 봤을 때 우리 경기도가 18개 광역시에서 최고 큰 광역 도고 또 우리 대한민국 지방자치의 가장 큰 지방자치단체로서 해야 될 역할은 분명히 있다고 봅니다. 그런 측면에서 우리 경기도의회와 GRI하고 또 경기도 집행부가 이 부분에서 좀 더 심도 있게 많은 정책과 대안을 제시해서 준비를 할 필요가 있다, 이런 차원에서 제가 질의한 겁니다. 
</p>
<p><b>○ 공존사회연구실장 박충훈 </b> 네.
</p>
<p><b>○ 박형덕 위원 </b> 이상입니다. 
</p>
<p><b>○ 위원장대리 나득수 </b> 박형덕 위원님 수고하셨습니다. 다음 질의하실 위원님 계십니까? 
</p>
<p style="padding-left:1.2em">  제가 잠깐 질의드리겠습니다. 우리 경기연구원 인사복무규정을 보면 50조의3항에 임금피크제를 도입하셨어요?
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네.
</p>
<p><b>○ 위원장대리 나득수 </b> 2016년 12월 24일 부로 임금피크제를 도입하셨는데 임금피크제 규정에 신규 고용창출을 위해서 임금피크제를 시행한다고 규정해 놓으셨어요. 그런데 실질적으로 임금피크제가 우리 계약직 아닌 호봉제, 호봉제에만 해당이 되는 것인가, 그렇죠? 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네, 지금 그렇게…….
</p>
<p><b>○ 위원장대리 나득수 </b> 호봉제에 해당되는 거죠. 그러니까 행정관리직만 해당되는 거죠? 우리 연구직은 연봉제죠?
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네, 그렇습니다. 
</p>
<p><b>○ 위원장대리 나득수 </b> 그리고 재계약방식으로 계약을 체결하는 거죠?
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네, 3년마다 재계약 형식으로…….
</p>
<p><b>○ 위원장대리 나득수 </b> 3년마다 그렇죠. 그런데 2016년 11월 25일 자 제83차 경기연구원 정기이사회 회의록을 보면 진정한 임금피크제에 대한 논쟁이 아니라 그냥 임시방편적으로 우리 경기도 자체감사에서, 그러니까 경기연구원 감사에서 좋은 점수를 받아야겠다. 또는 임금인상에 대해서 감점을 받지 않아야겠다. 그래서 우리 임금피크제를 도입해야 한다. 이렇게 기술이 돼 있어요. 이거 맞습니까? 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네, 그렇게 논의된 걸로 알고 있습니다. 
</p>
<p><b>○ 위원장대리 나득수 </b> 그렇게 논의됐어요? 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네. 저희가 경영평가를 받을 때 3점인가 몇 점을 감점 받도록 되어 있습니다, 임금피크제를 도입 안 했을 경우에는. 그래서 임금피크제를 도입하려고 하는 그런 움직임을 보였다가 호봉제는 임금피크제를 시행하고 연봉제를 적용받고 있는 박사진, 연구원 같은 경우에는 저희가 행정자치부하고 도에 문의한 결과 자율적으로 해도 된다는 그런 견적을 받았습니다. 
</p>
<p><b>○ 위원장대리 나득수 </b> 자, 그럼 행정관리직도 그러면 임금피크제를 하려면 모든 근로자들의 동의를 얻어야 되지 않습니까? 근로기준법상 그렇게 규정이 돼 있죠. 그 동의를 얻었어요? 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네, 동의를 받았습니다. 
</p>
<p><b>○ 위원장대리 나득수 </b> 다 받으셨습니까? 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네, 호봉제는 동의를 다 받았습니다. 
</p>
<p><b>○ 위원장대리 나득수 </b> 그 동의를 받는 과정에, 혹시 이 과정에서 관리청의 압력이라든가 이런 게 있었지 않나 싶은데 전혀 없었습니까? 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 그런 건 없었던 걸로 알고 있습니다. 근로자…….
</p>
<p><b>○ 위원장대리 나득수 </b> 자발적 동의인 건가요? 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 아, 이거를 다 찬성한 건 아닙니다만 그때 근로자 동의를 받으면서 어느 정도 취지를 설명했고 그런 과정 속에서 많은 사람들이 동의한 걸로 알고 있습니다. 
</p>
<p><b>○ 위원장대리 나득수 </b> 그렇다면 지금 실적은, 그러니까 임금피크제 실적은 어느 정도 되는 건가요? 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 지금 저희가 도래한 사람이 2021년도에 퇴직할 분이 한 분 계시기 때문에 2019년 7월부터 적용하게 됩니다. 
</p>
<p><b>○ 위원장대리 나득수 </b> 실적은 전혀 없네요? 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 실적은 아직 없습니다. 
</p>
<p><b>○ 위원장대리 나득수 </b> 아무튼 행정관리직만 대상이 되는 거죠? 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네, 그렇습니다. 
</p>
<p><b>○ 위원장대리 나득수 </b> 그런데 굳이, 서울연구원이라든가 대전연구원에서는 이 규정을 규정하지 않았대요. 그런데 유난히 우리 경기연구원만 인사복무규정에 규정을 해 놨어요. 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 규정에 도입한 거는 임금피크제 도입하면서 그때 개정한 걸로 알고 있습니다. 
</p>
<p><b>○ 위원장대리 나득수 </b> 그러니까 불이익을 받을 소지가 있어서, 그렇죠? 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네, 그렇습니다.
</p>
<p><b>○ 위원장대리 나득수 </b> 경기도 감사나 임금협약, 임금인상, 보수인상에 대한, 보수인상에서 불이익을 받을 것 같으니까 임금피크제를 도입했다 이런 말씀이신가요? 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네, 그런 것도 있고 경기도에서 권고사항이었고……. 
</p>
<p><b>○ 위원장대리 나득수 </b> 그다음에 여기 의사록을 보니까 우리들은, 박사들은 청년이 아니다, 청년고용이 아니다 이거예요. 대부분이 24세 이상이고 그러니까 청년고용 문제는 없으니까 이걸 그냥 도입하자 이런 식으로 계속 나와요, 의사록에. 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 박사들 말씀하시는 건가요? 
</p>
<p><b>○ 위원장대리 나득수 </b> 그러니까 의사록에 계속 나와, 이런 형태가. 그러니까 임금피크제에 대한 어떤 진정한 의미를 논의하는 것이 아니라 임시방편적으로 “우리가 점수를 더 많이 받겠다.” 그런 취지로 계속 얘기하고 있어요. 제가 의사록을 읽으면서 참, 우리 또 말씀드리지만 경기도 싱크탱크가 이사회에서 이런 말을 해도 되느냐. 저는 좀 실망했어요. 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 그 당시에 임금피크제 관련 논란이 상당히 많이 있었기 때문에 아마 이사회에서……. 
</p>
<p><b>○ 위원장대리 나득수 </b> 그리고 한 가지만 더 하겠습니다. 제50조에 보면 근무상한연령이 있어요. 제1항에 보면, 복무규정이요, 인사복무규정. 대외협력처장은 65세 그다음에 관리ㆍ정보 1급ㆍ2급, 연구직은 60세 그다음에 기타직원은 60세. 이런 것들이, 대외협력처장 65세는 지금 한 세 번째에 걸쳐서, 3차에 걸쳐서 개정돼 있어요. 다른 직원들은 다 60세예요. 그런데 유난히 대외협력처장만 65세예요. 그 이유가 뭐예요? 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 대외협력처장은 개방직이고 공모에 의한 외부 전문가를 채용해야 되기 때문에 굳이 60세라고 못을 박으면 사람을 뽑을 때 상당히 제한이 있다 이래서 연령을 높인 걸로 알고 있습니다. 
</p>
<p><b>○ 위원장대리 나득수 </b> 다른 이유는 없습니까? 그냥 그 이유입니까? 혹시 뭐 공무원 퇴직자들의 자리를 만들어주는 자리가 아닌가 싶은데, 그런 생각은 안 해 보셨어요? 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 저희가 개방직으로 했기 때문에 퇴직공무원뿐만 아니라 일반 전문가들 전부 다 수용을 한다는 취지에서 만든 것이기 때문에 굳이, 그것도 포함이 되어 있습니다만 꼭 그것만 위해서 한 건 아닌 것 같습니다. 
</p>
<p><b>○ 위원장대리 나득수 </b> 제가 의심스러워서 한번 여쭤본 겁니다. 이상 마치겠습니다.
</p>
<p style="padding-left:1.2em">  더 질의하실 위원님 계십니까? 장동일 위원님 질의해 주십시오. 
</p>
<p><b>○ 장동일 위원 </b> 부원장님께 좀 여쭤보겠습니다. 경기도의 인구가 앞으로 한 10년 이내에 데드크로스(dead-cross)가 날 것이다, 인구가 줄어든다는 얘기인데. 그렇게 봐도 됩니까? 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네, 그렇게 예측하고 있습니다. 
</p>
<p><b>○ 장동일 위원 </b> 그러면 제가 몇 년 동안 계속 연구원에서 연구 자료를 받아보고 있어요, 계속 보내주시니까. 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네.
</p>
<p><b>○ 장동일 위원 </b> 그 자료를 보면, 제가 그걸 쭉 다 볼 순 없으니까 큰 타이틀을 분류해서 제가 관심 있는 것만 보고 나머지는 이렇게, 그걸 다 볼 수가 없으니까 그러는데. 그 연구 자료를 보면 선도적 연구 자료라기보다는 계속해서 추격하고 일반적인 거, 우리가 그냥 보도를 통해서 알고 있는 내용에서 크게 벗어나질 않아요. 그래서 제가 느끼는 아쉬움은 뭐냐 하면 경기도의 인구 데드크로스 문제 이런 것들이, 지금은 그래도 인구가 계속 늘어나고 있기 때문인데. 그럼 모든 변화가 올 거 아닙니까? 주택, 산업, 취업 이런 부분에 대해서. 그럼 그런 부분들을 좀 앞서 나가서 이런 부분들을 선제적으로 해 주셨으면 좋겠다는 개인적인 생각들을 해 봤는데 그런 부분에 대해서 제 생각이 짧아서 그런가, 부원장님 생각은 어떠세요? 그런 부분이 좀 아쉬움이 있어서 이번 기회에 제가 질의를 드려보는 겁니다. 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네, 저희가 위원님이 말씀하신 선도적ㆍ창의적 연구를 하는 데 약간 소홀히 했습니다만 그럼에도 불구하고 일본 사례를 참고해서 올해 일본의 사례를 검토해서 시사점을 뽑으려고 노력을 많이 했습니다. 그래서 과제를 수행했고요. 앞으로도…….
</p>
<p><b>○ 장동일 위원 </b> 일본 지방소멸 이런 얘기 들어보셨죠?
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네. 
</p>
<p><b>○ 장동일 위원 </b> 2030년이면 일본에 빈집이 수백만 가구가 될 것이다. 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네.
</p>
<p><b>○ 장동일 위원 </b> 일본이 우리나라만큼 정책을 못 해서 그런 나라도 아니고 모든 하드웨어나 소프트웨어나 인프라가 우리보다 훨씬 나은 일본도 이런 상황인데 우리가 과연 일본의 사례를 벗어날 수 있을까, 일본의 그런 경우를. 그래서 일본 말씀을 하시니까 그런 의문이 생기는데 그럼 일본의 사례를 어떻게 비교분석해서 어떻게 적용하실 건지 시간도 있고 하니까 간단히 설명을 해 주십시오. 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 일본의 주택산업, 여러 가지 분야에 20년 정도의 차이를 두고 일어나고 있기 때문에 저희가 1990년도의 사항을 어느 정도 파악해서 분석을 해 놨습니다. 그래서 그 사례를 봐서 “우리나라도 앞으로 갈 거고 지자체 차원에서도 신도시 주변에 빈집들이 많이 발생하고 고령화가 많이 발생하니까 우리나라의 신도시 지역들도 그렇게 될 거라는 예측하에 나름대로 대책을 수립해야 한다.” 이런 얘기를 많이 하고 있는데 아직까지는 중앙정부 차원에서 주택공급이나 부동산 정책이 조금 저희 생각대로 가지 않는 부분이 있기 때문에 그런 부분을 많이 건의하고 이런 작업을 하고 있기는 합니다. 
</p>
<p><b>○ 장동일 위원 </b> 그러니까 일본의 경기도라고 하는 가나가와현을 가서 실제로 의회 관계자들과 부지사님하고 얘기를 들어보니까 일본도 굉장히 심각합니다. 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네, 그렇습니다.
</p>
<p><b>○ 장동일 위원 </b> 가나가와현은 거의 도쿄 중심부인데도, 인근에 굉장히 가까운 곳인데도 여러 가지 문제가 있어 가지고 그거를, 이제 약간 정상화돼 가고 있는데 그 시간이 굉장히 오래 걸렸다는 거지요. 그래서 그런 부분들이 우리가 참고해야 될 부분이라고 생각하고, 그다음에 마지막으로 짧게요. 경기도 분도에 관련해서는 어떻게 생각하세요?
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 분도에 관련돼서는 제가 2000년 초반 때부터 계속 들어왔던 얘기고 최근에도 가장 활발하게 진행이 되고 있는데 그것은 저희가 아직 연구한 바는 없습니다만 경기도와 경기도의회하고 같이 협력해서 한번 연구를 해야 되지 않을까…….
</p>
<p><b>○ 장동일 위원 </b> 부원장님 개인적으로는 어떻게, 분도 해야 됩니까, 아니면 더 광역화해서…….
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 저는 지금 고양시에 한 18년 살았고 지금 파주에 집을 두고 있습니다만 그쪽에 있는 사람들은 분도에 대한 갈망은 별로 없는 것 같습니다. 그래서 얼마큼 시너지 효과가 날지에 대해서는 저도 약간의 의문점을 가지고 있는 그런 상황입니다. 
</p>
<p><b>○ 장동일 위원 </b> 그러니까 하지 말자, 이대로.
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 그 문제는 제 소견이기 때문에, 의정부를 포함한 동두천, 양주, 연천 이쪽 지역 사람들은 상당히 많이 갈망하기 때문에…….
</p>
<p><b>○ 장동일 위원 </b> 분도 해야 된다고?
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네, 그쪽은 많이 갈망을 한다고 생각하기 때문에 논의를 거쳐서 해야 될 것으로 생각됩니다. 이쪽 서부지역은 별로 갈망하지 않고 있고 그렇기 때문에…….
</p>
<p><b>○ 장동일 위원 </b> 네, 알겠습니다. 수고하셨습니다. 이상입니다.
</p>
<p style="padding-left:2.4em">    (나득수 위원장대리, 이재준 위원장과 사회교대)
</p>
<p><b>○ 위원장 이재준 </b> 장동일 위원님 수고하셨습니다. 더 이상 질의하실 위원님 안 계십니까? 
</p>
<p style="padding-left:2.4em">    (「없습니다.」하는 위원 있음) 
</p>
<p><b>○ 박형덕 위원 </b> 하나만…….
</p>
<p><b>○ 위원장 이재준 </b> 박형덕 위원님. 
</p>
<p><b>○ 박형덕 위원 </b> 제가 집이 너무 멀다 보니까 이제 도착을 했어요. 그래서 저는 분도에 대해서 상당히 갈망하는 사람 중의 하나인데 우리 장동일 위원님이 지금 분도에 대해서 질의한 내용에 대해서 답변을 해 주셨는데 이 부분은 여기서 그렇게 할 부분은 아닌 것 같고 다음에 저희하고 한번 대화를 가져야 될 필요가 있을 것 같아요.
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네, 알겠습니다. 
</p>
<p><b>○ 박형덕 위원 </b> 제가 사실 오전에 와야 되는데 오전에 몸이 안 좋아서 이제 왔는데 질의를 늦게 하는 것에 대해서 죄송합니다. 
</p>
<p style="padding-left:1.2em">  130개 연구목록의 과제유형을 보니까 기본, 정책, 위탁, 수탁, 협약, 이슈&진단, GRI 현안대응, GRI 현안 브리프 등 다양한데 이게 각각 유형별로 어떤 차이가 있는 거예요?
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 우선 기본연구과제는 학술지에 게재를 의무화하고 있기 때문에 학술적 성격이 강한 과제를 의미하고요. 정책연구과제는 도나 도의회에서 필요한 정책적인 사항들을 저희가 체계적으로 연구하는 그런 과제입니다. 그리고 위탁연구과제는 저희 연구원에 전문분야가 없는 그런 분야를 외부 전문기관에게 위탁하는 그런 형태입니다. 예를 들면 재난이나 다문화, 에너지 그런 부분들을 저희 연구원에서 필요로 하는 분야인데 전문가가 없어서 다른 위원회에 위탁하는 그런 형태가 위탁과제고요. 수탁연구과제는 말씀한 바와 같이 외부에서 저희 연구기관과 같이 연구를 하는 그런 연구과제이고, 정책현안분석은 여러 가지가 있습니다만 이슈&진단은 저희 매주마다 현안을 잡아 가지고 그 현안에 대해서 빨리 대응하기 위해서 만드는 그런 게 하나 있겠고 그다음에 정책과제인데 과제로 하기보다 신속하게 대응하기 위해서 현안분석이나 현안대응으로 하는 그런 부분들이 있습니다. 
</p>
<p><b>○ 박형덕 위원 </b> 그런데 지난해만 해도 267개 연구목록이 있었는데 올해는 작년에 비해서 반으로 푹 줄어버렸어요. 그 이유가 있는 겁니까, 특별히? 
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 저희가 9월 말 현재 그렇게 반 정도밖에 안 나타났는데요. 저희가 작년, 재작년하고 경험해 보니까 올해도 9월 이후에 끝나는 과제들이 과반수가 됩니다. 그래서 10월, 11월, 12월에 끝나는 과제가 만약 끝나면 거의 작년도 수준으로 될 것으로 예상이 됩니다. 
</p>
<p><b>○ 박형덕 위원 </b> 그러면 연말 정도면 전년 수준하고 거의 비슷한 업무실적이 나온다 그런 내용이지요?
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네.
</p>
<p><b>○ 박형덕 위원 </b> 그러면 유형에서 보면 위탁하면 우리 연구원이 수행해야 될 거를 외부에다 위탁하는 건데 올해는 예년에 비해서 2건이 진행돼 있는데 이게 예년에 비해서 많이 줄어든 이유가 우리 의회에서 행정사무감사, 기타 등등 할 때 그런 부분인 겁니까? 그렇지 않으면 정말 위탁을, 정책과제를 수행해야 되는데 이런 부분에서 혹시 놓치는 부분이 또 있지 않아요?
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 우선 행정사무감사 때 지적사항들을 받아들였고요. 그다음에 저희가 꼭 필요한 것 두 가지만 선정해서 위탁을 내보냈습니다. 
</p>
<p><b>○ 박형덕 위원 </b> 올해 그러면 어느 부분을 위탁…….
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 세월호 관련해 가지고 유가족의 젠더와 가족유형에 따른 지원방안 그다음에 문화다양성 적용에 따른 경기도 다문화정책 발전방안…….
</p>
<p><b>○ 박형덕 위원 </b> 어느 거요?
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 경기도 다문화정책 발전방안 이 두 가지, 세월호하고 경기도 다문화 두 가지만 위탁으로 했습니다. 
</p>
<p><b>○ 박형덕 위원 </b> 어쨌든 2014년 이후 자료를 보니까 지금 거의 비슷하고 위탁연구를 줄이는 데도 한계가 아마 있는 것 같아요. 어쨌든 그런 구조적 문제가 좀 있기는 있지요? 그런 부분에 대해서. 그래서 어쨌든 경기도의회 행정사무감사의 위탁을 전문가가 있음에도 불구하고 이렇게 준 부분에 대해서 지적한 사항에 대해서 물론 정책을 따르는 부분에서는 긍정적으로 생각을 하지만 그래도 꼭 위탁을 줘야 될 경우가 있으면, 큰 정책이 있으면 외부기관에 보다 더 훌륭한 전문가들이 있잖아요?
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네.
</p>
<p><b>○ 박형덕 위원 </b> 그런 분들을 활용해서 우리 GRI연구소에서 더 좋은 정책을 내는 데, 그런 부분에 너무 집착하게 되면 실제 소탐대실이라고 큰 걸 놓칠 수 있으니까 그런 부분에서 적극 대응을 좀 해 주시고.
</p>
<p style="padding-left:1.2em">  저는 경기연구원이 어쨌든 대한민국에서 최고, 얼마 전에 여론조사를 하더라고요. 상당히 난 긍정적인 답변을 해 드렸는데 사실 경기도의 많은 정책과 과제를 많은 도민들에게 지금 내놓고 있어요. 또 그 지방자치단체에서도 상당히 큰 도움을 받고 있고. 그래서 좀 어렵고 힘들더라도 긍지와 자부심을 가지시고 열심히 해 주시기 바랍니다.
</p>
<p><b>○ 경기연구원장직무대행 김군수 </b> 네, 감사합니다. 열심히 하도록 하겠습니다.
</p>
<p><b>○ 박형덕 위원 </b> 이상입니다.
</p>
<p><b>○ 위원장 이재준 </b> 더 이상 질의하실 위원님이 안 계시므로 오늘 경기연구원 소관 업무에 대한 질의와 답변을 마치겠습니다. 
</p>
<p style="padding-left:1.2em">  위원 여러분 그리고 김군수 경기연구원 원장 직무대행을 비롯한 임직원 여러분! 장시간 열의를 갖고 행정사무감사에 임해 주신 위원 여러분과 행정사무감사를 위한 자료준비와 위원님들의 질의에 성심껏 답변해 주신 임직원 여러분께 감사를 드립니다. 
</p>
<p style="padding-left:1.2em">  그러면 이상으로 경기연구원 소관 사항에 대한 2017년도 행정사무감사를 모두 마치겠습니다. 
</p>
<p class=''ar''>(14시52분 감사종료)
</p>
<p><hr /></p>
<p><b>○ 출석감사위원(10명)
</b></p>
<p class=''aMan''>이재준나득수박형덕김영환양근서오완석이현호임채호장동일최춘식</p>
<p><b>○ 출석전문위원
</b></p>
<p class=''em15''>   수석전문위원 오태철
</p>
<p><b>○ 피감사기관참석자
</b></p>
<p><p class=''em15''>경기연구원장직무대행 김군수연구기획본부장 이정훈</p>
<p><p class=''em15''>경영본부장 이용환대외협력처장 박정란</p>
