insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'audit','[2016.11.07. 월요일] 경기연구원 — 기획재정위원회 2016년도 행정사무감사','<div class="box" style="margin-bottom:16px"><b>제9대 경기도의회 기획재정위원회</b> · 2016년도 행정사무감사(2016. 11. 02. ~ 2016. 11. 15.)<br>원문: <a href="https://kms.ggc.go.kr/cms/mntsViewer.do?mntsId=9630" target="_blank" rel="noopener" style="color:var(--primary);text-decoration:underline">경기도의회 회의록 뷰어에서 보기</a></div><p>2016년도 행정사무감사
</p>
<h4>기획재정위원회 회의록
</h4>
<p class=''ar''>경기도의회사무처
</p>
<p><hr /></p>
<p>피감사기관 : 경기연구원
</p>
<p><hr /></p>
<p>일  시 : 2016년 11월 7일(월)
</p>
<p>장  소 : 경기연구원 회의실
</p>
<p><hr /></p>
<p class=''ar''>(14시02분 감사개시)
</p>
<p><b>○ 위원장 이재준 </b> 좌석을 정돈하여 주시기 바랍니다. 성원이 되었으므로 지금부터 지방자치법 제41조, 동법 시행령 제39조 및 경기도의회 행정사무감사 및 조사에 관한 조례 제2조의 규정에 의하여 경기연구원에 대한 2016년도 행정사무감사를 시작하겠습니다.
</p>
<p style="padding-left:1.2em">  위원 여러분 그리고 경기연구원장을 비롯한 임직원 여러분! 안녕하십니까? 경기도의회 기획재정위원회 감사위원장 이재준 위원입니다. 오늘은 우리 위원회의 감사일정에 따라 경기연구원에 대한 행정사무감사를 실시하게 되었습니다.
</p>
<p style="padding-left:1.2em">  여러분께서도 잘 아시는 바와 같이 우리 의회의 행정사무감사는 경기도의 행정사무 전반에 관한 실태를 정확히 파악하여 의정활동에 반영하고 도민의 삶의 질 향상에 기여하고자 함이 목적이므로 매우 중요한 의미가 있다고 하겠습니다. 오늘은 경기도의 싱크탱크인 경기연구원의 운영실태를 감사하는 것인 만큼 연구원에 대한 심도 있는 감사활동으로 경기도 발전을 위한 정책대안이 제시될 수 있도록 위원 여러분들의 적극적인 감사활동을 부탁드립니다. 아울러 감사에 임하는 원장과 임직원 여러분께서도 이와 같은 목적이 달성될 수 있도록 적극 협조해 주시기 바랍니다.
</p>
<p style="padding-left:1.2em">  그러면 감사를 시작하기 전에 증인선서를 받도록 하겠습니다. 감사를 받는 원장 및 부원장, 본부장, 실장, 부장은 증인의 자격으로 소관 업무를 보고하고 질의에 답변하기에 앞서 먼저 선서를 하셔야 합니다.
</p>
<p style="padding-left:1.2em">  증인선서의 취지와 관계 규정을 말씀드리면 선서를 하는 이유는 이번에 경기도의회가 2016년도 행정사무감사를 실시함에 있어서 증인으로부터 양심에 따라 숨김없이 사실대로 증언하겠다는 서약을 받기 위한 것입니다. 만약 증인이 허위증언을 한 때에는 지방자치법 제41조제5항 및 경기도의회 행정사무감사 및 조사에 관한 조례 제30조의 규정에 의하여 고발될 수 있습니다. 또한 증언 또는 진술을 거부한 때에는 동법 규정에 의하여 500만 원 이하의 과태료가 부과될 수 있음을 알려드립니다.
</p>
<p style="padding-left:1.2em">  그러면 먼저 증인 출석여부를 확인하겠습니다. 증인들께서는 모두 자리에서 일어나 주시기 바랍니다.
</p>
<p style="padding-left:1.2em">  경기연구원장 나왔습니까?
</p>
<p><b>○ 경기연구원장 임해규 </b> 네.
</p>
<p><b>○ 위원장 이재준 </b> 경기연구원 부원장 나왔습니까?
</p>
<p><b>○ 부원장 이상훈 </b> 네.
</p>
<p><b>○ 위원장 이재준 </b> 경영기획본부장 나왔습니까?
</p>
<p><b>○ 경영기획본부장 이상대 </b> 네.
</p>
<p><b>○ 위원장 이재준 </b> 대외협력처장 나왔습니까?
</p>
<p><b>○ 대외협력처장 이병관 </b> 네.
</p>
<p><b>○ 위원장 이재준 </b> 북부연구센터장 나왔습니까?
</p>
<p><b>○ 북부연구센터장 김동성 </b> 네.
</p>
<p><b>○ 위원장 이재준 </b> 연구기획실장 나왔습니까?
</p>
<p><b>○ 연구기획실장 유영성 </b> 네.
</p>
<p><b>○ 위원장 이재준 </b> 공존사회연구실장 나왔습니까?
</p>
<p><b>○ 공존사회연구실장 이용환 </b> 네.
</p>
<p><b>○ 위원장 이재준 </b> 공감도시연구실장 나왔습니까?
</p>
<p><b>○ 공감도시연구실장 이외희 </b> 네.
</p>
<p><b>○ 위원장 이재준 </b> 상생경제연구실장 나왔습니까? 
</p>
<p><b>○ 상생경제연구실장 김군수 </b> 네.
</p>
<p><b>○ 위원장 이재준 </b> 휴먼교통연구실장 나왔습니까? 
</p>
<p><b>○ 휴먼교통연구실장 지우석 </b> 네.
</p>
<p><b>○ 위원장 이재준 </b> 생태환경연구실장 나왔습니까? 
</p>
<p><b>○ 생태환경연구실장 이기영 </b> 네.
</p>
<p><b>○ 위원장 이재준 </b> 연구지원부장 나왔습니까?
</p>
<p><b>○ 연구지원부장 배미성 </b> 네.
</p>
<p><b>○ 위원장 이재준 </b> 행정지원부장 나왔습니까?
</p>
<p><b>○ 행정지원부장 이용원 </b> 네.
</p>
<p><b>○ 위원장 이재준 </b> 재정지원부장 나왔습니까?
</p>
<p><b>○ 재정지원부장 박인숙 </b> 네.
</p>
<p><b>○ 위원장 이재준 </b> 대외ㆍ의정부장 나왔습니까?
</p>
<p><b>○ 대외ㆍ의정부장 이덕환 </b> 네.
</p>
<p><b>○ 위원장 이재준 </b> 다음은 선서의 요령을 설명드리겠습니다. 선서는 전체 증인을 대표하여 경기연구원장이 발언대에 나오셔서 오른손을 들고 선서문을 낭독하시고 다른 증인들께서는 자리에 서서 오른손만 들어주시면 됩니다.
</p>
<p style="padding-left:1.2em">  그러면 선서를 해 주시기 바랍니다.
</p>
<p><b>○ 경기연구원장 임해규 </b> 선서! 본인은 경기도의회가 지방자치법 제41조, 같은 법 시행령 제39조제1항, 경기도의회 행정사무감사 및 조사에 관한 조례 제2조에 따라서 소관 업무에 대한 2016년도 행정사무감사를 실시함에 있어 기관장으로서 성실하게 감사를 받을 것이며 또한 증인으로서 증언을 함에 있어서는 지방자치법 시행령 제43조제5항과 경기도의회 행정사무감사 및 조사에 관한 조례 제19조에 따라 양심에 따라 숨김과 보탬이 없이 사실 그대로 말하고 만일 거짓이 있으면 위증의 벌을 받기로 서약하고 이에 선서합니다. 2016년 11월 7일 경기연구원장 임해규.
</p>
<p><b>○ 위원장 이재준 </b> 모두 자리에 앉아 주시기 바랍니다.
</p>
<p style="padding-left:1.2em">  그러면 경기연구원장 나오셔서 간부소개와 업무보고를 간략하게 해 주시기 바랍니다. 
</p>
<p><b>○ 경기연구원장 임해규 </b> 경기연구원장 임해규입니다. 오늘 경기도의회 기획재정위원회 행정사무감사에 존경하는 이재준 위원장님과 위원님들을 모시고 연구원의 주요 업무보고를 드리게 되어 감사의 말씀을 드립니다. 우리 연구원은 경기도의 싱크탱크로서 경기도민의 삶의 질 향상을 위해 경기도정 현안을 해결하고 경기도 미래비전을 제시하는 등 임직원 모두가 열정을 다해 정책개발을 추진해 가고 있습니다. 향후에도 연구원의 발전을 위하여 기획재정위원회 위원님들의 많은 관심과 성원을 부탁드립니다.
</p>
<p style="padding-left:1.2em">  그러면 보고에 앞서 연구원의 주요 간부를 소개해 드리겠습니다.
</p>
<p style="padding-left:1.2em">  먼저 이상훈 부원장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  이상대 경영기획본부장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  이병관 대외협력처장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  김동성 북부연구센터장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  유영성 연구기획실장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  이용환 공존사회연구실장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  이외희 공감도시연구실장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  김군수 상생경제연구실장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  지우석 휴먼교통연구실장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  이기영 생태환경연구실장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  배미성 연구지원부장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  이용원 행정지원부장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  박인숙 재정지원부장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  이덕환 대외ㆍ의정부장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  이상으로 간부소개를 마치고 지금부터 연구원의 주요업무를 보고드리겠습니다. 배부해 드린 보고자료의 목차를 봐 주시기 바랍니다. 보고순서는 기본현황, 민선6기 3년간 주요 연구성과, 2016년 상반기 주요성과, 2017년 주요 사업계획 순입니다. 
</p>
<p style="padding-left:1.2em">  먼저 1쪽의 기본현황입니다. 저희 연구원은 1995년에 개원하여 경기도의 중장기 비전 제시와 정책개발 기능을 수행하고 있습니다. 연구원 조직은 1본부, 1처, 1센터, 6실, 4부로 구성되어 있으며 자료를 참조해 주시기 바랍니다.
</p>
<p style="padding-left:1.2em">  우리 원의 인력은 원장 1명, 부원장 1명, 연구직 56명, 관리ㆍ정보ㆍ기능직 20명으로 78명의 정규직원과 계약직원 93명 등 총 171명이 근무하고 있습니다.
</p>
<p style="padding-left:1.2em">  다음은 2쪽 주요기능이며 자료 참조하여 주시기 바랍니다.
</p>
<p style="padding-left:1.2em">  3쪽 예산현황에 대해 보고드리겠습니다. 올해의 총 예산규모는 235억 원으로 일반회계 185억 원, 수탁용역사업특별회계 50억 원입니다.
</p>
<p style="padding-left:1.2em">  일반회계의 수입 지출내역을 말씀드리겠습니다. 수입항목은 경기도 출연금이 전체의 64.6%인 120억 원으로 가장 많습니다. 지출항목은 인건비가 45%인 84억 원으로 가장 많고 연구사업비가 77억 원으로 전체 41% 정도 차지하고 있습니다.
</p>
<p style="padding-left:1.2em">  다음은 민선6기 3년간 주요 연구성과에 대해 보고드리겠습니다. 보고자료 4쪽부터 5쪽이 되겠습니다.
</p>
<p style="padding-left:1.2em">  우리 연구원은 지난 3년간 연구역량 강화를 위한 기본연구와 미래ㆍ융합ㆍ현장 연구 차원의 전략연구 비중이 증가하였습니다. 도정발전 및 자립경영을 위한 지속적인 수탁과제를 수행하고 있습니다. 민선6기 3년간 총 368건의 정책이나 사업이 도정에 반영되었습니다. 도정반영 사업은 별도 자료로 배부해 드렸습니다.
</p>
<p style="padding-left:1.2em">  다음은 5쪽 주요연구 현황입니다. 구체적인 내용은 자료를 참조해 주시기 바랍니다.
</p>
<p style="padding-left:1.2em">  다음은 2016년 상반기 주요성과에 대해 보고드리겠습니다. 보고자료 6쪽부터 10쪽이 되겠습니다.
</p>
<p style="padding-left:1.2em">  먼저 6쪽의 2016년 상반기 주요 연구성과입니다. 10월 31일 기준으로 연구과제 및 정책현안분석이 279건으로 신규 추진하고 있습니다. 이는 2016년 계획 대비 85.8%에 해당합니다. 또한 정책현안분석을 통해 미세먼지, 청년지원, 복지비 지출 등 도정 주요이슈에 역점을 두고 대응하고 있습니다.
</p>
<p style="padding-left:1.2em">  다음은 7쪽 주요 연구현황입니다. 구체적인 내용은 자료를 참조해 주시기 바랍니다.
</p>
<p style="padding-left:1.2em">  다음은 8쪽 경기도 의뢰 단기정책과제 현황입니다. 경기도 집행부 및 경기도의회 단기정책과제는 총 50건 중 46건이 채택되었습니다. 그중 경기도의회에서 의뢰한 건수는 단기정책과제 6건, 수탁과제 2건 등 총 8건입니다.
</p>
<p style="padding-left:1.2em">  다음은 9쪽 2016년 상반기 경영부문 주요성과에 대해 보고드리겠습니다. 2016년 상반기 주요성과는 크게 미래ㆍ융합ㆍ현장 연구, 연구교류 및 성과공유 확대, 자율적인 조직으로 위상 정립 이렇게 세 가지로 구분하여 보고드리겠습니다.
</p>
<p style="padding-left:1.2em">  먼저 미래ㆍ융합ㆍ현장 연구 분야입니다. 첫 번째, 환경변화에 대응한 사업목표 및 전략을 변경하였습니다. 두 번째, 지역균형 발전을 위한 경기 동부지역 발전에 적극적으로 대응하고 있습니다. 세 번째, 종단연구 활용을 통한 경기도민 밀착형 연구를 확대해 나가고 있습니다. 네 번째, 종합적 연구역량 강화를 위한 전략연구과제를 강화하고 있습니다. 다섯 번째, 지진재해 등과 같은 전문성이 필요한 부분에 대해 위탁과제를 추진하고 있습니다. 
</p>
<p style="padding-left:1.2em">  다음으로 연구교류 및 성과공유 확대 분야입니다. 첫 번째, 경기도 공공기관과의 MOU 체결 및 연구교류 확대를 추진하고 있습니다. 두 번째, 기본연구 성과의 전문학술지 게재 의무화 등 학술연구를 확대하고 있습니다. 세 번째, 의정연구교류, 초청특강, 정책포럼 등 연구원 행사 참여를 확대하고 있습니다. 네 번째, 경기도 공공외교 뒷받침 차원의 GBC 소재 국제연구기관과의 학술교류를 추진 중에 있습니다. 다섯 번째, 사회적 책임 강화를 위해 도내 중ㆍ고등학생을 대상으로 G.G Talk Talk 프로그램을 운영하고 있으며 9월 말 현재 21개 주제, 67회 강의가 완료되었습니다. 여섯 번째, 영문홈페이지 개설 등 다양한 콘텐츠 활용을 통한 홍보를 강화하고 있습니다. 특히 2016년 제6회 대한민국 SNS 대상에서 경기연구원은 연구부문 최우수상을 수상한 바 있습니다. 
</p>
<p style="padding-left:1.2em">  마지막으로 자율적인 조직으로 위상 정립 분야입니다. 첫 번째, 홍보ㆍ정보팀을 연구기획실 내 신설하고 대외ㆍ의정부 신설 등의 조직개편으로 조직의 효율성을 강화하였습니다. 두 번째, 연구원ㆍ행정원 보수제도를 개선하여 석사연구원의 처우를 개선하였습니다. 세 번째, 유연근무제도, 동호회 활성화 등을 통해 연구 및 근로여건을 개선하고자 하였습니다. 네 번째, 연구윤리포럼 참석, 청탁금지법 행동강령 시행을 위한 원내 지침 정비를 통해 연구윤리를 강화하고 있습니다. 다섯 번째, 석사급 연구원의 학술기회 제공 및 학술지 논문 게재료 지원 등을 통해 학술활동을 장려하고 있습니다.
</p>
<p style="padding-left:1.2em">  다음은 11쪽의 2017년 주요 업무계획입니다. 먼저 우리 연구원은 ‘더 큰 경기도를 꿈꾸는 희망발전소 GRI’라는 비전 아래 중장기 목표로 세계수준의 정책연구기관 토대 마련, 미래 혁신적 가치를 창출하는 지식플랫폼 구축, 지속가능한 자립경영기반 조성을 설정하였습니다. 또한 중장기 목표를 이루기 위해 미래ㆍ융합ㆍ현장 연구, 연구교류 및 성과공유 확대, 자율적인 조직으로의 위상 정립 이렇게 세 가지로 경영목표를 설정하였습니다.
</p>
<p style="padding-left:1.2em">  다음은 12쪽 2017년 주요 업무계획 중에서 연구분야 부문입니다. 2017년 주요업무 계획상 기본과제, 정책과제, 정책현안분석 등 총 235개 연구과제를 추진할 예정입니다. 정책과제, 정책현안분석 중점으로 연구를 추진할 예정입니다. 
</p>
<p style="padding-left:1.2em">  다음은 각 부서별 계획에 대해 보고드리겠습니다. 보고자료 13쪽부터 21쪽이 되겠습니다.
</p>
<p style="padding-left:1.2em">  먼저 공존사회연구실입니다. 주요 역점 연구분야는 경기도민의 복지수요에 부응하는 정책개발 및 시스템 구축입니다. 특히 미래지향적 사회구조와 정부 간 관계 정립 등을 연구하고 있습니다. 연구과제 목록은 자료를 참고해 주시기 바랍니다.
</p>
<p style="padding-left:1.2em">  다음은 공감도시연구실입니다. 역점 연구분야는 경기도민의 삶의 질 향상과 지역경쟁력 제고입니다. 특히 임대주택, 도시재생, 비도시지역 관리, 빅데이터 등을 연구하고 있습니다. 연구과제 목록은 자료를 참조해 주시기 바랍니다.
</p>
<p style="padding-left:1.2em">  다음은 상생경제연구실입니다. 주요 역점 연구분야는 경제와 사회문화의 융합 발전입니다. 특히 창업생태계, 수도권규제, 미래융복합산업, 미래형 문화관광산업 등을 연구하고 있습니다. 구체적인 목록은 자료를 참고해 주시기 바랍니다.
</p>
<p style="padding-left:1.2em">  다음은 휴먼교통연구실입니다. 역점 연구분야는 편리하고 효율적인 수도권 광역교통체계 구축입니다. 특히 교통안전시설, 차세대 교통통신 인프라, 미래교통수단을 연구하고 있습니다. 구체적인 연구과제 목록은 자료를 참고해 주시기 바랍니다.
</p>
<p style="padding-left:1.2em">  다음은 생태환경연구실입니다. 역점 연구분야는 경기도의 지속가능한 발전과 삶의 질 향상입니다. 특히 물관리, 그린인프라, 기후변화대응, 공중보건 향상 등을 연구하고 있습니다. 구체적인 연구과제 목록은 자료를 참고해 주시기 바랍니다.
</p>
<p style="padding-left:1.2em">  다음은 북부연구센터입니다. 역점 연구분야는 경기북부의 지역발전 지원 및 한반도 통일시대 대비입니다. 특히 경기북부 비전, 지역균형 발전 및 낙후지 개발 등을 연구하고 있습니다. 연구과제 목록은 자료를 참고해 주시기 바랍니다. 
</p>
<p style="padding-left:1.2em">  다음은 19쪽 연구부대사업 부문으로 정책세미나포럼, 동향분석과 전망, 학술지 발간, 콘텐츠 홍보, 의정연구교류, 대외협력교류 등을 계획하고 있습니다.
</p>
<p style="padding-left:1.2em">  다음은 20쪽 연구지원사업 부문으로 정보자원 지원, 전산사업, GIS사업을 추진할 계획입니다.
</p>
<p style="padding-left:1.2em">  다음은 21쪽 연구기반사업 부문으로 연구인력 아웃소싱, 인적자원 개발, 연구기획 및 평가를 추진할 계획입니다.
</p>
<p style="padding-left:1.2em">  다음으로 2017년 주요 업무계획 중에서 경영분야 부문입니다. 2017년 주요 업무계획상 세 가지 경영목표인 미래ㆍ융합ㆍ현장 연구, 자율적인 조직으로 위상 정립, 연구교류 및 성과공유 확대를 토대로 전략과제를 설정하였습니다. 
</p>
<p style="padding-left:1.2em">  먼저 미래ㆍ융합ㆍ현장 연구 추진의 경우 도 미래발전 연구, 현장ㆍ시계열 융복합 연구를 토대로 사업을 계획하였습니다. 도 미래발전 연구에서는 지역균형 발전을 위한 경기도 내 비전 설정을 위해 전략ㆍ기획 사업을 추진할 계획입니다. 또한 현장ㆍ시계열 융복합 연구 지원 강화의 경우에는 경기도 사회조사 DB를 활용한 학술대회를 개최할 예정입니다.
</p>
<p style="padding-left:1.2em">  다음으로 연구교류 및 성과공유 확대의 경우 지식공유 생태계 구축을 위한 연구의 질적 제고, 대외소통 강화, 지역현안분석 및 전파 확대, 도민과 직접 소통하는 연구, 국제 산학연관 공동연구 추진체계 구축을 계획하였습니다. 특히 경기도 산하 공공 연구기관과의 협력적 연구 확대를 통해 대외소통을 강화할 예정입니다. 또한 뉴스레터 발송, 연구원 블로그 확대 이용 등을 통해 보다 다양한 콘텐츠를 활용하여 도민과의 지속적인 소통창구를 마련하고자 하였습니다.
</p>
<p style="padding-left:1.2em">  마지막으로 자율적인 조직으로 위상 정립의 경우 조직문화의 개선, 역량의 강화를 계획하였습니다. 특히 연구기관이라는 조직적 특성상 연구원의 자기계발 및 연구윤리 강화에 중점을 두려고 하였습니다.
</p>
<p style="padding-left:1.2em">  다음 25쪽의 2016년 신규 착수 연구목록과 37쪽의 3년간 도의회 요청과제 현황, 38쪽의 2015년 행정사무감사 처리요구사항 조치결과는 허락해 주시면 자료로 대신토록 하겠습니다.
</p>
<p style="padding-left:1.2em">  이상으로 연구원의 주요업무보고를 모두 마치겠습니다. 경청해 주셔서 감사합니다.
</p>
<p><hr /></p>
<p>업무보고서(경기연구원)
</p>
<p><hr /></p>
<p><b>○ 위원장 이재준 </b> 원장님 수고하셨습니다. 다음은 감사를 위한 질의 답변 순서가 되겠습니다. 감사의 효율적인 진행을 위하여 질의는 일문일답으로 하되 질의시간을 제한하도록 하겠습니다. 우선 위원님 한 분당 10분씩 시간을 드리고 추가질의는 5분을 드리도록 하겠습니다. 그리고 5분의 추가질문이 끝나면 감사 진행상황과 시간 등 제반 여건을 감안해 추가질문을 계속할지 여부를 결정하도록 하겠습니다. 원활한 감사 진행을 위해 부득이 시간을 제한하게 된 점을 널리 양해해 주시면 고맙겠습니다. 만약 시간 제약으로 준비하신 질의를 미처 다 하지 못하신 위원님께서는 추후 서면으로 질의가 가능하오니 이를 활용해 주시기 바랍니다. 또 위원님들의 질의에 대하여 원장의 답변이 어려울 경우 업무 담당 실장 및 부장 등 실무자가 답변해도 좋습니다. 다만 사전에 위원장에게 동의를 얻은 후 발언대로 나와 소속과 직, 성명을 분명히 밝히고 답변해 주시기 바랍니다.
</p>
<p style="padding-left:1.2em">  그럼 질의하실 위원님께서는 거수로 신청하여 주시기 바랍니다.
</p>
<p><b>○ 오완석 위원 </b> 자료 먼저 신청하겠습니다.
</p>
<p><b>○ 위원장 이재준 </b> 네. 
</p>
<p><b>○ 오완석 위원 </b> 자료가 있는지 모르겠는데 혹시 외부에 위탁한 연구현황이 있는지. 있으면 3년간 것을 주시고요. 그다음에 초빙연구원 급여현황도 3년간 해서 토털금액하고 연구과제에 따른 수행비라든가 이런 게 있으면 급여와 관련된 부분을 주시면 좋겠고요.
</p>
<p><b>○ 경기연구원장 임해규 </b> 네.
</p>
<p><b>○ 오완석 위원 </b> 그다음에 초빙연구원을 연구원 부서장이나 또는 경기도지사가 추천하기로 했는데 그 추천현황 알 수 있을까요? 추천현황 좀 부탁드리겠고요.
</p>
<p><b>○ 경기연구원장 임해규 </b> 네.
</p>
<p style="padding-left:2.4em">    (자료를 들어 보이며)
</p>
<p><b>○ 오완석 위원 </b> 그다음에 이거 연구과제물인데요. 고양형 대중교통체계 개편 연구용역 이 결과물이 나왔는지 모르겠습니다. 나왔으면 아마 책자로 되어 있을 것 같은데 그걸 하나 주시고요.
</p>
<p><b>○ 경기연구원장 임해규 </b> 네.
</p>
<p><b>○ 오완석 위원 </b> 그다음에 의왕시 청소년육성재단 설립 타당성 검토용역 이것도 아마 보고서 나왔을 거예요. 이것도 주시면 되겠습니다. 이상입니다.
</p>
<p><b>○ 경기연구원장 임해규 </b> 네, 알겠습니다.
</p>
<p><b>○ 위원장 이재준 </b> 추가로 자료 요청하실 위원님, 양근서 위원님.
</p>
<p><b>○ 양근서 위원 </b> 세부적으로 목록은 말씀 안 드리겠는데 오전 중에 추가로 요청했던 자료들이 있습니다. 행정지원부장님, 재정지원부장님 그리고 연구지원부장님 그거 준비됐습니까? 곧바로 제출해 주시기 바랍니다.
</p>
<p><b>○ 위원장 이재준 </b> 추가로 자료 요청하실 위원님 안 계십니까?
</p>
<p style="padding-left:2.4em">    (「없습니다.」하는 위원 있음)
</p>
<p style="padding-left:1.2em">  그러면 질의하실 위원님, 임채호 위원님.
</p>
<p><b>○ 임채호 위원 </b> 연구교류 및 성과공유 확대라고 그래서 경기도 공공기관과의 MOU 체결이 있습니다. 그 MOU 체결해서 연구교류, 확대 추진을 했는데 그 성과라든가 MOU 체결했던 것 각 공공기관하고 자료 좀 제출해 주시고……. 
</p>
<p><b>○ 경기연구원장 임해규 </b> 위원님, 지금 그걸 추진 중에 있어서 아직까지 체결은 하지 않고 실무자회의까지 마친 상태입니다.
</p>
<p><b>○ 임채호 위원 </b> 기존 MOU 체결은 안 됐더라도 업무협약이라든가 이런 거 맺은 것도 아직 없습니까?
</p>
<p><b>○ 경기연구원장 임해규 </b> 실무 차원에서만 의향이 오갔습니다. 그래서 원장들이 조만간 모여서 MOU를 체결할 예정입니다.
</p>
<p><b>○ 임채호 위원 </b> 체결 아직은 안 돼 있고?
</p>
<p><b>○ 경기연구원장 임해규 </b> 네.
</p>
<p><b>○ 임채호 위원 </b> 잘 알았습니다. 
</p>
<p><b>○ 위원장 이재준 </b> 그러면 질의하실 위원님, 이현호 위원님 질의해 주시기 바랍니다.
</p>
<p><b>○ 이현호 위원 </b> 이현호 위원입니다. 우리 원장님과 또 모든 직원 여러분들 행정사무감사 준비하시느라 수고 많이 하셨습니다. 
</p>
<p style="padding-left:1.2em">  업무보고서 25쪽을 제가 보니까 연구의 목록이 있습니다. 267개 연구목록에 보면, 과제의 유형을 보면 기본, 정책, 위탁, 수탁, 협약, 이슈&진단 또 GRI 현안대응, GRI 현안브리프 등으로 다양한데 각각 유형별로 차이가 어떤 게 있습니까? 
</p>
<p><b>○ 경기연구원장 임해규 </b> 저희들이 수행하는 연구과제 종류가 일단 위원님들이 보시기에 한 100쪽에서 200쪽 사이되는 이런 책자형식으로 돼 있는 것은 기본연구, 정책연구, 전략연구, 수탁연구 이렇게 보실 수 있습니다, 두꺼운 것들은. 그리고 한 10쪽에서 20쪽 정도 유인돼서 의원님들한테 발송 드리는 이슈&진단이라는 것은 서술도 개조식으로 돼 있고요. 그런 형식이 있고 현안브리프 같은 경우는 아주 짧은, A4용지로 5장 내외의 것으로 되어 있습니다. 그래서 그거는 부차적인 연구물이고 저희 주 연구물 한 3개월, 4개월 또는 6개월, 1년 단위로 걸리는 연구물이 저희 주 연구물입니다. 그런데 그거는 기본연구는 그 과제를 가장 많이 하는 것은 정책연구입니다, 보통정책연구. 그거는 도나 시군이나 혹은 의원님들께서 의뢰를 하실 경우에 저희들이 수행하는 연구이고 그것이 가장 많은 양을 저희들이 하고 있습니다. 그리고 기본연구는 박사들이 학문적인 어떤 수준을 유지하고 또 자기 개인의 관심 있는 연구를 하기 위해서 수행하는 연구입니다. 그런데 그거는 많이 하지는 않고 1년에 10건 좀 안 되는 정도로 연구를 그간 수행해 왔습니다. 그리고 수탁연구는 저희들이 가지고 있는 예산으로 수행하는 것이 아니고 별도로 경기도나 산하시군 혹은 공공기관과 협약을 맺어서 저희들이 수탁을 받습니다, 별도로 돈을 받고. 그렇게 해서 수행하는 연구가 수탁연구가 되겠습니다. 그래서 각각 발주하는 기관의 성격이 좀 다르고 연구를 하는 목적이 서로 간에 좀 다른 사항입니다.
</p>
<p><b>○ 이현호 위원 </b> 유형에서 보면 위탁이 있는데 위탁은 연구원이 수행하는 과제를 보다 전문성을 지닌 다른 연구기관에 의뢰합니까, 그럼? 
</p>
<p><b>○ 경기연구원장 임해규 </b> 그렇습니다. 저희 박사들이 수행하기에는 그 과제가 좀 적절하지 않다고 판단이 드는데 연구과제는 의뢰가 여러 곳에서 있을 경우에 저희들이 다른 곳에 위탁을 주는 연구입니다. 예를 들면 이번에 지진이 올해 굉장히 심각한 사회문제가 되었는데 아직까지 우리가 지진연구를 할 수 있는 내부 박사는 없기 때문에 그와 관련된 연구를 예를 들면 신속히 외부에 있는 전문가에게 맡겨서 연구를 부탁하는 게 그런 사례입니다.
</p>
<p><b>○ 이현호 위원 </b> 올해도 위탁연구 6건이 진행 중에 있어요. 그렇죠, 원장님?
</p>
<p><b>○ 경기연구원장 임해규 </b> 네, 그렇습니다. 
</p>
<p><b>○ 이현호 위원 </b> 지난번 행정감사에서도 가능하면 위탁연구를 하지 말라고 지적을 했었죠? 
</p>
<p><b>○ 경기연구원장 임해규 </b> 그렇습니다. 
</p>
<p><b>○ 이현호 위원 </b> 14년도, 15년도에는 줄었는데 16년도에는 또 2건이 더 늘었어요, 오히려. 지지난번 감사 때에 지적했더니 지난해에는 2건 줄었더니 이번에는 2건이 또 늘었어요, 그죠? 
</p>
<p><b>○ 경기연구원장 임해규 </b> 저희들이 예산서에는 4건으로 잡혀 있는데 6건을 하고 있습니다. 
</p>
<p><b>○ 이현호 위원 </b> 6건, 네. 그러니까 14년도 6건, 15년도 4건 또 금년도에는 6건이 됐거든요. 해마다 비슷한 건수의 수탁연구가 이루어지고 있는데 위탁연구를 줄이는 데 한계 없습니까? 구조상 문제가 있나요, 줄이는 데?  
</p>
<p><b>○ 경기연구원장 임해규 </b> 사실 4건으로 애초에 기획을 한 것이 사실은 막상 제가 2년간 운영을 해 보니까 사실 4건을 가지고는 수요에 대응을 못하는 측면이 좀 있는 것 같습니다. 그래서 저희들이 불가피하게 한 6건 이번 주게 되었는데요. 주게 된 성격이 보시게 되면 방금 오완석 위원님께서도 자료요청을 하셨습니다마는 저희들이 예를 들면 수원-인천, 그러니까 수인선변의 공동체 문화, 문화유적이나 또는 그런 문화연구가 1건이 있고요. 그리고 세월호 사고피해자 유가족 생활실태 및 심리상태에 관한 조사도 있습니다. 이와 같은 연구들은 제목을 벌써, 그리고 조금 아까 말씀드린 지진 재해 대응에 대한 정책방향 연구나 이와 같은 것들이 사실 저희 연구원에 이런 아주 구체화된 분야를 저희들이 공동연구를 하면서 배워서 앞으로는 이런 연구도 해야 되겠지만 사실 당장 하기가 어려워서 저희들이 불가피하게 위탁을 줄 수밖에 없어서 저희들로서는 좀 위원님들의 지적에 대해서 알고 있습니다만 그대로 시행하기 좀 어려운 점이 있었습니다. 이해해 주시면 좋겠습니다. 
</p>
<p><b>○ 이현호 위원 </b> 연구를 위탁 주게 되면 그만큼 우리가 위탁비가 나가고 또 아까 말씀드렸지만 우리 연구원 내에 연구직들이 많으신데 꼭 이렇게 전문성이 없다 해 가지고 외부로 주다 보니까 우리 예산이 예를 들어서 낭비되는 거 아닌가 이런 감이 들고. 지난번에 지적할 때는 분명히 지양해서 가능하면 외부에 위탁을 안 주겠다 이렇게 말씀하셨는데 이번에 또 늘었기 때문에 제가 이거를 지적하는 겁니다. 가급적 위탁연구는 지양하면서 내부 연구진의 전문성이 부족하거나 해당 분야의 전공자가 없는 경우 위탁연구가 불가피하겠지만 가능하면 우리 경기연구원이 주도적으로 연구를 주도하면서 필요시 외부전문가를 참여시키는 방식으로, 그렇잖아요. 우리가 하면서 필요시에 불러들여서 시작을 하고 좀 부족한 부분에 대해서는 외부전문가를 불러들여서 우리 자체 내에서 하면 어떻겠냐 이런 말씀을 다시 한 번 드리는데 여기에 대해서 어떻게 생각하십니까, 원장님?
</p>
<p><b>○ 경기연구원장 임해규 </b> 그런 방향으로 저희들이 추진하도록 그렇게 노력을 하겠습니다. 
</p>
<p><b>○ 이현호 위원 </b> 그리고요. 또 한 가지는 외부용역 금액증가에 대해서 제가 말씀을 드리겠는데 지난번 행정사무감사 할 때도 있었던 얘기인데 외부용역 금액이 증가하고 있어요, 계속. 보세요. 2014년도는 약 9억 7,600만 원 또 15년도에는 약 14억 4,800만 원, 금년도에는 무려 19억 260만 원이 증액이 됐습니다. 이처럼 계속해서 외부용역 금액이 증가되고 있는데 특별한 이유가 있습니까? 
</p>
<p><b>○ 경기연구원장 임해규 </b> 지금 위원님께서 지적하신 외부위탁용역은 조금 아까 제가 설명드린 우리 정책과제를 외부에 주는 그런 것이 아니고 지금 말씀하신 것은 저희들이 주로 외부로부터 수탁을 받은 연구들의 경우에는 주로 기술용역 같은 거는 외부에다가 다시 줍니다. 그러니까 저희들이 큰 용역을 받고 그 용역 중에 일부를 외부용역을 주는 겁니다. 그러니까 주로 어떤 것이 있냐 하면 설문조사를 한다거나 이런 조사를 하는, 주로 조사와 관련된 거를 주게 되는데 그게 이렇게 많이 는 거는 예를 들면 2016년 올해 같은 경우에 국토교통부가 수도권의 교통수요량 조사를 하게 되는데 그게 서울연구원, 경기연구원, 인천연구원 3개 연구원에게 공동으로 주었습니다. 그런데 그 준 용역이 시민들, 경기도민들에게 교통량을 실제로 조사하는 조사비용입니다. 10억이나 됩니다, 그게. 그러니까 여기 19억 중에 10억은 저희들이 연구를 위탁받았는데 그 연구가 대부분 조사연구라서 다시 조사기관한테 위탁을 또 준 것이죠. 그래서 이렇게 액수가 늘어난 것이기 때문에 저희들이 통상적으로 수행하는 저희들 연구비용이 는 것은 아닙니다. 그리고 이 연구위탁용역은 외부에다 준 것은 저희들이 수탁을 받은 그 수탁에 따르는 연구용역을 준 겁니다.
</p>
<p><b>○ 이현호 위원 </b> 그런데 거기에 따라 가지고 인건비도 늘어났더라고요, 그죠? 인건비도 보면 2014년도는 한 76억 500만 원, 2015년도에는 한 83억 또 2016년도에는 84억 이렇게 인건비도 계속 늘어나고 있는데 위 인건비에는 초빙연구원 등의 인건비도 포함됐습니까?
</p>
<p><b>○ 경기연구원장 임해규 </b> 그렇습니다.
</p>
<p><b>○ 이현호 위원 </b> 초빙연구원들의 인건비가?
</p>
<p><b>○ 경기연구원장 임해규 </b> 그렇습니다. 어떤 과제를 저희들이 수탁을 받으면 그 수탁을 받을 때 우리 내부 박사들만으로는 수행하기가 어렵기 때문에 그에 따르는 초빙연구원을 초빙박사를 저희들이 별도로 또 고용을 합니다. 그에 따르는 인건비입니다. 그러니까 수탁과제를 저희들이 많은 양을 받으면 그 양을 받은 것만큼 초빙연구원들도 늘어나니까 인건비도 자동으로 상승을 하게 되는 것이죠.
</p>
<p><b>○ 이현호 위원 </b> 잘 들었고요. 향후에는 반복되는 말씀이지만 부득이한 경우를 제외하고는 자체연구의 기조를 갖도록 해서, 그것이 연구원의 존재이유일 것입니다. 그렇지 않습니까? 우리 연구원이 많은데 위탁을 줘서 하는 것보다는 그래도 자체에서 움직여서 해야만 우리 연구원의 존재감이 있죠. 우리 연구원이 지금 몇 분 있죠, 연구직이?
</p>
<p><b>○ 경기연구원장 임해규 </b> 지금 저희들이 한 56명 정도 있습니다. 
</p>
<p><b>○ 이현호 위원 </b> 56명의 연구직이 있는데도 부득이하게 물론 어쩔 수 없이 외부위탁 하겠지만 가능하면 내부에서 소화시키는 게 낫지 않겠나 이렇게 말씀을 드리는데 어떻게 제 말씀에 동의하십니까? 
</p>
<p><b>○ 경기연구원장 임해규 </b> 그럼요. 거의 모든 연구는 사실 저희들이 다 하고 수탁연구의 경우도 저희 연구원이 책임연구원으로 수행을 하고 그 연구를 수행하는 최소한의 필요인원을 초빙으로 받아들이거나 이렇게 하는 것이기 때문에 그 원칙에는 저희들이 견지하고 있다고 생각합니다. 그런데 위원님 지적마따나 꼭 필요하지 않은 인력을 혹시 저희들이 그런 연구를 위탁을 주거나 또는 그런 인력을 저희들이 초빙으로 쓰거나 이러지 않을까 하는 걱정 때문에 그러시는데 그런 일이 없도록 저희들이 만전을 기해서 하도록 하겠습니다. 
</p>
<p><b>○ 이현호 위원 </b> 감사합니다. 이상입니다.
</p>
<p><b>○ 위원장 이재준 </b> 이현호 위원님 수고하셨습니다. 다음 질의하실 위원님, 나득수 위원님 질의해 주시기 바랍니다. 
</p>
<p><b>○ 나득수 위원 </b> 원장님, 감사 준비하시느라 노고가 많으십니다. 
</p>
<p><b>○ 경기연구원장 임해규 </b> 고맙습니다.
</p>
<p><b>○ 나득수 위원 </b> 부천 출신 나득수 위원입니다. 요구자료 191쪽을 보면요. 청탁금지법이 시행되고 있죠? 
</p>
<p><b>○ 경기연구원장 임해규 </b> 네. 
</p>
<p><b>○ 나득수 위원 </b> 그런데 우리 연구원들이 외부 겸임교수로 강의를 한다든가 외부특강을 많이 하고 있는 것으로 나타나요, 맞습니까? 
</p>
<p><b>○ 경기연구원장 임해규 </b> 네. 
</p>
<p><b>○ 나득수 위원 </b> 그런데 연구원도 청탁금지법 적용 대상이 맞습니까? 
</p>
<p><b>○ 경기연구원장 임해규 </b> 맞습니다. 
</p>
<p><b>○ 나득수 위원 </b> 그렇다면 연구원들 외부강의는 신고 대상인가요? 
</p>
<p><b>○ 경기연구원장 임해규 </b> 그렇습니다. 
</p>
<p><b>○ 나득수 위원 </b> 신고 절차와 연구원의 관리체계는 어떻게 돼 있습니까? 
</p>
<p><b>○ 경기연구원장 임해규 </b> 외부강의의 경우에는 저희들이 오래전부터 외부강의 할 경우에는 원장에게 사전 신고를 하도록 되어 있습니다. 그리고 저희 내부규정에 따라서 1회 강의를 할 수 있고 또 그것이 근무시간 내에 할 경우에는 반차, 연차의 반차를 쓰도록 그렇게 규정이 되어 있습니다. 
</p>
<p><b>○ 나득수 위원 </b> 그렇습니다. 그럼 우리 석사연구원들도 마찬가지입니까? 
</p>
<p><b>○ 경기연구원장 임해규 </b> 석사연구원 중에서도 있습니다. 
</p>
<p><b>○ 나득수 위원 </b> 그리고 강의료를 보면 1회 강의에 100만 원인 경우도 있어요. 그러면 청탁금지법에 제한되는 강의수수료보다 많은 경우도 있어요, 그죠? 100만 원 이상 된 것, 그렇죠? 
</p>
<p><b>○ 경기연구원장 임해규 </b> 저희가 파악한 바로는 1회 강의료가 많은 경우는 없는 걸로 알고 있고요. 보통 대학에 강의를 나갈 경우에는 한 15회 정도 하게 되니까요. 그 한 회의 강의료가 청탁금지법보다 많은 것은 없는 것으로 알고 있습니다마는 그와는 관계없이 외부강의는 일반적으로 말하는 외부에 가서 특강하는 그것과는 또 다르기 때문에요. 그거는 해당되는 그러니까 청탁금지법에 위배되는 경우는 없는 것으로 알고 있습니다. 
</p>
<p><b>○ 나득수 위원 </b> 그렇습니까? 그럼 청탁금지법 이후에 강의수수료는 어느 정도 수준인가요?  
</p>
<p><b>○ 경기연구원장 임해규 </b> 청탁금지법에는 저희가 1시간 이내에 30만 원에 그 이후 시간일 경우에는 그거에 50%를 가산한 금액 수준으로 알고 있습니다. 
</p>
<p><b>○ 나득수 위원 </b> 우리 연구원들은 30만 원 이상이다 이 말씀이신가요? 
</p>
<p><b>○ 경기연구원장 임해규 </b> 지금 저희들 그거를 평균을 내보지는 않았습니다마는 하여튼…….
</p>
<p><b>○ 나득수 위원 </b> 아직 정확한 규정은…….
</p>
<p><b>○ 경기연구원장 임해규 </b> 저희들 내부에 가지고 있는 규정은 20만 원으로, 상한액이 20만 원으로 되어 있습니다. 
</p>
<p><b>○ 나득수 위원 </b> 20만 원으로요?  
</p>
<p><b>○ 경기연구원장 임해규 </b> 그렇습니다. 임원의 경우에는 30만 원입니다. 
</p>
<p><b>○ 나득수 위원 </b> 그러니까 공직자 사례금 상한액에서 정하고 있는 것을 말씀하시죠? 
</p>
<p><b>○ 경기연구원장 임해규 </b> 그렇습니다. 
</p>
<p><b>○ 나득수 위원 </b> 기관장 40만 원, 임원 30만 원, 그 외 직원 20만 원. 
</p>
<p><b>○ 경기연구원장 임해규 </b> 그렇습니다.  
</p>
<p><b>○ 나득수 위원 </b> 우리 연구원들은 20만 원 정도다 이 말씀인 거죠? 그렇죠? 
</p>
<p><b>○ 경기연구원장 임해규 </b> 그렇습니다. 
</p>
<p><b>○ 나득수 위원 </b> 그동안에도 연구원들의 대외활동 관련이라든가 본연의 연구업무 소홀 그다음에 사적이익 추구 이런 여러 가지 문제점이 지적돼 왔습니다. 청탁금지법으로 이런 문제점들에 대한 관리감독이 더욱 중요해졌다는데 연구원의 대책은 무엇인가요? 세워놓고 있습니까, 대책은?
</p>
<p><b>○ 경기연구원장 임해규 </b> 저희들은 원래부터 외부강의에 대해서는 신고를 하게 했습니다. 김영란법 제정 이전에도 저희들이 했습니다. 그런데 그 금액은 이번에 김영란법에서 내려온 것과 사실 큰 차이가 없습니다만 김영란법으로 당연히 맞춰야 하니까요. 그렇게 맞추는 것으로 저희들이 지금 조정을 했습니다. 
</p>
<p><b>○ 나득수 위원 </b> 그러면 청탁금지법에 관련해서 직원들을 대상으로 교육을 실시한 적이 있어요?  
</p>
<p><b>○ 경기연구원장 임해규 </b> 외부에서, 경기도 평가담당관실에서도 와서 김영란법에 대해서 저희들에게 연수를 한 바가 있습니다. 
</p>
<p><b>○ 나득수 위원 </b> 위반사례라든가 신고 접수된 것은 있으신가요? 
</p>
<p><b>○ 경기연구원장 임해규 </b> 다시 말씀해 주…….
</p>
<p><b>○ 나득수 위원 </b> 위반사례, 신고사례. 
</p>
<p><b>○ 경기연구원장 임해규 </b> 아직은 저희들 위반사례 없습니다. 
</p>
<p><b>○ 나득수 위원 </b> 아무쪼록 연구원들의 청탁금지법 위반사례가 없도록 철저하게 제도 마련이나 교육을 당부드리겠습니다. 
</p>
<p><b>○ 경기연구원장 임해규 </b> 네. 대가기준을 초과해서 반환한 사례가 하나 있었습니다. 이건 위반한 사례가 아니라 어떤 연구원이 규정보다 좀 많은 것을 받아서 다 반환을 한 사례가 한 번 있습니다. 
</p>
<p><b>○ 나득수 위원 </b> 다음 질문드리겠습니다. 업무보고서 3쪽을 보면요. 연구원의 설립 및 운영에 필요한 자금을 충당하기 위해서 연구원의 경기연구원 육성기금을 설치하도록 되어 있죠? 
</p>
<p><b>○ 경기연구원장 임해규 </b> 네. 
</p>
<p><b>○ 나득수 위원 </b> 그러니까 우리 설립 및 운영 조례 제5조에 규정이 돼 있죠? 
</p>
<p><b>○ 경기연구원장 임해규 </b> 네. 
</p>
<p><b>○ 나득수 위원 </b> 경기연구원 육성기금 현재 조성된 규모는 어느 정도 됩니까? 
</p>
<p><b>○ 경기연구원장 임해규 </b> 지금 현재 121억이 남아 있습니다. 
</p>
<p><b>○ 나득수 위원 </b> 121억이요? 그러면 출자 재원이 도와 시군의 출연금을 재원으로 하고 있는 것 같아요, 그렇죠? 
</p>
<p><b>○ 경기연구원장 임해규 </b> 그렇습니다. 
</p>
<p><b>○ 나득수 위원 </b> 그러면 실제 시군의 출연이 많이 있는가요? 
</p>
<p><b>○ 경기연구원장 임해규 </b> 그 출연금을 최초에 모금할 당시에 저희들이 기금을 시군에서 출연을 했던 거였고요. 그때 경기도와 시군과 또 민간에서 합쳐서 100억을 한 거고 그 이후에는 사실 시군에서 별도로 더 출연금을 낸 경우는 없습니다. 
</p>
<p><b>○ 나득수 위원 </b> 네. 그렇다면 출연이 있는 시군에서 연구지원이라든가 혜택이 주어집니까? 출연한 시군에 혜택이 주어지는 건가요?
</p>
<p><b>○ 경기연구원장 임해규 </b> 그때는 산하 모든 시군에 일정하게 경기연구원을 설립하니까 좀 내라. 그때는 민선 이전 시절이었기 때문에 그렇게 쉽게 각출을 해서 기금이 구성된 것 같습니다. 그런데 저희들이 시군으로부터도 별도의 수탁형식이 아니라 정책연구 차원에서 해 주는 연구들이 있기 때문에, 지금도 예를 들면 북부발전 10개년 계획을 한다 이럴 때면 시군으로부터 별도로 돈을 받지 않고 저희들이 전략연구로 북부발전계획도 해 주고 이번에 동부발전계획도 말하자면 그런 식으로 했기 때문에 포괄적으로 보면 저희들이 시군에 대해서도 정책개발 서비스를 하고 있다 이렇게 말씀드릴 수 있을 것 같습니다.
</p>
<p><b>○ 나득수 위원 </b> 그렇습니까? 우리 경기연구원의 2016년도 수입을 보면 기금전입액과 기금이자수입이 한 11% 정도 차지해요. 그렇죠?
</p>
<p><b>○ 경기연구원장 임해규 </b> 네.
</p>
<p><b>○ 나득수 위원 </b> 그런데 연구원 육성기금을 일반회계 예산으로 충당해서 사용하고 있는 것입니까? 
</p>
<p><b>○ 경기연구원장 임해규 </b> 그렇습니다. 
</p>
<p><b>○ 나득수 위원 </b> 별도 기금을 설정하지 않고요?
</p>
<p><b>○ 경기연구원장 임해규 </b> 네, 그렇습니다.
</p>
<p><b>○ 나득수 위원 </b> 그러면 도 같은 경우에는 기금을 별도 운영 조례를 둬 가지고 규정해서 사용하는데 별도 규정을 두지 않고 사용해도 문제점은 없는 것으로…….
</p>
<p><b>○ 경기연구원장 임해규 </b> 그건 왜 그러냐 하면 도에서 하는 일반적인 기금의 경우는 특수사업을 염두에 두고 기금이 조성됐기 때문에 그 특수사업에 따른 수입과 지출을 해야 되기 때문에 별도 회계를 해야 될지 모르지만 저희는 이 기금이 그렇게 사용하기 위한 목적이 아니라 이자수입을 일반회계로 전입해서 전반적인 운영에 도움이 되라고 만들어 놓은 기금이기 때문에 그 기금을 별도로 설치해서 기금 자체의 회계를  별도로 가질 필요는 없다고 생각이 됩니다.
</p>
<p><b>○ 나득수 위원 </b> 그러니까 본래 기금이라는 것이 어떤 특정목적 사업을 추진하기 위해서 운영하는 것 아닙니까, 그렇죠?
</p>
<p><b>○ 경기연구원장 임해규 </b> 네. 
</p>
<p><b>○ 나득수 위원 </b> 그래서 집행과정에서 합목적성 차원에서 일반예산에 비해서 어떤 자율성과 탄력성이 부여돼야 된다고 봅니다. 제 생각에는 경기연구원 육성기금도 별도의 어떤 조례를 만들어서 집행하는 게 투명하다고 보는데 그에 대해서는 어떻게…….
</p>
<p><b>○ 경기연구원장 임해규 </b> 네, 위원님. 저희들도 기금에서 돈이 나오거나 또는 이렇게 할 때는, 지금은 기금으로 돈이 들어가는 경우는 없습니다만 기금을 계속 깨먹고는 있습니다만 기금에서부터 돈이 일반회계로 나올 때 그 기금 자체는 기금특별회계를 운영하고는 있습니다. 그런데 오로지 그 기금특별회계는, 그러니까 저희들 일반회계로 기금을 전출하는 것만 잡힌다는 뜻으로 제가 아까 말씀드린 것이고요. 특별회계는 별도로 설치되어 있습니다.
</p>
<p><b>○ 나득수 위원 </b> 네, 아무쪼록 운영계획 수립이나 집행에 있어서 공정한 심의가 이루어지도록 기금 운영관리에 철저를 기해 주시기 바랍니다.
</p>
<p><b>○ 경기연구원장 임해규 </b> 네, 그렇게 하겠습니다.
</p>
<p><b>○ 나득수 위원 </b> 이상입니다.
</p>
<p><b>○ 위원장 이재준 </b> 나득수 위원님 수고하셨습니다. 김승남 위원님.
</p>
<p><b>○ 김승남 위원 </b> 원장님, 늘 수고가 많으십니다. 김승남 위원입니다. 연구년제도 운영에 대해서 간략하게 질의를 드리도록 하겠습니다. 많은 연구기관들이 연구박사들의 재충전의 시간을 가지면서 자발적인, 자율적이죠. 자율적인 연구과제를 수행하면서 자기발전을 통해서 연구원에 기여하기 위한 그러한 제도로 생각을 하고 있는데 맞는 건가요?
</p>
<p><b>○ 경기연구원장 임해규 </b> 네, 맞습니다.
</p>
<p><b>○ 김승남 위원 </b> 우리 경기연구원에서도 이러한 연구년제도를 운영하고 있죠?
</p>
<p><b>○ 경기연구원장 임해규 </b> 그렇습니다.
</p>
<p><b>○ 김승남 위원 </b> 지금 이 제도를 어떻게 운영하고 계십니까?
</p>
<p><b>○ 경기연구원장 임해규 </b> 저희들 인사ㆍ복무규정에 보면 연구연수에 관한 게 48조에 있습니다. “6년 이상 근무한 직원이 국내외 타 기관에서 전문지식을 얻고자 할 때 1년 이내의 연구연수를 명할 수 있다.”고 되어 있습니다. 그렇긴 하지만 저희들이 지금 벌써 10년, 15년 이상 한 연구원들도 많습니다만 대체로 현재는 재임 중에 한 번 정도 한 8년, 10년 정도 되면 연구년을 가고 있습니다. 그래서 지금 한 해에 한 3명 정도가 연구연수를 가고 있습니다. 그리고 연구연수를 가게 되면 일단 급여는 통상적인 급여가 지급이 되고 연구연수 가서 연구하는 데 따라 약간의 연구비가 지급이 되고 연구에서 돌아오면 그 연구과제를 저희들에게 제출하게 되어 있습니다.
</p>
<p><b>○ 김승남 위원 </b> 지금 몇 분 정도의 박사분들이 연구년을 보내고 계시나요?
</p>
<p><b>○ 경기연구원장 임해규 </b> 지금 1년에 3명 정도 가고 있습니다. 
</p>
<p><b>○ 김승남 위원 </b> 현재 가 계시는 분들이……. 
</p>
<p><b>○ 경기연구원장 임해규 </b> 현재 3명 가 있습니다. 
</p>
<p><b>○ 김승남 위원 </b> 그 대상은 앞서서 말씀하신 대로 지금 56분의 연구박사님들이 다 해당자가 되시는 거죠?
</p>
<p><b>○ 경기연구원장 임해규 </b> 그렇습니다. 그런데 여기 우리 규정상으로는 6년 이상으로 되어 있습니다만 한 8년, 10년 이 정도 되면 갑니다, 보통.
</p>
<p><b>○ 김승남 위원 </b> 그러면 지금 원장님께서 복귀할 당시에 연구한 과제에 대해서 보고서를 받는다고 말씀을 하셨죠?
</p>
<p><b>○ 경기연구원장 임해규 </b> 그렇습니다.
</p>
<p><b>○ 김승남 위원 </b> 이게 연구년을 가지는 근본취지는 본 위원이 앞서서 말씀을 드렸듯이 재충전의 시간을 가져야 될 필요성이 있다고 생각되는 부분이 있고요. 그래서 자율적인 연구과제를 소화하면서 자기역량을 개발하고 이런 거 아니겠습니까? 그럼으로써 그것이 또 연구원에 기여를 할 수 있는 계기가 되고. 그렇기 때문에 사실은 과도한 연구과제가 부여가 돼서는 안 된다고 생각해요, 원칙적으로는. 그렇지만 자율적으로 연구하고 있는 과제에 대해서는 중간보고가 됐든지, 아니면 1년의 기간이 끝난 이후에 전반적인 자료에 대해서 제출을 해야 될 의무는 줘야지 된다고 생각을 합니다. 그래서 그 정도 과하지 않는 과제 내에서 그렇게 통제를 하고 계시는 거죠?
</p>
<p><b>○ 경기연구원장 임해규 </b> 그렇습니다. 보통은 연구연수를 가게 되면 국내외의 대학으로 가게 되는 경우가 많습니다. 그러면 가게 될 경우에 나름대로 연구과제를 미리 계획을 가지고 갑니다, 통상적으로. 그래서 그 과제를 수행하고 그리고 오기 때문에…….
</p>
<p><b>○ 김승남 위원 </b> 아, 기본과제를 가지고요?
</p>
<p><b>○ 경기연구원장 임해규 </b> 그렇습니다. 보통 과제를 사전에 계획을 해서 가기 때문에 그 과제를 수행하는 데 큰 부담은 되지 않는다고 보고 있고요. 또 그렇게 과제를 하나 가지고 가야, 이게 연구연수기 때문에요. 연구년이기 때문에, 그냥 쉬는 게 아니기 때문에 적절하게 운영되고 있다고 생각합니다.
</p>
<p><b>○ 김승남 위원 </b> 그러면 지금 한 분당 박사분이 연구년을 보내시면서 연구비용이 얼마 정도가 소요가 되는 건가요? 박사님들대로 다 일률적으로 같은 건지, 아니면 지금 부여되는 과제에 따라서 비용에 차이가 있는 건지 설명을 해 주시기 바랍니다. 
</p>
<p><b>○ 경기연구원장 임해규 </b> 비용 차이는 없고요. 연구활동비가 2,000만 원까지 지급되고 국내 연수할 경우는 1,000만 원까지 감액해서 지급합니다.
</p>
<p><b>○ 김승남 위원 </b> 1년을 연구과제를 수행하는 데 2,000만 원뿐이 안 된다고요?
</p>
<p><b>○ 경기연구원장 임해규 </b> 그렇습니다. 연구활동비 지원이요.
</p>
<p><b>○ 김승남 위원 </b> 연구년을 보내지 않고 근무를 하는 기관에도 우리가 지금 기본연구를 하는 데는 보통 1,000만 원 정도인가요, 1,500만 원 정도인가요? 과제당 이렇게 비용이 지금 들어가고 있죠?
</p>
<p><b>○ 경기연구원장 임해규 </b> 그렇습니다. 
</p>
<p><b>○ 김승남 위원 </b> 그런데 1년간 그것도 외국이나 이렇게 나가서 활동을 하시는 데 2,000만 원 정도의 연구비뿐이 안 된다는 말씀을 하시네요?
</p>
<p><b>○ 경기연구원장 임해규 </b> 그렇습니다.
</p>
<p><b>○ 김승남 위원 </b> 그러면 연구년을 보내면서 연구한 그 실적이 지금 도정이나 이런 데 반영된 게 있습니까, 혹시라도? 기억나시는 게 있나요? 그런 것이 결국은 연구년을 보내면서 연구기관에 도움을 주는 그러한 기능을 하는 부분인데 나가서 자율적으로 연구활동을 하신 거긴 하지만 또 과제를 부여받아서 나가신다고 했잖아요, 일정 부분?
</p>
<p><b>○ 경기연구원장 임해규 </b> 그렇습니다.
</p>
<p><b>○ 김승남 위원 </b> 그런 것이 도정에 반영이 돼야 되는 부분이 있어야 될 것 같은데 그러한 실적이 전혀 없습니까?
</p>
<p><b>○ 경기연구원장 임해규 </b> 그러니까 이게 다른 정책연구의 경우는 저희들이 연구위원회나 연구심의위원회를 통해서 의뢰자들이 있지 않습니까? 연구를 의뢰한 행정 각 기관이나 이런 곳의 의뢰자들이 오셔서 말하자면 계속 요구도 하고 또 감수도 해 주고 이렇게 하게 됩니다. 그런데 사실 지금 이게 연수를 갈 때의 과제는 아까 위원님도 말씀하셨지만 자율적으로 과제를 본인이 제기하기 때문에 사실 다른 일반 정책연구처럼 밀접하게 의뢰자와 연결되어 있지 않기 때문에 바로 연구결과가 도정이나 이런 곳에 반영되기는 사실 어려운 구조입니다, 구조적으로. 그게 의무로 부과되어 있지 않기 때문에. 그렇지만 예를 들면 이렇습니다. 지금 연구 가 있는 분이 하고 있는 연구가 에너지정책의 민간협력모델 연구 이런 걸 말하자면 하고 있습니다, 지금 간 분이. 그런데 이런 건 계속 자기가 지금 여기서 근무를 하는 중에도 관심 있는 분야에 대한 연구를 이어서 하기 때문에 이런 연구는 갔다 오고 난 다음에 해당부서와 협의를 하면 금방 해당부서에서 정책화하는 데 매우 큰 도움이 될 걸로 그렇게 보고 있습니다. 
</p>
<p style="padding-left:1.2em">  그리고 다른 하나 또 지금 가 있는 세 분의 연구주제인데요. 또 하나는 국가별 창조도시 환경 및 정책이 창조계급의 집적에 미치는 영향이라는 연구과제를 진행 중이고 또 하나는 뉴저지 주정부와 지방정부의 재정분권과 재원배분 연구거든요. 그러니까 이건 재정에 관한 연구. 이런 식으로 직접 행정 각 부서에서 의뢰하거나 이건 아니지만 연구제목을 보시면, 또 다른 연구한 것도 제목을 쭉 보시면 ‘아, 이게 충분히 도정에 반영되겠구나.’ 하는 것은 아마 느끼실 수 있을 겁니다. 그래서 도정에 반영된 여부는 확인은 어렵습니다만 연관은 있다고 생각이 됩니다. 
</p>
<p><b>○ 김승남 위원 </b> 본 위원은 연구년제도에 대해서 긍정적인 생각을 가지고 있습니다. 이 부분이 잘 활용이 되면 여러 면에서 자기발전도 있고 앞서서 말씀드렸듯이 자기의 역량 강화가 연구원에 기여를 하게 돼서 결국은 우리 도민의 삶의 질을 향상시키는 데 기여를 한다고 본 위원은 생각을 하고 있고요.
</p>
<p style="padding-left:1.2em">  그럼에도 불구하고 연구원에 따라서 연구년 활용방식이 사익추구로 흘러서 도덕적 해이의 전형이자 또 근무 오래하신 분에 대한 특혜로 인식을 갖게 하는 이런 오해를 사게 하는 부분도 상당히 많은 것 같아요. 그래서 그러한 것이 주변에 그렇게 인식이 가지 않도록 우리 연구원장님께서 관리를 잘해 주셔서 이 제도에 대해서 내실화를 기해 주시기를 바라겠습니다.
</p>
<p><b>○ 경기연구원장 임해규 </b> 네, 그렇게 하겠습니다. 이해해 주셔서 감사합니다.
</p>
<p><b>○ 김승남 위원 </b> 질의 마치겠습니다.
</p>
<p style="padding-left:2.4em">    (이재준 위원장, 나득수 간사와 사회교대)
</p>
<p><b>○ 위원장대리 나득수 </b> 김승남 위원님 수고하셨습니다. 다음 질의하실 위원님, 임채호 위원님 질의해 주십시오.
</p>
<p><b>○ 임채호 위원 </b> 임채호 위원입니다. 먼저 우리 연구원의 1년 예산이 135억 정도가 되고요. 그렇죠?
</p>
<p><b>○ 경기연구원장 임해규 </b> 그렇습니다.
</p>
<p><b>○ 임채호 위원 </b> 출연금이 120억인데 이 출연금은 우리 경기도에서 지원하는 거고요. 그다음에 기금전입이랑 이자수입, 사업수입이라는 건 어떤 걸 사업수입으로 잡고 있는 건가요?
</p>
<p><b>○ 경기연구원장 임해규 </b> 저희들이 그러니까 수탁을 받으면, 어떤 연구과제를 수탁을 받으면 그 수탁 받는 총금액의 한 30%가량을 저희들이 수익금으로 뗍니다. 경기도나 국토교통부로부터 10억짜리 사업을 저희들이 받았다 그러면 10억이 저희들의 총수입인데 그 10억 총수입 중에 3억 정도를 수익으로 잡습니다, 수익으로.
</p>
<p><b>○ 임채호 위원 </b> 그러니까 수탁 받는 금액에서.
</p>
<p><b>○ 경기연구원장 임해규 </b> 그렇습니다.
</p>
<p><b>○ 임채호 위원 </b> 이번에 수탁 받은 사업비가 50억이 아니에요? 그 50억 말고 또 15억이 잡힌 거네요? 
</p>
<p><b>○ 경기연구원장 임해규 </b> 아니죠. 그러니까 50억이 총 받은 금액이고 그 50억의 30%, 그러니까 저희들이 사업수익으로 잡는 겁니다.
</p>
<p><b>○ 임채호 위원 </b> 나머지는 이제……. 
</p>
<p><b>○ 경기연구원장 임해규 </b> 경비죠.
</p>
<p><b>○ 임채호 위원 </b> 경비로 다 떨려나가는 겁니까?
</p>
<p><b>○ 경기연구원장 임해규 </b> 그렇습니다. 경비로 다 쓰죠.
</p>
<p><b>○ 임채호 위원 </b> 그 경비라는 것은 거기에 따르는 연구원이라든가 인건비, 토털 자료, 재료 이런 거 다 포함한 겁니까?
</p>
<p><b>○ 경기연구원장 임해규 </b> 그렇습니다. 아까 다른 위원님께서 질의 주셨습니다만 그게 일단 10억짜리를 국토교통부로부터 “수도권 교통통행량조사를 해 주시오, 경기도에 대해서.” 이렇게 저희들이 받으면.
</p>
<p><b>○ 임채호 위원 </b> 짧게 짧게요. 
</p>
<p><b>○ 경기연구원장 임해규 </b> 받으면 그 10억 중에 저희들이 상당한 건 또 조사를 하기 위해 어떤 업체에다가 조사를 줘버리죠.
</p>
<p><b>○ 임채호 위원 </b> 용역을 준다, 위탁을?
</p>
<p><b>○ 경기연구원장 임해규 </b> 네, 그 비용이죠. 위탁을 주게 되면.
</p>
<p><b>○ 임채호 위원 </b> 위탁을 주는 비용이다?
</p>
<p><b>○ 경기연구원장 임해규 </b> 그렇습니다.
</p>
<p><b>○ 임채호 위원 </b> 그 연구비 수탁 받은 것에서 일부 위탁비로 나간다?
</p>
<p><b>○ 경기연구원장 임해규 </b> 위탁비로 주고 또 연구하는 데 따르는 초빙연구원을 저희들이 고용하게 될 경우에 초빙연구원의 급여도 나가야 되고요.
</p>
<p><b>○ 임채호 위원 </b> 그러면 지출에서 연구사업비가 77억이 나가고 있습니다. 그리고 인건비가 84억이 나가고요. 경상비 나가고 예비비 나가고. 그러니까 제가 출연금을 보면 120억 경기도에서 출연하는 걸로 인건비 플러스 경상비, 예비비 포함하면 그게 한 120억 나가고 연구사업비라는 게 그럼 어떤 걸 연구사업비라고 그럽니까?
</p>
<p><b>○ 경기연구원장 임해규 </b> 저희들이 한 300여 건의 연구를 수행하지 않습니까?
</p>
<p><b>○ 임채호 위원 </b> 그러니까 우리 자체적으로 각 박사님들의 개별적인 경기도 대응방안이나 이런 걸 나름대로 설정해 가지고 그 연구비용이 여기 연구사업비에 포함된 겁니까? 
</p>
<p><b>○ 경기연구원장 임해규 </b> 네, 그렇습니다.
</p>
<p><b>○ 임채호 위원 </b> 그 연구비에 들어가는 돈이라 이거죠? 
</p>
<p><b>○ 경기연구원장 임해규 </b> 그렇습니다. 한 건당 저희들이 한 1,000에서 1,500만 원 정도 연구사업의 비용이 들어가거든요. 
</p>
<p><b>○ 임채호 위원 </b> 글쎄, 그걸 내가 한번 들춰보니까 어떤 건 한 달도 걸리고 어떤 건 5일도 걸리고 뭐 이렇더라고요.
</p>
<p><b>○ 경기연구원장 임해규 </b> 그건 이런 큰 정책연구과제가 아니라 아까 말씀드린 현안대응 뭐 이런 짧은 글들이고요. 보통은 3개월에서 6개월가량 걸리거든요, 과제가.
</p>
<p><b>○ 임채호 위원 </b> 그러게요. 1년 걸리는 것도 있는데 그걸 토털해서 연구사업비로 77억이 들어간다는 얘기예요?
</p>
<p><b>○ 경기연구원장 임해규 </b> 그렇습니다.
</p>
<p><b>○ 임채호 위원 </b> 그렇다는 얘기고요. 자, 그러면 일단 자료 하나만 요구하겠습니다. 위탁 6건이 있습니다. 우리가 위탁 준 것. 그걸 자료로 구체적으로 현황을 주시고 지금 수탁연구가 있어요. 수탁연구도 구분을 해서 경기도청이나 의회나 경기도 산하기관에서 의뢰하는 연구과제 그다음에 지자체, 31개 시군구가 됐든 서울시가 됐든 지자체에서 들어온 연구과제 그걸 구분해 주시고 정부기관 및 정부 공공기관에서 의뢰 들어왔던 수탁 받은 연구과제가 있는 거 그걸 자료로 주시면 될 것 같습니다.
</p>
<p style="padding-left:1.2em">  그러면 우리 많은 박사님들이 외부강의도 나가잖아요. 아까 나왔던 것 같은데 외부강의를 받게 되면 외부강의에 대한 수수료는 어떻게 처리합니까? 수입으로 잡습니까? 수입으로 잡냐 이거예요.
</p>
<p><b>○ 경기연구원장 임해규 </b> 그렇습니다. 수입인데 저희들 연구원의 수입이 아니고 개별 박사의 수입입니다.
</p>
<p><b>○ 임채호 위원 </b> 아, 그렇습니까?
</p>
<p><b>○ 경기연구원장 임해규 </b> 네. 
</p>
<p><b>○ 임채호 위원 </b> 그러면 근무 중에 시간을 내서 강의를 나가. 그런데 우리는 급여를 줘. 그런데 그 박사님이 자기 시간을, 소속은 여기 되어 있지만 출강을 나가서 50만 원이든 100만 원이든 강의료를 받아. 그러면 그거 개인 거다?
</p>
<p><b>○ 경기연구원장 임해규 </b> 그래서 저희들 규정이 무한히 물론 부르지도 않습니다만 한 달에 세 번 정도 하는 걸로 제약이 되어 있고요. 그리고 한 번 나갈 때 받는 액수가 20만 원으로 한정이 되어 있고 그렇습니다. 그래서 위원님이 생각한 것처럼 이렇게 막 무절제하게 나가, 물론 그렇게 부르지도 않습니다만 그렇게 많이 나가거나 이러기는 사실 어렵습니다.
</p>
<p><b>○ 임채호 위원 </b> 그러면 2015년하고 2016년 현재 외부강의를 나갔던 리스트하고 횟수, 연구원들에 대한 리스트하고 횟수가 어떻게 되는 건가 그걸 자료로 같이 제출해 주시면 되겠습니다.
</p>
<p style="padding-left:1.2em">  자, 두 번째는 우리가 2017년도 주요업무를 아까 말씀하셨어요. 그런데 공감도시연구실에서 아주 이런 건 잘 만든 거 같아요. 도시재생 마을만들기라든가 임대주택의 다변화 이런 연구분야를 우리 친서민들과 관련된 부분을 한다는 건 참 바람직하게 잘 짜여진 것 같아요.
</p>
<p style="padding-left:1.2em">  그런데 지금 우리나라에서 가장 민감하고 앞으로 큰 문제가 터질듯 한 것이 재개발ㆍ재건축, 우리 경기도뿐만이 아니고 국가적인 위기가 오지 않을까 이렇게 생각됩니다. 지금 어떤 추진위원회가 구성돼서 조합까지 가서 이걸 더 나갈 수도 없고 아니면 철수할 수도 없는 이러한 안타까운 현실이 많습니다.
</p>
<p style="padding-left:1.2em">  그리고 또 그와 관련돼서 소송이 붙어서 10년, 20년째 재산이 동결돼서 자기 재산권도 못 움직이는 것이 많습니다. 이런 것을 우리가 연구를 좀 해야 된다. 우리 경기연구원에서 바로 어떤 도시기반시설은 정부기관에서 해 줘야 된다. 옛날에 아파트 당첨이 되면 프리미엄이 1억, 2억씩 올라갈 때가 아닙니다. 그래서 부동산경기를 잡기 위해서 그 사람들한테 기반시설을 내게끔 했는데 지금은 그 사람들한테 기반시설 내고 기타 자기 집을 주고 1~2억씩 아파트 사는 값을 주고도 못 들어가는 경우가 많잖아요, 지금 재개발ㆍ재건축에서.
</p>
<p style="padding-left:1.2em">  이런 것을 우리 연구기관이나 도시공사에서도 이렇게 연구를 좀 해서 어떤 방법을 찾아야 된다. 그러니까 시행사 배불려주고 이럴 것이 아니고 우리 공공관리재가 돼 있으니까, 공공관리재 활용을 않습니다. 잘 모르기도 하지만 추진위가 조합장이 돼 가지고 자기 이권을 개입하려고 건설사하고 쫌매지다 보니까 공공관리재 활용을 안 합니다. 그래서 그러한 지자체의 공공관리재의 이점이라든가 이런 것을 홍보해서 앞으로 재개발ㆍ개건축이 그야말로 우리 서민들 내쫓고, 길거리에 내쫓는 그러한 정책이 돼서는 안 된다는 말씀을 드리고 싶어요.
</p>
<p style="padding-left:1.2em">  그래서 그런 연구가 필요하고 경기도시공사하고 MOU 체결해서 어떤 방법이 있는가. 그리고 앞으로 경기도시공사가 이제는 대단위 택지개발에서 도시재생사업으로 지금 방향을 틀고 있는데 바로 우리 경기연구원하고 같이 MOU 체결로 인해서 앞으로 어떠한 정책을 펼쳐나갈 것인가 그러한 자료도 필요하지 않은가 이렇게 생각이 됩니다.
</p>
<p style="padding-left:1.2em">  그래서 저는 공감도시연구실에서 연구를 하지만 재개발ㆍ재건축 이대로 두고 볼 수 없습니다. 앞으로 이것은 큰 문제가 됩니다. 그래서 이것은 국가 차원에서 지원이 되지 않으면 해결방법이 없을 것 같아요. 국회에서 다뤄야 할 부분이지만 우리 경기도에서 더 이상 주민들이 피해 보기 전에 빨리 좀 대응을 할 필요성이 있다 이 말씀을 드리고 싶습니다.
</p>
<p><b>○ 경기연구원장 임해규 </b> 네, 공감합니다.
</p>
<p><b>○ 임채호 위원 </b> 그거 공감하시죠?
</p>
<p><b>○ 경기연구원장 임해규 </b> 네.
</p>
<p><b>○ 임채호 위원 </b> 그래서 그 부분도 공감도시연구실에서 한 축으로 넣어 가지고 연구과제로 해 주십사 하는 부탁의 말씀을 드립니다.
</p>
<p><b>○ 경기연구원장 임해규 </b> 네, 그러겠습니다.
</p>
<p><b>○ 임채호 위원 </b> 이상입니다.
</p>
<p><b>○ 위원장대리 나득수 </b> 임채호 위원님 수고하셨습니다. 다음 질의하실 위원님, 양근서 위원님 질의해 주십시오.
</p>
<p><b>○ 양근서 위원 </b> 양근서 위원입니다. 우선 첫 번째 질의를 하겠는데요. 저는 이번에 경기연구원에 대한 행감을 준비하면서 깜짝 놀랐어요. 어떤 부분에 대해서 나름대로 충격을 받았냐 하면 경기연구원 내 비정규직에 대한 차별구조가 굉장히 만연화돼 있고 제도화돼 있다고 하는 데 대해서 굉장히 깜짝 놀랐습니다.
</p>
<p style="padding-left:1.2em">  대부분 정책연구를 하게 되면 우리 사회의 가장 큰 아픈 속살 중의 하나고 현안 중의 하나인 비정규직 문제해결에 대해서 굉장히 정책적 대안들을 많이 내놓지 않습니까?
</p>
<p><b>○ 경기연구원장 임해규 </b> 네.
</p>
<p><b>○ 양근서 위원 </b> 그럼에도 불구하고 정작 경기연구원이 비정규직 문제에 대해서는 굉장히 퇴행적으로, 퇴보적으로 운영되고 있다는 데 대해서 놀란 거예요.
</p>
<p style="padding-left:1.2em">  내용을 한번 살펴보겠습니다. 우선 우리 핵심기능이 연구하는 거기 때문에 연구원의 연구원들을 정규직과 비정규직 그리고 석ㆍ박사급으로 한번 분류를 해 봤는데요. 지금 정규직에 석사가 있습니까, 없습니까? 한 명도 없습니다.
</p>
<p><b>○ 경기연구원장 임해규 </b> 네.
</p>
<p><b>○ 양근서 위원 </b> 지금 정규직이 총 56명인데 56명 전원 박사입니다. 석사는 단 한 명도 없고요. 비정규직에는 박사가 얼마나 될까요? 비정규직 지금 83명의 연구원이 있는데요. 이 가운데 박사는 17명이고 나머지 66명은 다 석사입니다. 결국은 정규직은 박사 그다음에 비정규직은 석사식으로 마치 크게 대기업과 중소기업의 구조를 보면 대기업이 중소기업을 약탈하기 위해서, 착취하기 위해서 만들어 놓은 일종의 하청구조 같은 체계를 그대로 답습을 하고 있다는 인상을 지울 수가 없고요.
</p>
<p style="padding-left:1.2em">  더 놀라운 것은 석사를 아예 안 뽑고 있어요, 2002년도 이후부터 무려 14년 동안. 해마다 연구원들을 공채했는데 석사 이상, 석사급은 모집공고조차 안 했어요. 아예 지금 채용을 않고 있는 거예요. 그러니까 당연히 정규직에 석사가 지금 없는 것이죠. 이것은 지금 객관적인 사실이에요. 그거 인정은 하시죠?
</p>
<p><b>○ 경기연구원장 임해규 </b> 네.
</p>
<p><b>○ 양근서 위원 </b> 왜 그렇게 운영하고 있습니까? 잠깐 간단하게 한번 답변해 보시죠.
</p>
<p><b>○ 경기연구원장 임해규 </b> 그게 관행이기도 한데요. 지금 위원님 지적처럼 그렇게 쭉 해 온 것이기도 한데 그런데 사실 저도 처음 여기 연구원 와서 그 점에 대해서 문제의식을 가지고 살펴봤었습니다. 그런데 여기는 처음 신규, 저희들이 새로 박사를 뽑을 경우에는 결국은 연구역량을 놓고서 해당분야의 박사를 뽑아야 되니까요. 그래서 연구역량이 상당히 있는 사람을 저희들이 뽑게 되겠죠.
</p>
<p><b>○ 양근서 위원 </b> 알겠습니다.
</p>
<p><b>○ 경기연구원장 임해규 </b> 그러다 보니 박사연구원을 뽑게 되고, 그 경쟁률이 굉장히 높습니다. 그리고 박사연구원 중에서도 지금 입직연령이 평균 38세에 이를 정도로 일정한 경력이 있는 사람을 뽑게 되더라고요. 경쟁적으로 뽑게 되니까, 저희들이. 그래서 그건 우리 연구원의 구조상 상당히 불가피한 측면이 있어 보입니다, 일단 정규연구원을 뽑는 건. 그런데 위원님 지적처럼 석사연구원도 정규직으로 뽑으면 되지 않겠나 혹은 기왕에 있는 석사연구원들을 정규직으로 전환하는 문제는 어떤가는 사실 굉장히 많은 고심을 했습니다. 그런데 아직은……. 우리 연구원 내에서 토의도 했습니다, 석사연구원을 정규직으로 뽑는 게 어떻겠느냐 하는 문제를. 그런데 우리나라 국책연구원도 그렇고 전반적인 연구원들이 석사연구원들을 정규직으로 뽑는 경우는 사실 얼마 없고 그것도 장단점이 여러 가지로 논의될 만한 것이어서 아직까지 그것까지는 나가고 있지 못합니다.
</p>
<p><b>○ 양근서 위원 </b> 저는 굉장히 학벌주의를 조장하는 듯 한 좀 편향된 시각을 보여주신 거라고 생각을 하고요. 정책연구과제를 수행할 때 박사들만 참여하지 않지 않습니까? 보통 박사급이 책임연구원을 맡게 되고 그리고 공동연구원으로 참여하는 사람들은 박사도 있지만 거의 대부분 석사들이 참여해서 공동으로 연구해서 그 결과물이 나오는 거예요. 그렇죠?
</p>
<p><b>○ 경기연구원장 임해규 </b> 그렇습니다.
</p>
<p><b>○ 양근서 위원 </b> 물론 석ㆍ박사급에 따라서 연구역량에 차이는 당연히 있을 수 있죠. 그래서 그 차이에 따라서 당연히 일의 질이 다르기 때문에 급여가 다르지 않습니까?
</p>
<p><b>○ 경기연구원장 임해규 </b> 네.
</p>
<p><b>○ 양근서 위원 </b> 연봉이 석사에 비해서 박사가 훨씬 높죠? 보통 경기연구원의 경우에도 두 배 이상 높던데요. 그렇지 않습니까?
</p>
<p><b>○ 경기연구원장 임해규 </b> 그렇습니다.
</p>
<p><b>○ 양근서 위원 </b> 그리고 일단 구조적으로 연구정책과제를 수행하는 기본 인력체계가 박사만으로 이루어져서는 될 수가 없고 석사급이 들어갈 수밖에 없는 구조란 얘기예요. 그러면 당연히 비정규직을 활용할 게 아니라 정규직으로 포함시켜서 이걸 활용할 수 있는 체계를 만드는 것이 저는 당연하다고 보고요. 특히 경기연구원은 일의 효율성이랄지 경제성만 가지고 일을 하는 곳이 아니라 어떻게 보면 사회 전체의 분위기랄지 그다음에 노동문화랄지 인사문화랄지 이걸 선도하는 기능까지 해야 된단 말이에요. 그렇죠?
</p>
<p><b>○ 경기연구원장 임해규 </b> 맞습니다.
</p>
<p><b>○ 양근서 위원 </b> 그렇다면 당연히 실제 필요한 인력이기 때문에 정규직으로 채용을 하고 또는 전환을 해서 활용하는 것이 너무나 마땅하다고 생각합니다. 그것을 다른 국책연구원이나 타 공공기관하고 비교해 가지고 남들도 안 하니까 우리도 안 한다 이렇게 이야기하는 것은 굉장히 변명에 불과하다고 생각을 합니다.
</p>
<p style="padding-left:1.2em">  저는 이왕 이 문제가 불거진 만큼 경기연구원에서 당장 내년부터라도 연구인력을 채용할 때 기존에 있던 석사급 비정규직, 계약직 인력들을 정규직으로 전환하는 문제를 비롯해서 신규로 채용할 때도 당연히 석사를 포함시켜야 된다고 봅니다.
</p>
<p style="padding-left:1.2em">  지금 정부의 정책적 지침 자체가 이런 비정규직 문제랄지 학벌이 낮은 인력에 대한 사회적 배려 차원에서 특히 공기업 같은 경우는 이를테면 고졸학력자도 뽑고 있지 않습니까?
</p>
<p><b>○ 경기연구원장 임해규 </b> 네.
</p>
<p><b>○ 양근서 위원 </b> 거의 의무적으로 할당해 가지고 하고 있고 심지어는 장애인마저도 의무고용비율을 지키도록 시책을 추진하고 있고, 여성도 마찬가지고 그렇게 하고 있어요. 그렇지 않습니까?
</p>
<p><b>○ 경기연구원장 임해규 </b> 네.
</p>
<p><b>○ 양근서 위원 </b> 저는 그런 관점에서 이 문제도 바라봐야 한다 이렇게 생각을 하고 지금 현재 어쨌든 연구인력을 운용하는 시스템 자체가 지나치게 정규직은 마치 특권계급인 것처럼 박사들로만 이루어져 있고 나머지 석사급들은 다 비정규직으로 전환해서 운영하는 것은 올바르지 않다, 정당하지 않다, 공정하지 않다고 보기 때문에 내년부터 석사를 일단 정규직으로 전환하고 신규 채용하는 데 방안들을 마련해 주시기 바랍니다.
</p>
<p><b>○ 경기연구원장 임해규 </b> 답변을 딱 드리기가 좀 어려운 측면이 있습니다. 사실 제가 고민을 많이 했던 분야기 때문에 큰 방향에서 위원님의 문제의식에 대해서 공감을 하고 또 진짜 그 고민을 했습니다, 우리 내부적으로도. 그런데 그렇게 하려면 사실 저희 연구원에서 어떻게 보면 정말로 혁명을 하는 거거든요. 그래서 제가 쉽게 “그렇게 한번 해 보겠습니다.” 이렇게 답변을 하기 어렵습니다.
</p>
<p style="padding-left:1.2em">  그런데 이걸 저희들이 검토는 한번 하겠습니다. 저도 큰 방향에서 옳다고 생각하고 그렇기 때문에. 그런데 어떤 문제가 있냐 하면 금방 위원님도 이건 ‘아, 그럴 수 있겠다.’ 이렇게 생각하실 것 같은데 사실 석사연구원을 정규직으로 하게 될 경우에 석사연구원이 시간이 가면, 그러니까 석사와 박사를 별도의 직렬로 두기가 사실 굉장히 어렵습니다. 그러면 적정하게 경력이 쌓이면 박사학위가 있건 없건, 학위가 있고 없고가 약간 급여에 차이는 있겠지만 어쨌든 약간씩 이렇게 돼야 되는데 그렇게 되면 많은 우리 연구원들이 걱정하는 것은 사실 연구에 있어서는 연구역량이 굉장히 중요하거든요, 연구의 질을 유지하기 위해서.
</p>
<p style="padding-left:1.2em">  그럼 우리가 처음 석사연구원들을 뽑을 때부터도 지금보다는 훨씬 강화된 시스템에서 뽑아야 되고 그렇게 될 경우에 근무체계가 어떻게 되는가 하는 문제가 굉장히 복잡해집니다, 상황이.
</p>
<p><b>○ 양근서 위원 </b> 저는 근무체계냐 급여체계는 기왕에 있는 시스템으로도 얼마든지 극복 가능하다고 생각하고 중요한 문제는 혁명을 하기 위해서는 결국은 정책적 결단인데요. 저는 원장님께서 그 부분에 대한 의지가 박약하다고밖에 볼 수가 없어요. 자꾸 연구의 질을 강조하시는데 한마디로 박사가 참여하면 연구의 질이 높고 석사가 참여하면 연구의 질이 낮다는 말씀밖에 안 되는 거예요.
</p>
<p style="padding-left:1.2em">  그런데 현실적으로 지금 현재 모든 경기연구원에서 수행하고 있는 수탁과제를 비롯해서 정책연구과제들이 어떻게 이루어지고 있습니까? 대부분 박사하고 석사급들이 다 들어가서 일하고 있어요.
</p>
<p><b>○ 경기연구원장 임해규 </b> 아니, 박사가 책임연구원을 하죠.
</p>
<p><b>○ 양근서 위원 </b> 아니, 그러니까요.
</p>
<p><b>○ 경기연구원장 임해규 </b> 사실 연구의 질은 책임연구를 하는 박사의 질이 가장 결정적이라고 봐야 합니다.
</p>
<p><b>○ 양근서 위원 </b> 지금 현재 비정규직으로 있는 석사들이 연구과제에 참여해서 공동연구를 해요. 그런데 이분들이 정규직으로 전환된다고 돼서 공동연구원으로 참여가 안 되고 무조건 책임연구원으로만 등재가 돼야 된다는 건 아니지 않습니까? 그건 적절하게 연구역량에 따라서 분리해서 활용을 하면 되겠죠. 그렇지 않습니까? 당연한 거죠. 그렇게 연구의 질 문제 때문에 곤란하다고 말하고 있는 것은 적절하지 않다는 거죠. 어쨌든 이것은 시정을 지금 주장하는 거예요. 행감 중이고 기획재정위 차원에서 관리감독하는 입장에서 그건 부적절하다, 그래서 이것은 강력하게 시정을 권고하고 주장을 하는 것이기 때문에 거기에 대해서 어쨌든 수용을 해 주시기를 바랍니다. 시간이 됐으므로 이상 질문드리고 또 추가질문하겠습니다. 
</p>
<p><b>○ 위원장대리 나득수 </b> 양근서 위원님 수고하셨습니다. 다음 질의하실 위원님 계십니까? 박형덕 위원님 질의해 주십시오. 
</p>
<p><b>○ 박형덕 위원 </b> 장시간 서서 발언대에서 답변하시느라고 고생이 많으신데……. 
</p>
<p><b>○ 경기연구원장 임해규 </b> 괜찮습니다. 
</p>
<p><b>○ 박형덕 위원 </b> 사실 우리 경기연구원에서 많은 연구과제를 수행함에 있어서 많은 도움이 되고 있다고 저는 생각합니다. 각계 각 분야에서 많은 분들이 연구를 해 줌으로 해서 많은 정책을 우리 경기도에서 반영을 하고 저 역시 그 자료를 보면서 의정에 도움이 많이 되는 부분에 대해서는 감사한 말씀을 드리겠습니다.
</p>
<p><b>○ 경기연구원장 임해규 </b> 네, 감사합니다.
</p>
<p><b>○ 박형덕 위원 </b> 지금 경기북부 인구가 320만으로 전국에서 5대 도시로 거듭날 정도로 많이 방대해졌는데 물론 우리 경기도에서 지역 균형발전을 위해서 많은 노력을 하고 있습니다. 그런데 연구과제를 이렇게 보면 물론 북부연구센터가 작년에 만들어져서 나름대로 많은 연구과제를 해서 대안을 내놓고 있는데 도로나 기타 미군기지 관련해서 많은 정책을 연구는 해 왔어요. 그런데 사실 교통인프라나 광역버스 기타 이런 부분에 대해서는 연구과제가 전혀 없는 것 같아요. 그거 한번 연구한 사례가 있습니까?
</p>
<p><b>○ 경기연구원장 임해규 </b> 일단 우리 북부연구센터장이 답변토록 하면 될까요?
</p>
<p><b>○ 박형덕 위원 </b> 네.
</p>
<p><b>○ 경기연구원장 임해규 </b> 북부연구센터장.
</p>
<p><b>○ 북부연구센터장 김동성 </b> 북부연구센터장 김동성입니다. 박형덕 위원님 질의에 간략히 답변을 드리겠습니다. 저희 북부연구센터는 모두 6명의 박사가 있고 그중에 한 사람이 교통분야를 담당하고 있습니다. 류시균 박사라는 연구원인데 이분이 올해 파주의 교통버스체계 그다음에 고양시의 교통버스체계를 하고 있습니다. 그리고 전반적인 그러한 교통체계 개선, 버스체계 개선이라든지 이런 것들은 남쪽에 있는 교통연구실과 같이 협동으로 과제를 진행하고 있는 그런 상황입니다.
</p>
<p><b>○ 박형덕 위원 </b> 지금 보면 경기북부도 동부, 서부, 중부, 남부 이렇게 분리가 돼 있는데 특히 교통인프라가 가장 열악한 데가 제가 볼 때는 아마 북부인 것 같습니다. 중부북부, 중북부. 서부는 고양시, 파주 같은 경우 인구가 워낙 많기 때문에, 어쨌든 교통은 모든 기업이 이윤이 우선이기 때문에 인구 많은 쪽에 배차라든가 모든 공공이 잘 이루어져 있는데 중부, 특히 양주ㆍ동두천ㆍ연천 또 포천 이쪽으로 보면 사실 버스공영체제는 제대로 잘 안 돼 있습니다. 그래서 지난번에 특히 경기북도의 전철이 출퇴근시간만 빼고는 보통 1시간에 두 대 정도 겨우 운행하고 어떨 때는 45분 걸리다 보니까 정작 낮에 서울로 출퇴근하는 사람들이 교통에 대해서 상당히 어려움을 겪고 있습니다. 그래서 전철을 증액시켜 달라고 많이 요구를 했지만 버스, 기타 공공버스를 이용하라고 철도관리공단에서 그런 협조를 잘 안 해 줍니다. 부족한 예산은 채워줘라 뭐 이렇게 요구는 하는데 정작 그런 데이터베이스가 좀 나와서, 낮에도 서울로 출퇴근하는 사람 또 수도권으로 버스를 이용하는 사람들이 얼마나 많이 이용을 하고 있냐는 그런 데이터베이스가 좀 나왔을 때 그런 걸 강력하게 철도관리공단이나 교통시설 하는 분들한테 요구를 할 수 있는데 그런 데이터베이스가 안 나와 있습니다.
</p>
<p style="padding-left:1.2em">  물론 서부 쪽에 또 구리나 남양주 같은 동부는 인구가 많아서 인프라가 구성이 돼 있고 또 가평 같은 경우는 춘천이란 도시가 있기 때문에 그런 부분이 잘 연구가 돼 있는데 경기북부, 중부 쪽은 연구가 잘 안 돼 있는데 그런 부분에 대해서 한번 검토 좀 해 주시기를 부탁을 드리고요.
</p>
<p style="padding-left:1.2em">  지난번에 감사 때도 보니까 경기북부에 대한 분도가 꾸준히 말이 많이 나왔잖아요. 그때도 감사자료에 분도에 대한 필요성을 제기해서 한번 연구과제를 줬는데 연구원에서는 적극 검토를 해서 연구를 해 보겠다고 그랬는데 제가 자료 보니까 한 2년이 지났는데도 아직 연구는 안 이루어졌는데 연구를 했습니까, 그렇지 않으면 연구를 일부러 안 하는 것인지. 괜히 이게 잘못하게 되면 경기도 전체에 미치는 파급효과 때문에 안 하는 건지 그것에 대해서 한번 답변 좀 해 주시기 바랍니다.
</p>
<p><b>○ 북부연구센터장 김동성 </b> 아직 저희가 가시적으로 연구를 진행하지는 않았습니다만 이것이 북부에서 가장 큰 이슈화될 것이라고는 저희 잘 알고 있습니다. 특히 내년의 대통령선거를 앞두고서 많은 분들이 또 경기북부의 독립적인 그러한 위상을 가져야 한다는 얘기를 할 걸로 예측을 하고 있습니다.
</p>
<p><b>○ 박형덕 위원 </b> 분도가 갑작스럽게 이루어지지는 않지만 저는 대의, 거시적인 안목에서는 지금 준비를 해야 된다 이렇게 생각합니다. 경기북부경찰청도 독립을 했고 많은 행정적인 게 어느 정도 준비는 잘 돼 있다고 생각을 합니다. 물론 국가적인 정책이나 도의 정책 때문에 쉽게 이루어지지는 않지만 행정적인 서비스의 질을 북부도민들을 위해서는 미리미리 준비를 해야 되는데 그런 연구과제도 정확하게 좀 나와 줘야 된다. 그런 백데이터가 나와 주지 않으면 정작 그런 부분이 이루어질 때 많은 어려움을 겪을 것이다 이렇게 생각합니다. 그래서 이 부분이 언제 또 연구가 이루어질지 모르겠지만 그 부분에 대해서는 적극 검토를 해 주시기 바랍니다. 
</p>
<p><b>○ 북부연구센터장 김동성 </b> 알겠습니다. 
</p>
<p><b>○ 박형덕 위원 </b> 그리고 업무보고, 임해규 사장님. 업무보고자료 28쪽 72번 정책과제를 보면 주한미군 공여구역주변지역 등 발전종합계획 수립에 따른 경기도 대응방안 그리고 연구책임자가 장윤배 연구원님이라고 그랬는데 2016년 6월 1일하고 연구마감이 2016년 11월 30일이고요. 또 자료 30쪽 131번 보면 수탁연구과제로 해서 제2차 주한미군 공여구역주변지역 등 발전종합계획 수립 연구라고 해서 이건 2016년 3월 23일 날 해서 2016년 11월 17일 마감한 것으로 되어 있는데 하나는 수탁이고 하나는 정책과제로 했는데 이게 뭐가 다른 겁니까? 
</p>
<p><b>○ 경기연구원장 임해규 </b> 거의 성격이 같은 과제입니다. 그런데 경기도 대응방안 수탁과제로 돼 있는 것은 저희들이 행정자치부로 수탁을 받은 연구과제입니다. 그리고 이거는 저희들이 정책과제로 수행하는 것입니다. 
</p>
<p><b>○ 박형덕 위원 </b> 그러면 정책과제에 대한 연구자료 따로 있고 수탁 연구자료도 따로 있는 거예요? 
</p>
<p><b>○ 경기연구원장 임해규 </b> 아니, 그러니까 같은 연구자가 책임연구원이기 때문에 같이 하는 것이죠. 그런데 하나는 국가 전체 차원에서 주한미군 공여지에 대해서 연구를 하는 것이고 이거는 우리 경기도에 관한 거를 하는 겁니다. 
</p>
<p><b>○ 박형덕 위원 </b> 아, 그러면 수탁과제는 경기도 것 전체만 보는 것이 아니고 대한민국 전체 미군공여지를 보고. 
</p>
<p><b>○ 경기연구원장 임해규 </b> 그렇습니다. 
</p>
<p><b>○ 박형덕 위원 </b> 그러면 여기 우리 정책과제에 있는 것을 이쪽으로 반영을 좀 시키겠네요?  
</p>
<p><b>○ 경기연구원장 임해규 </b> 그렇죠. 
</p>
<p><b>○ 박형덕 위원 </b> 반영시켜서 세부적인 안이 좀 나오겠네요?  
</p>
<p><b>○ 경기연구원장 임해규 </b> 그렇습니다. 그러니까 저희들 생각은 경기도의 대응방안을 확고하게 수립하면서 그거를 국가과제에, 이제 같은 연구자가 하니까 최대한 반영하도록 저희들이 노력을 하고자 하는 게 연구방향입니다.
</p>
<p><b>○ 박형덕 위원 </b> 그러면 경기도 정책과제에 대해서는 다 나와 있겠네요? 2차 종합발전계획에 대해서.
</p>
<p><b>○ 경기연구원장 임해규 </b> 아직까지 사업이 완료는 되지 않았기 때문에 유인돼서 나오진 않았습니다만 연구자의 연구의 전반적인 기조 속에서는 거의 결론이 나와 있다고 생각이 듭니다. 
</p>
<p><b>○ 박형덕 위원 </b> 그러면 사실 2차 종합발전계획이 경기북부 미군공여지 및 주변지역에 대해서 상당히 중요한 과제인데 물론 현장을 잘 방문을 하고 또 각 지자체를 많이 방문하면서 연구과제가 잘 나와서 잘 수립을 했으리라고 저는 생각이 됩니다. 물론 지금 어차피 경기도에는 미군공여지가 전체의 90% 이상 차지하고 있을 정도로 중요한 과제기 때문에 경기연구원에서는 그동안에도 많이 그 부분을 연구해 왔기 때문에 지금 많이 변화가 됐습니다. 미군공여지가 반환된 데도 있고 또 반환이 유보된 데가 있고 또 반환이 될 예정지도 있고 그런데 어쨌든 그러한 부분에 있어서는 경기북부뿐만 아니라 경기도 전체의 발전에 바로미터가 될 수 있는 연구과제기 때문에 좀 신중을 기해서 연구를 좀 많이 잘 하셔서 향후 미군공여지가 반환이 됐을 때 또 반환된 공여지가 그 지역에 필요한 시설로 꼭 이용될 수 있도록 연구를 잘해 주시기 바랍니다. 
</p>
<p><b>○ 경기연구원장 임해규 </b> 네, 그렇게 하겠습니다. 
</p>
<p><b>○ 박형덕 위원 </b> 이상입니다.
</p>
<p><b>○ 위원장대리 나득수 </b> 박형덕 위원님 수고하셨습니다. 다음은 오완석 위원님 질의해 주십시오. 
</p>
<p><b>○ 오완석 위원 </b> 수원 출신 오완석입니다. 감사 준비하시느라 고생하셨고요. 아까 제가 자료요청을 했는데 자료가 좀 들어왔는데요. 초빙연구원에 대해서 질문을 좀 드리겠습니다. 초빙연구원의 역할이 지금 어떻게 됩니까? 
</p>
<p><b>○ 경기연구원장 임해규 </b> 일단은 저희들이 연구과제를 수행하는 데 우리 정규박사들, 그러니까 연구위원들만으로는 불충분할 경우에 저희들이 추가로 고용해서 같이 일하고 있습니다. 
</p>
<p><b>○ 오완석 위원 </b> 그러니까 인원이 부족해서 그런 건가요, 아니면 과제내용이 현재 경기연구원에 있는 연구진 가지고는 수행을 할 수 없기 때문에 그런가요?
</p>
<p><b>○ 경기연구원장 임해규 </b> 그렇습니다. 두 가지 이유가 다 해당합니다. 
</p>
<p><b>○ 오완석 위원 </b> 그런데 꼭 그렇지만도 않은 것 같아요. 초빙연구원분들이 연구과제를 수행한 걸 보면 금액으로 따지면 그렇지만 대부분 시군에서 위탁한 연구과제들이 꽤 많은데 일상적이라고 보기는 그렇지만 교통이라든가 일반화돼 있는 과제들이 꽤 많은 것 같아요. 
</p>
<p><b>○ 경기연구원장 임해규 </b> 그렇기도 합니다. 
</p>
<p><b>○ 오완석 위원 </b> 그러면 인원이 부족해서 초빙으로 가고.
</p>
<p><b>○ 경기연구원장 임해규 </b> 그러니까 그런 측면도 있습니다. 예를 들어서 저희들이 공공기관에 대해서 무슨 평가연구를 하는 경우는 저희들이 공공기관평가연구팀이 있습니다만 거기에는 우리 정규박사는 한 분 계시거든요. 그러니까 거기에는 항상적으로 고용돼 있는 초빙박사가 예를 들면 두 명이 항상 있습니다. 그런 경우는 그 연구가 항상적인 연구기 때문에 바로 그 사람들을 그냥 정규박사로 뽑으면 되지 왜 계속 몇 년 동안 초빙으로 쓰냐 이렇게 금방 질문할 수 있는데 그런데 그거는 저희들이 정원규정이 묶여있습니다. 막 정원을 늘리기가 어렵습니다. 
</p>
<p><b>○ 오완석 위원 </b> 아까 업무보고하실 때 보면 연구직 인원이 결원이 있어요. 정원이 86명인데 현원이 78명이고 8명이 결원인데 이 중 연구진이 다섯 분이 결원이에요. 이거는…….
</p>
<p><b>○ 경기연구원장 임해규 </b> 그래서 제가 들어와서 8명 고용을 했거든요. 결원이 있으면 결원보다도 좀 더 뽑았습니다. 그런데 사실 정원이 저희들이 예를 들어서 81명이라고 해서 81명이 다 예산에 반영돼 있냐면 그게 아니고 그중에 올해 더 뽑을 수 있는 인원은 또 몇 명만 급여에 반영이 돼 있습니다. 그러니까…….
</p>
<p><b>○ 오완석 위원 </b> 그러면 정원규정이 잘못돼 있는 거 아닌가요?  
</p>
<p><b>○ 경기연구원장 임해규 </b> 그러니까 정원은 그 정도 정원을 계속 유지하라는 취지로, 가이드라인으로 이해하고 있고 현실적으로는 또 총액임금으로 저희들도 규제를 정하게 하고 있기 때문에 저희들이 박사를 또 늘리려면 행정부랑 상당히 협의도 해야 됩니다, 저희들 예산문제가 있기 때문에. 현재는 저희가 2명 정도 박사를 더 늘릴 수 있는 여유가 있습니다, 사실. 그래서 올해 초에도 저희들이 늘리려고 했는데 그때 아시다시피 저희들이 예산파동이 나서 더 그래서 사실 뽑는 과정을 진행하다가 취소한 바 있습니다. 그래서 올해도 저희들이 한 2명은 더 뽑을 생각을 하고 있습니다. 
</p>
<p><b>○ 오완석 위원 </b> 그러니까 수탁과제라든가 위탁, 시군에서 올라온 외부에서 의뢰한 과제들이 상당히 많은데 그리고 중복돼 있는 것도 많고. 그래서 아까 말씀하셨듯이 연구원이 부족해서 초빙연구원을 하는 경우도 있고 또 새로운 과제를 수행하기 위해서 하는 경우도 있는데 물론 새로운 과제를 수행하기 위해서 그렇다면 그럴 수도 있겠죠. 그런데 과거에 어떤 경우가 있었냐면 아실지 모르겠지만 초빙선임연구원이 가족으로 들어와서 연구하는 것이 일응 정치권에 대한 특혜라든가 이런 것들 때문에, 제가 거론은 않겠습니다마는 그런 불미스러운 일도 있었고 그렇습니다. 그래서 이게 다는 안 그렇겠지만 만에 하나, 다는 안 그렇겠지만 그런 부분도 없지 않아 있고 또 초빙연구원을 대부분 보면 특별채용하도록 되어 있는데 공개채용이 아니고 부서장 추천이라든가 도지사 추천으로 하게끔 돼 있지 않습니까? 이런 부분들이 과연, 물론 제가 자료를 받아 보니까 월 보수, 이게 월 보수구나. 월 보수가 지금 다 달라요. 물론 경력에 따라 다르겠지만 한 300에서 400 정도, 200, 300 이렇게 다 다른데 이게 1년 부분도 있고 2년 부분도 있고 다 있습니다. 이분들이 연구해서 상시적으로 근무하면서 연구하는 것도 아니고 본인 다른 연구를 하면서 또 연구하는 그런 부분이 있지 않습니까? 그래서 어떻게 보면 시군에서 2,000만 원, 1,800만 원짜리 수의계약을 맺어서 연구를 하는 것들에 대부분 많이 투여가 돼 있는데 오해는 하지 마시고요. 제가 확인된 바는 아니기 때문에 과거에 그런 것들이 있어서 말씀드리는 겁니다. 그래서 혹시 부서장이 굳이 초빙연구원을 채용을 안 해도 되는데 자리 하나 주기 위해서 한다든가 이런 부분에 대한 오해라든가 이런 것들이 좀 있을 수도 있다. 과거에도 그런 이가 있어서 곤욕을 치른 경우가 있다 이렇게 말씀을 좀 드리겠습니다. 그런 부분에 대해서는 크게 걱정을 안 해도 되겠습니까? 
</p>
<p><b>○ 경기연구원장 임해규 </b> 네, 저희들이 걱정하시지 않도록 잘 운영을 하도록 하겠습니다. 
</p>
<p><b>○ 오완석 위원 </b> 사실 가끔 보면 연구원에서 뜬금없는 것들이 언론에 나오고 뜬금없는 것들이 나와요. 왜 그러냐면 저희 위원들도 연구 실적에 대해서 일일이 분석하기가 사실 쉽지 않습니다. 워낙 많은 양을 하고 있고 또 전문적이지 않기 때문에. 그런데 간혹 가다 보면 그런 경우가 있고 그다음에 특별히 연구에 해당되지 않는 것들이 연구가 돼서 그런 오해를 받는 경우가 있습니다. 그래서 그런 부분들은 관리를 철저히 해 줘야 된다고 보고 있고요. 왜 그러냐면 이런 것들이 없으면 모르겠지만 자주 있는 건 아니지만 간혹 가다 그런 일이 생깁니다. 그러면 연구원에 대한, 연구원분들에 대한 자존감이나 그다음에 연구원의 부분이 한 번 실수가 되면 시군에서도 의뢰를 잘 안 하죠. 3, 4년 전에 그런 일이 있어서 뭐 있었는데 하여튼 이런 것들이 내부적으로 관리가 되는, 관리가 가능한 연구원들로만 구성이 돼 있고 연구를 한다면야 쉽게 관리가 되겠지만 그렇지 않다면 또 그런 채용과정에서, 공개채용도 아닌 특별채용을 하는 과정에서 그런 문제점이 있을 수 있기 때문에 그 부분은 좀 철저를 기해 줬으면 좋겠다란 말씀드리고 싶습니다. 
</p>
<p><b>○ 경기연구원장 임해규 </b> 저희들이 지금 초빙연구원도 전부 공개채용을 원칙으로 하고 있습니다. 
</p>
<p><b>○ 오완석 위원 </b> 특별채용이 대부분이에요. 보니까 저한테 지금 주신 것은 특별채용 16명인데 이 특별채용 외에도 공개채용하시는 분들도 있나요?  
</p>
<p><b>○ 경기연구원장 임해규 </b> 그러니까는 6개월 이내의 특정한 과제와 관련해서 초빙연구원을 많이 쓰거든요. 아까 말씀드렸지만 수탁연구나 이럴 때, 6개월 이내의 과제 이럴 경우는 특별채용 합니다. 그러니까 그 해당 연구책임자가 보통 추천하면 사인해서 쓰게 됩니다. 그런데 그게 아니라 6개월이 넘어서 저희들이 초빙연구원으로 채용한다 이러면 다 공개채용 합니다. 
</p>
<p><b>○ 오완석 위원 </b> 그러면 초빙연구원의 공개채용사항도 저한테 좀 주셨으면 좋겠습니다. 이건 이대로 하고요. 
</p>
<p style="padding-left:1.2em">  그다음에 한 가지 더 말씀드리면 연구원의 설립목적 중의 하나가 저는 도정의 주요이슈, 도지사 공약사항 부분들을 일원화시키고 백데이터를 만들어서 그 사업이 잘 진행될 수 있게끔 도와주는 것도 커다란 임무 중의 하나다. 그리고 어찌 보면 아주 중요한 업무 중의 하나라고 생각이 됩니다. 그래서 제가 공공임대주택에 대해서 자료요구를 했고요. 그리고 엊그제 경기도시공사 감사를 하면서 따복하우스에 대해서 질의를 했습니다. 그런데 여기 보니까 자료에는 공공임대주택에서 청년이라든가 신혼부부에 관련된 부분에 대해서 연구한 것이 있어요, 제가 읽어보지는 않았지만. 몇 가지 이것도 공공임대주택에 대한 부분도 지금 연구 중인 게 있고요. 그래서 제가 말씀드리고 싶은 것은 따복버스라든가 그다음에 따복택시 관련된 부분은 연구된 게 있어요. 제가 보지는 않았습니다. 구체적으로 어디까지 연구가 됐는지 모르겠지만 따복하우스를 지금 경기도에서 경기도형 공공임대주택으로 해서 1만 호를 공급하겠다고 하고 있습니다. 그런데 당위성이나 그다음에 왜 따복하우스 임대주택을 해야 되는가에 대한 부분에 대해서는 충분히 연구가 되겠죠. 그리고 지금 경기도에서 추구하고 있는 것처럼 신혼부부라든가 아니면 학생들이라든가 이렇게 해서 그런 쪽에 수요가 있기 때문에 그분들한테 혜택을 주기 위해서 할 수 있겠어요. 그런데 이게 도에서 추진하는 것들이 이론적이고 필요에 의해서 한다고 하더라도 중요한 것은 누가, 무엇을 가지고, 어떤 돈으로 어떻게 할 것인가에 대한 부분도 중요하다고 봅니다. 아까 제가 여기서 자료, 의왕시에서 의뢰한 청소년육성재단 설립 타당성검토에 대한 부분에 대해서 쭉 봤는데 여기 보니까 예산, 재정규모, 모든 부분들이 다 들어 있어요. 도시공사에서 그냥 하겠다라고 계획만 쭉 세워 있는데 재원을 어디에서 마련하고 그다음에 경기도시공사 현재 상태는 어떻고 과연 1만 호를 2020년도까지 공급할 수 있는 것인가. 도지사 임기는 2018년이면 끝납니다, 그렇죠?  
</p>
<p><b>○ 경기연구원장 임해규 </b> 네. 
</p>
<p><b>○ 오완석 위원 </b> 그럼 시작도, 제가 보기에는 그래서 2017년도 예산에 계획했던, 도에서 지원하기로 했던 예산을 확보했냐 그랬더니 그렇지도 못한 것 같고. 그래서 제가 생각하기에는 도정이슈에 대한 부분들이 그냥 이론적이고 피상적인 것 그다음에 당위적인 부분에 대해서 연구도 중요하지만 실질적으로 이게 사업으로서 완성을 할 수 있을 것인가. 완성품을 만들 수 있을 것인가에 대한 부분도 저는 면밀히 검토가 돼야 되지 않겠는가 싶습니다. 우리가 GTX를 예로 한다 그러면 BC분석 해 가지고 타당성 있느냐 없느냐. 그다음에 재원은 어떻게 할 것이냐. 과연 이게 해서 실효성이 있겠느냐. 그다음에 기간 내에 할 수 있겠느냐. 여러 가지가 있지 않습니까? 이런 부분들까지도 구체적으로 도정이슈에 대한 부분은 도지사 공약사업에 대해서는 백데이터를 연구해 줘야 되지 않느냐. 그래야만이 그 사업이 실질적으로 살아 있는 사업이 되고 지사가 약속한 공약을 이행할 수 있는 그런 사업이 되지 않을까 싶습니다. 물론 사업을 입안해서 공약을 해서 하다가 중간에 못하는 경우도 있겠죠. 물론 본인 대에 하기로 했는데, 2020년까지 하기로 했는데 본인이 2018년도에 그만두니까 나머지 부분에 대해서는 도지사가 바뀌면 그 정책에 대해서 안 할 수도 있지 않습니까? 
</p>
<p><b>○ 경기연구원장 임해규 </b> 네.
</p>
<p><b>○ 오완석 위원 </b> 그런데 그것들이 탄탄하게 조사된, 탄탄하게 연구된, 탄탄하게 타당성이 검토된 상태라면 차기 도지사도 그 부분에 대해서 쉽게 버리지 못할 것이다. 그래서 상당히 중요하다라는 생각이 듭니다. 그래서 많은 주요목적들이 있겠지만 그중에서도 도지사 공약사업, 도정이슈에 대한 분석 그다음에 보고, 타당성검토 이런 부분들이 면밀히 이루어졌으면 좋겠다라고 말씀드리고 싶습니다.
</p>
<p><b>○ 경기연구원장 임해규 </b> 네, 그렇게 하도록 하겠습니다. 사실 위원님 말씀마따나 어떤 한 정책을 최초에는 타당성과 재원이 어느 정도 될 거다, 재원을 어느 정도 동원할 수 있다 이렇게 연구하지만 그게 막상 집행부에 들어가서 거기서 구체화하는 과정 또 의회에 가서 예산을 받는 과정, 이런 과정에서 변형되거든요. 그러면 결국은 한 번의 연구로 끝나는 게 아니라 주요한 정책과제나 이런 것들은 후속연구가 계속 이어져야 합니다. 중간에 또 그것이 잘 안 된 요인이 뭐가 있고 잘된 요인이 뭐가 있고 이렇게 또 한 번 해야 됩니다. 저희들이 2040연구를 해도 2040 후속연구를 계속 해야 되고 북부 10개년 계획을 연구를 끝냈어도 또 거기에 대한 후속연구를 시군별로 다 해야 되거든요. 그래서 그런 취지에서 저희들도 굉장히 공공임대주택문제 중요하다고 보고 있고 우리 공감도시연구실의 가장 중요한 과제입니다. 그래서 말씀 주신 것처럼 저희들이 변화된 조건에서 새로운 후속연구를 계속 하겠다는 생각을 가지고 있습니다. 꼭 그렇게 하도록 하겠습니다. 
</p>
<p><b>○ 오완석 위원 </b> 부탁을 드리겠습니다. 이상입니다.
