<p><b>○ 최춘식 위원 </b> 수고 많으십니다. 한 가지만 좀 제가 질의를 드리려고 센터장님 좀 앞으로 나오시라고 했습니다. 예측하실지 모르겠지만 지난번 포천시 장자산단의 에너지보급시설에 대한 부분 연구하신 것 있잖아요? 이 부분에 대해 질의 좀 드릴게요. 여기에 처음 제가 우리 센터장님하고 김동영 박사하고 또 한 분 오셨었죠? 제가 잘…….
