<p><b>○ 북부연구센터장 김동성 </b> 네, 문미성 박사. 셋이 갔었습니다. 
</p>
<p><b>○ 최춘식 위원 </b> 그때 현장까지 나가서 제가 말씀드린 부분은 이것을 어떤 학술적인 부분만 가지고는 풀어나갈 수 없는 거라고 제가 말씀을 드렸고 현재 있는 현 실태를 충분히 감안해 가지고 거기에 대해서 업체, 소위 말하는 발전 내지는 열 공급을 하겠다는 업체의 관계자까지도 만나게 하면서 처음에 시도했던 것과 지금의 사정이 달라졌을 수 있으니까 그 부분까지 감안해서 분석을 해서 거기에 대한 대응방안을 주십사 이렇게 부탁의 말씀을 드렸었어요. 그런데 그 뒤에 제가 자료를 받았는데 내가 가지고 있는 거하고 업체가 주장하는 것을 그때 이미 내가 가지고 있기 때문에 좀 비교해 보니까 잘 안 맞아요, 이게. 그래서 이 부분을 내가 가지고 답을 못 드리고 있었는데 그게 다른 쪽으로 유출이 된 그런 과정들이 있었습니다. 
</p>
<p style="padding-left:1.2em">  우리 김동영 박사는 제가 시의 자료를 좀 보다 보니까 2014년도에 토론회에 참석했던 경력이 있더만요, 보니까. 그거 모르고 계십니까? 여기 오셨습니까? 
