</p>
<p style="padding-left:1.2em">  배출허용기준, 소위 말하면 수도권 대기배출허용기준 거기에 대한 부분이 보니까 서로 괴리감이 있었고 출입하는 석탄을 싣고 오는 차량의 대수에 대한 부분이 업체와 우리 박사님이 좀 다른 부분이 있습니다.
</p>
<p style="padding-left:1.2em">  그다음에 사용연료에 대한 거, 유연탄과 LNG에 대한 것은 왜 도입됐는지는 너무나 잘 알고 계시기 때문에 이 부분에 대해 가지고는 더 이상 언급하지 않고 그다음에 장자산단에서 배출하는 부분에 대해서 배출량에 대해 가지고 이것이 서로 업체하고 우리 연구하신 박사님하고 조금 이질감이 있습니다. 여기에 대해서는 제가 전자에 말씀드린 대로 전문적인 연구분야이기 때문에 어떤 드릴 말씀 없어요, 이건요. 그대로 좋습니다. 받아들이고요.
</p>
<p style="padding-left:1.2em">  다만 이거 한 가지요. 고체연료 사용금지지역으로 포천이 되어 있다고 말씀하셨죠. 그렇죠? 박사님은.
