<p><b>○ 최춘식 위원 </b> 이건 제가 여기서 더 이상 언급 안 하겠습니다. 가서 그것이 다른 쪽으로 이용이 됐어요. 활용이죠, 활용으로 봐야죠. 활용이 돼 가지고 이 부분이 지역지에 또 지방지에 대서특필하고 이렇게 쭉 나왔는데 이러한 박사님이 연구했던 그 문건 자체가 지금까지가, 배포되기 전까지 말씀드리는 겁니다. 그때까지가 이게 완성품입니까, 아니면 완성품이 아닙니까? 
