<p><b>○ 경기연구원장 임해규 </b> 언론에 보도되고 난 다음에 저희가 검토를 했습니다, 경기연 차원에서. 그런데 저희는 우선 제일 먼저 확인한 것은 김동영 박사께 근거가 충분히 본인이 그렇게 발표되는 것, 대외적으로 공개되는 것에 대해서 내용상의 책임을 질 수 있을 정도의 확고한 연구결과냐 해서 그렇다고 확인했습니다. 그래서 저희들이 사실 공개, 비공개를 결정할 때 원래는 그게 지역사회에 큰 어떤 파장이 있다거나 이럴 때는 보통 비공개하는 게 일반적입니다만 이미 그 자료는 나갔기 때문에, 그리고 문제가 됐기 때문에 그것을 그때 상태에서 비공개로 하는 것은 의미가 없다고 생각을 했습니다. 이미 업체도 가지고 있었기 때문에. 그래서 그건 관계되는 기관에 빨리 그 내용을 주는 것이 오히려 사태를 정확하게 처리하는 데 맞겠다 싶어서 저희들이 그렇게 결정해서 관계기관에 다 배부를 했습니다.
