<p style="padding-left:1.2em">  그러나 이것이 파급효과라는 것이 엄청나게 와 작용하는 부분이기 때문에 이것을 좀 더 심도 있게, 전자에 내가 말씀드린 대로 이질감이 있는 몇 가지 사안이 있잖아요, 여기에. 이것은 업체가 이런 것을 주장하고 있을 때 이것에 대해서 배출기준을 지키겠다고 한다면 연구과정에 이 부분을 좀 포함시켰어야 된다는 거죠. 그래서 업체에서 제시하는 수치를 놓고 분석을 해 주셨어야지. 그것을 제가 2014년도의 자료를 말씀드리는 이유가 뭐냐 하면 그때 김동영 박사가 그때 패널로 참석했던 토론회기 때문에 거기에서 말씀하신 부분과 여기에 수록되어 있는 것이 거의 같을 거라는 생각 때문에 그럽니다. 그렇다면 업체의 사정은 변했다는 거죠. 그러면 이것도 같이 포함해서 분석해 줬어야 된다는 겁니다. 그런데 그 부분이 이렇게 됐는데 이걸 제가 드리는 말씀은 결국은 사전 배포된 것 때문에 배포됐다니까 할 말 없어요. 그러나 앞으로 만약에 이런 일이 또 있을 때에도 이렇게 배포가 될 수 있는 것인가 그걸 제가 여쭤보고 싶은 겁니다.
</p>
<p><b>○ 경기연구원장 임해규 </b> 일반적으로 지역에 큰 갈등이 있는 예민한 연구를 저희들이 스스로 하는 경우는 없거든요. 보통은 도 집행부에서 주로 이런 연구가 있으니까 해 달라 그러고 그럴 경우는 과제를 의뢰하는 사람이 “이것은 비공개로 해 주십시오.” 하고 비공개 요청을 보통 하는 경우입니다. 그렇기 때문에 이런 일이 잘 발생하지 않는데 오히려 그래서 문제가 발생하기보다는 다른 어떤 경로를 통해서 그냥 정보가 비공식적으로 흘러나가서 보통 문제가 되죠, 이런 경우보다는. 그런데 이번 경우는 아무래도 그냥 위원님이 바로 상임위원회 의정활동하는 과정에 그냥 한번 연구를 해 달라 그래서 우리도 그것을 정식과제로 연구를 하기보다는 해당 연구자가 가장 빠른 시일 내에 위원님한테 의정서비스를 하는 형태로 되다 보니까 비공개나 이런 절차를 충분히 밟지 못했던 것 같습니다, 저희들도. 그래서 아마 그런 것들이 부주의하게 다뤄져서 그렇게 되지 않았나 싶습니다. 그런데 향후 이런 갈등이 상당히 유발될 수 있는 사안에 대해서는 저희들이 내부적으로도 공개, 비공개 여부를 충분히 관계자들과 협의해서 잘 처리하도록 하겠습니다.
