<p><b>○ 최춘식 위원 </b> 물론 저 자신도 이 부분에 대해 가지고는 지금 원장님이 말씀하시듯이 공개, 비공개에 대한 부분을 저 또한 단서를 달지 못했기 때문에 그 부분까지 생각을 못했던 사항이고 또 본의 아니게 이것이 유출된 거니까 거기에 대해 가지고 이런 잘잘못을 따지고 싶은 생각은 아닙니다. 그러나 앞으로 이러한 게 있을 때는 저희가 잘 알지 못하는 부분에 대해 가지고 먼저 단서조항을 달아주시는 것도 좋을 것 같아요.
