<p><b>○ 임채호 위원 </b> 이 내부규정을 한번 자료로 제출해 주시고요. 이건 의회에서 좀 심도 있게 고려해 봐야 할 사항인 것 같습니다. 다음은 봉인식 선임연구원 계십니까?
</p>
<p><b>○ 경기연구원장 임해규 </b> 네? 
</p>
<p><b>○ 임채호 위원 </b> 봉인식. 지금 여기 계십니까?
</p>
<p><b>○ 경기연구원장 임해규 </b> 이 자리에는 없습니다만…….
</p>
<p><b>○ 임채호 위원 </b> 도시재생 정책방향 수립 연구와 관련돼서 좀 하려고 그러는데 왜 오늘 여기 자리에……. 
</p>
<p><b>○ 경기연구원장 임해규 </b> 모든 박사가 다 있는 게 아니라 여기는 지금 증인으로 출석돼 있는 박사 전체가 아니고 간부들만 와 있습니다.
</p>
<p><b>○ 임채호 위원 </b> 그래서 여기에는 지금 없으시다?
</p>
<p><b>○ 경기연구원장 임해규 </b> 네.  
</p>
<p><b>○ 임채호 위원 </b> 그래요. 그러면 말이에요. 우리 원장님이 답변하실 수 있을까 모르겠네요. 제가 아까 말씀드렸다시피 경기도의 열악한 주거환경, 최저주거기준 미달가구수가 상당히 많습니다, 경기도가. 다른 지역에 비해서 가장 많은 데가 경기도입니다. 그래서 이러한 연구를 하신다고 그랬어요. 봉인식 연구관님께서, 박사님께서 이런 연구를 한다고 그래서 어느 정도 알고 앞으로 향후 어떠한 기획을 가지고 있으신가를 알기 위해서 세웠으면 좋겠는데 좀 이따가 그럼 질의하는 걸로 하고 수배 좀 해 주셔서 오시면 바로 될 수 있게.
</p>
<p><b>○ 경기연구원장 임해규 </b> 네, 지금 부르러 갔습니다. 
</p>
<p><b>○ 임채호 위원 </b> 위원장님, 이상입니다. 이따가 봉인식 박사님 오시면 질의하도록 하겠습니다. 
</p>
<p><b>○ 위원장 이재준 </b> 임채호 위원님 수고하셨습니다. 다음 장동일 위원님 질의해 주시기 바랍니다. 
</p>
<p><b>○ 장동일 위원 </b> 네, 장동일 위원입니다. 원장님 수고하십니다. 경기연구원의 설립목적이 국가발전, 경기도 소속 시군의 경쟁력 강화, 도민의 삶의 질 향상 등을 위해서 체계적이고 종합적인 이런 연구를 하는 것이 목적인데, 그런 과제를 수행하는 것이. 그런 차원에서 여러 가지 도의 과제도 수행하고 했는데 주로 추격연구, 그러니까 선도적인 연구가 아니고 추격연구 이런 지적에 대해서는 어떻게 생각하세요? 연구라는 게 선도적이어야 되는데 자꾸 현실에 대한 추격연구랄지 이런 것에 너무 안주하는 게 아니냐는 그런 지적에 대해서는 어떻게 생각하세요?
</p>
<p><b>○ 경기연구원장 임해규 </b> 저희들도 선도적인 연구가 되게 하기 위해서 문제의식을 가지고 있습니다. 그래서 저희들이 하는 제도는 전략연구는 선도적인 연구가 될 수 있도록 하고 있고 제가 오고 난 다음에는 전략연구를 상당히 늘렸습니다. 그래서 예산도 많이 배정하고 또 숫자도 좀 늘리고 그래서 그런 방향으로, 예를 들면 북부 10개년 계획이나 동부 10개년 계획 이런 건 상당히 전략적이고 또 선도적인 연구를 하려고 하는 거거든요. 또 에너지비전 같은 걸 만들었다거나 이런 것도 굉장히 선도적인 연구라고 생각을 합니다.
</p>
<p><b>○ 장동일 위원 </b> 금융위기를 거치면서 우리 사회의 기본적인 틀이 바뀌었어요. 그러다 보니까 자치단체나 이런 데서 정책을 수행하는 데 있어서 굉장히 그런 역량이 좀 부족한 부분이 있다 보니까 연구, 특히 경기도 같은 경우 경기연구원에서 이런 부분들을 좀 선도적으로 정책을 수립해 주고 해야 될 거라고 생각하는데 아까 여러 가지 얘기들은 나왔지만 저는 거시적인 차원에서 몇 가지를 같이 좀 얘기해 보도록 하겠습니다. 보면 80년대, 90년대에는 PC, 2000년대는 웹, 2010년대는 모바일 이런 식으로 시대가 10년 단위로 바뀌어 가잖아요. 그러면 2020년, 30년 이후에는 어떻게 사회가 변해갈 것으로 보십니까, 연구자의 입장에서?
</p>
<p><b>○ 경기연구원장 임해규 </b> 빅데이터에 기반한 인공지능이 주도하는 사회가 될 걸로 보고 있습니다.
</p>
<p><b>○ 장동일 위원 </b> 그러니까 지난번에 플랫폼 관련해서 우리가 박사님하고 토론회도 하고 했는데 판을 까는 거죠, 이게. 야후 같은 경우 혹시, 우리 공감도시연구실장님 좀 발언대로 나와 주실래요? 공감도시연구실장님.
</p>
<p><b>○ 공감도시연구실장 이외희 </b> 공감도시연구실 이외희입니다.
</p>
<p><b>○ 장동일 위원 </b> 뭐 좀 질의하겠습니다.
</p>
<p><b>○ 공감도시연구실장 이외희 </b> 네.
</p>
<p><b>○ 장동일 위원 </b> 플랫폼 세상이 올 것이다. 플랫폼에 대해서 연구를 주도하고 계시나요?
</p>
<p><b>○ 공감도시연구실장 이외희 </b> 플랫폼은 저희 연구실에 GIS 데이터로 빅데이터 관련한 옥진아 박사하고 또 경제 측면에서는 상생경제연구실에서 같이 연구하고 있습니다.
</p>
<p><b>○ 장동일 위원 </b> 아, 상생경제연구실.
</p>
<p><b>○ 공감도시연구실장 이외희 </b> 경제 측면에서는.
</p>
<p><b>○ 장동일 위원 </b> 그러면 실장님은 해당이 안 되시네?
</p>
<p><b>○ 공감도시연구실장 이외희 </b> 직접 연구는 하지 않고 있지만 저희 부서에서 연구하고 있습니다. 
</p>
<p><b>○ 장동일 위원 </b> 그래요. 빅데이터 관련해서 플랫폼 관련정책을 경기도에서 아주 의욕적으로 추진하고 있는데 어떤 부분들을 앞으로 좀 체계화해야 된다고 생각하시나요? 앞으로 5년, 10년 후에는 영어도 필요 없다고 그러네요. 이렇게 귀에 뭐 꼽기만 하면 그냥 다 해석해 주고 이런 시대가 올 거라고 그래서 사회가 급격하게 변하고 있는데 우리 경기연구원에서는 앞으로 5년, 10년 후의 방향들을 어떻게 보고 계신지 거시적인 차원에서 제가 한번 여쭈어 보는 거예요.
</p>
<p><b>○ 공감도시연구실장 이외희 </b> 제가 구체적으로 답변드리기는 좀 그렇긴 한데 사실 지금 기술이 워낙 혁신적으로 바뀌고 있기 때문에 어떻게 예측하기가 힘든 면이 있습니다만 어쨌든 4차혁명이 계속 화두가 되고 있기 때문에 융복합으로 해서 그런 데까지 앞으로 갈 수 있지 않을까 생각은 하지만 한편으로는 또 기술이란 게 사실 그렇게 쉽게, 지금까지 기술이 굉장히 많이 발전되었기 때문에 이런 미세한 혁신적인 기술이 쉽게 이렇게 개발될 수 있으리라고는 조금 부정적인 생각도 저 개인적으로는 갖고 있습니다. 
</p>
<p><b>○ 장동일 위원 </b> 제조업이 너무 힘들고 취업이 안 되고 하다 보니까 4차산업혁명이 도래하면 제조업이 더 붕괴되고 그러다 보면 취업은 더 안 되고 이런 문제가 사회적인 현상으로 복잡하게 일어날 것이라고 미래학자들이 그런 얘기를 해서 제가 그런 차원에서 한번 질의를 해 본 겁니다. 
</p>
<p style="padding-left:1.2em">  들어가시고요. 그다음에 공존사회연구실장님 좀 나와 주실래요?
</p>
<p><b>○ 공존사회연구실장 이용환 </b> 공존사회연구실 이용환입니다.
</p>
<p><b>○ 장동일 위원 </b> 작년에도 제가 지방분권에 대해서 얘기를 좀 했는데 연구를 하시기도 했는데 앞으로 이런 연구가 더 좀 나왔으면 좋겠어요. 사회가 어지러울수록 지방자치가 자리를 잡아야, 국가가 하나하나 해결할 수 없고 다 일일이 관여할 수 없어서 지금 이렇게 사회가 시끄러워도 지방자치가 안정돼 가다 보니까 우리 경기도는 별 큰 문제없이 굴러가잖아요. 그래서 지방분권에 대해서 아직도 미흡한 부분이 너무 많다. 그래서 그런 부분에 대해서 좀 신경을 써야 된다고 생각하는데 연구에 대해서 어떻게 생각하세요?
</p>
<p><b>○ 공존사회연구실장 이용환 </b> 너무 당연한 말씀이시라고 생각합니다. 저희들도 지금까지도 계속 노력은 했습니다만 우리가 전통적인 중앙ㆍ지방의 관계가 크게 개선되고 있지는 않습니다. 그렇다 할지라도 향후 미래사회에는 중앙ㆍ지방의 수평적 관계가 돼야 되고 지방에서도 보다 자주적이고 자율적으로 정부 운영을 할 수 있는 이런 방향으로 가야 되기 때문에 저희 부서에서는 지방분권이라든가 지방자치 또 주민자치 이런 분야에 대해서 연구를 보다 강화할 그런 생각을 갖고 있습니다.
</p>
<p><b>○ 장동일 위원 </b> 앞으로 특히 분권에 대해서, 이번에 저희들이 너무나 분권에 대해서 또 한 번 그런 것을 절감하게 됐어요. 중앙정치가 너무 엉망이고 그래서 우리 지방자치가 확실하게 뿌리를 내려야 사회가 안전하게 유지될 수 있다 하는 그런 생각을 굳게 갖게 됐습니다. 그런 측면에서도 더 좀 부탁드리겠습니다. 
</p>
<p style="padding-left:1.2em">  자리해 주시고요.
</p>
<p><b>○ 공존사회연구실장 이용환 </b> 네, 감사합니다.
</p>
<p><b>○ 장동일 위원 </b> 원장님께 좀. 경기도 종합감사 결과 처리내역을 보면 출장비, 공용차량 관리비 이런 기본 업무절차에 부적정한 부분이 많이 나타났다 이런 지적이 있었어요. 이게 어떤 내용입니까?
</p>
<p><b>○ 경기연구원장 임해규 </b> 2015년도 종합감사…….
</p>
<p><b>○ 장동일 위원 </b> 여기 보면 감사 지적사항 중에 장애인 법정 고용의무 소홀로 인한 것들이 지적되고 했는데 채용계획을 수립해서 시행하겠다고 했는데 이후 개선된 사항이 있습니까?
</p>
<p><b>○ 경기연구원장 임해규 </b> 차량계획은 제가 타고 다니는 차량 문제입니다. 그런데 그게 저희 차량이 구입된 이후에 공공기관 차량의 배기량이 다 정해서 내려왔습니다. 그런데 그게 제가 사용하고 있는 차량이 그 배기량을 넘기 때문에 교체해야 되는 대상이 됩니다. 그런데 저희들이 3년을 리스해서 쓰고 있습니다. 그런데 그걸 지금 바꿀 경우에는 위약금을 물어야 돼서, 또 공문에는 위약금은 물지 말라 이렇게 되어 있습니다. 그래서 사용 이후에 아마 재계약할 때는 기준배기량으로 낮춰야 된다 이런 생각을 저희들이 계획을 가지고 있고요. 그리고 다른 사항은…….
</p>
<p><b>○ 장동일 위원 </b> 여러 가지 지적사항들이 있는데 여기 보니까 수당이나 여비 같은 게 좀 안일하게 집행됐다 이런 것들이 지적됐는데 이후에 그런 것들을 잘 모니터링하고 시정이 됐는지 이걸 좀 여쭤보는 거예요.
</p>
<p><b>○ 경기연구원장 임해규 </b> 나머지 수당지급 문제는 전부 다 시정조치를 했고요.
</p>
<p><b>○ 장동일 위원 </b> 장애인 채용 관련돼서는 어떻게 좀 성과가 있었나요?
</p>
<p><b>○ 경기연구원장 임해규 </b> 저희들이 지금도 정부에서 정한 기준에 1명이 못 미치는 상태에 있습니다. 그래서 다음에 저희들이 정규직을 뽑는 건 사실 굉장히 어려움이 있기 때문에 어쨌든 그걸 아예 한정해서, 그러니까 장애인만을 뽑는 걸로 한정해서라도 저희들이 뽑을 그런 계획을 가지고 있습니다.
</p>
<p><b>○ 장동일 위원 </b> 그건 이따가 제가 추가로 질의할 시간에 한번 확인해 보도록 하겠습니다. 결론적으로 연구원은 연구윤리하고 성과 그다음에 연구의 질 이런 것이 핵심인데 이런 부분들에 대해서 정말로 거시적으로 어떤 방향으로 정책을 수립하고 우리 연구원이 나아가야 될지를, 아까 제가 두리뭉실하게 여러 가지 4차 아니면 플랫폼 등등 우리가 가상세계에서나 들어볼 수 있는 그런 것들을 그냥 막연하게 질의를 좀 했는데 앞으로는 5년, 10년 안에 그런 세상이 온다는 거죠. 그래서 그런 것들을 선도적으로 연구를 해서 저희들이 같이 공유할 수 있도록 그런 부분에도 신경을 각별히 써주셨으면 좋겠다는 생각을 하게 됩니다.
</p>
<p><b>○ 경기연구원장 임해규 </b> 네, 그러겠습니다. 저희들이 전략연구로 지금 하고 있는 게 우선 일본의 잃어버린 20년으로부터 우리가 뭘 배울 건가 이 점을 한편으로 하고 있고요. 또 다른 한편으로 4차산업혁명에 대한 연구를 저희들이 좀 할 생각입니다. 그래서 생각보다도 그것이 경제 전반이나 사회 전반에 미칠 파급이 굉장히 클 걸로 보고 있기 때문에 거기에 맞춰서 우리가 선도적으로 공공영역에서, 공공부문에서 어떤 노력을 기울여야 될 건가 이런 점도 해야 될 연구라고 보고 있고 아마 다양한 국가 연구기관에서도 다 그 연구를 하고 있습니다, 보니까. 그래서 저희들도 그 연구를 할 계획을 가지고 있습니다.
</p>
<p><b>○ 장동일 위원 </b> 그러니까 아까 여기 보면 경기연구원이 세계적 수준의 정책연구기관을 목표로 하고 있는데 맥킨지연구소 같은 데하고 어깨를 나란히 하려면 이런 거 연구해야 된다는 거죠.
</p>
<p><b>○ 경기연구원장 임해규 </b> 그렇습니다. 그렇게 생각하고 있습니다. 
</p>
<p><b>○ 장동일 위원 </b> 그래서 이런 부분들에 대해서 저희들은 아직 여기에 대한 어떤 전문적인 것이 전혀 없기 때문에 경기연구원에서 이런 걸 선도적으로 해 주셨으면 좋겠다는 생각을 하게 됩니다.
</p>
<p><b>○ 경기연구원장 임해규 </b> 네, 그렇게 하겠습니다.
</p>
<p><b>○ 장동일 위원 </b> 이따가 또 질의하겠습니다. 감사합니다. 
</p>
<p><b>○ 위원장 이재준 </b> 장동일 위원님 수고하셨습니다. 얼마 전에 9월 달 보도자료가 하나 나왔었어요. 주요 도정이슈라는 거 있죠, 13개 분야?
</p>
<p><b>○ 경기연구원장 임해규 </b> 네.
</p>
<p><b>○ 위원장 이재준 </b> 그걸 연구한 목적이 뭔가요?
</p>
<p><b>○ 경기연구원장 임해규 </b> 저희들이 도로부터 다양한 현안에 대한 연구 요청이 있습니다. 그러면 저희들이 가능한 범위에서 작업을 해서 제출합니다. 그런 사업의 일환으로 한 것입니다.
</p>
<p><b>○ 위원장 이재준 </b> 그런데 여기 연구과제 2016년도 제출한 자료목록에는 여기에 있는 것들이 없는 것 같아요.
</p>
<p><b>○ 경기연구원장 임해규 </b> 다 제출을 했습니다. 저희들이 현안연구 한 것은…….
</p>
<p><b>○ 위원장 이재준 </b> 아니, 그러니까 13개 현안 주요 도정이슈라는 것이 지금 우리한테 제출한 목록에는 없는 것 같다고, 행감 자료에 제출한 목록에. 389페이지부터…….
</p>
<p><b>○ 경기연구원장 임해규 </b> 저희 업무보고서 지금 드린 것의 36쪽에 있습니다. 우리 GRI 현안브리프라고 하는 것에 들어 있습니다. 그리고 2016년 기타 도정 검토 실적이라고 하는 것에 들어 있습니다. 
</p>
<p><b>○ 위원장 이재준 </b> 그런데 여기서 얘기하는 이명박ㆍ박근혜 정부의 정책 비교분석 이런 것들이 사실 필요한 게 아니고 여기에도 지금 목록이 없는데요? 기타 도정…….
</p>
<p><b>○ 경기연구원장 임해규 </b> 36쪽에 보면.
</p>
<p><b>○ 위원장 이재준 </b> 아니, 36쪽 거기에도 결국은 이명박ㆍ박근혜 정부 정책 비교분석이란 건 없고 증세정책이라는 것도 없고. 그러니까 뭐냐 하면 이것을 사실상은…….
</p>
<p><b>○ 경기연구원장 임해규 </b> 방금 말씀하신 제목은 저희들이 연구를 수행한 적이 없는 것 같은데요?
</p>
<p><b>○ 위원장 이재준 </b> 그러니까 이명박ㆍ박근혜 등 전ㆍ현직 대통령 정권의 정책을 비교분석, 증세논쟁에 대한 기조와 대책을 내놓기도 했다 이런 거거든요.
</p>
<p><b>○ 경기연구원장 임해규 </b> 그런 건 연구를 저희들이 한 바가 없습니다.
</p>
<p><b>○ 위원장 이재준 </b> 저한테 준 논문이 있어요, 이 자료에 대해서 보고서가. 13개 현안이슈로 해서 주요 도정이슈라는 것이. 그런데 여기에서 다룬 얘기들이 대부분 우리 경기도의 정책이 아니라 국가의 정책이라는 거죠. 그동안은 이런 게 없었는데 국가의 정책에 집중을 해서 연구를 했는데 이것을 왜 연구했냐 이런 거죠. 여기에 참여하신 분들은 누구고. 그것 답변 좀 해 주시죠.
</p>
<p><b>○ 경기연구원장 임해규 </b> 36쪽에 보면 연구를 한 연구자 이름도 쓰여 있고요, 과제도 다 있습니다. 그런데 보시기에는 그렇게 보실 수도 있는데 대부분 저희들이 하는 연구가 특히 도에서 요구하는 단기과제들 같은 경우는 꼭 경기도에 특화된, 경기도 지역에서만 일어나는 연구과제를 하지는 않거든요. 예를 들어서 전월세 대란 그러면 그게 꼭 경기도에만 전월세대란이 일어나는 것이 아니지 않습니까? 
</p>
<p><b>○ 위원장 이재준 </b> 그렇죠. 전월세 대란이나 이런 것들은 이해를 하는데 간접세 증세현황 이런 것까지도 분석내용에 담는다면 이것이 과연 경기도가 이런 일을 했었는가 이런 생각이 드는 거죠.
</p>
<p><b>○ 경기연구원장 임해규 </b> 그런데 그것도 위원장님 보시기에 사실 우리 도의 재정에 관련된 연구를 하려면 백그라운드로 지금 중앙정부에서 벌어지고 있는 증세와 관련된 여러 가지 논쟁이나 그것에 대해서 우리가 어떤 스탠스를 가져야 될 건가 하는 걸 사실 도 정책을 하는 사람은 모르면 안 되는 거거든요. 그러니까 백데이터로는 그런 연구를 저희들이 일정하게, 그러니까 그게 정책연구 수준에서는 하기가 어려운데 현안브리프와 같은 브리프 형식으로는 저희들이 계속 그런 자료를 냅니다. 
</p>
<p><b>○ 위원장 이재준 </b> 지금 경기연구원에서 경기도청에 파견 나가 있는 분이 여섯 분이에요, 연구원이.
</p>
<p><b>○ 경기연구원장 임해규 </b> 3명 파견 나가 있습니다. 
</p>
<p><b>○ 위원장 이재준 </b> 세 분밖에 안 됩니까? 거의 1년 된 게 제가 받은 자료에서는 다섯 분인가 여섯 분인데 옛날에도 그런 적이 있나요?
</p>
<p><b>○ 경기연구원장 임해규 </b> 도의 특정한 정책과 관련해서 파견 나간 경우는 좀 있습니다.
</p>
<p><b>○ 위원장 이재준 </b> 그러니까 한 분이나 두 분이었지 제가 받은 자료는 거의 1년씩 나가 있는 분이 다섯 분인가 여섯 분이에요.
</p>
<p><b>○ 경기연구원장 임해규 </b> 그건 나갔다가 들어오고 나가고 이렇게 한 총 인원이라서 그렇지…….
</p>
<p><b>○ 위원장 이재준 </b> 그렇죠, 1년씩. 그런데 같이 같은 기간에 이렇게 맞물려 있는 거죠.
</p>
<p><b>○ 경기연구원장 임해규 </b> 아닙니다. 같은 기간에는 3명 보냈습니다.
</p>
<p><b>○ 위원장 이재준 </b> 그걸 우리가 도에서는 연구원의 사람을 파견을 받는 기준이 있어요, 우리 조례에 공무원 파견이라고. 그런데 우리가 연구원을 도로 파견할 수 있는 부분이 있나요, 규정에?
</p>
<p><b>○ 경기연구원장 임해규 </b> 네, 그런 근거도 있습니다. 
</p>
<p><b>○ 위원장 이재준 </b> 그건 어디에 나와 있죠?
</p>
<p><b>○ 경기연구원장 임해규 </b> 인사ㆍ복무규정에 있습니다. 그 인사ㆍ복무규정에 따라서 의회에도 파견 보내고 도에도 파견 보내고. 그래서 그전에도 파견을 보낸 사례가 몇 번 있습니다. 한두 명이 아니라 몇 명씩, 한 서너 명씩 이렇게.
</p>
<p><b>○ 위원장 이재준 </b> 남경필 지사 초기에 그것이 저희가 행감을 하면서 도지사 캠프에서부터 있었기 때문에 문제가 돼서 그때 이런 걸 안 했으면 좋겠다라고 얘기했던 기억이 있는데.
</p>
<p><b>○ 경기연구원장 임해규 </b> 아닙니다. 그때도 파견 나가서 문제가 됐던 것이 아니었고요. 파견이 문제되지는 않았고 그냥 우리 연구원 내의 전략연구센터에 재직하는 역할이 그런 역할을 했다 해서 문제가 됐었습니다.
</p>
<p><b>○ 위원장 이재준 </b> 지금 나가 계신 분들이 한 공간에서 머무시죠? 아닌가요?
</p>
<p><b>○ 경기연구원장 임해규 </b> 지금도 한 공간에서 근무를 하고 있습니다.
</p>
<p><b>○ 위원장 이재준 </b> 도청 한 공간에서 머무시죠?
</p>
<p><b>○ 경기연구원장 임해규 </b> 네, 정책실에서.
</p>
<p><b>○ 위원장 이재준 </b> 그 정책실은 뭐하는 건가요? 우리 직제에 없는데.
</p>
<p><b>○ 경기연구원장 임해규 </b> 정책실이 도지사의 정책에 대해서 연구를 지원하는 그런 업무를 하고 있습니다.
</p>
<p><b>○ 위원장 이재준 </b> 제가 볼 때는 공무원 정원관리 규정에 어긋나는 것 같은데 아닌가요, 그것이?
</p>
<p><b>○ 경기연구원장 임해규 </b> 파견은 저희들도 법에 의해서 도의 인사위원회에서도 저희들한테 요청을 하고, 도에서 저희들한테 우선 파견 요청을 합니다. 그럼 저희들이 파견을 보내는 거죠. 그러니까 저희들이 파견 가서도 정책연구 지원을 하는 경우는 저희들 내부규정에 따라서 하고 있습니다.
</p>
<p><b>○ 위원장 이재준 </b> 그러니까 일례를 들면 한 분이 환경전문가라고 하면 환경부서에 가서 근무하는 건 맞아요. 그런데 그 전문가들을 한 공간에 모아놓고 여섯, 일곱 분이 같이 근무를 해 가면서 어떤 일들을 한다는 것은 사실상은 상당히 오해를 불러일으킬 수 있다는 거죠. 더군다나 직제에도 없는 조직이. 지금 우리가 외주용역을 하면서 보면 인건비가 거의 50% 가까이 나가거든요, 사람들이 없어서 우리가 저기를 해 가지고. 그런데 우리 연구원들이 거기 나가서 꼭 그렇게까지 해야 되는 건지?
</p>
<p><b>○ 경기연구원장 임해규 </b> 그건 여러 가지 판단이 좀 필요할 것 같습니다. 왜냐하면 제가 이렇게 말씀드리기는 뭣합니다만 지금 의회에서 저희들에게 파견 요청하는 거랑 생각해 보시면 이게 다 비슷한 요구가 아닐까 싶습니다.
</p>
<p><b>○ 위원장 이재준 </b> 그래서 저희가 그때 했던 것이 안 돼서 연구원 내에다 두고 했던 거죠.
</p>
<p><b>○ 경기연구원장 임해규 </b> 지금도 그래서 파견형식으로 추진하고 있는 거거든요. 그때는 아예 연구원 내에 의정연구센터라고 하는 것을 두어서 실제로 일은 여기서 안 하면서, 파견도 아니면서. 그러니까 이게 법에 여러 가지 안 맞으니까 저희들이 지적을 받았는데 아예 파견을 보내는 건 법적으로 문제도 없고 그래서 서로 간에 충분한 절차를 밟아서 진행한 것인데 다만 가서 하는 그들의 일이, 흔히 우리 연구원에서 하는 일이 도지사에게 바로 가 가지고 정책 지원하는 것이 합당하냐 하는 건 논란이 될 수는 있습니다만 이게 법적으로나 이런 건 문제가 없고…….
</p>
<p><b>○ 위원장 이재준 </b> 아니, 정책실에서 하는 일이 지금 사실상은 논란이 되고 있죠, 정치적으로 오해도 사고. 그러니까 하는 소리고.
</p>
<p style="padding-left:1.2em">  그리고 올 연말에 채용계획이 있습니까, 연구원?
</p>
<p><b>○ 경기연구원장 임해규 </b> 저희들이 도의회로 파견할 13명에 대해서 채용계획을 세우고 지금 채용절차를 밟고 있습니다.
</p>
<p><b>○ 위원장 이재준 </b> 지난번에 보면 청년고용 특별법이 제정됐는데 사실상은 그것에 경기연구원도 부합하지를 못했더라고요. 그래서 채용을 한다면 그것에 맞게, 34세 이하로 사실상은 기준에 맞게 채용을 해야 되지 않나, 그런 내용들이 포함돼야 되지 않냐 해서 물어보는 겁니다. 
</p>
<p><b>○ 경기연구원장 임해규 </b> 위원장님, 지금 예를 들면 석사연구원급의 고용을 하는 경우는 거의 다 청년에 해당됩니다. 그런데 저희들이 계속 지적을 받는 건 정규직은 거의 박사들이기 때문에요. 저희 박사들 입직연령이 거의 38세입니다. 그러니까 고용을 해도 청년고용이 거의 안 이루어지기 때문에 문제가 되는 거죠. 그런데 저희들 석사연구원은 거의가 다 청년고용이기 때문에, 사실은 이번에 새로 고용하는 12명은 대부분이 청년고용일 걸로 생각하고 있습니다. 
</p>
<p><b>○ 위원장 이재준 </b> 하여간 기조실이 남아 있으니까 정책실에 대해서는 일단 우리가 연구한 목록이나 이런 걸 볼 텐데 사실 그렇습니다. 어떤 대선이라는 더 큰 꿈을 위해서 가는 것들은 좋은데 그런 것들은 사실상 외부에서 자기 개인적인 정치조직을 활용을 해야지 연구원이나 도의 공무원들을 활용한다는 이런 오해를 불러일으키지 않았으면 좋겠다는 말씀을 드리겠습니다. 
</p>
<p><b>○ 경기연구원장 임해규 </b> 저희들이 그런 의도로 전혀 하지 않았고요. 일상적인 사업의 일환으로 했고 앞으로 그런 일이 더더욱 오해가 되지 않도록 저희들이 더욱 관리를 잘하도록 하겠습니다. 
</p>
<p><b>○ 위원장 이재준 </b> 네, 고맙습니다. 이제 10분씩 본질의가 다 끝났습니다. 이제 추가 5분씩 돌아가겠는데요. 질의하실 위원님 거수로, 양근서 위원님. 
</p>
<p><b>○ 양근서 위원 </b> 방금 위원장님 질의하신 내용인데요. 저도 외부 직원 파견문제 관련해서 들여다봤는데 법적으로도 문제가 없는 건 분명해요. 그러니까 관련법규에 구체적으로는 지방공무원 임용령하고 경기연구원 인사ㆍ복무규정에 따라서 지방자치단체에서 관련절차를 밟아서 요청을 하면 파견할 수 있다고 봅니다. 저는 경기도에 파견하는 것하고 경기도의회에 파견하는 것하고 이것도 굉장히 차별적으로 파견제도를 운영하고 있다는 생각이 들어요. 지금 현재 경기도에 파견된 직원이 다 박사급이에요, 그렇죠? 
</p>
<p><b>○ 경기연구원장 임해규 </b> 그렇습니다. 
</p>
<p><b>○ 양근서 위원 </b> 연구위원들입니다, 정규직입니다. 그런데 경기도의회에 한 명이 지금 유일하게 입법정책담당관실에 파견이 돼 있습니다. 이것도 경기도의회에서 요청을 한 건데 여기는 지금 비정규직 석사급 계약직 연구원이 와 있습니다. 그리고 말씀하신 대로 최근에 경기도의회에서 경기연구원에서 다시 연구인력 지원을 요청했습니다. 석사, 박사를 구분해서 요청했는지 모르겠는데.
</p>
<p><b>○ 경기연구원장 임해규 </b> 구분해서 요청했습니다. 
</p>
<p><b>○ 양근서 위원 </b> 지금 파견 계획은 어쨌든 정규직 자체가 없으니까 석사를, 석사가 없으니까 석사를 임시계약직으로 채용을 해서 보내겠다는 것 아닙니까, 그렇죠? 12명을 신규채용해서 보내겠다는 얘기 아니에요, 비정규 계약직으로. 
</p>
<p><b>○ 경기연구원장 임해규 </b> 그렇습니다. 박사 4명, 석사 9명입니다.
</p>
<p><b>○ 양근서 위원 </b> 그러니까 보면, 박사도 있어요? 
</p>
<p><b>○ 경기연구원장 임해규 </b> 그렇습니다. 
</p>
<p><b>○ 양근서 위원 </b> 어쨌든 다 비정규직 아니에요.
</p>
<p><b>○ 경기연구원장 임해규 </b> 박사급 연구원 4명에.
</p>
<p><b>○ 양근서 위원 </b> 구체적으로 그러면 우리 경기도의회에서 요구를 할 때 박사급 몇 명, 석사급 몇 명 이렇게 요청했습니까, 아니면 포괄적으로.
</p>
<p><b>○ 경기연구원장 임해규 </b> 그렇게 요청했습니다. 
</p>
<p><b>○ 양근서 위원 </b> 그렇게 요청했습니까? 왜 거기 경기도에서 요청한 데는 정규직 박사연구위원을 보내고 경기도의회에는 다 비정규직을 보냅니까? 
</p>
<p><b>○ 경기연구원장 임해규 </b> 그렇게 정규직으로 요청하면 그렇게 보낼 수 있습니다. 대신에 그렇게 하면 정규직 정원을 늘려주셔야 되는 거죠. 도하고 협의를 좀 하셔야 되는 거죠. 
</p>
<p><b>○ 양근서 위원 </b> 경기도에 파견 나간 연구위원들은 정원을 늘려 가지고 파견됐습니까? 정원 내에 있는 인력을 지금 경기도에 파견한 거 아닙니까? 
</p>
<p><b>○ 경기연구원장 임해규 </b> 그렇습니다. 
</p>
<p><b>○ 양근서 위원 </b> 그렇잖아요. 그럼 경기도의회에서 요청할 때는 왜 파견을 못해 주시는 거예요?
</p>
<p><b>○ 경기연구원장 임해규 </b> 파견을 할 수 있습니다. 
</p>
<p><b>○ 양근서 위원 </b> 그럼 그렇게 해 주세요.
</p>
<p><b>○ 경기연구원장 임해규 </b> 그렇게 하겠습니다. 
</p>
<p><b>○ 양근서 위원 </b> 아니, 분명하게 명시적으로 봤을 때 차별적인 파견제도를 운영하고 있는 거 아닙니까? 
</p>
<p><b>○ 경기연구원장 임해규 </b> 그렇지 않습니다. 저희들이 그렇게 하겠다는 의도도 없었고. 
</p>
<p><b>○ 양근서 위원 </b> 지금 자체가 그래요. 
</p>
<p><b>○ 경기연구원장 임해규 </b> 작년에 요청을 할 때도 제가 의회는 왜 파견 안 하냐, 그래서 의회도 파견해 드릴 수 있다고 얘기를 했습니다. 
</p>
<p><b>○ 양근서 위원 </b> 그러니까 경기도는 정규직, 경기도의회는 비정규직 이렇게 지금 파견을 하고 있는 거예요. 어쨌든 지금 현실적으로 그렇게 드러난 거죠. 그게 차별적인 거죠, 그러니까. 정규직으로 파견해 주세요, 그러면. 훨씬 더 연구경험도 많고 경륜도 더 많이 있을 것 아닙니까? 그럼 좋은 성과를 내겠죠. 그것이 연구 질의 차이를 담보하는 것이라면.  
</p>
<p style="padding-left:1.2em">  계속해서 임금차별문제를 지적하겠는데요. 저는 경기연구원이 조금 전에 지적했던 정규직과 비정규직의 차별뿐만 아니라 박사와 석사에 대한 일종의 학벌, 학력차별도 존재된 게 이중차별구조가 굉장히 구조화돼 있다 이렇게 지금 봅니다. 왜 그러냐면요. 지금 석사급 정규직 연구원은 없는데도 불구하고 일단 봉급체계는 있어요. 이 봉급체계에 따르면 석사 초임이 4,270만 원 정도 됩니다. 그렇죠?  
</p>
<p><b>○ 경기연구원장 임해규 </b> 네. 
</p>
<p><b>○ 양근서 위원 </b> 그런데 비정규직 석사는 2,870만 원 정도 돼요. 그래서 2개를 비교해 보면 비정규직 석사가 정규직 석사에 비해서 67%밖에 안 받아요. 임금구조를 봤습니다. 임금구조를 보면 정규직 같은 경우에는 기본연봉이 있고 개별성과연봉이 있고 그다음에 기관성과급 이렇게 크게 구분이 돼 있습니다. 그런데 비정규직은 어떻게 구성이 돼 있냐면 당연히 기본연봉은 있는 거죠. 그런데 기관성과급만 있고 개별성과연봉 자체가 없어요, 임금구조상에. 저는 어차피 같이 연구를 할 텐데 외부수탁과제든 아니면 정책과제든 대부분 비정규직 계약직으로 채용을 해 가지고 같이 연구에 참여시키는 것 아니겠습니까? 그러면 성과가 나더라도 같이 나는 것일 텐데 왜 개별성과연봉에서는 비정규직은 제외하는지 그것도 좀 납득이 안 되고요. 
</p>
<p style="padding-left:1.2em">  이것뿐만이 아니에요. 가장 큰 문제가 연구장려금이라고 하는 제도가 있습니다. 연구장려금은 뭐냐 하면 수탁연구과제를 하게 되면 여기에 참여하는 연구진에 대한 인센티브를 지급할 목적으로 수탁연구과제 예산 총액에서 연구개발비를 뺀 나머지 금액의 35%를 전출금이라는 이름으로 해서 적립을 합니다, 그렇죠?  
</p>
<p><b>○ 경기연구원장 임해규 </b> 네. 
</p>
<p><b>○ 양근서 위원 </b> 이 전출금의 20% 이내에서 조금 전에 말씀드린 연구장려금을 또다시 적립을 해요. 이 연구장려금 가지고 각 수탁연구과제에 참여한 연구진에 대해서 인센티브 형태로 장려금을 지급하는 것이죠. 그런데 연구에 똑같이 정규직 연구원, 비정규직 계약직이 참여를 해서 일을 하는데도 불구하고 지금까지 최근 3년간 연구장려금 지급현황을 쭉 자료로 살펴보니까 정규직 연구원들에게만 다 지급이 됐어요. 한 해에 보통 수억 원씩 연구장려금이 지급됩니다. 그런데 비정규직 연구원들한테는 단 한 푼도, 단 한 차례도 지급이 안 돼 있는 상태예요. 이건 어떻게 보면 내부에 어떤 사정이 있는지 모르겠는데 누가 보더라도 차별구조지 않습니까? 정규직에서 비정규직을 차별하는 구조인거고 또 다시 말씀드리지만 학력차별도 존재하는 거예요. 그러니까 똑같은 비정규직 계약직으로 연구에 참여하더라도 초빙연구원, 박사급이죠. 박사급에 대해서는 또 보니까 비정규직인데도 불구하고 연구장려금을 지급했어요. 똑같이 일을 했는데 초빙연구원이 아닌 그냥 일반연구 보조원이라고 하나요? 석사급 비정규 계약직에 대해서는 한 푼도 연구장려금을 지급 않고 있어요. 이해를 할 수가 없어요. 그러니까 동시에 존재하는 거죠. 비정규직에 대한 차별, 학력에 대한 차별. 도대체 이 경기연구원이라는 집단 자체가 도덕적으로 정말 온전한 집단인지. 어떻게 그러면서 여러 사회 현안문제에 대해서 도덕적으로 이렇게 가야 된다, 저렇게 가야 된다 감히 방향을 제시하고 그럴 수 있는지 이해가 안 돼요. 이게 근거도 없어요. 그냥 그렇게 하고 있는 거예요, 특별히. 그렇지 않습니까? 이를테면 원장님이 이런 문제를 들여다보시고 이건 부당하다, 공정하지 못하다, 이런 차별구조를 시정해야겠다고 생각만 하고 방침만 바꾸면 돼요. 금방 시정될 수 있는 거예요. 그렇잖아요?
</p>
<p><b>○ 경기연구원장 임해규 </b> 그래서 바꿨습니다, 방식을. 
</p>
<p><b>○ 양근서 위원 </b> 언제부터 바꿨어요? 
</p>
<p><b>○ 경기연구원장 임해규 </b> (관계직원을 향하여) 언제부터 시행하기로 했죠?
</p>
<p><b>○ 양근서 위원 </b> 오늘 지금 저한테 보고된 자료…….
</p>
<p><b>○ 경기연구원장 임해규 </b> 방금 말씀드린 이유 때문에 내년 1월 1일부터는 바꾸기로 했습니다. 
</p>
<p><b>○ 양근서 위원 </b> 언제 그런 회의를 통해서 바꾸기로 하신 거예요? 지금 당장 결정하신 겁니까, 아니면 어떻게 하신 겁니까?
</p>
<p><b>○ 경기연구원장 임해규 </b> 벌써 한 두세 달 됐습니다. 저희들이 2016년 7월부터 이 문제를 논의해서요. 바꾸기로 방침을 결정한 거는 지난달에 바꾸기로 방침을 결정하고 내년 1월 1일부터 시행하기로 했습니다. 
</p>
<p><b>○ 양근서 위원 </b> 구체적으로 방침을 결정하게 되기까지의 과정 자료로 제출해 주시고요.
</p>
<p><b>○ 경기연구원장 임해규 </b> 네. 
</p>
<p><b>○ 양근서 위원 </b> 어쨌든 내년 1월 1일부터 이 문제를 시정하기로 한 결정은 잘한 것이라고 생각을 합니다. 왜냐하면 이게 그대로 온존이 되면요. 결국 어떤 거냐면 비정규직, 특히 석사학위를 가진 계약직 연구원들을 약탈하는 거예요. 착취하는 거 아닙니까, 결국은. 똑같이 일해 가지고 그 사람들이 일한 인건비 주지 않잖아요. 별도로 수탁과제에 참여하더라도 그분들 인건비 안 주잖아요, 그렇죠? 그런데 그 인건비 중의 일부를 전출금이라고 하는 형태로 적립을 하고 또 연구장려금으로 별도로 만들어요. 그걸 가지고 정작 같이 공동연구에 참여했던 연구원들, 비정규직들한테 주지 않고 그걸 다 지금 박사급 정규직들이 독식하고 있는 거 아닙니까? 그게 바로 차별을 떠나서, 완전히 차별을 넘어서 약탈하는 구조죠, 착취하는 구조. 어쨌든 그것을 내년 1월 1일부터 당장 시정하겠다고 한 것은 잘한 결정이고 꼭 그렇게 해 주시기 바랍니다.
</p>
<p style="padding-left:1.2em">  다음 또 질의 이어가겠습니다. 그렇게 해도 됩니까? 
</p>
<p><b>○ 위원장 이재준 </b> 네. 
</p>
<p><b>○ 양근서 위원 </b> 다음에 또 이걸 한번 짚어보겠습니다. 정규직 연구원들이 대외활동을 해요. 각종 강연, 발표, 자문, 출강, 토론 등 이렇게 대외활동을 하는데 대외활동 범위가 굉장히 큽니다. 실제로 보니까 1인당 평균, 정규직 연구원 1인당 이런 대외활동을 통해 가지고 433만 원 정도 평균적으로 부수입으로 가져가고 있어요. 이것은 아까 말씀드린 전출금 형태로 경기연구원 일반회계에 귀속되지 않습니다. 그냥 다 자기 수입으로 가져가는 거예요. 가장 많은 대외활동수입을 올리신 분이 누군가 봤더니 이것도 마찬가지로 정규직 연구원인데 3년 동안 3,724만 원을 벌었어요. 한 해 평균 따지면 1,000만 원 정도 대외활동수입을 가져간 겁니다. 그럼 주로 어떤 곳에서 대외활동이 이루어지냐를 봤더니 대외활동대상의 60% 정도가 대부분 중앙정부 및 지방자치단체에 대한 회의참석이나 자문활동들이에요. 나머지는 일반 민간기관도 있을 수 있고 대학 같은 데 출강하는 것도 있게 되는데 어쨌든 대부분의 대외활동이 경기도 그다음에 31개 시군 또는 각 중앙정부에서 회의에 참석해 달라고 하거나 무슨 자문의견 달라고 할 때 참석해서 수당을 받는 방식이거든요. 그런데 저는 이것이, 그러면서 지금 또 돈은 수당 형태로 다 가져가고 있어요. 아까 말씀하신 것처럼 상한선은 있겠죠. 회당 20만 원이라든지 있을 수는 있는데 경기연구원이 경기도가 100% 출연한 지방정부 출연기관 아닙니까? 
</p>
<p><b>○ 경기연구원장 임해규 </b> 네.
</p>
<p><b>○ 양근서 위원 </b> 사실상 공기관이에요, 공기관. 경기도를 위해서 만들어진 거고 31개 시군을 위해서 만들어진 거란 말이에요. 그러면 인건비도 별도로 주잖아요, 그렇죠? 경기도 예산을 가지고 인건비를 별도로 다 주고 있어요, 정규직 연구원들에 대해서. 그런데 경기도하고 31개 시군에 대한 자문활동은 저는 그런 측면에서 보면 너무나도 당연한 고유업무일 것 같아. 고유한 일이에요. 그러라고 돈을 준 거예요. 돈을 주는 이유는 연구해 가지고 연구과제 발표하는 것도 당연히 있겠지만 거기에는 각종, 페이퍼로만 합니까, 연구활동이라는 것이? 자문활동할 수 있고 회의활동할 수 있는 거잖아요. 너무나 당연히 해야 되는 고유한 업무영역이라고 생각하는데 그 일을 하면서 또 별도로 수당을 받아가요, 그렇죠? 그 돈이 상당합니다. 저는 이것도 도덕적으로 봤을 때 온당한 것인지 한번 묻고 싶어요. 예를 들면 경기도의원들도, 경기도 소속의 행정직 공무원들도 다 마찬가지로 이런 방금 제가 말씀드린 차원에서 공직자기 때문에 이미 별도의 수당이랄지 급여를 받고 있기 때문에 같은 동종의 공공파트 내에서 자문활동한다랄지 회의한다랄지 이런 것에 대해서는 당연한 업무의 연장선상이라고 보기 때문에 별도의 수당을 지급하지 않는 거예요. 그런데 왜 경기연구원은 그렇게 하고 있습니까? 답변을 해 보십시오. 
</p>
<p><b>○ 경기연구원장 임해규 </b> 사실 그것도 여러 가지 고민되는 것 중의 한 가지입니다. 그런데 예를 들어서 외부에 나가서 특별강연을 한다거나 이러면 강연에 따르는 원고작성도 하고 여러 가지 노력을 기울이고 이러기 때문에 그것은 그것대로 또 논의할 수 있습니다마는 특히 경기도나 산하 시군의 회의에 참석해서 회의수당 받는 문제는 저희들도 아마 받는 것이 옳으냐, 그렇지 않는 것이 옳으냐 이런 논의가 계속 있었던 것 같습니다, 그 점에 관해서는. 그런데 또 한편으로 보면 저희들이 그렇게 가서 회의수당을 받는 경우에는 저희들이 출장비는 전혀 주지 않습니다, 또. 그렇지 않은 경우는 출장 나가면 출장비도 줘야 되거든요. 그래서 그거는 오랫동안 이렇게 돼 오면서 관행으로 있는 것 같습니다. 그런데 위원님께서 만약에 우리 공직자 전체가 어떤 회의에 참여해서 수당 받는 것을 다 안 받는 것이 옳다고 한다면 그런 방향에서 검토를 해 볼 수 있는 일이라고 생각합니다. 
</p>
<p><b>○ 양근서 위원 </b> 저는 그 부분도 아마 공직자 또는 국책, 지방정부 출연연구기관의 대외활동과 관련된 행동강령이랄지 관련된 수당을 받을지 말지 여부에 대한 나름대로의 지침이 구체적으로 있거나 구체적으로 없다 할지라도 그것을 준거로 활용할 수 있는 여러 가지 자료들이 있을 겁니다. 또 그렇게 운영하고 있는 기관들이 많이 있기 때문에 그런 데 대해서 보다 좀 조사를 하셔서 거기에 대해서 시정할 수 있는 방향으로 대안을 저는 만들어야 된다고 생각을 합니다. 그렇게 하시겠습니까? 
</p>
<p><b>○ 경기연구원장 임해규 </b> 네, 저희들이 방금 말씀하신 검토는 사실 다 해서 액수나 이런 것도 적정하게 가지고 있는 거거든요. 그런데 지금 위원님 말씀은 전면적으로 우리 도나 또는 공공기관에 가서 자문활동을 하는 것은 자문료를 일체 받지 않는 것이 좋겠다고 하는 제안을 주신 것으로 저는 이해가 되기 때문에 그 점은 다른 기관에서의 사례나 또는 전체적으로 준거가 어떤가를 보고 저희들도 맞춰서 하겠다는 말씀드립니다. 
</p>
<p><b>○ 양근서 위원 </b> 마지막으로 한 가지만 더 질의하고 끝내겠습니다. 저는 경기연구원의 가장 큰 핵심적인 기능 중의 하나가 결국은 정책연구과제를 잘 만들어내서 이것이 결국 정책에 반영되도록 하게끔 하는 일이라고 생각합니다. 그래서 연간 수십억 원의 출연금을 받아가면서 운영을 하고 있는 거죠. 연구원의 연구업무를 크게 분석을 해 봤더니 과제가 있어요. 과제는 정책연구과제 그다음에 기본연구, 수탁과제 이렇게 크게 세 가지로 구분되고. 그다음에 현안분석이라고 해서 우리가 보통 받아보는 이슈&진단이라고 하는 페이퍼 있죠? 그다음에 현안대응, 현안브리프 이렇게 유형별로 분류를 할 수 있을 것 같습니다. 
</p>
<p style="padding-left:1.2em">  이 가운데 제가 관심 있는 것은 정책연구예요. 아무래도 아까 말씀드린 것처럼 가장 핵심적인 기능이 정책연구를 수행하는 거고. 그런데 정책연구는 대부분 전체 100이다 그러면 60% 이상이 경기도 출연기관의 의뢰에 의해서 보통 과제들이 설정되고 나머지 40% 정도는 자체적으로 발굴해서 연구작업이 진행되고 있습니다. 우선 여기서 한 가지 궁금한 것은 경기도의회에서 의뢰한 정책연구과제들이 별로 안 보여요, 일단. 숫자가 거의 없어. 이것이 경기도의회에서 정책연구에 대해서 관심이 없어서 의뢰를 안 해서 그런 것인지. 실제 그런 건가요? 아니면 만약에 그렇다면 우리도 정책연구과제를 많이 의뢰를 해야 될 것 같은데 그런 건가요? 왜 별로 없는 거죠, 경기도의회에서 하는 것은?  
</p>
<p><b>○ 경기연구원장 임해규 </b> 제가 와서 판단하기에는 일단 도의회 의원님들과의 그간의 교류는 소위 의정연구센터라고 하는 것을 통해서 교류가 이루어져 왔습니다. 그런데 그것이 폐지가 된 거죠. 그때 이루어졌던 것은 지금 말씀하신 3개월 이상의 연구시간이 걸리는 정책연구라기보다는 주로 도정질의서라거나 그런 것들이었습니다, 보니까. 그런데 그게 폐지가 되면서부터는 저희들이 어떻게 바꿨냐면 위원회 단위로 정책연구를 의뢰해 줬으면 좋겠다. 그래서 저희들이 의정 콜로키움을 상임위원회별로 전반기, 후반기 이렇게 두 번 하겠다는 계획을 가지고 계속 접촉을 했습니다. 그런데 사실 말하면 의원님들이 그 필요성이나 이런 거에 대해서 저희들에게 요구하는 게 아니었습니다. 우리가 분석을 해 보니까 저희도 도의회에서 의뢰하는 건수를 늘려야 되겠다하는 자체의 계획이 있었기 때문에 저희들이 1년에 우선 10건 정도는 하자. 그래서 올해 지금 한 게 저희들이 6건 했습니다. 총 8건을 했는데 10건 정도 하자, 우선. 그리고 그다음에 좀 늘려서 20건 정도는 도의회에서 의뢰하는 것을 하면 좋지 않겠느냐 하는 게 자체계획입니다, 저희들. 그래서 그렇게 하기 위한 상호 간의 협약이 필요해서 저희들이 의장님께도 의사를 전달했고 신임 의장님께도 의사전달을 했습니다. 그래서 도의회하고 우리하고 MOU 체결하는 게 어떨지 모르겠는데 그렇게라도 해서 좀 도의회 차원에서 우리를 그런 식으로 상임위원회별로 1년에 두 번쯤은 과제발굴하기 위한 것을 열어서 하면 좋겠다는 계획을 가지고 있고 지금 그렇게 추진하고 있습니다. 
</p>
<p><b>○ 양근서 위원 </b> 알겠습니다. 결국은 경기도의회의 정책연구과제 의뢰 자체가 조금 낮게 나타나기 때문에 그럴 수밖에 없는 형편인 것 같은데 그런 부분은 의회 차원에서도 좀 분발을 할 필요성은 있는 것 같습니다. 
</p>
<p style="padding-left:1.2em">  마지막으로 정책연구결과가 그러면 어떻게 정책에 반영이 되고 이걸 한번 살펴봤어요. 그랬더니 이미 책자로 만들어서 GRI 연구결과 정책반영사례집 이렇게 해서 제출해 주셨는데요. 보니까 성과분석자료를 보면 법령 제ㆍ개정 및 제도개선으로 활용된 정책연구과제가 2014년도에 전체 114건 중에 19건. 그러니까 비율로 보면 17% 정도됩니다. 그다음에 2015년도에는 전체 154건의 정책과제 중에서 24건, 역시 비율로 보면 15.5%. 대략 15% 내외 정도 이렇게 실질적인 법령이나 또는 조례의 제ㆍ개정을 통해서 정책에 반영되고 있는 것 같아요. 그럼 나머지 정책연구과제들은 어떻게 반영이 되고 있느냐. 중앙정부 정책수정 또는 정책기조 변화, 현안해결 지원, 수범사례 구축 이렇게 유형별로 분류가 돼서 성과관리가 되고 있어요.
</p>
<p style="padding-left:1.2em">  그런데 전체적으로 보면 어떻게 평가할 수밖에 없냐면 정책연구과제의 실질적인 정책반영비율이 대단히 낮다. 여기서 제가 실질적이라고 말씀드리는 것은 아까 말씀드렸던 법령 제ㆍ개정이랄지 제도개선, 조례를 포함해서 이걸 말씀드리는 거예요. 그런데 이게 15% 안팎밖에 안 되는 걸로 나타났고 나머지는 사실 일종의 정성적인 성과분석이에요. 그러니까 이것이 중앙정부 정책수정에 반영됐는지 안 됐는지는 구체적으로 정량적으로 평가 자체가 불가능하기 때문에 그냥 반영됐다라고 하면 그런가 보다 하는 것이지 이걸 기다 할 수도 없고 안 했다 할 수도 없는 거란 말이에요.
</p>
<p style="padding-left:1.2em">  그러니까 실제 중앙정부의 정책이나 지방자치단체의 수많은 수백 가지 정책이 변화무쌍하게 변화를 많이 합니다. 그렇죠? 그런데 과연 이 경기연구원에 수천만 원 또는 전체적으로 수억, 수십억 원의 정책연구과제비를 들여서 나오는 결과보고서를 통해서 그것이 변화가 된 것인지에 대해서는 불분명하다는 얘기예요. 아니면 언론보도랄지 그 외에 수많은 다른 단기연구과제들, 다른 기관에서 수행하고 민간 연구소에서 수행하는 각종 결과들을 통해서 반영이 되고 있는지는 구분하기가 힘들다는 것이죠.
</p>
<p style="padding-left:1.2em">  그래서 결론적으로 말씀드리면 저는 경기연구원의 핵심기능이 여러 가지 현안대응도 하고 이슈＆진단도 하고 정책연구들 많이 하고 계시는데 가장 핵심적인 것은 결국 정책연구과제다. 그래서 지금 정규직 연구원들에 대해서 의무적으로 1년에 정책연구과제는 1건 이상이죠, 사실상?
</p>
<p><b>○ 경기연구원장 임해규 </b> 그렇습니다.
</p>
<p><b>○ 양근서 위원 </b> 기본연구과제 포함해서 1년에 2건이니까. 기본연구라고 하는 것은 사실은 이런 정책연구는 아니고 개인 전문분야의 일종의 학술역량을 제고시키기 위해서 학계에 논문을 제출한다든지 그런 걸 주로 하는 거고, 그렇잖아요? 
</p>
<p><b>○ 경기연구원장 임해규 </b> 그렇습니다.
</p>
<p><b>○ 양근서 위원 </b> 그래서 그건 정책연구과제하고 상관이 없는 거니까. 가장 핵심적인 게 정책연구과제인데 아까 말씀드린 것처럼 실질적인 정책 제도개선 또는 법령 제ㆍ개정…….
</p>
<p><b>○ 경기연구원장 임해규 </b> 2건입니다, 1건은 아니고. 저희들이 100점을 해야 되기 때문에요. 기본정책을 100점을 해야 되기 때문에요. 한 연구과제를 책임을 하면 50점쯤 되기 때문에 한 2건 정도를 해야 됩니다.
</p>
<p><b>○ 양근서 위원 </b> 네, 2건.
</p>
<p><b>○ 경기연구원장 임해규 </b> 최소한 2건은 해야만 합니다, 의무적으로.
</p>
<p><b>○ 양근서 위원 </b> 어쨌든 그렇게 의무적으로 규정할 만큼 중요한 핵심과제인데도 불구하고 실질적으로 정책에 반영되는 활용도는 좀 낮은 것으로 평가할 수밖에 없다는 생각이 들거든요. 그래서 그것을 높이기 위한 방안을 굉장히 저는 핵심적으로 고민해야 될 것 같아요. 여러 가지 시스템이 있을 수 있죠. 아까 원장님 말씀하신 것처럼 사실 지방정부단위에서는 지방의회에서 입법권을 가지고 있기 때문에 조례 제ㆍ개정을 통해서 제도개선을 하려면, 새로운 제도를 만들려면 결국 의회하고의 정책 친밀감, 정책적 소통 이것이 굉장히 시스템화되고 활발하게 진행이 돼야 될 거라고 생각을 합니다. 물론 여러 방안을 만들어서 의회하고 그런 노력을 하려고 하지만 의회가 정책문제에 대해서 관심이 없고 등한시해서 한다라고 하는 말씀으로 이해가 되지만 의회의 속성상 정치집단 아닙니까, 말하자면? 정치집단으로 이루어진 의회의 속성상 그런 한계는 분명히 있어요. 그럼에도 불구하고 저는 그런 노력을 게을리하지 말고 기존의 방법이 현실에서 제대로 작동하지 않는다면 또 새로운 대안을 만들어서 시스템화하려고 노력하는 거 저는 이게 굉장히 필요하다고 생각합니다. 저는 그것이 굉장히 부족하다고 생각해요. 자꾸 원장님은 그걸 많이 제안했는데도 불구하고 의회에서 소극적이다라고 표현하시지만 저는 그렇지는 않아요.
</p>
<p><b>○ 경기연구원장 임해규 </b> 저 그렇게 얘기하지 않았습니다. 그건 곡해입니다.
</p>
<p><b>○ 양근서 위원 </b> 그러면 실제로 의회의 전체 288명의 의원님들 중에서 정책연구를 통한 일종의 입법활동에 대한 욕구, 수요가 있는 분들이 굉장히, 숨어 있는 분들이 많단 말이에요. 그런 분들하고 어쨌든 소통할 수 있는 시스템들을 만들어서 이 문제를 해결해야 된다. 그렇지 않으면 나중에 “경기연구원 돈값 못한다.” 이 얘기 제가 보기에는 당연히 나올 것 같아요. 그런 얘기가 나오기 전에 선제적으로 대응을 해서 그런 문제들을 해결할 수 있도록 당부를 드립니다.
</p>
<p><b>○ 경기연구원장 임해규 </b> 네, 그렇게 하겠습니다. 어쨌든 저희들 연구가 질도 높아야 되지만 또 쓰임새가 있어야 되기 때문에요. 저희들이 그 쓰임새를 높이기 위한 다양한 노력을 하고 있습니다만 부족한 것도 많습니다, 아직도. 저희들이 아직 부족한 것도 많고 그리고 반영도가 어떠냐도, 저희들이 계속 이렇게 하는 이유도 반영도를 높여야 되겠다고 보고 또 한편으로는 어떤 고민도 있냐면 사실 행정부의 일선 부서에서 “이걸 해 주세요.” 하고 의뢰하는 건 그건 100% 반영되는 거거든요. 반영도가 그냥 단순히 높은 것만도 꼭 좋은 것이 아닙니다. 그러면 우리는 종속적이 되니까요. 선도적인 정책은 못하기 때문에. 그래서 선도적인 정책과 종합적인 연구와 미래지향적 연구를 하면서도 반영도를 높이게 하기 위해서 어떻게 해야 되는가 하는 것이 저희들 고민이고 또 그런 고민의 한 지점에 의회 의원님들이 그냥 개인의 의원이 아니라고 저희들이 보고 있기 때문에 그게 경기도정의 많은 것을 현장성을 담고 있고 또 미래지향성을 담고 있기 때문에, 그래서 의원님들과 저희들도 접촉면을 높이려고 하는 거거든요. 그것도 다 연구의 질을 높이고자 하는 저희들의 바람과 또 저희들의 어떤 계획 때문에 그런 겁니다. 그래서 위원님 말씀하신 대로 저희들이 다양하게 연구의 질과 또 적합도를 높이기 위한 노력을 더 기울이도록 그렇게 하겠습니다.
</p>
<p><b>○ 양근서 위원 </b> 좋습니다. 실제로 올 초에 경기연구원에서 기획재정위원회 위원님들 대상으로 정책연구과제 수요조사를 한 적이 있어요. 그때 저는 평상시에 제 고민거리였던 경기도의회 재정구조 개혁방안 이런 내용으로 해서 의뢰를 했는데 그 뒤에 이게 채택이 됐는지 어쨌는지 지금 소식이 없어요.
</p>
<p><b>○ 위원장 이재준 </b> 정리하시죠.
</p>
<p><b>○ 양근서 위원 </b> 나중에 답변을 좀 해 주시고요. 마지막 딱 하나만 확인을 하는데요. 아까 말씀하신 것처럼 연구원당 기본연구과제하고 정책연구과제 연구책임이 연간 2건 딱 할당이 되어 있어요, 의무적으로. 그런데 자료를 추가적으로 받아보니까 2014년도, 2015년도 또 올해 한 건씩밖에 연구과제를 수행하지 않은 분들이 여전히 계세요. 2014년도에는 한 건밖에 안 한 분이 열세 분, 2015년도에 열두 분, 올해는 8월 말 현재 아홉 분이 한 건밖에 안 하고 있어요. 물론 이제 어떻게 될지 모르겠는데. 만약에 이렇게 의무량을 책임연구하지 않으신 분들에 대해서는 어떤 징계가 있나요?
</p>
<p><b>○ 경기연구원장 임해규 </b> 그 자료가 아마 파견 혹은 연구년 혹은 이러저러한 사유가 있는 분들일 거라고 저는 생각이 들고요. 왜냐하면 제 기억으로는 저희들이 매년 평가를 하니까요. 그렇게 책임연구과제를 수행 못한 박사는 한 분도 없었거든요. 그러니까 그건 아마도 특별한 사정이 있는 분들의 통계가 아닌가 싶고 그리고 사실 제가 알기로는 올해도 본인의 책임량, 연구책임량이 있어서, 저희들 연구책임량 관리가 굉장히 엄격합니다. 그런데 거기에 의해서 한 분도 탈락되는 분이 없으리라고 지금 보고받고 있기 때문에 그런 걱정은 하지 않습니다. 그리고 위원님 제안하신 것은 저희들 내년도 연구과제에 채택됐습니다.
</p>
<p><b>○ 양근서 위원 </b> 됐습니까? 고맙습니다. 이상입니다.
</p>
<p><b>○ 위원장 이재준 </b> 양근서 위원님 수고하셨습니다. 다음 나득수 위원님.
</p>
<p><b>○ 나득수 위원 </b> 나득수 위원입니다. 원장님, 우리가 기금을 사용하실 때 기금사용계획서를 이사회에 안건으로 제출해서 승인을 받고 바로 사용하시는 건가요?
</p>
<p><b>○ 경기연구원장 임해규 </b> 네, 그렇습니다.
</p>
<p><b>○ 나득수 위원 </b> 그러면 어떤 별도의 기금 예산서를 작성한다든가 그런 건 없고요?
</p>
<p><b>○ 경기연구원장 임해규 </b> 별도의? 
</p>
<p><b>○ 나득수 위원 </b> 기금 예산서를 작성한다든가……. 
</p>
<p><b>○ 경기연구원장 임해규 </b> 그러니까 저희들이 기금사용계획안을, 기금사용계획안이 대체로 뭐냐 하면 저희들이 기금이 새로 들어온 건 없으니까요. 지금은 있는 기금 까먹는 상황이니까. 그래서 내년도에 기금 중에 얼마를 일반예산으로 돌려서 사용을 하겠다고 하는 것의 계획안이죠. 그 계획안을 이사회에 상정해서 허락을 받고 사용합니다.
</p>
<p><b>○ 나득수 위원 </b> 원장님께서 지금 2014년도에 부임하셨죠?
</p>
<p><b>○ 경기연구원장 임해규 </b> 네.
</p>
<p><b>○ 나득수 위원 </b> 부임하신 것부터 지금 2016년까지 한 76억의 기금을 사용하시는 것 같아요?
</p>
<p><b>○ 경기연구원장 임해규 </b> 그렇습니다. 
</p>
<p><b>○ 나득수 위원 </b> 그래서 현재 지금 2014년 잔액이 242억이었는데 2016년에는 121억의 잔액이 남는 거죠? 이건 좀 타당하다고 생각하십니까?
</p>
<p><b>○ 경기연구원장 임해규 </b> 저희들 경영하는 입장에서는 굉장히 부담입니다. 왜냐하면 물론 기금이 예전에는 이자율이 상당히 높았기 때문에 그 기금의 이자율로도 저희들 운용하는 데 상당한 충당이 됐습니다. 그런데 이자율이 워낙 낮아서 지금은 별로 저희들 살림살이에 도움이 안 되기 때문에 도의 방침이 가급적이면 지금 이율이 낮으니까 그 기금을 그냥 사용하는 게 좋겠다. 왜냐하면 도 입장에서는 전체적으로 부채도 많은데 이자도 얼마 안 되는 돈을 쓰냐 이런 것 때문에 지금 하고는 있습니다만 저희들 방침은 애초 저희들 조성액이 100억입니다. 그래서 100억은 절대 사용하지 않겠다. 그리고 100억을 쓰려면 이사회 동의도 얻어야 되고 도지사의 승인도 받아야 됩니다. 그래서 저희들이 내부방침은 이사님들도 확고합니다, 그 의지가. 100억 이상은, 100억은 더 이상 쓰지 않는다. 그래서 방침을 그렇게 잡고 있습니다.
</p>
<p><b>○ 나득수 위원 </b> 다음 질의드리겠어요. 우리가 지금 2014년도에 출연금과 기금사용액이 우리 경기도 출연금이 104억, 그렇죠? 그리고 기금사용액이 31억. 그래서 135억을 사용하셨어요.
</p>
<p><b>○ 경기연구원장 임해규 </b> 네.
</p>
<p><b>○ 나득수 위원 </b> 그리고 15년도는 147억 그다음에 16년도는 137억, 그렇죠? 그렇다면 이게 15년도는 활발한 연구활동 때문에 이렇게 예산을 편성하신 건가요? 15년하고 14년, 16년하고 지금 한 10억 정도 편차가 있어요. 그 편차를 어떻게 설명하실 거냐.
</p>
<p><b>○ 경기연구원장 임해규 </b> 총액을 말씀하시는 건가요?
</p>
<p><b>○ 나득수 위원 </b> 네. 그러니까 출연금하고 기금하고 사용액이, 합한 금액이.
</p>
<p><b>○ 경기연구원장 임해규 </b> 저희들이 기금을 100억으로 묶으려고 그랬기 때문에 기금액을 점차적으로 30억에서 20억으로, 20억에서 15억으로, 15억에서 10억으로 이렇게 점차로 줄여서 사용하고 내후년부터는 기금은 절대 사용하지 않는다는 방침이기 때문에 기금을 일반회계로 전입하는 액수가 1년에 한 7~8억씩 이렇게 줄어온 것입니다. 
</p>
<p><b>○ 나득수 위원 </b> 그렇다면 2015년도에는 연구활동이 활발했냐 이거죠. 그렇지 않았나요?
</p>
<p><b>○ 경기연구원장 임해규 </b> 저희들이 북부연구센터를 개소해서 그만큼 비용이 늘었습니다.
</p>
<p><b>○ 나득수 위원 </b> 한 10억 정도가?
</p>
<p><b>○ 경기연구원장 임해규 </b> 네.
</p>
<p><b>○ 나득수 위원 </b> 그렇습니까? 그리고 예산서를 보면 정기이월금이 있어요. 2015년도에는 한 20억 정도, 2016도에는 정기이월금이 29억 있단 말입니다. 그렇다면 2016년도 정기이월금이라는 것은 2015년도에 사용하다가 남은 금액 아닙니까?
</p>
<p><b>○ 경기연구원장 임해규 </b> 그렇습니다.
</p>
<p><b>○ 나득수 위원 </b> 그런데 이 정기이월금을 계속적으로 남겨가는 패턴은 왜 이렇게 남겨가시는 건가요?
</p>
<p><b>○ 경기연구원장 임해규 </b> 불용액을 적정선으로 유지하는 건 굉장히 중요하다고 저희들도 생각하고 있습니다. 불용액이 많으면 안 되는데 사실 2015년도에 돈이 남았던 사유 중의 가장 큰 것은 저희들이 추경예산을 받았는데 추경예산을 그해에는 못 쓰고 이월시켰습니다. 그때 9억을 저희들이 받았거든요. 그런데 당해연도에는 쓰지 못하고 그다음 해 2월에 썼습니다. 
</p>
<p><b>○ 나득수 위원 </b> 그렇다면 불용액이 보통 10%, 15% 된다는 것은 우리가 사업을 적정하게 하지 못한다는 거 아닌가요?
</p>
<p><b>○ 경기연구원장 임해규 </b> 그래서 그게 갑자기 많아진 것의 사유는 그렇다고 말씀드릴 수 있습니다.
</p>
<p><b>○ 나득수 위원 </b> 그거 좀 각별히 유의해 주시기 바랍니다. 그다음에 수탁용역사업 있죠?
</p>
<p><b>○ 경기연구원장 임해규 </b> 네.
</p>
<p><b>○ 나득수 위원 </b> 수탁용역사업이 우리가 항상 50억으로 책정을 하는데 그게 우리 연구원 캐파에 적당한 수치입니까? 아니면 60억이나 70억 이렇게 늘릴 수는 없는 건가요?
</p>
<p><b>○ 경기연구원장 임해규 </b> 그 이상 늘리기가 사실 쉽지가 않은 것 같습니다.
</p>
<p><b>○ 나득수 위원 </b> 쉽지가 않다?
</p>
<p><b>○ 경기연구원장 임해규 </b> 물론 우리는 더 늘려서 더 열심히 수탁과제를 받아오자 이런 생각이 있습니다만 잘 아시다시피 출자ㆍ출연법이, 출ㆍ출법이 바뀌어서 아마 거기 보시면 경기도의 위탁사업 공모에 저희들이 들어가 가지고 낙찰 안 된 비율이 점점점점, 낙찰 안 된 비율이 높아지는 걸 아마 보실 수 있을 겁니다. 그건 뭐냐 하면 이제는 수의계약이 점점 줄어들고 있기 때문에요, 사실 따기도 쉽지가 않고. 그래서 저희들이 한 50억 정도를 계속 잘 유지하면 좋겠다고 하는 생각을 많이 가지고 있습니다.
</p>
<p><b>○ 나득수 위원 </b> 지금 10월 말인가요? 그러면 지금 현재까지 어느 정도예요, 수탁용역사업?
</p>
<p><b>○ 경기연구원장 임해규 </b> 지금 한 벌써 40억, 41억 정도는 됩니다.
</p>
<p><b>○ 나득수 위원 </b> 41억 정도요? 그러면 아직도 한 9억이 남았네요, 실적이?
</p>
<p><b>○ 경기연구원장 임해규 </b> 그렇습니다.
</p>
<p><b>○ 나득수 위원 </b> 그리고 비정규직 석사 연구원들이, 석사 비정규직들이 수탁용역사업에 투입이 되잖아요. 그러면 일반회계 수입금액의 인건비에는 잡히지 않는 건가요?
</p>
<p><b>○ 경기연구원장 임해규 </b> 잡힙니다.
</p>
<p><b>○ 나득수 위원 </b> 그쪽도 잡히고 이 수탁사업도 잡히고?
</p>
<p><b>○ 경기연구원장 임해규 </b> 아닙니다. 수탁사업을 하느라고 별도로 고용된 경우는 수탁사업비로 잡히지만 그냥 항상적으로, 일반적으로 고용되어 있는 경우에는 저희들 일반회계상의 아웃소싱으로 그 인건비가 잡혀 있습니다.
</p>
<p><b>○ 나득수 위원 </b> 정규직 같은 경우는 수탁용역사업이면 이쪽의 지출에 잡히는 거잖아요? 그러니까 일반회계의 인건비에 잡히고…….
</p>
<p><b>○ 경기연구원장 임해규 </b> 그렇습니다.
</p>
<p><b>○ 나득수 위원 </b> 그다음에 수탁용역사업의 사업비로 잡히는 거잖아요. 그렇죠? 그에 대한 수당은. 그렇지 않아요?
</p>
<p><b>○ 경기연구원장 임해규 </b> 수당이 안 잡힙니다.
</p>
<p><b>○ 나득수 위원 </b> 안 잡혀요?
</p>
<p><b>○ 경기연구원장 임해규 </b> 정규직 박사는 수탁과제를 한다고 해서 어떠한 인건비도 받지 않습니다.
</p>
<p><b>○ 나득수 위원 </b> 아, 그러면 일반회계 인건비로 책정이 됩니까?
</p>
<p><b>○ 경기연구원장 임해규 </b> 그렇습니다. 석사연구원도 마찬가지입니다.
</p>
<p><b>○ 나득수 위원 </b> 석사연구원도요?
</p>
<p><b>○ 경기연구원장 임해규 </b> 그렇습니다. 그 수탁사업을 위해서 별도로 고용된 사람만  수탁사업비로 주는 겁니다.
</p>
<p><b>○ 나득수 위원 </b> 알겠습니다. 정기이월금, 이월분도 좀 고려를 많이 해 주시고요. 그다음에 기금을 많이 사용하지 마시고 출연금을 좀 늘려 달라 이렇게 요구를 하세요, 출연금을.
</p>
<p><b>○ 경기연구원장 임해규 </b> 위원님들이 삭감을 안 하시면 저희도 충분히…….
</p>
<p><b>○ 나득수 위원 </b> 아니, 그러니까 저희들도 경기연구원 사업에 대해서 그렇게 다 좋은 용역사업을 하고 있는데 그렇지 않잖아요. 그러니까 앞으로…….
</p>
<p><b>○ 경기연구원장 임해규 </b> 위원님 많이 도와주시면 고맙겠습니다.
</p>
<p><b>○ 나득수 위원 </b> 알겠습니다. 이상입니다.
</p>
<p><b>○ 위원장 이재준 </b> 나득수 위원님 수고하셨습니다. 지금 3시간 동안 계속 회의를 진행했습니다. 그래서 10분간 휴식을 위해서 정회를 하고자 하는데 이의 없으십니까?
</p>
<p style="padding-left:2.4em">    (「없습니다.」하는 위원 있음)
</p>
<p style="padding-left:1.2em">  10분간 정회를 선포합니다.
</p>
<p class=''ar''>(16시58분 감사중지)
</p>
<p class=''ar''>(17시18분 감사계속)
</p>
<p><b>○ 위원장 이재준 </b> 의석을 정돈해 주시기 바랍니다. 감사를 속개하겠습니다.
</p>
<p style="padding-left:1.2em">  추가질의하실 위원님, 이현호 위원님 질의해 주시기 바랍니다.
</p>
<p><b>○ 이현호 위원 </b> 이현호 위원입니다. 우리 경기연구원에 근무하시는 분들 보수문제에 대해서 제가 한번 말씀을 드리겠습니다. 나쁜 건 아니고 제가 궁금하고 자료 받아본 게 있어 가지고 말씀을 드리겠습니다. 본 위원이 파악하기에는 경기연구원은 2013년부터 임금이 동결됐죠, 동결? 알고 계세요?
</p>
<p><b>○ 경기연구원장 임해규 </b> 네, 그렇습니다. 동결됐습니다.
</p>
<p><b>○ 이현호 위원 </b> 왜 동결됐을까요? 거기에 대해서 어떻게 생각하십니까, 동결된 것에 대해서?
</p>
<p><b>○ 경기연구원장 임해규 </b> 일단 우리 연구원들 사기가 좀 많이 떨어져 있는 상태입니다.
</p>
<p><b>○ 이현호 위원 </b> 그래서 원장님이 거기에 대해서 생각이 어떠시냐고요? 사기 떨어진 것은 사실이지만 원장님 생각이 어떠시냐 이거죠. 원장님이 무책임한 거 아니신가?
</p>
<p><b>○ 경기연구원장 임해규 </b> 저희들이 계속 적절한 임금인상에 대한 요구를 도 집행부에다가 하지만 사실 최근에 도 재정상의 여러 가지 어려움이나 이런 것 때문에 반영이 되고 있지 못해서 저로서도 큰 부담과 책임감을 느낍니다.
</p>
<p><b>○ 이현호 위원 </b> 13년도, 14년도, 15년도 이렇게 보니까 임금이 전혀 움직이지 않고 동결됐다는 말씀을 드리고요. 타 연구기관들도 이렇게 경력가급 유사제도가 있는지 또 임금인상이 우리와 똑같이 되고 있는지. 제가 타 시도 서울시 걸 한번 봤거든요. 서울시는 안 그렇더라고요. 경기연구원하고 다르거든. 이런 것을 아마 우리 연구원에 근무하시는 분들 연구직이든지 또 관리ㆍ정보ㆍ기능직 또 연구원의 행정직들이 볼 때에 아까 원장님 말씀하신 대로 여기 근무하시는 직원들의 사기가 저하되는 건 사실이지 않습니까?
</p>
<p><b>○ 경기연구원장 임해규 </b> 네.
</p>
<p><b>○ 이현호 위원 </b> 이걸 한번 원장님께서, 이제 얼마 안 남으셨죠? 죄송하지만 임기가 얼마 안 남았지 않았습니까?
</p>
<p><b>○ 경기연구원장 임해규 </b> 네, 한 10개 월 남았습니다.
</p>
<p><b>○ 이현호 위원 </b> 그래서 혁신적인 각오를 가지시고. 서울시하고 차이가 많이 나요, 우리가 보니까. 같은 20년 근무한 경력 가지고 연 한 840만 원 나더라고요, 연구직의 경우. 그리고 또 관리ㆍ정보ㆍ기능직의 경우도 우리하고 서울시하고 차이가 많이 나고 연구, 일반행정도 마찬가지거든요. 그래서 우리 원장님께서 임기 내에 연구직원들과 근무하는 직원들을 위해서 보수만큼은 원장님이 한번, 더는 제가 말씀 안 드리겠지만 어떻게 보수규정을 개선할 의지가 있으신지 한번 제가 여쭤보겠습니다. 
</p>
<p><b>○ 경기연구원장 임해규 </b> 저는 말하자면 다른 연구기관과의 차이도, 특히 서울연구원하고 저희들이 경쟁하는 관계에 있다고 봐야 됩니다. 그런데 점점 차이가 벌어지고 있어서 사실 두뇌유출이 잘못하면 발생할 수도 있습니다. 서울연구원으로 빠져나갈 수도 있고 다른 연구원으로 빠져 나갈 수 있고 그래서 그것도 상당히 걱정이 되고. 왜냐하면 우리 연구기관의 특성상 경기도에 굉장히 정통하기 때문에, 여기서 오랫동안 근무하면. 그래서 연구경력이 굉장히 중요합니다. 그래서 계속 여기서 근무를 잘할 수 있도록 경영진에서 노력을 해야 되기 때문에 그런 차원에서도 저희가 적정한, 그러니까 동종 유사업종에 비교해 봤을 때 적정하게 유지가 돼야 된다고 봅니다. 그런 차원에서 더 노력해야 된다고 보고 내년에는 어쨌든 저희들이 최대한 임금인상이 될 수 있도록, 그리고 또 내부적으로도 공무원들 같은 경우는 그래도 임금인상이 꾸준히 되어 왔습니다. 그런데 그게 지금 안 되고 있기 때문에 실질임금이 하락되고 있어서 그 점에 대해서도 내년도에는 저희들이 도 집행부에게 강력하게 요구를 더 해서 꼭 임금인상을 이루어내도록 그렇게 하겠습니다.
</p>
<p><b>○ 이현호 위원 </b> 그래서 보니까 우리 연구직 이직자가 다른 데로 갔지 않습니까?
</p>
<p><b>○ 경기연구원장 임해규 </b> 네.
</p>
<p><b>○ 이현호 위원 </b> 14년도에는 3명이고 15년도에도 3명, 6명이 됐거든요. 16년도에는 아직 없습니까, 이직자가?
</p>
<p><b>○ 경기연구원장 임해규 </b> 네, 저희가 정년을 맞은 분은 아직은 없습니다. 그런데 내년부터는 생기고.
</p>
<p><b>○ 이현호 위원 </b> 아니, 정년 말고.
</p>
<p><b>○ 경기연구원장 임해규 </b> 이직의 경우는 올해도 이직이 물론 있었습니다. 이직이 있었는데 그런데 꼭 급여 때문이라고는 보지 않습니다만 지금과 같은 사태가 계속 진행이 되면 그야말로 이런 처우문제 때문에도 다른 곳으로 적극적으로 이직을 고려하는 연구원들이 생겨날 수도 있다 이렇게 우려를 하고 있습니다.
</p>
