<p><b>○ 임채호 위원 </b> 2017년도죠. 2017년도 예산은 연구비를 얼마 정도 책정할 계획이신가요? 준비 안 됐으면…….
</p>
<p><b>○ 경기연구원장 임해규 </b> 2017년도 예산액에 연구사업비는 63억 정도 저희들이 예정하고 있습니다.
</p>
<p><b>○ 임채호 위원 </b> 63억. 많이 내리네요?
</p>
<p><b>○ 경기연구원장 임해규 </b> 네, 2016년도에 74억이었는데 그게 63억이니까 좀……. 
</p>
<p><b>○ 임채호 위원 </b> 그건 예산 할 때 다룰 거고 여하튼 간에 연구과제에 대해서 많은 도민들이 활용할 수 있게끔 하고 또한 제가 보기에는 연구용역이 연구과제에서도 거의 흡사한 것이 많다. 그래서 괜히 쓸데없이 예산 낭비할 필요 없이 같이 연계할 수 있는, 용역과 연구과제를 연계할 수 있는 방안도 한번 모색을 해 봐라 이런 말씀을 드리고 싶습니다.
</p>
<p><b>○ 경기연구원장 임해규 </b> 네, 그렇게 하겠습니다.
</p>
<p><b>○ 임채호 위원 </b> 이상입니다.
</p>
<p><b>○ 위원장 이재준 </b> 임채호 위원님 수고하셨습니다. 더 이상 질의하실 위원님 안 계십니까?
</p>
<p style="padding-left:2.4em">    (「없습니다.」하는 위원 있음)
</p>
<p style="padding-left:1.2em">  얼마 전에 어떤 모임에서 이런 얘기가 나왔습니다. 우리 경기도에 연구기관들이 많이 있는데 기본적으로 데이터만을 공유할 수 있는 방법이 없겠느냐? 그러니까 연구논문, 연구업적이 아니라 거기서 사용한 데이터만을 쭉 축적해서 모든 기관이 같이 쓸 수 있는 그런 게 어떻겠느냐 이런 얘기가 나왔는데 혹시 다른 산하기관들하고 어떤 업무협약이나 이런 걸 토론할 때 기회가 되시면 한번 거론 좀 해 주셨으면 좋겠습니다. 
</p>
<p><b>○ 경기연구원장 임해규 </b> 네, 그렇게 하도록 하겠습니다. 그렇지 않아도 아마 이번 달이나 다른 기관들하고 MOU를 체결하기로 했기 때문에 그때 연구성과물을 공동으로 공유할 수 있는 시스템에 대해서도 논의해 보도록 하겠습니다.
</p>
<p><b>○ 위원장 이재준 </b> 그리고 데이터가 사실 10년 전 거랑 지금 거랑 저희들이 비교해 볼 필요성도 있는데 그것이 축적은 논문으로는 되어 있는데 그것이 따로따로 별도의 데이터는 없어서 검색할 때 필요하다는 그런 생각이 들어서요.
</p>
<p style="padding-left:1.2em">  더 이상 질의하실 위원님이 안 계시므로 오늘 경기연구원 소관 업무에 대한 질의와 답변을 마치겠습니다.
</p>
<p style="padding-left:1.2em">  위원 여러분 그리고 임해규 경기연구원장을 비롯한 임직원 여러분! 장시간 열의를 갖고 행정사무감사에 임해 주신 위원 여러분과 행정사무감사를 위한 자료 준비와 위원님들의 질의에 성심껏 답변해 주신 경기연구원 원장을 비롯한 임직원 여러분께 감사를 드립니다.
</p>
<p style="padding-left:1.2em">  그러면 이상으로 경기연구원 소관 사항에 대한 2016년 행정사무감사를 모두 마치겠습니다.
</p>
<p class=''ar''>(17시39분 감사종료)
</p>
<p><hr /></p>
<p><b>○ 출석감사위원(10명)
</b></p>
<p class=''aMan''>이재준나득수박형덕김승남양근서오완석이현호임채호장동일최춘식</p>
<p><b>○ 출석전문위원
</b></p>
<p class=''em15''>   수석전문위원 오태철
</p>
<p><b>○ 피감사기관참석자
</b></p>
<p><p class=''em15''>경기연구원장 임해규부원장 이상훈</p>
<p><p class=''em15''>경영기획본부장 이상대대외협력처장 이병관</p>
<p><p class=''em15''>북부연구센터장 김동성연구기획실장 유영성</p>
<p><p class=''em15''>공존사회연구실장 이용환공감도시연구실장 이외희</p>
<p><p class=''em15''>상생경제연구실장 김군수휴먼교통연구실장 지우석</p>
<p><p class=''em15''>생태환경연구실장 이기영연구지원부장 배미성</p>
<p><p class=''em15''>행정지원부장 이용원재정지원부장 박인숙</p>
<p><p class=''em15''>대외ㆍ의정부장 이덕환</p>
<p><b>○ 기록공무원
</b></p>
<p><p class=''em15''>이춘영</p>
