            <div','경기도의회',false,'{"legacy_id": "audit-9630", "files": [], "source": "kms.ggc.go.kr 행정사무감사", "url": "https://kms.ggc.go.kr/cms/mntsViewer.do?mntsId=9630"}'::jsonb,'2016-11-07'::date,'2016-11-07'::date where not exists (select 1 from public.posts where attachments->>'legacy_id' = 'audit-9630');
insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'audit','[2015.11.13. 금요일] 경기연구원 — 기획재정위원회 2015년도 행정사무감사','<div class="box" style="margin-bottom:16px"><b>제9대 경기도의회 기획재정위원회</b> · 2015년도 행정사무감사(2015. 11. 10. ~ 2015. 11. 23.)<br>원문: <a href="https://kms.ggc.go.kr/cms/mntsViewer.do?mntsId=8822" target="_blank" rel="noopener" style="color:var(--primary);text-decoration:underline">경기도의회 회의록 뷰어에서 보기</a></div><p>2015년도 행정사무감사 
</p>
<h4>기획재정위원회 회의록
</h4>
<p class=''ar''>경기도의회사무처
</p>
<p><hr /></p>
<p>피감사기관 : 경기연구원
</p>
<p><hr /></p>
<p>일  시 : 2015년 11월 13일(금)
</p>
<p>장  소 : 경기연구원 회의실
</p>
<p><hr /></p>
<p class=''ar''>(10시18분 감사개시)
</p>
<p><b>○ 위원장 배수문 </b> 좌석을 정돈하여 주시기 바랍니다. 성원이 되었으므로 지금부터 지방자치법 제41조, 동법 시행령 제39조 및 경기도의회 행정사무감사 및 조사에 관한 조례 제2조 규정에 의하여 경기연구원에 대한 2015년도 행정사무감사를 시작하겠습니다. 
</p>
<p style="padding-left:1.2em">  위원 여러분 그리고 경기연구원 원장을 비롯한 임직원 여러분! 안녕하십니까? 경기도의회 기획재정위원장 배수문 위원입니다. 오늘 감사위원장으로 같이 여러분들과 행감을 진행하게 되었습니다. 오늘은 우리 위원회 감사일정에 따라 경기연구원에 대한 행정사무감사를 실시하게 되었습니다. 여러분도 잘 아시는 바와 같이 지방의회 행정사무감사는 연구원의 행정사무 전반에 관한 실태를 정확히 파악하여 의정활동에 반영하고 도민의 삶의 질 향상에 기여하고자 함이 목적이므로 매우 중요한 의미가 있다고 하겠습니다. 
</p>
<p style="padding-left:1.2em">  오늘은 경기도의 싱크탱크인 경기연구원의 운영 실태를 감사하는 것인 만큼 연구원에 대한 심도 있는 감사활동으로 경기도 발전을 위한 정책대안이 제시될 수 있도록 위원 여러분들의 적극적인 감사활동을 부탁드립니다. 아울러 감사에 임하는 원장과 임직원 여러분께서도 이와 같은 목적이 달성될 수 있도록 적극 협조해 주시기 바랍니다.  그러면 감사를 시작하기 전에 증인선서를 받도록 하겠습니다. 감사를 받는 원장 및 부원장, 본부장, 실장, 부장은 증인의 자격으로 소관 업무를 보고하고 질의에 답변하기에 앞서 먼저 선서하셔야 됩니다. 
</p>
<p style="padding-left:1.2em">  증인선서의 취지와 관계규정을 말씀드리면 선서를 하는 이유는 이번에 경기도의회가 2015년도 행정사무감사를 실시함에 있어 증인으로부터 양심에 따라 숨김없이 사실대로 증언하겠다는 서약을 받기 위한 것입니다. 만약 증인이 허위증언을 한 때에는 지방자치법 제41조제5항 및 경기도의회 행정사무감사 및 조사에 관한 조례 제30조의 규정에 의하여 고발될 수 있습니다. 또한 증언 또는 진술을 거부한 때에는 동법 규정에 의하여 500만 원 이하의 과태료가 부과될 수 있음을 알려드립니다.
</p>
<p style="padding-left:1.2em">  그러면 먼저 증인 출석여부를 확인하겠습니다. 증인들께서는 모두 자리에서 일어나 주시기 바랍니다. 
</p>
<p style="padding-left:1.2em">  경기연구원장 나왔습니까? 
</p>
<p><b>○ 경기연구원장 임해규 </b> 네.
</p>
<p><b>○ 위원장 배수문 </b> 경기연구원 부원장 나왔습니까?
</p>
<p><b>○ 부원장 이상훈 </b> 네.
</p>
<p><b>○ 위원장 배수문 </b> 경영기획본부장 나왔습니까?
</p>
<p><b>○ 경영기획본부장 이양주 </b> 네.
</p>
<p><b>○ 위원장 배수문 </b> 대외협력처장 나왔습니까?
</p>
<p><b>○ 대회협력처장 이병관 </b> 네.
</p>
<p><b>○ 위원장 배수문 </b> 북부연구센터장 나왔습니까? 
</p>
<p><b>○ 북부연구센터장 김동성 </b> 네.
</p>
<p><b>○ 위원장 배수문 </b> 연구기획실장 나왔습니까?
</p>
<p><b>○ 연구기획실장 유영성 </b> 네.
</p>
<p><b>○ 위원장 배수문 </b> 연구지원부장 나왔습니까?
</p>
<p><b>○ 연구지원부장 배미성 </b> 네.
</p>
<p><b>○ 위원장 배수문 </b> 행정지원부장 나왔습니까?
</p>
<p><b>○ 행정지원부장 이용원 </b> 네.
</p>
<p><b>○ 위원장 배수문 </b> 재정지원부장 나왔습니까?
</p>
<p><b>○ 재정지원부장 박인숙 </b> 네.
</p>
<p><b>○ 위원장 배수문 </b> 자치의정부장 나왔습니까?
</p>
<p><b>○ 자치의정부장 신원득 </b> 네.
</p>
<p><b>○ 위원장 배수문 </b> 공존사회연구실장 나왔습니까?
</p>
<p><b>○ 공존사회연구실장 송상훈 </b> 네.
</p>
<p><b>○ 위원장 배수문 </b> 공감도시연구실장 나왔습니까? 
</p>
<p><b>○ 공감도시연구실장 이외희 </b> 네.
</p>
<p><b>○ 위원장 배수문 </b> 상생경제연구실장 나왔습니까? 
</p>
<p><b>○ 상생경제연구실장 김군수 </b> 네.
</p>
<p><b>○ 위원장 배수문 </b> 휴먼교통연구실장 나왔습니까? 
</p>
<p><b>○ 휴먼교통연구실장 지우석 </b> 네.
</p>
<p><b>○ 위원장 배수문 </b> 생태환경연구실장 나왔습니까? 
</p>
<p><b>○ 생태환경연구실장 고재경 </b> 네.
</p>
<p><b>○ 위원장 배수문 </b> 다음은 선서의 요령을 설명드리겠습니다. 선서는 전체 증인을 대표하여 경기연구원장이 발언대로 나오셔서 오른손을 들고 선서문을 낭독하시고 다른 증인들께서는 자리에 서서 오른손만 들어주시기 바랍니다. 
</p>
<p style="padding-left:1.2em">  그러면 선서해 주시기 바랍니다. 
</p>
<p><b>○ 경기연구원장 임해규 </b> 선서! 본인은 경기도의회가 지방자치법 제41조, 같은 법 시행령 제39조제1항, 경기도의회 행정사무감사 및 조사에 관한 조례 제2조에 따라 소관 업무에 대한 2015년도 행정사무감사를 실시함에 있어 기관장으로서 성실히 감사를 받을 것이며 또한 증인으로서 증언을 함에 있어서는 지방자치법 시행령 제43조5항과 경기도의회 행정사무감사 및 조사에 관한 조례 제19조에 의거하여 양심에 따라 숨김과 보탬이 없이 사실 그대로 말하고 만일 거짓이 있으면 위증의 벌을 받기로 서약하고 이에 선서합니다. 2015년 11월 13일 경기연구원장 임해규.
</p>
<p><b>○ 위원장 배수문 </b> 모두 자리에 앉아주시기 바랍니다. 그러면 경기연구원장 나오셔서 간부소개와 업무보고를 간략히 해 주시기 바랍니다. 
</p>
<p><b>○ 경기연구원장 임해규 </b> 보고에 앞서 경기연구원의 주요간부를 소개해 드리겠습니다. 간부명단은 보고자료 68쪽에 있습니다. 참고해 주시기 바랍니다. 
</p>
<p style="padding-left:1.2em">  먼저 이상훈 부원장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  다음은 이양주 경영기획본부장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  다음은 이병관 대외협력처장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  다음은 김동성 북부연구센터장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  다음은 유영성 연구기획실장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  다음은 송상훈 공존사회연구실장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  다음은 이외희 공감도시연구실장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  다음은 김군수 상생경제연구실장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  다음은 지우석 휴먼교통연구실장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  다음은 고재경 생태환경연구실장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  다음은 배미성 연구지원부장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  다음은 이용원 행정지원부장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  다음은 박인숙 재정지원부장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  마지막으로 신원득 자치의정부장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  이상으로 간부소개를 마치겠습니다.
</p>
<p style="padding-left:1.2em">  연구원의 주요업무 보고드리도록 하겠습니다. 존경하는 배수문 위원장님 그리고 기획재정위원회 감사위원 여러분! 여러분의 노고에 감사드립니다. 이번 행정사무감사 경기연구원 업무보고는 존경하는 배수문 위원장님 배려로 프레젠테이션으로 간단히 보고드리도록 하겠습니다. 보고를 좀 더 간략하고 명료하게 하기 위해서 준비하였습니다. 좀 더 자세한 내용은 미리 배부해 드린 주요 업무보고를 참고해 주시면 감사하겠습니다. 보고를 시작하도록 하겠습니다. 
</p>
<p class=''ar''>(10시25분 프레젠테이션 개시)
</p>
<p><b>○ 경기연구원장 임해규 </b> 연구목표는 우선 연구의 3대 방향과 그리고 경영 4대 방침, 연구성과, 경영성과, 반성 및 개선방안 순서로 말씀드리겠습니다. 
</p>
<p style="padding-left:1.2em">  저희 연구원의 3대 방향은 첫 번째 미래지향적 연구입니다. 두 번째는 학제 간 융합연구이고 세 번째는 수요맞춤형 연구입니다. 저희 경영의 4대 방침은 첫째는 GRI 역할을 재정립하는 것이고 둘째는 조직문화를 개선하고 셋째는 연구역량을 강화하고 마지막으로 대외소통을 강화하는 것을 저희 2015년 경영의 4대 방침으로 삼았습니다. 
</p>
<p style="padding-left:1.2em">  먼저 연구성과는 저희들 연구는 연구보고서와 이슈분석 두 파트로 크게 나눌 수 있습니다. 연구보고서는 다시 정책연구, 수탁연구, 전략연구 그리고 기본연구의 네 가지 연구가 있습니다. 이슈분석은 이슈&진단과 현안브리프 이렇게 두 종류를 저희들이 발행하고 있습니다. 
</p>
<p style="padding-left:1.2em">  정책연구는 저희들이 가장 기본적으로 수행하는 연구입니다. 주로 경기도, 도의회 그리고 경기도 산하 시군에서 보통 연구의뢰가 오거나 저희들이 자체 발굴하는 정책연구도 있습니다. 저희들 실이 공존사회, 공감도시, 상생경제, 휴먼교통, 생태환경의 5개 부서가 본원에 있고 경기북부센터 이렇게 6개 부서가 있습니다. 그 부서에서 정책연구 중에 저희들이 특징적으로 한두 가지만 위원님께 소개시켜 드리도록 하겠습니다. 아마 이 연구는 각각의 연구실 앞쪽에 붙은 공존, 공감, 상생, 휴먼, 생태라고 하는 그와 같은 저희들이 지향하는, 각 실에서 지향하는 가치에 걸맞은 연구다 싶은 것을 몇 가지 뽑았습니다.
</p>
<p style="padding-left:1.2em">  먼저 공존사회에서는 경기특별도 타당성에 관한 연구를 지금 수행하고 있습니다. 그 연구 옆에 별표 표시돼 있는 것은 현재 연구가 마무리되지 않고 올해 연구과제로 진행되고 있다는 의미입니다. 그리고 제8대 경기도의회 의정성과 분석을 하였습니다. 공감도시에서는 공유지 활용, 청년층 임대주택 공급방안 연구가 있고 그리고 경기도 비경제활동인구의 노동시장 유인정책 방안이 있습니다. 그리고 경기도 중산층 강화를 위한 정책방안 연구가 있습니다. 휴먼교통에서는 경기도 어린이 등하교길 교육안전 증진방안이 있습니다. 생태환경에는 경기도 물 환경정책 비전연구를 수행하고 있습니다. 그리고 경기북부센터에서는 경기북부지역 규제와 지원제도 개선방안 연구를 수행했습니다. 
</p>
<p style="padding-left:1.2em">  그다음은 연구보고서 중에 수탁연구에 대해서 몇 가지 소개해 드리도록 하겠습니다. 공존사회에서는 경기도 따복공동체 기본계획 수립연구를 수행 중이고 그리고 경기도의회 의정활동 활성화를 위한 자치법규 개선 연구를 수행하였습니다. 공감도시에서는 경기비전 2040을 현재 마무리 단계에 있습니다. 상생경제에서는 경기도 판교테크노밸리 중기발전전략 수립을 수행 중에 있고 휴먼교통에서는 개성공단 지원 물류단지 타당성 평가 및 운영방안 연구를 수행하였습니다. 그리고 생태환경에서는 반월ㆍ시화산업단지 환경질 개선방안을 현재 마무리 단계에 있고 경기북부연구센터에서는 경기북부 K-디자인빌리지 개발전략 연구가 지금 마무리 단계에 있습니다. 
</p>
<p style="padding-left:1.2em">  다음은 연구보고서의 전략연구에 대해서 말씀드리겠습니다. 먼저 공존사회에서는 경기도민 삶의 질 동태분석을 위한 기초연구를 지금 시작했습니다. 그리고 경기도 발전 전략과제 체계화 연구도 지금 수행하고 있습니다. 경기북부센터에서는 경기북부 10개년 발전 계획 중간보고를 하고 지금 마무리하고 있습니다. 
</p>
<p style="padding-left:1.2em">  다음은 기본연구입니다. 기본연구는 박사들 개인의 어떤 질적연구를 위해서 학술연구 중심으로 하고 있는 연구입니다. 먼저 공존사회연구실에서는 인구고령화와 지역별 사회보장 실태연구를 수행 중이고 공감도시연구실에서는 사회통합형 지역발전정책 개발과 도내 적용방안을 연구 중입니다. 상생경제에서는 사회정책의 사중손실분석 방안을 연구하고 있고 휴먼교통에서는 경기도 주차장 공유 도입을 위한 기초연구를 하고 있습니다. 생태환경에서는 ICT기술 물 재난 관리체계 도입 방안 연구를 하고 있고 경기북부센터에서는 광역버스 차내 혼잡도 완화의 경제적 편익측정에 관한 연구를 수행하고 있습니다. 지금 이 기본연구는 아직 연구가 완결되지 못한 가장 큰 이유는 사실 저희가 기본연구를 올해 상당히 강화해서 확대하기로 결정하고 착수가 조금씩 늦은 측면이 있고 또 각 박사님들이 정책연구를 마무리하고 시간적 여유가 있을 때 아무래도 기본연구를 하게 되는 경향이 있어서 12월이 돼야 연구가 대체로 다 마무리될 걸로 그렇게 보고 있습니다. 
</p>
<p style="padding-left:1.2em">  다음은 연구보고서보다는 좀 짧은 형태의 이슈를 중심으로 한 그런 연구물들입니다. 우선 이슈&진단을 공존사회에서는 낙태실태와 쟁점 그리고 학교 밖 청소년 지원 대책과 현실적 보완방안, 공감도시에서는 해외개발협력에서 지역건설업의 활로를 찾다 그리고 상생경제에서는 경기도 가계부채 진단 및 시사점, 휴먼교통에서는 교통약자 정책, 교통복지의 시작 그리고 생태환경에서는 수도권 매립지 이슈와 시사점, 수도권 가뭄으로부터 안전한가, 경기북부센터에서는 통일대박, 통일의 손익계산서라는 제목으로 그간 이슈&진단을 발행했습니다. 아마 위원님들께서 이 중에 일부는 받아보시지 않았을까 생각이 듭니다. 
</p>
<p style="padding-left:1.2em">  다음은 이슈분석 중에 현안브리프입니다. 현안브리프와 이슈분석의 차이점은 현안브리프는 이슈진단보다는 좀 더 짧고 조금은 더 발 빠른 대응을 하는 그와 같은 발행물입니다. 아마 위원님들 문자메시지로 발송을 해서 보신 분도 있으리라 생각이 듭니다. 우선 공존사회연구실에서 세월호 유가족들의 삶과 우리 사회의 과제 그리고 지방의원의 상해ㆍ사망 시의 보상금 지급요건의 개선이라는 현안브리프를 발간했습니다. 공감도시에서는 청년층 주거문제, 이제 관심을 가져야 할 때다 해서 주거문제에 대해서 했고 상생경제연구실에서는 진화하는 창조경제혁신센터, 성공의 조건과 과제라는 주제로 발행했습니다. 그리고 휴먼교통에서 버스가 이용하지 않는 버스베이라는 버스베이 개선점에 대해서 연구를 했고 생태환경연구실에서는 환경-경제 상생을 위한 상수원 입지규제 개선방안을 발행했고 경기북부센터에서는 천년경기를 맞이하여라는 주제로 발행한 바가 있습니다. 
</p>
<p style="padding-left:1.2em">  지금까지 말씀드린 것이 저희가 발행한 주요 연구물들의 특징적인 것들을 저희들이 했습니다만 이외에 저희들이 연구한 것이 거의 300건 가까이, 연구를 완료한 것까지 포함하면 약 300여 건의 연구물이 되기 때문에 위원님들께 배부해 드린 리스트에 보면 나머지 연구물들이 전부 다 망라되어 있습니다. 
</p>
<p style="padding-left:1.2em">  그래서 저희가 이 연구물 중에 정책 반영된 것을 유형별로 지난 3년 것을 살펴보았습니다. 그런데 법령 제ㆍ개정 및 제도개선에 반영된 것으로 올해 한 11건 정도가 있고 중앙정부의 정책 수정ㆍ개선하는 데 영향을 미친 것이 8건 그리고 도 정책기조를 개발하거나 또는 변경한 것이 34건, 도정현안 사안에 대해서 지원한 것이 약 69건 그리고 수범사례에 관한 연구가 한 8건 정도 됩니다. 그래서 저희들이 현재……. 아, 제가 잘못, 2014년 것을 잘못 말씀드렸는데 2015년은 드린 거에 오른쪽에 있는데 제가 잘못 말씀드렸습니다. 대체로 2015년은 9월 30일 기준으로 되어 있기 때문에 건수는 전년도에 비해서 한 20건에서 30건 적게 잡혀 있습니다만 저희들 연구과제 완료한 기준으로 하면 전년도하고 대비해서 거의 같은 숫자라고 보시면 될 것 같습니다. 그리고 연구성과가 어떻게 반영되었는가와 관련해서는 별도로 저희들이 위원님들께 좀 더 상세히 정리해서 어떤 식으로 구체적으로 반영되었는가 하는 것을 별도로 위원님들께 배부해 드렸습니다. 참고해 주시면 감사하겠습니다. 
</p>
<p style="padding-left:1.2em">  다음은 경영성과에 대해서 말씀드리겠습니다. 앞에 말씀드린 대로 네 가지 영역으로 나눠서 보고드리겠습니다. 첫째는 GRI 역할 재정립에 관한 것입니다. 저희들이 역할 재정립이라고 하는 것은 그간에 주로 우리 GRI가 경기도청, 도 집행부의 연구를 주로 맡아서 수행하는 어떻게 보면 경기도청 산하 연구원이라는 의미가 강했다고 한다면 저희들이 경기연구원으로 기관 명칭을 변경하면서 명실상부하게 경기도민의 어떤 연구기관으로 거듭나야 되지 않겠는가 하는 문제의식 속에서 저희들이 GRI 역할을 재정립하자, 도민의 연구원으로 재정립하자고 하는 그런 차원에서 경영방침을 정하고 수행한 사업입니다.
</p>
<p style="padding-left:1.2em">  우선 첫째는 기관 명칭을 변경하고 그리고 저희들 예산을 위원님들 늘 겪으시는 일이지만 사실 저희 연구원 예산서를, 아주 구체적인 사업설명서를 위원님들께 일찍 그간에 배부하지 못했습니다. 그런데 그것은 저희들이 의회로부터 심사받는 것이 출연금 100억이라고 하는 것 때문에 그간에 그렇게 했는데 향후 저희들 세부적인, 이사회에서 통과한 예산 계획을 세부적인 목록과 상세설명을 일찍 위원님들께 드려서 의회로부터 저희들 예산에 대한 감시와 통제를 철저히 받겠다고 하는 의지로 저희들이 내부적으로 3회에 걸쳐서 예산에 관한 회의를 저희들이 했고 그래서 이번에 이사회를 통과하면 위원님들께 일찍 배부될 걸로 그렇게 생각하고 있습니다. 그렇게 계획하고 있습니다. 
</p>
<p style="padding-left:1.2em">  그리고 GRI비전 2040을 수립했습니다. 이것은 올해가 저희들 20주년 기념이었기 때문에 20주년 기념을 맞이해서 지난 20년 과정을 돌아보고 향후 20년을 어떤 방향으로 할 것인지에 대해서 계획을 수립한 바 있습니다. 
</p>
<p style="padding-left:1.2em">  그리고 대외주의 연구과제를 대폭 해제했습니다. 이 점은 그간에도 행정사무감사를 통해서 여러 위원님들이 굉장히 많은 지적이 있으셨고 그리고 저희들이 도민의 알 권리가 가장 우선한다고 하는 그런 문제의식 속에서 연구과제를 해제하고, 대외주의 연구과제를 해제하고 내부적으로는 정보공개법에 맞게끔 공개를 우선원칙으로 확립했습니다. 그럼에도 불구하고 정보공개법상 비공개 사유가 되는 것만 엄격하게 저희들이 내부에서 검토해서 비공개를 하는 걸 원칙으로 했습니다. 그래서 명실상부하게 경기도민의 경기연구원으로 발돋움을 해야 되겠다고 하는 것이 저희들 GRI 역할 재정립의 취지이고 그런 관점에서 지난 한 해 노력해 왔습니다.
</p>
<p style="padding-left:1.2em">  다음은 조직문화 개선문제입니다. 우선 지난 1년 동안 저희들이 제도개선 태스크포스를 운영했습니다. 운영을 해서 우선 저희들 내부 평가체계 개편안을 마련하고 특히 비정규직 처우개선에 대해서도 안을 마련했습니다. 그래서 이것은 지난번 추경 때 위원님들께서 처우개선비를 추경예산으로 세워주셨기 때문에 지금 도 집행부와 개선을 위해서 협의 중에 있습니다.
</p>
<p style="padding-left:1.2em">  다음은 화합하는 직장문화를 만들기 위해서 저희들이 동아리를 좀 더 활성화하고 또 단합대회도 한두 차례 정도 열었습니다.
</p>
<p style="padding-left:1.2em">  다음은 사업계획을 저희들이 보통 전년도에서 차년도 사업계획을 가을에 하는데 이것도 박사 한 분, 한 분이 자신이 내년도에 할 사업을 전체 박사와 석사연구원들이 함께 참여하는 속에서 연구계획을 발표하는 것을 통해서 우리 전체가 각자 어떤 박사가 어떤 연구를 하는지 서로가 알고 또 협업연구를 촉진하기 위해서 발표회를 개최했습니다. 그리고 올해 저희들이, 석사연구원들이 연구원의 주요한 축으로서, 주인으로서 존재하고 있기 때문에 석사연구원들의 연구의욕을 고취시키기 위해서 아이디어 경진대회를 개최할 겁니다. 조만간 개최할 계획이 되어 있습니다만 여기서 나오는 좋은 아이디어는 저희들이 정책연구과제로 할 생각을 가지고 있습니다. 이러한 사업들을 통해서 저희 경기연구원의 석사, 박사 그리고 행정원들, 모든 연구원이 좀 만족할 만한 그런 직장으로 하려고 하는 계획을 가지고 있습니다.
</p>
<p style="padding-left:1.2em">  다음은 연구역량 강화 부분입니다. 아무래도 저희 연구원 존립의 의의는 저희들이 지금보다는 훨씬 나은 연구역량을 갖는 것에 있다고 생각합니다. 그래서 그렇게 하기 위한 주요한 것 중의 하나가 많은 위원님들이 지적하셨지만 통섭연구가 굉장히 중요하다고 생각을 하고 있습니다. 그래서 통섭연구를 위해서 전공분야를 좀 다변화하고자 했습니다. 그래서 저희들이 철학, 미학 그리고 과학, 법학, 사회학 등의 기초학문 분야의 연구자를 올해 8명 정도 새로, 이제 나간 분들도 계시고, 한 네 분 정도는 나가셨고 한 네 분 정도는 나간 분에 대해서 뽑고 4명 정도는 신규로 저희들이 뽑아서 한 여덟 분 정도의 박사인력을 확충했습니다. 그다음에 연구원의 학술연구를 확대했는데 이것은 앞서 저희가 보고를 몇 가지 드렸습니다만 박사들이 적극적으로 기본연구를 할 수 있도록 여건을 만드는 일에 저희들이 좀 힘을 기울였습니다. 그리고 연구기반으로서 패널사회조사를 지금 연구를 수행하고 있는데요. 이 패널사회조사는 사실 저희 연구원이 연구기반을 확고히 하는 가장 중요한 물적 토대라고 생각을 해서 그간에 저희들이 독자적으로 한 분, 한 분 박사들께서 연구과제를 수행할 때 설문조사 형식으로 1,000만 원 이하의 적은 예산을 들여 가지고 사회조사를 했습니다만 지금 패널사회조사는 그런 수준이 아니라 저희들이 종단연구조사를 지금 하고자 하는 겁니다. 이게 경기도에서도 종합사회조사를 하고 있습니다만 그것은 종단패널조사는 아닙니다. 그런데 저희 연구원에서는 종단패널조사를 지금 실시하고 있습니다. 그래서 이러한 사업을 통해서 다양한 시각을 포함하는, 포괄하는 경기연구원이 되고자 그래서 그것을 통해서 연구의 질을 제고하는 그와 같은 노력을 하고 있습니다.
</p>
<p style="padding-left:1.2em">  다음은 대외소통강화 부문입니다. 우선은 도 집행부와 정책협의를 활성화하고자 애를 쓰고 있습니다. 그래서 도에서 벌어지는 각종 정책을 둘러싼 토론회나 이런 곳에 저희들이 적극적으로 참여해서 의견 개진하고 있습니다. 그리고 도의회와 연구협력의 질을 제고하고자 하는 노력을 기울였습니다. 그래서 상임위원회별로 의정 콜로키움을  개최하고 있고 또 도의회 발의 조례에 대해서 저희들이 가급적 지원을 하고자 노력하고 있고 또 도의회에서 주관하는 각종 토론회에 적극적으로 참여해 왔습니다. 그리고 찾아가는 현장연구를 활성화하기 위해서 또 노력을 했습니다. 그래서 찾아가는 시군 순회토론회를 비롯해서 저희들이 현장 순회간담회를 수차례 열었습니다. 그리고 연구성과 공유체계를 확대하기 위해서 문자메시지를 통해서도 저희들 연구한 것을 보내기도 하고 또 이메일을 통해서 보내기도 하고, 이메일을 통해서 저희들의 연구성과를 공유하는 거는 약 한 1만 건 정도에 해당하고 저희들이 올해 홈페이지도 개편을 해서 새로운 홈페이지로 서비스를 하고 있습니다. 이를 통해서 협력적인 거버넌스를 지향하는 그런 경기연구원이 되고자 하는 목표를 실행하고 있습니다.
</p>
<p style="padding-left:1.2em">  저희들이 이와 같은 목표와 방침 속에서 과제를 수행하고 연구과제 수행하고 또 경영을 했습니다만 여전히 미흡한 부분이 상당히 많았습니다. 그래서 이번에는 저희들 내부적으로 어떠한 반성의 토대에서 어떤 측면의 개선방안이 필요한가에 대해서 간략히 말씀드리겠습니다. 먼저 지역연구를 확대해야 한다는 문제 그리고 사회통합연구를 강화해야 한다는 문제 그리고 의회협력연구를 확대하는 문제 그리고 연구역량을 강화하는 문제입니다. 이와 같은 방향은 2015년에도 나름대로 이런 방향에서 하려고 했습니다만 역시 평가결과 아직 미흡한 것으로 그렇게 판단을 했습니다. 먼저 지역연구 확대 말씀을 간단히 드리면 지역균형발전연구가 다소 미약했다 이렇게 생각하고 있습니다. 그래서 북부발전 10개년 계획을 세웠습니다만 동부발전에 대해서도 현장에 많은 요구가 있는데 저희들이 사실 올해 수행하지 못했습니다. 그래서 내년에는 동부발전 10개년 계획도 한번 수행하면 어떨까 하는 생각을 가지고 있습니다. 그리고 아무래도 균형발전에 관한 연구가 시군별로 상당히 요구도 많고 또 앞으로 많이 수용을 해야겠다는 생각을 하고 있습니다.
</p>
<p style="padding-left:1.2em">  다음은 사회통합연구 강화부문입니다. 사회갈등을 해소해야 된다는 그러한 문제는 어제오늘의 일이 아닙니다만 사실 이 분야가 저희들 연구원에서 아직 연구가 미흡하지 않았나 이런 생각을 하고 있습니다. 그래서 사회통합 현안연구로써 노동정책에 관한 것 그리고 주거정책에 관한 것, 다문화정책에 관한 것 등 사회적 격차 완화를 위한 그래서 사회통합을 강화하는 방안의 그런 연구를 좀 더 활성화해서 추진할 그런 생각입니다. 그리고 의회협력연구를 확대해야 되는 문제인데요. 올해 의정연구센터가 사실 없어짐으로 해서 도의회와 우리 연구원 간의 연결지점이 취약해진 것이 사실입니다. 그래서 그것을 저희들이 질적 개선을 하기 위한 여러 가지 방안을 마련하고 또 추진을 하고자 했습니다만 사실 착수도 좀 상당히 늦었고 그래서 올해는 많은 성과를 내지는 못했습니다. 그렇지만 저희들이 시스템은 지금 구축을 했기 때문에 도의회의 정책생산을 하는 것을 지원하는 그런 역할을 강화할 생각입니다. 그래서 모든 상임위원회와 의정 콜로키움을 하는 문제를 비롯해서 저희들이 다각적인 위원님들과의 접촉면을 넓히는, 그래서 정책형성을 지원하고 또 위원님들이 발의하는 조례에 대한 지원을 전문적으로 하기 위한 그런 노력을 배가해야 된다고 하는 그런 생각을 가지고 있습니다.
</p>
<p style="padding-left:1.2em">  마지막으로 연구역량 강화 관련해서는 연구의 질적 제고가 여전히 필요하다고 생각하고 있습니다. 올해 그렇게 해야겠다는 문제의식 속에서 나름 노력을 기울인 바가 있습니다만 향후 직무교육을 강화하고 그래서 연구방법론과 같은 것을 지속적으로 저희들이 내부교육을 실시하고 그리고 기본연구를 더욱 강화해서 기본적으로 기본연구의 성과는 해당 전공영역 학회지에 기재를 해서 질 관리가 되도록 하고 또 모든 그런 기본연구에 대해서는 영문발행을 저희들이 지금 권장하고 있습니다. 그리고 저희들이 국제학술대회 개최를 통해서 연구를, 이거는 경기도와 주요한 자매도시로 있는 곳과의 어떤 교류활성화, 그래서 도의 외교정책을 뒷받침하는 것뿐만이 아니라 또 우리 연구원의 연구의 질적 향상을 위해서도 국제학술대회가 상당히 필요하다고 생각을 하고 그래서 내년도에는 국제학술대회도 개최를 해 볼까 이런 생각을 가지고 있습니다.
</p>
<p style="padding-left:1.2em">  이것으로 준비한 저희들 업무보고를 마치겠습니다. 그 외에 우리 경기연구원의 일반현황은 제가 특별히 보고하지 않았습니다. 그것은 위원님들이 저희들 일반현황은 다 파악하고 계실 걸로 보기 때문에 자료로 대체하도록 하고 2014년 행정사무감사 처리요구사항, 위원님들이 전년도에 행정사무감사 때 처리하라고 요구하신 사항에 대한 조치결과는 위원님들께서 양해하시면 보고자료로 대체하도록 하겠습니다.
</p>
<p style="padding-left:1.2em">  이상으로 업무보고를 마치겠습니다. 감사합니다.
</p>
<p><hr /></p>
<p>업무보고서(경기연구원)
</p>
<p><hr /></p>
<p class=''ar''>(10시45분 프레젠테이션 종료)
</p>
<p><b>○ 위원장 배수문 </b> 임해규 원장님의 업무보고 잘 들었습니다. 다음은 감사를 위한 질의 답변 순서가 되겠습니다. 감사의 효율적인 진행을 위해서 질의는 일문일답으로 하되 질의시간에 제한을 두도록 하겠습니다. 우선 위원님 한 분당 10분씩 시간을 드리고 추가질의는 5분으로 하겠습니다. 그리고 5분의 추가질문이 끝나면 감사 진행상황과 시간 등 제반여건을 감안해 추가질문을 계속할지 여부를 결정하겠습니다. 원활한 감사진행을 위해 부득이 시간제한을 두게 된 점을 널리 양해해 주시면 고맙겠습니다.
</p>
<p style="padding-left:1.2em">  오늘은 이현호 위원님, 김호겸 위원님, 임병택 위원님 순으로 질의하도록 하겠습니다. 아울러 질의에 앞서 위원장으로서 한 가지 부탁의 말씀을 드리면 위원님들의 질의에 대하여 원장의 답변이 어려울 경우 업무담당 실장 및 부장 등 실무자가 답변해도 좋습니다. 다만 사전에 위원장의 동의를 얻은 후 발언대로 나와 소속과 직ㆍ성명을 분명히 밝히고 답변해 주시기 바랍니다.
</p>
<p style="padding-left:1.2em">  그러면 첫 번째로 이현호 위원님 질의하여 주시기 바랍니다.
</p>
<p><b>○ 임두순 위원 </b> 자료요청.
</p>
<p><b>○ 위원장 배수문 </b> 그럼 질의에 앞서 자료요청 먼저 받도록 하겠습니다. 임두순 위원님.
</p>
<p><b>○ 임두순 위원 </b> 남양주 임두순인데요. 최근 2년간 생태환경 연구한 목록만, 내용까지는 말고요. 목록만 하나 좀, 생태환경연구요. 그다음에 최근 2년간 장사시설 있죠, 장사시설. 화장장이나 이런 장사시설에 대한 연구내용, 저도 몇 번 받은 적이 있는데 그것도 따로 목록을 하나 만들어 주시고요, 한 장에다가. 그다음에 장기표류 지방도 사업 우선 선정하는 것에 대해서 용역 있죠, 우리 김동성 본부장님. 그리고 현재까지 진행된 내용이랑 앞으로 진행계획까지 간략하게 한 장으로 자료 좀 제출해 주시고요. 그다음에 규제완화 연구한 내용이 있으면 그 내용도 같이 제출해 주시기 바랍니다. 이 네 가지요.
</p>
<p><b>○ 위원장 배수문 </b> 또 자료요청하실, 최지용 위원님.
</p>
<p><b>○ 최지용 위원 </b> 최지용 위원입니다. 임두순 위원께서 장사시설 용역보고서에 대한 자료요청을 했었는데 화성시에 함백산 장사시설이 있죠? 그것도 별도로 하나 주시고. 감사원 감사 지적사항에 대한 조치결과도 해 주시면 좋겠고요. 군 공항 이전 후보지의 용역보고서가 있으면 그것도 한번 자료를 요청하겠습니다.
</p>
<p><b>○ 경기연구원장 임해규 </b> 다시 한 번 말씀해 주세요.
</p>
<p><b>○ 최지용 위원 </b> 군 공항 이전 후보지에 대한 용역입니다. 용역보고서 나왔죠?
</p>
<p><b>○ 경기연구원장 임해규 </b> 네, 용역보고, 검토보고서는 있습니다만 지금 대외비 처리돼 있습니다.
</p>
<p><b>○ 최지용 위원 </b> 감사기관에서 나와서 보자 그래도 안 보여주나요? 그건 어느 부서에서, 기관에서 대외비로 정해 놓으신 거죠?
</p>
<p><b>○ 경기연구원장 임해규 </b> 그것은 저희들이…….
</p>
<p><b>○ 최지용 위원 </b> 청와대입니까?
</p>
<p style="padding-left:2.4em">    (관계직원, 경기연구원장에게 개별설명)
</p>
<p><b>○ 경기연구원장 임해규 </b> 저희들 내부에서, 물론 그 연구를 의뢰한 곳에서 대외비로 해 달라는 요청이 있었고요. 그리고 저희들 내부에서도 아직까지 결정되거나 이런 사항이 아니기 때문에 그것을 대외적으로 공개하는 것이 여러 가지 문제가 있다고 생각이 들어서 저희들도 지금 대외비로 분류해서 처리하고 있습니다.
</p>
<p><b>○ 최지용 위원 </b> 자신 있게 보고서 제출을 못 하는 것은 그만한 이유가 있어서 아니겠습니까? 해당 지역에 어떤 이슈가 될 만하니까 제출을 못 하는 거 아니겠어요? 초유의 관심사업을 연구한 용역보고서를 제출하지 못하는 이유가 뭡니까?
</p>
<p><b>○ 경기연구원장 임해규 </b> 우선은 저희들이 검토, 그것을 결정하는 것은 아마 국방부 관련기관에서 결정하는 걸로 알고 있습니다.
</p>
<p><b>○ 최지용 위원 </b> 일단 자료요청은 그렇게 하고요. 우선 감사시작을 해야 되니까 일단 여기서 마치겠습니다.
</p>
<p><b>○ 위원장 배수문 </b> 또 자료요청하실 위원님 계십니까? 그러면 이현호 위원님부터 질의하도록 하겠습니다.
</p>
<p><b>○ 이현호 위원 </b> 이천 출신 이현호 위원입니다. 임해규 원장님과 또 임직원 여러분들 행정사무감사 준비하시느라고 수고 많으셨습니다. 우리 연구원 박사님들 성과연봉제를 운영하고 계시죠?
</p>
<p><b>○ 경기연구원장 임해규 </b> 네.
</p>
<p><b>○ 이현호 위원 </b> 기본연봉에다가 또 성과연봉을 하는데 제가 자료제출은 요구 안 했습니다. 그건 자료제출하다 보면 개인, 박사님들의 어떤 자존심도 있고 그래서 못 했는데 제대로 보니까 0~200%의 차이가 크더라고요. 못 받는 분은 못 받고, 그죠? 또 받는 분은 200%까지 받는데 너무 차등이 크다 보니까 못 받는 분들한테는 위화감을 느끼지 않느냐 그런 생각이 본인은 듭니다. 그래서 제 생각으로는 폭을 줄여서 우리 박사님들이 그런 위화감을 느끼지 않게끔 할 수 있는 방법이 없는지 제가 원장님께 질의합니다.
</p>
<p><b>○ 경기연구원장 임해규 </b> 그래서 저희가 제도개선 TF를 만들어서 지난 몇 개월간 저희들 나름대로 안을 만들었습니다. 그것은 일단 능력급 제도는 필요한 거라고 보기 때문에 저희들이 성과에 따라서 차등을 둬서 지급하는 것의 기조를 유지하되 방금 위원님께서 말씀하신 것처럼 너무나 차등 폭이 크기 때문에 이게 위화감 조성의 요인이 있어서 차이가 약 200%가 아니라 100% 정도가 나게끔 하는 걸로 저희들이 설계를 해서 지금 도 집행부하고 협의를 한 바가 있습니다. 그런데 위원님께서 관심을 그렇게 가져주셔서 감사를 드리고요. 앞으로도 도 집행부하고 이 문제에 관해서 지속적으로 협의해서 차등의 정도를 줄여서 박사님들께서 연구를 하는 데 조금 더 협력적 연구가 잘 되도록, 사실 차등이 너무 크고 이러면 협업연구에 장애요인이 있습니다. 왜냐하면 같이 연구를 하게 될 경우에 혹시 불이익을 받을까 이런 게 있어서 저희들이 협업연구 강화 차원에서도 한번 개선하려고 좀 더 노력하고자 합니다. 위원님들 계속 관심 가져주시면 감사하겠습니다.
</p>
<p><b>○ 이현호 위원 </b> 원장님이 답변해 주셨는데 도하고 긴밀하게 협조하고 또 원장님께서 의지만 있으면 저는 할 수 있다고 봅니다. 그래서 지금 말씀하신 대로 물론 차등은 두지만 폭이 크니까 개선해 주시기를 부탁드리고, 그렇게 되겠죠?
</p>
<p><b>○ 경기연구원장 임해규 </b> 쉽지는 않아 보입니다. 그렇지만 어쨌든 우리처럼 이렇게 0~200% 하는 사례가 사실 다른 연구원 같은 경우는 잘 없습니다. 굉장히 강한 차등 폭이기 때문에 저희들이 다른 연구원 사례도 말씀드려서 조금은 줄이도록 하는 데 노력하도록 하겠습니다. 
</p>
<p><b>○ 이현호 위원 </b> 네, 감사드립니다. 다음에는 연구원이나 박사님들의 부정행위를 미연에 방지하자는 말씀을 드리는데 아시겠지만 대학교수든지 일반사회에서도 논문 같은 거 표절논란이 많지 않습니까? 그래서 우리 연구원에서는 부정행위를 미연에 방지할 수 있는 시스템이 있습니까? 거기에 대해서 말씀해 주시기 부탁드립니다.
</p>
<p><b>○ 경기연구원장 임해규 </b> 저희들이 업무보고 할 때도 말씀드린 바가 있는 것 같습니다만 카피킬러라고 하는 프로그램이 있습니다. 그 프로그램에 박사가 연구한 연구물을 띄우면, 거기 입력하면 그 프로그램이 소장하고 있는 굉장히 많은 연구물들과 대조합니다. 대조해서 중복되는지 여부가 몇 % 정도 중복되는지 그런 것들을 체크하는 프로그램입니다. 그래서 그 프로그램에서 10% 이하로 중복이 나타나면 대체로 표절이 아닌 것으로 보통 그렇게, 물론 그것이 학계에서 공인 받거나 아니면 국가표준이거나 이런 건 아닙니다만 그런 정도면 표절했다고 보기 어렵다고 하는 취지의 그런 프로그램입니다. 그래서 그 프로그램으로 저희들이 운영해서 1차적으로 박사들께서 연구한 연구결과물이 연구지원부로 올라오면 연구지원부에서 그 프로그램을 돌려서 표절의 프로테이지, 표절이 있나, 중복성이 어느 정도인가 이런 거에 대한 프로그램의 결과를 연구결과보고서에 기재를 합니다. 그래서 결재를 할 때 우리 결재라인을 타고 부원장, 원장 결재라인으로 올라올 때 그거를 저희들이 점검하는 시스템으로 해서 하고 있고. 또 박사 개개인도 자신의 연구물이 중복성이 어느 정도인지를 스스로 자가 체크할 수 있도록 해 놨습니다. 그래서 박사 스스로도 자가 체크해서 중복이 안 되도록 그런 것들을 주의를 기울이는 그런 제도를 저희들이 시행하고 있습니다. 그래서 저희들 그간에 대부분의 연구물들, 정책연구물들은 그런 카피킬러를 통해서 다 검토를 했는데 크게 문제되는 연구물들은 없었습니다. 
</p>
<p><b>○ 이현호 위원 </b> 그동안 경기연구원에서 어떤 연구 부정행위가 혹시 있었나요?
</p>
<p><b>○ 경기연구원장 임해규 </b> 오래 전에 표절시비가 있어서 아마 징계도 받고 이런 적이 있었던 걸로 알고 있습니다. 제가 아주 구체적으로 기억을 못합니다만 오래 전에 있었던 것 같고 그 이후로는 굉장히 이 점에 대해서 박사 개개인들이, 연구자 개개인들이 상당히 경각심을 가지고 있기 때문에 근자에 이르러서는 제가 없는 것으로 알고 있습니다. 
</p>
<p><b>○ 이현호 위원 </b> 연구 부정행위가 이슈화되기 전에 사전에 확인할 수 있는 방법이 있으면 좋겠다 이런 말씀드리는 겁니다. 왜냐하면 사회 이슈화된 다음에 어떤 연구부정이 나타나면 박사님들한테도 상당히 치명타가 되지만 또 우리 연구원의 이미지도 손상되지 않나 이런 말씀드리면서 미연에 방지할 수 있는 시스템을 철저히 해 주시기를 간절히 부탁을 드리겠습니다. 
</p>
<p style="padding-left:1.2em">  또 한 가지는 제가 사전에 감사 자료요청한 건 아닌데요. 지금 경기도에 지방도가 장기동안 표류돼 가지고 확포장공사가 안 되는 곳이 많지 않습니까? 그래서 아마 경기도에서 연구원에다가 용역을 줘 가지고 타당성 검토를 하고 있는 것으로 알고 있습니다. 지금 진행 중에 있는 것이죠?
</p>
<p><b>○ 경기연구원장 임해규 </b> 네.
</p>
<p><b>○ 이현호 위원 </b> 어차피 진행 중에 있는데 박사님들이 하시겠지만 타당성 검사를 잘하셔서 조기에 지방도 확포장공사가 될 수 있도록 도와주시기 부탁드리면서 거기에 대해서 잠깐만 원장님께서 부연설명이 있으면 부탁드리겠습니다. 
</p>
<p><b>○ 경기연구원장 임해규 </b> 사실 저도 이 연구수행 관련해서 연구를 수행하는 박사님께 들은 이야기입니다만 오래 전에 손학규 지사님 시절이니까 그 시절에 예산사정이 상당히 괜찮을 때 상당히 많은 도로를 시군도가 아니라 우리 도가 관할하는 지방도로 많은 도로를 승격시키기도 하고 또 그렇게 할 수밖에 없는 것은 사실 우리 경기도 북동부지역의 시군들 같은 경우 재정력이 취약하기 때문에 시군비로 지방도로를 건설하기에 상당히 애로가 있어서 아마도 그때 많은 요청에 의해서 도에서 하는 지방도로 승격해서 계획을 많이 했던 걸로 알고 있습니다. 그런데 그 이후에 재정사정이 악화되면서 그것을 계획한 대로 다 진행을 하지 못해서 지금 굉장히 많은 민원으로, 어쨌든 그때 지방도로 승격을 해서 계획을 다 잡아 놓은 건데 주민과의 약속을 지키지 못해서 지금 경기도가 굉장히 재정상에 어려움이 있는 것을 파악하고 있습니다. 그래서 아마 이 연구용역을 통해서 우선 빨리해야 될 것은 아무리 힘들어도 빨리하자 하는 취지로 우선순위를 정하는 연구용역인 걸로 알고 있습니다. 그래서 이 연구용역이 정말로 각 지방의 사정을 잘 살피고 또 우선 시급한 것들을 잘 살펴서 원활하게 연구가 수행되도록 저희 연구원에서 만전을 기하겠습니다. 
</p>
<p><b>○ 이현호 위원 </b> 네, 공정하게 해 주시고요. 우리 이천에도 아마 2건이 올라와 있는 것 같은데 공정한 용역을 해 주시기 부탁드리겠습니다. 
</p>
<p><b>○ 경기연구원장 임해규 </b> 알겠습니다. 
</p>
<p><b>○ 이현호 위원 </b> 이상으로 질의 마치겠습니다. 
</p>
<p><b>○ 위원장 배수문 </b> 이현호 위원님 수고하셨습니다. 이어서 임병택 위원님 질의하여 주시기 바랍니다. 
</p>
<p><b>○ 임병택 위원 </b> 임병택 위원입니다. 먼저 원장님께서 PT를 통해서 업무보고 해 주신 부분은 대단히 잘 봤습니다. 그리고 또 이해도도 훨씬 높았고요. 직접 새로운 보고방식을 채택해 주셔서 감사드립니다.
</p>
<p style="padding-left:1.2em">  지난 추경에 의회 제안 자율편성권을 통해서 경기연구원의 비정규직 처우개선에 관한 노력을 당부드렸죠?
</p>
<p><b>○ 경기연구원장 임해규 </b> 네.
</p>
<p><b>○ 임병택 위원 </b> 아까 보고자료에서도 계획을 수립했다라고 말씀하시는 것 같은데요. 그 관련자료 좀 준비되시면 저희 위원님들께 다 배부해 주시기 바라겠습니다. 
</p>
<p><b>○ 경기연구원장 임해규 </b> 네.
</p>
<p><b>○ 임병택 위원 </b> 질문에 들어갈게요. 작년 행정감사 기억을 더듬어 보시면 우리 경기연구원 박사님들께서 위탁연구를 통해서 다른 기관에 연구를 맡기고 그 연구 성과물을 본인의 성과물로 평가 받는 것에 대해서 제가 지적했습니다. 그래서 원장님 기억하실지 모르겠지만 경기연구원의 연구역량 성과에 비춰볼 때 앞으로 위탁연구는 최대한 지양하겠다라고 그렇게 말씀하셨는데요. 기억하시나요?
</p>
<p><b>○ 경기연구원장 임해규 </b> 네.
</p>
<p><b>○ 임병택 위원 </b> 정말 불가피한 경우를 빼고는 위탁연구를 지양하시겠다고, 우리 경기연구원 재정상황도 그렇고요. 또 우리 경기연구원 자존심도 있는데 그럼에도 불구하고 작년 행정감사 이후에 오히려 위탁연구가 더 많아졌어요. 행정감사 이후에 2014년 12월 달에 2,000만 원씩 두 곳, 올해는 네 곳 그래서 총 6건이나 위탁연구, 다른 연구기관에 연구물을 맡겼더라고요. 작년 11월 감사에서는 최대한 지양하겠다고 하셨던 원장님께서 도대체 그 전보다 더 많은 위탁을 맡기게 된 건 무슨 사유가 있으신 겁니까? 행감장에서 하신 말씀과 실정은 다르신 건가요?
</p>
<p><b>○ 경기연구원장 임해규 </b> 사실 저희들이 가급적 줄이고자 하는 것이 저희 방침인 것은 분명히 맞습니다. 불필요한 것은 하지 않겠다는 것인데요. 사실 저희들이 2014년도에 했던 것은 에너지 분야와 관련해서 산업 활성화 방안인데 이것은 우리 내부 연구진이 산업 활성화 방안까지 하기가 역량이 안 됐습니다. 그렇기 때문에 외부위탁을 준 것이었고요. 그리고 공동체 주거모델 발굴 연구 같은 경우도 우리가 전문성이 매우 떨어진다고 보았기 때문에 사실 이 분야는 저희들이 공동체 연구를 위해서 새로 확장해야 될 사업영역이었는데 아직까지 내부적으로는 준비가 안 돼서 외부에 위탁한 것입니다. 그리고 2015년도에도 4건이 있었는데요. 그것도 쭉 제목을 보시면 우선…….
</p>
<p><b>○ 임병택 위원 </b> 오케이. 알겠습니다. 
</p>
<p><b>○ 경기연구원장 임해규 </b> 독일 사례 연구 같은 경우는, 사실 독일에서 여러 가지 스타트업이라든지 이런 거에 대한 연구에 상당한 전문성이 있는 분이셨습니다, 이분이. 그래서 굉장히 괜찮겠다. 이거는 우리가 독일에 대해서 어떤 시범사례…….
</p>
<p><b>○ 임병택 위원 </b> 한국언론학회에서 독일과 무슨 관련이 있습니까? 한국언론학회에서 독일 사례 연구를 왜 수행합니까?
</p>
<p><b>○ 경기연구원장 임해규 </b> 여기 이 연구를 수행한 분이 언론학회 멤버였습니다. 그리고 많은, 여기는 주관 책임자만 나왔는데 제가 이름은 잠깐 기억을 못하겠는데 그분이 이 분야로 독일 연구를 그간에 계속해서 언론에도 많이 알려진 분이셨습니다. 그래서 그분에게 독일 연구를 한번 해 보면 어떻겠는가 하는 취지로 그분께는 연구를 위탁했습니다. 
</p>
<p style="padding-left:1.2em">  그리고 재난안전대책본부 관련해서는 사실 우리가 아직까지 재난관련 분야에 전문성을 가진 박사가 안 계셨고 우리한테는 중요한 연구과제였기 때문에 저희들이 불가피하게 위탁하게 되었고요. 전략산업 육성방안 연구도 사실 우리 내부에도 이 유사한 연구를 수차례 했습니다만 좀 외부적 관점에서 이런 데 전문화 된 분의 어떤 연구를 한번 받아보는 게 객관성을 높이겠다 싶어서 저희들이 연구 수행했고. 교통사고 골든타임 확보를 위한 응급구난시스템 방안도 우리 내부 전문성은 떨어진다고 보았습니다. 왜냐하면 이것이 굉장히 재난안전 쪽에는 상당히 연구를 해야 되는 분야라고 보았기 때문에 불가피하게 연구를 수행하게 되었습니다. 
</p>
<p><b>○ 임병택 위원 </b> 제가 충분히 원장님 하실 말씀, 소명하실 기회를 드렸습니다. 그건 원장님이 알아주십시오. 제가 중간에 말을 끊지 않았는데요. 그러나 납득이 가지는 않습니다. 작년 행정감사에서 분명히 이 문제가 지적됐고 위탁연구를 지양하시겠다고 하셨고 그럼에도 불구하고 1년 지난 시점에서는 오히려 2014년 1건보다 6건이나 행감 이후에 곧바로 하셨다는 부분에 대해서는 전 대단히 행정감사의 의미에 반하는 일을 하신 게 아닌가 싶고요. 그리고 또 연구과제와 업체들 간의 연관성 또한 투명하지 못하다는 의심을 떨칠 수가 없네요. 좋습니다. 이 부분은 제가 좀 더 연구자료를 검토해 보고 다시 추가질문하도록 하겠습니다. 행감 때 하셨던 약속이 지켜지는 경기연구원이 됐으면 좋겠습니다. 
</p>
<p style="padding-left:1.2em">  다음 질문은 올해 슈뢰더 전 총리를 경기연 예산을 통해서 초청하고 강의료를 지급하셨죠?
</p>
<p><b>○ 경기연구원장 임해규 </b> 네. 
</p>
<p><b>○ 임병택 위원 </b> 총액이 얼마입니까? 8,140만 원입니다. 8,140만 원. 강연료 5,500, 행사대행료 1,800, 일등석 왕복항공료의 50% 800만 원을 경기연구원이 부담을 해서 슈뢰더 전 총리가 경기도에 오게 됩니다. 의회연설을 했고요. 오찬까지 하고 가셨죠.
</p>
<p style="padding-left:1.2em">  우리 경기연구원의 예산집행 규정이 있죠? 그러니까 강연료를 지급하는 경기연 자체 규정이 있지 않습니까? 
</p>
<p><b>○ 경기연구원장 임해규 </b> 일반적으로 저희 연구원의 자문을 받는다거나 이렇게 할 때 저희들이 자문료 드리는 기준은 있습니다. 
</p>
<p><b>○ 임병택 위원 </b> 자문과 강연료에 대한 규정을 실무자께서는 찾으셔서 저에게 전달해 주시기 바랍니다. 최고가 얼마입니까? 
</p>
<p><b>○ 경기연구원장 임해규 </b> 우선 참석수당은 기조연설자의 경우는 40만 원이고요. 토론자의 경우는 15만 원 정도 됩니다. 
</p>
<p><b>○ 임병택 위원 </b> 그럼 슈뢰더 전 총리는 왜 5,500만 원이나 책정하고 부대비용 3,000만 원까지 합해서 하게 되셨습니까? 
</p>
<p><b>○ 경기연구원장 임해규 </b> 위원님 잘 아시겠지만 이것은 우리 연구원 내부의 연구자문을 한다거나 연구원 내부의 행사에 초대돼서 사회를 보거나 이런 상황은 아니었습니다. 그렇기 때문에 경기도와 협의해서 사실 저희들이 예산을 사용한 것이기 때문에 방금 위원님께서 말씀하신 우리 내부에 오셔서 하는 그런 기준하고는 다른 기준이라고 생각이 들고 저희들이 아마 이거를 대행하는 대행사와 협의하는데 사실 저희들이 협의에 약간 뭐랄까요, 적정하게…….
</p>
<p><b>○ 임병택 위원 </b> 경기도 집행부의 요청이 있었죠? 경기도 집행부의 요청. 
</p>
<p><b>○ 경기연구원장 임해규 </b> 네, 물론입니다.
</p>
<p><b>○ 임병택 위원 </b> 요청이 있었고 경기연구원에서는 힘없이 그 요청을 받아들일 수밖에 없었죠? 
</p>
<p><b>○ 경기연구원장 임해규 </b> 힘없는 건 아니고 저희들이 대외협력사업에 일정한 부분은 사실 경기도와 협의해서 하는 대외협력사업 예산이 있기 때문에 그런 과정에…….
</p>
<p><b>○ 임병택 위원 </b> 대외협력사업 예산이 아니죠. 이것은 이사회에, 2014년 이사회에 원장님이 보고하셨을 때는 국제세미나 하겠다, 국제디지털포럼 개최하겠다. 그래서 판교에 첨단산업단지를 국내외 저명한 학자들에게 알리겠다라고 하셔서 국제세미나 사업비 2억 원을 확보하신 거예요, 그죠?
</p>
<p><b>○ 경기연구원장 임해규 </b> 네.
</p>
<p><b>○ 임병택 위원 </b> 그러면 목이 정해져 있는 사업비였어요. 그런데 이사회 수정의결 거치셨습니까? 슈뢰더 총리 초청할 때? 안 거치셨죠?
</p>
<p><b>○ 경기연구원장 임해규 </b> 네, 거치지 못했습니다.
</p>
<p><b>○ 임병택 위원 </b> 개인적인 판단에 의해서 국제세미나 예산비용 2억 원을 전용하신 거죠? 아무런 근거도, 규정도 없이. 이것은 배임에 해당될 수도 있습니다. 저는 그렇게 판단합니다. 그러면 경기도 집행부가 지사께서 다음에 빌 클린턴 데려오겠다라고 했을 때 또 경기연이 똑같이 1억 원 지출해 주면서 비행기 값 주고 강연료 주면서 예산을 지출해야 되겠습니까? 어떻게 생각하세요?
</p>
<p><b>○ 경기연구원장 임해규 </b> 이번 이 사례를 저희들이 위원님 지적사항을 토대로 해서 경기도와 이런 문제에 대해서, 공동으로 하는 사업 분야에 대해서는 좀 더 엄격하게 관리하도록 하겠습니다. 
</p>
<p><b>○ 임병택 위원 </b> 엄격하셔야죠. 원장님일수록 더더욱 엄격하게 규정에 맞게 하셨어야죠. 오후에 추가질문하겠습니다. 
</p>
<p><b>○ 위원장 배수문 </b> 임병택 위원님 수고하셨습니다. 이어서 최지용 위원님 질의하여 주시기 바랍니다. 
</p>
<p><b>○ 최지용 위원 </b> 최지용 위원입니다. 아까 자료요구 했던 것은 아직 준비가 안 되셨나요? 이현호 위원님도 말씀하셨는데 장기표류 지방도 사업 타당성 재검토 순위는 용역이 언제까지죠, 기간이?
</p>
<p><b>○ 경기연구원장 임해규 </b> 다시 한 번 말씀…….
</p>
<p><b>○ 최지용 위원 </b> 장기표류 지방도 사업…….
</p>
<p><b>○ 경기연구원장 임해규 </b> 아, 지방도요. 
</p>
<p><b>○ 최지용 위원 </b> 타당성용역이 언제까지죠? 아직 안 끝났나요?
</p>
<p><b>○ 경기연구원장 임해규 </b> 1월 말쯤 되면 아마 결과보고가 될 것 같습니다. 
</p>
<p><b>○ 최지용 위원 </b> 내년도 1월 말?
</p>
<p><b>○ 경기연구원장 임해규 </b> 네, 그렇습니다.
</p>
<p><b>○ 최지용 위원 </b> 그럼 아직 진행 중이겠네요?
</p>
<p><b>○ 경기연구원장 임해규 </b> 진행 중입니다.
</p>
<p><b>○ 최지용 위원 </b> 화성에 설치되는 장사시설 용역보고서는 다 끝난 거죠?
</p>
<p><b>○ 경기연구원장 임해규 </b> 화성에.
</p>
<p><b>○ 최지용 위원 </b> 혹시 그 용역 안 하셨나요? 아까 자료요구 했었는데. 우리 연구원에서 용역을 안 했나요? 한 걸로 기억하는데. 어느 박사님이 하셨는지 잘 모르시나요?
</p>
<p style="padding-left:2.4em">    (경기연구원장, 내용 확인 중)
</p>
<p style="padding-left:1.2em">  광역 장사시설에 대해서 용역 안 하셨어요?
</p>
<p><b>○ 경기연구원장 임해규 </b> 지금은 우리 연구원에 계시지 않는데요. 그 광역 장사시설에 대한 용역을 한 바가 있습니다. 시기는 제가 정확하게 잘 모르겠습니다.
</p>
<p><b>○ 최지용 위원 </b> 아니, 그런데 박사님이 안 계시면 용역보고서가 남아있지 않은가요?
</p>
<p><b>○ 경기연구원장 임해규 </b> 지금 찾고 있습니다.
</p>
<p><b>○ 최지용 위원 </b> 아까 임두순 위원께서도 자료요청을 하셨는데, 자료 나오는 대로 제출 좀……. 
</p>
<p><b>○ 경기연구원장 임해규 </b> 그게 아마 올해 한 연구물이 아니고 지금 기간이 좀 지나간 거라서 자료를 찾고 있는 것 같습니다. 잠깐만 기다려 주시면 찾아서 말씀드리겠습니다.
</p>
<p><b>○ 최지용 위원 </b> 네, 알겠습니다. 질의하겠습니다. 북부연구센터 개원이 언제쯤 한 거죠?
</p>
<p><b>○ 경기연구원장 임해규 </b> 북부연구센터는 올해 개원했습니다.
</p>
<p><b>○ 최지용 위원 </b> 얼마 안 됐죠?
</p>
<p><b>○ 경기연구원장 임해규 </b> 네.
</p>
<p><b>○ 최지용 위원 </b> 그런데 북부연구센터를 꼭 개원했어야 하는 이유가 있습니까?
</p>
<p><b>○ 경기연구원장 임해규 </b> 지금 북부연구센터 개원하고 난 다음에 사실 북부 10개 시군에서는 저희들이 순회하면서 쭉 토론회를 하고 또 북부 10개년 계획도 수립 중에 있습니다만 북부지역이 굉장한 소외감을 정말 느끼고 있다는 걸 저도 가서 이렇게 많이 느꼈습니다, 같이 다니면서. 그런데 북부연구센터가 거기 들어섰다는 사실만으로도 북부지역의 많은 분들 굉장히 반기셨고요. 그리고…….
</p>
<p><b>○ 최지용 위원 </b> 연구원의 방문객이 연간 몇 명이나 방문합니까?
</p>
<p><b>○ 경기연구원장 임해규 </b> 저희 연구센터 말입니까?
</p>
<p><b>○ 최지용 위원 </b> 네. 아니, 북부에 뭐 생긴 지 얼마 안 됐으니까 우리 연구원에, 이곳에 방문하는 분들이 대략 몇 분이나 방문을 하시는지.
</p>
<p><b>○ 경기연구원장 임해규 </b> 아, 우리 본원의 방문객이요?
</p>
<p><b>○ 최지용 위원 </b> 네, 본원의.
</p>
<p><b>○ 경기연구원장 임해규 </b> 저희들이 방문객을 따로 숫자를 카운팅하거나 이러지는 않을 것 같은데요.
</p>
<p><b>○ 최지용 위원 </b> 민원인이나 이런 사람들이 많이 오지는 않을 거 아닙니까? 연구원인데.
</p>
<p><b>○ 경기연구원장 임해규 </b> 민원인들이 보통 오더라도 박사님들과 통화를 해서 오게 되거나 그렇지 저희들이 따로 접수창고가 있거나 이게 아니니까요.
</p>
<p><b>○ 최지용 위원 </b> 그러게요.
</p>
<p><b>○ 경기연구원장 임해규 </b> 숫자파악은 안 되고 있다고 보셔야 될 것 같습니다.
</p>
<p><b>○ 최지용 위원 </b> 우리 연구원에 자리가 부족해서 확장이전도 아니고 경쟁력이 그렇게 있나요? 출장연구를 하신다고 그러면 얼마든지 본원에서 출장도 달고 다 다닐 수가 있는데 꼭 북부다, 남부다 하면 동부지역에도 그러면 설치를 할 수 있잖아요, 센터를.
</p>
<p><b>○ 경기연구원장 임해규 </b> 그런데 이게…….
</p>
<p><b>○ 최지용 위원 </b> 현장감 있게 연구를 하신다 그러면.
</p>
<p><b>○ 경기연구원장 임해규 </b> 그런데 저는 꼭 그렇게 비교할 수는 없겠습니다만 사실 경기도청 북부청이 2000년도에 생긴 걸로 제가 알고 있습니다.
</p>
<p><b>○ 최지용 위원 </b> 압니다.
</p>
<p><b>○ 경기연구원장 임해규 </b> 그거 마찬가지로…….
</p>
<p><b>○ 최지용 위원 </b> 모든 기관이 다 균형에 맞게 이렇게 쪼개서 나갈 거냐 이거죠.
</p>
<p><b>○ 경기연구원장 임해규 </b> 꼭 그런 거는 아니지만 저희는 이제 또 북부지역의 소외감에 해당되는 연구를 밀도 있게 하려면…….
</p>
<p><b>○ 최지용 위원 </b> 다른 행정기구나 어떤 기관은 북부청으로 가는 게 맞습니다마는 연구기관까지 거기다 개원을 해서 나간다는 것은 그런 건 좀, 여기서 다른 용역은 해도 우리 연구원에서 거기에 대한 타당성 연구용역은 안 했었나요?
</p>
<p><b>○ 경기연구원장 임해규 </b> 네, 그 연구는…….
</p>
<p><b>○ 최지용 위원 </b> 아닌 건 아니었다고 발표를 해 주셨어야지 기구 늘어가는 것만 혹시 좋아서 하신 건지 그 이유를 알 수가 없습니다. 방문객이나 민원인들이 드나드는 것도 아니면서, 그렇지 않습니까? 지금 여기 자료에 연구용역 내용이 다 이렇게 나열이 돼 있습니다마는 이거 연구원들이 박사님들이 앉아서 그런 거 고민하고 연구하고 이러는데 어차피 출장은 나가서 현장에서 그 자료를 수집해야 연구가 되는 것 아니겠어요? 그런데 기구를 자꾸 벌여나가면서 별도의 연구원을 개설을 해 갖고 센터를 운영한다는 것은 좀 무리가 있지 않느냐, 좀 적절치 않은 걸로 본 위원은 생각을 합니다. 어떻게 생각하세요? 물론 북부에서 여러 가지 측면에서 소외감 느끼는 부분도 다 이해는 합니다만 연구원이 있다는 것 자체만으로도, 건물 보니까 미로같이 올라가서 연구원이 있는 건지 어느 상가에 상가가 하나 들어가 있는 건지 정도의 간판을 붙여 놓고 과연 우리 도민들이 얼마나 이해를 하겠느냐 이거죠. 여기 연구원도 그렇습니다. 연구원도 우리 도민들이 인식하는 차원이 얼마나 되는지 잘 모르고 이해를 할 수가 없습니다.
</p>
<p><b>○ 경기연구원장 임해규 </b> 그런데 분명한 거는 이제 저희들이 북부센터가 생김으로써 자기 역할과 임무가 분명해짐으로써 북부지역에 대한 연구의 양과 질이 높아질 거는 분명하다고 생각합니다. 그리고 그 정도 투자를 하는 것이 성과를 내는 데 적합한가 하는 효용성 문제는 논란이 될 수는 있겠습니다만 그것에 대한 평가는 좀 더 지켜보고 이후 해야 되지 않을까 싶습니다. 우선은 하는 걸로 결정이 돼서 지금 추진을 하고 있는 사항이기 때문에…….
</p>
<p><b>○ 최지용 위원 </b> 네, 알겠습니다. 다음 질문하겠습니다. 감사원이나 도 자체감사 지적내용인데요. 2014년도에 했나요? 이거 채용공고 규정에 위반되게 했다는 지적내용이 있는데, 지난해에. 법률에 위반되게 직원 특채라든지 비공개로 채용했다라는 지적이 있었습니다.
</p>
<p><b>○ 경기연구원장 임해규 </b> 다시 한 번 말씀해 주십시오.
</p>
<p><b>○ 최지용 위원 </b> 비공개 특별직원채용에 대해서 지적당한 바가 있죠? 지적 받으신.
</p>
<p><b>○ 경기연구원장 임해규 </b> 감사에서?
</p>
<p><b>○ 최지용 위원 </b> 네, 감사결과가. 조치결과를 다시 한 번 좀 말씀해 주시겠어요?
</p>
<p><b>○ 경기연구원장 임해규 </b> 그게 방금 실무자 이야기에 의하면 당시 저희 사무처가 있을 때, 그러니까 지금은 대외협력처로 바뀌었습니다만 그 사무처가 사무처장을 채용할 때 공개채용하지 않고 특채를 했다고 해서 감사원의 지적을 받은 사항입니다.
</p>
<p><b>○ 최지용 위원 </b> 특별한 한 자리만 그랬던 건가요, 아니면…….
</p>
<p><b>○ 경기연구원장 임해규 </b> 네, 그랬습니다. 그래서 딱 그 한 분에 대해서 지적이 있었고 그 이후로 직원채용 규칙을 개정해서 특별채용을 공개채용으로 의무화하는 걸로 바꾸었습니다.
</p>
<p><b>○ 최지용 위원 </b> 아, 그렇습니까? 자료요구한 것이 언제 나올는지 모르겠는데 그때 또 질의를 하기로 하고요. 이것 좀 우리 박사님들한테 혹시 기분 나쁠지 모르겠습니다만 한 가지 좀 여쭙겠습니다. 우리 박사님들의 검증은 어디서 하나요? 왜 이런, 우리가 실무감사 말고.
</p>
<p><b>○ 경기연구원장 임해규 </b> 우선은 박사님들이 하는 주요한 연구가 연구업무이기 때문에 우선 연구계획서 제출을 처음에 하면 연구계획 제출한 것에 대해서도 그냥 본인이 연구하겠다고 해서 연구하는 게 아니라 연구를 착수할 때도 저희들이 연구위원회에서 그 연구과제가 타당한지에 대한 검토를 하고 또 연구결과가 완성된 다음에 그 분야의 전문가, 외부전문가까지 모시고 와서 연구심의위원회를 열어서 그 연구물의 질적 평가를 합니다. 그리고 의뢰자가 있다면 그 의뢰자까지도 연구를 제대로 했는가에 대한 평가를 받습니다. 그러기 때문에 연구 질 관리를 통해서 박사들의 질을 일상적으로 체크하고 있다고 보셔야 됩니다.
</p>
<p><b>○ 최지용 위원 </b> 얼마 전에, 지난해도 그렇고 가끔 심심치 않게 터져 나오는, 매스컴에서 보면 특히 고위층, 정치인, 유명인들이 논문표절로 인해서 아주 망신을 당하고 그런 적을 여러 번 봤는데 우리 여기 박사님들이 그럴 일은 없으시겠지만 그런 검증을 하는, 국가에서 인정하는 기관에 검증을 하는 어떤 용역이나 이런 것을 의뢰해 본 적은 있습니까, 우리 원에서?
</p>
<p><b>○ 경기연구원장 임해규 </b> 아까도 제가 이현호 위원님 질의에 말씀드렸는데 저희들이 표절과 관련해서는 카피킬러라고 하는 중복성, 그러니까 다른 논문과의 중복성을 가리는 그런 프로그램을 가지고, 중복성이 유사성 체크죠. 유사성이 어느 정도인지를 저희들이 다 검토하고 있습니다. 그래서 저희들이 결재를 할 때 그 유사성이 10% 이상 되면 표절이라고 저희 내부적으로는 그런 기준을 가지고 지금 가려내는, 그러니까 검증…….
</p>
<p><b>○ 최지용 위원 </b> 그 유사성은 자체에서 검증을 하십니까?
</p>
<p><b>○ 경기연구원장 임해규 </b> 아닙니다. 그거는 유명한 프로그램입니다, 그게. 유사성을 체크하는, 매우 알려져 있는, 그래서 보편적으로 쓰고 있는 프로그램입니다.
</p>
<p><b>○ 최지용 위원 </b> 아니, 우리 원내에 기구가 따로 있는 겁니까, 아니면 외부기관에다가 의뢰를 하신 겁니까?
</p>
<p><b>○ 경기연구원장 임해규 </b> 그 프로그램을 저희들이 사용료를 주고, 한 번 사용할 때마다 일정한 돈을 주고 그 프로그램을 사용하는 겁니다. 돈을 들여서 하는 것이죠, 유사성 체크를.
</p>
<p><b>○ 최지용 위원 </b> 알겠습니다. 시간이 넘어서 마치겠습니다.
</p>
<p><b>○ 위원장 배수문 </b> 최지용 위원님 수고하셨습니다. 이재준 위원님 질의해 주시기 바랍니다.
</p>
<p><b>○ 이재준 위원 </b> 고양 출신 이재준 위원입니다. 경기연구원에 있는 직원분들이나 정원 외 직원분들이 다른 일을 해서 수익을 볼 수 있습니까, 없습니까?
</p>
<p><b>○ 경기연구원장 임해규 </b> 정원 외 분들은 저희들이 비상임연구원이라든지 이런 분들은 다른 수입을 가질 수 있는 걸로 알고 있습니다.
</p>
<p><b>○ 이재준 위원 </b> 수탁과제 연구결과를 보면 2013년도에 13억 그다음에 2014년도에 12억 그다음에 2015년도에 또 17억 이렇게 해서 인건비가 지출이 됐는데 보면 거의 대부분 95% 이상이 다 연구원 소속이에요. 그런데 이것이 전출금으로 경기연구원에 들어오지 않고 인건비로 편성을 해서 지출을 했어요. 이것이 어디로 갔습니까? 금액이, 돈이?
</p>
<p><b>○ 경기연구원장 임해규 </b> 그러니까 저희들이 수탁과제를 하게 되면 전출금으로 한 30% 약간 안 되는 돈을 저희들한테 수익으로 떼고 나머지는 예를 들어서 그 연구에 초빙박사들이 보통 붙는 경우가 많습니다. 그러면 초빙박사 인건비가 또 지출이 되고…….
</p>
<p><b>○ 이재준 위원 </b> 그러니까 초빙박사는 여기 참여자 명단에 보면 기타항목에 있는데 5%도 안 되고 나머지가 다 연구원 소속의 직원분들이 하신 거거든요.
</p>
<p><b>○ 경기연구원장 임해규 </b> 연구원들만, 우리 소속 연구원들로만 이루어진 수탁과제의 경우를 말씀하시는 거죠?
</p>
<p><b>○ 이재준 위원 </b> 그렇지 않은 경우도 있는데 어쨌든 뭐냐면, (자료를 들어 보이며) 이런 경우에 보면 이 부분은 연구원 소속이고 이건 아니에요. 그런데 여기에 인건비가 얼마가 되냐면 4,600만 원 책정이 됐는데 그럼 이분들 것 빼고 나머지는 이것이 어디로 갔냐는 거죠.
</p>
<p><b>○ 경기연구원장 임해규 </b> 그거는 뭐 연구하는 과정에 설문조사를 하게 되면 설문조사 비용도 쓰이고 또 수탁…….
</p>
<p><b>○ 이재준 위원 </b> 그거는 위탁관리비로 들어가고 직접경비로 들어가고 다 들어갑니다, 인건비가. 그러니까 이중으로 지출된 거 아니냐는 거예요.
</p>
<p><b>○ 경기연구원장 임해규 </b> 그렇지 않죠.
</p>
<p><b>○ 이재준 위원 </b> 그렇지 않으면 이거 인건비 책정을 했을 때는 우리가 수탁과제로서 수탁을 하는 사람들한테 “이만큼이 경비가 들어갑니다.”라고 해서 과제를 받는데 그다음에 받고 나서는 이것이 전출금으로, 그러니까 여기 연구원들이 참여한 연구실적에 대한, 인건비 부분에 대한 것은 전출금으로 들어오든지 어떤 계정이 있어야지 지금 이것만 보면 전부 다 개별적으로 지출된 걸로 되어 있어요. 이것에 대해서 정확하게 좀 답변해 주시죠.
</p>
<p><b>○ 경기연구원장 임해규 </b> 그건 좀 실무자가 답변을 올리겠습니다.
</p>
<p><b>○ 재정지원부장 박인숙 </b> 재정지원부장 박인숙입니다. 수탁과제가 저희가 산출내역서에 보면 인건비로 책정되어 있는 부분은 내부 박사님 같은 경우 결산 시에 전출금으로 해서 일반회계 그다음 사업비로 다 편성이 되고 있습니다. 운영비로써 편성이 되고 있습니다.
</p>
<p><b>○ 이재준 위원 </b> 이런 거 보면요. 2015년도 과천시 철도시설에 한 건데 총액이 1억 2,400이에요. 거기에 4,070만 원이 인건비로 돼 있고 이 4,070만의 인건비를 받으신 모든 분들이 연구원 소속 직원들이에요. 그런데 전출금이 4,200만 원이에요. 그러면 안 맞는 거죠. 직접경비 쓰고, 그러니까 이게 세세한 부분이 아니라 전체적인 큰 틀에서 보면 연구원들이 연구에 참여해서 우리가 수탁할 때는 인건비를 상정을 해요, 계산을. 그러면 그것이 다 전출금으로 들어오든지 그렇지 않으면 그것이 다른 계정으로 들어가서 그것이 공적자금으로 쓰여져야 된다는 거죠. 어차피 지금 연구원들한테 인건비로 또 지급이 되진 않잖아요, 여기서 급여로만 나가지. 그렇다면 이 돈이 어디 가 있냐는 거예요, 지금 문제는.
</p>
<p><b>○ 재정지원부장 박인숙 </b> 위원님, 그거는 지당하신 말씀이신데요. 저희가 수탁과제를 받아올 때 인건비를 책정하는 부분 중에서도 직접경비 부분으로 저희가 내부적으로 사용하는 경우가 있습니다. 사업비가 학술용역 자체가 목이 한정이 돼 있기 때문에 그 외에도 나가야 될, 연구에 필요한 부분이 있기 때문에 그런 부분에 대해서는 저희가 별도로 책정을 하고 인건비는 내부 박사님들이 다 하시기 때문에 저희가 전출금을 조금 남기고 그다음에 사업비에 더 많이 투자를 하는 거거든요.
</p>
<p><b>○ 이재준 위원 </b> 그렇지가 않고요. 이게 지금 보면 직접경비로 나간 것도 있고 인건비로 나간 거 있고 위탁과제별로 나간 게 있고 전출금으로 다 세부항목이 정해져 있어요, 모든 항목이. 그래서 지금 2015년도에 보면 17억이 인건비로 나갔어요. 그런데 거의 다가 95% 이상이 우리 직원분들이 하신 거예요, 연구를. 그러면 이 돈이 어디 가 있냐는 거예요. 전출금은 15억으로 따로 잡혀있는 거예요, 이 인건비 말고 별도로.
</p>
<p><b>○ 재정지원부장 박인숙 </b> 죄송한데 지금 몇 번, 2015년도?
</p>
<p><b>○ 이재준 위원 </b> 2015년도. 이거 시간 가니까 저기해서 다시 한 번 파악해 보시고 이따 따로 보고 좀 해 주세요. 
</p>
<p><b>○ 재정지원부장 박인숙 </b> 네, 알겠습니다.
</p>
<p><b>○ 이재준 위원 </b> 그다음에 원장님, 주거복지 문제하고 굿모닝버스하고 이층버스에 대해 질문할 건데 이거 우리 경기연구원이 연구한 과제예요. 이거에 대해서 질문을 좀 드리겠습니다. 굿모닝버스라는 것이 사실상 되게 좋은 제도지만 저는 환상적이라고 생각을 해요. 왜냐면 ‘모두 다 앉아서 갈 수 있다.’ 그 대전제가 성립을 하냐? 못 하거든요. 왜 광역버스만 앉아서 가야 된다는 전제를 세운 거죠?
</p>
<p><b>○ 경기연구원장 임해규 </b> 제가 알기로는 광역버스가 보통 고속도로를 달리기 때문에 고속도로는 입석이 금지돼 있지 않습니까? 그렇기 때문에 우선적으로 광역버스만이라도 입석을 하지 않아서 안전을 확보하자 이런 걸로 알고 있습니다.
</p>
<p><b>○ 이재준 위원 </b> 그러면 그냥 금지하면 돼요. 25년 동안 실효성이 하나도 없는 것을 광역버스를 타고 다니는 사람들이, 좌석에 앉지 못하는 사람이 7,800명이니까 그 사람을 앉게 해 줘야 되고 그러니까 이거 차량을 390대를 늘려야 되고 요금을 또 거기에 대해서 400원을 올려줘야 되고 이런 식의 논리를 폈다는 거예요. 그런데 지금 아시다시피 입석금지를 하지도 않고 단속도 안 하고. 지금 좌석으로 다니지 않고 전부 입석으로 다니고 있어요. 존경하는 남경필 지사님도 거기에 해당, 동생분이 하시는 차도 입석으로 다니고 있습니다. 그래서 주민들은 400원이 오른 거예요. 원래는 좌석버스가 250원이 올랐습니다. 150원을 추가로 올리는 이런 것들을 한 거예요. 그러고 거기의 전제가 뭐냐면 내부적으로 다니는 사람들은 왜 돈을 더 내야 돼요? 잘못된 전제를 가지고 이걸 해서 결국은 실패했고 정부도 이제 입석대체버스에 대한 지원금도 중단을 했고 우리 도도 지원금을 중단을 했고. 이 엉망이 된 것에 대해서 책임을 통감하셔야 되지 않아요?
</p>
<p style="padding-left:1.2em">  그러니까 제가 전에 한번 여기 와서 토론회 때 참여해서 얘기를 했을 때 전문가들은 합리적이고 그리고 객관적이어야 된다는 거예요. 그것을 보장해 달라는 것이 저는 원장님한테 지난 행감 때도 부탁을 드렸던 말씀이거든요. 그래서 객관적인 연구를 해야지 아닌 거, 정책이라고 해서 잘못된 거, 틀린 것을 갖고서 정책이라고 해 가지고 그것을 그대로 보고가 나가면 그 결과에 따라서 집행부는 집행을 하는 거죠. 그분들은 논리적으로 경기연구원에서 결과가 이렇게 나왔기 때문에 한다라고 그러지만 우선적으로 그것이 아무런 효과가 없다는 것이 증명이 되는 것이 뭐냐면 버스중앙차로라면 서울에서, 서울에서 모든 교통체증이 일어나요. 우리 고양시만 해도 이미 행주대교서부터 밀려요. 어떻게 들어갈 거냐는 거지. 아무리 좌석버스를 많이 해도 안 되는 거예요. 그럼 교통체계가 잘못된 거고 그 부분에 대해서 다른 수요를 해야지 광역버스만 늘린다라고 해 가지고, 390대를 늘려서 이거 가능한 거냐는 거죠. 아닌 거죠. 그리고 출근시간 말고 나머지 시간 텅텅 비어 있는데 그 부분에 대해서 손실은 누가 부담해야 될 거고 어떻게 해야 되는 대책이 없어요, 보고서에. 엉터리 보고서 아닙니까? 제가 볼 때는 엉터리 보고서예요. 답변 좀 해 보시죠.
</p>
<p><b>○ 경기연구원장 임해규 </b> 시내버스든 시외버스든 광역버스든 사실 첨두시에 전부 다 앉아 가도록 한다는 게 사실 쉬운 일이 아니죠.
</p>
<p><b>○ 이재준 위원 </b> 불가능하죠.
</p>
<p><b>○ 경기연구원장 임해규 </b> 굉장히 어려운 일이라고 봅니다. 그거는 이제 우리나라 교통시스템의 현재 상태의 교통수요로 보자면 시스템의 혁신을 통해서 가능할까…….
</p>
<p><b>○ 이재준 위원 </b> 우리나라 교통시스템이 기형적인 거고 거기에 또 하나 우리가 잘못한 게 이층버스예요. 이층버스가 출근시간 한 번만 풀로 타요. 나머지 시간에 그거 다 뭐 할 겁니까? 나머지 시간에는 지금도 버스가 30% 정도가 차고지에 서 있습니다. 운행 안 합니다. 그럼 이층버스, 일반버스도 남는데 이층버스 운행하겠습니까? 그러면 하루에 두 번 뛰고, 출근시간 때 한 번, 퇴근시간 때 한 번 뛰고서 이걸 갖다 손실금을 다 어떻게 메꿔줄 거예요. 이런 엉터리 보고서가 어떻게 나와요. 
</p>
<p><b>○ 경기연구원장 임해규 </b> 지금은 제가 그 보고서 내용을 자세하게, 완벽하게 알지 못합니다만 사실 지금 투입되고 있거나 앞으로 약간 증차하려고 하는 노선이 첨두시가 아닐 때도 이층버스 활용도가 어느 정도 되는 혼잡한 구간에 투입하는 걸로 설계돼 있는 걸로 알고 있습니다. 그래서 위원님께서 방금 말씀하신 것처럼 첨두시에는 그냥 세워놓고 놀 수밖에 없다고 하는 거는 아닌 걸로 알고 있습니다, 일단 그 작은 부분만 놓고 보자면. 그런데 위원님께서 전체…….
</p>
<p><b>○ 이재준 위원 </b> 저는 그렇게 생각합니다. 이런 버스들은 뭐냐 하면 서울시내 한복판이나, 사실상 우리나라 교통제도는 바뀌어야 되는 것이 뭐냐 하면 서울시내를 다 무료화하고 옆에서 가는 것들이 가주고 서울시내에서 도는 무료화ㆍ공용화 버스 같은 경우는 이층버스 해야 되는 거예요. 거기는 수시로 올라타고 그러니까. 이런 식으로 가야 되는 것이지. 이게 장거리에서 장거리 실어 나르는데 한 번만 필요한 것을 갖다가 이층버스로 하면 과연 그것이 수요가 맞냐. 지금은 수요가 맞는다고 얘기할지 모르지만 그렇지 않습니다. 그리고 이거에 대해서 MOU도 체결 안 했고 손실금에 대해서도 안 했어요. 지금 이것이 운영이 되면 낮 시간 때 사람이 없을 경우에 그 손실금을 다 우리가 메꿔줘야 되는데 그거에 대해서도 보증한 게 없어요. 그렇지만 업자들이 차 세우고 난리치면 해 줄 거 아닙니까? 이런 논리적 근거를 할 때 면밀하게 하셔야 되는 것이고 그리고 저희가 전문가는 아니지만 안 된다라고 그렇게 얘기하면 그럼 도입시기를 늦춘다든지 예산반영을 늦춘다든지 해야 되는데 그것도 아니고 결국은 지난번에도 사고결과가 나왔냐고 했더니 하나도 안 나왔어요, 하나도 없대. 그런데 엎어져 가지고 교통체증이 몇 시간 동안 정체됐던 거 있었어요. 그러니까 전부 다 거짓말만 시키고 통계자료 안 내놓고 이런단 말이에요. 지금이라도 한번 보세요. 우리 경기도가 어떤 정책주도력이 없어서 그런지 몰라도 하루에 15시간 이상 뛴 버스대수를 산출 못해요. 하루에 한 번만 뛰어도 가동률로 친단 말이에요. 이런 모순이 어디 있어요. 그러면 아침에 예비차가 한 번만 투입돼도 가동률로 산정돼서 진짜 서 있는 차 말고는 전부 다 가동하고 있는 걸로 이렇게 나온단 말이에요. 그것이 아니라 최소한 하루에 13시간, 14시간 이렇게 뛰는 차들만 가동률을 뽑아서 얼마만큼 운행하는지를 봐야 남아도는 게 나오거든요. 그러니까 그런 걸 데이터를 갖고 2층버스건 뭐건 해야 되는 것이지. 그리고 여기 수요자 만족도조사에서도 결국 광역버스를 늘려달라는 것이지. 그런데 그분들은 그러려면 택시 타고 다녀야 되는 거예요. 자기만 앉아서 가는데, 자기만 편하게 광역버스 늘려달라고 그러면 그다음 시간은 어떻게 할 거냐는 거예요. 그러니까 그것이 합리적으로 조정이 안 되는 교통정책이기 때문에 이 보고서가 면밀하게 수정이 돼야 된다는 겁니다.
</p>
<p><b>○ 경기연구원장 임해규 </b> 일단 연구자가 늘 현장에 살고 이 제도가 사실 도입되는 과정에 제가 알기로는 경기연구원이 이층버스 도입에 대해서, 광역버스ㆍ이층버스 도입에 대해서 상당히 오래 전부터 문제를 제기하고 연구를 해 오고 지금 그 제도가 도입되는 과정에서도 계속 붙어서 개선점도 찾아내고 이러는 걸로 알고 있습니다. 따라서 위원님 질의나 이런 문제제기에 충실하게 답변하려면 저는 연구책임을 했던 분이 충분하게 답변하고 또 위원님 지적 중에서 상당 부분 받아들일 만한 부분도 있다고 보기 때문에……. 
</p>
<p><b>○ 이재준 위원 </b> 이따 더 추가로 하고요. 뭐냐 하면 M버스도 고속도로 다닙니다. 그리고 M버스는 입석금지가 되어 있잖아요. 그러면 광역버스를 늘릴 것이 아니라 광역버스를 M버스화하면 되는 거예요. 그런데 이것이 아니고 환승할인 내지는 정부보조를 받는 광역버스를 늘리자고 해 가지고 정책이 이렇게 혼선이 온 거죠. 전부 M버스화하면 돼요. 그래서 정부지원 다 끊어버리고 자기 나름대로 가라고 하면 되는 거죠. 그런 문제가 있습니다. 하여간 이따 추가질의 할게요. 이상 질의 마치겠습니다. 
</p>
<p><b>○ 위원장 배수문 </b> 이재준 위원님 수고하셨습니다. 참고로 말씀드리면 경기도에서 버스지원금, 버스손실보전금이 2,800억 이상 지원되고 있습니다. 연구를 어떻게 하느냐에 따라서 그 금액의 낭비를 막을 수도 있고 그 금액을 더 불릴 수도 있는 거죠. 그래서 연구자들은 더 도민의 혈세를 지키는 방법도 같이 검토해 줘야 된다는 거죠. 단순히 정책이 이거 있으니까 이게 활성화될 수 있는 방안만 연구해라 이건 아니라는 거죠. 그래서 학자적 양심이 필요한 거고요. 도민의 혈세를 지키고자 하는 간절한 마음들이 필요하다 그렇게 생각합니다. 동의하시죠?
</p>
<p><b>○ 경기연구원장 임해규 </b> 물론입니다.
</p>
<p><b>○ 위원장 배수문 </b> 되게 중요한 얘기를 이재준 위원님이 지적해 주셨는데 이건 지난 행감에서도 지적됐던 부분이고요. 특히 학자적 양심으로 우리 GRI 박사들이 해 주지 않으시면 누가 해 주겠습니까? 개인 연구단체에서 그거 하겠습니까? 그렇지 않죠. 여기는 맞춤형 연구를 하게 되는 개인 연구단체가 아니지 않습니까? 정책의 실효성에 있어서 보다 더 객관적으로, 보다 더 장단점을 면밀히 분석할 필요가 있다 이렇게 생각합니다. 
</p>
<p style="padding-left:1.2em">  이어서 장동일 위원님 질의해 주시기 바랍니다. 
</p>
<p><b>○ 장동일 위원 </b> 원장님 수고하십니다. 우리 연구원의 홍보담당하시는 분이 누구시죠? 
</p>
<p><b>○ 경기연구원장 임해규 </b> 대외협력처 팀장.
</p>
<p><b>○ 장동일 위원 </b> 원장님이 그냥, 이거는 제가 좀 경기연구원의 여러 가지 상황을 체크하기 위해서 모 사이트를 들어갔더니 3월 달에 경기연구원으로 명칭이 바뀌었는데 경기연구원을 쳤더니 그대로 경기개발연구원으로 뜹니다.
</p>
<p><b>○ 경기연구원장 임해규 </b> 저희들이 명칭이 정식으로 바뀐 것은…….
</p>
<p><b>○ 장동일 위원 </b> 그렇다 하더라도, 그다음에 11월 8일 날 올라온 내용인데 경기개발연구원 대표 홍순영. 이걸 자세히 들어가 보니까 안에는 임해규로 바뀌어 있어요. 이거 설명 좀 해 주시죠. 제가 내용을 잘 몰라 가지고. 
</p>
<p><b>○ 경기연구원장 임해규 </b> 아마 제대로 고치지 않은 것이겠죠. 저도 지금 자세히 봐야 답변드릴 수 있을 것 같은데요. 
</p>
<p><b>○ 장동일 위원 </b> 한번 들어가 보세요. 지금 당장.
</p>
<p style="padding-left:2.4em">    (경기연구원장, 자료 확인 중)
</p>
<p style="padding-left:1.2em">  그대로 출력한 거예요.
</p>
<p><b>○ 경기연구원장 임해규 </b> 저희들도 이래서 굉장히 어려움을 겪고 있는 것인데요. 이게 저희들 홈피가 아니고 검색을 하면, 포털에서 검색을 하면 저희들이 경기도에 있는 언론기관이나 이런 데는 경기개발연구원하면 전화해 가지고 제발 이름 바꿨으니까 바꿔 달라 이렇게 계속 재촉하는데 포털에, 사실 우리가 접촉이 안 되는 기관에서 저희들 것을 띄워 올리는 경우는 사실 저희들이 일일이 고쳐달라 이렇게 연락하기가 쉽지 않기 때문에…….
</p>
<p><b>○ 장동일 위원 </b> 메인 사이트도 수정이 안 되어 있다 이 말이죠.
</p>
<p><b>○ 경기연구원장 임해규 </b> 네, 그렇습니다. 그러니까 이게 저희들이 올리는 게 아니기 때문에요.
</p>
<p><b>○ 장동일 위원 </b> 요청을 하는데, 우리 개인들도 일정기간 내용을 하면 거기에서 답이 와서 절차를 거쳐서 하는데, 한 20일에서 한 달 정도면 다 정리해 주는데 왜 그런 거를 중요 사이트에서, 해명이 조금 궁색해 보입니다.
</p>
<p><b>○ 경기연구원장 임해규 </b> 저희들이 사실 말하면 포털을 보고 늘 저희들 관련된 것을 검색은 하고 있습니다만 충분히 안 된 것 같습니다. 
</p>
<p><b>○ 장동일 위원 </b> 그것은 하여튼 참고하시고. 제가 당혹스러워서, 그걸 보니까 그런 내용이 있어서 그건 별도로 생각을……. 
</p>
<p><b>○ 경기연구원장 임해규 </b> 네, 그러겠습니다. 적극적으로 고쳐서 빨리 시정되도록 하겠습니다. 
</p>
<p><b>○ 장동일 위원 </b> 최근에 경기도 산하 10개 기관에 공채를 했는데 경쟁률이 86 대 1인가 나왔대요. 80명인가 60명인가를 채용하는데. 그래서 청년실업이 그만큼 문제고 사회적으로 커다란 이슈인데 제가 그런 말씀을 드리는 이유는 우리 경기연구원에서 연구과제로 시간선택제 취업 또는 직장이나 산하기관 같은 데서 아주 획기적으로 한번 이런 걸 시행해 볼 수 있는 그런 연구를 해 볼 수는 없나요?
</p>
<p><b>○ 경기연구원장 임해규 </b> 위원님이 연구의뢰를 해 주시면 저희들이 물론 연구할 수 있습니다. 그런데 저희들도 지금 청년취업에 대해서는 다양한 각도에서 연구를 수행해 오고 있거든요. 그래서 의뢰해 주시면 저희들이 연구해 보도록 하겠습니다. 
</p>
<p><b>○ 장동일 위원 </b> 그것은 요즘 잡셰어링이다, 일자리 나누기다 여러 가지, 하도 일자리 문제가 사회적으로 문제가 되다 보니까 여러 가지 방안들을 찾고 있는데 우리가 그런 부분들은 어떤 그 틀에, 프레임 갇혀서, 기존의 프레임에 갇혀서 생각할 게 아니라 정말 획기적으로 한번 이런 부분을 생각해서 일자리를 나눴으면 좋겠다는 생각을 제가 요즘 기업현장에 다니면서 너무 많이 느끼는 거거든요. 그래서 그것을 한번 말씀드린 거고.
</p>
<p style="padding-left:1.2em">  그다음에 지금 세월호 관련된 내용을 연구과제로 선택해서 연구하고 있습니까, 아직 연구가 진행 중인가요?
</p>
<p><b>○ 경기연구원장 임해규 </b> 우선 저희들이 정책연구가 아니고 현안브리프라고 하는 형식으로 세월호 가족들의 삶에 대해서는 간단한 거는 하나 써서 공유했는데 저희들 내부연구가 아니라 세월호 쪽에서 아카이브 활동을 하고 있는 연구자들에게 위탁연구를 하나 맡겼습니다. 저희들이 아무래도 수행하는 데는 여러 가지 어려움이 있는 것 같아서 위탁연구를 맡기고 저희들이 내부적으로는 앞으로 향후 계획은 세월호의 희생자 가족들이 거기서 일종의 공동체를 이루고, 고잔 그 지역에서 이루고 사시기 때문에 그 지역에서 어떤 공동체 차원에서 한번 접근해 보는 연구 이런 것들은 해 보면 어떨까 하는 그런 생각은 가지고 있습니다. 
</p>
<p><b>○ 장동일 위원 </b> 이게 안산시, 국가, 경기도 이렇게 여러 가지 내용들이 얽히고설켜서 경기도가 단독으로 뭔가 이슈를 선점해서 연구한다는 것은 사실 그 경계가 모호할 수 있을 것 같아요. 그래서 여기 이슈에 올라와 있어서 이 부분은 제가 지역이 그쪽이라고 해서가 아니라 워낙 지금 사회적으로 민감한 문제고. 실제로 지금 그쪽 사회에 내재돼 있는 문제들이 너무나 크고 해서 저희들도 뭘 어떻게 해야 될지 모르는 상황에 있어서 이 부분에 대해서 연구가 진행되고, 여기 올라와 있어서 제가 여쭤보는 것이고요. 그러니까 특별한 것은 없네요, 지금 연구원 차원에서는. 
</p>
<p><b>○ 경기연구원장 임해규 </b> 저희 문제의식은 사실 세월호 희생자들이 주로 경기도 안산지역에 있고 그리고 아직 국가차원에서 타결되지 않아서 원활하게 마무리는 안 되어 있습니다만 적어도 그분들이 그분들만의 삶이 아니라 우리 사회에 미치는 영향이 워낙 크기 때문에 우리 연구원에서도 뭔가 경기도가 어떻게 하면 도움이 될까 또는 경기도가 무슨 일을 해야 할까 이런 것들은 저희들이 연구가 필요하다고 생각이 들고. 그런데 그 지역에 대한 연구는 사실 희생자 가족분들하고의 접촉이나 신뢰감 없이는 연구가 불가능하거든요. 그래서 우리가 그분들하고 신뢰형성을 연구과제라는 것을 통해서 형성하는, 장기적으로 형성하는 게 필요하지 않겠느냐 하는 판단에 따라서 저희들이 부분적으로 연결점을 찾고 있다 이렇게 보시면 될 것 같습니다. 
</p>
<p><b>○ 장동일 위원 </b> 그 부분은 복잡하고 예민한 문제여서 나중에 한번 같이 생각해 보도록 하겠습니다. 
</p>
<p style="padding-left:1.2em">  그다음에 제가 몇 가지 질의 내용을 뽑으려고 보니까 공교롭게 제 지역 다문화와 관련해서, 저희 지역 같은 경우는 지역 문제를 말씀드린 게 아니고 실제로 얘기하다 보니까 저희는 인구의 13%를 넘어가고 있습니다. 그런데 전혀 정책적으로 뒷받침이 안 돼서 여러 가지 문제가 되고 있는데 지금 여기에 대해서 연구한 부분은 어떻게 혹시 핵심적으로 말씀해 줄 만한 게 있습니까? 지금 왜 이런 질의를 제가 드리냐 하면 인구의 12%, 13%를 넘어가는데 여전히 열악하고 뭔가 제도나 이런 것들이 뒷받침이 안 돼서 사회적으로, 지역적으로 문제가 되고 있는 이런 것 때문에 제가 관심을 갖고 질의드리는데 또 여기 올라와 있어요, 연구대상에. 그래서 경기연구원에서는 어떻게 핵심적으로 이거를 접근하고 있는지, 연구하고 있는지 한번 좀. 자료를 내가 이따 받아보겠습니다, 연구물은.
</p>
<p><b>○ 경기연구원장 임해규 </b> 아직 확연한 연구결과가 나와 있지 않습니다만 저희들이 이 문제 관련해서는 인구학박사 한 명 채용됐습니다, 올해. 그리고 다문화 분야, 철학박사도 한 분 됐고. 그래서 철학박사와 인구학박사가 다문화라고 하는 주제로 방금 위원님 말씀하신 것처럼 인구가 급감하고 있기 때문에 급감하게 되면 결국은 이민정책이 우리에게 중요한 정책이 될 수밖에 없고 그러면 다문화는 우리 사회에 보편적인 현상이 될 가능성도 매우 높아지기 때문에 그렇게 될 경우에 어떠한 사회적인 여러 문제가 발생할 것인지 이런 것들 선진국의 사례검토도 하고 그래서 그 다문화를 다문화와 이민정책 이런 것들과 함께해서 우리의 매우 주요한 연구주제로 삼아야 되겠다라고 하는 데까지는 저희들이 논의가 됐고 그래서 그 연구를 담당할 박사가 지정돼 있습니다. 그래서 저희들이 단계적으로 방금 말씀드린 이런 다양한 문제들에 대해서 앞으로 연구를 할 계획을 가지고 있습니다. 그래서 내년도에는 아마 한두 개의 다문화 관련 혹은 이민정책 관련된 그간에 연구되거나 시행된 정책을 총체적으로 리뷰하는 그러면서 나름대로 시사점을 얻는 그런 연구를 내년쯤에는 할 것으로 생각이 됩니다.
</p>
<p><b>○ 장동일 위원 </b> 이민이나 이런 부분들에 대해서 인구정책은 중앙정부와 경계가 그런 부분이 있는데 제가 요청드리고 싶은 것은 수원이나 안산, 평택지역에 다문화 외국인들이 많이 거주하고 있잖아요. 그런 부분들을 지역별로 별도의 우리만의 그런 것들을 따로 떼서 연구를 해서 거기에 적용할 수 있는, 참고할 수 있는 그런 것은 가능하지 않을까요?
</p>
<p><b>○ 경기연구원장 임해규 </b> 물론 그런 연구를 하기 위해서 방금 말씀드린 것처럼 전체적인 흐름에 대한 리뷰를 저희들이 해야 되기 때문에 그리고 중앙정부의 정책이 꼭 다 옳은 것은 아니기 때문에 또 거기에 대한 검토도 하고 또 거기에 맞춰서 우리 지역에서 나타나고 있는, 왜냐하면 다문화가 예전에는 농촌다문화가 대세였다면 지금은 도시다문화로 넘어왔거든요. 그렇기 때문에 도시다문화가 앞으로 주요한 측면이 될 것이기 때문에 그리고 경기도가 집중될 것이기 때문에 저희들이 앞으로 그 분야는 심도 있게 연구해야 된다고 보고 있습니다. 
</p>
<p><b>○ 장동일 위원 </b> 시간이 돼서 이따 다시 드리겠습니다. 이상입니다.
</p>
<p><b>○ 위원장 배수문 </b> 장동일 위원님 수고하셨습니다. 제가 자료요청을 했습니다. 경기북부연구센터 운영현황에 대해서. 보셨죠?
</p>
<p><b>○ 경기연구원장 임해규 </b> 네.
</p>
<p><b>○ 위원장 배수문 </b> 보셨어요? 올해 2월 달에 설치돼서 지금…….
</p>
<p><b>○ 경기연구원장 임해규 </b> 자료요청, 북부연구센터 운영 현황.
</p>
<p><b>○ 위원장 배수문 </b> 네. 내용을 다 보셨죠?
</p>
<p><b>○ 경기연구원장 임해규 </b> 네.
</p>
<p><b>○ 위원장 배수문 </b> 대답이 안 보신 것 같은 느낌으로 답을 하시네.
</p>
<p><b>○ 경기연구원장 임해규 </b> 아닙니다. 봤습니다. 
</p>
<p><b>○ 위원장 배수문 </b> 거기 운영개선 사항해 가지고 나와 있는 내용 그다음 뒤에 산하기관 관련해 가지고 협력사항 그다음에 2016년도 계획 빼고 장기 센터발전계획은 아예 없네요, 아직. 그리고 이것과 관련해서 원장님이 북부센터 몇 번 다녀오셨습니까? 정기적으로 북부센터 가시는 경우가 있으세요?
</p>
<p><b>○ 경기연구원장 임해규 </b> 정례적으로 회의를 하러 가거나 그런 경우는 없습니다. 
</p>
<p><b>○ 위원장 배수문 </b> 한 달에 몇 번 정도 가시죠?
</p>
<p><b>○ 경기연구원장 임해규 </b> 그간에 서너 번 간 것 같습니다. 
</p>
<p><b>○ 위원장 배수문 </b> 서너 번이요?
</p>
<p><b>○ 경기연구원장 임해규 </b> 네.
</p>
<p><b>○ 위원장 배수문 </b> 지금 거기 박사님은 여섯 분 계시죠?
</p>
<p><b>○ 경기연구원장 임해규 </b> 네.
</p>
<p><b>○ 위원장 배수문 </b> 제가 보기에 장점은 만들어낸 장점 같고요. 단점이 생각보다 많습니다. 북부발전이라는 이름하에 많은 부서들을 북부센터를 두고 있는데 그런 것들에 대한 종합적인, 북부센터를 두었을 때 효율성이 얼마만큼 있는지에 대한 고민이 있습니다. 무슨 얘기냐 하면 그쪽에서 직원들이 출퇴근하면서 느끼는 고충들 이런 것들이 다 녹아있음에도 불구하고 더 많은 연구물을 만들 수 있는지에 대한 고민을 하셔야 될 때다 이렇게 생각을 합니다. 그게 꼭 필요하다면, 도청에서 요청해서 간 걸로 알고 있는데 과감히 요청하셔서 다시 원위치 시킬 필요가 있다면 원위치가 필요하다고 봅니다. 그거를 단순히 협조 차원에서 만들어지고 진행되는 것들은 장기적으로 그렇게 도움 되는 부분이 없다 전 그렇게 판단하거든요. 자체 판단할 필요가 있고요. 그다음에 거기서 근무했던 직원들 보니까 워크숍 한 번 안 열었네요. 그리고 센터장님하고 직원 단합대회 한 번 한 적 없고요. 물론 개별적으로 업무상 회의하겠죠.
</p>
<p><b>○ 경기연구원장 임해규 </b> 그러니까 단합대회 같은 형식으로 같이 모여서는 여러 차례, 저도 참석해서 여러 차례 했습니다.
</p>
<p><b>○ 위원장 배수문 </b> 해 봤습니까?
</p>
<p><b>○ 경기연구원장 임해규 </b> 네.
</p>
<p><b>○ 위원장 배수문 </b> 워크숍을 안 열었다는 얘기인가요, 그러면?
</p>
<p><b>○ 경기연구원장 임해규 </b> 워크숍을 했습니다.
</p>
<p><b>○ 위원장 배수문 </b> 자료에는 그렇게 안 한 걸로 돼 있어서. 자체 워크숍이 없는 걸로 돼 있어서 제가 말씀드렸습니다.
</p>
<p><b>○ 경기연구원장 임해규 </b> 했습니다.
</p>
<p><b>○ 위원장 배수문 </b> 제가 운영현황을 좀 보자고 한 가장 큰 이유는 북부지역이 좀 어렵다고 해서 북부지역 직원들 숙소문제도 우리들이 지난번 의회 자율편성예산에서 일부를 그런 명목으로 하면서 지원을 하자고 했던 경우가 있습니다. 그렇죠?
</p>
<p><b>○ 경기연구원장 임해규 </b> 네.
</p>
<p><b>○ 위원장 배수문 </b> 일단 하는 데까지 운영을 해 보자라는 거에는 동의를 하는데 그럼에도 불구하고 억지로 끌고 가는 느낌이 계속 있다면 이거는 재고할 필요가 있지 않나 이렇게 생각을 합니다.
</p>
<p><b>○ 경기연구원장 임해규 </b> 그러니까 처음에 그건 미처 생각하지 못했거나 혹은 거기서 생활을 하면서 제기되는 추가요구에 대해서 저희들이 위원님들께 사실 요청을 한 것이고 또 그거에 대해서 적절한 방안을 지금 찾고 있고 이렇게 하고 있습니다. 그러니까 그거는 어떻게 보면 거기에서, 연구자들은 거기가 자기 직장이고 또 살아가야 되는 장소이기 때문에 하나하나 그것이 갖춰지는 과정이 아닌가 생각이 듭니다. 정착되는 과정으로 이렇게 봐 주시면 좋을 것 같고 또 그 과정에 위원님들 도와주셔서 굉장히 도움이 됐고요. 그런데 말씀하신 것처럼 궁극적으로는 북부연구센터가 설치됨으로 해서 과연 그 연구, 우리 전체 연구의 질과 양에 효용성이 있는가 이 점에 대한 판단이 제일 중요한 판단일 것 같습니다. 그런데 이번에 북부연구 10개년 계획을 세우면서는 상당히 호응도 좋았고 그 지역의 시군에서도 호응이 좋았고 또 박사님들도 북부를 훨씬 깊이 있게 이해할 수 있는 계기가 되었기 때문에 우리 북부에 나가 있는 박사님들만이 아니라 이쪽에서, 본원에 있는 우리 박사님들도 서로가 같이 협력연구를 하면서 훨씬 우리가 시군에 대한 이해도가 특히 북부에 대한 이해도가 높아졌다는 것이 다들 평가인 것 같습니다. 그래서 지금은 제가 보기에는 그렇게 나쁘지 않은, 이런 설치가 나쁘지 않은 걸로 이해하고 있습니다만 또 위원장님과 최지용 간사님 계속 문제를 제기하고 계시기 때문에 우리 북부연구센터에서 나가 있는 박사들과, 1년 좀 안 됐습니다만 그간의 성과나 문제점이나 이거를 한 번쯤 허심탄회하게 논의를 해 보는 그런 시간을 갖도록 하겠습니다.
</p>
<p><b>○ 위원장 배수문 </b> 자체 워크숍 개최하시고 그 건에 대해서 결과 있으시면 보고해 주시기 바랍니다.
</p>
<p><b>○ 경기연구원장 임해규 </b> 그러겠습니다.
</p>
<p><b>○ 위원장 배수문 </b> 이어서 우리 안혜영 위원님 질의해 주시기 바랍니다.
</p>
<p><b>○ 안혜영 위원 </b> 수원 출신 안혜영 위원입니다. 먼저 우리 원장님, 이번에 경기도 종합감사 받으셨죠?
</p>
<p><b>○ 경기연구원장 임해규 </b> 네, 그렇습니다.
</p>
<p><b>○ 안혜영 위원 </b> 10월 26일부터 11월 4일까지 받았고 아직 조치결과에 대한 내용들은 정리가 안 돼 있는 걸로 알고 있습니다. 그렇죠?
</p>
<p><b>○ 경기연구원장 임해규 </b> 네, 그렇습니다.
</p>
<p><b>○ 안혜영 위원 </b> 지금 주요 지적목록을 보니까 한 11개 정도가 되네요?
</p>
<p><b>○ 경기연구원장 임해규 </b> 네.
</p>
<p><b>○ 안혜영 위원 </b> 공용차량에 관련된 것, 직원 가족수당 지급 부적정, 전신전화가입권  관리 부적정, 장애인 법정고용의무 소홀, 국내출장여비 정산 부적정, 수탁사업용역 특별회계처리 부적정, 초빙연구원 채용 부적정, 비상임정책연구위원 위촉 부적정, 공동연구과제 수행방식 부적정, 근무지 무단이탈 및 연구용역ㆍ외부강의 등 대외활동 미승인, 설문응답 답례용 상품권 수불관리 소홀 등 11개 정도가 지적이 돼 있는데 이 내용에 대한 것들은 한 2~3개월 정도면 다 정리가 돼서 나오죠, 감사관실에서?
</p>
<p><b>○ 경기연구원장 임해규 </b> 네, 아마 그럴 걸로 생각합니다.
</p>
<p><b>○ 안혜영 위원 </b> 그런데 이제 마지막에 보면 근무지 무단이탈 및 연구용역ㆍ외부강의 등 대외활동 미승인 같은 경우는 우리 연구원의 박사님들이나 연구원들이 우리 경기연구원의 활동 외에 다른 강의라든가 아니면 회의라든가 이런 위원회 일에 참석하고 그런 과정들을 말씀하시는 거죠?
</p>
<p><b>○ 경기연구원장 임해규 </b> 그렇습니다.
</p>
<p><b>○ 안혜영 위원 </b> 그런 것들이 좀 많이 있었나요?
</p>
<p><b>○ 경기연구원장 임해규 </b> 네, 일상적으로 많이 하는 활동입니다. 
</p>
<p><b>○ 안혜영 위원 </b> 일상적으로 그런 활동들을 많이 하죠. 경기연구원에 계시는 분들이 능력 인정받고 계시니까 외부에 나가서 활동하시는 건 저는 나쁘다고 보지는 않는데 대외활동에 대한 미승인이기 때문에 문제가 되는 거죠?
</p>
<p><b>○ 경기연구원장 임해규 </b> 네.
</p>
<p><b>○ 안혜영 위원 </b> 원장님한테 원래 승인을 받고 나가셔야 되는 거잖아요?
</p>
<p><b>○ 경기연구원장 임해규 </b> 그런데 대체로 다, 그러니까 이 지적이 일반적으로 그렇다는 뜻은 아니고요. 이런 건이 한두 건 있는 것에 대해서 지적을 받았다…….
</p>
<p><b>○ 안혜영 위원 </b> 한두 건 정도였나요?
</p>
<p><b>○ 경기연구원장 임해규 </b> 제가 정확하게는 잘 모르겠습니다만 대부분 다…….
</p>
<p><b>○ 안혜영 위원 </b> 제가 자료를 달라고 했으니까 자료를 보고 얘기를 좀 하겠습니다. 그 건에 대해서도 좀 있었는데 관용차량을 제가 봤습니다. 경기연구원의 정책에 대한 얘기들을 좀 해야 되는데 기본적인 것 한두 개 짚고 가자면 관용차량을 모하비를 타고 계시죠?
</p>
<p><b>○ 경기연구원장 임해규 </b> 그렇습니다.
</p>
<p><b>○ 안혜영 위원 </b> 3,000㏄로 되어 있습니다.
</p>
<p><b>○ 경기연구원장 임해규 </b> 네.
</p>
<p><b>○ 안혜영 위원 </b> 차량에 대한 얘기를 하고 싶은 것은 아닌데 지침이 내려와 있죠, 경기도에서? 기관장 전용차량의 지나친 대형화, 고급화 지양하고 국가 공용차량 배기량 기준 및 경기도 공용차량 관리규칙을 참고해서 2,700㏄ 이하로 구입하게끔 되어 있습니다. 구입한 건 아니고 렌탈하고 계시다고 들었습니다.
</p>
<p><b>○ 경기연구원장 임해규 </b> 그렇습니다. 리스…….
</p>
<p><b>○ 안혜영 위원 </b> 렌탈을 하셨는데 2,700㏄ 이하로 임차를 하게끔 돼 있는데 3,000㏄를 임차를 하셨습니다. 특별한 이유가 있으신가요?
</p>
<p><b>○ 경기연구원장 임해규 </b> 특별한 이유는 아니고요. RV차량을 타고 있는데요. 대체로 제가 그 차를 개인적으로 탈 때도 그 차를, 그 유형의 차를 타서 새로, 그전에는 제네시스였습니다. 제네시스를 바꾸면서 RV차량으로 바꿨습니다.
</p>
<p><b>○ 안혜영 위원 </b> 내부규정을 어겨가면서 그렇게 하실 필요가 있나요, 개인차량이 아닌데? 잘못되신 거죠? 지금 여기 규정, 도에서 기존에 특별한 지시사항이 없었는지 모르겠습니다. 그런데 지시사항이 내려와 있어요. 이런 것들을 좀 지양하자고 15년도에 일부러 예산편성액 기준을 또 통보해서 내려 보냈는데 굳이 그걸 어겨가면서 하실 필요는 없었을 것 같고. 이 지침에 따르면 장관급ㆍ도지사가 3,300㏄, 차관급ㆍ부지사가 2,800㏄급 수준으로 타게끔 규정을 내려 보냈습니다. 앞으로 관용차량도 우리 연구원에서도 운영을 하시잖아요. 지금부터 관리를 하시기 때문에 이런 부분들은 면밀히 지켜주시면서 하셨으면 좋겠습니다.
</p>
<p><b>○ 경기연구원장 임해규 </b> 네, 알겠습니다.
</p>
<p><b>○ 안혜영 위원 </b> 우리 초빙연구원, 비상임연구원들이 연구하셨던 기록을 좀 봤습니다. 2015년도 오늘 기준으로 제가 자료를 받아봤는데 한 17건 정도 수탁한 것과 일반회계 13명이 있습니다. 기존에 보면 대부분 한 70만 원에서 100만 원선으로 가급, 나급 구분이 되어서 규정에 맞게끔 지급이 된 것 같습니다. 그런데 보니까 160만 원 기준으로 받으신 분이 두 분이 계세요. 그런데 규정에 보면 이 정도 금액을 받을 수 있는 규정은 없는 것 같아서, 특별한 사유가 있나요?
</p>
<p><b>○ 경기연구원장 임해규 </b> 전부 다 규정을 지켜서 한 거고요. 그런데 기준금액이 있고 또 원장이 적절하게 조정할 수 있는 유동적인 폭이 있습니다. 그래서 그 폭에 기초해서 전부 다 책정을 했습니다.
</p>
<p><b>○ 안혜영 위원 </b> 그래서 제가 규정을 좀 받아봤습니다. 초빙연구원, 규정을 여러 가지를 만들어 놓으셨더라고요. 운영규칙, 운영규정, 위원회 등 운영규칙 여러 가지가 있어서 제가 좀 살펴봤는데 그 안에 지금 말씀하셨던 부분이 있어요. 2-7 초빙연구원, 비상임연구원 등 운영규칙. 연구원분들이 대부분 근무를 하고 계시는 거라서 11쪽 보수를 보니까 비상임연구위원의 수당에 대해서 별도 지침이 있습니다. “비상임연구위원 대상자의 전문성과 사회적 저명도에 따라서 150% 범위 내에서 조정하여 지급할 수 있다.”라고 돼 있는데 해석이 잘못됐다고 봐요. 여기 보면 지금 이분들이 급으로 봤을 때 80만 원을 받으셔야 되는 분이라고 하시더라고요. 그러면 200%를 받으셨거든요? 80만 원인데 160만 원씩을 받으셨으면 200% 받으신 거잖아요, 아닌가요? 단순하게 제가 여쭤보는 거예요.
</p>
<p><b>○ 경기연구원장 임해규 </b> 아니, 그러니까…….
</p>
<p><b>○ 안혜영 위원 </b> 제 계산이 잘못됐나요? 80만 원인데 160만 원씩 받았으면 200%가 아니냐는 거죠.
</p>
<p><b>○ 경기연구원장 임해규 </b> 네, 맞습니다. 그거 200% 받은 겁니다.
</p>
<p><b>○ 안혜영 위원 </b> 맞죠?
</p>
<p><b>○ 경기연구원장 임해규 </b> 그런데 80만 원이 기준이 아니었을 걸로 생각이 드는데요.
</p>
<p><b>○ 안혜영 위원 </b> 제가 지금 따로 물어본 거예요.
</p>
<p><b>○ 경기연구원장 임해규 </b> 아, 그래요?
</p>
<p><b>○ 안혜영 위원 </b> 80만 원을 받으시는 분이라고 확인하고 지금 제가 질의하는 겁니다.
</p>
<p style="padding-left:2.4em">    (관계직원, 경기연구원장에게 개별설명)
</p>
<p style="padding-left:1.2em">  이 두 분은, 김 박사님 두 분은 연구위원 가급이라고 되어 있어요. 한 분은 박사시고 한 분은 학사시고. 물론 평균적인 사회지위를 인정하셔서 그 박사나 학사에 다르겠지만 80만 원을 기준으로 하셨다고 되어 있고요. 그런데 200%를 받으셨어요. 여기 사회적 저명도에 따라서 하시더라도, 재량껏 하시더라도 150% 범위 내에서 조정하게끔 되어 있습니다.
</p>
<p><b>○ 경기연구원장 임해규 </b> 방금 실무자 얘기를 잠깐 들었는데요. 그 150%가 기본적으로 주는 거에 추가하여 150%라고…….
</p>
<p><b>○ 안혜영 위원 </b> 아니요.
</p>
<p><b>○ 경기연구원장 임해규 </b> 이해를 하는데 저도…….
</p>
<p><b>○ 안혜영 위원 </b> 그거는 지금 제가, 이거 자료 하나 카피해서 드리시고요. “150% 범위 내에서 조정하여 지급할 수 있다.” 해석을 한번 해 보시죠.
</p>
<p><b>○ 경기연구원장 임해규 </b> 다툼의 여지는 있지만…….
</p>
<p><b>○ 안혜영 위원 </b> 인건비이기 때문에 제가 말씀드리는 거예요.
</p>
<p><b>○ 경기연구원장 임해규 </b> 다툼의 여지가 있지만 위원님 해석이 맞을 것 같습니다.
</p>
<p><b>○ 안혜영 위원 </b> 아니, 다툼의 여지는 없죠. 그거는 생각을 그렇게 하신 거고 150% 범위 내라는 건, 내외가 아니잖아요. 150% 내라고 하는 것은 그 안에서 지급하라는 거죠.
</p>
<p><b>○ 경기연구원장 임해규 </b> 네, 물론 그런데 그 150%가 원래 지급하기로 하던 기준금 플러스 150%로…….
</p>
<p><b>○ 안혜영 위원 </b> 그 플러스라는 단어가 여기 어디 있습니까? 추가지급이라는 말이 없습니다. 만약에 원장님이 그렇게 주고 싶은 마음이 있으시면 규정을 바꾸셔야죠. 운영규칙 바꾸십시오. 그렇게 해서 지급을 하셔야죠.
</p>
<p><b>○ 경기연구원장 임해규 </b> 아니, 그런데……. 네. 알겠습니다.
</p>
<p><b>○ 안혜영 위원 </b> 우리는 연구원분들이 다 비상임연구원이든 모든 연구원분들이 이 기준에 따라서 지급을 받고 계시잖아요.
</p>
<p><b>○ 경기연구원장 임해규 </b> 맞습니다.
</p>
<p><b>○ 안혜영 위원 </b> 인건비 책정도 그렇게 하고 계시죠?
</p>
<p><b>○ 경기연구원장 임해규 </b> 네.
</p>
<p><b>○ 안혜영 위원 </b> 그렇다라고 하면 내용이 잘못됐다고 하시고 만약에 그렇게 수정하고 싶으시면 규칙을 바꾸셔야죠. 바꾸신 다음에 그렇게 지급하십시오. 아시겠죠?
</p>
<p><b>○ 경기연구원장 임해규 </b> 알겠습니다. 검토하겠습니다. 
</p>
<p><b>○ 안혜영 위원 </b> 그리고 이 잘못된 부분에 대해서는 수정을 좀 하십시오.
</p>
<p><b>○ 경기연구원장 임해규 </b> 검토하겠습니다.
</p>
<p><b>○ 안혜영 위원 </b> 인건비 잘못 나간 것에 대해서 수정을 좀 하셔야 될 것 같습니다.
</p>
<p><b>○ 경기연구원장 임해규 </b> 이것은 제가 좀 한번 검토를 받아보겠습니다.
</p>
<p><b>○ 안혜영 위원 </b> 검토받고 말씀해 주시고요.
</p>
<p><b>○ 경기연구원장 임해규 </b> 그러겠습니다.
</p>
<p><b>○ 안혜영 위원 </b> 저희들이 자료를 만들고 규정, 규칙을 만드는 것은 그 외에 별도규정을 따로 두셨기 때문에 150%로 재량으로 주신 거잖아요.
</p>
<p><b>○ 경기연구원장 임해규 </b> 네, 그렇습니다.
</p>
<p><b>○ 안혜영 위원 </b> 재량을 더 넘어서 하시는 건 아닌 거죠.
</p>
<p><b>○ 경기연구원장 임해규 </b> 물론입니다.
</p>
<p><b>○ 안혜영 위원 </b> 그렇게 해 주시고……. 아무것도 아닌 걸로 시간이 다 갔습니다. 차후에 준비를 좀 해 주시기 바랍니다. 새로 여러 분이, 우리 원장님이 오시고 여러 분이 퇴사를 하시고 또 신규채용이 되셨습니다. 아까 발표를 하실 때도 미학이라든가 아니면 철학 여러 가지 부분에 대해서 인사채용을 다시 하셨는데 그 부분에 대해서 제가 궁금한 점이 있어서 추가질의 때 질의를 하겠습니다. 이상 마치겠습니다.
</p>
<p><b>○ 위원장 배수문 </b> 안혜영 위원님 수고하셨습니다. 임두순 위원님 질의하여 주시기 바랍니다.
</p>
<p><b>○ 임두순 위원 </b> 남양주 출신 임두순입니다. 먼저 항상 좋은 자료 만들어 가지고 보내 주셔서 잘 보고 있습니다. 인용에도 많은 도움이 되고요. 또 이 자리를 빌려서 감사하다는 말씀드리고요, 연구원분들한테. 저는 원장님이 답하기 어려우면 용역책임자가 좀 답을 하셔도 괜찮을 것 같아요. 뭐냐면 장기표류 지방도 사업 타당성 재검토 및 우선순위 결정연구에, 사실 이게 여기서 얘기할 내용도 있고 또 도청 집행부에다 할 얘기도 있는데 저는 이게 우선순위 결정연구를 연구라는 제목으로 경기연구원에서 하는 게 과연 맞는지 좀 문제제기를 하고 싶어요. 왜냐하면 이게 장기표류 지방도사업 타당성 재검토. 이게 주목적이 뭐라고 생각하세요, 원장님? 이 내용 잘 알고 계시죠?
</p>
<p><b>○ 경기연구원장 임해규 </b> 제가 소상히는 모릅니다만, 직접연구자는 아니기 때문에. 그런데 아까도…….
</p>
<p><b>○ 임두순 위원 </b> 그러면 소상히 아시는 분께서…….
</p>
<p><b>○ 경기연구원장 임해규 </b> 아까도 제가 다른 위원님 질의 때 잠깐 말씀드렸는데요. 이게 경기도 재정이 좀 풍부할 때 제가 그때 듣기로는 상당히 많은 재원을 취약한 시군도를 좀 경기도의 재정으로 지방도로 승격시켜서 사업을 해 달라고 하는 시군의 요구가 상당히 많았던 시절이 있었고 그것을 경기도가 수용을 해서 지방도로 이렇게 승격시켜서 계획을 쭉 한 걸로 아는데…….
</p>
<p><b>○ 임두순 위원 </b> 원장님 그런 말씀은 아까 하셔 가지고 저도 들었고요.
</p>
<p><b>○ 경기연구원장 임해규 </b> 그 얘기입니다.
</p>
<p><b>○ 임두순 위원 </b> 이게 주목적이 저거예요. 돈이 없으니까 구조조정 해 가지고 일몰사업 선정하려고 하는 거예요, 이게 지금. 저기 우리 김동성 센터장님, 이거 하나만. 그냥 앉은 자리에서 대답하세요. 이게 26개가 맞는 거예요, 24개가 맞는 거예요?
</p>
<p><b>○ 북부연구센터장 김동성 </b> 위원님, 실은 이쪽 분야가 제가 맡은 파트가 아니라서요, 지우석 교통연구실장이 답변할 수 있도록 하겠습니다.
</p>
<p><b>○ 임두순 위원 </b> 그러실래요? 잠깐 나오세요.
</p>
<p><b>○ 휴먼교통연구실장 지우석 </b> 안녕하십니까? 휴먼교통실장 지우석입니다.
</p>
<p><b>○ 임두순 위원 </b> 지금 우선순위 사업결정연구 이게 24개가 맞는 거예요, 26개가 맞는 거예요?
</p>
<p><b>○ 휴먼교통연구실장 지우석 </b> 26개입니다.
</p>
<p><b>○ 임두순 위원 </b> 26개가 맞아요?
</p>
<p><b>○ 휴먼교통연구실장 지우석 </b> 네.
</p>
<p><b>○ 임두순 위원 </b> 그런데 처음에 24개였었잖아요.
</p>
<p><b>○ 휴먼교통연구실장 지우석 </b> 처음에 24개였었는데요, 시군을 순회하면서…….
</p>
<p><b>○ 임두순 위원 </b> 그런데 2개는 언제 추가된 거예요?
</p>
<p><b>○ 휴먼교통연구실장 지우석 </b> 저희가 전 시군을 다 방문을 했고요. 시군에 방문했을 때 실무자들하고 이야기를 하면서 조정이 됐습니다.
</p>
<p><b>○ 임두순 위원 </b> 지금 경기연구원에서 이거 주도하고 있는 거죠?
</p>
<p><b>○ 휴먼교통연구실장 지우석 </b> 네.
</p>
<p><b>○ 임두순 위원 </b> 어쨌든 일몰사업 선정하는 게, 우선순위 선정도 선정이지만 일몰사업, 그러니까 여기서 사업을 좀 없애려고 하는 게 돈이 없으니까 목적이라고 생각하는데 지금 줄 세우기 한다는 생각이 좀 들어요. 왜냐하면 이게 사실은 이 사업이 처음에 24개였다가 26개가 됐는데 각 시군에서 이거 중요하지 않은 사업이 없어요. 중요하지 않았으면 그 당시에 사업 올리지도 않았죠, 이게. 그 지역에서 필요하고 그만큼 중요하기 때문에 또 이거 우리 지역에 정말 필요한 사업이기 때문에 올렸고 그다음에 해당 실국에서, 이게 지금 보상은 작게는 3%에서 많이 된 데는 90% 이상 된 데도 있어요. 잘 아시죠? 보상이.
</p>
<p><b>○ 휴먼교통연구실장 지우석 </b> 네.
</p>
<p><b>○ 임두순 위원 </b> 사업비 같은 경우는 작게는 100억이나 100억 미만에서 많게는 2,000억대까지 있는데 그런데 이게 사업이 올라왔을 때는, 지금 주도하시니까 잘 아시겠지만 각 지자체에서 중요하지 않은 도로가 있겠어요, 어디? 다 그만큼 필요하니까 올렸고 그 당시에 또 실국에서 강압을 한 거고. 그러니까 이미 보상도 나가고 또 계획도 나간 건데 이제 와서 돈 없다고 경기연구원에서, 아마 여기서 몇 번 회의를 하신 걸로 알고 있어요. 맞죠, 여기서?
</p>
<p><b>○ 휴먼교통연구실장 지우석 </b> 네.
</p>
<p><b>○ 임두순 위원 </b> 그래서 시군의 실국장들이 올라와 가지고 자기네 것 먼저 우선순위에 넣어 달라 이런 푸시(Push)가 있었던 걸로 아는데 그런데 경기연구원에서 이걸 순위를 결정해 주는 게 옳은 건지 저는 모르겠어요. 왜냐하면 근거제시만 해 주고 이 결정은 당연히 이제, 예를 들어 결정을 해야 된다 그러면 집행부에서 결정을 해야지 되는데 마치 지금 이게 경기연구원에서 결정하는 걸로 소문이 다 나 있어요, 이게 우선순위를. 잘 아시잖아요, 시군 다니면서 간담회도 하고 식사도 하고 그분들한테 의견청취도 하셨잖아요. 이거는 저는 경기연구원에서 이런 역할을 하는 건 온당치 않다고 생각을 해요. 그러니까 어떤 근거자료만 제시해 주는 게 좋지 경기연구원에서 시군 실국장들 불러다 놓고 우선순위 결정하는 데 이 내용을 가지고 결정을 하겠다고 얘기를 하고 있는데 저는 이거 정말 중요한 사업, 안 중요한 사업이 없고 또 이게 어떻게 명분을 만들고 있다는, 그러니까 일몰사업 선정하려고 우리가 돈이 없으니까 확 자르고 그다음에 이게 지금, 내가 하나 지우석 연구원님한테 물어볼게요. 이게 예를 들어서 우선사업이 선정이 되면 가장 빨리 예산투입이 될 수 있는 시기가 언제라고 생각하세요? 얘기 들으셨으니까 아실 거 아니에요.
</p>
<p><b>○ 휴먼교통연구실장 지우석 </b> 2017년부터 시작되는 걸로 알고 있습니다.
</p>
<p><b>○ 임두순 위원 </b> 그렇죠. 내후년이잖아요, 2017년.
</p>
<p><b>○ 휴먼교통연구실장 지우석 </b> 네.
</p>
<p><b>○ 임두순 위원 </b> 그런데 지금 이게 작게는 3년에서 많게는 10년 이상 계속 끌던 사업인데 그런데 여기서 우선순위 몇 개 선정하시려고 하는 거예요? 4개예요, 3개예요?
</p>
<p><b>○ 휴먼교통연구실장 지우석 </b> 지금 처음에 일몰에 대해서 언급을 하셨잖아요. 당초 과제가 제기될 때는 일몰을 고려하고 있었습니다. 그런데 도 실무담당자하고 시군을 돌아다녀 보면서 현장에서 느끼는 그런, 지금 말씀하신 대로 필요성이라든가 절박감이라든가 이런 얘기들을 들으면서 일몰에 대해서는 지금 재고를 하는 쪽으로 내부적으로는 의논이 되고 있고요. 그렇지만 저희는 경제성이라든가 정책적 중요성이라든가 또 보상률이라든가 이런 걸 고려해서 26개 사업에 대해서 우선순위를 정하는 건…….
</p>
<p><b>○ 임두순 위원 </b> 아니, 그러니까 몇 개를 우선 선정하려는 거예요?
</p>
<p><b>○ 휴먼교통연구실장 지우석 </b> 저희는 몇 개다라고 선정을 안 하는 거죠.
</p>
<p><b>○ 임두순 위원 </b> 4개 아니에요, 4개? 그러니까 2017년에 우선 예산투입 하는 게.
</p>
<p><b>○ 휴먼교통연구실장 지우석 </b> 아닙니다. 숫자가 정해진 게 아니고요. 처음에는 지금 말씀하신 대로 몇 개다 하고 정하려고 했습니다. 그런데 지금 말씀드린 대로 중간에…….
</p>
<p><b>○ 임두순 위원 </b> 시간 가니까 간단하게 단문으로 해 주세요.
</p>
<p><b>○ 휴먼교통연구실장 지우석 </b> 네, A, B, C 이렇게…….
</p>
<p><b>○ 임두순 위원 </b> 등급을 정해 놓는다?
</p>
<p><b>○ 휴먼교통연구실장 지우석 </b> 군집화하기로 했습니다.
</p>
<p><b>○ 임두순 위원 </b> 자, 그럼 봐 봐요. 지금 일몰을 지양하신다고 말씀하셨잖아요.
</p>
<p><b>○ 휴먼교통연구실장 지우석 </b> 내부적으로 검토 중입니다.
</p>
<p><b>○ 임두순 위원 </b> 내용을 검토하는데 A, B, C, D 이렇게 등급 나눠 가지고 2017년도에 아마 1개가 될지 2개가 될지 3개가 될지도 모르는 거 아니에요. 투입되는데 그럼 D 되면 일몰이나 마찬가지인데 이렇게 묶어놓을 필요가 뭐 있어요, 그렇잖아요. 그거 2017년도에 첫 예산 투입되는데, 지금 그렇게 알고 계신데 저도 건설국장한테 그렇게 얘기 들었어요. 들었는데 그러면 후순위에 밀려있는 것은 10년을 기다려야 될지 20년을 기다려야 될지 모르는 상황 아니에요. 이거는 도청 행감 때 문제제기하겠지만 이런 식으로 정하는 건 문제가 있다고 생각해요. 왜냐하면 이거는 어떤 시간을 끌든지 명분을 만들려고, 지금 이게 8개월간 용역으로 알고 있는데, 한 3억 들여 가지고 하는 용역이. 지자체에서는 아까 말씀드린 대로 3년에서 길게는 10년 이상 기다렸던 사업들인데 이제 와서 돈 없다고 우선순위 선정한다 뭐 한다 해 가지고 시간은 시간대로 끌고 그다음에 첫 예산 투입은, 지난 추경 때 건설국장은 나한테 내년에 세운다고 얘기 했었어요. 그런데 이번에 다시 물어보니까 2017년도에 세운다는 얘기예요, 예산을. 그러니까 이것은 계속 명분만 만들어 가지고 시간만 끄는 거야. 시군에서는 지금 목마른데. 그래서 이런 식으로 선정하는 건 저는 온당치 않다고 생각하고 경기연구원에서 객관적인 지표나 근거자료만 제시해 주고 그 결정이나 이런 것은 도청이나 해당 지자체에 의논해 가지고 어떻게 할 것이냐, 또 의회도 있고. 이렇게 논의해 가지고 정하는 게 맞다고 생각해요.
</p>
<p><b>○ 휴먼교통연구실장 지우석 </b> 맞습니다. 최종적인 사업결정은 집행부에서 하는 거고요. 저희는 말씀드린 여러 가지 지표를 통해서…….
</p>
<p><b>○ 임두순 위원 </b> 그런데 지금 이렇게 주도하고 있는 내용을 보면 시군에서도 그렇게 알고 있어요. 경기연구원에서 결정한다고 여기 와서 얘기 좀 해 달라고 심지어 저한테 그런 얘기도 해요.
</p>
<p><b>○ 휴먼교통연구실장 지우석 </b> 아닙니다. 개수를 결정하거나 이런 건 아니고요.
</p>
<p><b>○ 임두순 위원 </b> 어쨌든 우선순위 결정하는 데…….
</p>
<p><b>○ 휴먼교통연구실장 지우석 </b> 우선순위를 결정하는 건 맞습니다.
</p>
<p><b>○ 임두순 위원 </b> 경기연구원의 의견이 제일 중요한 거 아니에요, 이 내용이. 그러니까 이게 결정된다고 그래도 2017년에 첫 예산 투입되는데 이렇게 해 가지고 시간만 더 끌고 저는 이거는 방법이, 이미 용역비는 투입됐지만. 이 방법은 전에도 문제제기를 했는데 이런 식으로 정하는 건 저는 옳지 않다고 생각해요. 만일 이렇게 된다면 3개, 4개 빼놓고 나머지는 10년, 20년 기다려야 돼요. 안 하는 거나 마찬가지예요, 이거는. 그러니까 이거는 지양해야 된다고 생각하고 제가 박사님한테 뭐라고 하는 게 아니고 이거를 경기연구원의 연구를 통해 가지고 명분 만들고 시간을 끄는 도청 집행부에 대한 질타를 하는 거예요. 시간이 다 됐으니까 여기까지 질의하겠습니다. 
</p>
<p><b>○ 위원장 배수문 </b> 임두순 위원님 수고하셨습니다. 김호겸 위원님 질의하여 주시기 바랍니다.
</p>
<p><b>○ 김호겸 위원 </b> 수원 출신 김호겸 위원입니다. 임해규 원장님과 우리 연구진 여러분들, 직원 여러분들 우리 도민을 위한 좋은 정책들을 만들어줘서 감사의 말씀을 드리고요. 본 위원이 지난 행감에서도 지적하고 주문했던 사항 같은데 비교적 우리 사회적약자로 구분되는 장애인과 농업인들에 대한 연구가 거의 많지 않은 것 같아요. 왜 관심을 안 가져서 그러시나요, 아니면 연구진들이 없어서 그러나요?
</p>
<p><b>○ 경기연구원장 임해규 </b> 아닙니다. 우선 농업 관련된 연구는 저희들이 꾸준히 하고 있는 편이고요. 그리고 장애인 관련 연구는 사실 경기복지재단에서 주로 하는 연구기 때문에 저희들이 그 영역은…….
</p>
<p><b>○ 김호겸 위원 </b> 그렇습니다. 지금 농업 관련은 잘 아시겠습니다만 민선6기 들어와서 상당히 많이 정책이 후퇴되고 있습니다, 실질적으로. 농업 관련 예산도 경기도 전체의 1.3% 정도, 전국 지자체 평균 15%에 훨씬 못 미치죠. 그런 정책인데 알다시피 농업은 우리 먹거리 생명산업인데 지금 농업인들을 위해서 적극적으로 미래산업으로 갈 수 있도록 우리 연구원에서 제대로 된 연구 하나 만들어내야 된다고 보는데 그렇지 않나요?
</p>
<p><b>○ 경기연구원장 임해규 </b> 네, 저도 그렇게 생각합니다. 
</p>
<p><b>○ 김호겸 위원 </b> 특히 고령농업인들, 여성농업인들에 대한 지원책이라든가 하여튼 우리 농업이 브랜드농업이라든가 특화된 농업, 유통구조의 개선이라든가 전문농업인들 육성이라든가 이런 것들 전반적으로 표준적인 것을 만들어내야 된다고 보는데 한번 연구해 주실 거죠?
</p>
<p><b>○ 경기연구원장 임해규 </b> 그간에도 저희가 농업연구를 그래도 꽤나 했습니다. 올해도 저희들이 귀촌ㆍ귀농 연구도 하고 도시농업 연구도 하고 또 6차산업 연구도 하고 유통문제도 연구하고 그래서 연구물이 그래도 꽤 있는 편입니다.
</p>
<p><b>○ 김호겸 위원 </b> 그리고 복지문제도 복지재단이 있지만 복지재단을 보면 백화점식이지 전혀 실질적으로, 복지가 알다시피 맞춤형 복지정책도 지역별로 만들어야 되고 장애인복지, 노인복지들 이 복지정책을 만들어서 도에서도 이 좋은 정책들을 받아들여야 되는데, 만들어내야 되는데 지금 노인자살률도 OECD 제1위 아닙니까? 경제적으로도 어렵고 고독사도 있고 사회안전망이 절대 필요한데 노인복지정책도, 좋은 복지관련 정책도 한번 연구원에서 제대로 만들어 연구했으면 좋겠습니다. 
</p>
<p><b>○ 경기연구원장 임해규 </b> 네, 그렇게 하겠습니다. 
</p>
<p><b>○ 김호겸 위원 </b> 한번 해 주시고요. 지금 경기비전 2040 또 경기북부 10개년 발전 계획. 이게 연구가 다 끝난 건가요? 
</p>
<p><b>○ 경기연구원장 임해규 </b> 두 연구과제 다 지금 연말에 마무리를 할 생각으로 진행 중에 있습니다. 중간보고는 다 됐습니다. 
</p>
<p><b>○ 김호겸 위원 </b> 중간보고는 되셨죠? 저도 본 것 같은데. 하여튼 경기비전 2040과 관련해서 제가 한번 좀 더 개인적인 생각을 첨언해서 말씀드린다면, 우리 연구진들 계시니까. 지금 2030년 정도면 로봇산업이 상당히 발전될 거라고 봅니다, 로봇산업이. 그래서 로봇이 할 수 없는 여러 가지 지식경제라든가 문화예술 등에 대한 일자리 창출에 대한 전략적인 방안도 필요할 것 같고요. 또 우리 경기도는 지정학적으로, 역사적으로 통일의 선봉에 서있는 지역 아닙니까? 그리고 지금 5ㆍ24 조치 이후에 남북이 상당히 경색되어 있습니다만 최근에 추석 때 이산가족상봉으로 인해 가지고 상당히 전향적으로 많이 나오는 그런 모습도 있고요. 통일은 언제 급격한 통일이 도래될 수도 있고 그렇기 때문에 우리 2040 비전전략에는 통일이 이루어졌을 때 우리가 이를 뒷받침할 수 있는 통일의 거점도시 육성이라든가 이런 것에 전반적으로 같이 거시적인 계획도 필요하다고 보거든요. 그것도 담아줬으면 좋을 것 같고요.
</p>
<p style="padding-left:1.2em">  그다음에 민선자치가 올해 20년이 됐는데 아시다시피 지방자치가 중앙정부에 의존할 수밖에 없는 구조가 아닙니까? 그래서 앞으로 20년 후에는 완전한 지방자치가 될 수 있는 걸로 우리가 보면서, 생각하면서 제도적인 개선이 필요하다고 봅니다. 그래서 우리 경기연구원에서 지방자치에 관한 각종 법령이라든가 입법체계, 정부 계획 등을 전략적으로 마련하고 성숙한 지방자치 모습이 담겨질 수 있도록 이런 것도 우리가 미리 앞당겨서 동등하게, 중앙과 지방자치가 공동으로 성숙된 지방자치가 될 수 있도록 이것도 우리가 연구할 필요가 있다고 보는데 어떻게 생각하시죠? 
</p>
<p><b>○ 경기연구원장 임해규 </b> 저희들이 그런 방향에서 사실 연구를, 큰 방향은 위원님 말씀에 동의하고 그런 방향에서 연구하고 있습니다. 
</p>
<p><b>○ 김호겸 위원 </b> 북부 10개년 발전 계획도 북부에 엊그제 갔다 왔습니다만 김동성 소장님도 오신 것 같은데 북부 상당히 열악하죠. 그래서 우리 북부연구센터는 제대로 잘 만들어져서 많은 기대를 하고 있는데 북부지역에 원장님도 잘 아시겠습니다마는 인구는 320만으로 파악이 되고 면적도 42%, 지방자립도는 평균 30%대 정도 되는 것 같아요, 그쪽 지역에. 그래서 지역발전을 저해하는 여러 가지 원인이 있겠지만 그중에서도 이중삼중으로 많은 규제를 받고 있죠? 수도권정비법이라든가 군사시설에 대한 규제라든가 상수도보호 등등 여러 가지 있고 또 도로망 이런 것도 많이 부족한 것 같고 또 안보를 위협하는 여러 가지 요인도 상당히 있지 않습니까? 그러다 보니까 기업도 많이 위축되고 농업관광도 많이 위축되고 등등 해 가지고 상당히 어려움이 많죠. 그리고 동부권지역 여주, 가평 이쪽에도 지역발전을 위해서 그쪽도 함께 연구해 주시고. 하여튼 전반적으로 북부센터에서 이러한 것들을, 규제가 개혁되고 균형발전을 이룰 수 있는 이런 것들을 다 담아서 연구하고 진행되고 계신 거죠?
</p>
<p><b>○ 경기연구원장 임해규 </b> 네, 북부는 10개년 발전 계획을 통해서 방금 위원님 말씀하신 그런 방향으로 연구 추진하고 있고요. 동부는 사실 못했습니다. 그래서 내년도에는 동부권역도 여러 가지 지역의 특수한 사정이 있고 또 규제제한도 있기 때문에 동부에 맞는 발전전략이나 이런 것들을 세워보려고 생각하고 있습니다. 
</p>
<p><b>○ 김호겸 위원 </b> 무엇보다도 동부, 북부 쪽도 현장을 주로 많이 가시면서 그쪽의 지역적인 특성 이런 것도 우리가 고려해 보면서 연구해야 되지 않나 이런 생각을 갖고 있습니다. 
</p>
<p><b>○ 경기연구원장 임해규 </b> 네, 그렇게 하겠습니다.
</p>
<p><b>○ 김호겸 위원 </b> 앞으로 북부권에 좋은 기대를 많이 하겠습니다. 
</p>
<p><b>○ 경기연구원장 임해규 </b> 네, 연구성과가 거의 마무리가 됐기 때문에 한번 보시고 미흡한 점이 있으시면 얘기해 주시면…….
</p>
<p><b>○ 김호겸 위원 </b> 전반적으로 다 나오게 되면 저희들한테 한번 보고하실 수 있는 기회가 있으신 거죠?
</p>
<p><b>○ 경기연구원장 임해규 </b> 그럼요. 그렇게 하겠습니다.
</p>
<p><b>○ 김호겸 위원 </b> 이상 일단 마치겠습니다. 수고하셨습니다.
</p>
<p><b>○ 경기연구원장 임해규 </b> 감사합니다.
</p>
<p><b>○ 위원장 배수문 </b> 김호겸 위원님 수고하셨습니다. 위원님들께 양해말씀을 드리겠습니다. 감사를 진행하다 보니 중식시간이 경과되었습니다. 따라서 중식과 휴식 후 계속 감사를 진행하고자 하는데 이의 있습니까? 
</p>
<p style="padding-left:2.4em">    (「없습니다.」하는 위원 있음)
</p>
<p style="padding-left:1.2em">  그러면 중식과 휴식을 위하여 120분간 감사를 중지하겠습니다. 
</p>
<p class=''ar''>(12시30분 감사중지)
</p>
<p class=''ar''>(14시34분 감사계속)
</p>
<p><b>○ 위원장 배수문 </b> 좌석을 정돈해 주시기 바랍니다. 오전에 이어 감사를 계속하겠습니다.
</p>
<p style="padding-left:1.2em">  그러면 계속해서 나득수 위원님 질의하여 주시기 바랍니다. 
</p>
<p><b>○ 나득수 위원 </b> 부천 출신 나득수 위원입니다. 원장님 행정사무감사 준비하시느라 고생이 많으셨죠? 원장님이 작년 9월에 취임하셨죠?
</p>
<p><b>○ 경기연구원장 임해규 </b> 네.
</p>
<p><b>○ 나득수 위원 </b> 1년 조금 넘었네요. 원장님 취임 이후에 조직개편과 함께 명칭을 경기연구원으로 변경하셨어요. 그리고 대대적인 변화가 있었을 거라고 생각하는데 원장님 취임 후에 연구원의 목표를 어디에 두고 연구원을 이끌어 오셨는지 말씀해 주시고요. 또한 뜻하신 바대로 제대로 연구원이 운영되고 있는지 소견을 말씀해 주시면 고맙겠습니다. 
</p>
<p><b>○ 경기연구원장 임해규 </b> 일단 오전에 보고말씀 드리면서 그런 기조로 보고말씀 드렸습니다만 간단하게 추려서 말씀드리면 저는 미래지향연구하고 현장연구를 강화하는 것과 협업연구를 강화하는 세 가지를 주요한 연구목표로 잡았습니다. 그런데 특히 협업연구가 연구 질을 높이고 그런 게 굉장히 중요하다고 보고 그쪽으로 집중하려고 노력했고요. 그리고 우리 내부적으로는 경영방침을 4개 정도 정해서 했는데 그중에 특징적인 것은 우리 연구원들의 질을 높이는 것이 굉장히 중요하다고 보았습니다. 그래서 연구 질을 높이기 위해서, 일단 우리가 정책연구와 기본연구로 연구유형을 크게 나눌 수가 있는데 기본연구는 주로 학술적인 연구를 합니다. 이거는 정책연구를 하기 위한 밑천을 박사들이 마련하는 연구라고 저희들은 그렇게 보고 있습니다. 그래서 기본연구를 많이 할 수 있도록 여러 가지 여건을 개선하는 데에 저희들이 노력했습니다. 크게는 그렇게 두 가지 정도 특징 말씀드릴 수 있을 것 같습니다. 그런데 성과가 어느 정도냐 이렇게 말씀하시면 100을 목표로 한다 그러면 이제 그렇게 할 수 있는 여건조성 정도를 했다 그러니까 반 정도 했다 이렇게 저는 생각하고 있습니다. 나머지는 앞으로 그걸 토대로 성과를 내야 되는 문제가 2016년의 과제다 이렇게 보고 있습니다. 
</p>
<p><b>○ 나득수 위원 </b> 네, 알겠습니다. 다음은 행정사무감사 요구자료에 보면 3쪽인가요. 최근 3년간 수행한 연구과제 현황을 보면 2013년도에는 총 326건이에요. 그런데 2014년도에는 306건 그다음에 금년에는 9월 말 기준이죠. 193건으로 계속 줄어들고 있네요? 연구실적이 너무 저조한 것이 아닌가 생각하는데 어떠세요? 
</p>
<p><b>○ 경기연구원장 임해규 </b> 그게 결론부터 말씀드리면 저희들이 올 회계연도 마감할 때 연구과제가 다 납품이 일단 이루어지면 연구의 숫자는 그 정도에 이르게 됩니다, 숫자는. 그런데 그럼에도 불구하고 어떤 부분은 늘고 어떤 부분은 줄어들게 되었는데요. 대표적으로 줄게 된 요인 중의 하나는 사실 의정연구센터에서 그간에 수행한 연구가 연구량으로 보면 굉장히 많았습니다. 그런데 의정연구센터 활동을 그만두고 난 다음에 그 부분이 일단 연구량이 많이 줄어든 셈이고요. 대신에 저희들이 수탁연구나 정책연구의 숫자는 크지 않습니다만 이슈&진단이나 현안브리프 같은 단기적인 이슈 중심의 연구는 저희들이 많이 했습니다. 그래서 전체적으로는 그 정도 연구량은 연말이 되면 대충 비슷하게 나올 걸로 생각하고 있습니다. 
</p>
<p><b>○ 나득수 위원 </b> 그렇습니까? 작년 행감 때도 그렇게 말씀하신 거 아닌가요? 작년 행감 때도 그렇게 말씀한 것으로 기억되는데요. 그래서 2013년보다 작년에는 한 20건이 줄어들었네요, 그렇죠. 전반적으로 유형별 연구실적에서도 기본과제, 정책과제, 수탁과제, 협약연구과제에서 대부분 줄어들고 있어요, 줄었어요.
</p>
<p><b>○ 경기연구원장 임해규 </b> 정책연구과제는 2013년 80건이고 2014년도도 82건인데 2015년 9월 현재는 진행 중인 것까지 하면 115건입니다.
</p>
<p><b>○ 나득수 위원 </b> 그렇습니까? 
</p>
<p><b>○ 경기연구원장 임해규 </b> 네, 그러니까 훨씬 많이 늘었습니다. 
</p>
<p><b>○ 나득수 위원 </b> 제 생각도 연구원의 가장 근본적인 존재 목적은 연구과제를 수행하는 것이라고 생각합니다. 아무튼 더 많은 연구 그다음에 질 높은 연구를 해 주셨으면 고맙겠습니다. 
</p>
<p><b>○ 경기연구원장 임해규 </b> 그렇게 하겠습니다. 
</p>
<p><b>○ 나득수 위원 </b> 다음 질문드리겠습니다. 경기연구원에서 의정연구센터가 지난해에 폐지됐죠?
</p>
<p><b>○ 경기연구원장 임해규 </b> 네.
</p>
<p><b>○ 나득수 위원 </b> 감사원 감사결과에 따라 폐지됐습니까? 
</p>
<p><b>○ 경기연구원장 임해규 </b> 감사원 감사도 그렇고 또 의회에 입법전문위원으로 인원이 보충됐기 때문에 사실 저희들이 계속 설치할 수 있는 그런 근거는 없었습니다. 
</p>
<p><b>○ 나득수 위원 </b> 그래서 연구원에서 자치의정부와 대외협력처를 신설하셨습니까? 
</p>
<p><b>○ 경기연구원장 임해규 </b> 지금 저희들 내부적으로는 그런 방침을 세워놓고 있습니다만 그것이 지방자치단체 출자ㆍ출연법에 의해서 새로운 직제를 개편하는 것은 경기도청 집행부와 협의사항입니다. 그래서 조만간 저희들이 의정협력팀을 신설하는 것으로 그렇게…….
</p>
<p><b>○ 나득수 위원 </b> 경기연구원에요?
</p>
<p><b>○ 경기연구원장 임해규 </b> 네. 우리 경기연구원 대외협력처 산하에 의정협력팀을 별도로 구성하는 것을 가지고 도 집행부와 협의하고 있고 긍정적으로 집행부에서도 검토하고 있는 것으로 알고 있습니다. 
</p>
<p><b>○ 나득수 위원 </b> 다음 질문드리겠습니다. 손익계산서를 보면 계속적으로 손실이에요. 2012년도에 29억 2,900만 원 그다음에 2013년도에 29억 8,300만 원, 2014년도에 18억 6,000만 원 계속해서 순손실이 발생하고 있습니다. 그렇죠?
</p>
<p><b>○ 경기연구원장 임해규 </b> 그렇습니다. 
</p>
<p><b>○ 나득수 위원 </b> 연구원이 수익창출 목적으로 수립됐다고 보진 않지만 그렇더라도 수지균형은 이루어야 되지 않느냐 그렇게 저는 생각합니다. 그런데 지속적으로 순손실이 발생한다는 것은 무엇인가 구조적인 문제가 있지 않나 생각합니다. 이에 대해서 원장님의 생각은 어떠십니까?
</p>
<p><b>○ 경기연구원장 임해규 </b> 발생하는 요인은 뭐냐 하면 저희들이 기본자본금이라고 할 수 있는 기금, 저희들 기금손실분입니다, 그 부분이. 그런데 그 기금은 예전에는 사실 저희들이 기금이 유실되지 않도록 집행부에서 출연금으로 그간 다 주셨는데 출연금을 줄이고 기금에서 써라, 위원님 잘 아시다시피 그게 이자도 안 나오는 거를 가지고 있으면 뭐 하느냐 이래서 도 집행부의 방침이 기금을 계속 깨서 쓰는 쪽으로 전체 예산 수지타산을 맞춰서 하도록 정책을 했습니다. 그래서 저희들 기금을 매년 한 25억~30억가량을 지난 3년 계속 감했습니다. 그게 회계상에는 손실로 나타난 겁니다. 그런데 그걸 한편으로는, 그러니까 그 부족한 부분만큼 수탁연구를 해서 벌면 되지 않냐 이렇게 말씀하실 수 있지만 그건 사실 논리적으로는 말은 되나 현실적으로는 맞지 않는 거죠. 왜냐하면 대부분의 저희 연구는 경기도나 이런 데서 주는 것인데 그거를 그냥 안 준다고 저희들이 돈이 어디서 나오는 것은 아니기 때문에, 예를 들어서 그러면 저희들이 취할 수 있는 방안은 민간에서라도 수탁연구를 받아와라 이렇게 해야 되는데 경기연구원의 특성상 민간이 무슨 정책연구를 저희들에게 위탁을 맡길 일은 사실 없습니다, 저희들 연구원의 존립 자체가. 그렇기 때문에 그것은 사실 도에서 기금을 까먹지 않도록 적절하게 예산운영을 잘 맞춰주는 거라고 보고 아마 그렇기 때문에 저희들의 이러한 호소에 대해서 위원님들께서 지난 추경에 한 9억 정도를 기금에 보충을 하라고, 기금 까먹지 말라고 세워 주신 뜻이 있는 걸로 알고 있습니다. 그래서 아마 내년에는 기금을 저희들이 근 3년 동안 20억, 30억 썼는데 이제 한 20억 정도로 줄고 후년도에는 10억으로 줄이고 그다음 연도부터 기금이 한 100억 정도 남을 때에는, 애초 자본금입니다, 그게 저희들 설립자금입니다. 그래서 거기서는 묶기로 저희들이 방침을 정하고 있고 도에서도 긍정적으로 그렇게 검토를 해 줄 걸로 저희들은 바라고 있습니다.
</p>
<p style="padding-left:1.2em">  그리고 이제 하나 더 말씀드리면 100억이라고 하는 초기 기금을 까먹을 때에는 그것이 애초 기금을 조성했던 삼자가 있습니다. 경기도가 40억을 대고 시군이 40억을 대고 또 민간에서 20억을 댔습니다. 그러면 또 그곳의 승인을 받아야 됩니다. 그러니까 경기도가 막 그것을 쓰도록 할 수는 없습니다. 그렇기 때문에 저희들은 100억 수준에서는 어쨌든 더 이상은 기금 잠식하지 않도록 하면 말씀하셨던 것처럼 회계상, 대차대조표상 저희들이 단기순손실이 계속 나오는 이런 거는 막을 수 있다 이렇게 생각하고 있습니다.
</p>
<p><b>○ 나득수 위원 </b> 네, 시간이 지나서요. 자료요청 좀 할게요. 2014년 결산서 좀 갖다 주십시오.
</p>
<p><b>○ 경기연구원장 임해규 </b> 네, 그러겠습니다.
</p>
<p><b>○ 나득수 위원 </b> 이상입니다.
</p>
<p><b>○ 위원장 배수문 </b> 나득수 위원님 수고하셨습니다. 박재순 위원님 질의해 주시기 바랍니다.
</p>
<p><b>○ 박재순 위원 </b> 수원 출신 박재순 위원입니다. 오전에 질의를 못 해서 오후에 이렇게 하게 되었는데요. 어쨌든 연간 240억을 쓰는 우리 연구원이죠. 240억을 쓰는 연구원인데 직원이 약 80여 분, 박사급까지 포함해서 80여 분 되는 것 같아요. 최근에 국감자료에서 지적사항이 있었죠?
</p>
<p><b>○ 경기연구원장 임해규 </b> 네.
</p>
<p><b>○ 박재순 위원 </b> 지적사항이 있었는데 만성적자에 시달리고 있는 경기도 산하기관들이 성과급잔치를 벌였다는 지적이 되었습니다. 그중에서 우리 경기연구원은 “직원 75명에게 가장 많은 32억 3,210만 원을 지급했다.”는 지적하고 “연구직원 1인당 평균 4,300만 원 정도를 받은 셈이다. 이는 한국토지주택공사나 가스공사나 한전, 국내 30대 공공기관의 1인당 평균 성과급 1,400만 원보다도 세 배의 수준으로 받았다.” 이 부분이거든요. 이 부분에 대해서 지금 어떻게 생각하고 있나요?
</p>
<p><b>○ 경기연구원장 임해규 </b> 그것은 저희들 급여체계가 사실은 기본연봉이 있고 성과연봉이라고 해서 저희들 기본급여체계가 이원화되어 있습니다. 그런데 성과연봉은 저희들 기본연봉에서 적절한 비율을 한 20% 정도 되는 비율을 떼서 성과연봉이라고 하는 걸로 나눠주고 있는데요. 그런데 그거는 사실 능력급인 셈입니다, 일종의. 그래서 연구성과를 내부에서 양질평가를 해서, 질도 평가하고 양도 평가해서 성적이 좋은 분에게는 1,500만 원, 그러니까 모든 연구원 평균 1,500만 원을 떼서 그 1,500만 원 뗀 거를 가지고 잘하는 사람에게는 200%를 주고 못하는 사람은 0%를 주는 제도입니다. 물론 1,500만 원을 그냥 가져가는 비율이 제일 많습니다, 중간에 40% 정도 있고. 그렇게 돼 있지만 어쨌든 그거는 따로 무슨 성과가 있으면 주고 없으면 안 주는 게 아니라 내부의 경쟁을 유도하기 위해서 그냥 줘야 될 급여 중의 일부를 잘하는 사람은 많이 주고 못하는 사람은 안 주는 형식으로 돼 있기 때문에 그것을 마치 성과 나눠먹기로 막 나눠먹는다라고 하는 언론은 이런 사정을 모르고 한 것으로 저희들은 그렇게 평가하고 있습니다. 따라서 그것을 정확한 명칭으로 하면 능력급제를 실시했다고 보아야지 그것을 성과급을 가져갔다 이렇게 보면 저희는 안 된다고 봅니다. 그러니까 아마 1인 평균 1,500만 원 곱하기 3년 이렇게 하니까 그거를 4,500만 원 전부 다 잔치했다 이런 식의 표현을 한 것으로 저희들은 그렇게 이해하고 있습니다.
</p>
<p><b>○ 박재순 위원 </b> 75명에게 줬다 이런 표현을 했을 때 원장님도 거기에 대해서 분명하게 그렇게 대답을 하셨나요?
</p>
<p><b>○ 경기연구원장 임해규 </b> 그게 이제 질의를 한 게 아니고요. 그냥 그 위원이 보도자료로 그냥 풀 한 겁니다.
</p>
<p><b>○ 박재순 위원 </b> 아, 보도자료로?
</p>
<p><b>○ 경기연구원장 임해규 </b> 네, 보도자료로 풀 해서 저희들은 그것에 대해서 반박하는 반박문을 하나 써 놨는데 이게 나중에 알고 보니까 질의를 하시고 답변을 하시고 이랬다면 저희들이 바로 반박을 냈을 텐데 그렇게 된 게 아니라 그냥 보도자료를 내신 거기 때문에 저희들이 특별히 대응을 하지 않았습니다.
</p>
<p><b>○ 박재순 위원 </b> 대응을 하지 않았다. 거기에 이제 결국은 그런 문제들이 보도자료라고 한다면, 물론 우리 연구원은 특수성이 있습니다. 그래서 2012년도에 29억, 2013년도에 30억 그다음에 14년도에 19억의 적자를 보면서 그렇게 잔치를 하는 것처럼 보도가 돼 있고 또 이런 부분에 대해서 우리 연구원에서 적극적으로 대처하지 않았고 묵인하고 있으니까 우리 연구원의 어떤 이미지가 실추되지 않았나 본 위원은 생각을 하고 있고 이 부분에 대해서 왜 그때 당시 바로바로 보도자료를 하지 못했는지 안타까움이 좀 있습니다. 이 부분에 대해서 다시 한 번 좀 말씀해 주시기 바랍니다.
</p>
<p><b>○ 경기연구원장 임해규 </b> 빚이 29억 있고 이렇게 한다는 건 아까 나득수 위원님 질의사항과 똑같은 내용입니다. 그러니까 저희들이, 그게 바로 기금 삭감액입니다. 기금을 우리가 깨먹은 그 액수만큼이 계속 손실로 됐기 때문에 빚을 졌다 이렇게 표현되어 있는 것이고요. 그리고 저희들 성과급 했다는 건 방금 말씀드린 대로인데 그런데 그것을 적극적으로 대응보도를 하지 못한 점은, 향후에는 어쨌든 저희들이 적극적으로 대응하도록 그렇게 하겠습니다.
</p>
<p><b>○ 박재순 위원 </b> 그래야 우리 경기도민 1,280만은 어쨌든 경기도를 바라보고 있고 연구원을 바라보고 있습니다. 이렇게 잘못된 오보로 나가면 또 잘못된 이런 문구가 나가면 결국은 우리 도민의 피해고 우리 연구원의 피해고 이미지에 대한 상당한 신뢰성 이런 문제점이 발생하기 때문에 추후에 이런 문제가 생겼을 때는 바로바로 대처할 수 있는 그런 시스템이 되었으면 좋겠다는 말씀을 드리겠습니다.
</p>
<p><b>○ 경기연구원장 임해규 </b> 반박자료는 꼭 내겠습니다. 반박자료가 사실 언론에는 잘 실리지는 않습니다. 그렇지만 저희들이 최대한 노력을 해서 언론에 좀 실려서 저희들 입장을 정확하게 설명할 수 있도록 그런 노력을 더 기울이도록 그렇게 하겠습니다.
</p>
<p><b>○ 박재순 위원 </b> 그래야 된다고 봅니다. 여기 한 예로 보면 한전, 가스공사 이런 곳하고 비교를 해서 연구원들의 명예를 실추시키는 이런 잘못된 보도가 있었고 잘못된 말을 했다면 그것은 분명하게 말을 해야 된다고 봅니다. 그래서 어쨌든 우리 경기연구원에 계신 분들이 나름대로의 어떤 성과급을 가지고 또 일을 하고 있고 또 그것을 서로가 모아서 나눠 갖는 그런 시스템을 선택하고 있는데 잘못 알고 이렇게 타 공공기관하고 비교를 해 가지고 이렇게 주면 정말 조금 잘못된 그런 표현인 것 같고 또 우리 경기도 입장에서도, 연구원 입장에서도 별로 좋은 것 같지가 않아요. 그래서 추후에 이런 문제가 있으면 우리 원장님께서 또는 그 산하부서, 홍보부서에서 적극적으로 이런 부분들은 좀 챙겨서 대응해 주셨으면 좋겠다는 말씀을 드리고요.
</p>
<p><b>○ 경기연구원장 임해규 </b> 네, 그렇게 하겠습니다.
</p>
<p><b>○ 박재순 위원 </b> 최근에 또 경기도에서 대학생들 행정인턴을 뽑은 적이 있었어요.
</p>
<p><b>○ 경기연구원장 임해규 </b> 네, 그렇습니다.
</p>
<p><b>○ 박재순 위원 </b> 여름방학 때. 그때 우리 연구원만 또 질타의 대상이 되었던 게 대학생들에 대한 250명의 연구원 중에서 15명 뽑으셨나요, 연구원에? 인턴사업.
</p>
<p><b>○ 경기연구원장 임해규 </b> 15명 좀 넘었던 것 같습니다. 저희들 27명을 뽑았습니다.
</p>
<p><b>○ 박재순 위원 </b> 그때 27명을 뽑았나요? 그때도 언론에 질타되었던 부분은 석사급 이상만 선택해서 지원을 받았다 이런 부분에 대해서, 형평성에 대해서 또 우리 대학생들이 학교에 가지 않으면서 사실은 학비를 조금은 벌고 싶어서 지원했던 그런 부분들이 없지 않아 있었을 건데 우리 연구원만 유독 석사급으로 기준을 정해서 채용했다는 거에 대한 형평성을 말씀드리고 싶습니다. 그래서 왜 굳이 석사 이상을 요구했는지 거기에 대해서 말씀해 주시기 바랍니다. 
</p>
<p><b>○ 경기연구원장 임해규 </b> 저희 연구원의 특성상 저희들이 인턴을 데려오면 저희 직무에 대한 인턴을 하는 의미라고 이해하고 있습니다. 그러니까 저희 기관이 주로 연구를 하는 기관이다 보니까 아무래도 석사 정도의 훈련이 된 사람들이 와야 저희, 오면 인턴들에게 연구하는 것을 경험하게 해 주는 게 저희들의 주요한 프로그램입니다. 그래서 그때 왔을 때도 팀을 한 4개 팀 나누어서 저희들이 연구과제 주고 그 연구과제를 수행하도록 해서 한번 연구를 어떻게 하는지, 그래서 앞으로 연구원이 되는 것은 어떤 경로를 거치는지 프로그램을 했습니다. 그때 그 팀마다 우리 박사들을 한 명씩 붙여 가지고 멘토를 하게 하고, 그렇게 하려면 아무래도 그런 연구를 할 수 있는 정도의 준비된 사람들을 받는 것이 효율적이라고 보고 그렇지 않으면 와 가지고 사실 제대로 뭔가 훈련을 시킬 수 있는 프로그램을 운영하기 어렵다고 저희들이 봤기 때문에, 그리고 그때 신청한 사람 중에 사실 석사연구원들이 굉장히 많습니다. 그래서 그중에 석사연구원들은 우리 경기연구원 쪽에 와 가지고 인턴을 하는 것이 좋겠다는 판단이, 모르겠습니다. 제가 처음에 그 결정을 누가 했는가는 지금 잘 모르겠는데요. 아마 도하고 협의를 해서 우리 연구원에서는 그런 프로그램을 할 거니까 석사연구원하고 좀 맞는, 그러니까 학력을 아마 그런 정도로 자격을 주지 않았나 그런 생각이 듭니다.
</p>
<p><b>○ 박재순 위원 </b> 석사 이상을 요구하다 보니까 일반학생들은 접근하기 어려웠던 그런 부분이 있었는데 사실은 학생들에게 어떤 알바의 형식으로 했던 건데 우리 연구원의 취지하고 또 우리 본청에서 생각했던 취지하고 좀 틀렸던 것 같아요. 그래서 그런 부분들을 좀 더 명확하게 해 줬으면 좋겠다는 말씀드리고요.
</p>
<p><b>○ 경기연구원장 임해규 </b> 제가 잠깐, 석사급 이상을 요구한 것은 저희 연구원에서 요구했습니다.
</p>
<p><b>○ 박재순 위원 </b> 그러니까, 요구를 했고 집행부에서는 그 기준을 안 두고 뽑았던 건데 그런 부분들을 연구원에 인력이, 인턴사원이 필요했으면 별도로 이렇게 만들어야 되지 않았었을까, 인턴을 모집했었을 때. 그 생각이 좀 들었다는 거죠. 그랬으면 좀 더 좋은 그런 어떤 시스템이 운영되는 데 연구원에서 요구하는 사람들에게 또 다른 학생들에게 이렇게 오해받지 않는 그런 것 같아요, 지금. 사실은 연구원에 가서 본인이 대학생이면서 연구원에서 알바하고 싶지 않겠습니까? 자기 경력 쌓는 데 이것만큼 더 좋은 곳이 없으니까. 그래서 그 부분에 대해서 지금 말씀을 드려보는 거고요. 시간 벌써 다 됐나요? 추후 질문 다시 하겠습니다.
</p>
<p><b>○ 위원장 배수문 </b> 박재순 위원님 수고하셨습니다. 박재순 위원님을 끝으로 본질의는 마쳤습니다. 잠깐 쉬는 시간에 위원님들 일정 조율한 대로 진행을 하도록 하겠습니다. 추가질의는 5분 드리도록 하겠습니다. 장동일 위원님 더 질의하도록 그렇게 하겠습니다.
</p>
<p><b>○ 장동일 위원 </b> 이따 하겠습니다.
</p>
<p><b>○ 위원장 배수문 </b> 조금 이따가요. 그러면 안혜영 위원님.
</p>
<p><b>○ 안혜영 위원 </b> 자료를 하나하나씩 갖다 주셔 가지고 정리가 좀 안 됐는데요. 수원 출신 안혜영 위원입니다. 원장님, 제가 질의 시작하기 전에 해 주실 말씀 없으신가요? 아까 오전 질의에 관련해서.
</p>
<p><b>○ 경기연구원장 임해규 </b> 아까 추가로 검토하지는 않았습니다만 저희들이 조금 더 검토해서 추후에 보고드릴, 아마 말씀하시는 게 비상임 정책위원 그 건, 150% 지급 건 그거 말씀하시는 건가요?
</p>
<p><b>○ 안혜영 위원 </b> 네.
</p>
<p><b>○ 경기연구원장 임해규 </b> 그런데 어쨌든 제 판단은 그 조문의 글자 그대로의 의미를 보면 기준급의 150%라고 이해가 됩니다, 규정이. 그런데 지급은 기준급 플러스 150% 규정으로 해석하고 그중에 100%를 준 것으로 이렇게 제가 사료됩니다만, 그런데 그거를 애초에 판단하고 했을 때는 나름대로 검토를 거쳐서 했을 것 같아서 다시 한 번 그것을 살펴보고 추후에 명확한 답변을 드리도록 하겠습니다.
</p>
<p><b>○ 안혜영 위원 </b> 속기록 앞에 서시니까 설명이 또 많이 이렇게 달라지시는 것 같습니다.
</p>
<p><b>○ 경기연구원장 임해규 </b> 아닙니다, 진짜로 그렇게…….
</p>
<p><b>○ 안혜영 위원 </b> 제가 설명을 들은 것처럼, 길게 할 건 아닌 것 같고요. 말씀하신 것처럼 규정에 의해서 따라야 하고 규정의 해석을 하실 때 원장님도 150%로 해석을 하시죠? 그래서 오버 지급된 걸로…….
</p>
<p><b>○ 경기연구원장 임해규 </b> 그렇습니다. 제가 보기에는…….
</p>
<p><b>○ 안혜영 위원 </b> 오버 지급된 걸로 해석이 되시는 거고. 그런데 그 규정을 만들 때의 취지가 그랬다는 말씀이신데 그럼 규정을 잘못 만든 거죠. 그러니까 그런 취지로 규정을 정하실 것 같으면 규정을 바꾸시겠다라고 답변하셨죠? 바꾸시든가 그 규정을 지키시든가 해 주시기 바랍니다.
</p>
<p><b>○ 경기연구원장 임해규 </b> 그러겠습니다.
</p>
<p><b>○ 안혜영 위원 </b> 그렇게 해 주시고요. 아까 제가 감사관, 자료를 그냥 막 하나씩 갖다 주셔서……. 감사받았던 것 중에 연구원 박사님들이 근무시간 외에, 막 갖다 주셔서 제가 찾아봐야 되는데……. 연구원분들이 외부에 강의를 나가시거나 외부에 출장을 나가시거나 그런 것과 그리고 위원회에 참여를 하시거나 경기연구원의 근무 외에 추가일정을 보실 때에 관련된 말씀을 좀 드렸었습니다. 제가 경위서를 받아 봤습니다. 외부활동내역서도 받아 봤고요. 조금 안타까운 건 아직 감사원 결과가 나와 있지 않아서 제 개인적인 소견으로 말씀을 드리자면, 좀 민감할 수도 있고 해석의 차이가 있을 수 있을 것 같습니다. 박사님들이든 연구원분들이 지금 한 쉰일곱 분 정도 되신다고 그랬죠?
</p>
<p><b>○ 경기연구원장 임해규 </b> 네.
</p>
<p><b>○ 안혜영 위원 </b> 이번에 이 문제에 거론되신 분들이 마흔여섯 분이라고 들었습니다. 한두 건일 수도 있고 다수의 건일 수도 있는데 이번에 지적받았던 이 문제가 명확하게 해결되지 않으면 이것이 급여 문제나 인건비 문제와 연결성이 있죠?
</p>
<p><b>○ 경기연구원장 임해규 </b> 네.
</p>
<p><b>○ 안혜영 위원 </b> 그리고 수당의 문제가 있고 그리고 이중직업을 갖게 되는 그런 오해의 소지가 충분히 있을 수 있다고 봅니다. 그럴 수 있었던 것 중에 경위서를 제가 보니까 주말에 나가서 근무하는 것에 대해서 수당을 받거나 그런 회의참석수당 이런 것들, 연구용역비라든가 이런 것들을 받은 거에 대해서 뭐라고 하기는 힘든 거고, 그만큼 저희 경기연구원의 연구원 박사님들이 외부에서 인정받고 있다는 거에 저는 자긍심을 갖습니다. 하지만 근무시간과 연계성이 불분명하죠. 예를 들어서 한 달의 연구프로젝트를 받는다고 하면 저희 연구원의 연구실에 계시면서 한 달 동안의 프로젝트를 칼같이 딱 잘라서 출퇴근시간에 규정해 가지고 하기는 사람으로서 쉽지 않은 일입니다. 그때 참가하면서 그 프로젝트에 임한 외부에 전화통화도 할 수 있는 거고 그것에 대한 문의도 할 수 있는 거고 그걸로 인한 여러 가지의 연결고리들이 다 되어 있는데 그게 명확하게 이번에 규정으로 되거나 해결되지 않으면 시시비비의 논란의 소지는 계속될 것이다. 그리고 그 용역비가 일이십만 원이 아니라 보통 몇백만 원, 최소 몇백만 원 정도씩 되시잖아요?
</p>
<p><b>○ 경기연구원장 임해규 </b> 네, 총액으로 하면 그렇게 됩니다.
</p>
<p><b>○ 안혜영 위원 </b> 그렇죠. 그렇기 때문에 문제의 소지가 충분히 있고 어떤 거는 2,000만 원 이상 되는, 원고 집필비 같은 경우는 기간이 4~5개월, 한 6개월 정도 되네요. 그런 거 같은 경우는 2,000만 원이 넘는 원고료가 좌우되니 그런 문제들을 명확하게 짚으시고 이 결과에 대해서는 위원님들에게 보고해 주시기 바랍니다.
</p>
<p><b>○ 경기연구원장 임해규 </b> 네, 알겠습니다. 
</p>
<p><b>○ 안혜영 위원 </b> 아까 말씀드렸던 것 중에 하나가, 시간이 별로 없으니까 한 가지만 짚으면 민원 있으셨죠? 감사원 감사 이런 거 말고. 조사에 관련된 것들이 있어서 물품구입 그런 것들에 대한 문제제기가 있었던 걸로 알고 있습니다. 그렇죠?
</p>
<p><b>○ 경기연구원장 임해규 </b> 네.
</p>
<p><b>○ 안혜영 위원 </b> 적절하다고 판단되시나요? 물론 내부의 연구원분들의 피로도를 위해서 의무실을 만들고 층에 집기류, 그 외에 저희들이 생각하는 일반적인 사무용품이 아닌 그런 물품들이 필요하다라고 판단할 수도 있겠지만 제가 그 물품을 봤을 때는 연구원에 적절하지 않다라는 판단이 듭니다. 원장님의 의견은 어떠세요?
</p>
<p><b>○ 경기연구원장 임해규 </b> 말씀하신 게 아마 세탁기를 말씀하시는 거 맞습니까? 
</p>
<p><b>○ 안혜영 위원 </b> 세탁기도 있고 뭐 그 외 다른 물건도 있습니다. 
</p>
<p><b>○ 경기연구원장 임해규 </b> 우선 세탁기의 경우는 오해의 소지도 있을 수 있기 때문에 적절치 않을 수도 있다고 생각합니다. 그렇지만 애초에 그것을 구비할 때는 나름의 필요에 입각해서 한 것인데 문제가 제기됐습니다. 그렇다고 산 거를 처분할 수 없기 때문에 잘 활용할 수 있도록 할 생각이고요. 그리고 침대 부분은 실제로 일어나지 않았던 일입니다. 그렇기 때문에 논의가 된 바는 있습니다만 실제로 그렇게 하지 않았기 때문에 그것은 그렇게 말씀드릴 수 있을 것 같습니다. 
</p>
<p><b>○ 안혜영 위원 </b> 그런 논의의 의견들이 있지만 어찌 됐든, 거론을 어차피 하셨으니까 세탁기 같은 것도 지금 경기연구원 세탁기, 어느 누구도 이해하기가 쉽지 않은 겁니다. 물론 원장님이 오셔서 직원들의 사기진작이나 이런 걸 위해서 동아리 활동도 많이 하고 네트워크를 하려고 노력하시는 거는 충분히 이해가 가지만 그렇다고 해서 그런 것들이, 저희도 마찬가지로 의회에도 있습니다. 의회에도 동아리 활동 다 하고 축구동아리도 있고 그렇지만 그렇다고 해서 세탁기를 사야지라는 생각을 한 적은 없었던 것 같습니다. 그리고 적절선의 피로도라고 하면 간이침대도 있을 수 있는 거고 그런 것들에 대한 논의지 그렇다고 해서 아까 말씀하신 돌침대 정도의 그런 규모로 생각한다고 하면 그거는 직장이라고 표현하기가 쉽지 않은 부분이죠. 상식선에서 생각할 수 있는 그런 기준으로 직장에서의 기준을 바라봐 주셔야 할 것 같습니다. 지역주민들이 보셨을 때도 이해할 수 있는 부분들이 돼야지 않겠습니까? 일단 추가질의 이것으로 마치겠습니다. 
</p>
<p><b>○ 위원장 배수문 </b> 안혜영 위원님 수고하셨습니다. 한 가지만 질의하겠습니다. 경기연구원과 같은 연구의 역할을 하는 경기도 산하기관이 많죠?
</p>
<p><b>○ 경기연구원장 임해규 </b> 네.
</p>
<p><b>○ 위원장 배수문 </b> 그래서 작년 행감 때 많은 동료 위원님들이 질의했던 내용 중의 하나가 경기연구원이 일정부분의 역할을 해야 되지 않느냐라고 질의했던 걸로 알고 있는데 1년 동안 어떻게 진행됐습니까? 
</p>
<p><b>○ 경기연구원장 임해규 </b> 다른 산하 연구원, 산하기관들에 대해서…….
</p>
<p><b>○ 위원장 배수문 </b> 네, 여기서 경기연구원이 그래도 연구에 있어서는 경기도에서 가장 선두 연구원이지 않습니까? 누가 보더라도. 그래서 일정부분 리딩하는 부분이 있어야 되지 않겠느냐라고 요청했고 원장들끼리의 모임도 주재할 필요가 있지 않겠느냐라고 얘기됐던 걸로 알고 있거든요.
</p>
<p><b>○ 경기연구원장 임해규 </b> 저희가 그 사업도 검토를 하고 지금 어떤 방식으로든지 간에, 그러니까 연구원 간의 네트워크죠, 정확하게 얘기하면. 그게 굉장히 필요하고 그거는 왜냐하면 저희 연구원이 특히 과학기술 쪽은 전혀 커버를 못하고 저희는 정책연구는 할 수 있지만. 또 농업연구는 농업기술원이 하고 있고 여러 복지는 복지재단이 하고 있고 여성ㆍ보육 문제는 여가원이 하고 있기 때문에 저희들이 함께 연구를 해야 될 이런 요소도 많아서 그렇게 하기 위한 시스템을 한번 구축해 보자고 생각했는데 사실 그와 같은 문제의식 속에서 과거에 연구원협의회 비슷한 네트워킹이 있긴 했었습니다. 그런데 작동이 안 된 거죠. 그래서 그 요인 뭔가 하다가 우리 연구원이 주도해서 그와 같은 거를 하자 그러면 이게 잘 안 되는 면이 있는 것 같습니다. 그래서 저희가 도의 기획조정실에, 아무래도 기획조정실이 그런 중간역할을 해서, 산하 연구원들 다 커버하고 있으니까 모임을 끌어주시면 저희들도 참여해서 하는 쪽으로 하면 좋겠습니다라고 의견을 드렸고 그래서 아마 기조실에서 그렇게 네트워크 구성을 하기 위한 여러 가지 논의를 하고 있는 것으로 그렇게 이해하고 있습니다. 
</p>
<p><b>○ 위원장 배수문 </b> 현시대가 과거와 같이 한 분야만 집중적으로 연구결과를 내놓는 것들이 유의미하게 답을 내기가 쉽지 않은 구조인 거는 맞죠?
</p>
<p><b>○ 경기연구원장 임해규 </b> 네.
</p>
<p><b>○ 위원장 배수문 </b> 그래서 융합 얘기하고 있고 그래서 융합연구원 같은 경우도 만들어지고 있습니다. 일부러라도 만드는 경우죠. 그래서 연구원 내에 자체적으로 그러한 분야의 연구원들 뽑으셨죠? 융합 차원에서.
</p>
<p><b>○ 경기연구원장 임해규 </b> 그렇습니다. 
</p>
<p><b>○ 위원장 배수문 </b> 그런 부분들도 녹여내고 있는 거 맞죠?
</p>
<p><b>○ 경기연구원장 임해규 </b> 네.
</p>
<p><b>○ 위원장 배수문 </b> 그래서 한 연구원이 처음부터 끝까지 연구를 독점적으로 해야 될 분야가 물론 있습니다만 일정부분 다 돼서 이름에 네이밍을 휴먼 그래서 다 인간중심으로 실명도 바꾸고 그러지 않으셨습니까? 상생 뭐 이런 식으로. 그것의 의미가 연구원 내에서는 더 활성화된다라고 생각하고 연구원뿐만 아니라 경기도 전체로 확산시켜 나갈 필요가 있다라고 보는 건데 그중에 지금 연구원에서 하면 오해의 소지가 있기 때문에 기조실에서 하고 있다 이렇게 얘기하시는 겁니까? 
</p>
<p><b>○ 경기연구원장 임해규 </b> 네, 그렇게 판단하기, 지금 또 이렇게 말하는 거 자체가 다른 연구원이 보면 그럴 것 같아서 제가 말씀드리기가 좀 조심스럽습니다만 왜냐하면 경기연구원하고 다른 연구원하고 통합을 시킨다는 이런 논의도 많아서 다른 연구원에서는 경기연구원이 주도해서 하자 이렇게 하면 사실 불편한 것이 있는 것 같습니다, 그간의 관계를 보면.
</p>
<p><b>○ 위원장 배수문 </b> 알겠습니다. 거기까지만 답변 듣도록 하겠습니다.
</p>
<p><b>○ 경기연구원장 임해규 </b> 그래서 저희들이 주도하는 건 적절치 않은 것 같습니다. 
</p>
<p><b>○ 위원장 배수문 </b> 네, 알겠습니다. 이어서 임두순 위원님 질의해 주시기 바랍니다.
</p>
<p><b>○ 임두순 위원 </b> 남양주 출신 임두순입니다. 저는 다른 얘기를 하고 싶어요. 아까 식사시간에 원장님 잠깐 말씀 나누던 것 중에 화장장 얘기 있었죠. 왜 이렇게 화장장이 문제가 된다고 생각해요? 서로 입지를 못하게 하고 서로 님비현상도 있고 서로 우리 지역에 못 오게 하는 주된 이유가 뭐라고 생각하세요? 원장님.
</p>
<p><b>○ 경기연구원장 임해규 </b> 주민들 입장에서는, 사실 지금은 화장장이 여러 가지 시설들을, 환경 배출물 같은 것들이 문제가 안 되게끔 여러 가지 조치를 많이 취하고 있습니다만 아무래도 아직은 화장장이 주민기피시설로 되어 있기 때문에 직접 수혜를 받지 않는 주민들이 인근에 있는 주민들 같은 경우는, 오히려 화장장 옆에 있는 분들은 이런 화장장 설치하는 과정에 함께 논의도 하고 협의도 하고 또 일정하게 받아들이겠다고 하는 것들이 협의가 돼 있습니다만 그 영향 밖에 있으면서 영향을 받는다고 생각하는 인근 주민들은 반대를 하게 마련입니다. 그건 어디나 이런 현상이 벌어지게 됩니다. 그래서 아마 그런 것으로.
</p>
<p><b>○ 임두순 위원 </b> 어떤 말씀인지 알았고요. 본 위원이 이런 화장장에 대한 인식의 변화, 패러다임의 변화가 있어야 된다는 취지의 도정질의를 했어요, 얼마 전에. 그 내용의 골자는 간단히 결론만 말하면 황당한 얘길지 모르지만 광교에 짓는 경기도청 지하에다가 장례식장 놓고 옥상에 화장장 넣어라 이런 얘기거든요. 이렇게 공공기관이 생각을 변화시켜 가지고 앞서서 이런 시설을 설치한다고 하면 31개 시군에 파급효과가 무지하게 크거든요. 그럼 이런 장사시설에 대한 인식이 바뀌어야 돼요. 지난번에 유럽으로 연찬회를 갔었는데 유럽 같은 데 가면 이런 시설들 옆에 공원처럼 돼 가지고 와서 책도 읽고 자연스럽게 데이트도 하고 이런 분위기예요. 그런데 우리는 아직도 죽음에 대한 인식이 그쪽 분들이랑 틀리게 나타나기 때문에 그런다고 생각하는데 어쨌든 정말 중요한 장사시설이 우리 경기도가 1,280만이 다 됐는데 지금 수원이랑 화성이랑 용인 3개밖에 없어요. 이렇게 중요한 장사시설에 대한 연구가, 최근 2년간 장사시설 연구목록을 보니까 1년에 딱 하나씩 있더라고요. 2014년도에 경기도 장사시설 중장기 수급계획 수립 연구 하나랑 그다음에 2015년도에 정책연구과제로 화장시설의 환경영향분석 관리방안 연구. 이렇게 1년에 하나씩 딱 2개가 있더라고요. 그래서 이거는 좀 잘못되지 않았나 생각이 들어요. 
</p>
<p style="padding-left:1.2em">  이렇게 필요한 시설이고 어떻게 보면 학문적ㆍ이론적 도정의 방향을 제시해야 되는 경기연구원에서 이렇게 도에서 논란되고 있는 시설에 대한 연구가 14년도, 15년도, 저는 정말 이 자료 잘 받아보고 있거든요. 물론 워낙 분량이 많아서 다 읽어보지는 못하지만 관심 있는 건 저도 읽어보는데 항상 정말 유익한 자료라고 생각해요, 보내 주시는 게. 그런데 장사시설에 대한 연구 특히 도민들의 장사시설에 대한 인식변화에 대한 방향제시를 경기연구원에서 해 줘야 한다고 생각해요. 어쨌든 이게 필요한 시설인데 입지를 못하고 있는 거 아니에요. 자꾸 이것 때문에 분란이 일고 지역 간에 갈등도 일고. 그러니까 이런 인식변화에 대한 역할이나 방향제시를 경기연구원에서 앞으로 용역연구를 수행해 가지고 도민들에게 홍보책자를 만든다든가 아니면 도정홍보지나 이런 데 자꾸, 이게 생각이 바뀌어야 된다고 생각해요. 아까 우스갯소리로 말씀드렸지만 저는 정말 그렇게 하고 싶어요. 내가 만일에 지사라고 하면, 물론 법적인 테두리 안에서 이게 허락이 된다면 내가 일선 시군의 시장이라도, 대부분 수원처럼 이런 집합도시가 아닌 이천, 남양주 이런 데 보면 청사가 전부 떨어져 있잖아요. 주차장은 밤에는 비고. 그럼 이런 데 지하에다가 장례식장 넣어 가지고 도민들한테 서비스도 해 주고 그다음에 시청 청사 옥상에다가 화장장 넣어 가지고 도민들한테 저렴하게 화장장 서비스를 해 주고. 이런 획기적인 발상이 필요한 데 대한 연구를 경기연구원에서 선도적으로 해 가지고 인식의 변화를 가져올 수 있는 방향의 연구를 해 주셨으면 하는데 원장님 어떻게 생각하세요? 제가 말씀드린 거에.
</p>
<p><b>○ 경기연구원장 임해규 </b> 사실 제가 화장장 때문에 오랫동안 고생한 사람으로서는 화장장 입지를 반대하는 분들이 화장장을 추진하는 시장한테 “니네 집 지하에다가 하든지 아니면 시청 밑에다 해라.” 보통 이렇게 얘기를 많이 합니다. 그래서 그 말씀이 익숙한데 사실 시청이 만약에 외진 데, 주변에 아무것도 없고 홀로 있는 시청을 처음 짓는다면 아마 그것도 가능하겠죠. 그렇지만 시청 주변에 뭐가 있는 다음에야 아마 실현하기는 어려울 겁니다. 그런데 이거는 두 가지 문제인데…….
</p>
<p><b>○ 임두순 위원 </b> 그럼요. 생각이 바뀌어야 된다고 생각하죠.
</p>
<p><b>○ 경기연구원장 임해규 </b> 하나는 우리가 장사시설에 대한 연구를 매년 한 건 정도 하는 건 사실 다른 여러 가지 사안을 비춰볼 때 단일 사안을 가지고 1년에 연구 하나를 하는 건 적지 않게 하는 겁니다. 그렇기 때문에 연구량이 적은 건 아닌 것 같고요. 다만 갈등조정에 관한 문제가, 장사시설에 대한 연구만이 아니라 위원님 말씀처럼 기피시설에 대한 주민갈등 문제를 어떻게 해소하는가, 또 의식을 어떻게 변화시키는가 하는 연구는 갈등연구로서 굉장히 필요한 연구라고 생각이 들고 그래서 저희들이 정책연구로 갈등연구도 해 볼 생각입니다. 현안브리프나 이런 걸로는 갈등 관련된 연구를 이슈&진단 이거는 해 봤습니다. 그런데 본격적으로 이런 연구도 같이해서 장사시설을, 사실 장사시설이 얼마큼 해로우냐 뭐 하냐 이런 문제보다도 그거는 연구가 그간 많이 됐기 때문에요. 이런 막상 입지를 하려고 하면 갈등이 생겨서 해결이 안 되면 시행이 안 되는 문제는…….
</p>
<p><b>○ 임두순 위원 </b> 시간이 거의 다 됐는데요. 제가 한 가지 제목을 제안한다고 하면 장사시설에 대한 인식변화를 가져올 수 있는 연구방안. 그러니까 장사시설에 대해서 우리가 늘 혐오시설이라고 얘기하잖아요. 그런데 인식변화를 가져올 수 있는 방법이 여러 가지예요. 왜냐하면 분진 안 나오게 하고 정말 깨끗한 공기를 내보낸다는 그런 시설에 대한 홍보도 하고 여러 가지가 있는데 또 한 가지만 간단히 말씀드리면 저는 그래요. 여의도 국회의사당 앞에 땅 넓잖아요. 거기다 화장장 하나 만들면 이거 대한민국 얼마나 획기적이겠어요. 그리고 또 하나는 광교 같은 대단위 신도시를 조성할 때 설계단계에 장사시설이나 장사 관련시설을 이미 거기다 제도적으로 넣을 수 방안. 이렇게 되면 입주하는 사람도 있는 거 알고 입주하는 거 아니에요. 이런 역발상이 필요한 때라고 생각해요. 그런 취지에서 말씀드린 거니까 한번 연구를, 한번이 아니라 이거에 대한 연구는 어떻게 보면 경기연구원에서 꼭 수행해야 되는 연구과제라고 생각해요. 꼭 그렇게 해 주시면 고맙겠습니다. 
</p>
<p><b>○ 경기연구원장 임해규 </b> 네, 알겠습니다.
</p>
<p><b>○ 위원장 배수문 </b> 임두순 위원님 수고하셨습니다. 질의하실 위원님, 이현호 위원님 질의하여 주시기 바랍니다. 
</p>
<p><b>○ 이현호 위원 </b> 여러 번 이야기가 나왔던 사항인데요. 북부권에다가 경기연구원센터를 설립한 것하고 또 북부권 10개년 발전 계획을 세우고 계시지 않습니까? 그 말씀드리기 전에 우리 원장님께서 취임하시고 가장 내가 이런 것 때문에 보람 있었다 그런 거 한번 말씀하실 수 있을까요? 보람된 일.
</p>
<p><b>○ 경기연구원장 임해규 </b> 아직까지는 계획했던 대로 완수된 성과가 나오지 않았기 때문에, 1년 사이에는 잘 나오지 않는 것 같습니다. 그런데 저로서는 올해에 여러 박사님들이 기본연구과제라고 해서 학술적인, 수준 있는 그런 연구를 어려운 여건에서도 많은 박사님들이 한번 해 보겠다고 해서 지금 과제들이 다 진행 중이신데 그런 거를 그렇게 하는 것이 좋겠다, 우리 연구원의 질 발전을 위해서 이렇게 하는 것을 공유하고 또 발맞춰서 애를 써주시는 것이 저는 굉장히 고맙고 보람 있다고 생각합니다. 
</p>
<p><b>○ 이현호 위원 </b> 재임 중에 계속 보람된 일만 일어나길 바라고요. 경기북부지역에다가 연구센터를 건립한 것은 다 똑같이 동감하는 거겠지만 북부지역 주민들의 보다 나은 삶의 질 향상을 위해서 설립했습니다, 돕기 위해 가지고. 그 북부센터를 설립하다 보니까 아마 설립 과정에서도 마찬가지지만 하고 나서도 운영비까지 따지면 예산이 상당히 많이 들어갈 것으로 보입니다. 그렇죠?
</p>
<p><b>○ 경기연구원장 임해규 </b> 네.
</p>
<p><b>○ 이현호 위원 </b> 여기서 같이 있던 것하고 분리하다 보니까 예산이 상당히 많이 들어가는데 그러한 것은 다 도비 바로 도민의 세금이기 때문에 정말로 원장님께서나 근무하시는 박사님, 모든 직원들께서 특별한 관심을 가지시고 정말 도민을 위해서 열심히 해 주시기 부탁드리겠습니다. 
</p>
<p style="padding-left:1.2em">  10개년 북부권 사업 발전 계획을 세우셨는데 여기에 보면 사업을 많이 세분화시키지 않았습니까? 산업, 교통, 도로망 같은 거 또한 도시지역 개발, 문화관광 여러 가지 세분화해 가지고 10개년 발전 계획을 세웠는데 지금 완성품은 아니지 않습니까? 
</p>
<p><b>○ 경기연구원장 임해규 </b> 네, 중간보고는 했습니다. 
</p>
<p><b>○ 이현호 위원 </b> 제가 왜 이런 말씀드리냐 하면 이런 사업이, 이런 계획이 이루어지려면 뭐니 뭐니 해도 돈인데, 예산인데 여기 얼마 정도 들어갈 예산이라는 것은 아직 생각 안 해 보셨죠? 이거에 대해서.
</p>
<p><b>○ 경기연구원장 임해규 </b> 예산계획도 덧붙일 겁니다. 
</p>
<p><b>○ 이현호 위원 </b> 아직 안 나타난 거 아닙니까? 앞으로 할 것이지.
</p>
<p><b>○ 경기연구원장 임해규 </b> 10개년 계획이기 때문에 10개년 계획에 그 사업들을 어떤 식으로 배치하면 좋겠다 하는 예산계획까지 거기에 덧붙여서 완결판 낼 때는 붙을 겁니다. 
</p>
<p><b>○ 이현호 위원 </b> 그렇죠, 나중에. 제 말씀은 뭐냐 하면 차후에 다 해 놓은 상태에서 예산하고 맞아야 될 거 아닙니까? 그러면 북부권 지역발전을 위해서 하려면 그쪽 균형발전기획실에서 세우는 것이 아니라 본청 쪽에서 예산편성권이 있지 않습니까? 그런데 그때 과연 남경필 지사님께서, 이게 언제 시작해 가지고 언제 끝날지 모르겠지만 저는 그런 걱정이 되는 거죠. 잘못하면 전시행정 되는 거 아니냐. 이거 시작해 가지고 하다 보면 걸음마도 걷지 못한 단계에서 혹시 예산이 수반 안 돼 가지고 이것이 휴지조각 되지 않을까 이런 염려가 되는 거예요. 왜냐하면 지금 돈이 얼마가 될지 모르니까, 어마어마한 돈이 들어갈 것 같은데 우리 원장님께서 이 계획 세우실 때 정말 예산이 수반돼 가지고 손발이 맞아야만 되기 때문에 제가 이런 말씀을 드리겠습니다. 아무리 집을 잘 지으려고 설계를 꾸몄지만 건축주가 돈이 없으면 업자 선택 못 하지 않습니까? 그래서 제가 그런 노파심에서 말씀을 드리기 때문에, 원장님께서 잘하시겠지만 계획대로 정말 남경필 지사님께서 우리 경기북부권에 대해서 그 열악한 환경을 정말 좋게 만들어 가지고 우리 북부주민들이 보다 안락한 삶을 살기 위해서 하시는 거기 때문에 철저하게 계획을 세우셔서 차질이 없게 해 주시기를 바라겠습니다.
</p>
<p style="padding-left:1.2em">  한 가지만 제가 말씀드릴게요. 간단하게 한 가지만 말씀드리겠습니다. 연구보고서를 홈페이지에 게재하게 돼 있죠?
</p>
<p><b>○ 경기연구원장 임해규 </b> 그렇습니다.
</p>
<p><b>○ 이현호 위원 </b> 그런데 혹시 게재했다가 삭제한 그런 일은 없습니까?
</p>
<p><b>○ 경기연구원장 임해규 </b> 아마 지난번 제가 여기 상임위에서 한번 보고말씀 드렸던 것 같은데 한 건이 있었습니다, 제가 취임하고 난 다음에요. 그런데 그때 따복공동체 관련해서 연구보고서는 아니고 간단한 현황브리프 같은 형식의 글을 하나 실었는데 그게 시기적으로 좀 원고작성 시점하고 실제 그 당시하고 상황이 좀 많이 달라져서 자칫 오해가 있을 것 같아서 잠깐 글을 내린 적이 있었습니다. 그때 한 번 홈페이지에 게재했다가 내린 사례가 하나 있습니다.
</p>
<p><b>○ 이현호 위원 </b> 앞으로는 이런 일이 없도록 해 주시기를 부탁드리겠습니다.
</p>
<p><b>○ 경기연구원장 임해규 </b> 그러겠습니다.
</p>
<p><b>○ 이현호 위원 </b> 이상 마치겠습니다.
</p>
<p style="padding-left:2.4em">    (배수문 위원장, 임병택 간사와 사회교대)
</p>
<p><b>○ 위원장대리 임병택 </b> 수고하셨습니다. 위원님들 동의해 주시면 이제 추가질의 시간입니다. 원장님께서 자리에 앉으셔서 답변을 해도 좋으시겠습니까?
</p>
<p style="padding-left:2.4em">    (「네.」하는 위원 있음)
</p>
<p style="padding-left:1.2em">  원장님께서는 자리에 앉으셔서 답변을 하시죠.
</p>
<p><b>○ 경기연구원장 임해규 </b> 네, 감사합니다.
</p>
<p><b>○ 위원장대리 임병택 </b> 저기 테이블을 치우도록 하세요, 앞에. 다음 추가질의는 이재준 위원님께서 해 주시겠습니다.
</p>
<p><b>○ 이재준 위원 </b> 이재준 위원입니다. 제가 자료요청한 게 3년 동안 홈페이지 비공개 자료현황 및 사유를 부탁을 드렸었는데요. 지금 보면 아직까지도 한 67% 정도 공개를 했고 나머지를 안 했는데 그 이유가 뭔가요?
</p>
<p><b>○ 경기연구원장 임해규 </b> 저희들이 그간 아마 백이십 몇 건인가 있는데 두 차례 걸쳐서 해제를 많이 했습니다. 그리고 나머지 부분은 정보공개법에 따라서 저희들이 검토를 했습니다. 그런데 크게 분류를 하면 저희들이 수탁과제의 경우는 지식재산 소유권이 저희들에게 없습니다. 그렇기 때문에 수탁기관에서 비공개, 그러니까 저희가 홈페이지에 올릴 권한 자체가 일단 없습니다. 그것은 수탁과제니까 줘야 됩니다. 그래서 그 경우는 당연히 저희들에게는 연구했다는 목록만 있지 그 과제물을 저희 홈페이지에 올릴 수 없습니다.
</p>
<p><b>○ 이재준 위원 </b> 그건 아는데 우리 정책과제로 해서 우리 도와 협의 때문에 못 하는 것들이 상당히 많이 있어요. 2010년도에 보면…….
</p>
<p><b>○ 경기연구원장 임해규 </b> 그렇습니다. 그런데 그런 경우는 그 사업을 아직까지 발표하기 전 단계에서 발표를…….
</p>
<p><b>○ 이재준 위원 </b> 예를 들면 2010년도에 도립대학 설립방안에 대해서 했는데 아직까지도 공개를 안 하고 있고 그러고 또…….
</p>
<p><b>○ 경기연구원장 임해규 </b> 도립대학…….
</p>
<p><b>○ 이재준 위원 </b> 95번에 2010년도에 한 것 경기도립대학 설립방안에 대해서 공개를 안 하고 있고 그리고 또 2015년 7월 달에 23건을 추가로 해제했는데 그것도 올해 6월 달인가 5월 달인가 언론에 누가 취재를 해서 내가 얘기를 한 적이 있어요. 그래서 보도가 한 번 됐었어요. 그 이후에 이게 또 23건이 추가로 공개가 된 건데 공개원칙을 정해서 도에서 내지는 우리 자체적으로 정책적으로 한 거 같으면 3년이 지나면 의무적으로 공개한다든지 5년이 지나면 의무적으로 공개한다든지 이런 뭐가 좀 있어야지, 이거 오래된 거고 그렇게 민감한 사항도 아닌데 이걸 구태여 공개하지 않아야 될 이유가 있는지요?
</p>
<p><b>○ 경기연구원장 임해규 </b> 한두 건의 사례가 어떤지는 잘, 제가 왜 그랬는지는 추가 답변드리겠습니다만 저희들이 그 원칙은 분명히 정했습니다. 그러니까 저희들이 공개할 수 있는 권한 있는 모든 연구분은 공개하고, 공개를 원칙으로 한다 이렇게 하고 비공개할 때는 법적으로 비공개해도 괜찮은 것만 비공개로 하기로 했습니다, 그것은 정보공개법에 따라서. 그렇기 때문에 저희들이 경기도청에서 물론 진행 중인 사업 이렇게 하는 것은 정보공개법에도 그런 것은 공개를 하지 않도록, 일정기간입니다. 일정기간 공개하지 않도록 돼 있습니다, 그런 경우도. 그래서 전부 다 법에 따라서 엄격하게 잣대를 대도록 돼 있고 더군다나 저희가 이번에 변호사 겸 법학박사를 고용했기 때문에 저희들이 검토를 내부적으로 그렇게 하고 있습니다, 엄격하게 하고 있습니다. 
</p>
<p><b>○ 이재준 위원 </b> 어쨌든 공개를 해 주시고 그리고 꼭 비공개로 해야 될 이유가 없다면 그걸 정해서 3년이면 3년, 5년이면 5년 이후에는 다 공개하는 걸로 뭔가 검토가 있었으면, 그러니까 그렇게 해 줬으면…….
</p>
<p><b>○ 경기연구원장 임해규 </b> 비공개 사유가 없어지면 즉각 공개할 수 있도록 저희가 내부적으로도 그렇게 딱딱 정해서 하고 있습니다.
</p>
<p><b>○ 이재준 위원 </b> 그리고 제가 또 추가자료 요청을 했던 게 있었는데 지역개발기금, 도금고 선정, 재정적 효율운영 방안, 공기업 효율성 증대, 산하단체 통폐합, 지방정부 고용확대 방안 이런 여러 가지 자료를 요구했었는데 그중의 하나가 지역개발기금에 대한 것은 하나를 했더라고요. 지역개발기금을 활용한 공동주택 노후배관 교체사업 해서 2013년도에 했는데 사실상 이때 좀 더 면밀하게 검토가 됐다면, 이때부터 뭐가 있냐면 지역개발기금이 우리 도에 누적이 돼요. 빌려가는 것들을 조금씩 덜 해 가지고 지금 같은 경우 1조 원이 남아 돌아와서 이제는 받지 말자 이런 논의까지 오고 있는데 사실상 지역개발기금을 활용하는 방법이 경기도에는 지금 전무합니다. 그래서 자체적으로 이 돈을 쓰지도 못하고. 그러기 때문에 사실 이때 좀 더 면밀하게 흐름을, 추세를 관찰했더라면 그것을 어떤 방법으로, 그리고 이거 노후배관도 쓰지를 못해요, 하나도 안 빌려가요. 안양시에서 조금 빌려갔었는데, 왜 그러냐면 시군에 부채로 잡히기 때문에 그걸 민간업자들한테 빌려주고 이렇게 할 수 있는 방법이 없기 때문에. 그래서 좀 더 이 부분에 대해서 지역개발기금 자체의 활용 방안이 그때 검토가 됐더라면 지금 같은 상황은 안 오지 않았겠느냐 이런 생각이 듭니다. 그러니까 할 때 좀 더 심층적으로 해 주셨으면 좋겠다는 말씀을 드리고.
</p>
<p style="padding-left:1.2em">  그리고 주거복지문제 이건 검토해서 보고서를 냈다는 그 내용을 제가 간단히 요약분, 앞에 있는 것만 봤어요. 그거에 대해서 설명을 좀 해 주실 수 있습니까?
</p>
<p><b>○ 경기연구원장 임해규 </b> 지역개발기금 활용…….
</p>
<p><b>○ 이재준 위원 </b> 아니, 주거복지문제.
</p>
<p><b>○ 경기연구원장 임해규 </b> 주거복지 관련된 연구도 저희들이 몇 건을 했기 때문에 어떤 연구물을 말씀…….
</p>
<p><b>○ 이재준 위원 </b> 주거복지기금을 설립해서 확충을 해서 주거복지를 확대해야 된다는 논문이 있더라고요, 그 연구자료가. 그런데 아시다시피 우리 도에서는 주거복지기금을 지금까지 단돈 한 푼도 적립한 적이 없고 그리고 이번에 조례 개정한 것까지도 사실상 부동의해 가지고 재의요구를 했어요. 이런 상황이 왔는데 사실상 그러면 연구소에서 한 자료하고 지금 집행부 하는 것이 다르거든요, 입장들이. 그래서…….
</p>
<p><b>○ 경기연구원장 임해규 </b> 그런데 위원님 아시다시피 저희 연구원에서 하는 것들이 도에서 다 받아들이거나 그렇지 않습니다.
</p>
<p><b>○ 이재준 위원 </b> 그렇죠. 그래서 그 정확한 내용을 좀 알고 싶어서.
</p>
<p><b>○ 경기연구원장 임해규 </b> 그럼 그 자료를 저희들이 드리도록 하겠습니다.
</p>
<p><b>○ 이재준 위원 </b> 아니, 그 자료는 볼 수 있어요, 저희들도. 홈페이지에 들어가면 있으니까. 그것이 아니라 그런 것들이 집행부랑 어떻게 조율을 통해서 우리가 주거복지를 확대할 수 있냐 이런 부분에 대해서 더 알고 싶어서 얘기를 하는 거죠.
</p>
<p><b>○ 경기연구원장 임해규 </b> 그런데 제가 그 연구가, 그러니까 이게 연구를 누가 의뢰했느냐가 우선 제일 중요합니다. 보통 도가 의뢰를 했을 경우는 도가 의뢰를 해서 연구를 저희들이 수행했다 하더라도 그것을 도가 전부 정책으로 받아들이지는 않습니다. 왜냐하면 도도 타당한가를 한번 보고 최종의사결정은 또 도에서 하게 되니까요, 저희는 연구수행을 해 줄 뿐이죠. 그런데 애초에 연구를 의뢰한 사람의 의도대로 현실이 아니라는 것이 연구를 통해서 밝혀지면 정책을 포기하게 되는 경우도 많이 발생하고 저희들이 자체 발굴해서 하는 연구도 꽤 많습니다, 자체 발굴. 그런데 그런 경우는 사실 도에서 채택하는 비율이 그리 높지는 않습니다. 그런 경우는 서로 의견이 달라서 그럴 수도 있고 타이밍이 안 맞아서 그럴 수도 있고. 그래서 방금 말씀하신 주택기금 같은 경우는 어떤 건지 제가 좀 더 파악을 해 봐야 될 것 같고요. 그런데 그대로 되는 경우는 잘 없습니다. 그리고 다를 경우에는 보통 저희들이 연구한 거는 도의 해당부서에 다 가기 때문에 해당부서랑 상당한 논의를 합니다. 왜냐하면 박사가 3~4개월에 걸쳐서 상당히 열심히 연구한 것들이기 때문에 박사로서도 그게 사장되면 안 되기 때문에 설득도 하기도 하고 또 논의를 깊이 합니다. 그런데 그 과정이 어떻게 됐느냐는 제가 지금 파악하고 있지 못하기 때문에 지금 바로 답변드리기는 어려울 것 같습니다.
</p>
<p><b>○ 이재준 위원 </b> 알겠습니다. 이상 마치겠습니다.
</p>
<p><b>○ 위원장대리 임병택 </b> 수고하셨습니다. 박재순 위원님 추가질의해 주십시오.
</p>
<p><b>○ 박재순 위원 </b> 박재순 위원입니다. 첫 번째, 경기도 물에 관해서 좀 한번 여쭤보겠습니다. 우리가 팔당상수원 보호구역에 있는 물을 먹고 있는데 사실 이 물 우리가 직접 먹어도 괜찮나요? 수돗물을 직접 지금 먹어도 괜찮은지?
</p>
<p><b>○ 경기연구원장 임해규 </b> 보통 저는 끓여 먹습니다.
</p>
<p><b>○ 박재순 위원 </b> 끓여 먹습니까?
</p>
<p><b>○ 경기연구원장 임해규 </b> 네, 저는 식수로는 보통 끓여 먹고, 물론 음식물을 만들거나 이럴 때는 그냥 그대로 씻어서 조리하는 데는 그냥 사용하고 음용을 하는 경우는 보통 끓인 물을 먹습니다. 그런데 그게…….
</p>
<p><b>○ 박재순 위원 </b> 지금 원장님 경우만 그런 거고.
</p>
<p><b>○ 경기연구원장 임해규 </b> 일반적으로 그런 걸로 저는 이해하고 있습니다.
</p>
<p><b>○ 박재순 위원 </b> 그다음에 우리 연구원에서 발표한 그런 자료에는 어떻게 나와 있나요?
</p>
<p><b>○ 경기연구원장 임해규 </b> 저희들도 상수도의 음용률을 높이기 위한 그런 연구를 저희들 하고 있습니다. 그러니까 아마도 국민정서와 그리고 실제로 상수관의 노후도나 이런 것들 때문에 또 아파트 같은 데는 위에 있는 관 같은 게 청소상태가 안 좋은 경우나 이런, 물이 만들어지는 단계에서는 일정한 정도의 정수처리가 돼서 음용할 수 있는 수준이라 하더라도 그것이 가정으로까지 운반되는 과정에 여러 가지 이물질이 포함될 가능성이 높기 때문에 매우 국민들이 두려워하고 바로 음용하는 데 어려움을 겪고 있는 게 사실입니다. 그래서 그것을 음용률을 높이기 위한 다양한 연구를 저희들이 수행하고 있는 것이죠.
</p>
<p><b>○ 박재순 위원 </b> 그래서 서울 같은 경우는 관 길이가 아무래도 짧겠죠, 우리 경기도는 내려오면 내려올수록 관 길이가 넓어지고. 쉽게 말하면 관이 녹슬 확률이 더 많다는 거잖아요? 그래서 음용 자체가 수질이 나빠질 거라고 생각을 하고 있는 그런 부분들이 많기 때문에 직접 음용을 안 하고 현재 생수를 사서 먹고 있는 이런 실정이지 않습니까?
</p>
<p><b>○ 경기연구원장 임해규 </b> 그렇습니다.
</p>
<p><b>○ 박재순 위원 </b> 그죠? 그래서 지금 연구원에서 연구를 할 때 사실은 거기에 있는 수질, 물만 가지고 연구를 할 것 같은데, 팔당상수보호구역 안에 있는 것만.
</p>
<p><b>○ 경기연구원장 임해규 </b> 그렇지 않습니다.
</p>
<p><b>○ 박재순 위원 </b> 그렇지 않습니까?
</p>
<p><b>○ 경기연구원장 임해규 </b> 상수관과 관련된, 그러니까 수도꼭지 음용률, 수도꼭지에 얼마만큼 청정한 물인가 이런 관점에서 우리 상수도만 연구하는 박사님 계시거든요. 그런데 그런 관점에서 어떻게 하면 음용률을 높일 건가 하는 연구를 종합적으로 하고 있습니다.
</p>
<p><b>○ 박재순 위원 </b> 그래서 각 지역에, 쉽게 말하면 우리 같은 경우에는 안성, 평택, 수원 이런 멀리 있는 곳도 함께 해 주어야 좀 보편 타당적이고 검증된 그런 자료가 나오지 않을까 싶어서 말씀드렸고. 또 이제 우리 의회 안에서도 음용을 해야 하는 이런 시점이 되다 보니까 조금은 꺼림칙하지만 그래도 음용을 해야 되는 그런 시스템이 되어 있지 않습니까? 그래서 우리 의회뿐만 아니라 공공기관, 산하기관 모든 곳이 다 아마 음용으로 될 것 같은데 이 부분에 대해서 원장님 입장에서 한 말씀 간단하게 얘기해 주시기 바랍니다.
</p>
<p><b>○ 경기연구원장 임해규 </b> 상수도의 음용률을 높이기 위한 연구가 저희들 연구원에서도 굉장히 중요한 정책과제입니다. 앞으로 그것이 전부 다 예산이 뒷받침돼야 되는 것들이거든요, 또. 그래서 연구하는 박사님 말씀으로는 상수도 요금을 계속 이렇게 묶어둬서는 굉장히 어려움이 있다. 왜냐하면 도 재정으로만 가지고는, 이게 시군 재정으로 또 해야 되잖아요. 그러니까 그 재정으로만은 여러 가지 어려움이 있어서 그래서 물을 또 함부로 쓰는 경우도 있다. 그래서 종합적으로 이렇게 해서 실제로 서민들이 편안하게 물을 마실 수 있도록 그렇게 하는 것에 가치를 두고 연구를 많이 하도록 그렇게 하겠습니다.
</p>
<p><b>○ 박재순 위원 </b> 사실은 우리 시민이든 국민이든 물에 대한 중요성을 가장 중요하게 여겨야 되는데 그렇게 중요하게 여기질 않고 있죠. 말 그대로 좀 편리하게 쓰다 보니까 이런 문제가 나온 것 같은데 앞으로는 그런 문제들이 잘 해결될 것을, 또 노후상수도관 이런 것이 잘 해결될 것을 전 기대하고 있습니다.
</p>
<p style="padding-left:1.2em">  그리고 또 하나 신성장산업에 관한 연구 중에서 무인항공기에 대한 연구자료를 해 보신 적이 있나요?
</p>
<p><b>○ 경기연구원장 임해규 </b> 경기도 전략산업연구라고 그것을 아까 여러 위원님 지적하셨는데 저희들이 위탁해서 경기도의 주요한 전략산업이 무엇이어야 될 건가 하는 점에 대해서 전략연구를 한 바가 있습니다. 거기에 이런 초정밀 기계산업이 우리 경기도에서 굉장히 유망하다는 취지의 그런 연구를 한 바가 있습니다.
</p>
<p><b>○ 박재순 위원 </b> 그 전략산업에는 드론이 들어있지를 않았었어요. 들어있지 않고 거기에 아이로봇, 산업로봇, 가구산업 일부 조례로 제정돼서 나와 있는 그런 상황인데 연구원에서 결국은 대한민국 또 조그마하게 생각한다면 우리 경기도잖아요? 그러면 성장산업에 대한 어떤 연구, 앞으로 먹거리를 찾아야 되는 그런 부분이라고 저는 봅니다. 그래서 이 드론에 관해서 지금 세계에서도 또 우리 경기도뿐만 아니라 대한민국 전체의 지자체 단체장님들이 드론산업에 대한 열망을 갖고 있고 많은 연구를 하고 있고 자기 센터나 이런 건립에 관해서 또 앞으로 세계시장을 향해서 가는데 중국이 기본적인 장난감 이런 드론시장이 한 80%를 차지하고 있습니다, 현실적으로. 우리나라에도 한 80%가 들어와 있는 그런 실정이고. 그런데 우리 경기도 입장이나 대한민국 입장에서는 법률적, 제도적 이런 기반이 전혀 돼 있질 않아요. 그런데 우리 연구원에서나마 그래도 이 부분에 대해서 연구를 해 보고 미래의 성장동력산업이 먹거리산업으로서 나아갈 수 있는 방향이나 정책이나 이런 것 뒷받침해 줄 수 있는 그런 제도적인 보완을 좀 마련해야 된다고 본 위원은 생각하는데 원장님 입장은 어떠신지 말씀해 주시기 바랍니다.
</p>
<p><b>○ 경기연구원장 임해규 </b> 저도 동의합니다. 그리고 관련해서 사실 저희가 거의 매년 한 건 정도는 경기도 미래전략산업이 뭔가 하는 연구를 우리 상생경제실에서 계속 수행해 오고 있습니다. 왜냐하면 세상이 하도 빨리 바뀌니까 또 중국하고 경쟁해야 되는 측면도 있고 그래서 우리 강점이 뭐고 약점이 뭐고 어떤 거는 우리가 선도적으로 해야 되고 이런 연구는 꾸준히 하고 있습니다. 그래서 앞으로도, 마침 또 특정한 산업분야 한 가지를 말씀해 주셨기 때문에 저희들이 그 분야도 그 단일과제를 정책연구로 하기는 쉽지 않다 하더라도 전략연구와의 연관성 속에서 드론산업의 전망이라거나 이런 것은 단기적이고 작은 과제로서는 충분히 수행할 수 있거든요. 그래서 그런 것은 한번 저희들이 연구수행을 해 보도록 하겠습니다.
</p>
<p><b>○ 박재순 위원 </b> 원장님께 왜 이 말씀을 드리냐면 본 위원이 조례에 입법예고해서 지금 대기 중에 있습니다, 어쨌든 간에. 그런데 경기도 차원에서도 이 신성장산업에 대해서 한 번쯤은 걸러주어야 된다고 하고 있고 지금 연구자료를 1년에 한 번씩 내놨다고 이렇게 말씀을 하셨습니다. 그래서 그 자료 본 위원한테도 보내주셨으면 좋겠다는 말씀드리고요. 이 신성장산업이 우리 경기도와 앞으로 산업에 있어서 또 학계와 함께하는 그런 연구로서 발전시켜서 앞으로 우리가 정말 SF영화 봤었을 때 차 없는 거리를, 그냥 가는 거죠. 사람이 타지 않은 차를 탄다든지 비행기를 탄다든지 이런 제도가 앞으로 우리 눈앞에 머지않아 펼쳐질 거라고 본 위원도 생각하고 있고 지금 그것이 초기단계이기 때문에, 우리 경기도에는 IT산업이라는 게 현대전자, 삼성전자, LG전자 다 뒤에 있습니다. 그래서 이런 융복합산업이 잘될 수 있도록 한번 연구를 잘해서 자료적으로, 앞으로 좀 했으면 좋겠다고 생각합니다. 그래서 원장님께서도 이 부분에 각별한 관심을 가지시고 경기도의 발전을 위해서 또 대한민국의 발전을 위해서 좀 노력해 주셨으면 좋겠다는 말씀을 드리겠습니다. 이상으로 질의를 마치겠습니다.
</p>
<p><b>○ 경기연구원장 임해규 </b> 고맙습니다.
</p>
<p><b>○ 위원장대리 임병택 </b> 수고하셨습니다. 장동일 위원님 질의해 주시기 바랍니다.
</p>
<p><b>○ 장동일 위원 </b> 원장님, 올해가 이제 지방자치 부활 20년이고 해서요. 늘 저희들이 이 부분에 대해서 얘기가 있어 왔는데 또 의미 있는 올해이고 해서 제가 다 아는 내용이지만 한 번 더 말씀을 드려보도록 하겠습니다. 늘 이게 문제가 되는데 지방세감면, 국세하고 감면하더라도 지방세를 더 많이 한단 말이죠, 안 그래도 재정이 열악한데. 지방세법, 지방세특례제한법 등등을 통해 지방세를 감면하고 있는데, 작년인가요? 지방세를 감면하고자 할 때는 지방자치단체의 의견을 의무적으로 듣도록 하는 조항이 생긴 걸로 알고 있는데 그것이 실제로 별로 효력이 없다고 합니다. 그냥 형식적인 절차에 불과하고. 지금 지출은 6 대 4로 거꾸로 되어 있는데 늘 우리가 얘기하는 8 대 2 지방재정도 시간이 흘러가도 조금도 변화가 없고. 그래서 지방세수 확보 차원에서 양도세를 지방세로 전환하는 문제는 안 되는 건가요? 국세인 양도세 부분은? 그런 부분에 대해서 연구가 한번 있어 봤습니까? 
</p>
<p><b>○ 경기연구원장 임해규 </b> 우리 지방세 거는 말하자면 조세 자주권이죠. 조세 자주권을 강화하기 위해서 어떤 세는, 지방소비세도 말하자면 그런 차원에서 도입되고 이렇게 한 건데 어떤 세를 지방세로 하고 또 방금 말씀하신 것처럼 지방세 감면을 결정하는 것을 지방에서 하도록 저희들이 최근에 그 용역도 했습니다. 그래서 그런 거는 이 분야 전문가가 답하는 게 좋을 것 같습니다. 제가 좀 약간 엉터리로…….
</p>
<p><b>○ 장동일 위원 </b> 한번 들어보겠습니다.
</p>
<p><b>○ 경기연구원장 임해규 </b> 송상훈 실장.
</p>
<p><b>○ 공존사회연구실장 송상훈 </b> 공존사회연구실장 송상훈입니다. 소득세의 지방세에 대해서 많이 말씀하시는데 외국의 사례에서나 뭐나 양도소득세라는 거는 재산이 소득으로써 실현됐을 때 과세하는 것이기 때문에 이 부분은 다 소득으로 잡히기 때문에 소득세로 포함이 되는 겁니다. 그런데 그런 점에서 양도소득세 같은 경우에 지방세로 하기에는 어렵다. 또 양도소득세의 주체가 아무래도 소유자하고 물건지하고 사실은 굉장히 상이한 그런 부분들도 있기 때문에 그런 점에서 결국은 여러 가지 문제점들은 있습니다마는 지금 현재로써는 양도소득세에 대한 주장은 있습니다만 제가 볼 때 양도소득세는 지방세 성격으로써는 맞지 않은 부분이 없지 않아 있다. 그래서 차라리 다른 소득세나 법인세에 대한 부분에 공동세적인 성격을 좀 강화하는 편이 차라리 낫지 양도소득세 같은 경우 더더욱이나, 취득세와 양도소득세는 사실은 동전의 양면입니다. 한 번은 살 때 지불하는 거고 한 번은 팔 때 지불하는 거기 때문에 이 부분은 향후에서도 서로 어떤 형태로든지 조정이 돼야 되는 부분이기 때문에 이런 부분은 지방세로서 볼 때 그렇게 큰 실익은 없지 않을까 하는 그런 제 판단입니다. 저희 부서의 연구자들의 입장은 그런 스텐스를 가지고 있습니다. 
</p>
<p><b>○ 장동일 위원 </b> 지방세수 확보하는 획기적인 무슨 방안을 연구하셔야 될 텐데.
</p>
<p><b>○ 공존사회연구실장 송상훈 </b> 사실은 지방세, 우리나라가 조세법률주의이기 때문에 사실 지방에서 아무리 의견을 제시해도 국회를 통과하지 않으면 방법이 없는 현실적인 제한이 굉장히 있습니다. 그래서 지금 분권헌법에 대해 지방자치단체에서 많이 이야기하고 있습니다. 분권헌법에 대해서, 재정자주권에 대해서 지방이 스스로 과세권을 행사할 수 있는 그런 제도가 마련된다면 지역에 따라서는 사실 지역이 가지고 있는 여러 가지 자원이 있기 때문에 거기서 소득이 발생할 수 있고 그다음에 국세에 대한 공동세적인 역할을 해야 되는데 현재로써는 국가도 재정이 어렵다고 하기 때문에 지금 사실 말하자면 일종의 동일한 파이를 두고 지방이 많이 가져가느냐 국가가 많이 가져가느냐 이런 싸움이 벌어져 있는 상태라 결국은 쉽지 않을 것 같습니다. 
</p>
<p><b>○ 장동일 위원 </b> 조세감면 이런 부분들에 대해서 국회 또 기재부, 행자부 이런 데가 서로 잘 모르는데 지방세 부분은 행자부가 업무를 거의 하죠. 그런데 어떻게 된 게 서로 협의도 안 되고 정보공유도 안 된다는 거예요. 
</p>
<p><b>○ 공존사회연구실장 송상훈 </b> 제가 올해는 아닙니다만 올 초였는가 지방세감면심의위원회 행자부에서 심의했습니다. 그때 여러 가지 감면해야 될 사항들에 대해서 이건 더 이상 감면해서는 안 된다라고 의견을 폈었는데 기재부 차원에서도 반발이, 그 내용이 무시된 경향도 있지만 지방 차원에서도 해당되는 예를 들어서 병원이라든지 이런 거 같은 경우에 지방 차원에서도 로비가 들어갔는지 아니면 지방의 이해관계에 따라서 일부 반대하는 경향이 나타나고 있었습니다. 그러다 보니까 결국은 감면율 일몰제를 적용시키려고 했던 게 또 그대로 연장되는 그런 경향이 없지 않아 있었습니다. 그래서 심의위원회에서 결정을 해도 구속력을 가지고 있지 않기 때문에, 강제사항이 아니기 때문에 한계는 있는 것으로 알고 있습니다.
</p>
<p><b>○ 장동일 위원 </b> 시간이 돼서 이상입니다.
</p>
<p><b>○ 공존사회연구실장 송상훈 </b> 고맙습니다.
</p>
<p><b>○ 위원장대리 임병택 </b> 다음 질의는 김호겸 위원님 해 주십시오.
</p>
<p><b>○ 김호겸 위원 </b> 김호겸 위원입니다. 오전에 존경하는 최지용 위원님도 말씀을 주셨었고 우리 임두순 위원님도 말씀 주신 사항인데요. 지금 화성의 화장장시설 연구를 했던 부분 잘 아시죠? 원장님, 보고는 받으셨나요?
</p>
<p><b>○ 경기연구원장 임해규 </b> 네, 대충 흐름은 알고 있습니다. 
</p>
<p><b>○ 김호겸 위원 </b> 흐름 알고 계시죠. 지금 화성 숙곡리라는 지역에 5개 지자체에서 공동으로 유치해서 공동화장장을 짓기로 해서 아마 방송에 보도 나온 걸로는 모범적인 사례로 손꼽혀왔죠. 2017년도에 아마 착공하는 걸로 했는데 현재 수원 지역에서 반대가 있어 가지고 상당히 어려움에 처해 있는 것 같아요, 이 사업이. 주민갈등이 심화돼 가지고. 그래서 경기도에서도 중재역할을 포기한 것 같고 지금 수원시에서 주민의 정서상 어렵다 그렇게 얘기가 된 것 같아요. 그런데 화장장이 아까도 말씀 주셨다시피 연구과제로 하셨네요? 경기도 장사시설 중장기 수급에 관한 연구, 화장시설의 환경영향분석 및 관리방안 연구 등등 했는데 중장기 수급계획에 관한 거는 적절한 연구과제가 아닌가 이런 말씀드리면서 장사시설 들어오면 주민갈등 그게 상당히 심각해요. 그래서 갈등에 관한 문제도 화성시에서 기록을 한 게 있네요. 갈등해소전략이라든가 이런 것들이 나와 있는데 갈등 최소화 방안 등등 기록이 되어 있습니다. 그런데 지금 가장 중요한 게 환경오염에 관한 문제 아닙니까? 환경오염에 관한 문제인데 저는 전문가가 아니라 잘 모르겠습니다만 담배 한 개비 정도에서 나오는 그런 성분도 안 된다 이런 어떤 저기도 본 것 같애.
</p>
<p><b>○ 경기연구원장 임해규 </b> 다이옥신 배출량이…….
</p>
<p><b>○ 김호겸 위원 </b> 다이옥신 배출량이 담배 한 개비에서 나오는 양도 안 된다 그런 얘기도 들은 것 같아요. 그래서 환경오염에 관한 거는 큰 문제가 안 되는 것 같은데 주민정서상 그런 것들이 가장 문제인 것 같아요. 어떻게 생각하세요, 원장님은?
</p>
<p><b>○ 경기연구원장 임해규 </b> 일단 환경적 측면은 그 시설이 특별한 하자가 없고 결함이 없고 이렇다고 하면 사실 환경적인 문제는 상당부분 기술적으로 처리가 되는 걸로 이해가 됩니다. 그리고 말씀드린 것처럼 애초에 시설 입지하는 바로 이해관계가 걸려있는 주변의 주민들과는 공모과정을 다 거치기 때문에 주민 동의하에 하지만 주로 이런 시설이 경계, 시와 시에, 시군 간 경계지역에 보통 놓여있습니다. 그러다 보니까 인접 시의 영향권에 있지 않다고 생각한 인접 시의 주민이 그 길을 타고 들어와야 되기 때문에 보통 반대를 하거나 아니면 그 거리가 영향을 받는 거리라고 주장하기 시작하면 일이 굉장히 힘들어지는, 갈등이 유발되는 케이스입니다. 따라서 주민정서 문제죠. 그리고 피해가 있다고 생각하는 주민정서 문제고 또 그 길을 이용하게 될 경우에 길의 혼잡이나 이런 것들로 인한 피해를 이야기할 수 있고. 그래서 사실은 이런 문제가 단지 주민을 탓할 문제는 아니라고 생각합니다. 왜냐하면 사실은 정책을 입안하고 실시할 때 광범위하게 영향을 미칠 수 있는 주민 또 문제가 될 만한 소지가 있는 주민들 전체에 대해서 인센티브를 제공하는 방안이라든지 또는 인센티브를 제공하는 또 다른 시설의 입지를 동시에 고려한다든지 이런 다각적인 갈등해소 방안을 함께 그 정책에 포함하는 것이 어떤 갈등을 유발하지도 않고 갈등유발 예방효과도 있고 갈등이 유발된다 하더라도 그것을 해소할 수 있는 좋은 방안이 될 수 있을 거라고 생각합니다. 그게 갈등해소에 대한 저희 연구결과를 제가 요약해서 말씀드린 겁니다. 
</p>
<p><b>○ 김호겸 위원 </b> 화장은 선호하면서도 시설은 반대하는 이런 현상이죠. 
</p>
<p><b>○ 경기연구원장 임해규 </b> 님비현상이죠.
</p>
<p><b>○ 김호겸 위원 </b> 님비현상이죠. 그래서 본 위원이 말씀드리고 싶은 것은 대도시 서울이나 성남 같은 데도 화장장이 도심 한가운데 있습니다. 그래서 제가 말씀드리고 싶은 것은 뭐냐 하면 우리 화성시 장사시설 수급계획의 근거, 그 연구내용을 기초로 해서 사실 지자체 간의 갈등인데 이게 본 연구원에서 이런 내용들을 근거로 해서 갈등관계를 조정한다든가 치유할 수 있는 역할 없을까요, 혹시?
</p>
<p><b>○ 경기연구원장 임해규 </b> 그거는 사실 저희 연구결과에 의하면 결자해지죠. 그러니까 그 문제를 유발한 데가 있으니까요. 유발한 곳이 반대하는 곳까지를 포함해서 갈등을 조정하고 해결하려고 하는 1차적인 노력을 기울여야 된다고 보고요. 그리고 거기에는 갈등을 해결하는 전문가들이, 그게 단 시간에 갈등해결이 잘 안 되지 않습니까? 그래서 장기간에 걸쳐서라도 거기서 최대한 피해라고 느끼는 거에 대해서 서로가 과학적이고 합리적으로 대화하고 또 피해라고 느끼는 거에 대한 또 다른 인센티브 방안이 뭐가 있을 것이다 이래서 협의하고 또 그 과정에 인근에 있는 지자체들도 남 일이라고 생각하지 않고 함께 협심해서 그 문제를 풀려고 머리를 맞대야만 특히 화장장과 같이 매우 필요한 시설인데 이렇게 사업이 시행되지 않는 것을 극복할 수 있다고 생각합니다. 
</p>
<p><b>○ 김호겸 위원 </b> 지금 이게 지자체 간에 상당히 갈등이 심화돼서 최근에 보게 되면 화성시와 수원시가 상당히 멀어졌습니다, 관계가. 관계가 멀어진 걸로 알고 있는데 그런데 이게 장기간 표류될 가능성도 있고 자칫하면 백지화될 가능성도 있을 수도 있을 것 같아요, 이게. 그래서 우리 연구원에서 연구결과도 있고 또 경기도 최고의 연구기관으로서 신뢰를 바탕으로 해서 이런 부분도 우리가 나서서 갈등을 치유하고 조정할 수 있는 방법 없을까 그런 의미에서 말씀드린 거니까 한번 고민해 주시면 고맙겠습니다. 
</p>
<p><b>○ 경기연구원장 임해규 </b> 그렇게 하겠습니다. 
</p>
<p><b>○ 김호겸 위원 </b> 이상 마치겠습니다. 
</p>
<p><b>○ 위원장대리 임병택 </b> 추가질의 몇 분 더 계시는 것 같은데요. 잠시 휴식을 위해서 10분간만 감사중지를 하도록 하겠습니다. 동의해 주시겠습니까? 
</p>
<p style="padding-left:2.4em">    (「네.」하는 위원 있음)
</p>
<p style="padding-left:1.2em">  감사중지 10분간 하겠습니다.
</p>
<p class=''ar''>(15시54분 감사중지)
</p>
<p class=''ar''>(16시06분 감사계속)
</p>
<p><b>○ 위원장 배수문 </b> 좌석을 정돈해 주시기 바랍니다. 감사를 계속하겠습니다. 이재준 위원님 질의하여 주시기 바랍니다. 
</p>
<p><b>○ 이재준 위원 </b> 이재준 위원입니다. 지난번에 소비자정책심의위원회에 경기연구원에서 한 분이 참석하셨죠? 버스요금 결정할 때. 경기연구원의 대표로 해서, 대리로 해서 간 겁니까, 아니면 개인자격으로 간 겁니까? 
</p>
<p><b>○ 경기연구원장 임해규 </b> 보통 심의위원회 참석하는 거는 전문가로서, 연구원의 대표적인 견해는 아니고요. 해당분야 전문가로서 심의위원회에 참석합니다. 
</p>
<p><b>○ 이재준 위원 </b> 그런데 그날 거기서 결정한 것이 뭐냐 하면 1,960억이라는 버스업체들의 이익을 3,400만 원짜리 용역으로 해서 검증한 것을 갖다 의결하는 사항이었어요. 그것이 더군다나 의회에 보고하도록 되어 있는데 보고도 안 하고 그것이 3월 19일 날 강행처리 하려다가 못하고 이렇게 된 사건인데. 그런데 그러면서 그 논점이 뭐였었냐 하면 버스요금을 얼마 올릴까였는데 그다음에 들고 나온 게 버스거리비례제를 들고 나왔고 그다음에 2년마다 한 번씩 올리자 이렇게 들고 나오면서 하여간 논점을 많이 흐렸어요. 거기에 일조한 게 경기연구원에서 가신 분이 거리비례제를 되게 찬성하셨다는 거예요. 어느 분인지 모르겠어요, 제가. 거리비례제가 맞다고 생각하십니까?
</p>
<p><b>○ 경기연구원장 임해규 </b> 버스와 같이 노선을 달리는 대중교통의 경우는…….
</p>
<p><b>○ 이재준 위원 </b> 법에 보면 10㎞ 이상이면 거리비례제를 적용할 수 있다라고 되어 있지만 경기도는 처음에 환승할인제를 할 때 일반버스는 10㎞ 넘어서 거리비례제를 적용했고 그다음에 나머지는 거리비례제를 안 하는 걸로 해서 기본요금이 높게 책정된 거예요. 그러면 이 기본전제가 다 허물어지고 다시 해야 되는 거예요. 인천 같은 경우 이번에 거리비례제를 좌석이나 광역버스도 했어요. 그래서 기본요금을 절반으로 내렸습니다. 우리는 그런 것이 아니라 기본요금은 이번에 인상된 것까지를 합친 것이 기본요금이고 거기에서 추가로 발생되는 거에 대한 거리비례제를 적용하자라고 했던 거예요. 어떻게 그런 논리들이 가능하다는 건지 저는 사실상 경기연구원에서 그 정도는 충분하게 답변해 줘야 되는 거라고 생각합니다. 
</p>
<p style="padding-left:1.2em">  이번 과정에서 무슨 문제가 있냐 하면 버스 한 대당 기본적으로 적정 운전직 인원이 그날 도정질문에서 도지사님이 발표했듯이 1.3명에서 1.7명 사이예요. 왜 그러냐 하면 버스가 휴무하는 차들이 많이 있어요. 아침에만 예비차가 뛰고 오후에는 배차간격이 길어집니다. 그래서 가동률을 보면 83%~85% 정도 돼요. 그러면 15% 정도 여유가 있기 때문에 그렇게 되는데 우리 경기도가 보면 2.0명 넘는 게 21개 업체예요. 뭐를 검증했길래 거기서 자신 있게 그런 얘기를 하냐는 거예요. 대원고속 같은 경우 4,200만 원 연봉 받아요, 평균. 운전직이. 그런 인건비를 다 똑같은 비용으로 우리는 산출합니다. 어떤 회사는 1억 7,000만 원이 임원 평균 임금이에요, 평균. 평균 인건비가 1억 7,000을 받아요, 임원이. 그런 사람들 인건비를 다 버스요금으로 정당한 경비로 인정해 주고 그걸 갖다가 “버스요금 이만큼 올려야 됩니다.”라고 했어요. 거리비례제가 손해나는 게 거리비례제를 적용하면 40억 원을 주민이 부담한다고 했어요. 그러니까 그거의 반대로 뭐냐 하면 조조할인을 얘기합니다. 조조할인을 얘기해서 37억이라는 돈을 소비자들이 수혜를 본다고 했어. 그런데 결과가 뭐냐 하면 20억도 수혜를 안 봐요. 지금까지 운행한 걸 갖고 했을 때. 그러니까 자기네들 손해본다라고 하는 것은 부풀리고 자기네들 이익 보는 건 좁혀 놓고 이런 식이란 말이에요. 청소년 버스요금 할인하면서, 조조요금 할인하면서, 조조요금이 일반버스는 해당이 안 됩니다. 청소년 현금할증료를 낮췄어요. 서울이 먼저 했어. 그러니까 우리는 낮췄는데 좌석버스나 광역버스만 했어요. 애들이 타는, 학생들이 타는 일반버스는 하나도 안 해요. 이런 엉터리 같은 것들을 어떻게 경기연구원이 검토도 안 해 주고 거기에 가서 정책을 펴는 사람이 그걸 갖다 옳다고 동의하고 거기서 거리비례제 찬성하고. 거리비례제는 논의 대상이 아니었던 걸 어떻게 그렇게 하냐고. 정당하게 걸어줘야 될 거 아닙니까, 적어도. 학자적 양심을 갖고. 그렇지 않으면 그 자리에 참석을 하지 마시든지.
</p>
<p><b>○ 경기연구원장 임해규 </b> 구체적인 정책에 대한 말씀이셔서 제가 말씀하시는 거를 소상히 이해하고 답변하기는 어렵습니다. 위원님 괜찮으시면…….
</p>
<p><b>○ 이재준 위원 </b> 답변하실 분 계시면 답변해 주시죠.
</p>
<p><b>○ 경기연구원장 임해규 </b> (관계직원을 향하여) 연구한 박사님은 안 계시죠?
</p>
<p><b>○ 휴먼교통연구실장 지우석 </b> 제가 아는 대로…….
</p>
<p><b>○ 경기연구원장 임해규 </b> 그러면 휴먼교통연구실장이 답변하도록 하겠습니다.
</p>
<p><b>○ 이재준 위원 </b> (위원장을 향하여) 답변 들을 시간 있습니까? 
</p>
<p><b>○ 위원장 배수문 </b> 네, 잠깐 하겠습니다.
</p>
<p><b>○ 휴먼교통연구실장 지우석 </b> 지금 말씀하시는 게 버스정책위원회에 대해서 말씀하시는 것 같고요. 제가 알고 있는 바로는 기본요금은 버스 같은 경우에는 일정 부분 유지를 해야 버스가, 전체적으로 경기도 같은 경우에 적자가 많이 나기 때문에 유지를 해 줘야 되고 지금 말씀하신 대로 만약에 거리비례제를 적용하는 폭을 높인다면 그야말로 수익자분담원칙에 해당되는 겁니다. 그래서 그렇게 되면 계산에 의하면 사실 부담은 버스이용자분들한테 더 돌아가면서 버스업체 입장에서는 수익이 덜 나기 때문에 경기도 입장에서는 더 지원금을 많이 해 줘야 되는 어떻게 보면 악순환 구조가 되기 때문에 버스의 기본요금을 유지하는 대신에 거리비례제를 어느 정도 도입을 하자 그런 취지에서 거리비례제가 승인된 걸로 알고 있습니다. 
</p>
<p><b>○ 이재준 위원 </b> 그러니까 논리적으로는 맞아요. 논리적으로는 맞는데 그 사람들이 버스요금을 올려야 될 만큼 그만큼 비용이 많이 들어가지 않아요, 유지비가. 운영비가. 그 운영비가 많이 들어간다는 것이 자기네들이 펑펑 쓰고 사람이 아닌, 어떤 사람을 갖다 대체해 놨어요. 세무 신고한 거하고 실제 원가계산서의 임금대장하고 차이가 얼마냐 하면 약 400억이 나요. 그만큼을 부풀리는 그런 요소들을 하나도 안 잡아내고 3,000만 원짜리 용역에다가 1,900억이라는 혜택이 가는 것을 용역을 맡겨 가지고, 검증용역을 맡겨 가지고 그걸 갖다 그대로 승인해 준 게 버스정책심의위원회란 말이에요. 
</p>
<p><b>○ 휴먼교통연구실장 지우석 </b> 지금 말씀하시는 게 경기도 버스경영평가라는 과제입니다. 
</p>
<p><b>○ 이재준 위원 </b> 그거는 경기연구원이 한 거고.
</p>
<p><b>○ 휴먼교통연구실장 지우석 </b> 저희가 3년 정도 하다가 틀을 잡아서 지금은 민간 회계업체에서 그걸 하고 있고요. 지금 위원님 말씀하신 대로 각각의 버스업체에서 그런 식의 일종의 비용조작이라든가 또 적절치 못한 그런 수익구조를 숨긴다든가 이런 걸 잡아내기 위해서 하고는 있죠, 사실은.
</p>
<p><b>○ 이재준 위원 </b> 그런데 3,000만 원 짜리 줘 가지고 3개월 해서 뭘 잡아내겠습니까? 거기다가 또 하나가 뭐냐면 버스요금을 산정할 때 우리는 총괄원가 방식을 채택하지 않고 부가가치 방식을 채택을 해 갖고 모든 비용의 10%를 이윤으로 보장해 줘요. 그러니까 경영합리화를 꾀할 필요도 없고 비용을 절감할 필요가 없어요, 다 그냥 넣어 주니까. 그런데 그것이 뭐냐면 버스요금 산정기준에 어긋난다는 거예요, 법적으로. 이번 감사결과에도 그 법을 잘못 적용했으니까 이제는 총괄원가 방식을 채택하라라고 감사결과가 나갑니다. 그런데 그런 것들이 어떻게 하나도 검증이 안 되냐는 거예요. 전문가들이 다 모여 있고 경기도에서 내로라하는 대중교통의 모든 사람들이 관여를 하고 있는데. 그러면 이런 문제에 대해서 적어도 경기도가 1년에 2,800억이라는 돈을 부담하고 있으면, 이제 더 올라갈 거란 말입니다. 거기에 이층버스니 입석대체버스니 이런 모든 문제들이 함께 맞물려서 이런 심각한 현안과제로 갖고 정확하게 산정을 해 내고 판단해 주고 입장을 정확하게 객관적으로 전달해 줘야 되는데 그 기능을 하는 데가 하나도 없고. 그 부서에 가면 1년에서 1년 반이면 다 이동을 해요, 공무원들도 가기 싫으니까. 너무나 엄청나고 업자들이 얘기하는 걸 다 믿어줄 수밖에 없으니까, 근거를 댈 수가 없으니까. 그러니까 그런 것들을 해 줄 수 있는 기관이 여기밖에 없는데 그러면 이걸 적어도 이번에 이 논의 과정 속에서 단일요금체제 하나만 갖고 얘기를 하고 있는데 거리비례제 그다음에 2년마다 한 번씩 상승 이런 것들을 들고 나온 화두가 바로 여기 계신 분들이 거기 참여해서 했다는 거예요, 거리비례제를. 그런 게 문제가 된다는 거죠. 이 부분은 제가 도정질문한 게 있어요. 도정질문한 게 있고 그 속기록 보시고 제가 얘기하는 것들이 잘못될 수도 있어요. 그렇지만 분명하게 잘못돼 있어요, 지금 원가는. 전부 부풀려져 있고 엉터리라는 거예요. 거기에다가 최고 문제는 노선 하나 만들 때, 이번에 190대가 늘었습니다, 광역버스가. 190대 늘 때 이 사람들이 노선 하나에 보통 몇십억씩 프리미엄이 붙어요. 그런 일들을 1년 내내 서울시청 따라가도 10대도 허가가 안 납니다, 경기도가. 그걸 한꺼번에 190대를 증차해 준 거예요. 그만큼 엄청나게 벌었고 또 뭐냐면 그만큼 우리는 반대로 손실보전금을 해 줘야 된다는 얘기입니다. 이층버스도 지금 협약체결을 안 해서 손실보전금 내라는 협약이 없어요, 안 해 주겠대. 그래서 그 각서를 내라 했더니 각서를 못 내요. 이층버스도 반드시 환승할인체제에 들어가기 때문에 손실보전금 해 줘야 된다, 그 책임 누가 질 거냐는 거예요. 그 비용까지 산정을 하면 정말 잠을 안 자야 돼요, 여기 계신 분들은. 그래서 이게 이 행감에서는 얘기할 수 없는 거지만 분명히 최우선과제로 해서 다시 한 번, 이번 감사결과에도 분명히 나올 겁니다. 저는 징계까지 요구할 거예요. 그런데 그거에 대해서 좀 객관적으로 해서, 정 안 되면 제가 도정질문해서라도 요구를 할 테니까 과제로 채택을 좀 해서 연구 좀 해 주십시오.
</p>
<p><b>○ 휴먼교통연구실장 지우석 </b> 지금 말씀하신 대로 사실은 저희가 틀을 다 잡아서 이제는 민간업체에서 해도 된다고 해서 도하고 저희하고 협의를 해서 그쪽으로 넘어가 있는데 지금 말씀하신 대로는 부족한 점이 굉장히 많다. 그렇다면 정말 세밀하게 다시 한 번 탈탈 털어서 볼 수 있는 기회를 가질 필요는 있을 것 같습니다.
</p>
<p><b>○ 이재준 위원 </b> 이상 질의 마치겠습니다.
</p>
<p><b>○ 위원장 배수문 </b> 이재준 위원님 수고하셨습니다. 나득수 위원님 질의해 주시기 바랍니다.
</p>
<p><b>○ 나득수 위원 </b> 나득수 위원입니다. 원장님, 조금 전 제 질의시간에 순손실이 발생하는 것은 출연금을 적게 주기 때문에 그렇다. 구조적인 문제는 전혀 아니다 이렇게 말씀하신 것 같아요. 맞습니까?
</p>
<p><b>○ 경기연구원장 임해규 </b> 네, 그렇습니다.
</p>
<p><b>○ 나득수 위원 </b> 그런데 저희들이 어떤 성과평가를 할 때 물론 경기연구원에 대한 양적인 성과평가는 좀 맞지 않을 수도 있습니다. 질적인 평가가 우선돼야 되겠죠? 그런데 우리가 경영효율성 평가할 때 어떤 기준이 있어야 할 거 아닙니까? 상한선 기준이나 또는 하한선 기준을 둬야 될 거 아닙니까? 그런데 우리 경기연구원 같은 경우는 상한선, 하한선이 기준이 없는 것 같아요. 왜냐하면 출연금이라는 상한선이겠죠, 제가 말씀드린 건. 출연금을 그러면 어디까지 줘야 될 것인가, 경기연구원에서 요구하는 출연금은 과연 어디까지 줄 것인가. 그런 출연금을 많이 주면 많이 줄수록 지출 포션도 많이 올라갈 거라고 저는 생각하거든요. 그렇다면 하한선, 지출 포션을 많이 올리면 그에 따라서 출연금을 또 저희들이 상응해서 줘야 되잖아요. 출연금을 안 주면 또 기금에서 사용할 거 아닙니까? 기금에서. 그러면 어디다가 이 문제를 초점을 맞춰야 할 것인가 저는 좀 막연한 생각이 듭니다. 그래서 저는 제 생각 같아서는 이게 또 우리가 구조조정적인 측면에서 인원을 감축한다든가 아니면 지출경비를 좀 줄인다든가, 그죠? 아니면 받아가시는 상여금 포션을 줄인다든가 이런 자구책이 있어야 하지 않나 싶은데 우리 원장님께서는 출연금을 적게 주기 때문에 이게 손실이 발생한다 이렇게 말씀하신 것 같아요. 그에 대해서 어떻게 생각하십니까? 제 말에 대해서 어떻게 생각하십니까?
</p>
<p><b>○ 경기연구원장 임해규 </b> 일단은 전체 구조는 위원님께서 지적하신 것처럼 저는 우리 연구원의 특성상 사실 다른 곳으로부터 어떤 연구수탁을 받기가 굉장히 어려운 저희들 속성상 도정과제 또는 시군에서의 과제를 적절하게 수행할 만큼의 저희들 경비를 출연금으로 주는 것이 가장 합당하다고 생각합니다, 일단은 기본적으로. 그런데 방금 구조조정 문제를 말씀하셨는데 역시 구조조정은 우리 연구원에서 도나 아니면 시군에서 정책과제 혹은 전략과제 혹은 수탁과제 형식으로 저희들이 주는 연구량을 충분히 줄일 수 있다, 그렇게 줄여도 무방하다고 하는 의뢰기관 그리고 저희를 관리하는 통제기관의 판단이 선행해야 될 것 같습니다. 그런데 위원님도 아시다시피 사실 우리 연구원에서 수행하는 연구로도 충분하지 않다고 하는 것이, 저희들이 공급을 충분히 못 하고 있습니다. 왜냐하면 연초에 도에서 그리고 연중 도에서 굉장히 많은 연구의뢰가 오는데 저희들이 그걸 다 해 줄 수도 없는 상태입니다. 그렇기 때문에 그것은 역시 도에서 판단을 해야 한다고 생각합니다. 그런데 일단 현재 저희들이 현원, 박사를 61명까지 고용해야 된다고 하는 나름대로의 판단에 의해서 정원규정도 줘 놨습니다. 그런 정도의 인원이 연구를 해라 이렇게 줘 놨기 때문에 저는 그 정도는 도에서 책임지고 해야 된다고 생각하고 지금부터 한 3~4년 전에는 사실 출연금을 충분히 경상경비나 사업경비를 쓸 수 있도록 다 줬습니다, 저희들한테. 그런데 도가 재정운영상 여러 가지 어려움 때문에 출연금을 쓰라고 한 것이기 때문에 저는 그것이 곧바로 저희를 어떤 구조조정을 해야 되는 걸로 이어지지는 않는다고 봅니다. 일반적인 공공기관이 방만경영을 하니까 구조조정해야 된다거나 이런 문제를 우리 연구원이 안고 있지는 않다고 생각합니다.
</p>
<p><b>○ 나득수 위원 </b> 그렇습니까? 지금 원장님께서 말씀하신 것처럼 2009년도에 126억 정도 출연금을 받았었어요. 그런데 갑자기 2010년도에 99억으로 줄었어요. 줄었는데 거기서 급여를 보면 2009년도에는 84억을 급여로 처리했어요. 그런데 2010년도에는 75억으로 한 8억 정도가 줄었어요. 그러면 그 부대경비도 또 줄었겠죠. 지금 보면 지출비에서 포션이 2014년 현재 68%예요, 68%. 그렇다면 2010년도에 그 포션하고 지금 포션하고는 인건비에 대한 포션이 많이 올라갔다는 거죠, 높아졌다는 거죠. 그런 문제점이 있다는 거죠. 그래서 저는 구조조정이이나 인원감축이나 이런 거 반드시 그걸 이야기하는 것이 아니라 지출비용을 감소시킨다든가 그다음에 수탁용역 수입이죠, 수탁용역 수입. 그 수입에서 보니까 29% 정도를 우리 수입으로 잡네요?
</p>
<p><b>○ 경기연구원장 임해규 </b> 네.
</p>
<p><b>○ 나득수 위원 </b> 그 포션을 더 높인다든가, 그러면 외부연구원들 줄일 수도 있는 거잖아요, 그렇죠? 우리 자체 연구원들로 승인을 할 수 있는 거 아닌가 싶은데요. 그런 것들 조금씩 조금씩 지출경비를 줄여서라도 좀 순익을 높여야 되지 않느냐 저는 그런 의미에서 말씀드렸습니다.
</p>
<p><b>○ 경기연구원장 임해규 </b> 그래서 저희들이 수탁과제를 통한 수익을 늘리는 것들이 저희들 계속되는 경영과제이기도 합니다. 그래서 올해도…….
</p>
<p><b>○ 나득수 위원 </b> 유일하게 수탁용역밖에 없어요, 늘릴 것은.
</p>
<p><b>○ 경기연구원장 임해규 </b> 그렇습니다. 그거밖에 없어서 저희들도 그쪽으로 집중해서 올해는 작년보다 좀 늘었습니다. 그렇지만 그것도 여러 가지 한계가 있는 게 그전 같은 경우는 도에서 발주하는 수탁과제의 경우는 저희들이 어떻게 보면 내부자거래 비슷하게 그게 할 수가 있었는데 지금은 그것도 전부 다 공개경쟁입찰로 돼 있어서 보통 최저가격입찰로 되는 게 많기 때문에 그것도 사실 저희한테 어려운 경영환경입니다. 그럼에도 불구하고 저희들이 다각도로 애를 써서 작년보다는 또는 재작년보다는, 지난 3년 평균보다는 올해는 좀 더 늘었습니다. 그래서 그것이 위원님 말씀하시는 것처럼 저희들 수익을 늘리는 가장 중요한 과제이고요. 또 그 외에 불요불급한 사업들을 우리가 좀 줄여보려고, 아까 보고말씀 드렸습니다만 저희들이 예산 관련된 회의를 저희 연구원 박사님들 다 모여 가지고 한 세 차례 한 적도 있습니다. 어떻게 하면 최소로 줄일 것인가, 그리고 방금 말씀하신 것처럼 그것도 언론에도 나서 저희들 급여 중에 또 성과급이나 이런 것들을 일부 줄여야 되지 않느냐는 요구까지 많이 있어서 사실 저희 박사님들 모두가 상당히 스트레스를 받고 있습니다, 저희들도. 그래서 여러 가지 모색을 하고 있습니다만 어쨌든 지금으로써는 수탁과제를 늘리고 내부의 여러 가지 경비를 줄이는 방안으로 경비절감을 위한 또는 수익증대를 위한 그런 노력을 기울이고 있습니다.
</p>
<p><b>○ 나득수 위원 </b> 아무튼 많은 고민해 주시기 바랍니다. 그러니까 구조적인 문제는 없다 이렇게 말씀하시지 마시고요. 많은 고민을 해 주시기 바랍니다. 다음 질문 드려도 될까요?
</p>
<p><b>○ 위원장 배수문 </b> 한 번 질문하시고.
</p>
<p><b>○ 나득수 위원 </b> 한 번만 더 하겠습니다. 우리 경기도에서 출자ㆍ출연기관 대상으로 해서 평가를 하죠?
</p>
<p><b>○ 경기연구원장 임해규 </b> 네.
</p>
<p><b>○ 나득수 위원 </b> 그런데 5등급으로 평가가 나나요?
</p>
<p><b>○ 경기연구원장 임해규 </b> 네.
</p>
<p><b>○ 나득수 위원 </b> S, A, B, C, D 5개 등급으로. 그런데 우리 경기연구원이 2012년도, 13년도 A등급을 받았어요.
</p>
<p><b>○ 경기연구원장 임해규 </b> 네.
</p>
<p><b>○ 나득수 위원 </b> 그런데 14, 15년도에는 B등급으로 중위권으로 평가되고 있어요. 이게 혹시 제가 전에 질문드렸던 연구실적이 줄어든 거 이거하고 관계돼 있지 않나 싶은데 어떻게 생각하십니까?
</p>
<p><b>○ 경기연구원장 임해규 </b> 딱 꼬집어서 연구실적이 양적으로 줄었다 이것은 아닌 것 같고요. 저희가 판단하기에는 우선은 저희들이 정확하게 뭐 때문에 B로 줄었는가 이렇게 딱 하나로 집어서 말하기는 어렵습니다. 아마도 제가 보기에는 전반적으로 2013년 때 평가를 하는 기관이 일단 좀 바뀌면서 그것도 영향이 없지는 않은 것 같고요. 두 번째는 연구를 하는 박사님들의 사기도 좀 저하된 측면도 있는 것 같습니다. 그리고 여러 가지를 평가해서 점수를 매기는데 연구원 박사님들의 직무만족도나 이런 것들도 많이 높지 않았던 것 같고. 그래서 저희들이 사실 경영개선을 위한 태스크포스를 만들어서 몇 개월간 고심을 많이 하고 거의 모든 박사님이 참여하도록 독려해서 논의를 많이 한 것도 우선은 좀 연구를 적극적으로 또 연구하는 활동에 대해서 신명 나는 그런 연구를 할 수 있도록 분위기를 바꾸는 것이 중요하다고 생각하고 개선을 위해서 노력을 하고 있습니다. 그런데 그 성과가 제가 바라건대 2016년도 평가는 좀 잘 나올 걸로 저는 그렇게 기대하고 있습니다.
</p>
<p><b>○ 나득수 위원 </b> 아, 그렇습니까? 아무튼 우리 경기연구원은 경기도에서 최고의 브레인들만 지금 계시잖아요. 그런데 B등급이란 중급의 평가를 받았다는 것은 외부적으로도 좀 그렇지 않아요?
</p>
<p><b>○ 경기연구원장 임해규 </b> 네, 저희도 부끄럽습니다.
</p>
<p><b>○ 나득수 위원 </b> 그래서 아무튼 조직분위기 개선이라든가 많은 노력들을 해 주셨으면 고맙겠습니다.
</p>
<p><b>○ 경기연구원장 임해규 </b> 그렇게 하겠습니다.
</p>
<p><b>○ 나득수 위원 </b> 마지막으로 하나만 더 질문드리겠습니다. 올해도 또 여지없이 사회적으로 이슈가 되는 사건이 발생했죠. 제 생각으로는 메르스 사태하고 또 올해 가뭄 걱정인 것 같습니다. 아무쪼록 사회적으로 이렇게 어려운 문제가 발생했을 때마다 우리 경기연구원에서 많은, 우리 경기도의 싱크탱크로서 경기연구원에서 많은 일을 했을 것 같은데 어떤 일을 하셨는가 설명 좀 해 주시겠습니까?
</p>
<p><b>○ 경기연구원장 임해규 </b> 우선 사실 메르스 문제는 경기보건환경연구원에서 보건의료에 관해서 연구하는 기관이기 때문에 사실 그쪽에서 연구를 해야 되는 문제인 것 같습니다. 그렇지만 저희들이 재난이나 이런 것들이 매우 중요하기 때문에 재난 관련된, 일단 의료 관련된 박사를 한 분 최근에 뽑았습니다. 그리고 저희들이 재난전문박사를 지금 공모해 놓고 있습니다, 뽑으려고. 그래서 그쪽의 연구역량을 강화할 생각을 가지고 있고요. 최근에 아주 짧은 글입니다만 메르스에 대해서는 연구를 하나 했습니다. 그리고 가뭄과 관련해서는 저희들이 환경연구실에서 가뭄대책에 대해서는 여러 건의 연구를 했습니다. 그리고 경기도가 내년, 후년 가뭄이 이어지면 굉장히 수량공급 차원에서도 큰 문제가 발생할 가능성이 높기 때문에 장ㆍ단기적인 극복방안이 무엇일 건가와 관련해서는 아주 현실적이고 구체적인 대안 몇 가지를 이미 연구결과로 내놓았고 그래서 그 연구결과를 아마 도에서도 심각하게 그 문제를 검토할 것으로 저희는 생각하고 있습니다.
</p>
<p><b>○ 나득수 위원 </b> 아무튼 임시방편적인 대책이 아니라 장기적인 재난안전대책도 강구해 주셨으면, 그쪽에 대한 연구도 좀 강구해 주셨으면 고맙겠습니다. 이상입니다.
</p>
<p><b>○ 경기연구원장 임해규 </b> 그렇게 하겠습니다.
</p>
<p><b>○ 위원장 배수문 </b> 나득수 위원님 수고하셨습니다. 또 질의하실 위원님, 안혜영 위원님 질의해 주시기 바랍니다.
</p>
<p><b>○ 안혜영 위원 </b> 안혜영 위원입니다. 여러 가지 말씀을 해 주셨는데 우리 도에 파견자분이 계시죠?
</p>
<p><b>○ 경기연구원장 임해규 </b> 네.
</p>
<p><b>○ 안혜영 위원 </b> 세 분 계신 걸로 알고 있는데 이분들이 도에서 하시는 역할을 간단하게 설명하자면, 역할과 실효성에 대해서 좀 말씀해 주시죠.
</p>
<p><b>○ 경기연구원장 임해규 </b> 일단은 도에서 어떤 새로운 아이디어가, 어떤 정책을 하자고 하는, 도 차원에서 여러 가지 정책아이디어가 부서 차원에서 나올 수가 있습니다. 그런 경우를 1차적으로는 아마 그쪽에 파견 나가 있는 세 분의 박사님이 검토를 해서 그중에 연구를 좀 깊이 있게 해야 되는 것들이 있으면 저희들한테 또 연결을 해서 박사님들이 연구할 수 있도록 저희 연구계획실하고 연결이 돼 있습니다. 그것이 1차적인, 그러니까 여러 가지 많은 도정의 정책아이디어들을 1차적으로 그 실효성이나 타당성이나 이런 것들을 우선적으로 토의를 통해서 일종의 의제형성기능을 거기서 하고 있는 것으로 저희들이 생각하고 있습니다.
</p>
<p><b>○ 안혜영 위원 </b> 그 세 분이 그걸 다 전담해서 하실 수가 있나요?
</p>
<p><b>○ 경기연구원장 임해규 </b> 그러니까 도정의 여러 가지가 부서 차원에서 의제형성을 하는 경우도 있지만 그것이 비중이 있는 정책이다 이렇게 되는 경우는 아마 도에서도 일정한 검토를, 이거를 용역으로 맡길 것인가 이렇게 하기 전 단계에서 일정한 검토하는 기능은 필요하다고 생각합니다.
</p>
<p><b>○ 안혜영 위원 </b> 역할을 하실 수도 있는데 이 문제에 대한 지적이 매번 있었죠?
</p>
<p><b>○ 경기연구원장 임해규 </b> 네.
</p>
<p><b>○ 안혜영 위원 </b> 의회에서도 있었고. 대부분의 도에서 하는 연구용역들을 경기연구원에서 많이 맡아서 하고 있습니다. 그러다 보니 이런 역할이 장단점을 가지고 있는데 반면에 다른 면에서는 객관성을 담보하기가 쉽지 않다. 그렇게 일단은 경기연구원에서 1차적으로 걸러진 것들에 대한 기본안이 긍정적인 스타트를 하는 거죠. 그러다 보니 그 연구에 관련돼서 대부분 거기에서 의견을 주신 분들의 의견이 연구결과에 많이 반영이 될 거라고 보고 있어서 사실은 저희가 그런 정책적인 연구용역이라고 하는 것이 이것에 대한 근본적인 실태, 아까 원장님도 말씀을 하셨지만 연구용역을 발주하는 곳이 어디냐에 따라서 그 결과가 많이 좌우되는 경우들이 있습니다. 긍정적인 방향을, 그 일을 하기 위해서 용역을 대부분 하는 것이죠. 용역을 발주한다는 것은 그 사업을 하기 위해서 그 근거자료를 만들기 위한 것이 대부분입니다. 그렇기 때문에 이 연구용역의 결과에 의해서 많이 좌우가 되는데 그 객관성이나 신뢰성에 의문점이 생길 수 있는 그런 환경적인 요인을 많이 갖고 있다라는 지적을 드리고 싶고요. 그런 부분에서 더더군다나 경기연구원의 50~60명 이상 되시는 분들을 대표성으로 가서 계시긴 하지만 그것이 대부분의 뜻을 좌우하지 않지만 우려성을 아직도 많이 갖고 있습니다. 그리고 그 안에 그런 의견들의, 1차적인 의견을 할 때는 그것의 중요한 역할을 하고 있는 도의회는 항상 배제되어 있기 때문에 그것이 어느 정도 추진되고 거의 사업의 막바지에, 결정이 되기 일보 직전 아니면 결정된 후에 경기도의회와 소통하는 경우가 대부분이거든요. 그렇죠? 그래서 그런 단계에 대한 문제점, 환경에 대한 문제점 그리고 실효성에 대한 문제점을 다시 한 번 파악해 주시기 바랍니다. 
</p>
<p><b>○ 경기연구원장 임해규 </b> 네, 알겠습니다. 
</p>
<p><b>○ 안혜영 위원 </b> 그렇게 해 주시고요. 신규채용을 많이 하셨죠? 원장님 들어오시고 몇 분이 퇴직하시고 몇 분이 신규채용 되셨는지 혹시 파악하고 계시나요?
</p>
<p><b>○ 경기연구원장 임해규 </b> 정규직 퇴사자는 제가 들어오고 난 다음에는 여섯 분이 퇴직을 했습니다.
</p>
<p><b>○ 안혜영 위원 </b> 그리고 몇 분 신규채용 하셨어요?
</p>
<p><b>○ 경기연구원장 임해규 </b> 여섯 분 퇴직한 중에 한 분은 행정직이었고요. 다섯 분은 박사님이셨습니다. 그런데 저희가 신규 박사 채용한 것은 여덟 분하고 행정직은 두 분 채용했습니다. 그래서 10명 채용했습니다. 
</p>
<p><b>○ 안혜영 위원 </b> 여섯 분 퇴직하시고 열 분, 그러면 인건비도 많이 늘어났겠네요?
</p>
<p><b>○ 경기연구원장 임해규 </b> 그런데 그것은 사실 들어오신 분이…….
</p>
<p><b>○ 안혜영 위원 </b> 간단하게 답변해 주세요.
</p>
<p><b>○ 경기연구원장 임해규 </b> 최근까지 들어왔기 때문에 아직까지는 인건비가 그렇게 많지 않았고요, 인건비 지급이 많지 않았고. 그리고 그게 저희들 원래 예산에 그만큼 저희들이 충원하겠다고 애초에 예산신청을 한 것입니다. 
</p>
<p><b>○ 안혜영 위원 </b> 제가 이력서와 담당하게 되는 부서 이런 것들을, 정책을 담당하실 방향에 대해서 봤는데 어느 한 분을 딱 찍어서 말씀드리기는 그렇고요. 전반적으로 물론 아까 원장님께서 취지에 대해서는 설명해 주셨는데 경력이라든가 아니면 연계성이 딱히 드러나 있지 않은 것 같은 생각이 들어요. 본 위원이 볼 때는 대부분 강의를 하시거나 연구소나 연구원에 근무를 하셨던 경력이 있으셨으면 좋았을 텐데 그런 분들이 대부분 아니시고. 그리고 어떤 분은 그냥 행정사무관이셨고 대부분이 다 그런 분들이 많으신 것 같아요. 그래서 대학교에 계셨던 분들이 연구목적으로 계셨던 건 아니셔서 그리고 그 경력들이 대부분 좀 짧으시더군요. 그런 분들이 지금 1,280만의 경기도를 이끌고 가는 연구용역에 얼마나 많이 참여하실지 저는 의문을 제기하고 싶고요. 시간별로 없어서, 이분들이 앞으로, 물론 뽑으신 의미가 있으시겠죠. 그분들에 대한 의견들이나 이분들이 해야 될 역할들을 상세하게 저에게 자료로 만들어서 주셨으면 좋겠습니다. 
</p>
<p><b>○ 경기연구원장 임해규 </b> 제가 간단히 답변드릴까요?
</p>
<p><b>○ 안혜영 위원 </b> 지금 한두 분 답변 들을 건 아닌 것 같고요.
</p>
<p><b>○ 경기연구원장 임해규 </b> 그런데 저도 포괄적으로 한 분 한 분 하지 않고 답변드리는데 일단 저희들이 공모해서 어떤 경우는 아무도 못 뽑은 경우도 있습니다. 그래서 사실 엄격한 절차를 통해서 뽑았는데요. 그런데 전반적으로 경력도 굉장히 저희들이 중시해서 봤습니다. 연구경력이 있나 연구능력이 있는가 중시해서 봤고요. 그리고 전공과 관련해서는 사실 거의가 전부 다 특정한 분야의 전문가들입니다. 그리고 들어와 가지고 맡을 분야가 불분명하다고 하는 경우는 철학박사의 경우 그런 말씀도 할 수 있는데 저는 그거는 우리가 통섭연구를 위해서 굉장히 중요한 부분이라고 생각해서 저희들이 뽑았다는 말씀…….
</p>
<p><b>○ 안혜영 위원 </b> 제가 말씀드리는 것처럼 기존에 경기도가 정책적인 방향을 제시하는 경우가 많죠, 경기연구원에서. 지금 말씀하셨으니까 한 예로 들자면 길어지니까 짧게 제가 말씀드릴게요. 의문점을 갖는 이유, 이해를 저에게 시켜 주셨으면 좋겠다는 말씀을 드리는 거고요. 법학 관련된 것이라고 하면 저희들이 정책적인 방향에 법학을 전공하신 분이 왜 필요한지 제가 이해가 되지 않아서 그런 부분들은 차후에 저한테 말씀해 주셨으면 좋겠다는 것과 특정 무슨 예체능 쪽의 한쪽에 전공을 하신 분인데 그 외의 다른 쪽의 분야에서 혹시 경력이 있으신가 봤더니 특별하게 그렇지 않으신 부분들 그런 것들에 대해서 제가 전반적으로 말씀을 드리는 겁니다. 
</p>
<p><b>○ 경기연구원장 임해규 </b> 저희들 연구의 대부분이 법적인 개선이나 또는 자치법의 여러 가지 문제나 이런 것들을 그야말로 깊이 있게 검토해야 된다고 저는 생각합니다.
</p>
<p><b>○ 안혜영 위원 </b> 그러게요. 그런데 그분이 그런 것…….
</p>
<p><b>○ 경기연구원장 임해규 </b> 법학박사는…….
</p>
<p><b>○ 안혜영 위원 </b> 제가, 주고받고 계속 이렇게 되면 시간이 오래 걸리는데 그분의 경력들을 보면 그럴 만한 경력이 많아 보이지 않아서 제가 말씀드리는 거예요.
</p>
<p><b>○ 경기연구원장 임해규 </b> 행자부에서도 그런 연구를 하고 온 분입니다.
</p>
<p><b>○ 안혜영 위원 </b> 그리고 마지막으로 하나만 더 말씀드리겠습니다. 경기연구원에서 저희들이 이슈로 삼고 있는 여러 가지 현안들이 있습니다. 남경필 지사가 추진하고자 하는 그런 대표적인 사업들도 있고요. 예를 들자면 4대 테마파크나 이런 북부에 관련된 여러 가지 사업들이 있는데요. 그것에 깊이 관여가 되어 있는지 잘 모르겠습니다. 의회에서 저희 다수의 의견들에 반대의견을 갖고 있는 사업들도 연관이 많이 되어 있는 것 같아서 그런 부분들에 대한 걸 의회하고 소통을 많이 하셨으면 좋겠다라는 말씀과 또 이슈가 앞으로 많이 될 거라고 보는데 따복도 사회적경제에 관련돼서 원장님이 관심 많이 있으시잖아요. 경기도가 추진하고 있는 방향에, 경기도가 굿모닝경기 아니면 넥스트경기 이런 얘기들 많이 하죠. 그런데 그게 어느 순간에 다 사라지고 모든 게 다 따복 따복 따복으로 되어 가고 있는 것 같습니다. 따복센터가 있는데 그렇다고 하면 모든 사업을 다 따복센터에 넣고 해야죠. 그렇지 않으면서 모든 실국에 다 따복이라는 이름을 넣고 있어요. 따복이 지금 경기도를 대표하고 있는 네임이 되고 있다는 거죠. 알고 계시죠?
</p>
<p><b>○ 경기연구원장 임해규 </b> 바람직하지 않다고 생각합니다. 
</p>
<p><b>○ 안혜영 위원 </b> 네. 그래서 그런 것들에 대한 방향제시를 같이해 주셨으면 좋겠고요. 그리고 그게 옳은 건지 잘 모르겠습니다. 그래서 그런 의문점을 갖고 있어서 제가 제안을 드리는 거고. 또 청년에 관련돼서 한 가지 말씀드리면 청년에 관련된 일자리부터 시작해서 많은 연구용역을 하고 계시죠?
</p>
<p><b>○ 경기연구원장 임해규 </b> 네.
</p>
<p><b>○ 안혜영 위원 </b> 그런데 기존의 청년에 대한 연령, 저희들이 그런 기본적인 걸 하려고 하면 기본 틀이 중요하다고 보는데 청년에 대한 기본연령이 중구난방으로 되어 있습니다. 그렇기 때문에 지금 환경이 많이 바뀌었죠. 100세를 바라보고 있는 나이 연령대가 바뀌었다는 거죠. 평균 연령이 바뀐 상황에서 청년의 연령에 대한 기준을 어디다 둬야 될 것인지 또 여성이라고 하면 여성은 하나로 되어 있지 않습니까? 그런데 청년에 대한 것들이 어떻게 보면 만 19세라고 얘기했다가 35세로 얘기했다가 만 45세로 얘기했다가 그렇기 때문에 어디를 기준으로 두고 청년에 대한 정책을 우리가 삼아야 될지에 대한 기준을 경기도가 앞장서서 만들어 줬으면 좋겠다라는 제안과 모든 연구의 기준이 많이 다른 것 같습니다. 예산이나 저희들이 연령에 대한 모든 데이터를, 빅데이터를 저희들이 하고 있어서 데이터를 작성할 때 기본 틀을 정비하고 갔으면 좋겠다. 연구마다 다 그 기준이 달라서 저희들이 어떠한 거에 반영시켜야 될지 모르겠는 경우들이 많이 있습니다. 그런 제안을 드리면서 추가질의 마치도록 하겠습니다. 수고하셨습니다. 
</p>
<p><b>○ 경기연구원장 임해규 </b> 감사합니다.
</p>
<p><b>○ 위원장 배수문 </b> 안혜영 위원님 수고하셨습니다. 질의하실 위원님 계십니까? 박재순위원님 질의해 주시기 바랍니다. 
</p>
<p><b>○ 박재순 위원 </b> 59페이지 보면 보건의료 관련 정책연구에 관해서 2015년도 9월 1일 자로 채용한 부분이 나옵니다. 아마 의료에 관한 전문인력을 보강하신 모양인데요. 이게 제가 작년에도 말씀드렸던 6개 의료기관을 이용한 의료관광과 연계된 사업하고 연계되는 건가요, 이게? 지금 전문인력을 뽑으셨잖아요. 그래서 의료관광에 관한 사업을 연계시킨 거하고 어떤 연관이 되는지 질의를 드렸습니다. 
</p>
<p><b>○ 경기연구원장 임해규 </b> 지난해에 위원님께서 몇 차례에 걸쳐서 그런 연구의 필요성을 제기해 주신 거를 기억하고 있습니다. 그리고 사실 저희들이 의료전문가를 한 명 뽑았기 때문에 의학박사이기도 하고 예방의학을 하고 이렇기 때문에 위원님이 말씀하신 것을 관광문화를 전공하는 박사와 또 의료전문으로 하는 박사가 위원님 제기한 의료와 관광을 연결하는 그런 연구방안을 한번 해 보면 좋을 것 같습니다. 
</p>
<p><b>○ 박재순 위원 </b> 그래서 이 부분에 우리가 의료관광법에 관한 조례가 없어서 저도 조례를 준비 중에 있어서 물어보니까 상임위에서 아마 별도로 한다고 이 조례에 관해서 얘기를 했었어요. 그런데 아마 계류 중에 있는 건지 아니면 그냥 형식상 저한테 그렇게 얘기했는지 제가 잘 모르겠어요. 그래서 이게 상당히 늦은 부분이 없지 않아 있다고 저는 봅니다. 사실 우리가 동남아뿐만 아니라 세계적으로도 의료기술이라는 게 상당한 수준에 있고 그 수준을 잘 접목해서 경기도에 인프라가 6개 의료기관이 있기 때문에 본 위원은 그 부분에 대해서 좀 더 알찬 프로그램이 운영되길 바라고 있고 또 의료원이 현재 많은 돈을 투자했지만 거의 다 적자운영을 하고 있는 것으로 되어 있습니다. 그리고 또 경기도에는 많은 대학병원이 있기 때문에 충분하게 그렇게 연결시켜 주는 그런 부분이라든지 이렇게 잘 됐으면 좋겠는데 모처럼 이렇게 보니까 전문인력이 보강되었다고 하니까 저 스스로는 잘 되기를 기대해 보겠습니다. 그리고 이런 연구가 우리 산업에 또 우리 경기도가 뒷받침해 줘서 많은 의료관광이라고 하긴 뭐 하지만 많은 사람들이 본인들의 질병을 고치기 위해서 또 대한민국의 의료가 좋아서 찾아올 수 있는 문화를 만드는 게 실질적으로 경기도가 앞장서야 될 부분인데 그동안은 개인들이 서울을 비롯한 전국에서 많은 의료사업을 했고 지금은 아마 서울 서초구를 비롯한 중구에서도 준비하고 있는 것으로 제가 알고 있습니다. 우리 경기도도 늦은 감이 없지 않아 있지만 이번 기회로 해서 이런 것을 정말 우리 경기도가 뒷받침해 줘서 많은 동남아에 있는 또 세계에 뻗어있는 우리나라 사람을 비롯한 외국인들이 와서 좋은 양질의 진료를 받고 돌아갈 수 있고 또 나아서, 쾌유돼서 갈 수만 있다면 그것처럼 좋은 게 없다고 봅니다. 그런데 정말 우리 원장님 큰맘 잡으신 것 같아요. 그래서 고맙다는 말씀드리고 싶은데 괜찮으실지 모르겠습니다. 
</p>
<p><b>○ 경기연구원장 임해규 </b> 네, 그렇게 연구하도록, 저희가 생각하는 것은 일단 구제역도 있고 여러 가지 전염병ㆍ감염병들도 많고 이래서 저희들이 공공의료강화를 통해서 어떻게 하면 그런 국민보건, 도민의 보건을 높일 수 있는가 하는 것이 새로 의학박사를 뽑게 된 가장 큰 이유 중의 하나고요. 또 하나는 의료관광산업같이 의료산업을 어떻게 활성화시킬 건가 하는 측면도 경기도에 미래의 먹거리와 관련된 중요한 분야이기 때문에 위원님께서 지난번에 제기하신 그 연구과제를 포함해서 앞으로 연구를 많이 할 것으로 기대하고 있습니다. 그렇게 하도록 하겠습니다. 
</p>
<p><b>○ 박재순 위원 </b> 경기도에는 많은 제약사들이 있어요. 최근에도 한미약품에서 주식이 더블이 뛰는 그런 선례가 있는데요. 어쨌든 경기도에 많은 제약사 또 병원 또 우리 연구원 잘 되기를 기대해 보고요.
</p>
<p style="padding-left:1.2em">  또 하나는 경기도가 나갈 길이 통일에 대한 준비이고 또 통일을 위해서 가야 되는 건데 지금 2017년도, 18년도, 19년도 국회에서 계속적으로 입법을 예고하고 발의했던 통일경제특구에 관한 법률이 계속 안 됐어요. 그 문제가 무엇이라고 생각하시는지 또 여기에 대한 준비를 우리 경기도 차원에서 어떻게 해야 될 것인지 원장님 간단히 말씀해 주시기 바랍니다. 
</p>
<p><b>○ 경기연구원장 임해규 </b> 그것은 통일전문가가 있으니까 연구도 계속 수행하는 박사님이 하면…….
</p>
<p><b>○ 북부연구센터장 김동성 </b> 북부연구센터장 말씀드리겠습니다. 통일경제특구는 개성공단이 2005년도에 출범하면서부터 쭉 얘기가 됐었습니다. 그래서 많은 분들이 관심을 쭉 가졌고요. 가장 큰 이유 중의 하나가 접경지역에 지역구를 두시는 의원님들께서 많은 관심을 가져서 통일경제특구를 만들자 이런 말씀들을 하셨습니다. 또 각 당에서도 필요성을 인식한 부분도 있었습니다. 있었는데 18대에도 무산됐고 이번 19대에도 역시 남은 몇 개월 사이에 처리될 가능성은 없어 보입니다. 그럼에도 불구하고 저희 경기도에서는 일단 통일경제특구를 어떤 상황에서도 경기도 지역으로 유치한다는 그런 입장하에 각 사이트에 대한 나름대로 평가를 해 놓고 있습니다. 김포라든지 특정지역을 저희가 확정하지 않습니다만 파주, 연천 이렇게 여러 지역에 대해서 나름대로 장단점을 파악해 두고 하시라도 통일경제특구 법안이 통과됐을 경우에 저희 경기도의 입장을 체계적으로 내세울 수 있는 준비는 해 놓고 있습니다. 
</p>
<p><b>○ 박재순 위원 </b> 그 부분에 대해서 지난번에 균형발전실에서 본 위원이 국가에서 못하니까 그럼 경기도형 특별경제구역에 관한 어떤 조례나 이런 걸 만드는 게 더 실용적이지 않을까. 그래서 국가에서 상위법이 나중에 접목됐을 때 우리가 빨리 접목할 수 있고 경기도가 앞장서서 가는 선례가 되지 않을까 싶었는데 연구원 입장에서는 어떻게 생각하시는지.
</p>
<p><b>○ 북부연구센터장 김동성 </b> 기왕에 중앙정부에서 논의되고 있는 마당에 지자체에서 조례를 만드는 것이 전략적으로 더 나은지는 잘 모르겠습니다. 다만 저희는 그것보다는 남북교류를 보다 활성화해서 여기에 경기도가 선도적이고 주도적으로 이끌어가는 모습을 보이는 것이 추후에 특구의 어떤 유치라든지 기타 여러 가지에 도움이 되지 않을까 이렇게 생각하고 있습니다. 
</p>
<p><b>○ 박재순 위원 </b> 경제발전을 위해서 사실은 경제특별법을 만들자고 하는데 본 위원이 생각해도 아이러니한 문제예요. 이게 17, 18, 19 이번에 무산되면 벌써 3대째 무산되는 결과인데 참 보기가 안 좋다는 그런 생각이 들고요. 우리 경기도만의 어떤 파주나 연천 이런 곳에 특별하게 경제를 활성화시킬 수 있는 준비를, 연구원에서 좀 더 실질적으로 접목할 수 있게끔 그런 것도 미리 준비를 하면 더 좋겠다고 생각합니다. 그래서 원장님 위에 가셔서 고생하시는데 많이 노력해 주실 것을 부탁드리고 잘 되기를 기대해 보겠습니다. 본 위원은 이상 질의를 마치겠습니다. 하고 싶은 얘기 있으면 해 주시기 바랍니다.
</p>
<p><b>○ 북부연구센터장 김동성 </b> 위원님께서 각별한 관심을 기울여 주셨기 때문에 저희가 더욱더 접경지역 또 남북교류에 대한 연구를 많이 철저히 수행하도록 하겠습니다. 
</p>
<p><b>○ 박재순 위원 </b> 감사합니다. 이상 질의 마치겠습니다. 
</p>
<p><b>○ 위원장 배수문 </b> 박재순 위원님 수고하셨습니다. 장동일 위원님 질의해 주시기 바랍니다.
</p>
<p><b>○ 장동일 위원 </b> 원장님, 제가 폐기물 재활용 관련해서 이정임 박사님께, 괜찮죠?
</p>
<p><b>○ 경기연구원장 임해규 </b> 네.
</p>
<p><b>○ 장동일 위원 </b> 거기 앉으셔서. 자리가 적당치 않네요. 앉아서 그냥 하셔도 괜찮을 것 같습니다. 
</p>
<p style="padding-left:1.2em">  폐기물 재활용 관련해서 연구를 하고 계시죠?
</p>
<p><b>○ 생태환경연구실선임연구위원 이정임 </b> 재활용 관련해서 쭉 연구를 하는 건 아니고요. 계속적으로…….
</p>
<p><b>○ 장동일 위원 </b> 최근에 했던데. 보니까 자원재활용 관련된, 폐기물 재활용 관련해서요. 얼마 전에 수도권매립지가 반입 갈등으로 인해서 굉장히 문제가 됐다가 지금 봉합이 된 상태죠. 그래서 그 이후로 수도권매립지가 직매립 제로화 정책이라고 해서 웬만한 폐기물들이 수도권매립장에 들어가지 못하고 있습니다. 그러다 보니까 밖에 사업장, 생활계는 큰 문제가 없는데 사업장계가 지금 갈 곳이 없어서 가격이 오르고 사업하시는 분들이 굉장히 애로를 격고 있는데 제가 파악해 보니까 재활용할 수 있는 것들이 많은데 그런 인프라가 안 돼서 각 자치단체별로, 우리 경기도 내만 보더라도 안 돼서 재활용할 수 있는 것들이 지방으로 반출되고 이런 일들이 벌어지고 있는데 혹시 그런 부분에 대해 한 사항을 알고 계세요?
</p>
<p><b>○ 생태환경연구실선임연구위원 이정임 </b> 저는 폐기물분야 연구를 하기 때문에 계속적으로 그런 것들을 파악은 하고 있는데요. 제가 얼마 전에 자원순환산업 활성화방안이라는 보고서를 하나 냈습니다. 그래서 거기서도 지금 위원님께서 말씀하신 것과 같이 그런 다양한 형태의 자원순환산업을 경기도에서 좀 지원할 수 있는 방안 같은 것들 그리고 단지 같은 것들을 마련하는 것들 그런 것들의 내용을 담고 있습니다.
</p>
<p><b>○ 장동일 위원 </b> 지금 독일이나 일본의 경우 폐기물 재활용률이 몇 %나 됩니까?
</p>
<p><b>○ 생태환경연구실선임연구위원 이정임 </b> 재활용률을 제가 명확하게 기억하지 못하겠고요. 일본 같은 경우에는 대부분이 소각이기 때문에 소각률이 한 80%가 넘습니다. 그런데 소각을 80% 하지만 결과적으로는 소각을 해서 나오는 열을 또 열원으로 이용하고 있거든요. 그래서 엄격하게 보면 그런 것들이 어느 정도 에너지순환하고도 관련성이 많게 일본은 활용을 하고 있고요. 독일 같은 경우에는 한 2000년도쯤에 생활폐기물 직매립이 금지가 되면서 우리나라에서는 RDF라고 알려져 있는, 폐기물 갖다가 연료로 생산하는 그런 시설들이 굉장히 많이 늘어나고 있고 소각시설보다는 그런 시설들이 급증하고 있는 상태입니다.
</p>
<p><b>○ 장동일 위원 </b> 그러니까 RDF 이거를 도에서 허가를 내 주고 소각을 하게 하는데 뒤늦게 민간아파트단지 같은 데에서 민원을 제기해서 사업이 안 되고 있고 그러다 보니까 이게 지금 엄청난 문제가 되고 있는데 제가 드리고자 하는 말씀은 그거였거든요. 일본 같은 경우는 거의 소각을 합니다. 그래서 그 에너지를 재활용해서 몇 년 전에 에너지위기가 왔을 때도 상당히 상대적으로 잘 버텼다는 그런 것이 굉장히 널리 알려졌던 건데 우리는 할 수 있는 것들을 여러 가지 문제 때문에 안 하고 있는 거예요. 우리가 관심을 안 가져서 그렇지 이대로 방치하면 지금 협잡물 같은 거, 일반생활계는 공공에서 웬만하면 지금 소화를 해 주고 있어요. 몇 군데에서 시범적으로 하고 있는데 이것도 좀 더 확대해야 할 부분이지만 더 문제는 사업장계가 안 그래도 지금 어려운데 사업장계가 전면적으로 이런 것들이 막혀있단 말이죠. 그러다 보니까 이런 부분에 대해서 제가 좀 드리고자 하는 말씀은 이런 부분을 좀 더 정밀하게, 더 세게 연구를 해서 공론화해 달라 그런 말씀을 드리고 싶은 거예요.
</p>
<p><b>○ 생태환경연구실선임연구위원 이정임 </b> 그렇지 않아도 좀 전에 위원님이 수도권매립지의 현황도 말씀을 하셨잖아요. 그래서 지금 현재 진행상황을 조금 말씀드리면 수도권매립지 관련해 가지고 전체적으로 4자 협의해서 타결을 보면서 지금 환경부하고 4자협의체가 계속적으로 논의를 하고 있고요. 현재 상황으로는 올해 12월 달까지는 환경부에서는 그거 관련해 가지고 전체적인 대책을, 서울ㆍ인천ㆍ경기가 포함돼서 대책을 마련하려고 하고 있는 상황이고요. 그 각각에서 시도 연구원들이 같이 인볼브(involve)돼서 작업이라고 그럴까, 자문을 하고 있어요. 그런데 저희들은 환경부에 의견을 낸 것은 12월 달까지 너무 급하게 이런 대책들을 마련하면 좀 문제가 있으니 이거를 내년까지 해서 여러 가지 분석들을 포함해서 하는 게 좋겠다는 의견을 내고 있고 행정에서는 12월까지는 좀 마무리를 지으려고 하고 있는 것 같아요. 그래서 그 부분에서 어느 정도 생활폐기물하고 사업장폐기물의 어떤 목표라든가 이런 것들은 나올 예정이고요. 그리고 한 가지 덧붙여서 말씀드리면 제가 내년도에 수도권매립지랑 관련해서도 사업장폐기물 관련해서 대응방안 이런 것들을 과제로 진행할 예정으로 있습니다. 그때 위원님께서 말씀하시는 그런 부분들을 좀 심도 있게 고려하도록 하겠습니다.
</p>
<p><b>○ 장동일 위원 </b> 그때 저한테 연락 한번 주세요. 
</p>
<p><b>○ 생태환경연구실선임연구위원 이정임 </b> 네, 알겠습니다.
</p>
<p><b>○ 장동일 위원 </b> 감사합니다. 마치겠습니다. 
</p>
<p><b>○ 위원장 배수문 </b> 장동일 위원님 수고하셨습니다. 더 이상 질의하실 위원님 안 계십니까?
</p>
<p><b>○ 임두순 위원 </b> 여기 있습니다.
</p>
<p><b>○ 위원장 배수문 </b> 임두순 위원님 질의해 주시기 바랍니다.
</p>
<p><b>○ 임두순 위원 </b> 자료요청을 했기 때문에 1분, 2분 정도만 한 가지만 좀 말씀드리겠습니다. 최근 2년간 생태환경 연구목록 관련해 가지고 우리 고재경 연구실장님 전문가시니까 한 가지만 좀 물어보겠습니다.
</p>
<p style="padding-left:1.2em">  생태환경 연구목록에 보면 관련 내용이 있는지 없는지 모르겠는데 최근에 4대강 관련해서 자전거도로가 많이 생겼잖아요. 그다음에 지자체별로 경쟁적으로 자전거도로를 만들고 있는데 DMZ 관련해서 자전거도로 많이 활성화시키고 있잖아요. 그런데 이 자전거도로가 생태환경에 미치는 영향에 대해서 건설하시는 분들은 되게 미미하다고 생각을 해요. 지난번 도정질의 통해서 문제제기를 했는데 앞으로 이 수변구역이랑 그다음에 산이랑 사이에 두는 자전거도로 같은 경우는 생태통로, 우리가 자동차끼리는 생태통로를 설치하잖아요, 규정이 돼 있잖아요, 법으로. 그런데 자전거도로는 그런 어떤 규정이 없어요. 이게 되게 미미하다고 생각하는데 사실 자전거도로에서 로드킬 당하는 거랑 그다음에 자전거도로가 생태환경에 미치는, 특히 4대강 관련해서 생긴 자전거도로는. 이게 되게 심각하게 생각하시는 분들이 많이 있는데 특히 생태계의 가장 기본이 되는 양서류, 파충류 이동하는 시기가 있더라고요, 계절별로. 그런데 그때 로드킬 당하는, 심한 경우는 거의 학살수준의 그런 경우도 있어요, 특히 초저녁 이동시간에. 그런데 이런 자전거도로가 생태환경에, 지금 자전거도로가 많이 생기고 있으니까 이런 거 관련해서 전문가니까 건설하시는 분이랑 좀 생각이 틀리실 거 아니에요? 그러니까 자체연구 통해 가지고 한번 자전거도로가 생태통로 포함해 가지고 이런 관련해서 생태환경에 미치는 영향 한번 연구해 보실 의향은 없으신지, 해 봤으면 좋겠는데 어떻게 생각하세요?
</p>
<p><b>○ 생태환경연구실장 고재경 </b> 저희가 사실 미처 자전거도로의 생태계 미치는 영향은 생각을 못 했는데요. 한번 저희가…….
</p>
<p><b>○ 임두순 위원 </b> ㎞ 수로 따지면 지금 거의 도로에 맞먹을 정도로 많이 생기고 있어요.
</p>
<p><b>○ 생태환경연구실장 고재경 </b> 그런 연구를 한번 앞으로 검토해서 연구를 수행하도록 하겠습니다.
</p>
<p><b>○ 임두순 위원 </b> 네, 제가 지켜보겠습니다. 수고했습니다.
</p>
<p><b>○ 위원장 배수문 </b> 임두순 위원님 수고하셨습니다. 두 가지만 당부 좀 드리겠습니다. 2014년 9월 16일 원장님 취임하셨죠?
</p>
<p><b>○ 경기연구원장 임해규 </b> 네.
</p>
<p><b>○ 위원장 배수문 </b> 그 후로 두 번에 걸쳐서 조직개편을 했습니다. 지원팀은 작년 10월 20일에 조직개편을 했고요, 연구팀은 올 2월 10일 개편을 했죠? 북부센터 설치와 더불어 같이 했습니다. 그래서 얼마 있으면 그게 1주년이 다 돼 갑니다. 그죠? 1주년이 되는 시점에서 특히 북부연구센터가 가장 또 핵심이 될 수 있겠는데 장단점 분석하시고 지속가능한 방법 그리고 전에 어떻게 됐었는지 자체적으로 좀 그런 거에 대해서 판단 낼 만한 자료들이 좀 나왔으면 좋겠다는 생각이 듭니다.
</p>
<p><b>○ 경기연구원장 임해규 </b> 네.
</p>
<p><b>○ 위원장 배수문 </b> 내년 6월까지 가급적이면, 가능하다면 좀 해서 의회에도 같이 공유했으면 좋겠다라는 생각이 듭니다.
</p>
<p style="padding-left:1.2em">  또 한 가지는 경기특별도 타당성에 관한 연구를 지금 하고 계시죠?
</p>
<p><b>○ 경기연구원장 임해규 </b> 네.
</p>
<p><b>○ 위원장 배수문 </b> 제가 경기특별도 촉구 건의안을 냈습니다. 그죠? 그래서 경기도가 서울시 이상의 인구를 갖고 있고 훨씬 더 많은 일들을 해야 됨에도 불구하고 공무원도 3분의 1 수준밖에 되지 않는 안타까운 현실에 있습니다. 그래서 연구가 좀 잘됐으면 하는 마음을 갖고요. 이 연구의 완성본이 되기 전에 몇몇 위원님들과 같이 공유를 좀 했으면 좋겠다라는 생각을 갖습니다. 그렇게 해 주실 수 있죠?
</p>
<p><b>○ 경기연구원장 임해규 </b> 네.
</p>
<p><b>○ 위원장 배수문 </b> 그렇게 하겠습니다. 더 이상 질의하실 위원이 안 계시므로 오늘 경기연구원 소관업무에 대한 질의와 답변을 모두 마치도록 하겠습니다.
</p>
<p style="padding-left:1.2em">  위원 여러분 그리고 임해규 경기연구원장을 비롯한 임직원 여러분! 장시간 열의를 갖고 행정사무감사에 임해 주신 위원 여러분과 행정사무감사를 위한 자료준비와 위원님들의 질의에 성심껏 답변해 주신 경기연구원장을 비롯한 임직원 여러분께 감사드립니다. 오늘 위원님들께서 지적해 주신 사항이 위원님들의 의견이 아니라 도민의 의견이라 생각하시고 앞으로 경기연구원 운영에 위원님들의 지적사항을 최대한 반영해 주시기 바라고 저희 위원님들이 요구한 자료가 있다면 근시일 내에 그런 자료들을 만들어서 보고해 주셨으면 좋겠습니다.
</p>
<p style="padding-left:1.2em">  그럼 이상으로 경기연구원 소관 사항에 대한 2015년도 행정사무감사를 모두 마치겠습니다.
</p>
<p class=''ar''>(17시03분 감사종료)
</p>
<p><hr /></p>
<p><b>○ 출석감사위원(11명)
</b></p>
<p class=''aMan''>배수문임병택최지용김호겸나득수박재순안혜영이재준이현호임두순</p>
<p class=''aMan''>장동일</p>
<p><b>○ 출석전문위원
</b></p>
<p class=''em15''>   수석전문위원 오태철
</p>
<p><b>○ 피감사기관참석자
</b></p>
<p><p class=''em15''>경기연구원장 임해규부원장 이상훈경영기획본부장 이양주</p>
<p><p class=''em15''>대외협력처장 이병관북부연구센터장 김동성연구기획실장 유영성</p>
<p><p class=''em15''>공존사회연구실장 송상훈공감도시연구실장 이외희상생경제연구실장 김군수</p>
<p><p class=''em15''>휴먼교통연구실장 지우석생태환경연구실장 고재경연구지원부장 배미성</p>
<p><p class=''em15''>행정지원부장 이용원재정지원부장 박인숙자치의정부장 신원득</p>
<p><b>○ 기록공무원
</b></p>
<p><p class=''em15''>김혜련</p>
