            <div','경기도의회',false,'{"legacy_id": "audit-8822", "files": [], "source": "kms.ggc.go.kr 행정사무감사", "url": "https://kms.ggc.go.kr/cms/mntsViewer.do?mntsId=8822"}'::jsonb,'2015-11-13'::date,'2015-11-13'::date where not exists (select 1 from public.posts where attachments->>'legacy_id' = 'audit-8822');
insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'audit','[2014.11.13. 목요일] 경기개발연구원 — 기획재정위원회 2014년도 행정사무감사','<div class="box" style="margin-bottom:16px"><b>제9대 경기도의회 기획재정위원회</b> · 2014년도 행정사무감사(2014. 11. 11. ~ 2014. 11. 24.)<br>원문: <a href="https://kms.ggc.go.kr/cms/mntsViewer.do?mntsId=7809" target="_blank" rel="noopener" style="color:var(--primary);text-decoration:underline">경기도의회 회의록 뷰어에서 보기</a></div><p>2014년도 행정사무감사 
</p>
<h4>기획재정위원회 회의록 
</h4>
<p class=''ar''>경기도의회사무처 
</p>
<p><hr /></p>
<p>피감사기관 : 경기개발연구원
</p>
<p><hr /></p>
<p>일 시 : 2014년 11월 13일(목) 
</p>
<p>장 소 : 경기개발연구원 회의실 
</p>
<p><hr /></p>
<p class=''ar''>(10시32분 감사개시)
</p>
<p><b>○ 위원장 배수문 </b> 좌석을 정돈하여 주시기 바랍니다. 성원이 되었으므로 지금부터 지방자치법 제41조, 동법시행령 제39조 및 경기도의회 행정사무감사 및 조사에 관한 조례 제2조의 규정에 의하여 경기개발연구원에 대한 2014년도 행정사무감사를 시작하겠습니다.
</p>
<p style="padding-left:1.2em">  위원 여러분 그리고 경기개발연구원장을 비롯한 임직원 여러분! 안녕하십니까? 경기도의회 기획재정위원회 감사위원장 배수문 위원입니다. 오늘은 우리 위원회 감사일정에 따라 경기개발연구원에 대한 행정사무감사를 실시하게 되었습니다. 여러분께서도 잘 아시는 바와 같이 지방의회의 행정사무감사는 집행부의 행정사무 전반에 관한 실태를 정확히 파악하여 의정활동에 반영하고 2015년도 예산안 심사자료 및 정보를 획득하여 도민의 삶의 질 향상에 기여하고자 함이 목적이므로 매우 중요한 의미가 있다고 하겠습니다. 
</p>
<p style="padding-left:1.2em">  오늘은 경기도의 싱크탱크인 경기개발연구원의 운영실태를 감사하는 것인 만큼 연구원에 대한 심도 있는 감사활동으로 경기도 발전을 위한 정책대안이 제시될 수 있도록 위원 여러분들의 적극적인 감사활동을 부탁드립니다. 아울러 감사에 임하는 원장과 임직원 여러분께서도 이와 같은 목적이 달성될 수 있도록 적극 협조해 주시기 바랍니다.
</p>
<p style="padding-left:1.2em">  그러면 감사를 시작하기 전에 증인선서를 받도록 하겠습니다. 감사를 받는 원장 및 부원장, 본부장, 실장, 부장은 증인의 자격으로 소관 업무를 보고하고 질의에 답변하기에 앞서 먼저 선서를 하셔야 합니다. 증인선서의 취지와 관계 규정을 말씀드리면 선서를 하는 이유는 이번에 경기도의회가 2014년도 행정사무감사를 실시함에 있어 증인으로부터 양심에 따라 숨김없이 사실대로 증언하겠다는 서약을 받기 위한 것입니다. 만약 증인이 허위증언을 한 때에는 지방자치법 제41조제5항 및 경기도의회 행정사무감사 및 조사에 관한 조례 제30조의 규정에 의하여 고발될 수 있습니다. 또한 증언 또는 진술을 거부한 때에는 동법 규정에 의하여 500만 원 이하의 과태료가 부과될 수 있음을 알려드립니다. 
</p>
<p style="padding-left:1.2em">  그러면 먼저 증인 출석여부를 확인하겠습니다. 피감사기관의 증인은 모두 자리에서 일어서 주시기 바랍니다. 
</p>
<p style="padding-left:1.2em">  경기개발연구원장 나왔습니까? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 네. 
</p>
<p><b>○ 위원장 배수문 </b> 경기개발연구원 부원장 나왔습니까? 
</p>
<p><b>○ 부원장 이상훈 </b> 네.
</p>
<p><b>○ 위원장 배수문 </b> 기획조정본부장 나왔습니까? 
</p>
<p><b>○ 기획조정본부장 이양주 </b> 네.
</p>
<p><b>○ 위원장 배수문 </b> 연구기획실장 나왔습니까?
</p>
<p><b>○ 연구기획실장 유영성 </b> 네.
</p>
<p><b>○ 위원장 배수문 </b> 공존사회연구실장 나왔습니까?
</p>
<p><b>○ 공존사회연구실장 박충훈 </b> 네.
</p>
<p><b>○ 위원장 배수문 </b> 공감도시연구실장 나왔습니까? 
</p>
<p><b>○ 공감도시연구실장 장윤배 </b> 네.
</p>
<p><b>○ 위원장 배수문 </b> 상생경제연구실장 나왔습니까? 
</p>
<p><b>○ 상생경제연구실장 문미성 </b> 네.
</p>
<p><b>○ 위원장 배수문 </b> 휴먼교통연구실장 나왔습니까?
</p>
<p><b>○ 휴먼교통연구실장 류시균 </b> 네.
</p>
<p><b>○ 위원장 배수문 </b> 생태환경연구실장 나왔습니까?
</p>
<p><b>○ 생태환경연구실장 김동영 </b> 네.
</p>
<p><b>○ 위원장 배수문 </b> 자치의정부장 나왔습니까?
</p>
<p><b>○ 자치의정부장 신원득 </b> 네.
</p>
<p><b>○ 위원장 배수문 </b> 행정지원부장 나왔습니까? 
</p>
<p><b>○ 행정지원부장 이용원 </b> 네.
</p>
<p><b>○ 위원장 배수문 </b> 재정지원부장 나왔습니까? 
</p>
<p><b>○ 재정지원부장 박인숙 </b> 네.
</p>
<p><b>○ 위원장 배수문 </b> 다음은 선서의 요령을 설명드리겠습니다. 선서는 전체 증인을 대표하여 경기개발연구원장이 발언대에 나오셔서 오른손을 들고 선서문을 낭독하시고 다른 증인들께서는 자리에 서서 오른손만 들어주시기 바랍니다. 그러면 선서를 해주시기 바랍니다.
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 선서! 본인은 경기도의회가 지방자치법 제41조, 같은 법 시행령 제39조제1항, 경기도의회 행정사무감사 및 조사에 관한 조례 제2조에 따라서 소관 업무에 대한 2014년도 행정사무감사를 실시함에 있어 성실하게 감사를 받을 것이며 또한 증인으로서 증언을 함에 있어서는 지방자치법 시행령 제43조제5항과 경기도의회 행정사무감사 및 조사에 관한 조례 제19조에 따라 양심에 따라 숨김과 보탬이 없이 사실 그대로 말하고 만일 거짓이 있으면 위증의 벌을 받기로 서약하고 이에 선서합니다. 2014년 11월 13일 경기개발연구원장 임해규.
</p>
<p><b>○ 위원장 배수문 </b> 모두 자리에 앉아주시기 바랍니다. 그러면 경기개발연구원장 나오셔서 간부소개와 업무보고를 해주시기 바랍니다. 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 오늘 경기도의회 기획재정위원회 행정사무감사에 존경하는 배수문 위원장님과 위원님들을 모시고 연구원의 주요업무보고를 드리게 되어 감사의 말씀을 드립니다. 우리 연구원은 경기도의 싱크탱크로서 경기도민의 삶의 질 향상을 위해 경기도정 현안을 해결하고 경기도 미래비전을 제시하는 등 임직원 모두가 열정을 다해 정책개발을 추진해 가고 있습니다. 향후에도 연구원의 발전을 위해 기획재정위원회 위원님들의 많은 관심과 성원을 부탁드립니다. 그러면 보고에 앞서 연구원의 주요 간부를 소개해 드리겠습니다.
</p>
<p style="padding-left:1.2em">  먼저 이상훈 부원장입니다. 
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  이양주 기획조정본부장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  유영성 연구기획실장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  박충훈 공존사회연구실장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  다음은 장윤배 공감도시연구실장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  다음은 문미성 상생경제연구실장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  다음은 류시균 휴먼교통연구실장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  다음은 김동영 생태환경연구실장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  다음은 신원득 자치행정부장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  다음은 이용원 행정지원부장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  다음은 박인숙 재정지원부장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  이상으로 간부소개를 마치고 연구원의 주요 업무보고를 드리겠습니다. 배부해 드린 보고자료의 목차를 봐주시기 바랍니다. 보고순서는 일반 및 재정운영 현황, 2014년 주요성과, 2015년 주요사업계획 순입니다. 
</p>
<p style="padding-left:1.2em">  먼저 일반 및 재정운영 현황입니다. 3쪽의 일반현황입니다. 저희 연구원은 1995년에 개원해서 경기도의 중장기비전 제시와 정책개발 기능을 수행하고 있습니다. 부서별 주요기능은 자료를 참조해 주시기 바랍니다. 
</p>
<p style="padding-left:1.2em">  다음은 4쪽 조직 및 인력입니다. 우리 연구원은 지난 10월 20일에 조직을 대국대과로 개편해서 1본부 1처 6실 3부 5팀으로 개편하였습니다. 이 중 연구부서로는 공존사회연구실, 공감도시연구실, 상생경제연구실, 휴먼교통연구실, 생태환경연구실의 5실이 있고 그 밖에 기획조정본부의 연구기획 기능을 강화하였습니다. 사무처는 정책컨설팅과 대외협력 업무를 관장하도록 하였습니다. 구체적인 조직개편 사항은 제2장의 2014년 주요성과 부분에서 자세히 설명드리도록 하겠습니다. 우리 원의 인력은 원장 1명, 부원장 1명, 연구직 53명, 관리ㆍ정보ㆍ기능직 19명으로 74명의 정규직원과 계약직원 107명 등 총 181명이 근무하고 있습니다.
</p>
<p style="padding-left:1.2em">  다음은 5쪽 재정운영 현황에 대해서 보고드리겠습니다. 올해의 총 예산 규모는 237억 원으로 일반회계 172억 원, 수탁용역사업 특별회계 65억 원입니다. 일반회계의 수입ㆍ지출내역을 말씀드리겠습니다. 수입항목은 경기도 출연금이 전체의 61%인 104억 원으로 가장 많습니다. 지출항목으로는 인건비가 46%인 79억 원으로 가장 많고 연구사업비가 70억 원으로 전체의 41% 정도 차지하고 있습니다. 재정난 극복을 위해 저희 연구원은 자체수입을 확대하기 위한 노력을 기울이고 있으며 수탁과제 전출금 증액, 시장가격에 맞는 용역사업 수주 등 다각도에서 해결책을 모색해 왔습니다.
</p>
<p style="padding-left:1.2em">  다음은 6쪽 기금입니다. 연구원의 기금은 총 166억 원으로 모두 안전한 금융기관에 예치하고 있습니다. 우리 원은 도 산하 공공기관으로서 위험한 투자는 지양하고 있고 안전성과 수익성을 함께 고려한 금융상품에 기금을 운용하고 있습니다. 출연기관 및 예치기관 현황은 자료를 참조하여 주시기 바랍니다.
</p>
<p style="padding-left:1.2em">  다음은 2014년 주요성과에 대해 보고드리겠습니다. 보고자료 9쪽부터 33쪽에 있습니다. 먼저 9쪽의 2014년 연구사업 목표입니다. 우리 연구원은 2014년 연구사업 목표를 민선5기 핵심사업 성과도출 그리고 민선6기 전략수립, 재정건전성 강화 및 안정적 세수확보방안 제시, 지역경제 활성화 및 분야별 삶의 질 향상방안 제시 이렇게 세 가지로 정했습니다. 그리고 이를 달성하기 위해 11개 분야의 중점사업과 3개의 추진전략을 설정한 바 있습니다. 
</p>
<p style="padding-left:1.2em">  다음은 10쪽 2014년 주요성과에 대해 보고드리겠습니다. 2014년의 주요성과는 크게 경기도 중장기비전 수립, 고객의 요구를 반영한 정책개발, 도 현안의 선제적 대응, 의정정책 연구, 대내외 소통강화, 효율적 기관운영을 위한 조직시스템 강화 이렇게 여섯 가지로 구분하여 보고드리겠습니다. 먼저 경기도 중장기비전 수립분야입니다. 
</p>
<p style="padding-left:1.2em">  첫 번째, 경기도 서비스산업 육성 중장기계획을 수립하였습니다. 이는 경기도 경제의 지속가능한 성장을 뒷받침할 핵심산업분야로 서비스산업의 발전에 대한 경기도의 중장기 정책목표와 기본방향을 설정하기 위한 것입니다. 본 연구를 통해 경기도의 서비스산업 육성종합계획의 세부적인 추진방안과 로드맵을 제시한 바 있습니다. 
</p>
<p style="padding-left:1.2em">  두 번째, 2014년 경기도 남북교류 기본구상입니다. 작년 행정사무감사에서 위원님들께서 건의하신 내용 중 통일을 대비한 남북관계의 평화문제에 대해 연구하도록 주문하신 바 있었습니다. 따라서 본 연구를 통해 남북관계 동향과 정세를 분석하고 경기도의 남북교류 현황과 문제점을 진단하여 경기도 남북교류협력사업의 분야별 발굴과 추진전략을 제시하고 경기도와 시군 간의 파트너십 구축방안을 제시하였습니다. 남북교류 기본구상에 기초한 경기도 차원의 선도적이고 체계적인 대북사업 전개를 제안하였습니다. 
</p>
<p style="padding-left:1.2em">  세 번째는 12쪽의 경기도 주거복지 정책의 방향과 과제연구입니다. 주거급여법이 2014년 제정되었고 주거취약계층을 위한 주거복지기본법이 국회에 계류 중으로 중앙정부의 주거복지정책 확대가 예상됩니다. 이러한 상황 속에서 우리 연구원은 본 연구를 통해 경기도의 최저주거기준 미달가구 등을 지역별ㆍ가구특성별로 분석하고 시군의 주거복지정책의 과제를 제시하는 등 경기도 차원의 주거복지정책의 방향과 역할을 재정립하고 주거취약계층의 문제해소 방안을 제시했습니다. 
</p>
<p style="padding-left:1.2em">  네 번째는 경기도 장사시설 중장기 수급계획 수립연구입니다. 경기도의 지역적 특성과 경제적 사회적 환경변화를 고려하여 장사시설의 공급 및 관리운영 전략을 수립하고 향후 5년간 경기도의 장사정책 방향을 제시한 바 있습니다.
</p>
<p style="padding-left:1.2em">  다섯 번째는 경인대도시권 미래발전전략 및 추진대책 수립입니다. 2013년 새 정부 출범에 대한 경기도의 대응책으로 수도권의 전반적인 문제점을 분석하고 개선대책을 수립하기 위한 목적의 연구입니다. 본 연구과제는 저출산 고령화에 따른 인구구조와 가구특성 변화, 문화심리, 생활양식 변화 등을 고려하여 대도시권 정책의 전환, 경인대도시권의 경쟁력 강화, 낙후지역의 발전, 난개발 방지 등의 대응책을 마련하고 경인대도시권 내의 지역 간 그리고 대도시권 간의 상생전략을 구체적으로 제시하였습니다.
</p>
<p style="padding-left:1.2em">  다음은 15페이지입니다. 두 번째 주요성과로 고객의 요구를 반영한 정책개발입니다. 먼저 민선6기를 준비하는 경기도의 전략과 발전전략 연구를 통해 경기도가 직면한 문제를 분석하여 민선6기에 추진할 신규 시책사업과 프로그램을 발굴하고 정책화하는 것을 제안한 바 있습니다.
</p>
<p style="padding-left:1.2em">  다음으로 경기도 교통정책3.0 과제입니다. 이 과제를 통해 지역발전을 선도하는 이용자 맞춤형 교통정책 수립을 목표로 설정해서 사람중심, 환경중심, 안전중심의 교통체계 수립방안을 제시하였으며 버스서비스 리모델링, 택시서비스 경쟁체계 도입, 주거와 일자리를 연계하는 교통체계 구축, 다목적 개방형 교통정보 제공체계 구축 등 생활형 교통정책 추진방안을 연구하였습니다.
</p>
<p style="padding-left:1.2em">  다음은 17쪽입니다. 최근 5년간 경기도의 환경민원이 지속적인 증가율을 보이고 있습니다. 이에 따른 대책으로 환경 분쟁 민원에 따른 서비스제고와 지원체계 정비 방안을 제시한 바 있습니다. 중앙정부와 유관기관과의 역할과 협조체계 구축 방안 또한 제시하였습니다. 
</p>
<p style="padding-left:1.2em">  네 번째로는 경기도 문화유산 사용가치분석 및 활용방안 연구입니다. 본 연구를 통해 경기도의 문화유산을 관광자원화 하는 등 효율적 보존과 활용을 위한 실용적 방안을 마련하였으며 문화유산콘텐츠와 활용프로그램 개발을 통해 경기도 차원의 지역부가가치 창출 방안 등을 제시한 바 있습니다.
</p>
<p style="padding-left:1.2em">  다섯 번째 친환경농산물 유통체제 개선 및 소비촉진 방안에 관한 연구에서는 최근 들어 관심이 높아진 친환경농업에 대하여 경기도의 친환경농산물 유통시스템 분석을 통해 친환경농업이 기대만큼 성장하지 못하는 문제점 등을 분석하여 경기도 친환경농산물유통센터 활성화 방안과 친환경농산물의 소비확대 방안을 제안하였습니다. 
</p>
<p style="padding-left:1.2em">  다음은 20쪽 세 번째 주요성과로 도 현안에 대한 선제적 대응입니다. 최근 발생하고 있는 도심의 싱크홀에 대하여 발생원인과 그 사례를 면밀히 조사해서 지하수위 저하와 물 순환 관점에서의 싱크홀 대응방안을 마련하였고 경기도의 선도적인 싱크홀 방지 시범사업과 제도개선 방안을 제시한 바 있습니다. 또한 경기도의 광역버스가 지속적인 증차에도 불구하고 공급부족이 해소되지 않고 혼잡해지는 원인을 분석하였습니다. 대응방안으로는 광역버스 노선계획 타당성 제도 도입, 광역급행버스 공급확대, 광역버스 요금 및 재정지원 차별화 등을 제시하였습니다. 경기도 광역버스 혼잡완화를 위한 정책방안을 모색하기 위해 지속적으로 노력하겠습니다. 
</p>
<p style="padding-left:1.2em">  다음은 22쪽 새로운 가치창출 엔진으로 인식되고 있는 빅데이터부분의 현안대응입니다. 빅데이터의 사회적 활용이 산업계 전반과 공공분야까지 확대되는 추세입니다. 사회안전지킴이와 같은 사회공익 기여, 맞춤형 의료복지ㆍ교육ㆍ민원서비스 제고와 같이 건강한 사회를 만드는데 기여할 것으로 기대됩니다. 이에 경기도 차원의 사회안전 자산으로서 빅데이터를 적극 활용하는 방안을 선진적으로 제시했습니다.
</p>
<p style="padding-left:1.2em">  다음 23쪽 메디컬 한류를 경기도에 적용하기 위한 현안대응 실적입니다. 의료관광은 성장잠재력이 높은 서비스산업으로 고용창출과 소득창출의 효과가 매우 큽니다. 이를 경기도에 적용하는 방안을 연구해 본 결과 의료관광 협동조합과 공동브랜드를 구축하고 시군의 입지를 고려하여 의료관광 클러스터를 조성하는 등 경기도 차원의 의료관광 활성화를 위한 구체적 방안을 제시하였습니다. 
</p>
<p style="padding-left:1.2em">  다음은 교통 분야 규제개혁에 대한 현안대응 실적입니다. 본 연구를 통하여 서민의 생활을 불편하게 하는 대표적 불필요한 교통규제 사례를 조사ㆍ분석하고 그 개혁 방안을 여러 가지로 제시하였습니다. 이를 통해 중앙정부의 규제개혁에 대한 신속한 경기도 차원의 대응체계 마련에 기여하였습니다.
</p>
<p style="padding-left:1.2em">  다음은 25쪽입니다. 시군을 대상으로 한 중점연구실적도 다수 있었습니다. 먼저 시군의 중장기비전을 수립한 연구실적을 보고드리면 파주시에 자족도시 달성을 위한 특화 발전전략을 제시했고 광명시의 중장기 사회복지정책을 수립하여 향후 4년간 보건복지정책 방향을 설정했습니다. 부천시 구도심의 도시정비 방안을 중장기적으로 제시해서 열악한 주거환경으로 인한 주민의 불편을 해소하기 위해 노력하였습니다. 서수원 지역을 녹색첨단산업 R&D클러스터로 조성해서 지역주민의 생활편익과 복지, 소득증대에 기여하도록 수원시가 추진하는 도시개발사업의 중장기적 방향을 제시하였습니다. 그 외에도 전 31개 시군을 대상으로 국가균형발전특별법에 의한 지역발전 5개년 계획을 수립해서 향후 5년간 지역발전정책의 실질적인 효과제고에 기여하였습니다. 시군을 중점대상으로 한 정책개발 연구도 다소 있었습니다. 과천시의 철도시설 개량과 역사신설에 대한 타당성을 분석한 정책개발 연구를 비롯해서 하남, 남양주, 시흥 등의 개발제한구역 불법시설물 정비 방안 등 총 11건의 시군 중점 정책개발 연구를 수행한 바 있습니다. 또한 시군의 현안에 선제적으로 대응했던 연구실적으로는 성남 소재 판교테크노밸리의 교통 불편 해소 방안, 광주 소재 남한산성의 지역경제의 파급효과 분석, 연천ㆍ포천지역의 규제와 지역발전전략, 용인ㆍ이천ㆍ여주ㆍ남양주 등의 지역보전권역의 합리적 관리방안 등이 있으며 현장밀착형 연구를 통해 시군의 현안에 대해 신속히 대응하고 시의성 있는 연구를 수행하기 위해 노력하였습니다.
</p>
<p style="padding-left:1.2em">  다음은 27쪽부터 28쪽까지 의정정책연구 실적에 대해 보고드리겠습니다. 그간 본 연구원은 경기도의회의 의정역량과 네트워킹 강화를 위해 노력해 왔습니다. 2014년에 의정발전 정책연구과제로 경기도의회 운영의 최고규범인 경기도의회 기본조례안 제정을 구상 중에 있고 제9대 지방의회 출범에 따른 지방의회와 집행기관의 협력체계 구축방안 연구를 수행하고 있습니다. 의정연구 교류를 활성화하기 위해 의정포럼을 개최하였고 입법지원 활동과 정책조사 등 총 354건의 의정활동을 지원하였습니다. 의정콜로키움을 개최해서 의정활동의 질적 제고에 기여하고 상임위원회별 웹진을 발간해서 의정 주요이슈에 대한 브리핑과 연구동향 등을 제공했습니다. 
</p>
<p style="padding-left:1.2em">  다음은 29쪽부터 32쪽까지 대내외 소통강화에 대한 실적을 보고드리겠습니다. 먼저 경기도의 핵심현안에 대해서 여론과 정책을 선도하고 주요 연구성과를 홍보하며 확산하기 위한 정책세미나를 7회 개최하였습니다. 또한 시군의 주요현안에 대한 현장감 있는 의견을 수렴하고 공감대를 확산하기 위해 시군 순회토론회를 3회 개최하였습니다. 국가ㆍ사회적 이슈를 발굴하고 경기도 정책대안을 모색하기 위해 내ㆍ외부 전문가로 구성된 포럼을 운영해 오고 있고 2014년에는 인구정책포럼 등 총 16회를 개최한 바 있습니다. 경기도정 특정분야에 대한 정책제안이나 아이디어를 시의성 있게 제안하는 “이슈&진단”은 2014년 총 37건을 발간하였습니다. 또한 경기도 현안을 알기 쉽게 정리하여 도민에게 전달하고 도정에 대한 이해와 정책신뢰도를 제고하고 있는 GRI TIP은 2014년 총 34건을 발간하였습니다. 위원님들도 잘 아시는 바 GG공은 연구원과 경기도가 공동으로 매주 월요일마다 도정관련 주제로 상호 교류하는 소통의 장으로 시의성 있는 주제를 선정하여 스터디 성격으로 진행하면서 지식을 공유ㆍ전파하고 있으며 참석하는 이들의 호응도 상당히 큽니다. 2014년은 총 31회 개최하였습니다. 우리 연구원은 스마트미디어 시대에 부응하기 위해 각종 연구결과를 정보콘텐츠로 제작하여 모바일 홈페이지, 웹 뉴스, 스마트폰DM, 고객맞춤형 지식을 전파하는 데 노력하고 있습니다. 특히 연구결과를 그래픽으로 도식화하여 제공하는 인포그래픽스는 고객의 이해도를 증진시키고 연구원의 지식을 적극 공유하여 전파하는 데 크게 기여하고 있습니다. 
</p>
<p style="padding-left:1.2em">  다음은 33쪽 조직시스템 강화 부분입니다. 지난 10월 20일 자 조직개편을 실시했습니다. 연구부서를 대국대과로 개편해서 부서장급 관리 인력을 줄이고 융복합ㆍ통섭연구를 활성화하도록 했고 기획조정본부의 연구기획기능을 강화하는 등 조직과 기능의 효율화를 꾀하고 연구의 시너지 효과를 창출하도록 개편했습니다. 이전의 1본부 1처 6실 5센터 4부 2팀의 직제를 1본부 1처 6실 3부 5팀으로 축소하는 조직 다이어트를 실시했습니다. 즉, 이전의 11개 연구 부서를 5개로 축소해서 공존사회연구실 등으로 슬림화 했고 연구기획실을 신설해서 연구분야의 기획기능을 강화했습니다. 경기도와 도의회의 연구수요에 더욱 적극적이고 발 빠르게 대응할 수 있을 것으로 기대하고 있습니다.
</p>
<p style="padding-left:1.2em">  다음은 2015년 주요사업계획에 대해 보고드리겠습니다. 보고자료 37쪽부터 48쪽이 되겠습니다. 먼저 37쪽의 2015년 연구사업 목표에 대해 보고드리겠습니다. 저희 연구원은 2015년 연구사업 목표를 네 가지로 설정했습니다. 첫째, 연구원 구성원들의 경영철학 공감대 확대, 국내외 학술대회 개최 등을 통한 GRI 정체성 확립입니다. 둘째는 연구윤리의 기관책임 확대, 연구윤리 규칙강화를 통한 연구윤리 확립입니다. 셋째는 산학연 협동연구로 외부소통강화, 창조적 정책발굴과 개발을 통한 학제 간 융합연구의 추진입니다. 넷째는 지역현안 의견청취 기회확대, 경기도와 경기도의회 소통강화, 시군 컨설팅 강화를 통한 수요 맞춤형 연구수행입니다. 그리고 이를 달성하기 위해 8개 부문의 중점사업을 적극 추진하도록 하겠습니다. 자세한 내용은 39쪽 주요 연구사업계획에서 보고드리겠습니다.
</p>
<p style="padding-left:1.2em">  다음 38쪽 연구사업 추진체계는 내년도에도 올해와 동일하게 연구과제사업을 중심으로 연구부대사업, 연구지원사업, 연구기반사업으로 구분하여 추진할 계획입니다. 분야별 연구사업계획을 말씀드리겠습니다. 첫 번째 공존사회 연구분야에서는 민선6기 자치역량 강화를 위한 행정체계 및 조직진단 연구, 재정위기시대의 지방재원 확충 및 재정건전성 확보방안을 연구할 계획입니다. 지방정부ㆍ공공기관 경영성과 증진을 위한 연구와 컨설팅을 강화하고 사회통합정책과 사회적경제전략에 대한 연구를 추진할 계획입니다. 경기도 국제개발협력 기본계획을 수립해서 글로벌 경기도 추진과 국제협력 강화에 앞장서겠습니다. 또한 남북교류협력사업을 더욱 구체화시키고 통일기반을 구축하는 데 노력하겠습니다. 군사시설의 민군 공동 활용방안을 모색하는 등 군 관련 현안의 상생적 해결방안을 강구하고 군사시설보호구역 조정과 규제완화에 힘쓰겠습니다. 이를 위해 2015년도에 추진할 과제는 표를 참고해 주시기 바랍니다.
</p>
<p style="padding-left:1.2em">  다음은 공감도시 연구분야에 대해 보고드리겠습니다. 경기도 특성에 부합하는 따복 공동체와 주거복지지원 확대방안에 대해 연구하겠습니다. 규제합리화와 수도권 북부지역 개발을 지원하고 경기도 내 낙후된 주거지 생활환경 개선책을 마련할 계획입니다.주택ㆍ부동산 공간 빅데이터 활용체계를 구축하며 경기도 도시경관 개선과 안전도시 조성을 위한 도시계획과 설계기준 등을 중점적으로 연구할 계획입니다.
</p>
<p style="padding-left:1.2em">  43쪽입니다. 상생경제 연구분야에서는 경기북부테크노밸리, 패션디자인빌리지, 산업단지 활성화 등 경기북부지역의 경제산업 고도화를 위한 실천전략을 수립하고 경기도의 거시경제지표에 대한 리스크 모니터링을 강화하며 경기도의 사회적경제 혁신방안을 연구해서 이를 공동체 복원과 연계하는 방안을 모색하는 등 새로운 패러다임 연구에 초점을 맞추어 나가겠습니다.
</p>
<p style="padding-left:1.2em">  44쪽의 휴먼교통 연구분야입니다. 편리하고 효율적인 굿모닝버스의 단계적 도입과 경기도형 버스준공영제 도입을 위한 추진전략을 수립하고 광역버스를 중심으로 하는 대중교통서비스표준과 시설표준을 마련하며 교통사고 최소화를 통한 안전한 경기도 만들기 연구에 주력할 계획입니다.
</p>
<p style="padding-left:1.2em">  46쪽 생태환경 연구분야에서는 분야별 환경현안 분석과 개선연구를 강화하여 유해화학물질로부터 안전한 사회를 구축하기 위해 노력하겠으며 에너지 기후변화 정책 추진, 자원의 순환체계 구축 등을 통한 자원과 에너지 선순환 기반마련 연구를 수행하고 정부3.0, 빅데이터 등을 연계하여 환경분야를 정보화하고 환경서비스를 확대하는 등 경기도의 안전과 건강한 환경을 만드는 정책연구에 주력하겠습니다.
</p>
<p style="padding-left:1.2em">  47쪽의 자치의정 연구분야는 지방분권의 실효성 제고와 지방의정 발전을 위한 정책연구 수행을 통해 도의회 정책능력 향상과 의정활성화를 선도하고 도의회 및 행정부와의 공동세미나, 토론회 등을 개최하여 생산적인 지방의정기반으로 도정협력체계 구축에 주력할 계획입니다.
</p>
<p style="padding-left:1.2em">  다음은 48쪽의 2015년도 연구사업계획 총괄에 대해 보고드리겠습니다. 2015년도에는 연구과제사업으로 기본연구과제 15건, 정책연구과제 100건 등 총 310건의 연구과제를 계획하고 있습니다. 11월 말 이사회에서 2015년 연구사업계획을 최종 확정할 예정입니다. 나머지 사업의 내용은 도표를 참조하여 주시기 바랍니다.
</p>
<p style="padding-left:1.2em">  다음은 51쪽의 2014년 연구과제 목록과 61쪽의 2013년 행정사무감사 처리요구사항 조치결과는 허락해 주신다면 자료로 대신하겠습니다.
</p>
<p style="padding-left:1.2em">  이상으로 연구원의 주요 업무보고를 모두 마치겠습니다. 경청해 주셔서 감사합니다.
</p>
<p>업무보고서(경기개발연구원)
</p>
<p><b>○ 위원장 배수문 </b> 임해규 원장 수고하셨습니다. 다음은 감사를 위한 질의 답변 순서가 되겠습니다. 감사의 효율적인 진행을 위해서 질의는 일문일답으로 하되 질의시간에 제한을 두도록 하겠습니다. 우선 위원님 한 분당 10분씩의 시간을 드리고 추가질의는 일단 10분을 드리도록 하겠습니다. 그리고 10분의 추가질문이 끝나면 감사 진행상황과 시간 등 제반여건을 감안하여 추가질의를 할지 여부를 결정토록 하겠습니다. 원활한 감사진행을 위해 부득이 시간제한을 두게 된 점을 널리 양해해 주시면 감사하겠습니다. 
</p>
<p><b>○ 박재순 위원 </b> 진행에 앞서 자료제출 요구하겠습니다. 연구직 연구원들의 연봉자료 그것 좀 부탁드리고요. 그다음에 이수진 연구원이 발표했던 경기도 의료관광 지역파급효과 분석에 관한 자료 그것 좀 요청드립니다. 이상입니다. 
</p>
<p><b>○ 위원장 배수문 </b> 자료 준비해 주시기 바랍니다. 김호겸 위원님.
</p>
<p><b>○ 김호겸 위원 </b> 김호겸 위원입니다. 우리 경발연 연구실적과 관련해서 경기도정의 정책적인 반영현황을 자료로 주시기 바랍니다. 
</p>
<p><b>○ 위원장 배수문 </b> 그러면 질문 순서는 위원장석을 중심으로 좌우로 의석배열에 맞춰 진행하는 걸로 하겠습니다. 오늘은 최지용 위원님, 김호겸 위원님, 박재순 위원님 순으로 질의하도록 하겠습니다. 
</p>
<p style="padding-left:1.2em">  아울러 질의에 앞서 위원장으로서 한 가지 부탁의 말씀을 드리면 위원님들의 질의에 원장의 답변이 어려울 경우 업무담당 실장 및 부장 등 실무자가 답해도 좋습니다. 다만 직과 성명을 분명히 밝히고 동의를 얻은 후 답변하여 주시기 바랍니다. 그러면 최지용 위원님부터 질의하여 주시기 바랍니다.
</p>
<p><b>○ 최지용 위원 </b> 화성 출신의 최지용 위원입니다. 원장님이 부임하기 전부터 업무보고 상황을 듣고 보니까 많은 연구와 많은 실적을 올렸습니다. 수고 많으셨다고 말씀을 드리고요. 민선6기 출범 이후에 남경필 지사가 안전한 경기도를 만들겠다는 공약이 있었습니다. 그거 보면 싱크홀에 대한 연구가 아주 발 빠르게 잘 이루어졌습니다. 그럼에도 세월호의 대형사고가 있은 뒤에 판교 환풍구 사고도 또 연이어 발생이 됐는데 크고 작은 사건들이 빈번히 일어나고 있습니다. 무수히 많은 연구를 했으면서도 그동안 안전사각지대에 대한 연구는 왜 체크를 못하셨는지 그것에 대해서 우선 답변을 부탁드립니다.
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 저희가 사실 작고 큰 사고가 나면 그것에 대해서 사고원인 진단분석하고 또 개선방안을 마련하고 이러한 것을 사실 사후적으로 해온 것이 사실인 것 같습니다. 그런데 사실 경기도 지역이 아니라 전국의 다른 지역에 어떤 사고가 나면 그 사고를 경기도 차원에서 신속하게 대응하기 위한 그와 같은 연구도 저희들이 진행하고 있습니다. 그래서 위원님이 말씀하신 것처럼 모든 것에 대해서 미리미리 진단하고 대응책을 마련하는 것이 미흡한 점이 있는 건 사실입니다만 몇 가지들은 저희들이 선제적으로 준비하고 또 대응책을 내고 그렇게도 해 오고 있습니다. 
</p>
<p><b>○ 최지용 위원 </b> 그동안 이 자료를 봐도 그 많은 연구자료가 실적이 나왔음에도 도민이 안전한 그런 위험부담을 느끼는 불감증에 젖어있다고나 할까 그런 연구는 하나도 없습니다. 지금 사고에 대한 안전사각지대에 대한 연구실적이 한 건도 없습니다. 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 예를 들면 위원님, 경기도 지반침하 같은 것이 생길 경우에 지반침하에 대한 지도를 작성해서 취약지역을 미리미리 파악을 하는 그런 연구도 저희들이 수행한 바가 있습니다. 
</p>
<p><b>○ 최지용 위원 </b> 그 부분도 서울에서 싱크홀이 발생되면서 하다가 지금 발 빠르게 한 건 다행입니다마는 그 이전에는 우리 자체에서 싱크홀 사고가 있기 전에 연구한 것은 아니지 않습니까?
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 네, 그렇죠. 
</p>
<p><b>○ 최지용 위원 </b> 그래서 싱크홀도 발 빠르게 잘 하셨다고 제가 말씀은 드렸습니다마는 그 이후에 세월호의 엄청난 대형사고가 일어났음에도 우리 주변의 안전사고의 대책 이런 것을 지사의 공약도 있었음에도 그런 부분을 발췌를 못하고 원론적인 연구만 해 왔지 실제 그런 시민ㆍ도민들이 안전한 안전사고에 대한 연구는 없었단 말입니다. 이 부분에 대해서 어떻게 생각하십니까? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 사실 모든 사고나 안전사각지대를 미리 파악하고 또 선제적으로 대응하고 이와 같은 문제의식을 가져야 된다고 생각이 듭니다. 이런 것들은 필요하다고 보고요. 그래서 사실 요즘 빅데이터 관련된 문제의식이 많고 또 연구도 많은데요. 사실 빅데이터를 활용해서 여러 가지 사고발생 가능한 요소들을 빅데이터를 통해 추출해내고 취약지구를 저희들이 진단해내고 또 거기에 맞게끔 대응방안을 세우고 이와 같은 연구를 앞으로 꾸준히 모든 분야에서의 환경분야, 주택분야, 도로분야 여러 분야에서 그와 같은 노력을 추가로 기울여야 될 것으로 생각이 듭니다. 
</p>
<p><b>○ 최지용 위원 </b> 그래서 지적을 해 드리는 것인 만큼 앞으로 원론적인 발전적인 연구도 중요하지만 우선 사람이 살아가는 데 있어서 안전의 사각지대를 더 발굴해서 연구를 해주시기 바라고요. 우리 의정연구센터에서도 많은 실적을 올려주셨는데 센터 조직운영에 대해서 감사원의 지적을 받으신 적이 있죠? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 그렇습니다. 
</p>
<p><b>○ 최지용 위원 </b> 그렇다면 앞으로 어떤 방식으로 의정연구센터를 운영할 것인지, 대안이 무엇인지 그것에 대한 답변을 듣겠습니다.
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 사실 감사원의 지적은 위원님들 잘 아시는 바와 같이 도의회에 대한 지원이 있는데 저희 연구원에서 도의회의 의정연구를 중복적으로 하는 것에 대한 지적이었습니다. 그런데 또 한편으로는 저희 GRI는 경기도청만 의뢰자가 아니고 경기도의회도 저희들에 대한 정책의뢰자이기 때문에 경기도의회 의원님들이 제기하는 여러 가지 정책연구를 당연히 수행하는 것이 기본기능이기도 합니다. 그런데 다만 감사원 지적은 보좌관을 활용하는 것처럼 경기도의회가 기능을 한다고 하는 점에 대한 지적이었기 때문에 저희들이 마침 내년부터는 아마도 도의회에서 열한 분의 입법조사관을 채용할 것으로 보고 있기 때문에 그 입법조사관들이 구체적인 의원님들에 대한 입법지원 기능을 하고 또 저희들은 연구정책기능을 강화해서 서로 연계해서 사업을 잘 진행한다고 하면 그간의 우리가 새로이 의정연구센터를 세움으로 해서 도의회 정책기능을 강화한다고 하는 소기의 목적을 달성하는 데 큰 무리가 없을 것으로 그렇게 생각이 듭니다. 
</p>
<p><b>○ 최지용 위원 </b> 그 부분에 대해서도 자료로 다시 한 번 구체적으로 제출을 해 주시면 좋겠고요.
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 네, 알겠습니다. 
</p>
<p><b>○ 최지용 위원 </b> 우리 사무처의 어떤 기능, 이것에 대해서 아마 우리 원장님께서 질언을 해 주신 것 같은데요, 먼저. 지사님한테 한번 질언하신 적이 있으셨나요? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 다시 한 번…….
</p>
<p><b>○ 최지용 위원 </b> 사무처장의 역할이라든지 필요성에 대해서 말씀하신 적 있으셨죠?
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 네. 저희가 아직은 저희 내부 조직편제 개편에 사무처는 아직까지 개편을 하지는 못했습니다, 아직은. 그런데 저희들이 지금 도청하고도 협의를 진행 중에 있습니다만 저희 생각은 저희들이 점점 대외적인 정책협의기능이 매우 강화돼야 한다고 보고 있기 때문에 도청이나 또는 도의회와 정책협의기능과 그리고 산하 시군과 정책협의를 해야 되는 일들이 많습니다. 그래서 그와 같은 일들을 전담하는 것으로 해서 사무처를 정책협력처로 바꾸어서 운행을 하면 좋지 않겠나 하는 그런 아이디어를 가지고 있습니다. 그리고 그간에 행정지원기능은 사실 연구기획기능하고 통합해서 해도 큰 무리가 없겠다 이렇게 생각을 했습니다. 그래서 사무처를 향후 정책협력처로 전환을 하면 어떤가 하는 그런 문제의식을 가지고 있습니다. 
</p>
<p><b>○ 최지용 위원 </b> 문제는 사무처장의 위치, 자리가 꼭 필요한 자리냐는 얘기입니다. 따지고 보면 관피아 자리 아니겠습니까? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 사실 꼭 그렇다고 보지는 않습니다. 그러니까 크게는 두 가지인데요. 하나는 행정부와, 우리 GRI가 행정부 산하기관이고 또 행정부와도 정책의뢰를 항상 받는 가장 주요한 저희들의 정책의뢰의 대상이 행정부기 때문에 그 행정부…….
</p>
<p><b>○ 최지용 위원 </b> 정책의뢰 대상이 원장님 계시지 않습니까? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 네. 
</p>
<p><b>○ 최지용 위원 </b> 부원장 계시고 그런데 행정기능에 대한 협의가 꼭 그렇게 필요한 건지, 물론 도의 산하기관이겠습니다만 행정을 하던 분이 와서 꼭 그런 중간역할을 해야 하는 것인지 또 역할이라는 것이 그렇게 특별하게 연구원 박사님들의 사무분장을 한다든지 이런 역할도 아닐 거고 원장님 산하에 많은 분들, 조직원들이 있지 않습니까? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 그렇습니다. 
</p>
<p><b>○ 최지용 위원 </b> 충분히 그 기능 해내지 못하겠어요? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 그런데 아마 어느 연구원이나 도책 연구원이나 시책 연구원의 경우는 사실 행정하고의 연계가 필요하기 때문에 다양한 형식의 분들이 파견 형식으로도 와 있고 그렇게 되어 있습니다만 하여튼 행정경험 있는 분이 연결하는 역할은 필요하다고 생각이 듭니다. 
</p>
<p><b>○ 최지용 위원 </b> 지금 시간이 다 됐습니다. 그래서 이 부분을 분명하게 세부적으로 꼭 필요한 것인지 아닌지를 자료로 좀 제출을 해주시기 바랍니다. 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 네, 알겠습니다. 
</p>
<p><b>○ 최지용 위원 </b> 이상 질의 마치겠습니다. 
</p>
<p><b>○ 위원장 배수문 </b> 최지용 위원님 수고하셨습니다. 이어서 김호겸 위원님 질의하여 주시기 바랍니다. 
</p>
<p><b>○ 김호겸 위원 </b> 김호겸 위원입니다. 우리 경기도의 정책을 생산해내는 싱크탱크로서 수고하시는 연구진 여러분들 또 임해규 원장님 새로 취임한 이래 많은 기대를 하고 있습니다. 또 오늘 준비하느라 수고 많으셨고요. 저는 간단히 지난해에 감사에서 나온 얘기를 잠깐만 짚고 넘어가도록 하겠습니다. 아마 존경하는 배수문 위원장님이 말씀 주셨던 제안이신 것 같은데 경기개발연구원의 명칭 있잖아요, 명칭? 명칭에 대해서 새로운 명칭을 요구했는데 지금 완료로 돼 있는데 어떻게 새로운 명칭이 나왔습니까, 혹시? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 사실 저희가 작년에 감사지적 제시사항이어서 연구원 내에서 또 논의를 활발하게 하고 있는데 사실 원장 바뀌고 이러면서 매듭은 못 지은 것 같습니다. 그래서 지금도 우리가 이름을 그대로 쓰고 있는데요. 일단 내부적으로는 논의를 한번 했습니다. 
</p>
<p><b>○ 김호겸 위원 </b> 그런데 왜 완료로 나왔습니까? 경기개발연구원이 여러분들 다 아시겠습니다만 개발연구원 하니까 혹시 우리가 70∼80년대의 개발독재시대의 단어가 연상이 돼서 우리 싱크탱크에 맞는 그런 명칭이 나와야 되지 않나 이런 말씀을 드리는 것이고 또 우리 대부분 광역단체에 보게 되면 연구원이 대부분 발전연구원으로 통일돼 있는 건 다 아시죠? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 네. 
</p>
<p><b>○ 김호겸 위원 </b> 이번에 민선6기 들어와 가지고서도 넥스트 경기니 굿모닝 경기니 이런 얘기도 나왔고 또 여러분 아시다시피 세종연구소가 우리 대한민국의 통일안보를 연구하는 기관 아닙니까? 또 여의도연구소는 새누리당의 같은 싱크탱크로서 각종 선거를 주도하는 그런 두뇌들이, 전략가들이 모여 있는 그런 연구소죠? 하여튼 이런 걸 참고하셔서 임해규 원장님이 새로 오셨으니까 우리 GRI의 모든 것을 담아낼 수 있는 새로운 명칭, 공모를 하든지 한번 새롭게 하실 용의가 있으십니까? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 그렇습니다. 
</p>
<p><b>○ 김호겸 위원 </b> 한번 좀 해주시기를 바라고요. 두 번째로 우리 경기발전연구원의 주요사업의 연구과제나 목록을 보게 되면 복지부분이나 농업부분이 다소 소홀한 것 같습니다. 연구가 부족한 걸로 나와 있고 또 2015년도의 주요사업, 연구사업에도 보게 되면 그런 목록이 빠져있는데 잘 아시겠습니다마는 복지는 시대의 정신, 시대의 화두 아니겠습니까? 특히 OECD에 우리 노인자살률이 1위이고 줄줄 새는 복지비문제라든가 또 복지사각지대 해소문제라든가 등등 여러 가지 복지정책이 개발이 돼야 되고 또 지자체별로 지역실정에 맞는 복지정책도 우리가 GRI에서 생산해내야 되지 않나 이런 생각을 하고 있는데 동의하십니까? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 그렇습니다. 
</p>
<p><b>○ 김호겸 위원 </b> 그런 부분에 대해서 좀 연구해 주시고 특히 농업정책, 우리 농업정책이 이번에 예산이 얼마인지 아십니까, 우리 전체 예산에? 1.3%대예요, 1.3%. 그럼 우리 농업인구나 축산인구나 그런 걸 볼 때 영호남 농민에 비해서 적지도 않은데 예산은 1.3%에 불과합니다. 농업은 생명산업입니다. 이런 생명산업이 지켜져서 우리 농민들의 소득증대가 이루어질 수 있도록 그런 방향, 정책 이런 것들도 우리 연구원에서 나와야 된다고 보는데 동의하십니까? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 네. 
</p>
<p><b>○ 김호겸 위원 </b> 이런 부분들도 특별히 좀 짚어주시고요. 어제 저희들이 북부지역의 감사를 했었습니다마는 북부지역은 여러 가지 방안을 가지고 계신 것 같은데 북부지역의 수도권규제개혁과 균형발전을 위한 연구가 좀 필요하다고 보고요. 그런 경기도의 균형발전 차원에서 북부지역의 인구가 320만입니다. 면적이 전체의 40%를 차지하고 있는데 10개 시군의 재정자립도는 34%에 불과합니다. 주요 원인은 여러 가지가 있겠습니다만 그리고 지역총생산량이 45조 원, 전체의 18%에 불과한 아주 열악한 기반을 가지고 있죠? 그 원인은 여러 가지가 있겠습니다만 수도권정비법이라든가 군사시설로 인한 여러 가지 규제, 상수원보호, 환경문제. 이중삼중으로 규제를 받고 있고 또 기반시설이 상당히 부족해 있죠, 도로망이라든가. 또 안보 위협도 최근에 나오죠. 안보 위협 때문에 기업인들의 투자가 많이 위축이 되고 그렇기 때문에 이 지역의 피해상황에 대해서, 개선에 대해서 연구도 좀 많이 필요하고 지역경제 활성화를 시킬 수 있는 연구가 나와야 된다고 보는데 동의하십니까? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 네. 
</p>
<p><b>○ 김호겸 위원 </b> 그리고 북부발전을 위한 지원센터 건립도 우리 경발연의 노력이 좀 이루어져야 될 걸로 보는데 동의하십니까? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 북부발전 지원센터는 뭘 의미하는지 좀……. 
</p>
<p><b>○ 김호겸 위원 </b> 그러니까 북부발전을 위한 지원센터, 어떤 그런 지원센터 건립하는 부분도 한번 좀 생각해봐야 되지 않나 이런 말씀을 드린 겁니다. 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 위원님께서 좀 그 기능이나 역할에 대해서 구체적으로 말씀을 주시면 검토해 보도록 하겠습니다. 
</p>
<p><b>○ 김호겸 위원 </b> 하여튼 경기도의 균형발전 차원에서 북부지역 또 여주ㆍ가평ㆍ양평 등 동부지역에도 여러 가지 현안을 좀 연구하셔서 지역경제가 활성화될 수 있도록 그런 부분도 좀 적극적인 연구를 해달라는 말씀을 드리고요. 지금 경기도가 상당히 재정이 어렵죠? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 그렇습니다. 
</p>
<p><b>○ 김호겸 위원 </b> 우리 연구원에서도 수입이 될 수 있는 각종 연구용역 사업을 해야 된다고 보는데 지금 시군에서 위탁사업 받은 연구실적이 말이죠. 2011년도에 44건에서 2014년도에 22건으로 좀 많이 줄어있고요, 대폭 줄었고요. 또 외부용역도 2012년에 48건에서 2014년에 23건으로 실적이 많이 줄어있습니다. 이 부분에 대해서는 알고 계시나요? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 그렇습니다. 
</p>
<p><b>○ 김호겸 위원 </b> 이거 어떻게 이해를 해야 되죠, 이런 부분은? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 우선 저희 연구원이 기초자치단체나 또는 도에서 학술용역사업을 줄 때 그간에는 수의계약이 그냥 가능했습니다. 그런데 법이 바뀌어서 저희들이 전부 다 공모로 하게 되었습니다. 그런데 공모로 하게 되면 어떤 일이 벌어지냐면 각 대학의 산단 같은 곳에서 공모해 들어오게 됩니다. 그래서 굉장히 경쟁이 치열해지고 절차가 복잡해지고 이렇게 되기 때문에 아무래도 저희들이 수탁을 받는 비율이 떨어질 수밖에 없게 되어 있습니다. 
</p>
<p><b>○ 김호겸 위원 </b> 그래서 본 위원은 우리가 가장 훌륭한 연구진을 가지고서도 불구하고 각 시군에서 어떤 연구의뢰라든가 또 외부용역 같은 이런 실적이 많이 떨어지고 있기 때문에 우리 경기개발연구원 신뢰가 부족한 건지 아니면 홍보가 부족한 건지 아니면 연구용역 사업에 대한 비중을 안 두는 건지 여러 가지 생각을 하게 되는데 앞으로 우리 연구원에서 이러한 수익구조에도 우리가 좀 신경을 써서 우리 연구원의 위상뿐만 아니라 중요한 수입재원이 될 수 있도록 각별히 홍보나 그런 비중을 둬 달라는 그런 말씀을 드리겠습니다. 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 그래서 아까 말씀드린 것처럼 저희가 그간의 사무처의 기능을 시군에서의 수탁사업을 개발하고 또 저희들이 따오고 이렇게 하는 기능이 중요하다고 보기 때문에 정책협력처로 기능전환을 하면 어떻겠는가 하는 아이디어를 가지고 있습니다. 
</p>
<p><b>○ 김호겸 위원 </b> 그리고 요즘 위원님들께서도 많은 관심을 갖고 있는 경기도 분도 문제, 많이 들어보셨죠? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 네. 
</p>
<p><b>○ 김호겸 위원 </b> 이번에 북부지역인가 60몇 명이 동의를 하셔서 분도의 문제를 거론하고 있는데 이게 정치권에서 끊임없이 때만 되면 나오는 문제이기도 합니다. 그런데 중요한 것은 우리 경기개발연구원 차원에서 분도 문제에 대해서 연구가 필요한 시점이 아닌가 이렇게 생각하는데 어떻게 생각하시죠? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 사실 그간에는 위원님도 잘 아시다시피 이게 경기도 내의 기초자치단체 간에 이해대립이 있고 또 각각의 지방을 대변하시는 우리 도의원님들 사이에서도 상당한 의견대립이 있기 때문에 이런 경우에는 연구를 안 하는 것이 오히려 도움이 된다 이런 입장이었다고 들었습니다, 저도. 그런데 제 생각은 분도를 하게 될 때 어떤 범위의 문제를 다뤄야 되는지, 그게 단지 경기도의 분도만이 아니라 그게 대한민국 행정체계 전체의 변화와도 관련이 있기 때문에 그런 문제를 포함해서 또 분도를 하게 될 경우에 생기는 여러 가지 문제들, 이런 점들을 종합적으로 한번 검토하는 매우 전문적이고 중립적이고 종합적인 그런 검토를 하는 것이 저는 맞다고 생각합니다. 그래서 제 생각에는 한번 하면 좋겠다고 생각이 드는데 그런 연구를 보통 언론이나 또는 활용하시는 분들은 필요한 부분만 뽑아서 이걸 이슈화하기 때문에 굉장히 조심스럽게 접근해야 된다고 하는 우려도 굉장히 많은 것으로 알고 있습니다. 그래서 위원님들이 좀 의견을 모아주시면 집행부와도 협의를 해서 저희들이 그런 어떤 연구를 한번 해봤으면 하는 게 원장으로서 개인적인 생각입니다. 
</p>
<p><b>○ 김호겸 위원 </b> 이 분도 문제가 과거에서부터 쭉 나왔는데 최근 들어서 상당히 많이 대두가 되고 있습니다. 우리 위원님들도 관심이 많고 실질적으로 분도가 필요한 것인지, 분도를 통해서 어떤 북부지역의 이익이 있는 건지, 최근에 엊그저께 남경필 지사님이 도정연설을 통해서 북부지역에 많은 지원대책을 발표를 해서 청사진을 많이 발표를 해주셨는데 그와 별도로 우리가 분도에 대한 것, 우리 연구원 차원에서 분도를 하는 원인에서부터 여러 가지 다방면에서 분도에 대해서 이제 연구원 차원에서 연구가 절대적으로 필요한 시점이다. 거기에 대한 연구를 좀 해달라는 부탁의 말씀을 드리면서 본 위원의 1차 질문을 마치도록 하겠습니다. 수고하셨습니다. 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 네, 알겠습니다. 
</p>
<p><b>○ 위원장 배수문 </b> 김호겸 위원님 수고하셨습니다. 이어서 박재순 위원님 질의하여 주시기 바랍니다. 
</p>
<p><b>○ 박재순 위원 </b> 수원 출신 박재순 위원입니다. 먼저 천이백오십만의 경기도의 역할을 하고 있는 경기개발연구원 모든 분들에게 고맙다는 말씀을 드리면서 질의를 시작하겠습니다. 
</p>
<p style="padding-left:1.2em">  어제 산업통상부에서 나오는 뉴스가 있었어요. 자체 공무원행동강령의 강화ㆍ시행에 들어간다고 밝혔는데 거기서 징벌적 손해배상 규정을 도입했다 이렇게 나왔습니다. 거기에 주제가 뭐냐면 관용차량, 항공기를 이용한 출장으로 쌓인 마일리지 또 공용재산을 썼다가 적발되면 3배의 환수를 하겠다, 이렇게 나와 있었습니다. 그 내용 보셨습니까? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 못 봤습니다. 
</p>
<p><b>○ 박재순 위원 </b> 못 보셨어요? 그래서 경기도 종합감사에서 2013년 4월 15일∼19일에 지적사항이 있었습니다. 그 때에 국외출장 시 항공마일리지 관리가 잘 되고 있지 않은 부분에 대해서 지적사항이 있는데 그 부분은 알고 있는지 또 그 부분에 대해서 현재 어떻게 시행하고 있는지 말씀해 주시기 바랍니다. 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 이거는 담당자가 좀 답변을 하도록 하면 어떻겠습니까? 
</p>
<p><b>○ 재정지원부장 박인숙 </b> 항공마일리지는 박사님들이 출장을 다녀오시면 저희한테 마일리지가 몇 포인트 쌓였다 해서 지금 적립하고 있는 상태입니다. 통보를 해주십니다. 
</p>
<p><b>○ 박재순 위원 </b> 거기에 대한 장부를 지금 별도로 관리하고 있다는 거죠? 
</p>
<p><b>○ 재정지원부장 박인숙 </b> 네, 관리하고 있습니다. 
</p>
<p><b>○ 박재순 위원 </b> 거기 관리하고 있으면 장부 하나 좀 자료 제출 부탁드리겠습니다. 
</p>
<p><b>○ 재정지원부장 박인숙 </b> 네, 알겠습니다. 
</p>
<p><b>○ 박재순 위원 </b> 감사합니다. 그다음에 두 번째 질의를 드리겠습니다. 경기개발연구원은 장애인의 법정의무고용비율에 있어서 2%를 지키지 않고 있었죠? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 네. 
</p>
<p><b>○ 박재순 위원 </b> 우리가 그래서 부담금으로 2009년도부터 약 436만 5,000원을 부담금으로 내고 있었고 또 2010년부터는 2.3%로 올랐단 말입니다. 그래서 3명에서 4명으로 사람 고용비율이 늘어났어요. 사실 그래서 2010년도에 우리가 부과해야 될 부과금이 636만 원이었고 또 2012년도부터는 부과금, 부과특례라는 게 없어졌죠? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 네. 
</p>
<p><b>○ 박재순 위원 </b> 없어지면서 거기에 대한 부담금이 사실 늘어나는 데 대해서 장애인 의무고용비율에 대해서 달성하기 위한 대책이라든지 앞으로 어떻게 해야겠다든지 하는 게 있으면 말씀해 주시기 바랍니다. 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 사실 그런 문제의식을 가지고 있습니다만 쉽지 않은 저희들 원의 사정은 사실 저희들이 주로는 박사 연구자들이나 석사급 연구원들이 저희 구성원들의 대부분입니다. 그런데 저희들이 그런 전문인력의 경우에 아무래도 장애인의 학위취득 비율이 많이 떨어지는 것 같습니다. 그래서 꼭 채용을 할 때 채용선발기준에 장애인에 대해서는 우대한다고 쓰여 있습니다만 사실 저희가 다 공모로 하는데 그 공모에 응시하는 비율이 많이 낮은 게 주요한 원인인 것 같고요. 그런데 앞으로는 이 점에 대해서 역시 경영을 하는 사람의 의지문제가 상당히 크다고 생각이 듭니다. 그래서 저희들이 박사 인력을 충원하거나 석사인력을 충원할 경우에 이 점을 특별히 경각심을 가지고, 문제의식을 가지고 충원을 하는데 힘쓰도록 그렇게 해서 최소한 법적으로 갖춰야 될 어떤 비율은 지키도록 그것을 목표로 해서 꼭 지키도록 노력하겠습니다. 
</p>
<p><b>○ 박재순 위원 </b> 왜 그러냐면 사실 공직사회에서 또 산하단체에서 장애인에 대한 특별한 배려를 하지 않으면 고급인력을 배치할 곳이 없습니다. 또 일반 기업체에서는 잘 사용하지를 않고 있고요. 그렇기 때문에 고용비율을 강제조항으로 이렇게 만들어서 국가에서 하고 있는데 그 부분을 분명하게 지켜서 우리 경기도의 모범이 될 수 있는 연구기관으로 이렇게 거듭나기를 저는 부탁을 좀 드리겠습니다. 그 부분에 대해서 어떻게 생각하십니까? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 네, 노력하겠습니다. 
</p>
<p><b>○ 박재순 위원 </b> 감사합니다. 또 경기도의 5대 서비스산업에 경기도 신성장동력 강화 방안에 대해서 말씀을 하셨어요. 거기에 보면 5대 산업이라는 게 의료서비스, 문화 콘텐츠, 관광, 레저, 사회서비스 등을 이렇게 기획하고 지원한 것으로 말씀을 하셨는데 여기서 경기도 31개 시군의 사업과 관련하여 중장기적으로 사업이 추진되었거나 계획한 것이 있다면 말씀해 주시기 바랍니다. 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 그간에는 사실 위원님도 잘 아시다시피 고양이 MICE산업 쪽으로 이렇게 되어 있습니다. 의료서비스나 이런 것은 수원에 의료와 관련된, 바이오와 관련된 그와 같은 연구가 진행이 되고 있고 그래서 저희들의 연구가 사실 저희들이 연구를 해서 그거에 따라서 클러스터를 조성한다든지 이런 측면보다는 자연스럽게 사업이 지자체의 주도로 혹은 나름대로의 계획으로 사업이 되는 것을 더 발전시키고 네트워킹을 하고 그런 방안 연구가 저희들의 주로 그간의 연구였습니다. 그렇기 때문에 말씀 주신 것처럼 이미 상당 부분은 진행되고 있는 사업들이라고 그렇게 보셔야 될 것 같습니다. 
</p>
<p><b>○ 박재순 위원 </b> 원장님 말씀대로 의료원에 관한 질의를 좀 하겠습니다. 사실 우리 경기도의료원을 관리하는 곳이 우리가 수원, 이천, 포천, 의정부, 안성, 파주의료원 6개의 의료원이 있어요. 그런 인프라가 잘 구축돼 있는데 이런 인프라가 구축된 그 상황에서 과연 의료산업에 뛰어들어서 지금 서울을 비롯한, 강남에서 주로 많이 하고 있습니다. 의료산업에 대해서 관공서에서 앞장서서 하고 있는 걸로 제가, 강남 3구를 비롯한 중구까지 뛰어들고 있는데 우리는 아직 그런 준비를 하지 못하고 있었고 이런 인프라의 6개의 의료원이 잘 갖춰져 있었지만 거기에 대한 연구라든지 그 부분에 대해서 앞으로 어떻게 해나갈 건지 아직 정확하게 지금 답변이 나와 있지 않죠? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 저희들이 사실 의료원을 통해서 중국에 혹은 중국과 여러 나라에서 의료서비스를 받기 위해서 오는 거를 의료원과 연계해서 하는 연구는 아직 하지 못한 것으로 알고 있습니다. 그렇지만 의료관광 차원에서 우리 경기도가 어떻게 연결해서 할 건가 하는 연구는 우리 연구원에서 수행한 바가 있습니다. 
</p>
<p><b>○ 박재순 위원 </b> 그래서 원장님에게 말씀을 드린다면 사실 의료원 원장들하고 이 부분에 대해서 논의를 해야 된다고 저는 생각을 합니다. 그래서 지난번에 이천의료원에 대해서 30억까지 나가면서 지금 300병상의 어떤 병상을 짓기 위한 의료사업을 실시하기 위해서 서민과 중산층을 위해서 병동을 짓기 위한 그런 일들을 하고 있는데요. 그 600억이라는 돈이 투입되면서 우리 의료원에서도 거기에 대한 충분한 의료관광산업에 대한 자료가 있어야 된다. 그리고 이것은 중국이나 동남아뿐만 아니라 일본에서도 또 미국에서도 우리 의료산업에 대해서 굉장히 호의적인 반응을 갖고 있고 선진국은 선진국대로 또 후진국은 후진국으로서의, 우리나라에 와서 의료를 받기를 굉장히 원하는 것으로 알고 있습니다. 거기에 대한 부분을 본다면 선진국은 우리가 확실히 쌉니다. 또 후진국에서 우리를 보면 성형수술을 비롯한 모든 부분들에 있어서 분명히 우리가 잘하고 있고 기술면에 있어서나 또 가격면에 있어서나 모든 것이 좋기 때문에 특히 중국의 여성들을 비롯한 남성들이 많이 오는 것으로 알고 있습니다. 여기에 대한 우리의 인프라가 분명하게 갖추어져 있습니다. 6개 의료원 그다음에 관광 이런 것, 수원의 화성을 비롯한 여주의 세종대왕릉을 비롯한 많은 이런 시설들이 갖추어져 있는데 앞으로 여기에 대해서 많은 연구를 하셔서 우리 원장님께서 좀 더 나은 경기도민의 삶의 질이라든지 앞으로 발전에 대해서 더 많은 일들을 해 줬으면 좋겠다는 말씀을 저는 드리고 싶습니다.
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 네, 잘 알겠습니다. 위원님도 잘 아시다시피 이것은 저희가 아주 그런 우수한 의료기관이 경기도에도 이미 있고 또 그런 의료기관을 유치하는 이런 노력들이, 특히 북부지역도 그렇고 이런 곳에도 유치하고자 하는 노력도 있고 그렇기 때문에 그런 선진적인 이런 병원들을 경기도에 유치하는 것과 함께 의료관광으로 연결하는 이런 기획은 가지고 있습니다. 그래서 그쪽은 앞으로 저희들이 연구에 더 박차를 가해서 하겠다는 말씀을 드리고 다만 의료원 부분은 사실 위원님 잘 아시다시피 의료서비스 취약대상을 중심으로 서비스를 하는 곳이기 때문에 사실 그곳이 바로 어떤 의료관광하고 연결시키기는 사실 쉽지 않은 것 같습니다. 그런데 위원님께서 아이디어를 지금 제기하셨기 때문에 과연 우리 경기도의 의료원이 의료서비스 취약계층에 대해서 주로 사업을 하는 곳입니다만 그 아이디어도 어쨌든 한번 다시 검토를 해보도록 그렇게 하겠습니다. 
</p>
<p><b>○ 박재순 위원 </b> 원장님한테 왜 이 말씀을 드리느냐 하면 6개 의료기관이 분명한 건 서민과 중산층을 위한 의료기관입니다. 그런데 만성적자에서 헤어나지 못하고 있습니다. 또 의료서비스나 병원이나 기계가 모두가 낙후돼 있습니다. 이러한 부분들을 새롭게 하면서 거듭 태어나지 않으면 그 의료원이 갈 길이 없다는 거죠, 제가 보는 입장에 있어서. 그렇기 때문에 지금 이천의료원이 새롭게 태어나고 있는데 이런 부분을 하나의 적용대상으로 삼아서 확실하게 한다면 앞으로 만성적자에서 흑자로 전환하는 또 우리 경기도민의 일자리가 창출되고 먹을거리가 생산된다는 거죠. 그래서 신성장동력에 앞장설 수 있는 경기도의 싱크탱크 역할을 충분히 해주실 것을 저는 기대하겠습니다. 이상으로 질의를 마치겠습니다. 
</p>
<p><b>○ 위원장 배수문 </b> 박재순 위원님 수고하셨습니다. 나득수 위원님 질의하여 주시기 바랍니다.
</p>
<p><b>○ 나득수 위원 </b> 나득수 위원입니다. 연구원은 각자의 전문분야에서 전문성을 인정받는 권위자시죠, 전문가시죠? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 그렇습니다. 
</p>
<p><b>○ 나득수 위원 </b> 그런데 이해관계자가 존재하는 연구분야에 있어서 연구원으로서 어떤 전문적인 의견, 독립성과 객관성을 유지해서 전문적인 의견을 제시하는 것과 이해관계자들의 의견을 어떤 외압이라든가 여러 가지 요인에 의해서 의견을 반영하는 것 사이에는 상충관계가 있지 않습니까? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 일반적으로 그렇다고 생각합니다. 
</p>
<p><b>○ 나득수 위원 </b> 고민이 있죠. 연구원분들에 대한 고민이 있을 거라고 저는 생각하는데 그렇지 않습니까? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 잘 모르겠는데요. 질문의 의도를 잘 모르겠습니다. 
</p>
<p><b>○ 나득수 위원 </b> 저는 어떤 면에서 상충되는 면이 있을 거라고 생각합니다. 이럴 경우에 전문가들의 독립성과 객관성이 훼손되지 않도록 하는 GRI측에서의 통제방법 이런 것들이 존재하나 그걸 여쭤보고 싶습니다.
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 우선은 저희들이 연구윤리규정이 있습니다. 그래서 연구자가 양심에 따라서 자기의 전문성을 토대로 연구를 해야지 윤리를 해치는 그런 행위는 하지 못하도록 하는 연구윤리가 있고요. 그런데 제가 그런 사례가 있어 말씀을 주시면 검토하고 답변을 드리겠습니다만 제가 알기로는 지금 우리 연구원 박사님들이 특정한 이해관계가 있는 게 있다거나 이렇지는 않은 걸로 알고 있습니다. 
</p>
<p><b>○ 나득수 위원 </b> 그렇습니까? 그러니까 전문가들을 통제하는 시스템이 다 갖춰 있잖아요, 전문가집단에서는요. 다 지금 갖춰져 있거든요. 그런데 우리 GRI 차원에서는 갖추어져 있느냐, 않느냐는 걸 여쭤보는 겁니다. 갖춰지지 않으셨다면 통제방법을 어떻게 설계를 하셔서 갖추어 주셨으면 하는 그런 바람입니다.
</p>
<p style="padding-left:1.2em">  제가 예를 들자면 광명-서울 민자고속도로인가요. 부천시 통과구간 용역에 대해서 제가 한 말씀 드리겠는데 그 용역보고를 보니까 몇 차례를 하셨어요. 그런데 약간씩 다 바뀌어요. 그러니까 이해관계자들의 의견을 반영하는 거죠. 그렇다면 연구원 입장에서는 이게 도로를 한번 개설하게 되면 근 몇백 년을 가야 되는데 어떤 이해관계자들의 외압이라든가 아니면 집행부나 시민단체라든가 그런 외압에 의해서인지 어쩐지 모르겠지만 약간씩 바뀌는 게 참 안타깝다는 생각을 좀 했습니다. 그래서 제가 이런 통제방법이 있느냐 여쭤보는 겁니다. 애초에 그런 연구가 연구원이 자기 전문지식을 가지고 이건 절대 이렇게 해야 된다, 그런 방향으로 가야 되는데 약간씩 바뀌는 게 좀 안타까워서 제가 말씀드립니다. 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 그것은 이제 알겠습니다. 나 위원님이 지적하시는 그 사항은 제가 너무나 잘 아는 내용이니까요. 제가 말씀을 드리면 구체적으로 그 연구는 사실 부천시가 의뢰한 연구였습니다. 그렇기 때문에 의뢰자의 일종의 의견이 있었고요. 그것은 민원을 해결해야 되는 측면이 있었기 때문에, 그러니까 환경적인 요소와 교통의 요소와 그리고 또 민원인들의 이해관계자들의 의견이 있는 상태에서 저희들이 연구를 했어야 됐기 때문에 사실 연구자는 가장 최적의 노선을 만들어 내는 것이 연구 과업이었습니다, 사실 그 의견들 조정해서. 
</p>
<p><b>○ 나득수 위원 </b> 기존의 국토부인가요. 기존의 국토부안을 가지고 연구를 시작한 거 아닙니까? 기존의 국토부안이 잘못됐으면 그것부터 부정을 하고 들어갔어야죠. 저는 그런 생각을 합니다. 아무튼 이해관계자들의 의견을 반영하는 것도 좋잖아요. 그러면 전문가로서 어떤 객관성 그걸 유지를 해야 된다고. 국토부안이 잘못 됐으면 국토부안부터 부정을 하고 가야 되지 않나 저는 그런 생각을 해봅니다. 그래서 통제방법이 있느냐 이렇게 여쭤보는 것입니다.
</p>
<p style="padding-left:1.2em">  다음 질문 드리겠습니다. 우리 경기도 재정문제와 관련된 연구에 대해서 여쭤보겠습니다. 부동산경기가 지금 많이 침체돼 있죠? 그래서 조금 활성화된다고 하지만 아직까지 계속 침체되고 있는 실정입니다. 그렇다면 우리 GRI에서 지방세 세수확보 방안이라든가 그다음에 세입제도 개선방안 등에 관한 연구가 제가 봤을 때는 미약한 것 같은데 어떻게 생각하십니까? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 사실 지방세수 확충을 위한 여러 가지 지방세와 국세의 비율과 관련됐거나 아니면 구체적인 지방세 세목에 관한 용어나 이런 연구는 비단 올해나 작년의 문제가 아니라 꾸준히 GRI에서 해왔던 이슈였고 또 많은 연구물이 축적되어 있습니다. 그런데 위원님 잘 아시다시피 그게 전부다 법 개정과 연관돼 있는 것이다 보니 연구를 암만해도 이게 반영이 되지 않고 빈 목소리 메아리로 돌아오는 것 때문에 그럼에도 불구하고 말하자면 이번 최근에 담배소비세 문제와 관련해서 저희 GRI가 연구도 하고 또 의견도 내고 그렇게 했습니다. 그래서 저희들이 매번 근본적인 세제시스템에 대한 연구와 또 구체적인 세금에 대한, 세목에 대한 이런 연구는 꾸준히 해왔다고 생각합니다. 
</p>
<p><b>○ 나득수 위원 </b> 그렇습니까? 제가 봤을 때는 그렇게까지 많은 연구, 연구분야에서 보면 우리 재정문제와 관계된 연구가 좀 미약하다고 보는데요. 앞으로 그렇다면 많은 재정문제와 관련된 연구활동을 많이 해주시기를 제가 제안드립니다. 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 꾸준히 하겠습니다. 
</p>
<p><b>○ 나득수 위원 </b> 다음 질문 드리겠습니다. 연구원 성과평가가 지금 어떻게 제도개선을 하신다는데 어떻게 제도개선을 하시는 건가요? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 다시 한 번 질의…….
</p>
<p><b>○ 나득수 위원 </b> 우리 연구원들 성과평가문제. 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 저희가 그러니까 그간에 평가시스템은 평가시스템 대로 그간에 작동을 해 왔습니다. 그리고 그 성과시스템에 맞추어서 보수체계도 대응해서 가지고 있습니다. 그런데 그것이 약간은 어떤 연구원들 내에서 객관성이나 공정성이나 이런 것에 대한 문제제기가 있었습니다. 그래서 저희들이 지금 그것을 연구하는 전문가들과 함께 안 마련을 위해서 지금 논의를 진행하고 있습니다. 
</p>
<p><b>○ 나득수 위원 </b> 지금 완료된 것은 아닙니까? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 네. 
</p>
<p><b>○ 나득수 위원 </b> BSC에 대한 평가방법이나 이런 것들은, 객관적인 평가방법들은 도입 생각은 없으십니까? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 제가 지금 말씀주신 사항은 잘 모르겠는데요. 내용을 제가 잘 몰라서 답변드리기는 어렵습니다만…….
</p>
<p><b>○ 나득수 위원 </b> 성과평가방법 중에 많이 도입되는 게 BSC죠. Balanced Scorecard라고 그래서 BSC.
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 이게 연구원 내부의 박사님들의 의견만으로 하지 않고 또 외부전문가들과 도와 저희들이 성과시스템이나 보수시스템은 도와 다 협의해야 합니다. 저희들이 독자적으로 할 수는 없습니다. 그래서 협의해서 좋은 방안을 만들고 또 위원님께서 말씀하신 그런 평가방법에 대해서도 검토해 보도록 하겠습니다. 
</p>
<p><b>○ 나득수 위원 </b> 아무튼 조직문화는 어떤 객관적인 평가방법만이 조직을 성공적으로 이끌 수 있는 방법이라고 저는 생각합니다. 아무쪼록 객관적인 성과평가방법을 만들어 내주시기를 제안하겠습니다. 
</p>
<p style="padding-left:1.2em">  다음 질문하겠습니다. 제가 올 2014년도에 보면 우리 연구원의 연구실적이 상당히 미미해요. 다른 해에 비하면 50%도 안 되는 것 같아요. 그죠?
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 2014년도 연구실적이요?
</p>
<p><b>○ 나득수 위원 </b> 네. 외부용역이라든가 홍보비 집행이라든가 이런 연구활동에 대한 내용들이 너무 미미한 것 같아요. 그렇지 않습니까? 지방선거가 있어서 그러신가요? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 아주 특별히 적거나 이렇지는 않았다고 생각이 들고요. 아까 말씀드린 것처럼 수탁용역의 경우에는 여러 가지 여건변화가 있고 또 수탁용역은 많은 경우 정부에서 어떤 법이 예를 들어서 오염총량제에 대한 법이 생긴다 그러면 시군에서 그와 관련된 연구를 하기 때문에 저희들이 수탁용역을 많이 하게 됩니다, 어떤 해에는. 그런 정도의 차이가 있었고 올해 지방선거가 있어서 특별히 적었거나 그렇지는 않았다고 생각이 됩니다. 
</p>
<p><b>○ 나득수 위원 </b> 자료를 보고 계십니까? 자료를 보면 작년에는 56건 했는데 외부용역 같은 것도. 이번에는 23건밖에 안 되고 그런 상황입니다. 아무튼 선거가 있든 없든 간에 GRI 본연의 연구활동은 지속돼야 된다고 봅니다. 이점 유념해 주시기 바랍니다. 이상으로 질의 마치겠습니다. 
</p>
<p><b>○ 위원장 배수문 </b> 나득수 위원님 수고하셨습니다. 오늘 경기개발연구원 행정사무감사에 대한 언론의 관심이 지대한 것 같습니다. 신아일보의 임순만 국장님을 비롯한 십여 분의 언론인분들이 오셔서 취재 중입니다. 열띤 취재에 감사드리고요. 보다 더 우리 진행하는 것들에 대해서 객관적으로 볼 수 있도록 잘 협조해 주셨으면 좋겠다라는 말씀을 드립니다.
</p>
<p style="padding-left:1.2em">  이어서 이현호 위원님 질의하여 주시기 바랍니다.
</p>
<p><b>○ 이현호 위원 </b> 이천 출신 이현호 위원입니다. 임해규 원장님과 전 직원 여러분께 행정사무감사 자료제공과 준비해 주신 것에 대해서 수고가 많다는 말씀을 드리겠습니다. 앞서서 지금 존경하는 나득수 위원님께서 말씀하셨는데 경기개발연구원의 기능은 도정의 중장기 비전제시와 아울러서 정책개발인데 행정사무감사서 3쪽을 보면 방금 전에 나득수 위원이 말씀하셨지만 3년간 외부용역현황을 보면 2012년도하고 13년도에 비해서 14년도에는 실적이 매우 저조합니다. 외부용역 준 것에 대해서 많이 줄어들었는데 그 이유가 무엇인지에 대해서는 방금 말씀하셨기 때문에 제가 더 이상 듣지는 않겠습니다. 앞으로 이것 외부용역을 통해서 우리 도정에 반영하고 특별히 도의회에도 반영해서 경기도가 정말 다른 도에 비해서 앞장서서 발전할 수 있는 그런 계기를 만들어 주시기를 제가 부탁드리면서 나름대로의 견해를 잠시 부탁을 드리겠습니다. 
</p>
<p style="padding-left:1.2em">  원장님, 제가 말씀드린 것에 대해서 앞으로 외부용역을 어떻게 늘릴 계획이 있으신 건지에 대해서 제가 말씀을 여쭸습니다. 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 사실 우선 아까 2014년 연구실적이 부족한 것에 대해서 제가 추가로 하나 말씀드리면 저희 보고서에 드린 것은 9월 말 기준입니다, 2014년은. 그런데 수탁연구의 경우에 사실 기초시군이나 이런 곳에서 추경 때 연구용역을 주는 경우가 또 많습니다. 그래서 그런 연구성과가 여기에 잡혀 있지 않다는 말씀을 드려야 될 것 같고요. 이게 완료되면 2014년도에 시작한 과제들이 나중에 많이 늘어나게 되죠, 추후로. 그런 점에 사정이 있다는 말씀을 드리고요. 저희들이 경기도청도 그렇고 시군도 그렇고 거기서 오는 수탁연구용역이 대부분 그런 곳에서 옵니다. 그런데 아까 말씀드린 것처럼 법률이 엄해져서 저희들이 전부 다 공모를 통해서 하게 돼 있는데 따라서 공모를 하게 되면 여러 가지 제약조건이 생깁니다. 그러면 실력이 있으면 받을 수 있는 거지 왜 못 받느냐 이렇게 말씀하시면 간단한데 사실 경쟁에 노출되게 되면 저희들이 다 받아올 수 없기 때문에 떨어질 걸로 예상하고 있습니다. 그래서 저희들은 그쪽 분야의 수주를 하기 위한 여러 가지 전략도 세워야 되고 또 집중적인 노력도 해야 되기 때문에 그런 곳의 역할을 강화하는 쪽으로 조직개편에 저희들이 반영할 생각입니다. 
</p>
<p style="padding-left:1.2em">  그래서 저희들이 수탁연구는 저희들한테 왜 중요하냐 하면 수탁연구가 대부분 현장연구를 하지 않을 수가 없습니다. 아주 구체적으로 연구를 해야 되기 때문에 기술연구도 많고. 그래서 그런 연구를 저희들이 해야 저희들 연구의 질도 높일 수 있는 측면도 있기 때문에 저희들이 수탁연구를 결코 게을리하지 않겠다는 말씀을 드립니다.
</p>
<p><b>○ 이현호 위원 </b> 계약한 것을 보면 거의 100%가 다 수의계약으로 돼 있어요. 그죠?
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 네. 
</p>
<p><b>○ 이현호 위원 </b> 수탁 수의계약을 하다보면 잘못 하게 되면 입찰공고한 것에 비해서 주위사람들한테나 기관에 대해서 특별히 한쪽에 치우치든가 아니면 연구원하고 어떠한 관계가 있어서 밀어주기가 쉽지 않습니까? 그래서 그런 오해를 받을 수 있을 것 같아요, 제가 볼 때는. 지금 보니까 전부다 수의계약이고 특별히 제가 어느 기관을 지칭 안 하겠지만 한 군데도 많이 수의계약된 게 있습니다. 원장님께서 감사 끝나고 나서 살펴보시면 알겠지만 한쪽에 치우친 경향도 있는데 제가 그건 말씀을 안 드리겠습니다마는 부득이 수의계약을 꼭 해야 할 이유가 있는 건지 한번 말씀해 보세요.
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 그러니까 연구과제용역은 저희들이 위탁을 받는 게 있고요. 수탁과제가 있고 저희들이 부분적으로 위탁을 주는 경우도 있습니다. 부분위탁을 주는데요. 저희들 정책과제는 저희 연구원은 연구하기 위한 기관이기 때문에 저희들이 자체로 다 그냥 연구를 합니다. 그런데 특정연구의 경우는 기술용역이 필요한 경우가 있습니다. 그러니까 기술용역 부분만 별도로 부분위탁을 주는 경우가 있고요. 그런 경우도 다 저희들이 공개경쟁입찰을 통해서 주고 있습니다. 그런데 지금 말씀하신 거는 저희들이 받는 경우에, 저희가 수탁하는 경우에 대부분 수의계약으로 그간에 이루어졌는데요, 그간에는. 그런데 수의계약으로 이루어지는 것은 그간 왜 그게 당연하게 되었냐면 저희 경기개발연구원은 경기도청과 경기도 산하 시군의 정책연구를 하기 위해서 존재하는 기관이기 때문에 응당 그 일을 하는 것이 저희들의 일입니다. 그런데 그걸 공개경쟁입찰을 하게 되면 어떤 일이 벌어지게 되냐면 가격입찰을 합니다. 그러니까 이게 거의 추첨에 의해서 하게 됩니다, 최저가격입찰이 되니까. 그래서 예를 들면 저희들이 올해에도 15건 공개경쟁입찰에 응했는데 9건을 저희들이 낙찰됐습니다. 가격경쟁입찰이기 때문에 붙고 안 붙고는 운에 따르는 경우가 많습니다, 능력보다는. 왜냐하면 그게 저희가 자격이 있느냐 없느냐는 대부분의 연구원들이, 대학이나 이런 곳이 기본자격을 다 갖춰 가지고 들어오기 때문에요. 거기에서는 점수 차이가 별로 없고 그다음에 가격으로 들어가는데 가격으로 들어가면 이게 최저가격으로 누가 잘 쓰냐 하기 때문에 저희들이 낙찰이 잘 안 된다는 거죠. 잘 안 됩니다. 그렇기 때문에 사실상 저희들 생각은 법이 잘못됐다고 생각합니다, 오히려. 그러니까 경기도청이나 혹은 산하 시군에서 줄 때는 적정성으로 잘 가려서 저희들에게 주는 게 맞지 그거를 모든 곳에 일반적으로 하는 것은 맞지 않다. 물론 과제에 따라 다릅니다. 어떤 과제는 공개경쟁입찰을 하는 것이 바람직한 것도 있고 그렇습니다만 모든 것을 공개입찰 하는 것은 저희 연구원의 입장으로 봐서는 연구원의 본래 설립취지와 맞지 않는 측면이 있다고 저희들은 그렇게 생각합니다. 
</p>
<p><b>○ 이현호 위원 </b> 앞으로 하여간 용역을 주실 때요. 정말 공개입찰 못지않게 수의계약을 하시더라도 철저를 기해 주시기를 부탁드리고요. 
</p>
<p style="padding-left:1.2em">  행정사무감사 405쪽을 보면 경기도의회 의원연구단체하고 GRI가 최근 3년간 공동연구현황을 보면 2012년도에는 아무 것도 없습니다. 또 2013년도에 3건, 2014년도에도 0건입니다. 경기도의 싱크탱크로서 우리 경기도의회 연구단체와 긴밀한 협력 하에서 경기의 비전과 미래를 제시해야 한다고 생각하는데 공동연구현황이 부진한 사유가 무엇인지 또한 앞으로 활성화 대책이 있으시면 말씀해 주시기 바랍니다. 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 경기도의회 의원연구모임과의 공동연구를 말씀하시는 것이죠? 
</p>
<p><b>○ 이현호 위원 </b> 네. 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 저희들이 의정연구센터가 아시다시피 한 1년 몇 개월 됐습니다, 시작을 한 지. 그러니까 그전에는 아무래도 공동연구나 이런 것들이 기관과 기관 차원에서 이루어졌습니다만 저희들이 의정연구센터가 생기면서는 훨씬 교류가 빈번해지고 또 함께하는 의정연구포럼도 있고 콜로키움도 있고 시군순회토론회도 있고 이렇기 때문에 아마 그런 것들이 반영돼서 특별히 그런 연구물이 적은 것으로 이해가 됩니다만 앞으로 의원님들의 어떤 의원연구단체랄지 아니면 개별 의원님이랄지 이렇게 아이디어를 내시고 하면 저희들이 공동연구를 활발하게 진행해서 앞으로 경기도의회와 GRI의 어떤 협력, 그러니까 정책연구를 협력으로 하는 그와 같은 쪽으로 사업을 진행하도록 하겠습니다. 
</p>
<p><b>○ 이현호 위원 </b> 지금 말씀하신 대로 그 약속 꼭 지켜주시고 우리 경기도의회에 특별한 관심을 가져주시고 우리 경기도의회 128명의 의원들이 정말 의정활동을 열심히 할 수 있도록 큰 뒷받침을 해주시기를 부탁드리면서 저의 질문을 마치겠습니다. 
</p>
<p><b>○ 위원장 배수문 </b> 이현호 위원님 수고하셨습니다. 이어서 안혜영 위원님 질의하여 주시기 바랍니다. 
</p>
<p><b>○ 안혜영 위원 </b> 수원 출신 안혜영 위원입니다. 자료가 좀 요구한 것이 덜 왔는데 먼저 온 자료부터 간단하게 보면서 말씀드리겠습니다. 본 위원이 비공개 연구보고서 리스트를 달라고 했습니다. 비공개 연구 리스트를 보면 10년도부터 제가 받았는데 좀 눈에 띄는 것이 있습니다. 연구보고서를 비공개 리스트로 만들어서 보고하지 않는 이유가 따로 있나요? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 보통은 예를 들면 쌀 산업 발전방안 이런 것은 위원님도 잘 아시다시피 농민들의 이해관계가 굉장히 밀접한 연구이고 그래서 이거는 저희 연구원에서 객관적인 연구를 나름대로 했을 경우에 그것이 미치는 영향 같은 것들을 고려해서 일단 연구평가 실무위원회 할 때 이건 좀 나가면 민감한 것 같다 그러는 경우에……. 
</p>
<p><b>○ 안혜영 위원 </b> 그러면 그런 연구들은 대부분 자체적으로 사회적 이슈나 이런 것들을 선정해서 제목이나 연구내용을 정하는 건가요? 아니면 수탁을 받아서 하는 건가요? 여기 보면 수탁연구도 많이 있거든요? 수탁연구라는 게 뭡니까? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 수탁연구는 저희 연구원의 재정으로 그냥 수행하는 것이 아니라 외부기관, 그거는 경기도일 수도 있고 산하 시군일 수도 있습니다. 주로 경기도나 산하 시군입니다. 
</p>
<p><b>○ 안혜영 위원 </b> 그러니까 외부에서 그런 연구에 대해서 의뢰를 하게 되면 그 연구과제들은 다 오픈되는 게 맞는 것 아닌가요? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 그런데 그거는 연구를 발주하는, 의뢰하는 의뢰자가 비공개를 요구하는 경우에 그렇게 됩니다, 수탁의 경우는. 
</p>
<p><b>○ 안혜영 위원 </b> 그러면 눈에 띄는 것, 제가 자료를 지금 막 받아서 하나를 예로 들자면 내용이 거의 비슷합니다. 매년 했습니다. 2010년도에 여주군 수질오염총량관리계획, 가평군 수질오염총량관리계획, 여주군 수질오염총량관리계획 이행평가 그리고 가평군에 대한 것도 이행평가 그리고 2011년도에도 여주군 수질오염총량관리계획 이행평가, 가평군 관련된 이행평가 그리고 2012년도에 또 했습니다. 가평군에 관련된 게 2건이 또 있고요. 이렇게 비슷한 건이 계속 연도마다 있습니다. 이게 제가 볼 때에는 4대강 관련된 연구보고서라고 생각이 들거든요. 혹시 연구결과에 대해서 알고 계신 게 있습니까? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 제가 전부 다는 모릅니다만 알고 있는 것도 있습니다. 
</p>
<p><b>○ 안혜영 위원 </b> 연구결과가 어떻게 나왔습니까? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 그러니까……. 
</p>
<p><b>○ 안혜영 위원 </b> 시간이 없습니다. 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 예를 들면……. 
</p>
<p><b>○ 안혜영 위원 </b> 간단하게만 답을 해주시죠. 수질오염에 대해서 평가를 요청한 거라고 하면 수질오염도에 대한 평가 아니겠습니까? 결과만 단순하게 한 마디 해주신다면? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 그러니까 한강에 보 설치로 인한 수질오염 가능성, 생태계 교란 가능성 이런 것에 대한 연구도 저희들이 비공개로 처리한 바가 있는데요. 그런 경우는……. 
</p>
<p><b>○ 안혜영 위원 </b> 제가 말씀드린 이 건에 대해서만 답을 해주십시오. 여주하고 가평에 대해서 나온 수질오염평가거든요. 해마다 했습니다. 답하기가 곤란하신 건가요, 아니면 내용을 모르고 계신 건가요? 내용을 알고 계신 것 있으면 답변을 좀 도와주시죠. 
</p>
<p><b>○ 생태환경연구실장 김동영 </b> 생태환경연구실장 김동영입니다. 
</p>
<p><b>○ 안혜영 위원 </b> 단답으로 해주세요. 지금 벌써 시간이 너무 많이 됐습니다. 
</p>
<p><b>○ 생태환경연구실장 김동영 </b> 그 과제는 4대강하고는 특별한 직접적인 연관은 없는 과제입니다. 
</p>
<p><b>○ 안혜영 위원 </b> 그러면 여주ㆍ가평에 대한 수질오염평가를 집어서 한 이유가 뭔가요? 
</p>
<p><b>○ 생태환경연구실장 김동영 </b> 단지 한강수계 수질오염총량제를 도입을 하면서 해당 시군마다 다 계획을 세우도록 돼 있는데 그 안의 내용들이 주로 지역의 발전계획이나 이런 현안들이 굉장히 많습니다. 
</p>
<p><b>○ 안혜영 위원 </b> 이게 수탁연구거든요. 
</p>
<p><b>○ 생태환경연구실장 김동영 </b> 네, 그렇습니다. 
</p>
<p><b>○ 안혜영 위원 </b> 어디에서 의뢰하신 건가요? 
</p>
<p><b>○ 생태환경연구실장 김동영 </b> 대부분 다 시에서 직접 요청한 겁니다. 
</p>
<p><b>○ 안혜영 위원 </b> 다 시에서 요청하신 건가요, 해마다? 
</p>
<p><b>○ 생태환경연구실장 김동영 </b> 그렇습니다. 
</p>
<p><b>○ 안혜영 위원 </b> 그러면 연구결과에 대해서 자료를 제출해 주실 수 있죠? 
</p>
<p><b>○ 생태환경연구실장 김동영 </b> 그 보고서는 저희들이 검토해서 제출하도록 하겠습니다. 
</p>
<p><b>○ 안혜영 위원 </b> 간단하게 결과에 대한 것만, 결과 요약된 거 1∼2장짜리 있을 것 아니에요? 
</p>
<p><b>○ 생태환경연구실장 김동영 </b> 네. 
</p>
<p><b>○ 안혜영 위원 </b> 그거를, 해마다 나온 결과보고서를 저한테 오늘 좀 제출을 해주시기 바랍니다. 
</p>
<p><b>○ 생태환경연구실장 김동영 </b> 네, 알겠습니다. 
</p>
<p><b>○ 안혜영 위원 </b> 그리고 자문위원단에 대해서 여쭤보겠습니다. 자문위원단이, 원장님. 자문위원단이 경기도에 몇 개가 있죠, 경발연에. 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 지금 6개쯤으로 알고 있는데요. 
</p>
<p><b>○ 안혜영 위원 </b> 본 위원이 알기로는 7개입니다. 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 하나는 아마 구성이 아직까지 안 돼서……. 
</p>
<p><b>○ 안혜영 위원 </b> 안 된 건가요? 사회통합위원회 말씀하시는 건가요? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 네, 아직 구성이 안 됐습니다. 
</p>
<p><b>○ 안혜영 위원 </b> 그런데 자료에는 7개로 저한테 주셨어요. 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 아마 구성 중이라고 그렇게 돼 있을 것 같은데요. 
</p>
<p><b>○ 안혜영 위원 </b> 그런가요? 구성된 걸로 저한테는 주셨는데 여하튼 뭐 중요한 건 아니고요. 지금 여기 총괄자문위원단의 간사가 누구로 되어 있나요? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 현재 이수진 박사님으로 되어 있습니다. 그런데 약간 조정이 좀 필요할 것 같습니다. 
</p>
<p><b>○ 안혜영 위원 </b> 이유가 뭔가요? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 간사는 본인이 하시겠다고 해야 하거든요. 그냥 막 하라고 하는 것은 아니거든요. 
</p>
<p><b>○ 안혜영 위원 </b> 아, 선정한 지 얼마 안 되셨구나. 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 그렇습니다. 
</p>
<p><b>○ 안혜영 위원 </b> 일반적으로 선정이 됐기 때문에 지금 조정을 하신다는 얘기죠? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 그렇습니다. 
</p>
<p><b>○ 안혜영 위원 </b> 알겠습니다. 자문단에 위원회별로 명단을 봤습니다. 위원님들 명단을 봤는데 혁신위원회와 경기도 일자리, 글로벌위원회 이런 여러 가지 말씀하신 위원회들이 있는데 내용을 보면 위원회의 구성된 위원들이 대부분 전공이라든가 하고 있는 일, 소속되어 있는 연구단체라든가 이런 게 연관성이 거의 다 비슷한 것 같아요, 하고 계시는 쪽에. 그런데 특이하게 혁신위원회는 구성의 기본이 뭐였나요? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 혁신위원회는 사실 특정한 분야를 딱 선정한 것은 아니었고요. 경기도정 전반에 대해서 좀 새로운 아이디어를 만들어 내고 그 아이디어로 정책화할 수 있는 것들은 또 연구를 후속연구도 하고 이런 취지로 만든 것입니다. 
</p>
<p><b>○ 안혜영 위원 </b> 본 위원도 그렇게 생각합니다. 지금 자문위원단에서 다섯 번 회의를 개최했는데 그중에 두 번이 혁신위원회 회의였습니다. 혁신위원회의 개최목적을 보면 지금 원장님이 말씀하신 것처럼 경기도정의 전반적인 것과 혁신적으로 개혁을 하겠다는 취지가 많이 있는 것 같습니다. 본 위원도 그게 필요하다고 생각을 하고요. 그런데 명단을 보면 거의 열두 분, 열세 분 간사님까지 그 정도, 지사님 빼고. 그렇게 포함이 되어 있다고 하면 거의 연관성이, 거의 여덟 분 정도가 문화 쪽에 치우쳐 있습니다. 그리고 나머지 서너 분이 경제 한 분, 공과 쪽에 두세 분 이런 쪽으로 되어 있거든요. 그런데 문화 쪽으로 대부분 다 직장이라든가 소속되어 있는 곳, 전공이라든가 이런 것들이 다 문화 쪽에 포함되어 있는데 그게 어떻게 경기도정의 전반이라고 할 수 있죠? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 우선은 잘 아시겠지만 나머지 자문위원회가 특정한 곳의 전문가들이 주로 많지 않습니까? 그러다 보니까 자연스럽게 그런 경제, 금융 또는 기타 외교 이런 쪽은 그쪽 자문위원회가 아마 주로 하게 되기 때문에……. 
</p>
<p><b>○ 안혜영 위원 </b> 혁신위원회가 두 차례 회의를 하셨죠? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 네. 
</p>
<p><b>○ 안혜영 위원 </b> 두 차례가, 한 번 회의를 한 게 1차 회의의 내용이 경기도 내 농생대 부지방문 및 활용방안 검토였습니다. 그렇죠? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 그렇습니다. 
</p>
<p><b>○ 안혜영 위원 </b> 이 내용이 뭐죠? 얼마 전에 현장방문도 위원님들이 하신 걸로 알고 있는데……. 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 그런데 저는 참석을 하지 못해서 아주 구체적인 내용은 제가……. 
</p>
<p><b>○ 안혜영 위원 </b> 회의내용을 모르시나요? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 네. 
</p>
<p><b>○ 안혜영 위원 </b> 회의내용이 결과적으로 보면 농생대를 문화 관련된 쪽으로 개발을 하자는 거죠. 또 언론에 나온 것도 안 보셨나요? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 언론은 못 봤고요. 얘기는 들었습니다. 
</p>
<p><b>○ 안혜영 위원 </b> 뭐가 여기에 설치되어 있는 쪽으로 혁신위원회에서 자문을 하셨나요? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 구체적으로는 모르겠는데 농생대 부지 방문하면서 그것을 어떻게 하면 좀 문화 쪽으로 활용할 수 있을까 하는 점에 관심을 가진 것으로 알고 있습니다. 
</p>
<p><b>○ 안혜영 위원 </b> 첫 번째 회의도 문화 쪽으로 결과를 내셔서 그쪽 관련된 상임위 위원님들이 그쪽 현장방문까지 하셨습니다. 그리고 벌써 언론보도까지 하셨고요. 그리고 2차 회의가 음악도시 가평, 재즈페스티벌 할 때 방문하셨죠. 거기서도 논의하신 것이 문화 관련된 것이었습니다. 자라섬을 어떻게 문화도시로 만들 것인가에 대한 내용이 대부분이었습니다. 그렇다고 하면 저도 물론 문화체육관광위원회 위원장을 했던 사람으로 문화에 대한 예산이 부족하다고 강하게 주장했던 사람 중의 하나입니다. 그런데 혁신위원회가 이렇게 회의를 한 번 하고, 두 번 정도 내용을 전달하셨는지 모르겠지만 한 번 회의를 하고 그게 벌써 정책적으로 자문을 해주는 역할이 아니라 정책과제를 던져줘서 경기도가 그 혁신위원회 말에 의해서 지금 좌지우지되고 있다는 느낌을 받지 않을 수 없습니다. 자문위원단의 역할이 뭐라고 생각하십니까? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 저는 일하기 나름으로 굉장히 적극적으로 많은 일도 할 수 있고 또는 단순히 아이디어를 제공하는 수준으로 할 수 있다고 보지만……. 
</p>
<p><b>○ 안혜영 위원 </b> 지금 경발연에 따복위원회도 있죠? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 네. 
</p>
<p><b>○ 안혜영 위원 </b> 따복위원회도 있고 그런데 따복도 그렇고 혁신위원회도 그렇고 다른 위원회는 제가 면밀히 검토하지 못해서 잘은 모르겠는데 정책지원을 하기 위해서 자문위원단이 있는 거죠. 추진을 하기 위한 집행부가 아닙니다. 그런데 정책결정을 하거나 진행을 하는 역할을 하고 있는 것이 아닌가 그런 우려를 좀 표명할 수밖에 없고요. 그리고 또 하나는 얼마 전에도 따복추진단 회의를 하는 데서 새벽까지 하시는데 같이 동참을 했었습니다. 거기서 진행과정에서 보면 우리 따복추진단이 따로 있죠, 저희 집행부에. 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 그렇습니다. 
</p>
<p><b>○ 안혜영 위원 </b> 따복추진단에서 과장님도 계셨는데 그 주도적인 역할을 임해규 원장님이 하고 계신 것 같은 느낌을 받았습니다. 주도를 하고 계셨죠? 거기에 또 예산편성도 하셨죠? 따복 관련된 예산을……. 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 제가 예산편성을 물론 한 것은 아니고요. 
</p>
<p><b>○ 안혜영 위원 </b> 경발연에서도 예산집행을 하셨나요? 민에서 주도하셨다는 걸로 알고 있었는데? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 기획을 제가 주도적으로 했습니다. 
</p>
<p><b>○ 안혜영 위원 </b> 예산집행 한 게 하나도 없습니까? 그날 1박 2일 한 회의에 의해서?
</p>
<p><b>○ 경기개발연구원장 임해규 </b> GRI에 그게 자문위원으로 되어 있기 때문에 GRI의, 우리 위원회로서의 예산집행이 된 것이죠. 
</p>
<p><b>○ 안혜영 위원 </b> 그럼 거기에 공간에 대한 거나 다과라든가 식사 그런 비용으로는 하나도 집행된 게 없습니까? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> GRI에서 비용으로 집행이 됐습니다. 
</p>
<p><b>○ 안혜영 위원 </b> 그때 저한테, 의원들한테 얘기를 할 때는 민에서 주도를 한 거라고 하셨어요. 그런데 거기에 경발연과 집행부가 참여를 한다고 했고 도의원들도 그래서 하루 전날에서야 초대를 받아서 저희들도 참여를 하게 된 거거든요. 경발연에서 주도하고 추진단에서 주도하는 거라면 당연히 의원들이 먼저 참석에 대한 소식을 들었겠죠. 그런데 본 위원이 역으로 집행부에 다 알아봤을 때도 집행부나 경발연에서 주도하는 것이 아니라고 알고 갔습니다. 그런데 예산집행을 경발연에서 했다고 하는 건 경발연에서 주도를 했다는 거죠, 그 회의를. 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 그렇습니다. 그 회의는 따복공동체위원회에서 한 사업계획이었습니다. 
</p>
<p><b>○ 안혜영 위원 </b> 알겠습니다. 시간이 많이 지나서요. 다음 추가질의 때 다시 이어서 질의하겠습니다. 
</p>
<p><b>○ 위원장 배수문 </b> 안혜영 위원님 수고하셨습니다. 임두순 위원님 질의하여 주시기 바랍니다. 
</p>
<p><b>○ 임두순 위원 </b> 남양주 출신 임두순 위원입니다. 먼저 자료요청 좀 할게요. 2013년도에 수원시에서 용역의뢰한 지방재정보전금에 대한 용역이 있었죠. 이 상세한 내용 좀 부탁드리고요. 
</p>
<p style="padding-left:1.2em">  그다음에 업무보고 자료 6페이지에 보면 기금예치현황이 있어요. 기금예치현황이 있는데 여기에 보면 지난 7월 16일 날 업무보고 자료에는 예치일이랑 만기일이 좀 틀린 게 있어요. 신한은행이나 중소기업은행 같은 경우는 예치일이 좀 틀려요, 우리가 이 내용 파악한 거랑. 
</p>
<p style="padding-left:1.2em">  그다음에 기금이자수입이 한 5% 정도가 되는데 사무관리비가 거의 5%, 똑같아요. 똑같은데 기금이자운영에 대해서 이따가……, 이자율이 높은 데도 있고 낮은 데도 있잖아요? 이건 추가질문 시간에 질문을 할 테니까 이것 좀 준비해 주시고요. 
</p>
<p style="padding-left:1.2em">  먼저 원장님, 경기도의 인구가 현재 몇 명인지 아세요? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 1,260만 정도로 알고 있습니다. 
</p>
<p><b>○ 임두순 위원 </b> 1,260만이라고 그러셨는데 제가 왜 이 말씀을 드리냐면요. 방금 우리 존경하는 위원님들 중에서도 자료를 말씀하실 때 어느 분은 1,250만 명이라고 그러고 또 우리 연구원 중에서 업무보고 때도 보면 어떤 때는 1,270만 또 어떤 때는 1,247만, 제가 지금까지 본회의 때도 그렇고요. 오전에 얘기할 때는 1,247만 했다가 오후에 또 발의할 때 보면 1,260만. 아니 오전, 오후 몇 시간 차이도 안 나는데 인구가 갑자기 늘었다 줄었다 하는데 이러한 내용을 제가 질문하고 싶은데 왜 그러냐면 기준통계가 없다는 얘기예요. 왜냐하면 GRI에서 물론 인구가 연 통계 내는 게 있잖아요? 연 통계 내는 게 있는데 적어도 신뢰 있는 기관, 특히 집행부나 GRI 같은 연구기관에서 업무보고나 자료를 말씀하실 때 비근한 예지만 이런 인구에 대한 문제나 이런 것은 통일해서 어느 기준을 정해서 전반기면 전반기, 하반기면 하반기 이런 기준을 정해서 똑같은 얘기를 해 줬으면 좋겠어요. 아마 여기 계신 분들 지금 인구가 몇 명이냐고 물어보면 10명 중 5명 이상은 틀리게 답할 거예요, 서로. 어느 분은 1,247. 자의적 판단에 의해서 말씀하신 분들도 있고 또 어떤 자료를 보고 말씀하시는 분들이 있는데 여기 보면 경기일보에서도 기자님이 오셨는데 오늘 자 검색어에 보니까, 11월 19일 자 보도자료에 보니까 여기는 1,300만 명으로 돼 있어요. 이러한 것은 우리 경기도의 싱크탱크인 GRI에서 분기가 어렵다고 그러면 상반기ㆍ하반기를 기준으로 해서 이런 기준적인 통계가 되는 거, 이런 것은 제시를 해 주셔서 의원님들이 의정활동 할 때나 아니면 집행부에서 업무보고 할 때나 통일된 얘기를 할 수 있도록 이 점은 꼭 고려를 해주셨으면 고맙겠습니다. 그렇게 하실 수 있죠?
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 네. 
</p>
<p><b>○ 임두순 위원 </b> 조직개편에 대해서 질문 좀 할게요. 원장님, 9월 달에 청문회 하셨잖아요. 9월 달에 청문회 하셨는데 그때 혁신위에 계실 때 북부발전연구원에 대해서 아까 존경하는 김호겸 위원님도 잠깐 북부연구센터 말씀을 하셨는데 북부발전연구센터를 설립해야 된다는 필요성에 대해서 그때 말씀하지 않으셨나요? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 그러니까 연구원의 분원과 관련된 것을 말씀하시는 거죠?
</p>
<p><b>○ 임두순 위원 </b> 네. 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 구체적으로 연구원의 분원을 북부에 둔다는 내용은 없었고요. 다만 북부발전계획을 수립해서 북부발전을 매우 주요한 아젠다로 한다는 정도였습니다. 
</p>
<p><b>○ 임두순 위원 </b> 북부발전연구센터는 민선6기 남 지사님의 최대 공약 중의 하나가 북부지역의 균형발전 아닙니까? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 그렇습니다. 
</p>
<p><b>○ 임두순 위원 </b> 이런 차원에서 그때 임해규 원장님도 분명히 북부발전연구센터에 대한 어떤 생각이나 소신을 말씀하셨어요. 말씀을 하셨는데 지금 조직개편내용을 보면 지난 7월 16일인가 이때 업무보고 때 한 내용이랑 지금 조직개편은 됐잖아요. 이런 식으로 개편이 됐는데 여기에 보면 우리 민선6기 남 지사님의 최대 공약이 북부균형발전에 대한 이런, 그다음에 접경지역 발전 그다음에 상대적으로 열악한 북부 쪽의 경제활성화 이런 내용 때문에 북부 쪽에 많이 지원하시려고 노력을 하시잖아요. 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 네. 
</p>
<p><b>○ 임두순 위원 </b> 그런데 실제 우리 GRI에서는 집행부의 정책에 대해서 같이 따라가 줘야지 되는 거 아닌가 또 거기에 대한 맞는 도민을 위한 거니까요. 그런 연구센터가 조직개편에 들어가야지 되는데 지난번에 조직개편 전에 보면 통일동북아센터라고 있었고 아까 말씀하신 북부발전연구센터는 아마 내부적으로 자료를 가지고 계실 거예요. 제가 기억을 하고 있습니다, 분명히. 그런데 이 내용은 없고 이러한 내용이 개편조직의 어느 조직에 들어가 있는 거죠, 이런 내용이? 어떤 통일대비 연구나 아니면 북부지역 균형발전에 관한 연구나 이런 내용이 조직개편 중에 어디 민군정책팀에 들어가 있는 건가요 아니면 어디 들어가 있는 거죠? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 그렇지 않고 저희가 공존사회연구실에 그간의 센터로 소수의 인원으로 분화해서 있는 것을 일단은 대실체계로 묶었습니다. 그건 그렇게 묶어서 그 연구를 수행하게 되고요. 그런데 북부분원은 위원님 잘 아시다시피 아직까지 예산문제가 남아있고 그렇기 때문에 현재 그 시스템에서는 그림을 그릴 수가 없습니다. 그러니까 그것이 확정이, 그런데 이번에 예산의 15억 정도가 북부분원 예산으로 반영이 돼 있어서 그것이 저희 내부 이사회에서도 통과가 되고, 왜냐하면 조직개편을 하려면 이사회 회의를 거쳐야 됩니다. 그래서 그 예산이 일단 확정이 되고 이사회 회의를 통과하고 그렇게 되면 또 의회에서 그 예산을 승인하게 되고 이렇게 되면 저희들이 조직도를 바꾸게 되겠죠.
</p>
<p><b>○ 임두순 위원 </b> 그러면 이번에 배정을 하셨다는 얘기죠, 15억을.
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 15억을 저희들이 요청해서 지금 집행부 예산에는 들어가 있습니다. 그런데 그 예산을 포함해서 저희 GRI의 출연금이 지금 들어가 있습니다. 
</p>
<p><b>○ 임두순 위원 </b> 이 조직개편내용에 아까 말씀하신 분원내용이잖아요. 분원내용인데 조직개편내용이 아까 제가 말씀드린 북부지역의 현안을 연구하고 다룰 수 있는 그런 내용은 이 연구팀 중에 민군정책팀인가요, 아니면 공공 어떤 팀에서 이런 역할을 수행하는 거죠?
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 일단은 이렇습니다. 저희들이 북부의 특정한 시군 혹은 북부지역이 총괄적으로 관련돼 있는 연구사업은 모든 실에서 다 연구를 합니다, 그간에. 그런데 북부분원을 꼭 하자고 저희들이 기획을 한 것은 역시 그래도 북부지역에 연구원이 소재를 해야 그쪽의 문제의식도 더 강하고 또 북부지역의 어떤 다양한 정책을 할 수 있다는 것 때문에 북부분원을 하겠다는 기획을 가지고 있는 것이고요. 그간의 현재 연구원에서는 각 실에서 북부 관련된 연구를 총괄적으로 한다고 이해하셔야 될 것 같습니다. 
</p>
<p><b>○ 임두순 위원 </b> 어쨌든 제가 북부발전지원연구센터에 대해서 말씀드리느냐면요. 아까 모두에 말씀드린 것처럼 앞으로 북부지역이 물론 접경지역에 대한 안보와 관련된 그런 관련사항이 있지만 통일시대를 대비해서 앞으로 대규모 탈북난민이 생길 수도 있고 또 그것을 수용할 수 있는 북부지역의 경제규모나 북부지역 주민들의 경제활성화 또 지역민들의 행복한 삶의 지수를 위해서 북부지역발전지원연구센터는 반드시 필요하다고 저는 공감을 해요. 그래서 이런 내용 같은 경우 우리 GRI 차원에서 충분히 설명하고 공감대 형성을 위해서 세미나 아니면 공청회를 열든지 이런 내용을 통해서 북부지원연구센터는 반드시 성립이 되도록 노력을 해 주시기 바라고요.
</p>
<p style="padding-left:1.2em">  한 가지만 더 질문할게요. GRI 조직에 어떤 감사의 기능을 수행할 수 있는 그런 기능이 있나요? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 자체 내에는…….
</p>
<p><b>○ 임두순 위원 </b> 자체감사에서요, 자체감사.  
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 시스템은 별도로 없습니다. 다만 저희들 이사회에 감사 두 분이 계시는 것 말고는 상시적인 감사시스템은 가지고 있지 않습니다.  
</p>
<p><b>○ 임두순 위원 </b> 상시적인 감사부서를 두는 게 어떤 규정이나 조례에 어긋나는 부분이 있나요? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 아니, 꼭 그런 것은 아닐 것으로 생각이 듭니다만 저희 연구원이 아시다시피 주로 연구비를 지출하지 무슨 특별한 사업을 하는 곳이 아니기 때문에 이렇게 조그마한 조직에 감사시스템을 별도로 두는 것은 낭비적이지 않을까 이런 생각이 듭니다. 
</p>
<p><b>○ 임두순 위원 </b> 본 위원이 보기에는 어떤 공조직 특성상 연구방향이나 연구과제 선정할 때는 지나치게 관료적인 판단을 할 수 있다는 생각이 들어요. 왜냐하면 아까, 물론 연구비나 이런 게 차지하는 비용이 되게 많은데 그렇지만 어쨌든 전체적으로 GRI 운영차원에서, 합리적이고 투명한 운영차원에서 자체적인 감사기능을, 한번 투명함을 거를 수 있는 크지는 않지만 그런 기능을 가질 수 있는 담당자는 두시는 게 좋지 않은가 이런 바람을 말씀드리고 그 부분을 적극적으로 검토를 해주시기 바랍니다. 지금 시간이 많이 경과돼서 이따 추가질문 시간에 마저 질문하도록 하겠습니다. 이 점 원장님 검토 부탁드리겠습니다. 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 네. 
</p>
<p><b>○ 위원장 배수문 </b> 임두순 위원님 수고하셨습니다. 이재준 위원님 질의하여 주시기 바랍니다. 
</p>
<p><b>○ 이재준 위원 </b> 고양 출신 이재준 위원입니다. 지방자치단체 출자ㆍ출연기관의 운영에 관한 법률 제15조에 보면 조직과 정원 등의 운영해 가지고 정관 또는 내부규정에 “조직의 정원 등” 이것을 규정하게 돼 있는데 우리 정관에는 그게 없어요. 그래서 규정에는 아마 있을 거예요. 이게 무슨 문제냐 하면 정관에 있으면 사실상 위원회에 보고를 하지만 규정이 있으면 보고를 안 해도 되거든요. 그래서 김문수 지사 재임시절에 최근 5년간 산하기관에 이런 식으로 정관이 선 게 한 군데도 없어요. 그러니까 정관에 직원에 대한 규정이 채용만 있지 정원에 대한 규정이 없기 때문에 725명이 늘어났어요. 그래서 약 1년에 500억이라는 예산이 더 투입이 되고 있습니다. 사실상 이것을 정관에 안 하고 규칙에 정함으로 해서 마음대로 인사를 증원하거나 이런 걸 다 채용할 수 있는 이런 길을 열어놓은 거죠. 이것에 대해서 한 말씀 해주시죠. 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 저희가 그것은 말씀하신 것은 법적으로도 검토하고 반영해야 되면 반영하도록 하겠습니다. 그런데 잘 아시다시피 저희는…….
</p>
<p><b>○ 이재준 위원 </b> 아니, 법적으로는 하자가 없어요. 법적으로는 하자가 없는데 이런 것들이 뭐냐 하면 지금 남경필 지사께서 오셔서 통폐합을 하겠다 하는데 이런 안들이 경발연에서 연구결과가 나와서 이렇게 해야 됩니다라고 먼저 하셔야 되는 과제 아니냐는 의미에서 말씀을 드리는 거예요. 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 그러니까 지금 위원님 말씀은…….
</p>
<p><b>○ 이재준 위원 </b> 정관에 정원규정을 둬야 된다는 거죠. 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 그게 법적으로 꼭 둬야 되는 것은 아니지만 그렇게 두는 것이…….
</p>
<p><b>○ 이재준 위원 </b> 그렇죠. 통폐합을 하려고 그러면 기본적으로 이것부터가 돼야 그래도 위원회의 의결사항은 아니지만 보고라도 할 수 있어서 정원을 늘리는 데는 상당히 어렵지 않느냐, 이런 게 있는데 지금까지는 그냥 무방비로 늘려왔거든요. 그러니까 구조조정을 하려면 이런 것부터가 우선 만들어지고 구조조정을 어떻게 할 것인가를 연구하는 것보다도 이런 제도정비 미비부터 마련해야 되는 거 아닌가 이런 얘기를 드리는 거예요. 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 그런데 통상적으로는 정관에는 보통…….
</p>
<p><b>○ 이재준 위원 </b> 안 두죠.
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 제가 이해하고 있는 것은 그냥 직제규정에서 정하도록 정원은…….
</p>
<p><b>○ 이재준 위원 </b> 그렇죠. 그게 맞는데 너무 많이 늘어났는데 의회나 이런 견제기능이 아무런 역할도 할 수가 없는 부분이 있기 때문에, 맹점이 있기 때문에 이 법을 정관 또는 규칙에 두도록 되어 있으니까 정관을 적극적으로 해석하면 이거 하나만 해도 결국 무슨 문제가 있느냐 하면 우리가 구조조정이라는 아픔을 겪지 않아도 자동적으로 인원제한을 할 수 있고 정말 필요한 경우에만 허용할 수 있는 거 아니냐 이런 의미에서 말씀드리는 겁니다. 적극적으로 검토 좀 해 주시죠.
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 네, 검토하겠습니다. 
</p>
<p><b>○ 이재준 위원 </b> 그리고 저는 오늘 행감에서 몇 가지 자료에 대해서 질문을 드리려고 그러는데 사실 여기 연구원에서 하는 것은 학자적인 양심과 그리고 어떤 외압에도 불구하고 독자적인 연구를 수행할 수 있도록 다 케어가 되는 거죠? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 물론입니다.
</p>
<p><b>○ 이재준 위원 </b> 그러면 하나 여쭤볼게요. 우선 경기도 직접고용 비정규직 등의 고용개선방안 연구해서 2012년 7월 달에 나온 겁니다. 비정규직법에 보면 어떤 것도 규제를 안 둬요. 2년을 고용하면 무기계약직으로 기간을 정함이 없는 근로자로 넘어가게 되는데 여기 34페이지에 보면 상시지속업무 중에서 9개월 이상 근무한 사람이 203명입니다. 그런데 상시지속업무 중에서 9개월 이상 근무하고 도비가 100%인 사람이 93명으로 제한을 해요. 이 법에 도비가 100% 지원되는 사람만 무기계약직으로 전환하라는 법이 있습니까? 제가 알기로 법이 없거든요. 국비가 매칭이 되는 것은 다 빼버렸다는 거예요. 그래서 203명이 93명으로 줄어요. 이것에 대해 어떻게 생각하시는지요. 비정규직법이라는 한 명도 비정규직으로 채용하지 말라는 거지 그래서 더 많이 양보를 해 주고 허용을 해줘서 2년 동안 한 사람들은 장기 계속 필요인원으로 보고 해주라는 거거든요. 그런데 거기에서 국비가 내시 돼서, 매칭 돼서 이렇게 되기 때문에 뺀다는 논리를 여기 경발연에서 만들었어요. 이게 시대에 부응하는 연구인가요? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 아주 전문성을 요하는 연구의 특정 결과나 내용에 대해서 사실 제가 즉각 답하기는 좀 어려운 것 같고요. 그런데 그와 같은 비정규직법을 만들고 이렇게 한 큰 흐름들이 있기 때문에 그 흐름에 대해서는 위원님의 지적에 동의합니다만…….
</p>
<p><b>○ 이재준 위원 </b> 비정규직법을 만들었는데 하도 안 지키니까 국가인권위에서 강제로 정부에 권고를 한 거예요. 그래서 그나마 지키게 된 건데 거기에서도 국비 매칭되거나 내지는 도비하고 다른 어떤 자금하고 매칭이 되면 고용을 안 하게끔 되는 이런 식의 편법을 여기서 만들어서 논리적으로 근거를 제시했다는 거예요. 그래서 경기도가 몇 명을 고용하느냐면 30명을 고용합니다. 93명도 아니고 거기에서 또 기관장들이 면접을 통해서 면접이라는 자의성은 어느 누구한테도 부여되지 않았어요. 2년을 했으면 하게 돼 있는데 그렇게 해서 30명밖에 못하도록 이걸 만들어놓은 거예요. 203명이 30명으로 줄은 거죠. 거기에서 물론 예외규정에 적용되는 얼마가 빠지죠. 이렇게 비정규직법을 경기도가 악용하도록 여기서 근거를 제시한 것에 대해서 어떻게 생각하시는지요. 말씀 한번 해주시죠. 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 제가 연구보고서를 봐야지 답할 수 있을 것 같은데요. 
</p>
<p><b>○ 이재준 위원 </b> 알겠습니다. 그다음에 지방재정에 관한 거예요. 이게 2011년 7월 20일 날 지방의회의 희생을 강요하는 재정현실, 그다음에 2011년 9월 21일 날 지방예산의 위기와 정책방향 했는데 이것은 거의 다가 국가, 중앙정부가 강제적으로 한 부분에 대해서 얘기를 해요. 그런데 2개월밖에 안 지났는데 여기에서는 상당히 이상하게 써요. 뭐냐 하면 1장은 맞고 8페이지에 보면 “무상급식과 같은 교육감의 공약이행, 예산편성권 충돌 이렇게 해서 지방의회의 정치적 견해가 상이함에 따라 예산편성에 혼란을 가중하고 지방의회가 각종 사업 확대를 통한 이권추구 및 복지예산 증가를 통한 대중영합주의 경향” 이런 식으로 해서 얘기를 해요. 그런데 여기 뭐가 문제냐 하면 요 바로 얼마 전에 김문수 지사가 언론에다가 그 얘기를 했어요. 공무원 다 불러놓고 “의원들이 예산에 대해서 잘 모르니까 공무원들이 책임지고 해라.” 그래서 제가 5분발언을 했습니다. “예산에 대해서 모르는 것은 김문수 지사 당신이지 우리가 왜 모르느냐.” 김문수 지사가 좀 전에 얘기했지만 재임 5년 동안에 725명이 증가했어요. 그렇게 해서 예산을 500억이나 축내고 있죠. 
</p>
<p style="padding-left:1.2em">  바로 여기입니다, 여기. 우리 도청 광교로 옮긴다고 그러는데 여기 지방행정연수원 사잖아요. 어떻게 지방행정연수원을 사죠? 광교로 도청사를 옮기는데, 이거 매각해야 되는데. 파주영어마을 마찬가지고 어떻게 이렇게 하죠? 경인교대를 위해서 1,700억이라는 예산을 들여서 했는데 국비로 1,700억이라는 예산을 받아야 될 것을 우리가 도청 옆에 조그만 땅 하나, 남한산성에 있는 자투리땅 하나 그다음에 농생대부지 이렇게 인수하면서 1,700억을 다 흐지부지 써요. 어떻게 이렇게 얘기하죠? 의원들이 잘못하는 경향도 있어요, 있을 수도 있고. 그렇지만 보고서는 객관적으로 나와야 된다는 거예요. 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 그런데 그 보고서가 어떤 보고서인지 좀…….
</p>
<p><b>○ 이재준 위원 </b> 이거 2011년 9월 21일. 그다음에 4대강 이후 4대강에서 2012년 7월 25일 거 보고서가 또 하나 있습니다. 그런데 여기는 상당히 좋아졌다고 나와요, 수질이. 3페이지에 보면 수질이 좋아졌다고 나오는데 그리고 가뭄 해소에 영향을 줬다고 얘기를 합니다. 그런데 올해 신문이나 작년 신문에 보면 4대강 16개 보 중에서 단 한 곳도 물을 농업용수로 제공하지 못했어요. 그리고 더 웃기는 것은 이게 며칠이냐 하면 7월 25일인데 7월 25일 기사가 뭐가 나오느냐면 팔당호까지 시민들 불안해서 이때 당시 저기가 나와요. 녹조현상이 발생합니다, 7월 25일 날. 그리고 여기에 자료로 인용한 것이 뭐냐 하면 2012년 7월 23일 날 환경부에서 보도자료를 낸 거예요. 이 통계숫자가 이틀 만에 이걸 갖다가 이런 작업을 했어요. 그래서 결과를 내놨어요, 환경부 자료를 인용해서. 이게 맞는 거냐는 거죠. 그리고 이때 당시는 이미 하수종말처리장 고도화사업을 해서 수천억을 들여서 총인을 잡았어요. 총인은 수계에 영향을 미치기 때문에 좋아졌죠. 여기서 또 하나 뭐가 있느냐 하면 COD는 더 악화됐어요. 그런데 요새는 BOD보다 COD가 더 중요하다는 거예요. 더 오염의 측정기준을 COD를 많이 씁니다. 이런 보고서가 왜 이 필요성도 없는 녹조가 발생된 그날 이게 발간이 되냐 이거예요, 이틀 만에. 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 그러니까 무슨 정치적으로 의도가 있다 이런 말씀…….
</p>
<p><b>○ 이재준 위원 </b> 저는 그래서 학자적 양심을 걸고 연구하시는 분들한테 그런 연구할 분위기를 조성해 주셔야 되는 것이 원장님 책임이고 그렇지 못하고 이런 자료들이, 물론 그래요. 이것이 양심껏 했을 수도 있어요. 그렇지만 주변상황과 인과관계를 따져봤을 때는 다분히 의도된 거라는 거예요. 이런 의도된 것을 정책자료로 만들어서 도지사가 의회에서 엉뚱한 얘기하고 이럴 때 그런 밑바탕, 논리적 근거로 활용이 된다면 이것은 정말 문제가 많다는 거죠. 그래서 이런 문제에 대해서 점검하시고 원장님이 새로 오셨으니만큼 분명하게 외부에서 오는 압력들을 막아주시고 정당한 연구활동을 할 수 있도록 조직을 개편해 주시기 바랍니다.
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 그렇게 하겠습니다. 그런데 죄송한 것은 위원님이 어떤 연구물의 내용에 대해서 분석을 하셔서 질의하시는 것에 대해서 제가 그것을 다 파악하고 있지 못하니까 사실 이런 것은 토론이 필요한 내용인 것 같습니다. 왜냐하면 그것을 쓴 우리 박사님들이 지금 그 문제에 대해서 전문가적 견지에서 답변을 할 수 있는 기회가 지금 없는 상황이기 때문에 적절한 토론이 이루어지지 못하니까 일반론적으로 중립성을 유지하고 양심에 따른 전문성을 견지하도록 해야 된다는 거에 전적으로 공감을 하고요. 그리고 제가 알기로는 우리 여기의 정규직 박사님들은 제가 보기에는 그야말로 본인의 양심과 전문성에 입각해서 연구를 하고 있다고 저는 보고 있습니다. 
</p>
<p><b>○ 이재준 위원 </b> 저도 그렇게 믿고 있습니다. 그런데 결과물들이 간혹 가다가 이렇게 나와 버리니까, 그것이 또 상당히 미묘한 시점에 나와요. 그러니까 이걸 갖다가 인과관계를 저희가 의심하지 않을 수 없다는 겁니다. 그래서 원장님이 새로 오셨으니만큼 그런 분위기를 바로 잡아달라는 그런 부탁 말씀드리는 거예요. 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 알겠습니다. 
</p>
<p><b>○ 이재준 위원 </b> 이상 마치겠습니다. 
</p>
<p><b>○ 위원장 배수문 </b> 이재준 위원님 수고하셨습니다. 장동일 위원님 질의하여 주시기 바랍니다. 
</p>
<p><b>○ 장동일 위원 </b> 장동일 위원입니다. 자치의정부에서 의정연구센터 기능을 하고 있죠? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 네. 
</p>
<p><b>○ 장동일 위원 </b> 한 가지 확인 좀 하겠습니다. 자치의정 직원들은 아무래도 우리 의회 의원들의 어떤 현황이랄지 이런 자료도 만들고 수집해야 되잖아요? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 그렇습니다. 
</p>
<p><b>○ 장동일 위원 </b> 다른 부서 직원들과의 갈등ㆍ반목 이런 게 있다 이런 얘기가 들리는데 원장님 혹시 그런 보고받으신 적 있습니까? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 갈등과 반목이라기보다는 제가 보기에는 센터가 그간에 하는 일이 매우 독립적이고 특정한 일이기 때문에 연구원의 다른 연구원들이랑 섞이지 않는 연구 환경 속에서 있었던 것으로 알고 있습니다. 
</p>
<p><b>○ 장동일 위원 </b> 아무래도 의원들의 의정활동을 도우려고 하다 보면 집행부의 여러 가지 이런 걸 알아야 되고 그런 걸 수집하는 과정에서 이런 반목이 있다는 얘기를 제가 들어서 확인 차. 앞으로 원장님께서 그런 부분들은, 이건 절대 있어서는 안 되는 일이잖아요? 확인 좀 해주시기 부탁드리겠습니다. 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 네, 알겠습니다. 
</p>
<p><b>○ 장동일 위원 </b> 그다음에 2015년도 연구사업 목표를 8개 중점사업을 제시를 하셨어요? 맨 위에 보니까 따복마을 관련해서 올라와 있는데 얼마 전에 원장님 거기 가보시고 하셨죠, 거기? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 네. 
</p>
<p><b>○ 장동일 위원 </b> 그런데 저도 가봤는데 우선 따복공동체 이름, 네이밍부터 저는 썩 그렇게 마음에 와 닿지 않는데, 어떤 행정이나 정책에서 네이밍이 참 중요한데 원장님 마음에 드세요? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 뭐 크게 나쁘지 않다고 생각합니다. ‘따뜻하고 복된’이라는 의미를 줄인 건데요. 
</p>
<p><b>○ 장동일 위원 </b> 아니, 그냥 ‘따뜻한 마을 만들기’, ‘행복한 마을 만들기’ 이러면 포괄적으로 다 포함될 텐데 민원인들이 따복이 뭐냐고 저한테 물어보기도 해요. 그거 해명하려면 좀 신경 쓰이던데 이런 부분들은 한번 고민해볼 필요가 있지 않습니까? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 네, 그런데 지금 진행은 꽤 됐는데요. 
</p>
<p><b>○ 장동일 위원 </b> 좋습니다. 하여튼 그런 생각이 들어서요. 그다음에 따복마을이 진행하는 과정에서, 후쿠야마의 “한국 저신뢰사회” 그 얘기 들으셨잖아요? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 네. 
</p>
<p><b>○ 장동일 위원 </b> 한국 사회가 사회적 자산인 신뢰가 전혀 없다 그래서 사회적으로 논란이 됐었는데 신뢰가 없고 개인주의, 지금 학생들이나 20∼30대 사람들한테 가장 가까운 공동체가 뭐냐고 하면 네이버라고 합니다, 네이버. 이미 스마트폰이나 이런 것들이 하나의 개인의 문화로 자리 잡았는데 과연 우리가 추진하고자 하는 따복마을 이런 것들이 생각만큼, 필요는 인정하지만 될까 하는 우려가 늘 있거든요. 활동가 몇 분들이 그냥 그런 거에, 그분들이 나서서 하는 것에 그치지 않을까 하는 우려가 너무나 많습니다. 저도 관심이 많아서 가보고 공동체마을 만들기 하는 몇몇, 성미산마을에도 얼마 전에 제가 좀 갔다 와 봤습니다. 갔다 와 봤는데 자꾸 이런 의구심이 드는 겁니다. 원장님 말씀 좀 해주세요. 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 지금 공동체를 복원하려고 하는 사업은 크게 보아서 전통적으로 했던 마을 만들기 영역이 있고 또 하나는 사회적기업과 협동조합을 비롯한 사회적경제 영역으로 되어 있습니다. 그런데 많은 지자체에서 아주 열심히 해서 성과를 부분적으로 이루어낸 곳도 많이 있습니다만 우리 경기도도 그렇고요. 또 그런 곳에서 참여하는 주민 숫자나 이것은 활동가들이 열심히 활동을 하는 것이 그 활동을 촉진하긴 합니다만 참여하는 주민 수는 굉장히 많습니다. 그렇기 때문에 위원님께서 그날 보신 것은 활동가들이 어떻게 하면 잘할 건가 하는 거를 중심으로 논의하는 모습이어서 그렇지 사실 우리 사회가 저는 그런 많은 주민들이 참여해서, 주민참여가 제1번이거든요, 공동체 사업의 핵심은. 그리고 관 주도로 하게 된 경우는 실패한다고 하는 그런 문제의식 때문에 관 주도로 하지 않고 민관 거버넌스를 통해서 그 사업 추진을 지원하려고 하고 그것도 지원이지 민관이 자기네들이 하는 게 아니거든요. 그래서 그런 관점에서 본다고 하면 우리가 더디게 가는 일이지만, 이것이 성과가 몇 년 단위 또는 몇십 년 단위로 성과를 내는 것이지만 공동체 복원을 하기 위한 민관의 거버넌스를 통한 지속적인 노력은 매우 시급하고 한 치도 늦출 수 없는 과제라고 생각합니다. 
</p>
<p><b>○ 장동일 위원 </b> 아까 말씀드렸듯이 필요를 인정을 합니다. 그런데 성미산마을 대표적으로 좀 잘 진행되고 있다고 하는 그런 데를 가보면 또 다른 하나의 갈등을 만들어내는 거예요, 이분들과 또 이분들과의. 그래서 그런 부분들이 좀 많이 논의가 되고 깊이 있게 연구가 돼야겠다는 생각을 했습니다. 
</p>
<p style="padding-left:1.2em">  그리고 여기 중점사업으로 나와 있는 것 중에 몇 개 사안별로 여쭤보고자 합니다. 도민안전강화방안에 대해서는 아까 얘기가 나왔습니다만 원장님, 혹시 가족이 한 2일이나 3일 정도 어디 다녀오겠다고 하면 마음이 불안하지 않습니까? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 저희는 다 커서요. 그렇지는 않습니다. 
</p>
<p><b>○ 장동일 위원 </b> 가족이 부산이나 어디 갔다 오겠다고 2박 3일 친구들하고 놀러갔다 오겠다고 하면 안전히 돌아올까 하는 그런 불안감 없습니까? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 네, 저는 그런 불안감은 없습니다. 
</p>
<p><b>○ 장동일 위원 </b> 다행입니다. 저는 좀 불안하더라고요. 교회에서 어디 갔다 오겠다고 하면 수시로 전화를 하게 되고 버스 타고 어디 가겠다고 하면 잘 무사히 돌아올 수 있을까, 이게 참 큰일이죠. 이런 부분들 때문에 안전에 대한 이런 부분들은 몇 번을 강조해도 지나침이 없다. 얼마 전에 어떤 연구자료에 보니까 ‘최대의 복지는 안전이다.’ 이런 연구자료를 제가 본 적이 있거든요. 그래서 그런 부분에 대해서 입각해서 좀 해주시고 그리고 일자리 창출전략이 이렇게 보면 너무 디테일이 없어 보입니다, 여기에. 그래서 이런 부분들은 어떻게 해야 되나요? 지금 너무 지역경제가 어려워서, 특히 서비스나 자영업이 어려운데 여기 계획에 보면 디테일이 없어 보여요. 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 그런데 사실 일자리와 관련된 저희들의 연구물은 굉장히 많이 있습니다. 일자리를 새로 창출하는 측면에서 그리고 그간에 열악한 일자리, 사실상 반실업 상태나 다름없는 많은 자영업자들의 일자리를 어떻게 질을 높일 건가 하는 문제, 그리고 첨단산업 영역에서 새로운 일자리들을 어떻게 만들어낼 건가 하는 문제별로 각 부문별로 많은 연구물이 있습니다만 위원님이 특정한 부분 또 문제제기하시고 아이디어를 주시면 저희들이 또 연구를 하도록 그렇게 하겠습니다. 
</p>
<p><b>○ 장동일 위원 </b> 네, 2013년 작년도 맥킨지보고서 혹시 보신 적 있으세요? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 잘 기억이 나지 않습니다, 들어는 본 것 같은데. 
</p>
<p><b>○ 장동일 위원 </b> 맥킨지보고서라고 97년 IMF 이후에 그리고 작년에 두 번, 미국의 보고기관인데 거기서 모든 한국의 전반적인 것을 보고서를 낸 게 있습니다. 거기에 보면 제가 좀 자료를 가져왔는데요. 여기에 우리들의 현실이 다 담겨져 있더라고요. 깜짝 놀랐습니다. 그래서 앞으로 기회가, 시간이 되시면 이거 한번 꼭 좀 검토해 주십시오. 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 네. 
</p>
<p><b>○ 장동일 위원 </b> 많이 참고가 되실 것으로 제가 권해드립니다. 그다음에 제일 중요한 문제는 지금 지역에서 보면 지역경제의 어려움입니다. 그게 어렵다 보니까 일자리도, 취업도 안 되고 장사도 안 되다 보니까 아까 하려고 했던 모든 것들이 다 안 되는 거예요. 마을 만들기 사업도 먹고 살기 힘든데 그런 거냐. 그러니까 거기서 모든 게 다 출발이 된다고 보는 거죠. 그래서 이게 참 너무나 걱정스러운데 여기 주거복지정책, 일자리정책 다 나와 있습니다만 제가 어제, 그제, 오늘까지도 신문의 경제면 이런 것들을 점검을 해보니까 우리 경제가 5년 연속 저성장에 진입했다. 70년 이후로 처음이다. 97년 IMF 때는 그래도 미국 경제가 괜찮아서 그나마 우리가 탈출구가 있었고 2008년 국제금융위기가 왔을 때는 중국이 SOC에 투자해서 그나마 우리가 탈출구가 있었다. 그런데 앞으로는 이런 게 없다. 그래서 막막하다는 거죠. 그래서 국가 정책하고 경기도 정책이 많이 중복되는 부분이 있기 때문에 이 부분에 대해서 원장님의 견해를 좀 듣고 이제 질의는 마치도록 하겠습니다. 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 제가 경제전문가는 아닙니다만 현재 저성장기조 이런 것들은 사실 한국경제가 더 이상 추격경제의 패러다임이나 시스템으로는 안 된다는 것에 공감을 다 하고 있는 것 같습니다. 따라서 우리가 만 서비스산업의 고부가가치 서비스산업 쪽으로 신경을 많이 써야 되고 사실 우리 경제가 대기업 위주의 하청 계열화되어 있는 그런 측면이 많기 때문에 경제민주화 실현을 통해서 많은 경제활동을 하는 인구들이 함께 경제활동을 할 수 있도록 배려하는 시스템을 바꾸는 문제, 이런 것들이 굉장히 중요하다고 생각합니다. 따라서 경제민주화 화두라고 하는 것이 갖는 의미는 새로운 경제패러다임을 대한민국도 만들어내야 된다는 것과 특히 사회적경제, 요새 나오는 많은 이야기도 자본제적 경제 체제만으로는 더 이상 한국경제의 어떤 안정화된 시스템을 만들 수 없다는 문제의식 때문에 또 하나의 새로운 경제영역으로 사회적경제 이야기도 많이 나오는 것으로 알고 있습니다. 그래서 우리가 이제 고도성장의 시기는 이미 지나갔다고 보고 한국경제 발전단계가 새로운 시대 시스템에 맞는 그런  경제발전 단계로 우리가 잘 전환하기 위한 노력을 기울여야 되지 않나 그렇게 생각이 듭니다. 
</p>
<p><b>○ 장동일 위원 </b> 시간 관계상 나머지는 오후에 또 질의하도록 하겠습니다. 수고하셨습니다. 
</p>
<p><b>○ 위원장 배수문 </b> 장동일 위원님 수고하셨습니다. 임병택 위원님 질의하여 주시기 바랍니다. 
</p>
<p><b>○ 임병택 위원 </b> 시흥 출신 임병택 위원입니다. 행정사무감사는 지난 1년 동안 경기개발연구원이 잘한 일은 잘한 대로 못한 일은 못한 대로 평가하고 함께 고민하고 대안을 세우는 자리입니다. 
</p>
<p style="padding-left:1.2em">  일단 저는 잘한 점부터 좀 말씀을 드리겠습니다. 이것은 제 개인적, 주관적 판단이 가미된 잘한 일이기 때문에요. 그 점은 좀 이해를 해주시고요. 우리 경기개발연구원에서 4대강 사업, 특히 우리 한강구간과 관련돼서 성과분석과 개선방안이라는 보고서를 작년 말, 올해 초에 발간을 했습니다. 경기도의회의의 요구에 의해서 발간을 했는데 그 자료는 우리 대한민국의 어느 국책기관, 공공정책 연구기관에서도 연구하지 못했던 비판적 결론을 도출한 아주 용기 있는 보고서였습니다. BOD와 COD 기본적인 내용은 우리가 아시지 않겠습니까? 정부에서는 4대강 사업을 통해서 한강사업구간에 BOD가 평균치를 유지하고 있다, 수질 나쁘지 않았다고 했지만 경기개발연구원의 연구는 그것이 단순히 BOD가 평균치를 유지하는 이유는 갈수기 때 충주댐의 방류량을 70%를 늘렸다는 겁니다. 충주댐의 맑은 물을 섞어서 BOD를 유지했다. 그러나 COD는 더 악화됐다. 그리고 녹조의 원인인, 클로로포름이라고 하죠. 조류농도라고 하죠. 조류농도도 더 악화됐다고 하는 결과를 이 보고서에 담고 있고요. 그리고 또한 4대강 사업을 통해서 막대한 생태계의 파괴 그리고 또 관리ㆍ유지비의 증가 등을 아주 비판적 시각으로 만들어낸 자료입니다. 저는 이게 우리 대한민국 국책기관도 못하고 공공정책기관 어느 곳에서도 못했지만 경기개발연구원의 학자적 양심과 독립성으로 이러한 결과물을 만들어낸 데 있어서 특히 지금이 그 당이 계속 정권을 연장하고 있는 상황임에도 이러한 연구성과물을 낸 것에 대해서는 대단히 감사드리고 이러한 연구 분위기, 독립적인 학자의 개인과 양심, 공정성과 객관성을 담보할 수 있는 연구 분위기가 계속되는 경기개발연구원이기를 바랍니다. 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 네, 그렇게 하겠습니다. 
</p>
<p><b>○ 임병택 위원 </b> 저는 이 부분은 경기개발연구원이 잘했다고 하는 부분입니다. 그런데 경기개발연구원이 제가 볼 때 가장 못한 부분이 있는 것도 같아요. 일단 우리 경기개발연구원의 모든 학자들은 본인의 연구윤리규칙이라는 기본적인 지켜야 될 윤리가 있지 않겠습니까, 연구윤리라는. 우리 경기개발연구원의 연구원들이 다 숙지하고 있을 텐데요. 연구부정행위를 하면 안 되잖아요. 위조, 변조, 표절해서는 안 되겠죠? 그러나 제가 봤을 때는 이 부정행위가 있었다고 합리적인 추론, 어떻게 보면 저는 명확한 합리적인 추론을 할 수 있는 그런 자료가 있어서 말씀드리고 싶습니다. 뭐냐면 우리가 자료를 보면 2014년 위탁용역과 관련된 자료 7페이지를 보시면 맨 위에 서울대 산학협력단에 1,800만 원 들여서 수의계약을 통해서 일본 대내외정책 동향과 시사점이라는 외부용역을 발주를 합니다. 1,800만 원짜리입니다. 그래서 최근 일본 대내외정책 동향과 시사점이라는 이러한 보고서를 우리 경기개발연구원에 납품을 해요. 서울대 산학협력단은 잘했죠. 1,800만 원어치. 비록 두께는 얇지만 이런 성과물을 납품을 했습니다. 그런데 우리 경기개발연구원의 김 모 간부연구원께서 서울대 산학협력단이 제출한 1,800만 원짜리 이 자료를 본인의 연구성과로 보고를 하고 거기에 대한 평가까지 받았어요. 어떻게 생각하십니까? 
