<p style="padding-left:1.2em">  그리고 다음 부분은 거의 똑같은 주제예요. 1,800만 원짜리 서울대 준 것과 바로 직전 2013년 10월 23일 경기개발연구원에서는 거의 비슷한 내용인데 아베노믹스, 아베 리더십이라는 아주 알찬 자료를 이렇게 만들어냅니다. 제가 봤을 때는 이 내용을 이 책에다가 그냥 풀어쓴 거예요. 이게 왜 1,800만 원인지도 대단히 의문스럽고요. 또 같은 내용을 그대로 풀어쓴 걸 본인의 연구성과인 양 본인의 연구자료로 이렇게 발표하는 경기개발연구원의 연구윤리규칙을 제대로 반한 이런 행태를 저는 지금 지적을 아니 할 수가 없고요. 이 부분에 대해서는 합당한 조처를 원장님께서 하셔야 된다고 봅니다. 어떻게 생각하세요? 
