<p><b>○ 경기개발연구원장 임해규 </b> 그런데 제가 이해하기로는 저는 처음에 출연금이 100억으로 시작됐습니다. 그런데 그게 축적이 되다가 지금 계속 삭감되고 있는데 사실 그건 연구원의 기본자산이기 때문에 그것이 그렇게 삭감되는 것은 연구원에 있는 많은 구성원들이 굉장한 위기감을 가지고 있습니다. 그건 자연스러운 일이라고 생각이 들고 물론 이 연구원에는 기본적으로 출연금에 기초하기 때문에 이 연구원의 역할과 지위가 필요성이 인정되는 한 출연금을 통해서 유지를 하겠지만 기본적인 자산을 계속 잠식하는 것은 바람직하지 않다고 저는 봅니다. 그런데 사실 지금 의사결정하는 측에서는 제가 보기에는 경기도가 많은 부채를 지고 있고 그 부채는 상대적으로 높은 이자를 물어야 되기 때문에 기금을 그냥 예금이자도 얼마 되지 않는데 이 기금을 쌓아놓는 것은 전체 경기도 경영에 올바르지 않다고 하는 문제의식을 가지고 있는 것으로 알고 있고 그것은 제가 알기로는 상임위원회에서도 그런 인식을 가지고 있는 것으로 제가 이해하고 있습니다. 그런데 저는 그 인식을 바꾸어 될 필요가 있다고 보고 그것은 결국은 재정운용에 있어서 연구원이 가지고 있는 특성과 안정성이라고 하는 것을 주요한 가치로 보고 그것을 유지하도록 계속 설득을 해야 되지 않나 생각합니다. 
