<p style="padding-left:1.2em">  질의에 앞서 위원장으로 몇 가지 말씀을 드리고 오후 행감을 시작하도록 하겠습니다. 몇몇 중요한 일들 중에 가장 중요한 내용으로 말씀드리면 행감을 한다고 하는 것은 1년간의 기관에 대한 과실을 점검하고 앞으로의 방향을 모색하는 시간이라고 생각합니다. 자료준비, 기타 행감준비 모두 중요하지만 먼저는 행감을 대하는 자세라고 생각을 합니다. 관에서 그러한 자세들이 하나로 묶어지지 않았을 때 나타나는 해이된 모습 같은 것들이 조금 보여서 안타깝다라는 얘기를 공식적으로 드리겠습니다. 
</p>
<p style="padding-left:1.2em">  특히 임 원장님 새로 오셔서 경기도에서의 행감 방식을 조금 모른다고 할 수 있습니다. 그렇다면 준비하는 팀에서는 더 철저히 준비했어야 된다 그렇게 생각합니다. 경기도의 틀이 있기 때문에 기본적으로 갖추고 시작돼야 된다 그렇게 생각합니다. 행감을 받는 자세 상당히 중요합니다. 피감기관과 감사를 하는 측의 기본적인 예의도 있어야 된다고 생각합니다. 그런 모습들이 조금 더 존중돼야 더 나은 방향의 모색 그리고 더 상호 간에 격에 어울리는 대우들이 있다고 생각을 합니다. 조금 더 신경 써서 행감에 임해 주셨으면 하는 바람입니다. 오늘 행감 이후에 20일 날 종합행감이 같이 있습니다. 그래서 그때까지 같이 행감에 임해 주시는 자세 그리고 자료를 준비하고 제출하는 것까지 해서 더 행감에 성심성의를 다해 주시기를 부탁을 드립니다. 
</p>
<p style="padding-left:1.2em">  이어서 추가질의 시작하도록 하겠습니다. 오전 질의 순서의 역순으로 임병택 위원부터 질의하도록 그렇게 하겠습니다. 
</p>
<p><b>○ 임병택 위원 </b> 시흥 출신 임병택 위원입니다. 일단 자료준비하시는 분께 업무보고 자료 64페이지 행정감사 조치사항에 보면 답변처리 결과에 시군 용역수주 강화를 위해서 수탁용역사업 활성화방안을 수립하였다고 하셨네요. 이 내용을 전해 주시면 고맙겠습니다. 원장님께 오전에 저희 위원님들의 질문도 있었습니다. 시군 수탁용역 실적이 갈수록 떨어진다. 2014년 현재까지 13년에는 17건이었는데 20건, 17건 그래서 올해 현재까지는 9건이네요. 그러한 추세가 입찰로 전환됐기 때문에 불가피한 면이 있지 않냐라고 말씀을 하신 것 같습니다.
