<p><b>○ 임병택 위원 </b> 그러나 이 문제는 수년간 경기개발연구원의 독려차원에서 위원님들이 일관적으로 지적을 해 왔던 부분인데요. 그리고 13년에 수탁용역사업 활성화방안도 만드셔서 활동을 했는데 현재까지는 그 결과가 제대로 나오지 않은 것 같습니다. 이 수탁용역사업 활성화방안을 저도 참고하겠지만 원장님께서도 참고하셔서 31개 시군과 원활한 교류 그리고 또 그를 통한 신뢰관계 회복, 어쨌든 경기개발연구원은 우리 공유자산 아니겠습니까? 그런 관계를 복원해 주시기를 당부드리겠습니다. 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 아까 여러 위원님들 질의에 답변이 있었기 때문에 길게 말씀드리지 않겠습니다. 그런데 사실 공모방식으로 하게 되면 우리 경기개발연구원이 가지고 있는 어떤 전문성이랄지 아니면 그간의 경험의 축적이나 노하우의 축적 같은 것이 사실 잘 반영이 되지 않습니다. 그래서 공모방식이 갖는 한계 때문에 사실 올해 8월부터 제도가 바뀌어서 현격하게 줄게 되는 요인 중의 하나였습니다.
</p>
<p><b>○ 임병택 위원 </b> 올해 8월이요? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 네.
</p>
<p><b>○ 임병택 위원 </b> 아, 그렇습니까? 알겠습니다. 8월에 바뀐 내용까지도 함께 주시면 상황을 이해하는 데 도움이 될 듯합니다. 조직개편 하셨지 않습니까? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 네. 
</p>
<p><b>○ 임병택 위원 </b> 저희 기획재정위는 북부청사도 저희 소관업무를 하고 있습니다. 화요일에 의정부에 있는 북부청사를 다녀왔는데요. 북부청사의 고민은, 남경필 도지사의 주요 북부에 관련된 애정을 우리가 모르는 바가 아닙니다. 그리고 또 북부발전 10개년 계획도 수립해서 진행을 하고자 하는 업무보고를 받았습니다. 그 업무보고 자료에 내년 3월에 경기개발연구원 북부센터를 개원하겠다라는 계획도 있더라고요. 북부청사 실장님의 답변이었습니다. 그래서 경기연과 협의되고 있냐라고 물어봤더니 지속적으로 만나서 협의하고 있다라고 이야기를 하더라고요. 그래서 북부청사가 알고 있는 내년 3월 경기개발연구원 북부지원센터 개소는 정확히 어떻게 진행될 것 같으십니까, 원장님? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 저희들이 원래 통일동북아센터가 주로 통일문제를 중심으로 하지만 역시 북부분원을 하게 되면 통일 관련해서 지자체가 해야 될 역할은 그쪽으로 연구가 이관이 될 거라고 생각하고 있고 그 외에 저희들 애초의 계획은 추가로 일곱 분의 박사를 더 뽑아서 10명 정도의 박사와 석사연구원들을 또 10명 정도하고 행정원 1명으로 해서 총 21명 정도의 연구인력으로 북부분원을 해야지만 북부 쪽에 취약한 여러 가지 특화된 정책연구를 할 수 있고 또 하나의 연구원으로서의 제 기능을 할 수 있다고 판단을 해서 저희들이 계획을 올렸습니다. 
</p>
<p style="padding-left:1.2em">  그런데 도와 협의하는 과정에서는 그런 인원을 추가하는 정도로 예산을 잡기는 어렵다고 서로 협의가 돼서 규모는 약간 줄어들 것으로 생각하고 있습니다. 
</p>
<p><b>○ 임병택 위원 </b> 이제 지사님의 의지만 있다라면 운영비용 우리가 빅파이프로젝트사업단이라든지 따복사업단이라든지 그 반의 반 예산이면 충분히 저는 가능한, 의지만 있으면 가능한 거라고 봅니다. 그러한 정책이 실질적으로 예산으로 구체화돼서 경기북부지역에 뭐가 만들어져야지 경기북부사람들도, 특히 동북부겠죠. 접경지역 포함해서 낙후된 그런 분도 “아, 남경필 지사님의 의지가 진정성이 있구나.” 이렇게 저는 받아들일 거라고 보는데 늘 말로만 그치는 게 아닌가 싶어서 저는 아쉬움을 가지는 거고요. 아울러서 저는 그렇게 생각합니다. 원장님께서 의지만 있으시다면 예산이 부족하다 그러면 수원의 북부발전과 관련된 팀을 독립된 부서로 만들어서 우리의 북부에 대한 애정과 사랑은 변치 않는다라는 것을 휴먼교통, 생태환경, 상생경제처럼 경기북부와 관련된 독립된 부서를 두는 것도 의지의 표명 아닐까 저는 그런 아쉬움을 가지고 있습니다. 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 이번 직제에 포함하지 못한 것은 사실 이번에는 이사회를 열어서 전반적인 조직도 개편을 아직까지 하지 못했습니다. 그리고 예산반영이나 이런 것들이 되지 않아서 확정된 것만 그 조직도에는 실었기 때문에 그렇게 그림이 그려진 것으로 이해해 주시면 좋을 것 같습니다. 그리고 저희들이 가지고 기획은 올 11월 말에 저희들이 이사회를 열게 되면 그리고 예산반영이 지금 되어 있기 때문에 저희들이 북부분원은 조직도에는 반영되어서 그렇게 그려질 것이기 때문에 북부분원은 반드시 저희들이 설치하는 것은 되어 있습니다. 다만 그 규모나 인원배분을 어떻게 본원하고 배치할 건가는 약간의 논의를 해야 될 사항이라고 보시면 되겠습니다. 
</p>
<p><b>○ 임병택 위원 </b> 알겠습니다. 일단은 구체적으로 뭔가 만들어지는 그런 내일을 기대해 보겠습니다. 아울러서 원장님께서는 따복마을과 관련된 정책제안자로도 알려져 계시고요. 또 실질적으로 무한한 애정을 가지시고 활동을 하신 걸로 제가 듣고 있습니다. 맞죠?
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 그렇습니다.
</p>
<p><b>○ 임병택 위원 </b> 그러면 따복마을과 관련된 남경필 도지사의 대표공약 실현하기 위한 원장님의 역할은 어떻게 규정지을 수 있을까요? 원장님의 역할과 경기개발원의 역할, 본분에 충실하게. 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 제가 연구원의 원장으로 지금 되었기 때문에 제가 사실 연구원 원장이 아닐 때 그 사업을 기획하고 또 인큐베이팅하는 역할을 가지고 사실 그것은 민 주도로 진행이 되는 것이 기본사업이기 때문에 사실은 민간의 많은 분들과 이런 사업의 필요성을 공감하고 또 민간이 그런 것들을 할 수 있도록 하는, 사실 저로서는 일종의 매개역할을 제가 담당해서 탐방단을 했다고 보시면 되고 제가 GRI 연구원장으로 오면서는 그 일에 대한 실제적인 추진과정에서는 저는 거리를 두고 손을 뗐습니다. 
</p>
<p style="padding-left:1.2em">  그리고 다만 잘 아시다시피 위원님들 따복공동체지원센터를 앞으로 3월이면 만들겠다는 목표를 가지고 있습니다만 그렇게 하기 위한 추진체가 있어야 되는데 그것이 도 집행부에는 기조실의 따복공동체지원단이라는 행정부서가 있지만 시민사회를 중심으로 하는 추진체는, 그러니까 거버넌스로서의 추진체는 없기 때문에 그 사업을 추진하기 위한 어떤 위원회를 현재로서는 아직 조례에 입각한 위원회를 만들 수 없는 상황이라서 지금 GRI에 자문위원회 성격의 위원회를 두고 있습니다. 
</p>
<p><b>○ 임병택 위원 </b> 그 위원회 구성현황하고 향후 활동계획을 서면으로 제출해 주십시오.
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 그러겠습니다. 
</p>
<p><b>○ 임병택 위원 </b> 제가 우려하는 부분은 따복공동체는 민간주도의 사업이어야 됩니다. 그래서 집행부는 정책을 만들고 의회는 예산을 승인해 줘야 되겠죠. 그래서 우리 경기도 내의 민간주체들이 주체성을 가지고, 자발성을 가지고, 의지를 가지고 해 나가야 되는데 우려 섞인 목소리는 원장님처럼 어떻게 보면 아주 중요한 위치에 계신 분께서 직접적으로 개입을 하시면 민간의 자발성이 좀 위축되지는 않을까 하는 그런 우려 섞인 말들이 들려오고 해서요. 그래서 그런 차원에서 말씀을 드리는 겁니다. 그래서 따복지원위원회 경기개발연구원에 구성되어 있는 구성현황하고 활동계획을 서면으로 제출해 주시기 바라고요. 
</p>
<p style="padding-left:1.2em">  하나 더 말씀드리겠습니다. 직제개편에서 의정연구센터라는 직책은 없어졌습니다, 센터는. 의정연구센터는 지난 기간 동안 부족한 도의회 정책지원을 위해서 2014년도만 하더라도 354건의 의정활동 지원실적을 이루어냈습니다. 2년 전에 의정연구센터가 만들어졌죠. 만들어졌고 그 당시에는 집행부, 의회, 경기개발연구원이 부족한 우리가 집행부와 도의회라는 양 날개가 있을 때 모든 정책적 지원이 집행부에 집중되는 이런 폐단을 극복해 보고자 왜냐하면 견제와 균형의 원리 차원에서 의회의 정책역량도 강화시켜줘야 되는 게 경기개발연구원의 또 정관에 명시된 목적이지 않습니까? 그래서 만들어지게 됐습니다. 그래서 20여명의 젊은 연구원들을 모집해서 2년이라는 기간 동안 운영을 해 왔습니다. 2년 동안 지방의회 지방자치역량을 학습하고 훈련받은 이 인적자원들을 향후에 어떻게 활용할 것인지 원장님 대안이 있으신가요? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 우선은 저희로서는 사실 11명의 입법조사원이 생기면서 사실 11명에 대해서는 예산상의 그것도 의회 의원님들과 물론 협의를 해야 되지만 사실 예산의 축소가 저희들이 판단되고 있고 그럼에도 불구하고 도의회 의정지원이라고 하는 필요한 사업을 어떻게 지속할 것인가 하는 점은 남아있고 또 한편으로는 감사원에서 활동양상의 변화를 지금 요구하고 있고 이 세 가지의 서로 다른 요소들을 종합한 상태에서 판단할 수밖에 없는 입장인 것 같습니다. 그런데 저희로서는 남아있는 나머지 인원들이 어쨌든 도 의정지원을 할 수 있도록 시스템 개편을 통해서 또 기능의 전환을 통해서 계속하면 좋겠다고 하는 생각을 가지고 있습니다. 
</p>
<p><b>○ 임병택 위원 </b> 이 부분만 마무리하고 질문을 마치도록 하겠습니다. 감사원의 지적은 지적일 뿐이고요. 감사원의 구체적인 행위의 종결은 감사처분요구서가 와야지 공식적인 행정명령으로서의 효력이 있습니다. 아직까지는 보고가 간 것이라고 그렇게 느껴지고요. 너무 섣부르지 않느냐라는 생각을 하게 됩니다. 저는 올해만 해서 354건인데 이 모든 의제들이 우리 경기도민의 민생과 직결되는 의제들이라고 저는 생각을 합니다, 쭉 리스트만 보더라도요. 그리고 또 그 보고서의 수준도 아주 탁월합니다. 저희들이 미처 몰랐던 부분들에 대한 정책제안까지도 있고 이런 부분이 어느 순간 사라진다면 거기에 대한 의정력의 약화라든지 이런 게 우려가 돼서 긴밀하게 최소한 우리 의회전반을 다 논의는 못하시더라도 저희 기획재정위와는, 왜냐하면 만들 때 기획재정위와 협의해서 만들었던 조직체이기 때문에 그 이후의 과정도 저희가 앞으로 예견되는 감사원의 조치결과에 벗어나지 않는 선에서, 준법 테두리 내에서 우리와 함께 호흡을 맞췄으면 하는 그럼 바람이 있습니다. 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 네, 그러면 그렇게 하도록 하겠습니다. 저희들 생각도 도의회와 우리 연구원과의 어떤 정책협의나 정책교류가 훨씬 더 활발해야 된다고 저는 생각합니다. 그런데 그 중요한 매개가 의정연구센터였기 때문에 이번 조직개편에도 사실 여러 가지 어려움이 있습니다만 약간 명칭을 변경하고 기능의 재조정을 염두에 두면서 지금 그렇게 부서편제를 약간 바꾼 것이거든요. 그리고 이것은 감사원의 지적내용이 어떠어떠한 서비스는 중복된다고 하는 지적으로 저도 이해를 하고 있기 때문에 열한 분이 앞으로는 더 늘어날 걸로 봅니다. 의회의, 아마 의정지원 역량이. 그 부분과 맞춰서 어떻게 상호 잘 유기적으로 지원업무를 할 건가 이렇게 생각하고 있습니다. 그래서 기획위원회 위원님들과는 앞으로 이것을 어떤 식으로 잘, 역량의 소모 없이 또는 역량의 위축 없이 잘될 수 있을까 하는 협의를 잘 하도록 하겠습니다. 
</p>
<p><b>○ 임병택 위원 </b> 네, 고맙습니다. 이상 질문 마치겠습니다. 
</p>
<p><b>○ 위원장 배수문 </b> 임병택 위원 수고하셨습니다. 이어서 장동일 위원 질의하여 주시기 바랍니다. 
</p>
<p><b>○ 장동일 위원 </b> 장동일 위원입니다. 연구원에서 2층버스 관련해서 연구한 게 있죠?
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 네. 
</p>
<p><b>○ 장동일 위원 </b> 그거 좀 설명 해주시죠. 설명 좀 해 주십시오. 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 제가 일단 간단히 설명드리고 여기 전문가들이 있으니까요. 우리 박사님이 설명을 하도록 그렇게 하겠습니다. 일단 2층버스는 전 집행부에서도 검토가 됐던 사항으로 이해하고 버스 한 대에 일단은 타고 다닐 수 있는 손님이 늘어나기 때문에 좌석제 이전에도 교통 첨두시에, 러시아워 시간에 보다 원활한 대중교통을 위해서 서울로 출퇴근하는 M버스의 용량을 높이기 위해서 기획됐던 것으로 압니다. 그런데 잘 아시다시피 여러 가지 현실적으로 하는 데의 어려움 때문에 쉽게 하지는 못했던 것 같은데 지금 이제 이번 집행부에서는 적극적으로 그 사업을 전개해 보려는 계획을 가진 것으로 그렇게 알고 있습니다. 자세한 답변은 관련 박사님이……. 
</p>
<p><b>○ 장동일 위원 </b> 이따 추가로 시간이 되면 제가 별도로 하겠습니다. 그다음에 지금 당장 우리 경기도의 현안문제로 대두될 수 있는 부분이 수도권매립지가 2016년까지만, 인천시에서 현재 수도권매립지 연장을 하겠다 이런 입장인 것 같아요. 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 네. 
</p>
<p><b>○ 장동일 위원 </b> 지금 수도권매립지에 들어가는 경기도의, 정확히 수치는 잘 모르겠는데 이게 만약에 안 되면 상당히 여러 가지 문제가 생길 건데 여기에 대한 연구, 물론 한 걸로 알고 있는데 간단히 요약해서 설명 좀 해주시죠. 어떻게 대안을 마련해야 되는지. 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 그거는 박사님이 좀 설명하면 안 되겠습니까? 
</p>
<p><b>○ 장동일 위원 </b> 네, 관련 박사님, 짧게……. 
</p>
<p><b>○ 생태환경연구실장 김동영 </b> 생태환경연구실장 김동영입니다. 저희 연구원에서 전공하시는 박사님이 이정임 박사님이 계시고요. 관련된 연구는 한 3∼4건 정도 진행됐고 그다음에 서울, 인천 공동연구도 올해, 작년 2건 정도 있습니다. 사실 경기도로서는 특별한 입장이 있는 것은 아니고요. 사실 환경부하고 서울시하고 인천의 갈등구조로 이렇게 드러나고 있습니다. 그런데 사실 수도권매립지가 다른 대안이 크게 없기 때문에 환경부가 중재를 하고 아마 서울시의 의견이 장기적으로는 반영이 되지 않을까 이렇게 생각을 하고 있습니다. 다들 그렇게 예상을 하고 있습니다. 단지 경기도는 약간 3자적인 입장에서 타결되는 과정을 조금 지켜보면서 장기적으로 준비를 해 나간다 이게 공식적인 입장인 것 같습니다. 
</p>
<p><b>○ 장동일 위원 </b> 이건 좀 막연해 보이는데요. 그럼 최악의 상황에 대비할 정도의 어떤 그런 것은 있어야 되지 않겠어요? 
</p>
<p><b>○ 생태환경연구실장 김동영 </b> 그래 가지고 만약에 따로 쓰레기 처리를 하게 되면 파생되는 문제점들이 어떤 건가 이거에 대한 검토는 돼 있습니다. 추가로 기간이 어느 정도 필요하고 관련된 비용도 제가 정확하게 기억은 안 나는데 약 7조 정도 소요되는 걸로 이런 정도의 추정까지 나와 있는 상태입니다. 
</p>
<p><b>○ 장동일 위원 </b> 연구원에서 좀 심도 있게 한번 고민을 해야 될 것 같아요. 
</p>
<p><b>○ 생태환경연구실장 김동영 </b> 네, 계속해서 하고 있습니다. 
</p>
<p><b>○ 장동일 위원 </b> 알겠습니다. 원장님 자리에 좀 다시 나와 주세요. 그건 나중에 기회가 되는 대로 제가 좀 관심이 많으니까 그렇게 하도록 하겠습니다. 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 네. 
</p>
<p><b>○ 장동일 위원 </b> 빅데이터 관련해서 잠깐만 짧게. 업무보고에 “부메랑이냐, 구세주냐.” 어떤 부메랑, 뭐가 어떻게 해서 부메랑이 돼서 돌아와요? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 어떤? 
</p>
<p><b>○ 장동일 위원 </b> 빅데이터와 사회안전에서 업무보고서 22쪽에 보면, 제가 잘 이해를 못 하고 있는데 이게 무슨 말씀인지. 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 제목을 이렇게 한 것은 빅데이터가 요새 빅데이터를 통해서 다양한 생산적인 이러한 산업이 파생될 수 있다는 측면에서는 구세주가 될 수 있지만 또 그것이 부작용도 하게 될 경우에 갖는 어떤 여러 가지 이런……. 
</p>
<p><b>○ 장동일 위원 </b> 그 말씀입니다. 그러니까 빅데이터가 만능이 아니죠. 저는 굉장히 사실 우려도 많이 합니다. 경발연에서 빅데이터 관련해서는 기조실에서 전담팀이 있어서 논의를 하고 있는데 지금 원장님께서는 오늘 기왕에 또 이런 얘기가 나왔으니까 순효과, 그러니까 긍정효과와 부정효과를 짤막하게 상식적으로 혹시 생각되는 부분만 좀……. 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 우선 빅데이터 논의가 사실은 비즈니스라는 차원에서 굉장히 새로운 부를 창출하는 어떤 근거로써도 많이 얘기되지만 실제로는 공공기관에서 많은 빅데이터를 그간 가지고 활용을 해 왔습니다, GIS에서부터 시작해서. 굉장히 많이 해왔고 따라서 공공에서 이제 신경을 써야 되는 것은 빅데이터를 민간이 적절하게 가공해서 쓸 수 있게끔 잘 공개하는 인프라를 깔아주는 역할이 공공에서의 주요한 역할이라고 봅니다. 더 나아가서 그거를 가지고 공공이 직접 비즈니스를 한다거나 이런 문제는 아니라고 생각이 듭니다. 대신에 이로 인해서 나타날 부작용이라고 하면 이 빅데이터는 아차 잘못하면 이거는 큰 범죄에도 악용이 될 수도 있고 아직 국제적으로 빅데이터에 대한 표준이 그러니까 보안표준이 있지 않은 것으로 알고 있습니다. 그렇기 때문에 보안표준을 잘 설정해서 데이터를 어떻게 선별해서 모으고 또 공개할 것인가라고 하는 점을 공공이 아주 잘 하지 않으면 이게 오히려 상당히 부작용이 커질 수도 있다고 생각이 듭니다. 
</p>
<p><b>○ 장동일 위원 </b> 공공이 잘못하면 이게 행정의 트로이목마 같은 게 될 수도 있다. 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 그렇습니다. 
</p>
<p><b>○ 장동일 위원 </b> 그렇게 생각도 드시죠? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 네. 
</p>
<p><b>○ 장동일 위원 </b> 알겠습니다. 엊그제 북부청에 가서 저희 여러 위원님들이 질의도 하고 그랬는데 대북삐라와 관련해서요. 어떻게 생각하시나요? 지금 북부발전에 상당히 장애요인이 된다 이런 얘기가 있어서. 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 제가 이거 관련해서 대정부질의, 국감 때 우리 경기도에 와서 질의하는 것도 보고 했습니다만 제 생각에는 안보와 관련된 문제와 지역의 안전에 관한 문제가 서로 갈등하고 대립하는 측면이 좀 있다고 봅니다. 그런데 문제로 지적하는, 질의하는 의원님들의, 그것이 진짜 통일이라고 하는 우리의 큰 과제에 순기능으로 작용할 건가 하는 또 사회적인 논란도 있는 것 같습니다. 그런데 제 개인적인 입장으로 보면 현재로서는 그와 같은 방식으로 자극적으로 하는 것은 우리가 좀 삼가야 할 때가 되지 않았나 저는 그렇게 생각합니다. 
</p>
<p><b>○ 장동일 위원 </b> 저는 물론 우리 8대 과제 중에 통일기반 조성계획이 있습니다, GRI 연구과제 중에. 지금 저는 북부발전에 가장 좋지 않은 외부불경제 효과가 이거라고 보는 거예요, 부정적 외부효과를. 보기 때문에 이런 부분에 대해서 연구를 앞으로 진행하는 과정에 또 원장님의 생각도 들어봐야 될 것 같아서 제가 여쭤보는 거고 워낙 많은 얘기가 나왔기 때문에 그 부분은 거기까지 하겠습니다. 
</p>
<p style="padding-left:1.2em">  그다음에 지난번에 제가 취임 청문회 때도 잠깐 제가 여쭤본 적이 있는데 분권에 대해서 많은 연구를 하셨어요, 우리 GRI에서. 그래서 이 부분에 대해서 좀 더 깊이 있는 연구와 비중을 더 둬야 되겠다. 제가 의정활동 하면서 늘 그런 생각을 합니다. 그 부분에 대해서는 제가 답변을 듣는 것보다는 원장님한테 당부드리는 것으로 그렇게 하도록 하겠습니다. 하시고 싶은 말씀……. 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 마지막 분권과 관련된 것은 일반적으로도 분권이 더 추구되어야 한다고 보고 지방자치 발전이 지금 같이 절반의 지방자치를 더 발전시키려는 여러 가지 노력이 다양한 분야에서 돼야 한다고 봅니다. 그리고 사실 경기도 자체에서 북부 분도와 관련된 것도 어떻게 보면 분권에 대한 요구이기도 하다고 저는 생각합니다. 북부 쪽에 계시는 분들은 아무래도 남부 중심의 경기도 발전정책이 주가 아니냐 하는 문제를 계속 제기하고 계시기 때문에 분권에 관한 것은 굉장히 많은 이슈들이 있다고 생각이 들고 앞으로 연구를 좀 더 실효성 있는 연구를 하면 좋겠다고 생각합니다.
</p>
<p><b>○ 장동일 위원 </b> 끝으로 제가 한 말씀만 더……. 분도 관련돼서는 원장님이 아까 그냥 논의를 안 하는 것도 하나의 방법이라고 말씀하셨는데 기왕에 나온 얘기는 저는 분도에 대해서는 반대하는 분명한 입장을 가지고 있고 더 안 좋을 거라는 생각도 때로는 들어요. 그 대신에 대안으로는 지금 현재 북부청의 권한이나 기능을 좀 확대시켜서 자율적이고 자발적인 그런 기능을 할 수 있도록 뭔가 보완을 하는 게 현실적인 대안이지 않나 이렇게 그런 어떤 입장을 저는 견지하고 있는데 원장님께서도 혹시, 그런 논의가 계속될 겁니다, 아마. 연구과제로 채택이 들어올 수도 있고 그랬을 때 그냥 안 하는 게 좋겠다는 그런 입장보다는 분명한 어떤 메시지가 있는 것도 좋겠다는 생각을 해봅니다. 아무튼 시간이 돼서 그 부분은 나중에 더 듣도록 하겠습니다. 이상입니다.
</p>
<p><b>○ 위원장 배수문 </b> 장동일 위원님 수고하셨습니다. 이어서 임두순 위원님 질의하여 주시기 바랍니다. 
</p>
<p><b>○ 임두순 위원 </b> 임두순입니다. 오전에 이어서 행감 하시느라고 고생 많으시고요. 오전에 지방재정보전금에 대한 자료를 요청을 했었는데 이 내용은 사실 오늘 GRI 행감에서 따질 문제는 아니고요. 그 과정을 알아보고 싶어서 아까 요청을 했었는데 실무담당자를 만나 가지고 그 문제는 따로 얘기를 했습니다. 그래서 이건 기조실 행감 때 물어볼 얘기고요. 그다음에 오전에 제가 북부발전연구센터에 대해서 잠깐 원장님한테 질문했잖아요? 사실 북부발전연구센터 때문에 혹시나 해서 제가 여쭤보는 거예요. 북부발전연구센터 내부적으로 설립문제 때문에 이번 조직개편 때 아까 말씀드린 어떤 북부발전 관련 그다음에 통일발전 관련 그런 부서를 없앤 그런 조직개편을 한 것 아니냐 이런 생각이 좀 드는데 이 부분에 대해서는 어떻게 생각하세요? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 지금 이렇습니다. 과도기라서 서류를 보면 그런 오해를 하실 수 있을 것 같습니다. 그런데 그런 생각을 못 하고 서류를 그렇게 한 게 잘못됐구나 하는 생각이 들었습니다. 그런데 서류상에 그나마 있던 통일ㆍ동북아센터가 없어진 것이 오히려 북부에 대한 어떤 배려가 더 줄어든 게 아니냐 하는 오해일 거라고 생각이 듭니다. 그런데 상황은 완전히 반대고요. 통일ㆍ동북아센터를 그냥 합친 이유는 현재 통일동북아센터는 사실 통일문제에 관해서 일하는 박사님 한 세 분 정도가 있고 거기에 민군팀이 있는 기구입니다, 현재로서는. 그런데 북부분원은 단순히 통일문제만 하는 게 아니라 북부의 전반적인 상황을 독자적인 하나의 연구기관으로 만들어서 독자적인 연구도 어느 정도 수행할 수 있도록, 물론 본원과 연관 속에서 합니다만 그렇게 하려는 계획을 가지고 있습니다. 그리고 예산도 이미 확보를 일부 집행부에서는 일단 되어 있는 상태입니다. 그런데 이제 우리가 조직표를 완전하게 이거를 그리려면 예산확정이 되고 그래서 이렇게 돼야지만 우리는 조직도상에 변화를 반영할 수가 있는 것입니다. 그래서 현재는 과도기라서 그림표에만 없는 걸로 이해를 하시면 좋을 것 같습니다. 
</p>
<p><b>○ 임두순 위원 </b> 원장님! 제가 드리고 싶은 말씀은 북부발전연구센터의 필요성은 100%, 아니 200% 공감을 해요. 공감을 하는데요. 북부 쪽에 어떤 균형발전이나 경기도 전체로 봐서 앞으로 동북아 발전에 가장 중심축이 돼야 할 부분이 사실 북부 쪽이라고 생각을 해요. 접경지를 포함을 해 가지고, 통일을 생각한다고 그러면요. 그럼 균형발전이나 통일문제 이런 북부 쪽의 연관 문제를 위해서 우리 남 지사님의 중요한 공약 과제도, 민선6기의 과제도 균형발전의 문제인데 오전에 말씀드린 것처럼. 그렇다면 이렇게 중요한 내용 중에 또 연구과제에 보면 북부 관련 연구계획이 한 3개나 되더라고요, 여러 가지 중에서. 이러한 상황에 중요한, GRI에서 북부 관련 어떤 균형발전과 통일 접경지 쪽에, 북쪽에 이러한 관련부서를 하나 정도는 GRI에 둬야 되는 거 아닌가 그런 연구센터를, 본청에. 그런 맥락에서 말씀드린 거고요. 어쨌든 저는 원장님한테 좀 당부드리고 싶은 게 아까 말씀드린 북부발전연구지원센터는 100% 공감을 하지만 여기 GRI 조직에는 최소한 북부 쪽의 균형발전을 위해 또 통일을 위해서, 나중에 통일시대를 대비해서 그런 부서는 꼭 하나 둬야 되는 것이 아닌가 그 연구부서는, 그 맥락에서 말씀드린 겁니다. 어떻게 생각하십니까? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 물론 검토하겠습니다만 저희들이 북부분원에다가 통일센터를 두려고 하고 있습니다. 
</p>
<p><b>○ 임두순 위원 </b> 알겠습니다. 그 정도로 질문을 하도록 하겠습니다. 
</p>
<p style="padding-left:1.2em">  그리고 아까 기금예치 현황을 제가 잠깐 봤는데 한 가지 오해가 풀린 부분은 아까 실무자가 오셔서 말씀하신 게 날짜 차이 나는 부분은 휴일이 겹쳐 가지고 날짜가 차이난다고 그러는데 그건 좀 이해가 됐고요. 
</p>
<p style="padding-left:1.2em">  그리고 기금 중에 이자수입이 5%라는 말이에요? 그다음에 부서운영비가 5%로 거의 비슷해요, 금액 차이는 약간 있지만. 그런데 이렇게 중요한 기금 이자수입인데 어떤 안전 때문에 그랬는지 어떤 이유에서인지 여러 은행에다가 분산예치를 하셨잖아요?
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 네.
</p>
<p><b>○ 임두순 위원 </b> 그런데 은행별로 보면 이자가 거의 2%까지 차이나는 데도 있어요, 이자가. 그런데 예금예치를 이렇게 해야지 되는 이유가 어떤 이유죠? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 우선 보시면 기금이 3.5%대 혹은 3.2%대 이렇게 있는 것은 장기적인 것이지 않습니까? 그것은 기금이 아시다시피 우리가 기금을 지금 빼서 써야 되는 기금들도 있잖아요? 예를 들면 올해도 이미 30억을 썼고 내년에도 그 정도를 쓸 것으로 예상이 되기 때문에 그런 기금은 기간을 장기로 해서 예치할 수 없죠? 그렇기 때문에 좀 장기적으로 예치를 해 놔야 될 액수는 장기적으로 예치를 하고 있고 또 단기적으로 뽑아서 써야 되는 것은 그렇게 못 하는 것입니다. 기간이 짧을수록 이율이 낮으니까요. 그래서 그런 차이가 있는 것으로 봐야 되고 여러 기관에다가 분산한 것은 그 기금을 그때그때 이율이 높은 기관이 기관별로도 약간 차이가 있어서 당시에 이게 만기가 되면 만기가 됐다고 그 기관에다가 다시 예치하는 게 아니라 그때 당시에 더 높은 금리를 주는 곳이 있으면 또 기관을 옮기는 것이죠. 그래서 이율을 보고서 기관을 옮기고 또 분산을 해 놔야지 위험 분산이 되니까요, 한 기관에 다 하지 않고. 그렇게 하는 걸로 이해하고 있습니다. 
</p>
<p><b>○ 임두순 위원 </b> 네, 알겠습니다. 어쨌든 이 기금운용에 대해서는 특히 이자수입 부분에는 대해서는 이런 대표적인 몇 개 은행뿐만이 아니고 금융기관 여러 기관들을 좀 합리적으로 검토를 하셔 가지고 이자수입에 대한 부분을 잘 좀 관리해 주셨으면 하고요. 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 네. 
</p>
<p><b>○ 임두순 위원 </b> 오전에 임병택 위원님이 질문하신 내용과 좀 겹치는 부분이 있어 가지고 그 부분은 질문을 안 하겠는데요. 2014년도 4월에 법제처에서 수의계약불가 재해석으로 수임률이 많이 급감을 했죠, 우리 용역에 대한. 그런데 그때 4월 법제처에서 수의계약불가 재해석을 했는데 그 뒤로는 어떻게 진행이 된 거죠? 수의계약 내용이 굉장히 많더라고요. 그런데 법제처에서는 불가 해석을 했는데 GRI에서는 어떤 입장으로 용역수주를 이런 식으로 계속 하신 거죠? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 재정부장이 답변하도록 하면 좋을 것 같습니다.
</p>
<p><b>○ 임두순 위원 </b> 네, 그러세요.
</p>
<p><b>○ 재정지원부장 박인숙 </b> 재정지원부장 박인숙입니다. 4월 이후 법제처에서 수의계약 불가판정이 나서 저희는 협상에 의한 입찰과 최저가 적격심사에 의한 입찰에 계속 적극적으로 참여를 하고 있습니다. 그런데 10월에 안행부의 계약심의위원회를 통해서 저희가 정말 수행해야 될 용역에 대해서는 계약심의위원회를 통해서 할 수 있느냐고 문의를 한 사항이 있습니다. 그랬더니 적극적으로 계약심의위원회를 활용해서 하라는 그런 통지를 받았거든요. 
</p>
<p><b>○ 임두순 위원 </b> 그렇게 하면 문제는 없는 건가요?
</p>
<p><b>○ 재정지원부장 박인숙 </b> 계약심의위원회가 최고의 방법은 아닙니다. 
</p>
<p><b>○ 임두순 위원 </b> 어떤 게 최고의 방법이죠?
</p>
<p><b>○ 재정지원부장 박인숙 </b> 저희가 적극적으로 경쟁입찰에 참여하는 수밖에 없습니다. 
</p>
<p><b>○ 임두순 위원 </b> 그렇게 노력을 해 주시고요.
</p>
<p><b>○ 재정지원부장 박인숙 </b> 알겠습니다. 
</p>
<p><b>○ 임두순 위원 </b> 원장님, 오전에 존경하는 임병택 위원님이 기금에 대해서 질의를 하셨는데 최근 5년간 106억 원 정도 기금을 사용하셨잖아요. 지금 현재 잔여기금이 166억이네요. 그래서 우리 임병택 위원님이 말씀하신 대로 어떤 기금운용에 대한 합리적 운용으로 또 수익창출도 계속 노력을 하셔야 하겠지만 저는 사실 본 위원은 기금이라는 것이 물론 이자수입의 어떤 당위성이랑 우리 GRI의 존립기반인 기금의 조성은 당연하다고 보지만 일정 부분의 수익창출이나 향후의 수입이 예상 된다 그러면 저는 그 기금은 적극적으로 사용을 해서 더 많은 수익창출, 그러니까 이자수입이나 어떤 이런 것보다는 기금 사용을 오히려 늘려 가지고 수익을 창출할 수 있는 부분이나 어떤 당위성이 있다고 그러면 저는 기금을 적극적으로 사용하는 데 동의하는 편이거든요. 원장님 생각은 어떠세요, 이 기금 사용하는 건에 대해? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 그냥 떠오르는 생각은 그 말씀이 아주 모험적인 그런 사업에 투자하라는 뜻은 아니실 테고 예를 들면 국공채라든지 이런 곳에 해서 이율이 높은 곳도 찾아보고 이렇게 이해가 됩니다만 사실 큰 기금을 운용하는 그러니까 기금 자체를 가지고 사업하는 그런 기관 같으면, 공제회라든지 이런 기관 같으면 여러 가지 다양하게 위험도 일정하게 감수하지만, 좀 더 늘리도록 하는 그런 사업을 투자하지만 그런 곳은 제가 알기로는 기금운용을 위한 별도의 굉장히 전문화된 조직을 가지고 있습니다. 그런데도 항상 국감 때나 이런 때 보면 그 기금을 까먹거나 또 거기에 여러 가지 부정적인 문제가 있어서 굉장히 기금운용에 어려움을 겪고 있는 것으로 알고 있습니다. 그런데 우리 GRI는 사실 연구사업 중심이고 기금이라 해봐야 큰 액수도 아닌데 그것을 잘못 운용을, 전문가도 없는 상태에서 운용을 해서 조금이라도 누를 끼치는 일이 일어나면 감당할 수 없을 거라고 생각합니다. 
</p>
<p><b>○ 임두순 위원 </b> 아무튼 정책컨설팅센터가 신설됐잖아요. 그러니까 수익성 강화를 위한 방안을 적극적으로 연구를 해 주시고요.
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 그러겠습니다.
</p>
<p><b>○ 임두순 위원 </b> 당부드리는 말씀인데요. 그리고 인력도 좀 효율적인 운영을 하셔서 그만큼 어떤 절감되는 비용을 가지고 다시 재투자해서 GRI가 우리 경기도 발전의 싱크탱크인 만큼 더 많은 성과물을 내셔서 수익창출도 마찬가지지만, 그렇다고 수익창출에만 너무 의존하지 마시고 정말 좋은 연구성과를 내서 우리 경기도가 정책을 펴나가는 데 길잡이가 돼 주셨으면 하는 그런 바람의 당부 말씀드리면서 질문 마치겠습니다. 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 그렇게 하겠습니다. 
</p>
<p><b>○ 위원장 배수문 </b> 임두순 위원님 수고하셨습니다. 안혜영 위원님 질의하여 주시기 바랍니다.
</p>
<p><b>○ 안혜영 위원 </b> 수원 출신 안혜영 위원입니다. 10분이 짧아서 빨리빨리 질의를 하도록 하겠습니다. 민선4ㆍ5기 경기도정 주요성과 분석연구라는 걸 올해 했었습니다. 기간이 3월 10일부터 6월 30일까지 했던 사업인데요. 이 예산이 9,359만 5,900원짜리 사업이었고요. 그런데 그 안에 위탁연구비가 9,050만 원 돈이 됩니다. 계산이 되시죠? 전체예산이 사업비가 9,359만 5,000원인데 그중에서 한 300만 원 돈을 빼고 나머지는 위탁연구비로 사업을 주셨어요. GRI가 했다라고 할 수 없는 연구라고 보는데 어떻게 생각하시나요? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 이것은 당시 연구책임 맡은 분이 답변하면 안 되겠습니까?
</p>
<p><b>○ 안혜영 위원 </b> 그러다 보면 시간이 없어서요. 본 위원의 생각을 말씀드리자면 이게 민선4ㆍ5기 경기도정이라고 하는 것이 전임 지사님 시절을 얘기하는 거죠?
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 그렇습니다. 
</p>
<p><b>○ 안혜영 위원 </b> 전임 지사 치적보고서라고 생각을 할 수밖에 없습니다. 이게 연구내용이라기보다는 책자를 만들었어요, 딱딱한 하드 케이스로 해서 멋지게. 몇 부가 나왔느냐 하면 2,000부에 대한 예산입니다. 처음엔 예산이 훨씬 더 많았어요. 1억 3,000만 원이 넘는 예산으로 편성했었는데 진행과정에서 9,000만 원이 조금 넘는 비용으로 지급이 됐고요. 더 문제는 이게 전체 경기개발연구원의 사업으로 되어 있는데 연구비의 95% 이상이 외부로 나가고 겨우 그것도 일반수용비, 국내여비, 업무추진비 이런 비용으로 300만 원 돈이 쓰였다는 겁니다. 그렇다면 이게 정상적인 사업이라고 할 수 없겠죠. 어떻게 생각하십니까? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 적절하지 않은 것 같습니다.
</p>
<p><b>○ 안혜영 위원 </b> 적절하지 않죠. 그런데 더 문제는 이게 전체 이러한 사업비가 올해는 6억, 2013년도에 이게 정책연구과제비로 설정이 되었던 사업비인데 2013년도에는 89건이 있었습니다. 89건에 지출되었던 비용이 7억 4,000만 원 정도 그리고 2013년도에 73건이 이런 사업을 했습니다. 그런데 73건에 들어간 전체비용이 6억 1,700만 원 돈입니다. 그러면 73건 그 안에 겨우 한 건에 거의 1억을 지출하셨다는 거거든요. 문제가 아주 심각하겠죠. 나머지 사업이 제대로 진행이 됐겠습니까? 6억 1,700만 원 정도의 비용에서 9,000만 원 돈을 빼고 나면 5억 3,000만 원, 그것도 안 들어간 거거든요. 그걸로 나머지 72건을 다 사업을 진행하셨어요. 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 그 72건은…….
</p>
<p><b>○ 안혜영 위원 </b> 500만 원부터 몇십만 원짜리도 있고 다 그렇습니다. 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 대체로 정책연구를 하면 정책연구 하나당 보통 500에서 1,000만 원 내의 연구비를 씁니다. 그런데 이것은 지금 말씀하신 걸 보면 위탁을 준 사업인 것 같습니다.
</p>
<p><b>○ 안혜영 위원 </b> 그렇죠. 이게 경기도에서 물론 지시가 내려와서 한 사업이겠지만 앞으로 만약에 이런 식의 사업을 경기도에서 경발연에 요구를 한다면 원장님으로서 어떻게 하시겠습니까? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 저는 그러니까 한 집행부가 일단 임기를 마칠 때쯤 그 임기에 따르는 성과평가를 하는 것은 가능한 일이고 또 해야 된다고 봅니다. 
</p>
<p><b>○ 안혜영 위원 </b> 그런데 이런 방식은 아니겠죠. 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 그런데 이런 방식으로 하면 안 되죠.
</p>
<p><b>○ 안혜영 위원 </b> 경발연이 하려고 한다고 그러면 경발연에서의 연구실적에 대한 내용을 채우게끔 했어야 되는 거죠, 겉표지 만들 것이 아니라. 그렇지 않겠습니까? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 물론이죠. 우리 연구원 내에서 실질적으로…….
</p>
<p><b>○ 안혜영 위원 </b> 그렇다고 그러면 업체에다 줘야 될 그러한 사업이라고 생각합니다. 경발연이 일반업체는 아니겠죠, 기획사는 아니지 않습니까? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 물론이죠. 
</p>
<p><b>○ 안혜영 위원 </b> 그런 기획사가 되지 않으셨으면 하는 바람으로 지적을 드립니다. 그리고 또 하나 저희 초빙연구원에 대한 자료를 받아봤습니다. 정규직박사 외 초빙연구원 임용현황에 대해서 제가 하나 서류를 받았고요. 그리고 자료로 최근 연구원별 연구과제 수행현황에 대한 걸 받았습니다. 설명을 드리자면 제가 이 책자를 받은 것은 정규연구직과 초빙연구원을 포함한 자료고요. 이것은 초빙연구원에 한한 자료를 받았습니다. 그런데 초빙연구원은 계약이나 기간들이 없습니까? 정해진 게 없나요?
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 초빙연구원은 보통 1년 단위로 초빙을 할 수도 있고요. 아니면 과제…….
</p>
<p><b>○ 안혜영 위원 </b> 기본이 많으면 한 2년 정도 되겠죠.
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 과제 베이스로 받기도 합니다. 
</p>
<p><b>○ 안혜영 위원 </b> 짧은 것은 몇 개월인 것도 있습니다. 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 물론입니다. 
</p>
<p><b>○ 안혜영 위원 </b> 1개월 정도 되는 것도 있는 것 같고요. 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 과제가 빨리 끝나면 빨리 하죠. 
</p>
<p><b>○ 안혜영 위원 </b> 그런데 보통 그 과제들이 2년을 넘지 않겠죠. 그렇지 않겠습니까?
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 보통 그렇습니다. 
</p>
<p><b>○ 안혜영 위원 </b> 그런데 보면 2010년도 이전에 입사하셔서 지금까지 계시는 분들이 몇 분 계세요. 그분들의 연구실적을 보니 1년에 한 건 정도밖에 되지 않습니다. 경기개발연구원의 연구목적으로 설립된 그 취지와 목적에 맞지 않는다고 보는데 어떻게 생각하시나요? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 그런데 그것은 좀 케이스를 구체적으로 봐야 될 것 같은데요. 
</p>
<p><b>○ 안혜영 위원 </b> 케이스를 볼 수 있겠습니다. 그 이전에 본 위원이 체크를 해 봤습니다, 자료 주신 것에. 아까 설명해 드린 것처럼 정규연구직 포함한 초빙연구원 그렇다고 그러면 이건 포함한 거고 초빙연구원이니까 여기에 계신 분들은 다 이 자료에 포함이 되어 있어야겠죠? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 물론입니다. 
</p>
<p><b>○ 안혜영 위원 </b> 그런데 이 안에 초빙연구원 명단에는 있는데 포함돼서 정규연구직과 초빙연구원을 합쳐놓은 이 명단에 안 들어계신 분이 꽤 돼요. 그 이유를 제가 면밀히 따져봤더니 1저자로 주관해서 연구를 주도해서 하신 사업이 없기 때문에, 연구실적이 없기 때문에 이 안의 명단에 없으신 거예요. 그렇다고 치면 초빙연구원들은 몇 년 동안, 수년 동안 길게는 4~5년 동안 계시는 분들이 이 연구실적을, 1저자로 해서 연구실적을 추진해서 한 것이 한 건도 없다는 거예요. 공동저자로 하거나 아니면 지원을 좀 하거나 그런 식의 연구실적밖에 없다는 것에 문제 지적을 안 할 수가 없습니다. 
</p>
<p style="padding-left:1.2em">  또한 본 위원이 일일이 체크를 해 봤습니다. 2011년도부터 2014년도 9월 30일 기준입니다. 4년에 걸쳐서 연구실적을 보니 따져 보니까 66명 정도가 되세요. 그 안에 퇴사를 하신 분들도 있고요. 퇴사를 하신 분들이 많지는 않습니다. 그런데 그 안에 4명만 13년 전에 퇴사를 하셨습니다. 그런데 4년 동안 연구실적이 5개 이하로 되어 있으신 분들이 스물두 분이나 되세요. 문제가 있지 않습니까, 4년 동안? 그러면 1년에 1건에서 2건도 거의 안 하셨다는 거예요. 그리고 10개 이하가 열일곱 분 그리고 4년 동안 16개 이상 연구실적을 갖고 계신 분이 일곱 분밖에 안 계십니다. 더구나 이 안에 1개밖에 연구실적을 안 가지고 계신 분이 4명인데 그 안에 2명은 요 근래에 퇴사를 하셨더라고요. 그러니까 1년에 한 건도 연구실적을 갖고 있지 않으신 분이 경기개발연구원에 적을 두고 계신 거예요. 그러면 연구를 해야 되는 이 설립목적으로 예산을 받고 집행하고 또 연구를 충실히 하고 계시는 분들이 볼 때는 이해가 되지 않는 거죠. 그리고 아까 말씀하신 것처럼 무슨 한 예로 군부대 관련된 일을 하고 계시는 분이 있습니다. 연구실적이 아닌 대외활동을 더 많이 하고 계시는 거죠. 물론 그분들의 역할이 아주 크다는 거 알고 있습니다. 그렇다고 하면 경기개발연구원의 연구를 하시는 데에 적을 둘 것이 아니라 대외협력관이라든가 아니면 외부의 다른 적재적소에 그분들이 일을 더 열심히 할 수 있는 곳에 적을 두고 일을 할 수 있도록 환경을 만들어 드리는 것이 더 옳지 않은가 싶은데 어떻게 생각하십니까? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 우선 초빙연구원은 연구책임을 지지 않거든요. 그래서 연구책임성과물을 보면 실적이 없는 것은 당연한 일이고요. 
</p>
<p><b>○ 안혜영 위원 </b> 그분들에게도 월급이 거의 300~500만 원 돈이 나가죠?
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 물론이죠. 또 그분들도 연구를 수행하니까요. 그런데 연구책임은 원내 박사들이 지도록 제도적으로 그렇게 되어 있습니다. 
</p>
<p><b>○ 안혜영 위원 </b> 그러게요. 그런데 초빙연구원분들 이렇게 많이 필요하실까요? 경기개발연구원의 목적과 취지가 뭡니까, 설립목적이?
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 초빙연구원은 우리가 그 전문성을 가진 박사님이 안 계실 경우에 한해서 저희들이 초빙해서 하고 있습니다. 
</p>
<p><b>○ 안혜영 위원 </b> 그러면 다시 한 번 다른 방향에서 질의를 하겠습니다. 자료를 받은 것 중에 비상임연구위원에 관련된 자료를 받았습니다. 비상임연구위원으로 계신 분이 지금 현재 여덟 분이세요. 아시죠, 원장님?
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 네. 
</p>
<p><b>○ 안혜영 위원 </b> 여덟 분이십니다. 여덟 분 중에 다 박사급이세요. 그리고 기간이나 연구실적에 대한 기초연구라든가 과제 이런 것들이 다 있어요. 그런데 눈에 띄시는 분이 한 분 계십니다. 조동원 비상임이사님이신데 이분만 박사님으로 선임되시지 않은 분이세요. 이분이 저희 혁신위원회 위원장님이시죠?
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 그렇습니다. 
</p>
<p><b>○ 안혜영 위원 </b> 혁신위원회에 제가 지난번에 질의했을 때 혁신위원회에 따로 지원하는 게 없다고 그러셨습니다. 그죠? 지원되는 비용이 따로 책정되어 있는 게 없죠? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 그렇지 않습니다. 우리 GRI에 소속돼 있는 위원회기 때문에 회의수당이나 또는 사회자비용이나 이런 수당은 지급하고 있습니다. 
</p>
<p><b>○ 안혜영 위원 </b> 제가 혁신위원회 처음에 구성이 됐을 때 제가 성명을 낸 게 있습니다. 그때 설명을 집행부에서 듣기로는 혁신위원회에 따로 지원하는 게 없다. 그리고 공식적으로 회의를…….
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 그때 시점에는 아마 없었을 겁니다. 
</p>
<p><b>○ 안혜영 위원 </b> 회의를 공식적으로 형식을 갖춰서 하는 것이 아니다. 온라인상에 회의를 한다고까지 얘기를 했습니다. 모여서 하는 게 아니라 온라인상으로 하는 거고 다른 비용이 전혀 지원되는 게 없다고 했는데 혁신위원회 진행하는 과정에 보면 여러 가지 지금 말씀하신 회의수당 같은 게 지원이 되고 있습니다. 그러니까 처음에 설명하시고 설립했을 때보다 다른 취지에 진행이 된다는 거죠.
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 그것은 위원님이 당시에 질의했을 때는 혁신위원회가 아직까지 GRI의 공식적인 위원회가 아니었고요. GRI의 공식위원회가 된 게 한 달쯤인가 그전부터입니다. 그때부터는 수당이 나왔습니다. 
</p>
<p><b>○ 안혜영 위원 </b> 이분이 여기에 비상임이사로 선정된 이유가 특별한 게 있나요?
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 비상임연구위원의 역할은 도정에 대한 자문을 하고 또 일정한 활동을 하는 분을 비상근으로 쓰는 것입니다. 그렇기 때문에 그분이 경기도정에 대해서 한 기여도나 이런 것들을 보아서 우리가 비상임연구원으로 위촉한 겁니다. 
</p>
<p><b>○ 안혜영 위원 </b> 알겠습니다. 상세한 것은 다시 추가질의에 하도록 하겠습니다. 이상입니다.
</p>
<p style="padding-left:2.4em">    (배수문 위원장, 임병택 간사와 사회교대)
</p>
<p><b>○ 위원장대리 임병택 </b> 수고하셨습니다. 이현호 위원님 질의해 주시죠.
</p>
<p><b>○ 이현호 위원 </b> 이천 출신 이현호입니다. 오전에 질의했던 내용인데요, 다른 위원께서. 경기북부지역의 균형발전을 위해 가지고 경기문화재단과 경기개발연구원 북부분원을 설립을 하신다는 겁니까, 안 하신다는 겁니까? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 설립을 하겠다는 계획을 가지고 있고 집행부에서는 예산반영도 되어 있습니다. 
</p>
<p><b>○ 이현호 위원 </b> 하시겠다는 거죠?
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 그렇습니다. 
</p>
<p><b>○ 이현호 위원 </b> 지금까지 경기개발연구원에서 연구용역을 보면 늘상 나오는 얘기고 많은 위원님께서 말씀하셨지만 경기북부권에 관련돼서는 연구든지 또 도지사님께서도 그렇고 도정에서도 북부권에다 많이 반영을 하고 있는데 제가 물론 동부권지역의 위원이라고 해서 그렇겠지만 동부권 얘기는 나오는 데가 없어요. 경기개발연구원도 마찬가지고 도지사님의 정책방안도 보면 동부권은 완전히 소외당하는 그런 느낌을 갖고 있거든요. 원장님께서는 그렇게 생각 안 하십니까? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 저희 GRI에서는 동부권 관련해서도 그간에 연구를 꽤 많이 했습니다. 
</p>
<p><b>○ 이현호 위원 </b> 앞으로 계획이…….
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 앞으로도 많이 할 겁니다. 
</p>
<p><b>○ 이현호 위원 </b> 할 겁니까?
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 그리고 가지고 있는 생각은 사실 북부권연구라고 하지만 특히 물 관련된 것은 동부권이 많이 관련돼 있기 때문에 동부권과 함께 북부발전연구분원이 동부권을 포함해서 연구를 할 것으로 이렇게 생각하고 있습니다. 
</p>
<p><b>○ 이현호 위원 </b> 업무보고에서 보면 시군 순회토론회나 정책세미나에도 동부권은 안 들어가 있어요. 그래서 원장님께서 동부권에도 같은 경기지역이니까 균형발전 차원에서 신경을 쓰셔야 되지 않나 이렇게 말씀을 드리는 겁니다. 그래서 한번 이천에 내려오신다면 제가 만나 뵙고 이천의 어떤 발전적인 거, 오지지역 같은 데 또 경기개발연구원에서 한번 가봤으면 하는 데로 제가 안내할 테니까 오신다면 제가 함께 자리를 하겠습니다. 이천에 한번 오시겠습니까? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 네, 그럼요. 꼭 가겠습니다. 
</p>
<p><b>○ 이현호 위원 </b> 언제쯤 오실 계획입니까, 혹시요? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 빨리 가겠습니다. 
</p>
<p><b>○ 이현호 위원 </b> 금년 12월 달에 한번 오실 수 있으실까요?
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 그러겠습니다. 
</p>
<p><b>○ 이현호 위원 </b> 확실히 하겠습니다. 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 네.
</p>
<p><b>○ 이현호 위원 </b> 그리고요. 2012년도, 13년도, 14년도 우리 경기지역에 많은 언론사가 있습니다. 언론사에 홍보비가 많이 나갔다는 것을 얘기하려는 게 아니라 12년도에는 50회, 13년도에는 90회, 2014년도에는 물론 10월 3일까지라서 모르겠지만 여태까지 12개밖에 안 나갔어요, 홍보비가. 그러면 저희가 판단할 때에 전전년도, 지난 연도가 홍보비가 많이 나간 건지 아니면 지금 2014년도에 우리 경기개발연구원에서 홍보할 내용이 없어서 홍보 안 하신 건지 거기에 대해서 한번 명쾌한 답변을 주시기 바랍니다. 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 일단은 위원님이 아시다시피 지방선거가 있는 해에는 아무래도 연구원에서는 뭐랄까요. 홍보비나 이런 것들의 지출이 약간 줄어드는 측면도 있다고 봅니다. 그런 측면도 있고 또 언론사와 함께하는 사업내용이 단순히 GRI에서 하는 활동을 홍보하는 것만 있는 것이 아니라 공동으로 하는 다양한 지역사회 발전을 위한 사업들도 있습니다. 그렇기 때문에 언론은 굉장히 중요하다고 생각을 하고 있고요. 그래서 GRI를 단순히 홍보하는 문제만이 아니라 또 지역 언론의 발전이라고 하는 것도 굉장히 중요하기 때문에 저희들이 언론과의 관계를 잘 유지하도록 앞으로 더 만전을 기하겠습니다. 
</p>
<p><b>○ 이현호 위원 </b> 저는 금년도에 경기개발연구원에서 홍보할 내용이 없어 가지고 안 하신 거 같아. 언론사 계시지마는 정말 우리 국민들이나 도민들, 시민들은 언론이 가장 중요하거든요. 물론 우리 도의원들은 그래도 도에 드나들고 의원 활동을 하니까 확실히 알겠지마는 일반 도민들, 시민들은 신문이나 언론 안 보면 전혀 모릅니다. 그래서 앞으로 우리 언론사들 잘 통하셔 가지고 경기도에 일어난 일 또 경기개발연구원에서 일어난 일들을 낱낱이 홍보하셔서 많은 도민들의 알권리를 충족시켜 주기를 부탁드리면서 이만 마치겠습니다. 이상입니다. 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 알겠습니다. 
</p>
<p><b>○ 위원장대리 임병택 </b> 수고하셨습니다. 김호겸 위원님 질문하시죠. 
</p>
<p><b>○ 김호겸 위원 </b> 김호겸 위원입니다. 간단하게, 시간이 없기 때문에. 우리 이사회 정관 있죠? 정관에 지금 현재 이사진이 몇 분이 되어 있나요? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 정관에는 30명 미만으로 되어 있습니다. 
</p>
<p><b>○ 김호겸 위원 </b> 30명 미만으로 되어 있는데 현재 돼 있는 분이 일부 해촉이 되시고 30명 미만으로 돼 있죠? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 네. 
</p>
<p><b>○ 김호겸 위원 </b> 30명 미만인데 현재 우리가 13명으로 운영이 되다가 현재 여덟 분 정도가 아마 임기가 9월 달까지 만료돼서 현재 해촉되신 건가요? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 그렇습니다. 
</p>
<p><b>○ 김호겸 위원 </b> 앞으로 남은 분들은 언제 재위촉이 되시나요? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 지금 공고를 해놨습니다. 
</p>
<p><b>○ 김호겸 위원 </b> 공고를 했습니까? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 네. 
</p>
<p><b>○ 김호겸 위원 </b> 이사 선임은 각계에 원장님이 추천의뢰해서 거기서 추천을 받아서 이사회 의결로……. 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 추천을 받는 게 아니라 공모절차를 거칩니다. 
</p>
<p><b>○ 김호겸 위원 </b> 아, 공모절차를 거쳐서? 그렇죠. 지금 이사회가 1년에 보통 몇 번 정도 운영을 하고 계시나요? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 저희들이 반드시 해야 되는 경우만 주로 하고 있기 때문에 사실 한 4회? 이런 정도……. 
</p>
<p><b>○ 김호겸 위원 </b> 3∼4회 정도 하고 계시죠? 그래도 거기서 주요사업이라든가 운영과 관련해서 의결을 하고 있죠? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 그렇습니다. 
</p>
<p><b>○ 김호겸 위원 </b> 그런 의미에서 볼 때 현재 이사진들을 보게 되면 대부분 학계에 좀 계시고 언론사 관계되는 분도 계시고 그다음에 경제 쪽을 전공하신 분들이 구분이 돼 있어요. 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 네. 
</p>
<p><b>○ 김호겸 위원 </b> 본 위원이 말씀드리고 싶은 것은 여성계를 대표하는 분도 좀 있어야 되지 않나, 여성계. 여성의 입장에서 우리 어머니의 입장에서 우리 경발연에 반드시 이사진으로 참여해야 될 것 같고요. 그다음에 시민사회단체라든가 또 사회복지를 전공한 학계도 필요한데 경제 쪽에도 한 서너 명이, 언론계, 많이 중복돼 있어요? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 네. 
</p>
<p><b>○ 김호겸 위원 </b> 이런 분들을 각계각층의 좋은, 훌륭한 분들로 모셔야 되지 않나 그렇게 생각하는데 어떻게 생각하시죠? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 좋은 생각이라고 봅니다. 
</p>
<p><b>○ 김호겸 위원 </b> 그런 식으로 남은 분들 다시 재공고를 해서 위촉을 하실 때는 그런 분들로 채워주시게끔 적극적인 노력을 기울여주기를 부탁드리겠습니다. 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 네. 
</p>
<p><b>○ 김호겸 위원 </b> 그리고 두 번째로는 현재 연구원들, 연구하시는 분들이 몇 명으로 구성돼 있죠? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 정규직 박사 인력은 현재는 51명입니다. 
</p>
<p><b>○ 김호겸 위원 </b> 51명 돼 있죠? 그런데 하여튼 각 분야에서 많은 연구 과제를 수행해 오셔서 먼저 수고하셨다는 말씀 올리고요. 그런데 연구실적이나 과제 이런 걸 보게 되면 경기도민의 삶의 질과 관련되는 부분도 있지만 어떻게 보면 백화점식 나열되는 부분도 상당수 있다고 봅니다. 그래서 어떻게 보면 실적 위주의 연구도 있는 것도 같고 그런데 그래서 우리 경발연에서 연구실적과 관련해서 경기도정에 정책과 예산지원을 통해서 반영된 게 사업이 얼마나 있나 이렇게 보니까 지금 주신 자료를 가지고는 파악을 할 수 없습니다. 다 뭐 제안을 하고 이렇게 되어 있기 때문에 실질적으로 자료를 갖다 파악을 할 수 없기 때문에 향후 경기도의 도정에 정책적으로 또 예산으로 반영된 사업을 발췌를 해서 서면으로 좀 제출해 주시기 바라겠습니다. 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 네, 알겠습니다. 그런데 잠깐 설명을 좀 드리면 이렇습니다. 그러니까 저희가 연구를 하는 과제 중에 많은 부분은 사실상 기초자치단체나 경기도청에서 의뢰를 해서 하는 연구들이 꽤 있습니다. 그것은 수행하고 있는 연구, 하고자 하는 연구의 근거를 마련하기 위해서 저희들한테, 말하자면 액션플랜을 요구하는 것들이죠. 그러니까 그런 연구들은 대부분 도 정책에 반영되고 있다고 봐야 합니다. 그리고 저희들이 자체 발굴해서 이런 것들 꼭 하면 좋겠다고 해서 저희들이 정책연구과제를 수행했는데 그런 것은 도정에 반영되기도 하고 되지 않기도 하고……. 
</p>
<p><b>○ 김호겸 위원 </b> 각 과에서, 실국에서 요청되는 과제도 있으시잖아요? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 그렇습니다. 
</p>
<p><b>○ 김호겸 위원 </b> 그런 부분이 반드시 우리 정책이나 예산이 수반이 돼서 채택이 돼야 되지 않나 이런 말씀을 드리는데 특히 경기도의 현안, 주요 이슈가 되는 연구과제가 살펴볼 때 많이 있지 않은 것 같습니다. 특히 요즘에 경기도 산하기관이 현재 몇 개인지 기억하고 계시나요, 혹시? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 네, 경기도 산하기관이. 
</p>
<p><b>○ 김호겸 위원 </b> 산하기관이 몇 개로 파악되고 있으시죠, 지금? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 26개 정도. 
</p>
<p><b>○ 김호겸 위원 </b> 26개죠? 26개인데 현재 통폐합이 일부 추진되고 있는 사항을 알고 계시나요? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 그런 논의가 진행되고 있는 걸로 알고 있습니다. 
</p>
<p><b>○ 김호겸 위원 </b> 진행되고 있죠? 26개 기관이 21개 기관으로 통폐합되는 안이 지금 추진이 되고 있습니다. 그래서 중복 및 유사업무로 인해 가지고 업무의 비효율성이 클 것으로 판단이 돼서 통폐합을 하고 있는데 본 위원이 말씀드리고 싶은 것은 통폐합과 관련해서 우리 경기도, 경발연에서도 이와 같은 통폐합에 대해서도 충분히 검토를 해야 될 부분이 있고 또 예산의 절감부분이 어떤 부분이 있는 건지 이런 부분도 우리 연구원에서 연구물로 나와야 되지 않느냐 이런 말씀을 드리는 겁니다. 지금 파악을 하셨는지 모르겠습니다만 일부 산하기관이 일부 북부 쪽으로 이관된 내용을 알고 계신가요? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 네, 그렇습니다. 
</p>
<p><b>○ 김호겸 위원 </b> 지금 통폐합되는 부분을 먼저 하게 되면 경기관광공사, 경기복지재단이, 잠깐만요. 지금 일부 산하가 북부 이전도 검토되는 것도 알고 계시죠? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 네, 알고 있습니다. 
</p>
<p><b>○ 김호겸 위원 </b> 경기관광공사라든가 신용보증재단 또 경기복지재단, 농림진흥재단, 경기평생교육원, 교육진흥원 그다음에 경기도청소년수련원 등의 이전이 검토가 되고 있는데 이것들도 지금 본 위원이 볼 때는 경기관광공사나 경기복지재단은 지금 현재 이쪽으로 이전을 해 오지 않았습니까? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 여기 이 건물 내에 있습니다.
</p>
<p><b>○ 김호겸 위원 </b> 네, 건물 내에 이전을 해온 것 아닙니까, 많은, 수억을 들여서 이전을 했는데 또다시 북부 쪽으로 가게 되면 예산낭비 요인이 발생될 소지도 있고 또 신용보증재단은 북부 쪽보다는 남부 쪽에 업무가 상당히 많이 집중돼 있습니다, 아시다시피. 그래서 보증사업이 남부 쪽에 집중이 되어 있기 때문에 제대로 된 서비스가 안 될 것 같고 또 직원들도 상당한 어려움에 처해질 걸로 판단이 됩니다. 북부발전도 중요하지만 이런 무리한 추진은 결국 전시행정으로 이어질 부분도 있기 때문에 하여튼 통폐합과 관련해서 통폐합이 예상되는 부서 있죠? 경기가족연구원, 복지재단 그다음에 평생교육진흥원하고 경기도청소년수련원, 영어마을은 민간위탁 예정이고 경기문화재단, 경기문화의전당, 경기관광공사, 한국도자재단 이런 것들을 통폐합해서 추진되는 것도 있고 북부 이전계획이 있는데 이러한 부분들도 우리 경발원에서 좀 더 심도 있게 연구를 할 부분이 있다고 생각을 하는데 어떻게 생각하시죠? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 사실 그간에 논의가 많았는데 본격적으로 저희들이 그 부분에 대해서 연구를 못한 건 사실인 것 같습니다. 관심을 가지고 저희들이 시의적절하게 또 시기에 맞춰서 그렇게 연구를 하도록 하겠습니다. 
</p>
<p><b>○ 김호겸 위원 </b> 지금 시기적으로 적절한 때가 아닌가, 이런 부분들을 우리 경발원에서 좋은 안을 내놓아 주시기를 부탁의 말씀을 드리고요. 
</p>
<p style="padding-left:1.2em">  지금 31쪽에 보게 되면 이슈&진단 발간하고 GRI TIP 발간 책자가 있는데. 31쪽입니다, 업무보고서. 이 책을 하나 갖다 달라고 했는데 1부만 가져오셨어요. GRI TIP 발간 책자는 안 가져왔는데 현재 이게 어떻게 발간이 되고 있죠? 누가 답변할 수 있으면 답변을 누가 하시죠. 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 제가 간단히 말씀드리고 또 필요하시면 관계자한테 답변토록 그렇게 하겠습니다. 이슈&진단은 거의 격주로 발간되고 GRI TIP도 격주로 발간하고 있습니다. 
</p>
