</p>
<p><b>○ 경기개발연구원장 임해규 </b> 굉장히 오래 전부터 발간했습니다. 
</p>
<p><b>○ 김호겸 위원 </b> 지금 이슈&진단이라든가 그거는 각 사안별로 몇 부가 발간이 되고 있습니까? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 그거는 좀……. GRI TIP은 300부 발간하고 있습니다. 그리고 비매품이고요. 
