</p>
<p><b>○ 김호겸 위원 </b> 주 2회로 해 가지고, 2회로. 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 이게 원래는 주 1회를 했었습니다. 그런데 주 1회를 하는 게 너무 벅차서 주 2회 정도 하고 있고요. 
</p>
<p><b>○ 김호겸 위원 </b> 배부처는요? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 이슈&진단은 600부 배포하고 있습니다. 
</p>
<p><b>○ 김호겸 위원 </b> 배부처는 어디가 주로 해당이 되고 있죠? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 도청의 각 실국에 배포하고요. 그리고 31개 시군하고 도의원님들께도 배포하고 있습니다. 그리고 경기도에 지역구를 둔 국회의원들 그리고 국책연구원이나 도내 산하기관들도 하고 있습니다. 그리고 저희 경기도만이 아니라 17개 광역시, 도청하고 또 시도 연구원하고 유관기관들에도……. 
