<p><b>○ 경기개발연구원장 임해규 </b> 우편으로 하고 있습니다, 이슈&진단은. 
</p>
<p><b>○ 김호겸 위원 </b> 본 위원이 말씀드리는 것이 뭐냐 하면 우리 경기개발연구원의 홍보도 될 수 있습니다. 제가 아까 모두에 질의 때도 연구용역 31개 시군인가요? 31개 시군에서 전혀 의뢰조차 하지도 않은 시군들이 상당수가 있습니다. 그런 데가 상당수 있고, 하는 데도 있지만 전혀 우리에게 연구 1건도 의뢰 안 한 시군도 있습니다. 그래서 우리 경기발전의, 우리 연구원의 어떤 위상이라든가 홍보, 또 홍보 아울러서 우리 경기도의 주요 정책이라든가 주요 현안을 도민과 공유할 수 있는 부분이 아닌가 이런 생각을 하면서 이런 부분들도 좀 배부를 가능하면 늘려서 또 오피니언 리더뿐만 아니라 지역의 지도층 인사도 있죠? 지도층 인사들까지 좀 확대해서 배부를 하는 것이 좀 좋지 않을까 이런 생각을 하는데 어떻게 생각하시죠? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 저희들이 인쇄한 발간물을 적절하게 더 늘리는 것도 위원님 말씀대로 더 검토하겠습니다. 그런데 최근에는 모바일이나 이런 거를 통해서 워낙 많이들 보시기 때문에 저희들이 모바일을 통해서 하는……. 지금 말씀하신 이 발간물들은 전부 다 모바일을 통해서 다 공개가 되고 있습니다. 그래서 그것도 더 넓히기 위한 노력도 더 경주하겠습니다. 
</p>
<p><b>○ 김호겸 위원 </b> 하여튼 우리 경발연의 홍보와 아울러서 우리 도민과 주요 정책들 주요 현안문제들 함께 공유할 수 있는 이런 부분의 홍보에도 만전을 기해주길 부탁드리겠습니다. 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 네, 그렇게 하겠습니다. 
</p>
<p><b>○ 김호겸 위원 </b> 이상 마치겠습니다. 
</p>
<p><b>○ 위원장대리 임병택 </b> 박재순 위원님 질의해 주십시오. 
</p>
<p><b>○ 박재순 위원 </b> 수원 출신 박재순 위원입니다. 오전에 질의드렸던 의료관광사업이 각 지역의 의료원과 꼭 특화된 의료연구로써 잘 이루어져서 성공되기를 기대하면서 질의를 드리겠습니다. 
</p>
<p style="padding-left:1.2em">  연구원의 인력보충에 대한 계획은 갖고 있나요? 현재 결원을 보면 11명 정도 되는데 거기에 대한 계획이 있습니까? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 저희가 올해 들어서 3명이 또 퇴사를 했습니다. 그래서 우선 지금 현재 4명을 공개채용 모집공고를 내놓은 상태입니다. 그리고 북부분원과 관련해서 저희들이 또 한 네다섯 분, 예산 사정을 보아서 네다섯 분을 추가로 또 공개채용을 할 생각입니다. 그렇게 되면 지금 한 일곱, 여덟 분 정도 추가채용이 되게 되면 저희들이 정원으로 되어 있는 만큼은 아니라도 이렇게 좀 많이 충원을 할 수 있을 것으로 그렇게 생각하고 있습니다. 
</p>
<p><b>○ 박재순 위원 </b> 제가 오전에 질의드렸던 장애인 법정의무고용비율 2.3%로 상향돼서 있었는데 꼭 잘 보셔서 그때에도 우리 장애인들이 지원을 하면 참 좋겠다는 생각은 들지만 현실적으로 그렇게 될지 안 될지는 잘 모르겠습니다, 그렇죠? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 저도 이렇게 생각합니다. 사실 관공서가 장애인을 고용하라는 법정비율이 있는 이유는 같은 값이면 장애인을 쓰라는 취지가 아니라고 봅니다. 그 이상으로 배려를 해서 장애인이 여러 가지로 악조건 속에 있기 때문에 약간의 능력이 좀 못하더라도 함께하면서 기운을 북돋우고 또 사회적으로 함께하려고 하는 그런 배려의 차원에서 만든 제도라고 보기 때문에 장애인이 신청을 많이 할 수 있도록 그렇게 노력을 하고 또 신청을 하면 무엇보다도 전 우선기준을 적용해서 채용을 하도록 그렇게 노력하겠습니다. 
</p>
<p><b>○ 박재순 위원 </b> 아까 원장님께서 장애인의 능력이 좀 부족하더라는 말씀을 그렇게 하셨는데요. 그건 좀 잘못된 표현이 아닌가 싶고요. 그런 부분은 사실 개인, 사적으로나 할 수 있는 얘기라고 저는 생각을 하고 있습니다. 어쨌든 장애인도 우수한 인력이 많이 있다는 말씀을 드리고 싶고 그 우수한 인력이 우리 연구원에 와서 꼭 함께했으면 좋겠다는 말씀, 그래서 법정비율 이상으로 잘 되기를 기원하겠습니다. 그리고 연구에 있어서 사전심의로 용역발주 남발을 막아야 한다고 저는 생각을 합니다. 그래서 용역을 전담할 수 있는 제도적 장치는 있는지 있으면 말씀해 주시기 바랍니다. 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 다시 한 번……. 
</p>
<p><b>○ 박재순 위원 </b> 용역발주 남발을 막아야 되는 데 있어서 제도적인 장치가 있는지……. 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 그러니까 저희 연구원에서 다른 곳에 용역을 주는 경우를 말씀하시는 것이죠? 
</p>
<p><b>○ 박재순 위원 </b> 네. 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 사실 저희 연구원에서 용역을 주는 것은 주로 기술용역들이 주로입니다. 그러니까 용역 자체를, 전체 연구를 용역을 주는 경우는 사실 그렇게 많지 않습니다. 사실 그 점은 오늘도 여러 위원님들이 지적하셨는데 앞으로 그런 점에 대해서는 철저하게 필요한 경우에 주도록 그렇게 할 거고요. 그런 것은 우리가 내부에 연구위원회가 다 있어서 연구위원회에서 그 용역을 어떻게 할 건가 하는 심의를 다 하고 있습니다. 그리고 연구가 끝나면 다시 그 연구에 대해서 심사평가를 하고 이렇게 하는 절차와 제도가 다 있습니다. 그렇기 때문에 앞으로 필요 없는, 꼭 우리가 그렇게 하지 않아도 되는 것은 외부용역을 주지 않고 내부적으로 하도록 하고 부분위탁을 하는 경우에도 좀 더 연구위원회를 통해서 자격이 있는 그리고 충실히 잘 연구하는 곳에 부분위탁을 줄 수 있도록 그렇게 하겠습니다. 
</p>
<p><b>○ 박재순 위원 </b> 또한 정부출연기관과 연구기관이죠? 그래서 의견교환을 통해서 예산절감을 통한 전문성을 고취시킬 필요가 있다고 보는데 실제로 의견교환을 통하여 행해지는 예산절감이나 전문성 고취 사례 같은 게 있습니까?  
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 관련자가 좀 답변하면 어떻게……. 
</p>
<p><b>○ 박재순 위원 </b> 네, 그러니까 쉽게 말하면……. 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 사례를 한번 주시면 저희가……. 
</p>
<p><b>○ 박재순 위원 </b> 네? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 사례를 말씀해 주시면……. 
</p>
<p><b>○ 박재순 위원 </b> 한 예로 보면 정부기관에서도 많은 사례들을 연구하고 있는데 우리가 중복의 연구를 하게 된다는 거죠, 우리도 모르게. 그래서 사전에 정부기관에서, 경기도에서 연구를 한다 그러면 어떤 A라는 집단에 대해서 연구를 해 놨으면 그걸 우리가 갖다 쓰면 우리가 연구를 하지 않아도 되는데 그래서 서로가 정부기관과 어떤 커뮤니케이션이 될 수 있는 그런 역할을 하는지를 여쭤보고 있는 거예요. 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 그런데 저희가 우선은 기본적으로 2015년도의 연구과제를 책정하게 될 때 연구과제 의뢰를 도청이나 또는 도의회나 아니면 여러 관련기관들로부터 의뢰를 받습니다. ‘어떤 걸 연구 하면 좋겠습니까?’ 이렇게 받게 되고 그것을 거르기까지 굉장히 많은 숫자의 연구를 해 달라고 의뢰가 들어옵니다. 그러면 그중에 우리 역량에 맞게끔 100건이면 100건 정책과제를 선정하는 과정에 이런 연구는, 왜냐하면 여기 있는 박사님들이 다 해당 전문분야에 네트워크를 가지고 있고 전문가들이시기 때문에 이런 연구는 우리가 굳이 할 필요가 없다 해서 다 걸러내는 작업을 하고 있습니다. 그리고 특정한 연구를 하게 되면 그 연구에 참고해야 될 문헌들도 다 있기 때문에 그것이 중복되는지 또 연구의 방향이나 범위는 같더라도 그게 꼭 경기도에서 연구를 이미 했는지 이런 것들을 다 가리고 일차적으로 걸러내기 때문에 사실은 위원님이 생각하시는 것처럼 그런 이미 해 놓은 연구를 우리가 다시 하는 이런 케이스는 거의 발생하지 않는다고 보셔야 될 것 같습니다. 
</p>
<p><b>○ 박재순 위원 </b> 거기 부분에 대해서 잘 들었습니다. 또 우리가 연구원들이 53명으로 구성돼 있어요. 그죠? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 두 분이 최근에 퇴직을 해서 지금 51명입니다.
</p>
<p><b>○ 박재순 위원 </b> 51명입니까? 그래서 지금 1억대 연봉을 보니까 아까 여섯 분으로 나와 있었습니다. 여섯 분으로 나와 있는데 우리 1년 예산이 237억 원입니다. 그래서 시간이 흐르면서 연구라는 것은 생산을 유발하는 것이 아니고 어떤 판매로 인해서 돈이 얻어지는 것이 아니지 않습니까? 사실 출연기관 우리 도를 비롯한 시군 또 민간에서 출연을 해서 그 연구용역비를 주다 보니까 많이 일들이 벌어질 건데요. 연구원들에 대한 임금피크제에 대해서 생각을 해 보신 적이 있다면 한번 말씀해 주시기 바랍니다. 지금 현재 제가 보니까 최고 많이 받는 분이 1억 1,200만 원을 받고 있습니다. 그래서 임금피크제에 대해서 어떻게 생각하시는지 한번 여쭤보고 싶습니다.
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 우선 국책연구기관도 그렇고 또 저희 연구원도 연구직박사들의 경우에는 지금 연봉시스템을 적용하고 있습니다. 그런데 잘 아시다시피 아직은 연봉시스템이 완전히 정착돼 있지는 않습니다. 그래서 호봉제적인 그런 요소가 가미되어 있는 시스템입니다. 그래서 이 문제는 당장에 바꾸기는 어려움이 있다 하더라도 장기적으로 완전한 연봉시스템으로 전환하는 것이 추세라고 생각을 하고 있습니다. 그리고 그간에 진행해 오던 성과평가와 연봉ㆍ보수체계에 대해서는 저희들이 여러 가지 문제가 지금 제기되어서 그것을 어떻게 한번 개선해 볼까 하고 논의를 진행 중에 있어서 아마 내년도부터 바뀐, 우리가 연구를 해서 바꾸는 것을 통해서 내년부터 실시할 것으로 그렇게 지금 생각하고 있습니다. 
</p>
<p><b>○ 박재순 위원 </b> 원장님께서 그것을 결정할 때 우리 경기도에서 최고 연봉을 받는다 해도 1억이 넘는 사람이 거의 없을 거라고 제가 보고, 도지사님 빼놓고는. 될지 안 될지 모르겠지만 그런 상황이기 때문에 우리 집행부와도 형평성에 맞는 그런 연봉체계를 해 줬으면 좋겠다는 말씀을 드리고 또 우수한 인력일수록 사실 오랫동안 모셔야 되고 또 우리가 오랫동안 모심으로써 그분에게 많은 연구자료를 얻어야 되는데 사실 연봉이라는 것은 외국의 사례를 보면 협상에서 깨졌을 때 정말 좋은 사람을 놓쳐야 되고 그런 안타까운 현실이 많이 있고 앞으로도 또 볼 수 있습니다. 그래서 그런 부분에 대해서 사전에 잘 점검하셔서 우리 집행부에 준하는 수준보다는 좀 더 낫겠지만 박사급이니까 그래도 거기에 우리 본청에서 근무하시는 박사님들도 소외감을 느끼지 않을 정도로 거기 형평성에 대해서 고려를 해주십사 하는 부탁의 말씀을 드리고 싶고 거기에 대해서 말씀 있으면 해주시기 바랍니다. 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 그런데 위원님, 제가 양해 말씀드려야 되는 것은 사실 지금 지방자치단체들이 자체 출연연구기관을 가지면서 두뇌경쟁을 하고 있습니다. 그래서 우리 경기개발연구원이 예전에는 사실 서울연구원보다도 임금수준이 매우 낮아서 우리가 연구원의 지속가능성이나 연구인력들을 계속 유지하는 데 굉장한 어려움을  겪었습니다. 그런데 한 몇 년 전부터 비로소 서울연구원 수준의 지금 연봉시스템을 이제 갖추어서 조직이 그래도 새로운 연구인력들을 받아들이는 여건을 이제 비로소 갖추었다고 생각합니다. 아마 일전의 신문보도 보셨으면 인천연구원이 굉장히 많은 연구원들이 다 빠져나가서 역량이 축적되지 않고 굉장히 어려움을 겪는다고 들었습니다. 그래서 연구원장들 간에 만나면 이제 경기연구원이 경기도의 위상에 맞게 비로소 연구원의 시스템을 갖춘 걸로 평가를 받고 있는데 그것을 공무원들이 받는 급여하고 비교하는 것은 적절하지 않다고 생각합니다. 우리가 국책연구기관이나 아니면 다른 도책 연구기관, 시ㆍ도책 연구기관들하고 견주어서 저희들이 여러 가지 연구원의 처우를 생각을 해야지 저희들이 안정된 연구기반을 확보할 수 있지 않나 생각합니다. 양해해 주시기 바랍니다. 
</p>
<p><b>○ 박재순 위원 </b> 잘 들었습니다. 저는 연구비를 꼭 깎아서 그분을 우리 본청하고 구별했다고 생각지는 않습니다. 사람이 꼭 필요한 사람이면 1억이 아니라 10억을 주고라도 모셔 와서 정말 좋은, 훌륭한 연구논문을 가지고 우리 1,250만이 먹고 살 수 있는 그런 인프라가 구성되면 그것처럼 좋은 게 어디 있겠습니까, 이 세상을 살면서, 그죠?  그래서 원장님한테 말씀드리는 것은 꼭 핵심이 있다면 정말 많은 돈을 주고라도 꼭 써야 되지만 그렇지 않은 인력이 있다고 봅니다. 그래서 그런 부분들은 원장님 계시는 동안 충분히 형평성이나 그런 것을 고려해서 잘 해주십사 하는 부탁의 말씀을 드리면서 추후에 다시 질문드리도록 하겠습니다. 이상입니다.
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 네, 알겠습니다. 
</p>
<p style="padding-left:2.4em">    (임병택 위원장대리, 배수문 위원장과 사회교대)
</p>
<p><b>○ 위원장 배수문 </b> 박재순 위원 수고하셨습니다. 최지용 위원 질의하여 주시기 바랍니다.
</p>
<p><b>○ 최지용 위원 </b> 장시간 동안 우리 원장님 수감하시느라 수고 많으십니다. 화성 출신의 최지용 위원입니다. 우리 연구원에서 광역장사시설에 대한 용역을 하셨네요. 장사시설이 절대적으로 부족하다는 것은 우리 도민이나 전 국민이 공감하는 부분인데 다만 화장장에 대한 장사시설이 혐오시설로 인식이 되고 분류됨에 따라서 선뜻 다가가기는 쉽지 않은 시설입니다, 사실. 그러다 보니까 수용하기까지는 많은 갈등과 반목이 반복되다 보니까 어려움을 겪을 수밖에 없습니다. 그래서 우리 연구원에서 연구를 했다는 부분이 어떠한 부분을 연구를 하셨는지, 여기 자료 보면 시민의식조사 실시라고 돼 있는데 그 부분에 대해서 구체적으로 말씀을 해주시면 고맙겠습니다. 10개 시군 지자체에서 공동으로 화성시에 이게 유치가 돼 있어요, 저희 지역에. 그래서 관심이 있어서 이 부분에 대해서 한번 묻습니다. 답변해 주시고 또 직접 연구하신 분인 박사님께서 답변을 해주시면 감사하겠습니다.
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 일단, 아마 지난 집행부 시절에 하남에서도 광역장사시설을 추진하려고 했는데 자치단체 간 또는 주민들의 반대로 그것이 진행이 안 된 사례가 있는 것으로 알고 있습니다. 지금 화성에서 또 추진을 하고 있는데 함께 하기로  한 시군들에서 적극적으로 하지 않아서 상당히 난관에 봉착해 있는 것으로 그렇게 알고 있습니다. 그런데 이것은 장사시설의 필요성과 그것이 좀 더 안전하고 쾌적하게 하는 문제뿐만 아니라 또 그것을 각 시군이 공동으로 이용하는 데 따르는 문제 그리고 더 나아가서 지역주민의 기피시설에 대한 갈등을 조정하는 문제 이렇게 복합적으로 되어 있기 때문에 저 개인 자신으로는 이게 기초자치단체 수준에서 할 수 있는 문제가 아니라고 생각합니다. 이런 문제야말로 광역차원에서, 왜냐하면 시설을 모든 시군에 다 할 수도 없고 또 하기도 어렵기 때문에 결국 광역적 시설로 가는 것은 불가피하다고 생각이 됩니다. 그런 차원에서 우리가 장사시설에 대한 국민적인 시민들의 의식을 바꾸는 문제들을 포함해서 또 적절한 입지를 고려하는 문제 또 거기에 각 시군과 경기도가 함께 협력해서 이것을 만들어내는 문제, 이런 제반의 것들은 역시 광역주도로 할 수밖에 없다고 보고 또 도도 그런 방향에서 이 사업을 진행하고 있는 것으로 알고 있습니다. 그래서 그런 방향에서 경기도가 좀 더 적극적으로 이 문제를 대응해야 된다 이렇게 보고 있습니다. 그리고 관련된 연구를 한 분은 우리 연구 박사님께서 보충답변을 하도록 하겠습니다. 
</p>
<p><b>○ 기획조정본부장 이양주 </b> 기획조정본부장 이양주입니다. 지금은 김희연 박사가 주로 담당을 하는데 그 이전에는 제가 담당을 했기 때문에 스토리를 좀 알고 있습니다. 김문수 지사님 오시기 이전에는 원래 각 시군 차원에서 각자 장사시설을 지었습니다, 왜냐하면 화장이 급격하게 증가해 가지고. 지사님 오시고 난 뒤에는 이걸 광역차원에서 해야 되겠다 해서 초기에는 동북부지역에 가평 등에 유치하는 것으로 했고 님비가 워낙 심해서 사실 그때 당시에 지사님께서는 100억을 주겠다는 상금까지도 걸었음에도 불구하고 주민과의 협상과정에서 다소 아마 정보 비대칭 문제가 있어서 반대에 부딪혔고 그 이후에 포천에서도 자기들이 한번 해 보겠다고 했고 실제 클라이맥스는 하남시에서 일이 벌어졌습니다. 원래 서울과 같이 하기로 했었는데 서울에서는 안 하기로 해서 규모를 줄이는 문제, 그러면서 사업성 문제 또 이게 선거와 맞물리면서 실제 그걸 반대하신 분은 국회의원으로 당선이 되고 또 그걸 반대하신 지사님께서는 여러 가지 어려움을 겪고 이런 일이 있었는데, 최근에는 또 화성에서 비슷한 문제가 터졌는데 각 시군에서 반대하는 입장이 있었는데요. 사실 장사시설과 관련해서는 광역으로 하는 것이 낫다 하시는 분들도 계시고요. 조그맣게 마을단위로 하는 게 더 낫다 하시는 분도 있습니다. 
</p>
<p><b>○ 최지용 위원 </b> 이게 어차피 10개 시에서 공동으로 하자고 하면 이미 이건 광역화 돼 있는 거 아닙니까? 
</p>
<p><b>○ 기획조정본부장 이양주 </b> 맞습니다. 
</p>
<p><b>○ 최지용 위원 </b> 광역으로 하는 게 맞다라는 이야기보다는 이미 광역화가 돼 있기 때문에 각 지자체별로 분담금을 정해서 토지 제공하는 화성시 같은 경우 또 나머지 시설이나 제반 기반시설 부분은, 예산에 대한 것은 각 지자체별로 얼마씩 분담을 해서 하기로 이미 합의가 봐져 있고 위치까지 지정이 돼 있습니다. 그런데 일부 지자체에서 반대를 하는 목소리는 얘기를 듣기는 했습니다만 그 정도로 반대해서 도에서 이미 손을 댄다고 하면, 광역화 돼 있는 것을 도에서 하는 것을 광역화로 생각하고 손을 댄다고 하면 도에서 어느 정도 지원이 가능한가요? 연구원에서…….
</p>
<p><b>○ 기획조정본부장 이양주 </b> 사실 도의 지원문제보다는 제 생각에는 중재의 문제가 제일 큰 것 같습니다. 첫 번째는 갈등조정의 기능에 대한 것들이 현재 법적 법률이 아니라 규정으로 지금 돼 있는 것도 문제이고요. 두 번째는 그런 갈등이 생겼을 때 중재기관의 역할이 상당히 중요합니다. 그것은 중재위원회 같은 것도 가능하지만 미국처럼 전문기관이 중재기관으로서의 법적 지위를 가질 수도 있고 또는 우리 국내 제천사례처럼 주민의 투표에 의해서 할 수도 있는 세 가지 기능이 있는데 제가 볼 때 화성 같은 경우는 우리 같은 어떤 전문기관이 만약에 중재기관으로서 법적 기관을 가진다면 합리적으로 할 수 있을 텐데 그게 안 되는 게 저희들은 아쉽습니다. 
</p>
<p><b>○ 최지용 위원 </b> 이미 지자체별로 합의하에 추진이 돼 있는 상황인데 큰 문제는 없을 거로 보는데요. 다만 절차나 각 지자체에서 부담하는 비율, 부담액 이것이 문제가 늦춰질 수는 있겠죠. 하남문제 같은 경우는 광역장사시설하면 예를 들어서 그때 당시에 5,000억을 도에서 지원해 주겠다, 이렇게 해서 시장하고 지방의원들 주민소환에 끌려 나가서 그만둔 사례도 있었습니다마는. 
</p>
<p><b>○ 기획조정본부장 이양주 </b> 맞습니다.
</p>
<p><b>○ 최지용 위원 </b> 이것은 1개 지자체, 일선 지자체에서 하는 게 아니라 10개 지자체에서 합의하에 이루어지는 부분을 원활하게 돌아갈 수 있지 않을까요? 
</p>
<p><b>○ 기획조정본부장 이양주 </b> 저도 그게 위원님 지적처럼 왜 깨졌는지 참 의문스럽기도 합니다. 
</p>
<p><b>○ 최지용 위원 </b> 여기서 시민의식조사도 실시하셨다고 그랬는데 시민의식은 장사시설이 아까 얘기한 것처럼 혐오시설로 분류되기 때문에 그런 거부반응이나 또 누구나가 절대적으로 장사시설이 부족한 것은 다 공감하는 부분이기 때문에 이것 추진하는 데서 협조가 이루어지면 큰 문제가 없을 것 같다는 생각이 들어요. 
</p>
<p><b>○ 기획조정본부장 이양주 </b> 저도 생각이 같습니다. 
</p>
<p><b>○ 최지용 위원 </b> 제 지역구에 있는 장사시설은 오히려 큰 거부가 없습니다. 
</p>
<p><b>○ 기획조정본부장 이양주 </b> 어떤 데는 유치한다고 하기도 합니다. 
</p>
<p><b>○ 최지용 위원 </b> 들어가셔도 좋습니다. 제 질의를 여기서 마치겠습니다. 
</p>
<p><b>○ 위원장 배수문 </b> 최지용 위원 수고하셨습니다. 한 가지 질의해 보도록 하겠습니다. 지난 2013년도 행정사무감사 처리요구사항 중에 학회지 등록된 것이 한국연구재단으로부터 올해 학술지 등재 확정통보를 공문으로 받은 걸로 돼 있네요. 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 다시 한 번 말씀해 주십시오. 
</p>
<p><b>○ 위원장 배수문 </b> 2013년도 행정사무감사 처리요구사항 중에 다섯 번째 답변이에요. 한국연구재단으로부터 경발연에서 연구논총 원고관리를, 학술지 등재 확정통보를 공문으로 받은 걸로 돼 있죠? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 네. 
</p>
<p><b>○ 위원장 배수문 </b> 이렇게 되면 경발연에서 발표하는 논문들이 다 학술지에 등록되는 건 아니죠?
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 등록돼 있는 등재학술지가 되기 때문에 그것에 실리는 연구물이 일정한 권위를 갖게 되는 것이죠. 
</p>
<p><b>○ 위원장 배수문 </b> 그러면 지금 2014년도 2월 17일 이후에 경발연에서 연구자료로 발표된 것들은 한국연구재단으로부터 다 학술지 등재가 되는 걸로 자동 되는 건가요? ○ 경기개발연구원장 임해규  그렇습니다. 학술지로 등록된 것은, 학술진흥재단에 등재된 것은 GRI 연구논총입니다.
</p>
<p><b>○ 위원장 배수문 </b> 논총만?
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 네, 연구논총. 
</p>
<p><b>○ 위원장 배수문 </b> 그러면 그 외에 또 다른 외부로부터 GRI에서 발표한 논문자료들이 인정을 받을 만한 다른 방법은 도입될 만한 게 있습니까? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 보통은 그것에 실리는 것들이 저희 연구물 중에 기본연구과제의 성격을 띠는 것은 충분히 실릴 수 있을 정도의 질이 있다고 저희들은 생각이 듭니다. 그럴 경우에는 그것을 학술지에 연구논총에 실으면 그것이 자연스럽게 될 테지만 그렇지 않은 경우는 다른 학진 등재학술지에 또 학술 기고를 해야 되는 것입니다. 
</p>
<p><b>○ 위원장 배수문 </b> 그러면 연구논총으로 해서 학술지에 등록된 효과를 낸 제목만 해서 목록을 제출해 주시기 바랍니다.
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 네, 그렇게 하겠습니다. 
</p>
<p><b>○ 위원장 배수문 </b> 이제 위원님들의 1차 추가질문도 모두 끝났습니다. 잠시 휴식을 갖고 이후 감사일정에 대해서 의견을 조율코자 합니다. 감사중지에 이의 있습니까?
</p>
<p style="padding-left:2.4em">    (「없습니다.」하는 위원 있음)
</p>
<p style="padding-left:1.2em">  그러면 의견조율을 위해서 잠시 감사를 중지하도록 하겠습니다. 
</p>
<p class=''ar''>(16시15분 감사중지)
</p>
<p class=''ar''>(16시29분 감사계속)
</p>
<p><b>○ 위원장 배수문 </b> 좌석을 정돈해 주시기 바랍니다. 감사를 계속하겠습니다. 
</p>
<p style="padding-left:1.2em">  효율적인 감사를 위해 추가질의를 진행하기로 했습니다. 추가질의 시간은 5분으로 하기로 했고 또 원하시면 추가질의 기회를 더 드리도록 그렇게 하겠습니다. 그럼 먼저 안혜영 위원님 질의하여 주시기 바랍니다.
</p>
<p><b>○ 안혜영 위원 </b> 장시간 원장님 고생하고 계십니다. 쉬다 오니까 정리를 해야 되는데 우선 먼저 저희 이사회를 할 때 대리출석이 가능한가요? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 아마 대리출석 하는 경우는 행정부에서 감사…….
</p>
<p><b>○ 안혜영 위원 </b> 저희 이사회에서 어느 대상이 됐든 행정부라고 하더라도 예외는 아닐 거 아니겠습니까? 거기에 당연직이사든 아니면 이사회분들 중에 이사회를 할 때 대리 건을 인정하느냐는 말씀입니다. 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 대리로 오더라도 서면으로 심사하는 경우가 아니라면 아마 참관형식이 될 것으로 생각이 됩니다. 
</p>
<p><b>○ 안혜영 위원 </b> 참관이 아니라 답변도 하시고 하시던데요? 회의록에 대리출석을 하셨는데 회의록에 기재가 다 되어 있어서 질의를 하는 겁니다. 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 이거는 민법에 준용해서인데요. 민법에 보면 이사의 대리인 선임에 있어서 이사는 정관 또는 총회의 결의로 금지하지 아니한 사항에 한해서 타인으로 하여금 특정한 행위를 대리하게 할 수 있다고 되어 있네요. 
</p>
<p><b>○ 안혜영 위원 </b> 그런데 그 안에 보면 저희 이사회에 특별한 내용이 담아있지 않아서 민법에 대한 이 서류를 저한테도 주셨거든요. 자료를 주셨는데 명확하지 않은 거죠. 저희 이사회의 정관에 담아있지 않았기 때문에 명확하지가 않은데 그 안에 보면 의결권 같은 것이 다 있어요, 그렇죠? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 네. 
</p>
<p><b>○ 안혜영 위원 </b> 그냥 일반적인 회의를 하는 것이 아니라 의결권도 있고 예결에 관련된 것도 있기 때문에 그런 것들은 좀 기준을 잡을 필요가 있겠다고 생각을 하는데 어떻게 생각하세요? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 타당한 지적이라고 생각합니다. 그러니까 저희들 1년 살림살이 중에 예산과 관련된 거라든지 이렇게 중요한 사항을 논의할 때는 대리를 하지 못 하도록 정관에 기재할 수 있다고 생각합니다. 
</p>
<p><b>○ 안혜영 위원 </b> 네, 그거를 지금 즉답을 하지 마시고요. 좀 면밀히 검토를 하셔서 이사회를 해야 되는 건들이 다 있을 테니까 그런 것들을 면밀히 검토하셔서 그런 추가할 수 있는 요인을 좀 담으셨으면 좋겠습니다. 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 네. 
</p>
<p><b>○ 안혜영 위원 </b> 그리고 저희 이사장님이 있으시죠? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 네. 
</p>
<p><b>○ 안혜영 위원 </b> 기관운영업무추진비를 좀 훑어봤습니다. 이사장님이 하는 역할이 뭐죠? 간단하게. 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 일단은 상임이 아니시기 때문에요. 회의를 주재하는 게 이사장의 역할로 보시면 될 것 같습니다.  
</p>
<p><b>○ 안혜영 위원 </b> 회의를 주관한다 그러면 어떤 회의를 하시나요? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 이사회 회의죠. 
</p>
<p><b>○ 안혜영 위원 </b> 이사회 회의를 매번 오셔서 주관하시나요? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 그렇습니다. 
</p>
<p><b>○ 안혜영 위원 </b> 그럼 보통 한 달에 몇 번 정도 되나요? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 이사회 회의는 2013년의 경우는 3회 정도 한 걸로 알고 있습니다. 
</p>
<p><b>○ 안혜영 위원 </b> 그리고 2014년도는? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 2014년도는 2회를 한 걸로 알고 있습니다. 
</p>
<p><b>○ 안혜영 위원 </b> 그러면 2년 동안 다섯 번만 이사장님은 나오시면 되나요? 그 외에 경발연……. 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 그 외에는 특별히 나오시지 않습니다. 
</p>
<p><b>○ 안혜영 위원 </b> 그러면 경발연에서 하는 역할은 이사장님은 회의진행만 하신다? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 그렇습니다. 회의를……. 
</p>
<p><b>○ 안혜영 위원 </b> 그런데 회의진행은 GRI에 대해서 상세하게 좀 아시고 진행과정에 대해서도 좀 알고 현재 어떤 식으로 진행되고 있는지 알아야 회의진행을 할 수 있는 것 아닌가요? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 물론 이사장님께 회의안건이나 주요한 안건에 대해서는 저희들이 사전에 다 방문해서 보고드리고 또 의견을 다……. 
</p>
<p><b>○ 안혜영 위원 </b> 아, 방문해서 보고를 드려요? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 네, 방문해서 보고를 드리고 또 유선으로도 주요한 사항에 대해서는 원장하고 협의도……. 
</p>
<p><b>○ 안혜영 위원 </b> 원래 기존에 그렇게 하나요? 이사장님한테는 이사장님이 오시는 게 아니라 경발연에서 이사장님을 뵈러 가나요? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> GRI의 이사장이 원래는 도지사였습니다. 그런데, 따라서 비상임이고……. 
</p>
<p><b>○ 안혜영 위원 </b> 본 위원이 생각할 때는 조금 이해가 가지 않는 게 전에 문화체육관광위원회에, 같을 수는 없겠지만 거기에도 이사장님이 있어요. 문화의전당에도 있고 문화재단 강우현 이사장님도 이사장님이셨죠, 한국도자재단에? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 네. 
</p>
<p><b>○ 안혜영 위원 </b> 그런데 일주일에 한 번 정도씩 다 참여를 하시고 회의도 참여를 하시고 산하기관이 어떻게 돌아가는지에 대한 것들을 소통을 다 하세요. 물론 관여하고 간섭하는 개념은 아니시겠지만 그런 역할을, 이사장님이 우리 기관에 필요한 역할을 하기 위해서 있는 거라고 생각을 하는데 단지 회의 진행하기 위한, 다섯 번이다? 그런데 업무추진비가 100만 원씩 2013년도에 나가다가 올해 80만 원으로 줄었습니다. 그런데 보면, 제가 2년 치만 받아 봤어요. 3월 달부터 계셨는데, 2년 치만 받아 봤는데 한 번도 영수증이 수원이나 경기도에서 끊어진 적이 없어요. 다 서울에서 영수증 처리를 하셨습니다. 그건 모든 미팅이나 만남을 다 서울에서 하셨다는 얘기죠. 경기도에 발을 디디지 않으셨어요. 물론 그 외에 당신께서 영수처리하지 않은 그런 모임이나 이사회나 이런 것도 있었겠지만 본 위원이 생각할 때는 이해가 되지 않는 거예요. 
</p>
<p style="padding-left:1.2em">  그리고 그 참석 대상자들을 면밀히는 아니지만 대충 자료를 훑어봤습니다. 제가 어제 이거 밤 11시에 자료를 받아봤거든요. 늦게까지 자료를 준비해 주셔서 우리 직원분들께 너무 감사드리는데 자료를 쭉 밤새 훑어보니까 대상도 경기도 관계하시는 분들이 거의 없어요. 대학교분들하고 되게 많이 만나셨거든요, 교수님들하고. 그런데 경기도 산하에 있는 대학교 교수님들하고 만난 적이 없어요. 다 무슨 서울대, 무슨……. 다 서울에 있는 대학교예요. 그러면 이분이 과연 경기도를 위해서 어떤 역할을 하실 수 있는지 의문이 가지 않을 수 없습니다. 그래서 이 부분에 대해서도 좀 이사장님을, 앞으로도 마찬가지지만 지금 이사장님이 현존해 계시잖아요? 2년 동안 활동하셨던 분이 그대로 계시거든요. 그분의 역할을 좀 더 중요한 역할을 하실 수 있는 그런 분위기를 만들어야 되지 않을까. 그리고 다음번에 어떤 이사장님이 오실지는 모르겠지만 그런 역할을 좀 분명하게 하고 이사장님을 모셔야 되지 않을까. 그래야 발전된 경발연이 되지 않겠습니까? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 타당한 지적이라고 생각합니다. 
</p>
<p><b>○ 안혜영 위원 </b> 그렇게 생각을 하고요. 해도 되나요? 
</p>
<p><b>○ 위원장 배수문 </b> 네. 
</p>
<p><b>○ 안혜영 위원 </b> 간단하게, 위원장님께서 OK하셨기 때문에. 그런 부분과 함께 여러 가지, 전임 원장님께서 좀 무리가 있는지 모르겠지만 파격적인 승진을 많이 시켰다는 여론이 좀 있습니다. 그러니까 10년을 거쳐야만 승진할 수 있거나 그럴 수 있는데 10년이 안 된 그런 연구원들도 승진시키거나 이런 사례들이 좀 있는 거예요. 그리고 특별한 부서에 있는 직원들을 정식직원이라든가 아니면 비정규직 직원들을 조금 더 나은 직책으로 전환시켜 주시는데 그러한 데서 조금 특혜성이 있었다, 그런 지적이 있었습니다. 그렇기 때문에 원장님께서는 그러한 부분에 대해서 면밀히, 이제 오신지 얼마 안 되셨으니. 상담을 많이 하셨다고 들었습니다, 직원분들하고. 그런 애로사항을 좀 더 면밀히 들으시고 그리고 아까 존경하는 임병택 간사님께서도 지적을 하셨던 김 모 박사님에 대한 좋지 않은 여론들이 아주 많았죠. 경발연 안에서 뿐만이 아니라 외부에서도 그분에 대한 지적이 아주 많았습니다. 지금 이곳에 안 계시죠? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 네. 
</p>
<p><b>○ 안혜영 위원 </b> 경기도에 그럼 파견 나가셨나요? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 그렇습니다. 
</p>
<p><b>○ 안혜영 위원 </b> 혹시 혼자 나가셨나요, 아니면 다른 분들하고 같이 나가셨나요? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 두 분의 박사님과 함께 나갔습니다. 
</p>
<p><b>○ 안혜영 위원 </b> 원래 지금 파견을 산하기관에서 받는데 다 그렇게 한 분이 아닌 여러 분을 파견 받으셨나요, 도에서? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 제가 알기로는 특정한 사업을 위해서 몇 분이 파견나간 사례가 있는 것으로 알고 있습니다. 
</p>
<p><b>○ 안혜영 위원 </b> 그리고 그분이 여러 역할들을 하셨어요. 아까도 우리 자문단에, 아까 다른 분 바꿔야 된다는 간사님 이전에 그분이 간사를 하셨죠? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 그렇습니다. 
</p>
<p><b>○ 안혜영 위원 </b> 그분이 여러 위원회에 걸쳐서 역할을 하셨죠? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 네. 
</p>
<p><b>○ 안혜영 위원 </b> 그분의 전공이 뭡니까? 전문분야가 있을 것 아니에요, 연구하시면. 선임연구원이시죠? 센터장도 하시고. 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 경제학으로 알고 있습니다. 
</p>
<p><b>○ 안혜영 위원 </b> 경제학이신데 얼마나 뛰어나신 지는 제가 모르겠으나 따복공동체에도 좀 역할을 하셨던 것으로 알고 있고 그리고 교통문제, 굿모닝버스인가 그쪽에도 역할을 하셨던 걸로 알고 있고 그런데 이번에 굿모닝추진단에서 우리 경발연에서는 TF를 구성하셨죠? 모르시나요? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 우리 GRI에서 TF를 만든 건 아닙니다. 
</p>
<p><b>○ 안혜영 위원 </b> GRI에서 TF를 구성하지 않았나요? 굿모닝버스추진단은 도에서 했지만 TF운영계획을 갖고 있어서 굿모닝버스에 관련된 TF 구성을 운영하고 있다고 저는 자료를 받았는데요. 아닌가요? 경발연 굿모닝버스 TF 운영계획 8월 8일 자입니다. 모르시나요? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 잠깐 답변토록……. 
</p>
<p><b>○ 안혜영 위원 </b> 알고 계시나요? 
</p>
<p><b>○ 휴먼교통연구실장 류시균 </b> 안녕하십니까? 휴먼교통연구실장 류시균입니다. 굿모닝버스 TF는 당초 국토부가 좌석제 입석금지, 고속도로를 운행하는 광역버스의 입석금지를 시행한다고 발표를 했을 때요. 그거에 대한 대책을 만들기 위해서 TF를 만들었고요. 
</p>
<p><b>○ 안혜영 위원 </b> 지금은 운영하고 있나요? 
</p>
<p><b>○ 휴먼교통연구실장 류시균 </b> 지금 사라지지는, 공식적으로 해체는 안 됐습니다. 
</p>
<p><b>○ 안혜영 위원 </b> 여기 TF 구성체계에서 보면 교통연구실 관련 박사들이 참여, 이렇게 되어 있는데 괄호치고 (조직도에 없이 운영)이라고 되어 있습니다. 또 이게 두 파트로 되어 있어요, GRI하고 경기도하고. 그런데 경기도에서는 특별보좌관 총괄하에, 보좌관이 총괄을 합니다, 집행부가 아니라. 대중교통과 직원들이 참여하게 되었는데 이것도 괄호치고 (조직도에 없이 운영)이라고 되어 있습니다. 제가 이 질문을 하는 이유 중에 하나는, 지금 이 조직이 있다는 말씀이신 거죠? 
</p>
<p><b>○ 휴먼교통연구실장 류시균 </b> 조직도에 없다라는 의미는 저희 연구원의 직제상 조직도에 TF를 안 만든다는 겁니다. 
</p>
<p><b>○ 안혜영 위원 </b> 그러니까 조직도에 없는 거지 TF는 있다는 거죠? 
</p>
<p><b>○ 휴먼교통연구실장 류시균 </b> 네, 그렇습니다. 
</p>
<p><b>○ 안혜영 위원 </b> 네, 원장님 발언대에 서주시고요. 그런데 여기에도 GRI, 아까 제가 말씀드린 것처럼 경기도에서 특별보좌관이 이 총괄을 맡고 있습니다. 두 파트로 되어 있는데 GRI에서는 김 모 박사님, 정책연구센터장이라고 되어 있어요. 이분이 경발연을 대표해서 책임을 맡고 있어요. 그런데 그 산하에 밑에 류 모 실장님도 계시고 박사님이 세 분이 계십니다. 제가 이분들에 대한 연구실적을 다 훑어보니까 나머지 실장님을 비롯해서 세 박사님들은 다 교통 관련된 그런 연구실적을 다 갖고 계세요. 그런데 김 모 박사님만 교통에 관련된 연구실적이 없어요. 아까도 지적했던, 제가 이거 건수 다 세서 지적을 했는데 그간의 연구실적은 4건밖에 없습니다, 4년 동안. 2011년도에 2건, 12년도에 1건도 없나? 그리고 그 다음에 1건, 그 다음에 1건. 나머지 2014년도 올해 1건도 아까 임병택 간사님이 지적했던 다른 연구실적을 갖다가 이름만 올려놓은 것 같은, 그러한 거예요. 그런데 지금 이분이 교통, 이 굿모닝버스도 남 지사님의 대업 중에 하나시죠?  
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 그렇습니다. 
</p>
<p><b>○ 안혜영 위원 </b> 그런데 거기에 전혀 지식이 없는 분이 센터장으로 책임을 맡고 경발연의 대표로 가 계세요. 어떻게 생각하시나요? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 그것은 이제……. 
</p>
<p><b>○ 안혜영 위원 </b> 그런데 이분의 능력이 출중하신가 봐요. 안 들어가 계신 데가 없네요? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 그런데 그간에는 역할이었다고 생각이 듭니다, 제가 보기에는. 그러니까 연구실적이 정책연구과제에 책임연구원을 한 실적이 없다는 뜻인데요. 왜냐하면 전략연구센터를 계속 맡아왔고 또 한 해에는 연구년을 가 있었기 때문에 그런 연구실적은 없는 것으로 봐야 하고요. 
</p>
<p><b>○ 안혜영 위원 </b> 이 전략연구센터의 운영실적을 보면 지금 말씀하시는 거에, 김 모 박사님이 3년 전에는 그래도 연구실적이 몇 개 있어요. 그런데 작년이랑 올해 연구실적을 보면 거의 전무합니다. 1∼2개 이 정도밖에 없으세요. 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 그러니까 전략연구센터의 역할 자체가 현안 중심의 과제를 하도록 기구설치를 했기 때문에 없는 것이죠. 
</p>
<p><b>○ 안혜영 위원 </b> 아니, 전략연구센터에 있는 운영실적을 얘기하는 거예요, 제가 지금 말씀드리는 거는. 그러면 공식적으로, 아까 제가 지적했던 그 연구실적이 아닌 이 전략연구센터에서의 역할은 있었어야죠. 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 그러니까 전략연구센터 내에서도……. 
</p>
<p><b>○ 안혜영 위원 </b> 이 센터에서도 다른 분들은 다 연구실적이 있는데 이 분은 거의 없으세요. 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 그러니까 전략연구센터장이기 때문에 관리를 하는 입장이니까 그렇다고 봐야 합니다. 
</p>
<p><b>○ 안혜영 위원 </b> 그러게요. 관리만 하시면 되는 건지. 그렇다면 연구원의 직책이 아닌, GRI의 직원이 아닌 다른 역할을 하셔야 되는 것 아니에요? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 위원님! 그런데 부서장을 맡게 되면 보통 연구에는 상당히 부담을 덜어주거든요. 
</p>
<p><b>○ 안혜영 위원 </b> 조금 아까 특별하게 파격적인 승진이 있었다 이런 거에도 이분에 대한 거론이 빠지지 않아요. 이분도 승진 케이스가 아닌 다른 분들보다 훨씬 더 연차가 늦어지고 있는, 물론 그 기간에 따라서 승진을 해야 된다고 생각하지 않습니다. 물론 업적이나 연구실적이 중요하죠. 그런데 그런 기본 틀도 있어야 된다고 생각을 하는 거죠. 거기에서 동료, 선ㆍ후배 직원분들의 공감대가 형성돼야 된다고 보거든요. 그런 부분을 원장님도 인사청문회 하실 때도 이 부분에 대해서 아주 강하게 지적받으셨죠? 우려 섞인 목소리도 많이 들으셨잖아요? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 그렇습니다. 
</p>
<p><b>○ 안혜영 위원 </b> 그 부분에 대해서 원장님의 역할이 아주 크다고 봅니다. 아까 임병택 위원님께서 지적하셨듯이 그 부분에 대한 대처 그리고 사후처리에 대해서 좀 더 고민을 하셔야 될 것 같습니다. 
</p>
<p style="padding-left:1.2em">  이상으로 마치겠습니다. 예산에 대한 부분들은 아까 우리 위원님들께서 지적을 해 주셨는데 제가 이사회 검토를 해보니 이사회에 여러 가지 좋은 방안들이 많이 나왔었거든요. 외부의 기업에서도 연구에 대한 지원을 받았으면 좋겠다든가 이런 여러 가지가 있었으니까 그런 것들을 검토해서 좀 좋은 방향으로 제안을 해주시면 좋겠습니다. 
</p>
<p style="padding-left:1.2em">  수고 많으셨습니다. 이상입니다. 
</p>
<p><b>○ 위원장 배수문 </b> 안혜영 위원님 수고하셨습니다. 박재순 위원 질의하여 주시기 바랍니다. 
</p>
<p><b>○ 박재순 위원 </b> 수원 출신 박재순입니다. 장시간 서 있는데요. 정말 죄송하고 감사하다는 말씀드리면서 질의를 또 시작하도록 하겠습니다. 현재 연구원 되시는 분들께서 대학출강을 나가시는데 대충 연구원 대비 몇 % 정도 나가고 있고 또 연구원의 외부강의에 있어서 어떤 기준이 서 있나요? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 우선 연구원이 강연을 나가는 경우와 강의를 나가는 경우인데요. 그런데 위원님도 느끼시겠지만 사실 강연을 나가는 것은 기고를 한다거나 하는 것과 마찬가지로 연구원의 위상을 높이고 또 연구성과를 알리는 굉장히 주요한 수단입니다. 그래서 그것은 권장하고 있는 사항이고요. 대신에 강의를 나가는 것은 근무시간 내에 강의를 나가게 되면 연차를 쓰는 범위 내에서만 나가게 돼 있습니다. 그리고 근무 외 시간에 나가는 것은 특별한 통제를 하지 않습니다. 
</p>
<p><b>○ 박재순 위원 </b> 강의시간하고 강연하고 이렇게 두 가지로 구분되는 거죠? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 네. 
</p>
<p><b>○ 박재순 위원 </b> 그래서 연구원을 보면 사실은 관련업무와 무관한 외부의 특강과 출강은 엄격히 배제되어야 한다고 보고 또 관련성 유무는 어떻게 판단하고 처리하고 계시냐고 묻고 싶은데요. 거기에 대해서 또 추가로 말씀드릴 수 있는 게 있으면 말씀해 주시기 바랍니다. 특강에 관해서 또 출강에 관해서 더 저에게 하고 싶은 얘기 있으면 해주시기 바랍니다. 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 보통 그것이 연구윤리와 관련해서 위원님이 질의하시는 거라고 판단이 듭니다만 저희 연구원의 박사님들 같은 경우에 대부분 외부에 발제를 하러 나가거나 강연을 하러 나가거나 이와 같은 활동을 하는 것은 대부분 전문영역에서 그와 같은 일을 하고 있다고 확신하고 있고요. 그리고 출강 같은 경우는 가급적이면 근무시간 이후에 하도록 박사님들 스스로 그렇게 생각하고 있다고 봅니다. 그런데 다만 초빙연구원 같은 분들은 사실 이곳에서 정규직 박사가 아니기 때문에 앞으로의 여러 가지 개인적인 활로나 이런 것들을 더 고려해야 되기 때문에 시간강사나 이런 형식으로 또는 초빙교수나 이런 걸로 활동을 하는 것을 사실 권장까지는 아니라도 그것을 막을 수 없다고 생각합니다. 다만 우리 내부규정이 있기 때문에 연차를 쓰는 범위 내에서, 업무에 지장이 없는 범위 내에서 하도록 그렇게 관리해 왔고 앞으로도 그런 식으로 관리를 해나가야 한다고 생각합니다. 
</p>
<p><b>○ 박재순 위원 </b> 현재 그런 가이드라인이 잘 지켜지고 있다고 생각하시는 거죠? 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 일전에도 감사를 통해서 그런 것이 지적받은 사항도 있기 때문에 지금은 특별히 그런 상황이 없는 것으로 알고 있습니다. 
</p>
<p><b>○ 박재순 위원 </b> 이때 나가서, 분명히 업무와 관련성이 있는 부분에 대해서는 충분하게 저희들도 인식을 하고 있습니다. 사실 우리 경기개발연구원의 위상이나 경기도의 발전 위상에 대해서 그런 역할들을 그분들이 충분히 할 거라고 보고 있고 그러기 때문에 강의를 나가는 것도 권장 또는 묵인하에서 또 장려하는 차원에서도 가능하다고 봅니다. 다만 그 요지에 있어서 강의료, 그 강의료가 어떻게 쓰여지고 있는지, 아니면 그 강의료가 우리 연구원에 들어오는 건지, 아니면 개인적으로 그냥 가져가는 건지 거기에 대해서 좀 묻고 싶습니다. 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 제가 알기로는 강의료는 예를 들어서 한 학기 강의를 하면 한 200만 원 정도의 수익이 있는 것으로 제가 자료를 보았습니다만 그것은 자기 개인의 수익으로 그렇게 잡힙니다. 
</p>
<p><b>○ 박재순 위원 </b> 그러니까 연구원들이 결국은 경기도의 발전을 위해서 연구하는 것도 있겠지만 개인적으로 나가서 수입을 잡기 위한 그런 역할들도 하는데 어쨌든 소속되어 있는 것 아닙니까? 우리 경기도 연구원에. 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 물론입니다. 
</p>
<p><b>○ 박재순 위원 </b> 그렇죠? 그래서 여기에 보면 출장지급에 대해서는 전부 다 “무”예요. 그런데 한 분을 보니까 3만 원으로 되어 있어요, 2회에 걸쳐서 3만 원. 이게 분명히 잘못된 것 같은데 이 연구자료에 이게 어떻게 된 건지에 대해 좀 묻고 싶고 또 이 돈이, 분명하게 제가 말씀드리고 싶은 건 우리 연구원에서 직장인으로 친다면 직장에 소속 되어서 개인이 어떤 일을 했었을 때 그 부분에 대해서 시간이 비었다 한다 하더라도 그것은 반듯하게 인센티브제도나 이런 제도를 이용해서 그런 제도를 줬어야 된다고 저는 생각을 하는데 원장님은 어떻게 생각하십니까, 그 부분에 대해서.
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 그러니까 말하자면 외부강연이나 이런 것을 나갔는데 출장비가 지급됐다면 그건 잘못 지급된 거로 봐야 되고요. 그리고 강의를 하게 될 때도 강의를 나가지 않아도 사용하는 연차휴가를 대신해서 쓰기 때문에 그 기간에 강의를 하고 벌어들인 수익은 사실은 연구원에 귀속될 수는 없다고 생각이 듭니다. 
</p>
<p><b>○ 박재순 위원 </b> 본 위원하고 생각이 좀 틀리다고 생각하고 있거든요. 분명한 것은 본인이 우리 연구원에 소속돼 있기 때문에 밖에 나가서 연구비를 받은 거 그 부분이 우리 연구원에 들어와야 된다고 저는 생각을 하고 있습니다. 그리고 수당에 대해서 우리 연구원에서 그 수당 인센티브제도에 관한 그런 퍼센티지를 계산해서 그렇게 만들어 줘야 이분들도 편하게 가서 연구를 하고 이러는 건데 또 발표도 하고 강의도 하고 이러는 건데 지금과 같은 이런 제도를 하면 사실은 근무시간에 강의준비도 해야 되고 그러다 보면 우리 경기도의 발전을 위한 일보다는 주보다는 부가 더 많이 신경을 써서 일한다는 그런 취지로 저는 말씀을 드린 거예요. 
</p>
<p style="padding-left:1.2em">  그래서 이 부분에 대해서 분명한 것은 시정이 있어야 되지 않을까 본 위원은 이 부분에 대해서 말씀을 드리고 있고 원장님은 어떻게 생각하시는지 잘 모르겠습니다. 우리 연구원 되시는 분들에게도 제가 분명하게 말씀드리겠지만 연구를 함에 있어서 연봉이 1억에 가까운 돈을 받습니다. 물론 연구실적에 맞게끔 충분하게 주고 있습니다. 여기 보수액 규정에 보면 기본연봉 플러스 성과연봉 그다음에 연봉 외 급여. 그러나 어느 직장이고 다 가서 보면 직장업무의 연장선상으로 봤었을 때 그 부분에 대해서는 추가 일하는 것으로 해서 나가야 된다고 본 위원은 생각하는데 그 부분에 대해서 서로가 조금 다른 생각을 갖고 있기 때문에 이 부분의 시정을 요청하는 겁니다. 이 부분에 대해서 한 말씀 해 주시죠.
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 일단 위원님 생각에도 일리가 있다고 보기 때문에 검토는 해 보겠습니다만 저희들이 가지고 있는 생각은 사실 우리가 기본연구라는 걸 합니다. 그 기본연구는 당장 경기도에 즉각 정책으로 반영되지는 않지만 특정한 전공분야의 깊이 있는 연구를 하게끔 권장합니다, 2년에 한 건 정도는 하라고. 그런데 그렇게 하는 이유는 연구원은 연구의 특성상 그때그때 정책과제를 하는 것 이외에 그런 깊이 있는 연구를 해야만 역량이 쌓이고 또 실력이 쌓이기 때문에 그런 제도를 두고 있는 것이고 또 6∼7년에 한 번 정도씩 연구년을 두는 이유도 연구역량을 쌓으라고, 새로운 트렌드도 공부도 하고 이러라고 두는 것입니다. 그런 차원에서 보면 아까 위원님 말씀하신 것처럼 어디 가서 강의를 하려면 자기 전공분야라 하더라도 사실 준비를 해야 됩니다. 그런데 그 준비하는 과정도 또한 상당한 연구를 수반하고 있기 때문에 저희들은 그것도 연구원의 역량 배가에 플러스요인이 있다고 생각하는 겁니다. 그렇기 때문에 저희들이 강의를 하는 것이 근무시간 이외에 하는 강의를 권장하고 있고 근무시간 내에서 하면 연차휴가 범위 내에서 하라고 그런 제도를 둔 것입니다. 그래서 그런 관점에서 보면 저는 그것이 연구역량의 손실이라거나 우리들의 마이너스라고는 보지 않습니다. 
</p>
<p style="padding-left:1.2em">  다만 그렇게 해서 벌어들인 수익에 대해서는 좀 연구원으로 환원하고 일정한 규정에 의해서 다시 인센티브 형식으로 하자는 말씀에 대해서는 나름 일리가 있기 때문에 한번 검토를 해 보도록 하겠습니다. 
</p>
<p><b>○ 박재순 위원 </b> 충분하게 검토의 여지가 있다고 저는 생각을 합니다. 그리고 우리 연구원들도 거기에 대해서 한 번쯤은 생각해볼 필요성이 있다고 저는 생각을 합니다. 왜 그러냐 하면 분명한 것은 경기개발연구원의 소속이기 때문입니다. 다른 소속이 아니었다면 또 다른 직장이 아니었다면 그런 얘기를 하지 않겠죠. 그러나 모든 직장은 다 업무의 연관성으로 보고 있다고 저는 생각하고 있고요. 그 부분이 충분하게 검토되어서 이렇게 잘 활용되었으면 좋겠다는 말씀을 드리겠습니다. 
</p>
<p style="padding-left:1.2em">  그리고 항공마일리지 아까 오전에 말씀드렸던 그 부분에 대해서 보니까 이게 볼펜으로 적어 갖고 왔어요. 분명하게 감사에서 아마 지적이 되었던 그런 부분들인데 아직도 이게 완벽하게 잘 되지를 않은 것 같아요. 그래서 이런 부분들이 앞으로 더 완벽하게 잘 정리되기를 기대를 하고요. 
</p>
<p style="padding-left:1.2em">  그다음에 설문응답 조사하면서 상품권 수불관계가 있습니다. 상품권을 줬던 모양이죠. 그것도 경기도 종합감사에서 지적사항으로 나왔었는데 그 부분 알고 있나요?
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 지금 파악하고 있습니다. 
</p>
<p><b>○ 박재순 위원 </b> 있습니다. 감사지적사항에서도 설문응답 시 답례용으로 상품권을 줬어요. 그런데 수불관계가 명확하지 않아서 정리가 되지 않았었는데 지금은 잘하고 있는지 그것에 대해서 알면 얘기해 주시기 바랍니다.
</p>
<p><b>○ 재정지원부장 박인숙 </b> 제가 답변하겠습니다. 재정지원부장 박인숙입니다. 감사지적사항 이후에 수불대장이라고 저희가 만들었습니다. 상품권을 살 경우 어느 분한테 몇 장, 어느 분한테 한 장 누구누구 해서 그걸 꼭 제출하도록 돼 있습니다. 
</p>
<p><b>○ 박재순 위원 </b> 그 부분도 자료를 오늘과 같이 잘 해주시고요. 마일리지에 관해서 지금 볼펜으로 써 갖고 온 게 확실하게 되어 있지 않아서 써 갖고 온 거죠? 
</p>
<p><b>○ 재정지원부장 박인숙 </b> 그게 프린트가 잘못됐거나 그랬을 경우 그랬을 겁니다. 
</p>
<p><b>○ 박재순 위원 </b> 프린트가 잘못 됐으면 여기에 분명히 흔적이 남아있을 겁니다. 그런데 제가 봤을 때는 이게 기재가 안 돼 있었어요. 그래서 지적사항임에도 불구하고 아직도 태만하게 관리가 되지 않았나 본 위원은 생각하기 때문에 다시 한 번 말씀드리겠습니다. 
</p>
<p><b>○ 재정지원부장 박인숙 </b> 그것은 시정하겠습니다. 
</p>
<p><b>○ 박재순 위원 </b> 아까 수불관계하고 이 부분 앞으로도 더 지적사항이 나오지 않도록 신경을 써주시기를 부탁을 드리면서, 들어가셔도 좋습니다. 연구원은 분명한 것은 그겁니다. 우리 도민의 혈세로써 운영되고 있고 또 연구결과에 대한 자료나 도민들에게 충분하게 연구자료로써 또는 편리로써 제공이 돼야 된다고 생각합니다. 그래서 앞으로도 우리 경기개발연구원의 싱크탱크의 역할을 하기 위해서는 우리 원장님 이하 여기 계시는 우리 박사님들께서 경기도의 책임자십니다. 사실 우리 도의원들도 있고 도지사님도 있지만 가장 중요한 것은 헤드입니다, 헤드. 헤드가 썩어있으면 모든 조직은 다 썩어있다고 보는 거고 그 조직이 살았을 때 또 연구의 가치가 우리 실무공무원이나 우리 조직에 접목되어서 또 우리 경제인들에게 접목되어서 활용의 가치가 높아졌을 때 어떤 최대효과가 난다고 저는 생각을 하고 있습니다. 그래서 우리 원장님 힘드시고 어렵지만 앞으로 남은 임기동안 최선을 다해 주실 것을 부탁드리면서 오늘도 긴 시간동안 함께 해주신 우리 연구원장님에게 깊은 감사의 말씀드리겠습니다. 이상입니다. 감사합니다. 
</p>
<p><b>○ 위원장 배수문 </b> 박재순 위원님 수고하셨습니다. 장동일 위원님 질의하여 주시기 바랍니다. 
</p>
<p><b>○ 장동일 위원 </b> 원장님, 잠깐 자리에 계시고요. 장윤배 실장님께 제가 좀. 
</p>
<p><b>○ 공감도시연구실장 장윤배 </b> 장윤배입니다.
</p>
<p><b>○ 장동일 위원 </b> 민선6기 핵심연구사업으로 제가 쭉 이렇게 보면서 몇 가지는 아까 원장님께 질의를 드렸고 맞춤형 주거복지가 여섯 번째 들어가 있어요. 보니까 주거환경개선과 도심활성화를 위한 종합적인 도시재생전략 수립 이런 게 과제로 나와 있습니다. 그런데 연구실장님께서는 도시공학을 하시고 이런 쪽에 전문가시죠? 
</p>
<p><b>○ 공감도시연구실장 장윤배 </b> 네. 
</p>
<p><b>○ 장동일 위원 </b> 그런데 도심활성화, 도시재생 관련해서 시군에서 연구의뢰 같은 게 들어옵니까?
</p>
<p><b>○ 공감도시연구실장 장윤배 </b> 도시재생 관련해서는 평택시에서 연구의뢰가 한 번 있어서 수행한 바가 있습니다. 
</p>
<p><b>○ 장동일 위원 </b> 신도시가 생기고 그러다 보니까 구도심이 슬럼화되고 범죄가 발생되다 보니까, 깨진 유리창 이론이죠. 이렇게 되다 보니까 이게 필요를 느끼고 있는데 어떻게 해야 된다고 봅니까? 제가 이렇게 경기도 일원을 돌아다니다 보면 난개발로 인해서 도시가 도시 같지도 않고 특히 도농지역은 더 심합니다. 어떤 문제가 있느냐 하면 저는 그래서 저보다는 훨씬 그런 부분에 잘 아시겠지만 도시재생사업이 깨끗한 환경위주로 갔으면 좋겠다. 그러면 어떤 효과가 있냐고 하면 우선 정서적으로 안정이 되죠, 환경이 깨끗하면. 그리고 안전사고가 방지될 수가 있고. 또 범죄예방 이건 다 아는 내용이고요. 그다음에 우리가 가장 공동체사회 생활하는데 부족한 엠패티(empathy)라고 그러죠, 공감. 서로 간의 공감력이 키워진다는 거예요. 아주 중요한 부분입니다, 이게. 도시가 깨끗한 환경이 조성되면 여러 가지 이런 효과들이 있을 텐데 우리 실장님께서 앞으로 꼭 시군에서 의뢰가 안 들어오더라도 연구의 어떤 모티브를 확실히 잡아서 시군에 이런 것을 제공했으면 좋겠다는 생각을 하는데 본인이 가지고 계시는 재생에 대한, 환경에 대한, 도시환경재생사업에 대한 철학을 말씀해 주시죠.
</p>
<p><b>○ 공감도시연구실장 장윤배 </b> 철학까지는 아닐 것 같고요. 제가 생각하는 바를 잠깐 말씀드리면 일단은 과거의 대규모 철거형 재개발 시대는 다 아시다시피 지났다고 볼 수 있겠고요. 지금은 주민 스스로 공동체를 만드는 마을 만들기 방식이 지금 계속 가고 있는데 한계가 좀 있습니다. 한계라는 게 아무래도 자본이라든지 그런 부분이 부족하기 때문에 그런 부분을 끌어올 수 있는 부분이 필요한데 그런 부분을 공공에서 도나 국가에서 지원할 수 있다면 그 둘이 만나서 어떤 큰 시너지효과를 발휘할 수 있다고 봅니다. 그래서 저희가 이번에 생각을 했던 부분은 주거복지지구라고 한번 생각을 해 봤는데요. 기존의 기반시설 위주로 공공에서는 지원을 하고 있습니다. 거기 더하기 못하고 있는 부분이 주택문제, 주택개보수라든지 개선하는 부분이 부족하기 때문에 그런 부분을 주거복지지구로 지정해서 2개를 같이 융합을 시킨다면 굉장한 시너지효과가 있을 것이다라고 생각을 합니다. 그래서 그것과 더불어서 공동체까지 같이 결합을 가지고 있는 따복공동체와 연계를 시킨다면 앞으로 경기도에서, 우리나라에서, 다른 데서는 하지 못한 최초의 모델이 되지 않을까 생각을 합니다. 
</p>
<p style="padding-left:1.2em">  그래서 그런 아이디어를 이번에는 올해 연말하고 내년 포함해서 제안을 드리고 행정부 쪽이나 위원님께도 한번 설명을 드리면서 지원을 해 주셨으면 저희도 연구를 통해서 그런 쪽으로 한번 추진하려고 노력을 하고 있습니다. 저는 그렇게 생각하고 있습니다. 
</p>
<p><b>○ 장동일 위원 </b> 뭔가 너무 특색이 없잖아요, 우리가. 시군에 이렇게 보면. 앞으로 지금 이번에 요우커들이 많이 와서 돈도 많이 쓰고 갔다고 하는데 특색이 없다는 거죠. 가장 중요한 여기 지역경제를 활성화시키고 일자리창출하고 관광이 굉장히 중요한 화두인데 가장 중요한 제반여건을 만들어 내지 못한다는 거예요. 특색이 없습니다. 저도 경기도 어디 가보면 한번 가면 ‘야, 여기 뭐…….’ 그렇게 되거든요. 그런 것들을 뭔가 특색 있는 부분으로 유인하고 그런 것들이 개발이 돼야 되지 않겠나 그런 생각을 합니다. 이게 어떻게 보면 하드웨어지만 이것이 안으로 깊이 소프트웨어까지 저는 침투할 것이라고 보기 때문에 그런 부분에 대해서, 특히 도시부분에 대해서 전문가시니까 획기적인 연구를 한번 보도록 하겠습니다. 그런 좋은 제안이 들어오면 제가 적극적으로 지원을 하도록 하겠습니다. 
</p>
<p><b>○ 공감도시연구실장 장윤배 </b> 저희도 지역마다 매력 있는 도시를 만들어야지 외국인들 포함해서 방문을 할 수 있고 그래야지 지역이 활성화가 되는데 사실 우리 경기도에 있는 도시들이 그러한 뚜렷한 매력을 가지고 있는 도시들이 별로 없습니다. 그래서 매력을 찾기 위한 연구 그런 것도 저희가 한번 적극적으로 해 보겠습니다. 
</p>
<p><b>○ 장동일 위원 </b> 시범적으로라도 한두 군데를 해서 아무튼 그런 방안을 한번 찾아주셨으면 좋겠다. 
</p>
<p><b>○ 공감도시연구실장 장윤배 </b> 알겠습니다. 노력하겠습니다. 
</p>
<p><b>○ 장동일 위원 </b> 수고하셨습니다. 이상입니다.
</p>
<p><b>○ 공감도시연구실장 장윤배 </b> 고맙습니다.
</p>
<p><b>○ 위원장 배수문 </b> 장동일 위원님 수고하셨습니다. 이어서 임병택 위원님 질의하여 주시기 바랍니다. 
</p>
<p><b>○ 임병택 위원 </b> 장시간 수고 많으십니다. 임해규 원장님 개인에 대한 말씀을 제가 드리자면 제가 들은 평은 맨 처음 원장후보로 거론되시고 청문회 하시고 하는 과정 중에서 경기개발연구원이 다시 한 번 자리잡고 모든 연구원들이 조직에 대한 자존감도 높아지고 사명감을 가지고 일할 거라는 그런 기대가 아주 컸던 걸로 저는 그렇게 듣고 또 알고 있습니다. 그러나 몇몇 일탈행위를 하는 연구원님들 때문에 전체가 먹지 않아도 될 비판까지도 받게 되는 이런 상황인데요. 이 점은 원장님께서 충분히 이해하시리라고 전 생각을 합니다. 그래서 제가 오전 질문에도 말씀드렸지만 그런 절차들을 잘 이행하셔서 우리 종합감사 전까지는 꼭 보고를 해주시기를 그렇게 당부드리겠습니다. 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 네.
</p>
<p><b>○ 임병택 위원 </b> 그리고 한 말씀 더 덧붙이자면 따뜻하고 복된 공동체라는 이 정책방향, 저는 우리들이 지향해야 될 가치라고 저도 전적으로 동의를 합니다. 동의를 하는데 제가 겪고 있는 실화 한 가지만 말씀을 드릴게요. 저희 지역은 뉴타운으로 두 곳이 지정이 되어 있었습니다. 우리 원장님의 지역구도 아마 뉴타운 관련 갈등이 컸던 것으로 제가 알고 있습니다. 그런데 최근에 시에서 마을 만들기 선진지 견학을 가자라고 버스에 주민들을 모았단 말이에요. 제가 직접 들은 이야기인데요. 당시에 뉴타운에 찬성했던 사람들과 반대했던 사람들이 패가 나뉘더라는 거예요. 밥 먹을 때도 따로 먹고 돌 때도 따로 돌고 “저네들은 우리 뉴타운 할 때 찬성했던 놈들 아니야.” 이런 극단적인 말까지도 하면서 이 갈등의 골이 너무나 깊다는 겁니다. 저는 그게 너무 안타깝죠, 직접 그런 이야기를 전해 주시기 때문에. 저는 그분들 우리 뉴타운이라는 잘못된 정책으로 인해서 더 갈등이 심화됐던 이런 뉴타운 해제지역, 추진 중인 지역, 이런 곳에 저는 따뜻하고 복된 공동체 복원사업이 먼저 이루어져야 되지 않냐, 왜냐하면 우리가 먼저 그렇게 만들어갔던 측면이 있기 때문에 저는 그런 생각을 가지고 있습니다. 어떻게 생각하시는지요. 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 저도 동의합니다. 그래서 조금 아까 주거복지지구 지정 이야기했는데요. 뉴타운 해제지역 같은 경우는 아무래도 구도심들이고 주거환경개선이 굉장히 필요로 하는 곳이기 때문에 단순히 소프트웨어 차원에서 마을공동체를 만드는 사업에다가 인프라를 구축하는, 주거환경개선을 하는 국비와 도비와 이런 것들을 합쳐서 함께 들어가 줘야 전망을 만들어낼 수 있다고 보고 최근에 시군에서도 그와 같은 쪽으로 관심이 많고 그래서 그런 뉴타운과 관련돼서 지역의 기금들을 그런 쪽으로 사용하고자 생각하는 시군단체장들도 계시기 때문에 우선 그런 곳을 시범적으로 내년도에 사업을 우선적으로 추진하면 좋겠다, 이렇게 생각하고 있습니다. 
</p>
<p><b>○ 임병택 위원 </b> 뉴타운 할 때도 우리 경기개발연구원에서 많은 자료들, 연구활동, 토론회, 세미나를 했습니다. 뉴타운이 취소된 이후에도 그런 역할은 계속 사후관리 차원에서 저는 당연히 해야 될 책무가 있다고 봅니다. 그래서 이제 내년도 연구계획을 보니까 그런 부분이 조금 미진하지 않느냐라는 제 생각이 들어서 다시 한 번 당부드립니다. 
</p>
<p style="padding-left:1.2em">  한 말씀만 더 드리면 기사에 나온 작년 말에 국내 유력 민간연구소에서 한국사회의 사회갈등지수를 조사해서 발표를 했더라고요, 사회갈등지수. OECD국가 중에 저희가 2등을 했습니다, 터키 다음으로. 가장 갈등이 많은 나라다. 그런데 이 갈등지수가 현 상태에서 10%만 낮아지더라도 1인당 GDP가 2%에서 5.5%까지 1인당 GDP가 올라가고요. 평균 국가수준이 갈등지수가 내려간다 하더라도 7에서 30 이상 GDP 성장이 가능하다라는 그런 보고가 있더라고요. 그러면서 이런저런 대안들을 내놓은 기사를 보게 됐습니다. 저는 우리 한국사회의 뉴타운을 포함한 갈등을 극복하는 정책적 대안을 내는 경기개발연구원, 따뜻하고 복된 공동체와 함께 더불어서 선도적인 역할을 17개 광역시도 중에서 경기도가 나서서 경기도가 하면 서울이 따라올 거예요. 충청도도 따라오고요. 전 그런 사명감을 가지고 해주시기를 당부드리면서 질의를 마치도록 하겠습니다. 
</p>
<p><b>○ 경기개발연구원장 임해규 </b> 네, 그렇게 하겠습니다. 
</p>
<p><b>○ 위원장 배수문 </b> 임병택 위원님 수고하셨습니다. 또 질의하실 위원님 거수해 주시기 바랍니다. 
</p>
<p style="padding-left:2.4em">    (「없습니다.」하는 위원 있음)
</p>
<p style="padding-left:1.2em">  더 이상 질의하실 위원님이 안 계십니까? 
</p>
<p style="padding-left:2.4em">    (「없습니다.」하는 위원 있음)
</p>
<p style="padding-left:1.2em">  더 이상 질의하실 위원님이 안 계시므로 오늘 경기개발연구원 소관업무에 대한 질의와 답변을 모두 마치겠습니다. 
</p>
<p style="padding-left:1.2em">  위원 여러분 그리고 임해규 경기개발연구원장을 비롯한 임직원 여러분! 장시간 열의를 갖고 행정사무감사에 임해 주신 위원 여러분과 행정사무감사를 위한 자료준비 및 위원님들의 질의에 성의껏 답변해 주신 경기개발연구원장을 비롯한 임직원 여러분들께 감사드립니다. 20일 날 총괄 행감이 더 예정돼 있습니다. 오늘 자료요청된 것 중 미진한 것들이 있다면 조속한 시일 내에 자료요청을 원하시는 위원님들께 제출하여  주시기를 부탁을 드립니다.
</p>
<p style="padding-left:1.2em">  그러면 이상으로 경기개발연구원 소관에 대한 2014년도 행정사무감사를 마치겠습니다. 산회를 선포합니다.
</p>
<p class=''ar''>(17시12분 감사종료)
</p>
<p><hr /></p>
<p><b>○ 출석감사위원(11명)
</b></p>
<p class=''aMan''>배수문임병택최지용김호겸나득수박재순안혜영이재준이현호임두순</p>
<p class=''aMan''>장동일</p>
<p><b>○ 출석전문위원
</b></p>
<p class=''em15''>   수석전문위원 오태철
</p>
<p><b>○ 피감사기관참석자
</b></p>
<p><p class=''em15''>경기개발연구원장 임해규부원장 이상훈기획조정본부장 이양주</p>
<p><p class=''em15''>연구기획실장 유영성공존사회연구실장 박충훈공감도시연구실장 장윤배</p>
